/// Static empty HashMap used by rejection responses to avoid allocating a new
/// HashMap on every error path. ~20+ rejection sites in the proxy handler pass
/// `&HashMap::new()` — this eliminates those per-rejection allocations.
static EMPTY_HEADERS: std::sync::LazyLock<HashMap<String, String>> =
    std::sync::LazyLock::new(HashMap::new);

/// Hyper's HTTP/1 parser panics when `max_buf_size` is below 8 KiB. Ferrum's
/// configured logical header limit may be lower; keep the parser floor safe
/// and enforce the operator's lower limit in `check_protocol_headers`.
const HYPER_HTTP1_MIN_MAX_BUF_SIZE: usize = 8 * 1024;

#[inline]
fn http1_parser_max_buf_size(configured_header_limit: usize) -> usize {
    configured_header_limit.max(HYPER_HTTP1_MIN_MAX_BUF_SIZE)
}

/// Metadata key set on the request context for the duration of
/// `apply_after_proxy_hooks_to_rejection`. Plugins that wire
/// `applies_after_proxy_on_reject() -> true` can read this key from
/// `ctx.metadata` to tell apart "after_proxy invoked on a plugin rejection"
/// (response_headers are plugin-supplied) from the normal "after_proxy
/// invoked on a backend response" path (response_headers came from upstream).
pub(crate) const REJECTION_RESPONSE_METADATA_KEY: &str = "ferrum:rejection_response";

/// Companion marker set only while an uncommitted rejection body may still be
/// replaced by an opted-in `after_proxy` hook. The ordinary rejection replay
/// path sets [`REJECTION_RESPONSE_METADATA_KEY`] without this marker, so a
/// fail-closed plugin can distinguish a replacement that will reach the client
/// from a reject result that proxy core must ignore.
pub(crate) const REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY: &str =
    "ferrum:replaceable_rejection_response";

/// One-shot handoff for requester-owned auth session state that changed before
/// authentication attempts rejected. Distinct cookie storage keys are
/// newline-joined; a later attempt replaces an earlier candidate with the same
/// exact name/domain/host-only/path/partitioned scope. The authentication phase
/// removes this key on every exit: it attaches the cookies only to the final
/// rejection and discards them when a later credential succeeds. The key
/// contains "cookie" so metadata serialization still redacts the sealed values
/// defensively.
pub(crate) const AUTH_REJECTION_SET_COOKIE_METADATA_KEY: &str = "auth.rejection_set_cookie";

/// Marker recorded in `ctx.metadata` for the duration of
/// [`apply_synthetic_response_body_hooks`] — i.e. while the response-body hook
/// pipeline (`on_response_body`, `transform_response_body_with_context`,
/// `on_final_response_body`) runs over a governed synthetic plugin short-circuit
/// body rather than a real backend response. This includes final 2xx-5xx
/// terminate-mode serverless responses. Unlike
/// [`REJECTION_RESPONSE_METADATA_KEY`] (scoped to the `after_proxy` reject hooks
/// only), this marker stays set across the body-hook phase so that a storing
/// plugin's `on_final_response_body` can tell apart "this body was produced by a
/// later `before_proxy`/backend-admission short-circuit" from a genuine backend
/// response. `request_deduplication` reads this to avoid caching+replaying a
/// synthetic short-circuit body (e.g. a `fault_injection`/`mesh_route_dispatch`
/// 2xx abort) under the idempotency key — mirroring `response_caching`'s
/// served-from-cache guard and `ai_semantic_cache`'s miss-only buffering key.
/// Only ever set on the synthetic short-circuit path, so its presence is a
/// precise signal; the normal buffered backend-response path never sets it.
pub(crate) const SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY: &str = "ferrum:synthetic_short_circuit";

/// Body-independent lifecycle signal set once a plugin short-circuit has been
/// finalized as a successful synthetic response (final HTTP 2xx), including
/// empty 200 and 204/205 shapes that intentionally skip the synthetic
/// response-body hook pipeline. Unlike
/// [`SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY`] (scoped to the body-hook phase only),
/// this marker remains visible through `on_response_committed` so ownership
/// plugins such as `request_deduplication` can release token-matched local and
/// Redis in-flight markers after empty/no-body synthetic successes. Non-2xx
/// plugin rejects and downstream rejection replacements do **not** set this
/// marker — those keep in-flight ownership until `inflight_ttl` by design.
pub(crate) const FINALIZED_SYNTHETIC_RESPONSE_METADATA_KEY: &str =
    "ferrum:finalized_synthetic_response";

/// One-shot request-method override used only while synthetic response-body
/// hooks inspect a plugin-generated representation. `spec_expose` sets `GET`
/// for canonical HEAD responses so response guards evaluate the representation
/// exactly as they do for GET; the real method is restored before rejection
/// `after_proxy` hooks normalize the final wire response.
pub(crate) const SYNTHETIC_RESPONSE_METHOD_OVERRIDE_METADATA_KEY: &str =
    "ferrum:synthetic_response_method_override";

/// Internal marker carried only on a response-decision context clone while an
/// effective retry policy is active. It never reaches transaction metadata.
const RETRY_RESPONSE_BUFFERING_METADATA_KEY: &str = "ferrum:retry_response_buffering";

/// Marker recorded in `ctx.metadata` when the ORIGINAL backend response was a
/// range/partial response (`206` or carrying `Content-Range`), captured before
/// any `after_proxy` hook can mutate the response headers. A plugin whose
/// `after_proxy` runs after a header-rewriting plugin (e.g. `compression` at
/// order 4050 after `response_transformer` at 4000) can read this to preserve
/// the original range decision even if an earlier hook stripped/renamed
/// `Content-Range`. This matters because range responses are streamed (see
/// `compression`'s `should_buffer_response_body_for_content_type`), so a plugin
/// must not commit a body transform header (e.g. `Content-Encoding`) that its
/// buffered-only `transform_response_body` will never actually apply.
pub(crate) const RANGE_RESPONSE_METADATA_KEY: &str = "ferrum:range_response";

/// Marker recorded in `ctx.metadata` when the ORIGINAL backend response was a
/// **fragment** of the selected representation — a range slice or a delta —
/// captured before any `after_proxy` hook can mutate status or headers.
///
/// Kept separate from [`RANGE_RESPONSE_METADATA_KEY`] rather than folded into
/// it: that marker feeds `compression`'s streaming/`Content-Encoding` decision
/// and is deliberately header-presence-based, so narrowing or widening it would
/// change compression behavior as a side effect. This marker is the shared
/// representation gate's own evidence, and it applies the *semantic* rule from
/// [`original_response_is_fragment`], so an `after_proxy` hook that removed
/// `Content-Range`/`IM` or rewrote the status cannot hide a real fragment, and
/// a complete non-2xx status document carrying stale range/delta metadata is
/// not mistaken for one.
pub(crate) const ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY: &str = "ferrum:origin_fragment_response";

/// Whether a response's status and headers are evidence that its body is a
/// fragment of the selected representation rather than a complete one.
///
/// This is the single fragment rule, shared by both provenances of the
/// representation gate — a backend response applies it once to its pristine
/// pre-`after_proxy` snapshot (stamped as
/// [`ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY`]), gateway-generated bytes apply it
/// to their live headers. Same semantics, different evidence source.
///
/// * `206`/`226` are fragments by definition (RFC 9110 §15.3.7, RFC 3229 §10.4.1).
/// * Any other **2xx** carrying `Content-Range` or `IM` is treated as one too:
///   that is exactly the shape a fragment whose status was rewritten would take,
///   and over-detecting here only rejects, which is the safe direction.
/// * A **non-2xx** is not, anywhere in the category. A `1xx` carries no content
///   (RFC 9110 §15.2); a `3xx` body describes the redirection and a `4xx`/`5xx`
///   body describes the error condition (§15.4, §15.5, §15.6) — status-specific
///   content, not a delivered range or delta of the selected representation.
///   That holds for `416` specifically: its `Content-Range: bytes */<len>`
///   reports the selected representation's length rather than describing this
///   response's content (§15.5.17), so the body is a complete, fully inspectable
///   status document. On any other non-2xx the header is stale metadata with no
///   defined meaning — and it is precisely what
///   [`crate::plugins::invalidate_content_bound_response_headers`] strips after a
///   permitted rewrite. Treating it as fragment evidence would fail closed on
///   ordinary `416`/`429`/`503` replies while protecting nothing.
pub(crate) fn original_response_is_fragment(
    response_status: u16,
    response_headers: &HashMap<String, String>,
) -> bool {
    if matches!(response_status, 206 | 226) {
        return true;
    }
    (200..300).contains(&response_status)
        && (response_headers.contains_key("content-range") || response_headers.contains_key("im"))
}

/// Marker recorded in `ctx.metadata` when the ORIGINAL backend response carried
/// `Cache-Control: no-transform`, captured before any `after_proxy` hook can
/// mutate response headers. Compression reads this to preserve the backend's
/// no-transform directive even if an earlier response header transformer removes
/// or renames `Cache-Control` before compression's own `after_proxy` hook.
pub(crate) const NO_TRANSFORM_RESPONSE_METADATA_KEY: &str = "ferrum:no_transform_response";

/// Marker recorded in `ctx.metadata` when the ORIGINAL backend response carried
/// a strong `ETag`, captured before any `after_proxy` hook can mutate response
/// headers. Compression reads this to avoid returning transformed bytes with
/// the origin's strong validator.
pub(crate) const STRONG_ETAG_RESPONSE_METADATA_KEY: &str = "ferrum:strong_etag_response";

/// Marker proving that the original backend response metadata below was
/// captured before any `after_proxy` hook mutated its headers.
pub(crate) const ORIGINAL_RESPONSE_METADATA_STAMPED_KEY: &str =
    "ferrum:original_response_metadata_stamped";

/// The original backend response `Content-Type`, captured before any
/// `after_proxy` hook could rewrite it.
///
/// The representation gate decides which body policy claims a response from the
/// media type, and it runs after `after_proxy`. A header rule that removes or
/// relabels a framed gRPC response's `Content-Type` would otherwise push it onto
/// the untyped/JSON branch, where a JSON body policy claims its length-prefixed
/// frames, fails to parse them as a bare document, and replaces a valid RPC
/// reply with a `502`. Reading the media type from this snapshot — the same
/// discipline already applied to encoding and range/delta state — is what keeps
/// that relabel from changing which policy claims the bytes.
pub(crate) const ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY: &str =
    "ferrum:original_response_content_type";

/// Parsed `Content-Length` for the buffered representation a body transform will
/// be handed. Stamped from the original backend response, because a later gateway
/// plugin (notably `compression`) can remove the wire header before the
/// buffered-body phase.
///
/// Refreshed — not left pristine — by
/// [`crate::plugins::response_representation::install_decoded_response_body`]
/// when the representation gate decodes a protected body. The stamp answers "how
/// many bytes will the transform see?", and after a decode the encoded wire
/// length (or, for a chunked upstream, the ABSENCE of one) is no longer that
/// answer. Leaving it stale made `mcp_gateway`'s size precheck reject a decoded,
/// bounded, fully inspectable JSON body and skip MCP reverse mapping.
pub(crate) const ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY: &str =
    "ferrum:original_response_content_length";

/// Exact non-identity `Content-Encoding` from the original backend response.
/// This distinguishes origin encoding from an encoding selected later by the
/// gateway compression plugin and preserves the decoder input if a response
/// header transform subsequently removes or renames the live header.
pub(crate) const ORIGIN_ENCODED_RESPONSE_METADATA_KEY: &str = "ferrum:origin_encoded_response";

/// The ORIGINAL backend HTTP status, captured at the start of
/// `run_after_proxy_hooks` before any `after_proxy` hook can reject the response
/// and replace it with a rejection. Plugins whose `after_proxy` runs at a higher
/// priority than a rejecting hook (so their own genuine pass is skipped) read
/// this to recover the real backend status during the subsequent
/// `apply_after_proxy_hooks_to_rejection` re-run. `ai_rate_limiter` uses it to
/// keep a token reservation charged when the backend served 2xx but a later
/// after_proxy plugin (e.g. `response_size_limiting`) rejected the body — the
/// provider call already consumed tokens, so the reservation must not be
/// released as though it were a gateway rejection.
pub(crate) const BACKEND_STATUS_METADATA_KEY: &str = "ai_ratelimit_backend_status";

/// The token estimate `ai_rate_limiter` reserved for this request in its
/// `before_proxy` pass. Set only when a body-derived pre-reservation was taken
/// (non-zero estimate). `run_after_proxy_hooks` reads this to decide whether to
/// record `BACKEND_STATUS_METADATA_KEY`, and the plugin reads it back during
/// reconciliation. Shared here (rather than as a private copy in the plugin) so
/// the proxy-side writer/reader and the plugin-side writer/reader cannot drift.
pub(crate) const RESERVED_TOKENS_METADATA_KEY: &str = "ai_ratelimit_reserved_tokens";

/// Marker set by `ai_rate_limiter::before_proxy` whenever it identified the
/// request as an AI call (a parseable JSON request body it ran the token
/// estimate over), regardless of whether a non-zero reservation was taken —
/// `count_mode: "completion_tokens"` legitimately reserves 0 for AI requests
/// with no output cap. The plugin gates its `on_unmetered_response` policy on
/// this marker so a non-AI 2xx (GET, empty-body 200/204, non-JSON, etc.) on a
/// shared proxy is never rejected/charged by that policy. Distinct from
/// `RESERVED_TOKENS_METADATA_KEY` (which is absent for 0-reservation AI calls).
pub(crate) const AI_REQUEST_METADATA_KEY: &str = "ai_ratelimit_request";

/// Transient marker set while running `after_proxy` hooks when a later hook may
/// add `Cache-Control: no-transform`. Compression reads this before committing
/// `Content-Encoding`, then `run_after_proxy_hooks` clears it before returning.
pub(crate) const LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY: &str =
    "ferrum:later_no_transform_response";

/// Transient marker set while running `after_proxy` hooks when a later hook may
/// add a strong `ETag`. Compression reads this before committing
/// `Content-Encoding`, then `run_after_proxy_hooks` clears it before returning.
pub(crate) const LATER_STRONG_ETAG_RESPONSE_METADATA_KEY: &str =
    "ferrum:later_strong_etag_response";

/// Marker recorded in `ctx.metadata` when the ORIGINAL client request carried
/// `Cache-Control: no-transform`, captured before any `before_proxy` hook can
/// mutate request headers. Compression reads this to preserve the client's
/// no-transform directive even if an earlier request header transformer removes
/// or renames `Cache-Control` before compression's own `before_proxy` hook.
pub(crate) const NO_TRANSFORM_REQUEST_METADATA_KEY: &str = "ferrum:no_transform_request";

/// Marker recorded in `ctx.metadata` when the ORIGINAL client request declared a
/// non-identity `Content-Encoding`, captured before any `before_proxy` hook can
/// mutate request headers. `serverless_function` reads this so a header-only
/// `request_transformer` (priority 3000) that removes or renames
/// `Content-Encoding` before the serverless egress (priority 3025) cannot smuggle
/// the original compressed body past the fail-closed encoded-body boundary — the
/// buffered `ctx.request_body_bytes` are the original client bytes, so their
/// content coding is described by the original request headers, not the
/// transformed map the plugin receives.
pub(crate) const ORIGIN_ENCODED_REQUEST_METADATA_KEY: &str = "ferrum:origin_encoded_request";

/// Marker recorded in `ctx.metadata` when a `request_transformer` query rule
/// actually mutated `ctx.query_params` (add/remove/update/rename). Query
/// transformations operate on the decoded parameter map, which cannot be
/// reconciled with `serverless_function`'s raw-query payload without losing the
/// raw plus/duplicate/decode/auth-strip invariants the raw path exists to
/// preserve, so the serverless egress fails closed on the composition rather than
/// emitting a payload that silently ignores the operator's query transform.
pub(crate) const QUERY_PARAMS_TRANSFORMED_METADATA_KEY: &str = "ferrum:query_params_transformed";

/// True when a `Content-Encoding` field-line declares a coding other than
/// `identity`. Whitespace-only and empty values are treated as encoded
/// (fail-closed): a present-but-empty encoding is malformed and cannot be proven
/// to describe identity-coded bytes.
pub(crate) fn content_encoding_declares_non_identity(value: &str) -> bool {
    !value.trim().eq_ignore_ascii_case("identity")
}

pub(crate) fn stamp_original_request_metadata(ctx: &mut RequestContext) {
    // Capture the client's original `Accept-Encoding` before any `before_proxy`
    // hook can rewrite it. `request_transformer` (priority 3000) can remove or
    // replace the header before `compression` (priority 4050) takes its own
    // snapshot, and `compression` then strips it from the backend request, so
    // neither the live header map nor compression's metadata still proves what
    // the client negotiated by the time the buffered representation gate asks.
    // An explicit `identity;q=0` erased here would let a protected encoded
    // response be decoded and served in a representation the client refused.
    //
    // Multiple field-lines are folded with `, ` exactly as the list-header
    // grammar defines, so a split `Accept-Encoding` cannot hide a member. The
    // raw map is authoritative and available here (`set_raw_headers` runs
    // immediately before this call); the materialized map is the fallback for
    // paths that already consumed the raw headers.
    //
    // A present-but-EMPTY field value is recorded as such rather than collapsed
    // onto "absent": RFC 9110 §12.5.3 gives them different meanings (an empty
    // field admits only `identity`, an absent one places no constraint), so the
    // snapshot must preserve the distinction even though both currently accept
    // identity.
    let original_accept_encoding = {
        let raw: Vec<&str> = ctx.raw_header_values("accept-encoding").collect();
        if raw.is_empty() {
            ctx.headers.get("accept-encoding").cloned()
        } else {
            Some(raw.join(", "))
        }
    };
    if let Some(original_accept_encoding) = original_accept_encoding {
        ctx.set_original_accept_encoding(original_accept_encoding);
    }

    let raw_has_no_transform = ctx
        .raw_header_values("cache-control")
        .any(|value| cache_control_has_directive(value, "no-transform"));
    if raw_has_no_transform || headers_have_cache_control_directive(&ctx.headers, "no-transform") {
        ctx.metadata.insert(
            NO_TRANSFORM_REQUEST_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }

    // Capture the original non-identity content coding before any before_proxy
    // header transform can drop it. Check raw field-lines first (the pristine
    // wire header, available here because `set_raw_headers` runs immediately
    // before this) and fall back to the materialized map for paths that already
    // consumed the raw headers.
    let raw_declares_encoding = ctx
        .raw_header_values("content-encoding")
        .any(content_encoding_declares_non_identity);
    let materialized_declares_encoding = ctx
        .headers
        .get("content-encoding")
        .map(String::as_str)
        .is_some_and(content_encoding_declares_non_identity);
    if raw_declares_encoding || materialized_declares_encoding {
        ctx.metadata.insert(
            ORIGIN_ENCODED_REQUEST_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }
}

pub(crate) fn stamp_original_response_metadata(
    ctx: &mut RequestContext,
    response_status: u16,
    response_headers: &HashMap<String, String>,
) {
    ctx.metadata.insert(
        ORIGINAL_RESPONSE_METADATA_STAMPED_KEY.to_string(),
        "true".to_string(),
    );
    ctx.metadata
        .remove(ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY);
    if let Some(content_type) = response_headers.get("content-type") {
        ctx.metadata.insert(
            ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY.to_string(),
            content_type.clone(),
        );
    }
    ctx.metadata
        .remove(ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY);
    if let Some(content_length) = response_headers
        .get("content-length")
        .and_then(|value| value.parse::<usize>().ok())
    {
        ctx.metadata.insert(
            ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY.to_string(),
            content_length.to_string(),
        );
    }
    ctx.metadata.remove(ORIGIN_ENCODED_RESPONSE_METADATA_KEY);
    // A field that is not a list of pure `identity` tokens is stamped, so the
    // representation gate can judge it. That deliberately includes a MALFORMED
    // list (`,`, `identity,`): an empty token cannot be proven to describe
    // identity-coded bytes, and skipping the stamp would let a protected
    // response be inspected as though it carried no coding at all. Pure
    // `identity` stays unstamped, so no consumer of this key sees an
    // unencoded response as encoded.
    if let Some(encoding) = response_headers.get("content-encoding").filter(|encoding| {
        crate::plugins::response_representation::content_encoding_requires_decode_judgment(
            encoding.as_str(),
        )
    }) {
        ctx.metadata.insert(
            ORIGIN_ENCODED_RESPONSE_METADATA_KEY.to_string(),
            encoding.clone(),
        );
    }
    ctx.metadata.remove(RANGE_RESPONSE_METADATA_KEY);
    if response_status == 206 || response_headers.contains_key("content-range") {
        ctx.metadata
            .insert(RANGE_RESPONSE_METADATA_KEY.to_string(), "true".to_string());
    }
    ctx.metadata.remove(ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY);
    if original_response_is_fragment(response_status, response_headers) {
        ctx.metadata.insert(
            ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }
    if headers_have_cache_control_directive(response_headers, "no-transform") {
        ctx.metadata.insert(
            NO_TRANSFORM_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }
    if headers_have_strong_etag(response_headers) {
        ctx.metadata.insert(
            STRONG_ETAG_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }
}

/// Discard the pre-`after_proxy` backend snapshot once the buffered bytes are no
/// longer the backend's.
///
/// The inverse of [`stamp_original_response_metadata`], and the reason the
/// representation gate's provenance rules hold across the *whole* body phase
/// rather than only inside the gate itself.
///
/// Every key cleared here describes the response an `on_response_body` hook has
/// already REPLACED. The gate's own reads are provenance-switched
/// (`origin_content_encoding`, `is_partial_representation` both branch on
/// [`RepresentationOrigin`]), but the claim predicates it consults are not: a
/// plugin's `enforces_response_body_policy` receives only `&RequestContext`, the
/// live `Content-Type`, and the bytes, so it cannot tell a backend snapshot from
/// a stale one. `response_transformer::framed_grpc_request_without_proven_media_type`
/// reads [`ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY`] exactly that way: left
/// in place, a backend that answered `application/grpc+json` would make the
/// claim predicate decline a gateway-generated JSON rejection that has replaced
/// it, and the gate would then admit encoded, partial, or unparseable
/// replacement bytes as `Unprotected` while the transform still ran over the
/// live body. Clearing the stamp is what makes claim and gate agree on which
/// response they are describing.
///
/// The same staleness applies to every downstream reader of the snapshot, and
/// clearing is the right answer for all of them: `mcp_gateway`'s buffered
/// transform already falls back to the live headers when
/// [`ORIGINAL_RESPONSE_METADATA_STAMPED_KEY`] is absent, which is precisely the
/// correct description of gateway-authored bytes.
///
/// [`BACKEND_STATUS_METADATA_KEY`] is deliberately NOT cleared: it
/// records the backend's genuine status for `ai_rate_limiter`'s reservation
/// accounting, which is a fact about the upstream exchange rather than a
/// description of the bytes now being published.
///
/// [`RepresentationOrigin`]: crate::plugins::response_representation::RepresentationOrigin
fn clear_replaced_backend_response_snapshot(ctx: &mut RequestContext) {
    ctx.metadata.remove(ORIGINAL_RESPONSE_METADATA_STAMPED_KEY);
    ctx.metadata
        .remove(ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY);
    ctx.metadata
        .remove(ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY);
    ctx.metadata.remove(ORIGIN_ENCODED_RESPONSE_METADATA_KEY);
    ctx.metadata.remove(ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY);
}

fn record_node_waypoint_identity_drop(
    overload: &crate::overload::OverloadState,
    error: &NodeWaypointIdentityError,
) {
    let reason = match error {
        NodeWaypointIdentityError::SocketCookieUnavailable(_) => {
            crate::overload::NodeWaypointDropReason::CookieUnavailable
        }
        NodeWaypointIdentityError::UnknownCookie(_) => {
            crate::overload::NodeWaypointDropReason::UnknownCookie
        }
        NodeWaypointIdentityError::MissingPodUid(_) => {
            crate::overload::NodeWaypointDropReason::MissingPodUid
        }
        NodeWaypointIdentityError::MissingWorkloadHash { .. } => {
            crate::overload::NodeWaypointDropReason::MissingWorkloadHash
        }
        NodeWaypointIdentityError::UnknownPod(_) => {
            crate::overload::NodeWaypointDropReason::UnknownPod
        }
        NodeWaypointIdentityError::WorkloadHashMismatch { .. } => {
            crate::overload::NodeWaypointDropReason::HashMismatch
        }
        NodeWaypointIdentityError::PodUidMismatch { .. } => {
            crate::overload::NodeWaypointDropReason::HashMismatch
        }
    };
    overload.record_node_waypoint_drop(reason);
}

fn node_waypoint_listener_uid_fallback_allowed(error: &NodeWaypointIdentityError) -> bool {
    matches!(
        error,
        NodeWaypointIdentityError::SocketCookieUnavailable(_)
            | NodeWaypointIdentityError::UnknownCookie(_)
    )
}

/// Validate that every `mesh_route_dispatch` rule's
/// `destination.upstream_id` points at a real upstream in the config.
///
/// Treated as a rejecting validator (same bucket as
/// `validate_upstream_references` for `Proxy.upstream_id`): a typo in a
/// rule's upstream_id is observationally equivalent to a typo on
/// `Proxy.upstream_id` — `apply_route_overrides_with_upstreams` still
/// bakes the missing id into the request proxy, `select_upstream_target`
/// returns no target, and HTTP/H2/H3 dispatch falls back to the proxy's
/// default `backend_host:backend_port`. That silent fallback can route
/// matched traffic to the wrong backend instead of failing config
/// validation, so the contract here matches normal Proxy upstream-id
/// validation: refuse the config, log every dangling reference once.
///
/// `GatewayConfig` is already namespace-scoped by its loader/distributor
/// before this runtime validator runs. A missing id here can therefore mean
/// "does not exist" or "exists only in another namespace"; admin admission
/// performs the broader DB lookup and emits the more specific cross-namespace
/// error before the config reaches this path.
pub(crate) fn validate_mesh_route_dispatch_upstream_references(
    config: &GatewayConfig,
) -> Result<(), Vec<String>> {
    let upstream_ids: HashSet<&str> = config.upstreams.iter().map(|u| u.id.as_str()).collect();
    let mut errors = Vec::new();

    for plugin in &config.plugin_configs {
        if !plugin.enabled || plugin.plugin_name != "mesh_route_dispatch" {
            continue;
        }
        let Ok(dispatch_config) = MeshRouteDispatchConfig::from_value(&plugin.config) else {
            continue;
        };
        for (rule_idx, rule) in dispatch_config.rules.iter().enumerate() {
            if let Some(upstream_id) = rule.destination.upstream_id.as_deref()
                && !upstream_ids.contains(upstream_id)
            {
                let proxy_id = plugin.proxy_id.as_deref().unwrap_or("<none>");
                errors.push(format!(
                    "PluginConfig '{}' (mesh_route_dispatch) rule {} for proxy_id '{}' references upstream_id '{}' that is not present in the active GatewayConfig namespace",
                    plugin.id, rule_idx, proxy_id, upstream_id
                ));
            }
        }
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

/// Capability probes run during startup and background refresh, so they should
/// not inherit long per-request connect timeouts that could hold readiness.
const BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP: u64 = 5_000;

// Frontend HTTP/2 flow-control defaults. Conservative for untrusted clients;
// operators can override via FERRUM_FRONTEND_H2_* env vars for benchmarking
// or trusted-network deployments.
pub(crate) const FRONTEND_H2_INITIAL_STREAM_WINDOW_SIZE: u32 = 256 * 1024; // 256 KiB
pub(crate) const FRONTEND_H2_INITIAL_CONNECTION_WINDOW_SIZE: u32 = 2 * 1024 * 1024; // 2 MiB
pub(crate) const FRONTEND_H2_MAX_FRAME_SIZE: u32 = 16_384; // 16 KiB (RFC 9113 default)
const GATEWAY_WORKLOAD_METRICS_PLUGIN_ID: &str = "__gateway_workload_metrics";
const WORKLOAD_METRICS_PLUGIN_NAME: &str = "workload_metrics";
const HBONE_INNER_IDENTITY_BAGGAGE_PREFIXES: &[&str] = &[
    "source.",
    "source_",
    "src.",
    "src_",
    "destination.",
    "destination_",
    "dst.",
    "dst_",
];

/// Partial outcome of a single H3 capability probe. `probe_h2_tls` writes
/// directly into `record` (it owns `&mut record`), but `probe_h3` runs in
/// parallel via `tokio::join!` so it can't simultaneously alias that borrow.
/// Instead it returns this struct; `apply()` merges the result into the
/// shared record + error list when the join completes.
struct H3ProbeOutcome {
    h3: ProtocolSupport,
    error: Option<String>,
}

struct H2TlsProbeTarget<'a> {
    probe_proxy: &'a Proxy,
    probe_timeout: Duration,
    host: &'a str,
    port: u16,
    previous_h2_tls: Option<ProtocolSupport>,
    previous_grpc_h2_tls: Option<ProtocolSupport>,
    previous_h1: Option<ProtocolSupport>,
}

struct HboneProbeTarget<'a> {
    host: &'a str,
    dial_host: &'a str,
    port: u16,
    policy_port: u16,
    hbone_port: u16,
    /// Pinned destination identity for the probe handshake (mirrors dispatch).
    expected_peer: Option<&'a crate::identity::SpiffeId>,
    previous_hbone: Option<ProtocolSupport>,
    /// `true` for a UDP egress target: probe with a `udp`-marked datagram-over-
    /// HBONE CONNECT (the marker the dispatch datapath uses) instead of the
    /// `hbone` byte-stream marker, so the probe reaches the destination's `udp`
    /// relay rather than its byte-stream relay (codex r1 P1).
    is_udp: bool,
}

fn gateway_managed_plugin_timestamp() -> chrono::DateTime<chrono::Utc> {
    chrono::DateTime::from_timestamp(0, 0).unwrap_or_else(chrono::Utc::now)
}

fn gateway_svid_spiffe_id(slot: &SharedSvidBundle) -> Option<String> {
    let snapshot = slot.load_full();
    snapshot
        .as_ref()
        .as_ref()
        .map(|bundle| bundle.spiffe_id.as_str().to_string())
}

fn ensure_workload_spiffe_id_config(config: &mut serde_json::Value, spiffe_id: &str) {
    if !config.is_object() {
        *config = serde_json::json!({});
    }
    let Some(object) = config.as_object_mut() else {
        return;
    };
    if object
        .get("workload_spiffe_id")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|value| !value.trim().is_empty())
    {
        return;
    }
    object.insert(
        "workload_spiffe_id".to_string(),
        serde_json::Value::String(spiffe_id.to_string()),
    );
}

fn inject_gateway_workload_metrics_if_svid(
    config: &mut GatewayConfig,
    gateway_svid: &SharedSvidBundle,
    namespace: &str,
) {
    let Some(spiffe_id) = gateway_svid_spiffe_id(gateway_svid) else {
        return;
    };

    let operator_idx = config
        .plugin_configs
        .iter()
        .position(|plugin| {
            plugin.id != GATEWAY_WORKLOAD_METRICS_PLUGIN_ID
                && plugin.enabled
                && plugin.scope == PluginScope::Global
                && plugin.plugin_name == WORKLOAD_METRICS_PLUGIN_NAME
                && plugin.namespace == namespace
        })
        .or_else(|| {
            config.plugin_configs.iter().position(|plugin| {
                plugin.id != GATEWAY_WORKLOAD_METRICS_PLUGIN_ID
                    && plugin.scope == PluginScope::Global
                    && plugin.plugin_name == WORKLOAD_METRICS_PLUGIN_NAME
                    && plugin.namespace == namespace
            })
        });

    if let Some(operator_idx) = operator_idx {
        ensure_workload_spiffe_id_config(
            &mut config.plugin_configs[operator_idx].config,
            &spiffe_id,
        );
        config
            .plugin_configs
            .retain(|plugin| plugin.id != GATEWAY_WORKLOAD_METRICS_PLUGIN_ID);
        return;
    }

    if let Some(existing) = config
        .plugin_configs
        .iter_mut()
        .find(|plugin| plugin.id == GATEWAY_WORKLOAD_METRICS_PLUGIN_ID)
    {
        existing.plugin_name = WORKLOAD_METRICS_PLUGIN_NAME.to_string();
        existing.namespace = namespace.to_string();
        existing.scope = PluginScope::Global;
        existing.proxy_id = None;
        existing.enabled = true;
        existing.priority_override = None;
        existing.api_spec_id = None;
        existing.config = serde_json::json!({
            "workload_spiffe_id": spiffe_id,
        });
        return;
    }

    let timestamp = gateway_managed_plugin_timestamp();
    config.plugin_configs.push(PluginConfig {
        id: GATEWAY_WORKLOAD_METRICS_PLUGIN_ID.to_string(),
        plugin_name: WORKLOAD_METRICS_PLUGIN_NAME.to_string(),
        namespace: namespace.to_string(),
        config: serde_json::json!({
            "workload_spiffe_id": spiffe_id,
        }),
        scope: PluginScope::Global,
        proxy_id: None,
        enabled: true,
        priority_override: None,
        api_spec_id: None,
        created_at: timestamp,
        updated_at: timestamp,
    });
}

fn config_empty_ignoring_gateway_managed_plugins(config: &GatewayConfig) -> bool {
    config.proxies.is_empty()
        && config.consumers.is_empty()
        && config.upstreams.is_empty()
        && config
            .plugin_configs
            .iter()
            .all(|plugin| plugin.id == GATEWAY_WORKLOAD_METRICS_PLUGIN_ID)
}

fn gateway_hbone_mtls_observed(
    dispatch_mesh_transport: bool,
    error_class: Option<retry::ErrorClass>,
) -> bool {
    dispatch_mesh_transport
        && !matches!(
            error_class,
            Some(
                retry::ErrorClass::ConnectionTimeout
                    | retry::ErrorClass::ConnectionRefused
                    | retry::ErrorClass::ConnectionReset
                    | retry::ErrorClass::ConnectionClosed
                    | retry::ErrorClass::DnsLookupError
                    | retry::ErrorClass::TlsError
                    | retry::ErrorClass::ConnectionPoolError
                    | retry::ErrorClass::PortExhaustion
                    | retry::ErrorClass::ProtocolError
                    | retry::ErrorClass::DispatchPolicyRejected
                    | retry::ErrorClass::RequestError
                    | retry::ErrorClass::RequestBodyTooLarge
            )
        )
}

/// Stamp mesh transport metadata for an outbound mesh-mTLS-secured dispatch.
/// `transport` is `Some("hbone")` for Ambient HBONE and `Some("mtls")` for
/// Sidecar SVID-mTLS; `None` (non-mesh dispatch) stamps nothing.
fn annotate_gateway_mesh_metadata(
    ctx: &mut RequestContext,
    target: Option<&UpstreamTarget>,
    transport: Option<&'static str>,
    error_class: Option<retry::ErrorClass>,
) {
    let Some(transport) = transport else {
        return;
    };
    if !gateway_hbone_mtls_observed(true, error_class) {
        return;
    }

    ctx.metadata.insert(
        "mesh.connection_security_policy".to_string(),
        "mutual_tls".to_string(),
    );
    ctx.metadata
        .insert("mesh.gateway.transport".to_string(), transport.to_string());

    let Some(target) = target else {
        return;
    };
    for (tag, metadata_key) in [
        ("mesh.spiffe_id", "mesh.destination.principal"),
        ("mesh.namespace", "mesh.destination.namespace"),
        ("mesh.service", "mesh.destination.service"),
        ("mesh.trust_domain", "mesh.destination.trust_domain"),
    ] {
        if let Some(value) = target.tags.get(tag) {
            ctx.metadata.insert(metadata_key.to_string(), value.clone());
        }
    }
}

fn hbone_inner_baggage_strip_prefixes(configured_prefixes: &[String]) -> Vec<String> {
    let mut prefixes = configured_prefixes.to_vec();
    for prefix in HBONE_INNER_IDENTITY_BAGGAGE_PREFIXES {
        if !prefixes.iter().any(|existing| existing == prefix) {
            prefixes.push((*prefix).to_string());
        }
    }
    prefixes
}

fn hbone_inner_headers_with_stripped_baggage(
    headers: &HashMap<String, String>,
    configured_prefixes: &[String],
) -> Option<HashMap<String, String>> {
    if !crate::modes::mesh::hbone::has_baggage_header_in_map(headers) {
        return None;
    }

    let mut owned = headers.clone();
    let prefixes = hbone_inner_baggage_strip_prefixes(configured_prefixes);
    crate::modes::mesh::hbone::strip_egress_baggage_in_map(&mut owned, &prefixes);
    Some(owned)
}

impl H3ProbeOutcome {
    fn apply(self, record: &mut BackendCapabilityRecord, errors: &mut Vec<String>) {
        // `probe_h3` returns the fully merged classification (including a
        // timeout-preserved prior Unsupported/Supported, or Unknown when there
        // was no prior record). Always write it: the refresh path builds a
        // fresh default record, so skipping Unknown would be fine there, but
        // skipping a preserved non-Unknown value would wipe the prior state.
        // Writing Unknown is also intentional when the merge decided that.
        record.plain_http.h3 = self.h3;
        if let Some(err) = self.error {
            errors.push(err);
        }
    }
}

/// Append a probe-error message into `record.last_probe_error` without
/// stomping an existing error. Used by `probe_h2_tls` which borrows the
/// record mutably (can't also borrow the outer `errors` vec) — the outer
/// caller recombines any `last_probe_error` set here with its own `errors`
/// list.
fn append_probe_error(record: &mut BackendCapabilityRecord, msg: String) {
    match record.last_probe_error.as_mut() {
        Some(existing) => {
            existing.push_str("; ");
            existing.push_str(&msg);
        }
        None => {
            record.last_probe_error = Some(msg);
        }
    }
}

fn warn_capability_supported_regression(
    target: &BackendCapabilityProbeTarget,
    previous: &BackendCapabilityRecord,
    current: &BackendCapabilityRecord,
) {
    let last_probe_error = current.last_probe_error.as_deref().unwrap_or("none");
    let warn_one = |protocol: &'static str, before: ProtocolSupport, after: ProtocolSupport| {
        if before == ProtocolSupport::Supported && after != ProtocolSupport::Supported {
            warn!(
                proxy_id = %target.proxy.id,
                backend_host = %target.host(),
                backend_port = target.port(),
                protocol,
                previous = ?before,
                current = ?after,
                last_probe_error,
                "Backend capability probe changed supported protocol to unavailable"
            );
        }
    };

    warn_one(
        "h2_tls",
        previous.plain_http.h2_tls,
        current.plain_http.h2_tls,
    );
    warn_one("h3", previous.plain_http.h3, current.plain_http.h3);
    warn_one(
        "h2c",
        previous.grpc_transport.h2c,
        current.grpc_transport.h2c,
    );
    warn_one("hbone", previous.hbone, current.hbone);
}

/// Boxed future type for pool warmup tasks.
/// Returns `Ok(description)` on success or `Err(message)` on failure.
type WarmupTask =
    std::pin::Pin<Box<dyn std::future::Future<Output = Result<String, String>> + Send>>;

/// One unique reqwest warmup target captured during candidate collection,
/// before the task future is built. Held as a separate struct so the HTTPS
/// gating phase can decide per-target whether to materialize the task at all
/// (skipping is much cheaper than building a task and dropping it unrun).
struct ReqwestWarmupCandidate {
    /// Representative proxy used to build the `reqwest::Client`. Multiple
    /// proxies sharing the same `(scheme, host, port)` collapse onto the
    /// first one collected — same as the original warmup behaviour.
    proxy: Proxy,
    host: String,
    port: u16,
    /// Scheme literal for URL formatting + log lines. `&'static str` instead
    /// of `String` because the only valid values are the two compile-time
    /// constants the dispatcher accepts ("http", "https").
    scheme: &'static str,
    /// `true` when at least one proxy routing to this `(scheme, host, port)`
    /// would dispatch via reqwest at runtime — the OR across every proxy
    /// merged into this candidate. The HTTPS gating phase must NOT skip
    /// reqwest warmup when this is true, even if the capability registry
    /// classifies the target as `h2_tls=Supported`: the direct H2 pool only
    /// covers traffic that satisfies all of `can_use_direct_http2_pool`'s
    /// guards (`enable_http2`, `!retain_request_body`,
    /// `!requires_request_body_buffering`), and any proxy that fails one
    /// of those guards still routes via reqwest.
    requires_reqwest_warmup: bool,
}

/// Lookup the capability registry for a specific (proxy, host, port) triple
/// and decide whether the direct HTTP/2 pool *could* handle this backend
/// (so the reqwest pool does not need a startup HEAD).
///
/// Returns `true` only when `plain_http.h2_tls` is definitively `Supported`.
/// `Unknown` (probe never ran or timed out) and `Unsupported` (post-ALPN
/// HTTP/1.1 fallback) both fall back to "warm reqwest" so the fallback pool
/// is always pre-warmed for any target the H2 pool cannot cover.
///
/// **NOT sufficient on its own to skip reqwest warmup.** The runtime
/// dispatch path also gates on `can_use_direct_http2_pool` (per-proxy
/// `enable_http2`, retain-request-body retries, request-body-buffering
/// plugins), so the warmup gating must also consult
/// `proxy_config_forces_reqwest_dispatch` for every proxy routing to the
/// target before deciding to skip. See `ReqwestWarmupCandidate.requires_reqwest_warmup`.
///
/// Constructed as a free function so the gating predicate is unit-testable
/// against a stand-alone `BackendCapabilityRegistry` without needing to
/// instantiate a full `ProxyState`.
fn target_uses_direct_h2_pool(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    host: &str,
    port: u16,
) -> bool {
    let target = UpstreamTarget {
        host: host.to_string(),
        port,
        service_port_policy_key: None,
        weight: 1,
        tags: HashMap::new(),
        locality: None,
        path: None,
    };
    registry
        .get(proxy, Some(&target))
        .map(|record| record.plain_http.h2_tls.is_supported())
        .unwrap_or(false)
}

/// Decide whether a proxy's *configuration* would force at least some
/// requests onto the reqwest dispatch path at runtime, regardless of
/// what the capability registry says about the backend.
///
/// Mirrors the runtime guard set in `can_use_direct_http2_pool` plus the
/// outer `dispatch_kind == HttpsPool` gate the dispatcher applies before
/// it. Returns `true` when ANY of the following are true — meaning at
/// least some traffic for this proxy will land on reqwest and the
/// warmup gating MUST keep reqwest warmed for this target:
///
/// - `proxy.dispatch_kind` is HTTP-not-HTTPS — the direct H2 pool is
///   never tried for plain-HTTP backends.
/// - `enable_http2 = false` — operator explicitly disabled backend HTTP/2
///   on this proxy (`pool_enable_http2: false`).
/// - `requires_request_body_buffering = true` — at least one of the
///   proxy's plugins needs to inspect/transform the request body, which
///   the direct H2 sender path doesn't implement (per
///   `can_use_direct_http2_pool`).
/// - `proxy.retry` is configured with non-zero `max_retries` AND can
///   actually retry something (connection-failure replay or a non-empty
///   pair of retryable methods + statuses). When retries are effective,
///   the request body is retained for replay and the direct H2 path is
///   skipped (`retain_request_body` ⇒ false from `can_use_direct_http2_pool`).
///
/// Caller pre-computes the `enable_http2` and
/// `requires_request_body_buffering` booleans from the
/// `ConnectionPool::global_pool_config().for_proxy(proxy)` and
/// `PluginCache::requires_request_body_buffering(&proxy.id)` accessors so
/// this predicate is a pure function over its inputs and trivially
/// unit-testable.
fn proxy_config_forces_reqwest_dispatch(
    proxy: &Proxy,
    enable_http2: bool,
    requires_request_body_buffering: bool,
) -> bool {
    if !matches!(proxy.backend_scheme, Some(BackendScheme::Https)) {
        return true;
    }
    if !enable_http2 {
        return true;
    }
    if requires_request_body_buffering {
        return true;
    }
    if let Some(retry) = proxy.retry.as_ref()
        && retry.max_retries > 0
        && (retry.retry_on_connect_failure
            || (!retry.retryable_status_codes.is_empty() && !retry.retryable_methods.is_empty()))
    {
        return true;
    }
    false
}

/// Collect reqwest warmup candidates for a single proxy, partitioning by
/// scheme so the caller can run HTTP-only candidates in parallel with the
/// capability refresh and apply capability-driven gating to HTTPS-only
/// candidates after the refresh completes.
///
/// HTTP candidates can warm in parallel with the refresh — they hit a
/// disjoint pool (reqwest plain HTTP) from the gRPC h2c probe. HTTPS
/// candidates must wait for the refresh so the gating phase can consult
/// the registry.
///
/// `pool_key` is the proxy's `ConnectionPool::pool_key_for_warmup(proxy)` —
/// the same identity the connection pool uses to keep distinct
/// `reqwest::Client`s. Including it in the dedup key (instead of just
/// `(scheme, host, port)`) ensures two proxies that share a backend
/// `host:port` BUT have different TLS configs (different CA bundle,
/// different mTLS cert, different DNS override, …) each get their own
/// warmup task — because they end up with separate `reqwest::Client`s
/// at runtime. Without TLS-aware dedup, only the first-collected
/// proxy's client gets warmed and the others pay a cold connect on
/// the first real request despite warmup being enabled.
///
/// `forces_reqwest` is the per-proxy verdict from
/// `proxy_config_forces_reqwest_dispatch` — `true` when the proxy's
/// configuration would route some traffic via reqwest at runtime. The
/// flag is OR-merged into any existing candidate sharing the same
/// dedup key: if proxy A on the target can use the direct H2 pool but
/// proxy B (same target, same TLS) requires reqwest, the merged
/// candidate's `requires_reqwest_warmup` stays `true` so the gating
/// phase keeps the warmup task. This is the regression guard against
/// the per-target dedup hiding a single proxy's reqwest dependency.
///
/// Maps (not sets) so the OR-merge can mutate the existing entry in
/// place. Order is irrelevant: the warmup batch runs concurrently and
/// log lines key off the per-target description, not insertion order.
///
/// Free function so it's callable from tests without constructing a full
/// `ProxyState`. Tests pass arbitrary `pool_key` strings to exercise the
/// dedup contract directly.
fn collect_reqwest_warmup_candidates_for_proxy(
    proxy: &Proxy,
    pool_key: &str,
    forces_reqwest: bool,
    upstream_map: &HashMap<&str, &crate::config::types::Upstream>,
    http_candidates: &mut HashMap<String, ReqwestWarmupCandidate>,
    https_candidates: &mut HashMap<String, ReqwestWarmupCandidate>,
) {
    let scheme: &'static str = match proxy.backend_scheme {
        Some(BackendScheme::Http) => "http",
        _ => "https",
    };

    let mut targets: Vec<(String, u16)> = Vec::new();
    if let Some(ref upstream_id) = proxy.upstream_id
        && let Some(upstream) = upstream_map.get(upstream_id.as_str())
    {
        for target in &upstream.targets {
            // Mesh-transport-tagged targets are NOT plaintext reqwest backends.
            // HBONE targets warm via their own capability probe; SVID-mTLS
            // targets dial a peer's mTLS listener — a plaintext reqwest HEAD to
            // the app port would fail (or, worse, dial the app outside the mesh
            // transport). Leave both to their transport-specific paths.
            if hbone_pool::target_hbone_enabled(target)
                || mesh_mtls_pool::target_mesh_mtls_enabled(target)
            {
                continue;
            }
            targets.push((target.host.clone(), target.port));
        }
    }
    // Fall back to the proxy's own backend only when it has one. A mesh egress
    // proxy carries `upstream_id` + an empty `backend_host`, so once its
    // mesh-tagged targets are filtered out above, `targets` is empty and there
    // is nothing to warm — do NOT synthesize a `:0` candidate from the empty
    // backend.
    if targets.is_empty() && !proxy.backend_host.is_empty() {
        targets.push((proxy.backend_host.clone(), proxy.backend_port));
    }

    let bucket = if scheme == "http" {
        http_candidates
    } else {
        https_candidates
    };

    for (host, port) in targets {
        // Dedup key composes the connection pool's TLS-aware client key
        // with the per-target host:port. Multiple targets in one upstream
        // share a pool key but get distinct dedup keys (each target
        // connection in reqwest's internal pool needs its own HEAD).
        // Multiple proxies sharing the same (host, port) but different
        // TLS configs have distinct pool keys → distinct dedup keys →
        // each `reqwest::Client` gets its own warmup task.
        let dedup_key = format!("{}|{}:{}", pool_key, host, port);
        bucket
            .entry(dedup_key)
            .and_modify(|existing| {
                // OR-merge: any proxy on this target that would use reqwest
                // at runtime keeps the warmup enabled.
                existing.requires_reqwest_warmup |= forces_reqwest;
            })
            .or_insert_with(|| ReqwestWarmupCandidate {
                proxy: proxy.clone(),
                host,
                port,
                scheme,
                requires_reqwest_warmup: forces_reqwest,
            });
    }
}

/// Run a batch of warmup tasks gated by a shared concurrency semaphore and
/// emit aggregate info-level success/failure counts. Used by both the
/// HTTP-only warmup phase (running in parallel with the capability refresh)
/// and the gated HTTPS warmup phase. `label` identifies the batch in log
/// lines so operators can tell the two phases apart.
///
/// The semaphore is the actual concurrency cap — `for_each_concurrent`'s
/// `buffer` argument is only the *polling-window* size. Phase-1 shares the
/// semaphore with the capability refresh so the combined fanout never
/// exceeds `pool_warmup_concurrency`. Without the shared semaphore, two
/// `tokio::join!`-ed batches each independently respecting that limit
/// would burst to ~2× (or more, since per-HTTPS-target probes also
/// `tokio::join!` H2 + H3 internally) — overloading backends and
/// triggering avoidable startup timeouts in large configs.
///
/// `polling_buffer` is the configured `pool_warmup_concurrency` cap, NOT
/// `semaphore.available_permits()`. The semaphore can be momentarily
/// drained by the parallel capability refresh at the moment this function
/// is entered, which would clamp the polling buffer to 1 and serialize
/// the rest of the batch even after the refresh releases its permits.
/// Sizing the buffer from the configured cap keeps the polling window
/// large enough to absorb permit churn.
async fn run_warmup_task_batch(
    tasks: Vec<WarmupTask>,
    semaphore: Arc<Semaphore>,
    polling_buffer: usize,
    label: &'static str,
) {
    use futures_util::stream;

    if tasks.is_empty() {
        debug!("Pool warmup ({}): no targets to warm", label);
        return;
    }

    let total = tasks.len();
    info!(
        "Pool warmup ({}): establishing {} backend connections (shared concurrency cap={})",
        label, total, polling_buffer
    );

    let ok = Arc::new(AtomicU64::new(0));
    let failed = Arc::new(AtomicU64::new(0));

    let buffer = polling_buffer.max(1);
    stream::iter(tasks)
        .for_each_concurrent(buffer, |task| {
            let ok = ok.clone();
            let failed = failed.clone();
            let semaphore = semaphore.clone();
            async move {
                // The semaphore is owned by `warmup_connection_pools` and
                // not closed during normal operation, but the codebase
                // rule (`No .unwrap()/.expect() in production`) prefers
                // explicit Err handling. Skip the task and count it as
                // failed if the semaphore ever does close — startup must
                // not panic.
                let _permit = match semaphore.acquire_owned().await {
                    Ok(permit) => permit,
                    Err(e) => {
                        warn!("Pool warmup: semaphore closed before acquire ({e}); skipping task");
                        failed.fetch_add(1, Ordering::Relaxed);
                        return;
                    }
                };
                match task.await {
                    Ok(desc) => {
                        debug!("Pool warmup: {} ok", desc);
                        ok.fetch_add(1, Ordering::Relaxed);
                    }
                    Err(msg) => {
                        warn!("Pool warmup failed: {}", msg);
                        failed.fetch_add(1, Ordering::Relaxed);
                    }
                }
            }
        })
        .await;

    let ok_count = ok.load(Ordering::Relaxed);
    let failed_count = failed.load(Ordering::Relaxed);
    if failed_count > 0 {
        info!(
            "Pool warmup complete ({}): {} ok, {} failed out of {} targets",
            label,
            ok_count,
            failed_count,
            ok_count + failed_count
        );
    } else {
        info!(
            "Pool warmup complete ({}): all {} targets ok",
            label, ok_count
        );
    }
}

/// Shared response-body buffering decision used across the H1/H2, H3, and
/// cross-protocol paths so `response_body_mode` and per-request plugin
/// refinements stay in sync.
pub(crate) fn should_stream_response_body(
    proxy: &Proxy,
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    maybe_requires_response_body_buffering: bool,
) -> bool {
    // Before #2505, translated gRPC-Web responses were always buffered, so
    // response_transformer header rules saw the merged initial-header +
    // trailer compatibility view. Streaming ordinary gRPC-Web must not turn
    // that existing terminal-metadata policy into a bypass. Keep only those
    // explicitly policy-bearing configurations on the compatible buffered
    // path; a plain grpc_web instance remains fully streaming.
    if crate::plugins::grpc_web::request_is_grpc_web_translated(ctx)
        && plugins
            .iter()
            .any(|plugin| plugin.requires_buffered_grpc_web_trailer_policy(ctx))
    {
        return false;
    }
    match proxy.response_body_mode {
        ResponseBodyMode::Buffer => false,
        ResponseBodyMode::Stream => {
            if maybe_requires_response_body_buffering {
                !plugins
                    .iter()
                    .any(|plugin| plugin.should_buffer_response_body(ctx))
            } else {
                true
            }
        }
    }
}

pub(crate) fn retry_response_decision_context(ctx: &RequestContext) -> RequestContext {
    let mut retry_ctx = ctx.clone();
    retry_ctx.metadata.insert(
        RETRY_RESPONSE_BUFFERING_METADATA_KEY.to_string(),
        "true".to_string(),
    );
    retry_ctx
}

pub(crate) fn plugins_may_release_response_body_under_retries(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
) -> bool {
    plugins.iter().any(|plugin| {
        plugin.should_buffer_response_body(ctx)
            && plugin.may_release_response_body_under_retries(ctx)
    })
}

#[derive(Debug, Default)]
struct LaterHeaderSimulation {
    cache_control_no_transform: bool,
    strong_etag: bool,
}

fn simulate_later_after_proxy_headers(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    response_headers: &HashMap<String, String>,
) -> LaterHeaderSimulation {
    let mut exact_builtin_may_add_no_transform = false;
    let mut exact_builtin_may_add_strong_etag = false;
    for plugin in plugins {
        if !is_builtin_plugin_name(plugin.name()) {
            return LaterHeaderSimulation {
                cache_control_no_transform: true,
                strong_etag: true,
            };
        }
        exact_builtin_may_add_no_transform |=
            plugin.may_add_response_cache_control_no_transform(ctx, response_headers);
        exact_builtin_may_add_strong_etag |=
            plugin.may_add_response_strong_etag(ctx, response_headers);
    }
    if !exact_builtin_may_add_no_transform && !exact_builtin_may_add_strong_etag {
        return LaterHeaderSimulation::default();
    }

    let mut simulated_ctx = ctx.clone();
    let mut simulated_headers = response_headers.clone();
    for plugin in plugins {
        plugin.simulate_after_proxy_response_headers(&mut simulated_ctx, &mut simulated_headers);
    }
    LaterHeaderSimulation {
        cache_control_no_transform: headers_have_cache_control_directive(
            &simulated_headers,
            "no-transform",
        ),
        strong_etag: headers_have_strong_etag(&simulated_headers),
    }
}

/// Refine the pre-flight `stream_response` decision once the backend response
/// headers — including representation metadata such as `Content-Type` and
/// `Content-Encoding` — are known.
///
/// [`should_stream_response_body`] runs before the backend request is sent, so
/// it cannot consult the response headers and conservatively buffers whenever
/// any plugin *might* need the body. This downgrades buffer -> stream when no
/// plugin actually needs to inspect the body for THIS representation
/// (e.g. `waf` with `response_body_inspection` skips non-allowlisted/binary
/// bodies), avoiding a full-body collection that would be discarded unscanned.
///
/// Only ever downgrades (buffer -> stream); it never forces buffering, so a
/// plugin that needs the body (caching/compression/transform, or `waf` for an
/// allowlisted content-type) is never affected. An explicit
/// [`ResponseBodyMode::Buffer`] is always honored, and a `None` context leaves
/// the pre-flight decision unchanged. Retry-enabled callers pass a marked
/// context clone: ordinary responses stay buffered, while every active
/// buffering plugin must explicitly opt an inherently streaming response out
/// after headers arrive.
///
/// If any plugin can mutate the response `Content-Type` in a later
/// `after_proxy` hook, the helper keeps the original buffered decision. That
/// preserves response-body inspection for the final client-visible headers
/// rather than trusting a backend header value that may be relabeled before
/// `on_final_response_body` runs.
pub(crate) fn refine_stream_response_for_content_type(
    stream_response: bool,
    proxy: &Proxy,
    plugins: &[Arc<dyn Plugin>],
    ctx: Option<&RequestContext>,
    response_status: u16,
    response_headers: &HashMap<String, String>,
) -> bool {
    if stream_response {
        return true;
    }
    // Operator explicitly forced buffering for every response — honor it.
    if !matches!(proxy.response_body_mode, ResponseBodyMode::Stream) {
        return false;
    }
    let Some(ctx) = ctx else {
        return false;
    };
    let content_type = response_headers.get("content-type").map(String::as_str);
    let mut saw_active_buffering_plugin = false;
    let mut simulated_ctx = ctx.clone();
    stamp_original_response_metadata(&mut simulated_ctx, response_status, response_headers);
    let mut simulated_response_headers = response_headers.clone();
    if simulated_ctx
        .metadata
        .contains_key(RETRY_RESPONSE_BUFFERING_METADATA_KEY)
    {
        if plugins
            .iter()
            .any(|plugin| plugin.may_modify_response_content_type(ctx, content_type))
        {
            return false;
        }
        let mut saw_retry_release_plugin = false;
        let all_active_plugins_release = plugins.iter().all(|plugin| {
            if !plugin.should_buffer_response_body(&simulated_ctx) {
                true
            } else if plugin.may_release_response_body_under_retries(&simulated_ctx) {
                saw_retry_release_plugin = true;
                plugin.should_release_response_body_under_retries(
                    &simulated_ctx,
                    response_status,
                    response_headers,
                )
            } else {
                !plugin.should_buffer_response_body_for_content_type(
                    &simulated_ctx,
                    content_type,
                    response_status,
                    response_headers,
                )
            }
        });
        return saw_retry_release_plugin && all_active_plugins_release;
    }
    let all_active_plugins_can_release_before_content_type_rewrite =
        plugins.iter().enumerate().all(|(index, plugin)| {
            let can_release = if plugin.should_buffer_response_body(&simulated_ctx) {
                saw_active_buffering_plugin = true;
                let later_headers = simulate_later_after_proxy_headers(
                    &plugins[index + 1..],
                    &simulated_ctx,
                    &simulated_response_headers,
                );
                plugin.should_release_response_body_before_content_type_rewrite(
                    &simulated_ctx,
                    response_status,
                    &simulated_response_headers,
                ) || (later_headers.cache_control_no_transform
                    && plugin.should_release_response_body_for_later_no_transform(
                        &simulated_ctx,
                        response_status,
                        &simulated_response_headers,
                    ))
                    || (later_headers.strong_etag
                        && plugin.should_release_response_body_for_later_strong_etag(
                            &simulated_ctx,
                            response_status,
                            &simulated_response_headers,
                        ))
            } else {
                true
            };
            if can_release {
                plugin.simulate_after_proxy_response_headers(
                    &mut simulated_ctx,
                    &mut simulated_response_headers,
                );
            }
            can_release
        });
    if saw_active_buffering_plugin && all_active_plugins_can_release_before_content_type_rewrite {
        return true;
    }
    if plugins
        .iter()
        .any(|plugin| plugin.may_modify_response_content_type(ctx, content_type))
    {
        return false;
    }
    // Keep buffering only while at least one plugin still needs the body for
    // this response representation; otherwise stream it straight through.
    // Plugins see the response status and full header map so they can account
    // for Content-Encoding or release a response they will not transform (e.g.
    // `compression` skips `206`/`Content-Range` range responses).
    !plugins.iter().any(|plugin| {
        plugin.should_buffer_response_body_for_content_type(
            ctx,
            content_type,
            response_status,
            response_headers,
        )
    })
}

/// Fix 5: decide whether a plain-HTTPS direct-H2 response body should skip
/// the `CoalescingH2Body` adapter and stream through hyper's `Incoming`
/// directly.
///
/// Bypass is safe when:
///   * `content-length` is known (we can size-check up-front), AND
///   * it is ≥ 512 KiB (backend is already emitting large H2 frames —
///     `http2_max_frame_size` is 1 MiB in our build — so coalescing just
///     adds a `BytesMut::extend_from_slice` copy that the large-frame
///     bypass at `body.rs:~1184` would skip anyway), AND
///   * the size fits within `max_response_body_size_bytes` (or the limit
///     is disabled). Outside that window we keep the coalescer so any
///     upstream size enforcement still wraps the body.
///
/// Does NOT apply to the gRPC streaming response path — CLAUDE.md
/// documents a +35 % gRPC large-payload win from coalescing, so that path
/// deliberately stays on `CoalescingH2Body`.
///
/// Threshold is 512 KiB: below that the coalescer's per-frame amortisation
/// dominates; above that the backend's own frame size already matches or
/// exceeds the coalesce target of 128 KiB so coalescing is a net copy.
pub(crate) fn should_bypass_h2_coalesce_for_large_response(
    content_length: Option<u64>,
    max_response_body_size_bytes: usize,
) -> bool {
    /// Responses smaller than this retain the coalescer — per-frame
    /// writer amortisation still helps the downstream H2 send path.
    const LARGE_H2_BYPASS_THRESHOLD: u64 = 512 * 1024;

    let Some(len) = content_length else {
        return false;
    };
    let within_limit =
        max_response_body_size_bytes == 0 || len <= max_response_body_size_bytes as u64;
    len >= LARGE_H2_BYPASS_THRESHOLD && within_limit
}

/// Keep H2 transport header-list enforcement from resetting the stream before
/// Ferrum's configured total-header validator can produce a protocol-aware 431.
fn h2_parser_max_header_list_size(max_header_size_bytes: usize) -> u32 {
    const MIN_H2_HEADER_LIST_SIZE: usize = 16 * 1024;

    max_header_size_bytes
        .max(MIN_H2_HEADER_LIST_SIZE)
        .min(u32::MAX as usize) as u32
}

fn warn_if_h3_backend_tls_policy_incompatible(
    config: &GatewayConfig,
    tls_policy: Option<&TlsPolicy>,
) {
    let Some(policy) = tls_policy else {
        return;
    };

    let h3_candidate_proxy_ids: Vec<&str> = config
        .proxies
        .iter()
        .filter(|proxy| proxy.dispatch_kind == DispatchKind::HttpsPool)
        .map(|proxy| proxy.id.as_str())
        .collect();
    if h3_candidate_proxy_ids.is_empty() {
        return;
    }

    if let Err(err) = crate::tls::validate_backend_tls_policy_for_quic(policy) {
        let sample = h3_candidate_proxy_ids
            .iter()
            .take(3)
            .copied()
            .collect::<Vec<_>>()
            .join(", ");
        warn!(
            h3_proxy_count = h3_candidate_proxy_ids.len(),
            h3_proxy_sample = %sample,
            "Backend TLS policy is incompatible with HTTP/3/QUIC ({}). H3 backends will fall back to rustls safe defaults for the QUIC builder.",
            err
        );
    }
}

/// IDs of HTTP-family proxies whose effective WebSocket idle timeout resolves to
/// `0` (disabled) — i.e. an upgraded WebSocket on them would have no idle bound.
/// The effective timeout is the per-proxy `websocket_idle_timeout_seconds`
/// override when set, else the global `FERRUM_WEBSOCKET_IDLE_TIMEOUT_SECONDS`.
fn websocket_idle_disabled_proxy_ids(
    config: &GatewayConfig,
    global_ws_idle_timeout_seconds: u64,
) -> Vec<&str> {
    config
        .proxies
        .iter()
        .filter(|proxy| {
            matches!(
                proxy.dispatch_kind,
                DispatchKind::HttpPool | DispatchKind::HttpsPool
            ) && proxy.effective_websocket_idle_timeout_seconds(global_ws_idle_timeout_seconds) == 0
        })
        .map(|proxy| proxy.id.as_str())
        .collect()
}

/// Emit the resource-hoarding warning for a set of proxies with a disabled
/// WebSocket idle bound. An upgraded WebSocket holds a dedicated backend
/// connection plus a `websocket_max_connections` slot for its entire lifetime;
/// with the idle timeout disabled, a silent (non-heartbeating) client can hoard
/// that slot indefinitely. Activity from either direction — including Ping/Pong
/// — refreshes the timer, so the disabled state is the only exposure.
fn emit_websocket_idle_disabled_warning(
    disabled_proxy_ids: &[&str],
    global_ws_idle_timeout_seconds: u64,
) {
    let sample = disabled_proxy_ids
        .iter()
        .take(3)
        .copied()
        .collect::<Vec<_>>()
        .join(", ");
    warn!(
        ws_idle_disabled_proxy_count = disabled_proxy_ids.len(),
        ws_idle_disabled_proxy_sample = %sample,
        global_websocket_idle_timeout_seconds = global_ws_idle_timeout_seconds,
        "WebSocket idle timeout is disabled (0) for one or more HTTP-family proxies. \
         Idle upgraded WebSocket sessions will hold a backend connection and a \
         FERRUM_WEBSOCKET_MAX_CONNECTIONS slot indefinitely (resource-hoarding risk). \
         Set FERRUM_WEBSOCKET_IDLE_TIMEOUT_SECONDS (global) or the per-proxy \
         websocket_idle_timeout_seconds to a non-zero value to bound idle lifetime."
    );
}

/// Warn at startup when WebSocket sessions on HTTP-family proxies have no idle
/// bound. Fires only when an operator has explicitly opted out (the global
/// default is 300s), so the warning maps to a deliberate opt-out rather than
/// spamming default deployments.
fn warn_if_websocket_idle_disabled(config: &GatewayConfig, global_ws_idle_timeout_seconds: u64) {
    let disabled = websocket_idle_disabled_proxy_ids(config, global_ws_idle_timeout_seconds);
    if disabled.is_empty() {
        return;
    }
    emit_websocket_idle_disabled_warning(&disabled, global_ws_idle_timeout_seconds);
}

/// IDs of HTTP-family proxies whose WebSocket idle bound becomes *newly* disabled
/// in `next` relative to `previous` — i.e. a proxy added with an effective `0`
/// timeout, or one whose effective timeout changed from a bound value to `0`.
/// Proxies already disabled in `previous` are excluded so a persistent opt-out
/// is not reported again. The returned slices borrow from `next`.
fn websocket_idle_newly_disabled_proxy_ids<'a>(
    previous: &GatewayConfig,
    next: &'a GatewayConfig,
    global_ws_idle_timeout_seconds: u64,
) -> Vec<&'a str> {
    let previously_disabled: std::collections::HashSet<&str> =
        websocket_idle_disabled_proxy_ids(previous, global_ws_idle_timeout_seconds)
            .into_iter()
            .collect();
    websocket_idle_disabled_proxy_ids(next, global_ws_idle_timeout_seconds)
        .into_iter()
        .filter(|id| !previously_disabled.contains(id))
        .collect()
}

/// Warn on config reload when a reload makes a proxy's WebSocket idle bound
/// *newly* disabled. Hot-reloaded `websocket_idle_timeout_seconds` changes are
/// otherwise invisible because reload swaps config in place rather than
/// rebuilding `ProxyState` (where the startup warning lives).
fn warn_if_websocket_idle_newly_disabled(
    previous: &GatewayConfig,
    next: &GatewayConfig,
    global_ws_idle_timeout_seconds: u64,
) {
    let newly_disabled =
        websocket_idle_newly_disabled_proxy_ids(previous, next, global_ws_idle_timeout_seconds);
    if newly_disabled.is_empty() {
        return;
    }
    emit_websocket_idle_disabled_warning(&newly_disabled, global_ws_idle_timeout_seconds);
}

fn h3_websocket_reachable_from_listener(env_config: &EnvConfig, h3_listener_started: bool) -> bool {
    h3_listener_started && env_config.enable_http3 && env_config.http3_websocket_enabled
}

fn h3_websocket_quic_idle_mismatch_proxy_ids(
    config: &GatewayConfig,
    h3_websocket_reachable: bool,
    global_ws_idle_timeout_seconds: u64,
    http3_idle_timeout_seconds: u64,
) -> Vec<&str> {
    if !h3_websocket_reachable || http3_idle_timeout_seconds == 0 {
        return Vec::new();
    }

    config
        .proxies
        .iter()
        .filter(|proxy| proxy.dispatch_kind.is_http_family())
        .filter(|proxy| {
            let ws_idle =
                proxy.effective_websocket_idle_timeout_seconds(global_ws_idle_timeout_seconds);
            ws_idle == 0 || ws_idle > http3_idle_timeout_seconds
        })
        .map(|proxy| proxy.id.as_str())
        .collect()
}

fn emit_h3_websocket_quic_idle_mismatch_warning(
    affected_proxy_ids: &[&str],
    global_ws_idle_timeout_seconds: u64,
    http3_idle_timeout_seconds: u64,
) {
    let sample = affected_proxy_ids
        .iter()
        .take(3)
        .copied()
        .collect::<Vec<_>>()
        .join(", ");
    warn!(
        h3_websocket_quic_idle_mismatch_proxy_count = affected_proxy_ids.len(),
        h3_websocket_quic_idle_mismatch_proxy_sample = %sample,
        global_websocket_idle_timeout_seconds = global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
        "One or more HTTP-family proxies have a WebSocket idle timeout longer than the HTTP/3 QUIC connection idle timeout. \
         On an otherwise-idle H3 connection, QUIC max_idle_timeout (FERRUM_HTTP3_IDLE_TIMEOUT) can close the connection before the WebSocket idle timer; \
         multiplexed H3 connections with other active streams may stay open. Raise FERRUM_HTTP3_IDLE_TIMEOUT or lower websocket_idle_timeout_seconds / \
         FERRUM_WEBSOCKET_IDLE_TIMEOUT_SECONDS if isolated H3 WebSockets must honor the longer idle window."
    );
}

fn warn_if_h3_websocket_quic_idle_mismatch(
    config: &GatewayConfig,
    h3_websocket_reachable: bool,
    global_ws_idle_timeout_seconds: u64,
    http3_idle_timeout_seconds: u64,
) {
    let affected = h3_websocket_quic_idle_mismatch_proxy_ids(
        config,
        h3_websocket_reachable,
        global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
    );
    if affected.is_empty() {
        return;
    }
    emit_h3_websocket_quic_idle_mismatch_warning(
        &affected,
        global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
    );
}

fn h3_websocket_new_quic_idle_mismatch_proxy_ids<'a>(
    previous: &GatewayConfig,
    next: &'a GatewayConfig,
    h3_websocket_reachable: bool,
    global_ws_idle_timeout_seconds: u64,
    http3_idle_timeout_seconds: u64,
) -> Vec<&'a str> {
    let previous_affected: std::collections::HashSet<&str> =
        h3_websocket_quic_idle_mismatch_proxy_ids(
            previous,
            h3_websocket_reachable,
            global_ws_idle_timeout_seconds,
            http3_idle_timeout_seconds,
        )
        .into_iter()
        .collect();

    h3_websocket_quic_idle_mismatch_proxy_ids(
        next,
        h3_websocket_reachable,
        global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
    )
    .into_iter()
    .filter(|id| !previous_affected.contains(id))
    .collect()
}

fn warn_if_h3_websocket_new_quic_idle_mismatch(
    previous: &GatewayConfig,
    next: &GatewayConfig,
    h3_websocket_reachable: bool,
    global_ws_idle_timeout_seconds: u64,
    http3_idle_timeout_seconds: u64,
) {
    let newly_affected = h3_websocket_new_quic_idle_mismatch_proxy_ids(
        previous,
        next,
        h3_websocket_reachable,
        global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
    );
    if newly_affected.is_empty() {
        return;
    }
    emit_h3_websocket_quic_idle_mismatch_warning(
        &newly_affected,
        global_ws_idle_timeout_seconds,
        http3_idle_timeout_seconds,
    );
}

/// Check if the request is a WebSocket upgrade request.
///
/// Uses ASCII case-insensitive comparisons to avoid per-request `to_lowercase()`
/// String allocations on the hot path.
///
/// Validates the `Sec-WebSocket-Key` header format: RFC 6455 §4.1 requires it to
/// be a base64-encoded 16-byte nonce (exactly 24 base64 characters). A malformed
/// key causes the handshake to be treated as a non-WebSocket request, which the
/// backend will handle as a regular HTTP request rather than proceeding with a
/// broken upgrade.
/// Check if the request is an HTTP/2 Extended CONNECT WebSocket request (RFC 8441).
///
/// In HTTP/2, WebSocket upgrades use the CONNECT method with a `:protocol = "websocket"`
/// pseudo-header instead of the HTTP/1.1 Upgrade mechanism. hyper exposes the pseudo-header
/// as a `hyper::ext::Protocol` extension on the request.
///
/// Generic over the body type so unit tests can use `Request<()>` without constructing
/// an `Incoming` body.
pub fn is_h2_websocket_connect<B>(req: &Request<B>) -> bool {
    req.method() == hyper::Method::CONNECT
        && req.version() == hyper::Version::HTTP_2
        && req
            .extensions()
            .get::<hyper::ext::Protocol>()
            .is_some_and(|p| p.as_ref().eq_ignore_ascii_case(b"websocket"))
}

/// Check if this is an Istio-flavored HBONE CONNECT request admitted by mesh mode.
///
/// HBONE is ordinary HTTP/2 CONNECT over mTLS. Unlike RFC 8441 WebSocket
/// Extended CONNECT, it does not use a `:protocol` value. Requiring the
/// `Protocol` extension to be absent keeps other Extended CONNECT variants
/// (for example `connect-udp`) on the existing fail-closed path.
pub fn is_hbone_connect_request<B>(req: &Request<B>, env_config: &EnvConfig) -> bool {
    hbone_proxy::is_connect_request(req, env_config)
}

/// Whether `req` is a datagram-over-HBONE CONNECT (F3 §3.3 Stage 4). Disjoint
/// from [`is_hbone_connect_request`]; the dispatch ladder treats EITHER as a
/// CONNECT-relay (shared path normalization, body-buffering avoidance, route-miss
/// relay synthesis) but routes the `udp` flavor to the unframing UDP handler.
pub fn is_udp_hbone_connect_request<B>(req: &Request<B>, env_config: &EnvConfig) -> bool {
    hbone_proxy::is_udp_connect_request(req, env_config)
}

/// Whether an authenticated inbound HBONE CONNECT to `host:port` may be
/// transparently relayed. SAFE local targets only: a loopback address on an
/// application port declared by the slice, or an in-mesh workload address+port
/// the slice already declares. This bounds the terminator to mesh-known
/// destinations, so an authenticated peer can never use the HBONE listener as
/// an open proxy to arbitrary internal hosts or undeclared loopback listeners.
/// (`handle_hbone_request` separately requires the peer to be an authenticated,
/// trust-domain-verified mesh identity before dialing.)
fn inbound_hbone_relay_destination_allowed(
    host: &str,
    port: u16,
    mesh: Option<&crate::modes::mesh::config::MeshConfig>,
) -> bool {
    let Some(mesh) = mesh else {
        return false;
    };
    let host = hbone_relay_authority_host_for_mesh(host);

    if host.eq_ignore_ascii_case("localhost")
        || host
            .parse::<std::net::IpAddr>()
            .is_ok_and(|ip| ip.is_loopback())
    {
        return mesh
            .workloads
            .iter()
            .flat_map(|workload| &workload.ports)
            .any(|workload_port| workload_port.port == port);
    }

    // Otherwise the destination must be an in-mesh workload address+port the
    // slice declares — never an arbitrary host. A workload that declares no
    // ports admits any port for its address (the slice does not constrain it).
    mesh.workloads.iter().any(|workload| {
        workload.addresses.iter().any(|addr| addr == host)
            && (workload.ports.is_empty() || workload.ports.iter().any(|wp| wp.port == port))
    })
}

fn hbone_relay_authority_host_for_mesh(host: &str) -> &str {
    let Some(inner) = host
        .strip_prefix('[')
        .and_then(|host| host.strip_suffix(']'))
    else {
        return host;
    };
    if inner.parse::<std::net::Ipv6Addr>().is_ok() {
        inner
    } else {
        host
    }
}

/// Build a transparent inbound HBONE relay proxy that dials the CONNECT
/// `:authority` of an authenticated mesh peer, for an Ambient/Waypoint
/// terminator where no inbound route is materialized. Returns `None` (caller
/// 404s) when the authority is missing/portless or is not a safe local relay
/// target per [`inbound_hbone_relay_destination_allowed`].
fn build_inbound_hbone_relay_proxy(
    authority: Option<&http::uri::Authority>,
    mesh: Option<&crate::modes::mesh::config::MeshConfig>,
) -> Option<Arc<Proxy>> {
    let authority = authority?;
    let host = hbone_relay_authority_host_for_mesh(authority.host());
    let port = authority.port_u16()?;
    if host.is_empty() || port == 0 {
        return None;
    }
    if !inbound_hbone_relay_destination_allowed(host, port, mesh) {
        return None;
    }
    Some(Arc::new(
        crate::modes::mesh::mesh_inbound_hbone_relay_proxy(host, port),
    ))
}

#[allow(dead_code)]
fn is_websocket_upgrade(req: &Request<Incoming>) -> bool {
    let headers = req.headers();
    let connection = headers.get("connection").and_then(|v| v.to_str().ok());
    let upgrade = headers.get("upgrade").and_then(|v| v.to_str().ok());
    let sec_key = headers
        .get("sec-websocket-key")
        .and_then(|v| v.to_str().ok());
    let sec_version = headers
        .get("sec-websocket-version")
        .and_then(|v| v.to_str().ok());

    connection.is_some_and(|conn| {
        // The Connection header can contain comma-separated values (e.g., "keep-alive, Upgrade").
        // Split on commas and check each token case-insensitively without allocating.
        conn.split(',')
            .any(|token| token.trim().eq_ignore_ascii_case("upgrade"))
    }) && upgrade.is_some_and(|up| up.eq_ignore_ascii_case("websocket"))
        && sec_key.is_some_and(is_valid_websocket_key)
        && (sec_version == Some("13"))
}

/// Validate that a `Sec-WebSocket-Key` value is a base64-encoded 16-byte nonce.
///
/// RFC 6455 §4.1 requires the key to be exactly 16 bytes of random data,
/// base64-encoded to 24 characters (16 bytes → 22 base64 chars + 2 padding `=`).
///
/// Leading/trailing OWS (RFC 9110 §5.5: ASCII space + horizontal tab) is trimmed
/// before validation. Header parsers are required to strip OWS, but cross-hop
/// normalization is not guaranteed to be consistent, so we trim defensively here.
/// `str::trim_ascii` is used (vs. `str::trim`) because OWS is strictly ASCII —
/// avoiding the Unicode-boundary scan is both faster and more spec-precise.
/// `ws_accept_from_key` performs the same trim so admission and accept-key
/// derivation stay byte-for-byte aligned.
pub fn is_valid_websocket_key(key: &str) -> bool {
    use base64::Engine;
    let key = key.trim_ascii();
    key.len() == 24
        && base64::engine::general_purpose::STANDARD
            .decode(key)
            .is_ok_and(|bytes| bytes.len() == 16)
}

/// Derive the `Sec-WebSocket-Accept` response header value from a raw
/// `Sec-WebSocket-Key` request header.
///
/// RFC 6455 §4.2.2 specifies that the Accept value is computed over the EXACT
/// base64-encoded key the client sent. Any leading/trailing whitespace in the
/// raw header value would otherwise leak into the SHA-1 input and produce an
/// Accept value the client rejects, so we trim before hashing.
/// `str::trim_ascii` is used (vs. `str::trim`) because RFC 9110 §5.5 OWS is
/// strictly ASCII — avoiding the Unicode-boundary scan is both faster and more
/// spec-precise. `is_valid_websocket_key` performs the same trim so admission
/// and derivation agree on what counts as the "key bytes".
///
/// An empty / missing key (`""`) is passed through to `derive_accept_key`
/// unchanged to preserve the prior fallback behavior — admission already
/// rejects requests without a key, so this branch is only reachable in
/// pathological / mock cases.
pub fn ws_accept_from_key(raw: &str) -> String {
    derive_accept_key(raw.trim_ascii().as_bytes())
}

/// Parse an HTTP method string into a `reqwest::Method`.
///
/// Common methods are matched as constants (zero-cost), with a fallback to
/// `from_bytes()` for non-standard methods. Extracted as a helper to avoid
/// duplicating this match block across `proxy_to_backend` and `proxy_to_backend_retry`
/// (code deduplication improves instruction cache utilization).
fn parse_reqwest_method(method: &str) -> Result<reqwest::Method, ()> {
    match method {
        "GET" => Ok(reqwest::Method::GET),
        "POST" => Ok(reqwest::Method::POST),
        "PUT" => Ok(reqwest::Method::PUT),
        "DELETE" => Ok(reqwest::Method::DELETE),
        "PATCH" => Ok(reqwest::Method::PATCH),
        "HEAD" => Ok(reqwest::Method::HEAD),
        "OPTIONS" => Ok(reqwest::Method::OPTIONS),
        other => reqwest::Method::from_bytes(other.as_bytes()).map_err(|_| ()),
    }
}

/// Whether HTTPS requests may use the direct hyper HTTP/2 backend pool.
///
/// Request-body plugins require buffering and transformation before forwarding,
/// which the direct H2 path does not implement. Those requests must stay on the
/// reqwest path so the final backend body matches the plugin output.
pub(crate) fn can_use_direct_http2_pool(
    enable_http2: bool,
    retain_request_body: bool,
    requires_request_body_buffering: bool,
) -> bool {
    enable_http2 && !retain_request_body && !requires_request_body_buffering
}

/// Whether HTTPS requests may dispatch over the direct hyper HTTP/2 backend pool.
///
/// `get_sender()` may dial or probe the backend, so callers must use this
/// stricter predicate before opening an H2 sender. When body-size limits are
/// enabled, ordinary (non-SNI) requests stay on the reqwest path so local
/// request-size checks and deferred backend admission run before any backend
/// interaction. Backend TLS SNI overrides cannot use reqwest, so callers that
/// require direct-H2 for SNI should consult [`can_use_direct_http2_pool`]
/// instead and enforce limits in-path (413 / 502) on the H2 sender.
pub(crate) fn can_dispatch_direct_http2_pool(
    enable_http2: bool,
    retain_request_body: bool,
    requires_request_body_buffering: bool,
    max_request_body_size_bytes: usize,
    max_response_body_size_bytes: usize,
) -> bool {
    can_use_direct_http2_pool(
        enable_http2,
        retain_request_body,
        requires_request_body_buffering,
    ) && max_request_body_size_bytes == 0
        && max_response_body_size_bytes == 0
}

/// Resolve whether plain-HTTPS dispatch should take the direct HTTP/2 pool,
/// folding in the DestinationRule `connectionPool.http.h2UpgradePolicy`
/// override on top of the capability-registry verdict.
///
/// `can_dispatch` is the body/limit/`enable_http2` gate
/// ([`can_dispatch_direct_http2_pool`]). `supports` is the registry's
/// `h2_tls == Supported`; `known_unsupported` is `h2_tls == Unsupported`
/// (absence / `Unknown` is neither). `requires_sni` forces direct-H2 because
/// reqwest cannot apply a per-request backend SNI.
///
/// Policy interaction (scope is strictly plain-HTTPS h1-vs-h2; gRPC and
/// HBONE/mesh-mTLS never reach this):
/// * `DoNotUpgrade` → never take direct-H2 (force reqwest/H1), UNLESS a
///   backend-TLS SNI override mandates it (`requires_sni` wins).
/// * `Upgrade` → also take direct-H2 when the registry verdict is `Unknown`
///   (no record yet / `h2_tls == Unknown`), as a hint to try H2 instead of
///   defaulting to reqwest — but stays fail-safe: a target proven
///   `Unsupported` is never forced onto H2.
/// * `DEFAULT`/absent (`None`) → unchanged probe-driven behavior (take H2
///   only when `supports` or `requires_sni`).
pub(crate) fn should_dispatch_direct_h2(
    can_dispatch: bool,
    supports: bool,
    known_unsupported: bool,
    requires_sni: bool,
    policy: Option<crate::config::types::H2UpgradePolicy>,
) -> bool {
    use crate::config::types::H2UpgradePolicy;
    if !can_dispatch {
        return false;
    }
    // DO_NOT_UPGRADE forces reqwest/H1 unless a per-request SNI mandates H2.
    if matches!(policy, Some(H2UpgradePolicy::DoNotUpgrade)) && !requires_sni {
        return false;
    }
    // UPGRADE treats an unclassified target as a hint to try H2, but never
    // overrides a proven-Unsupported verdict.
    let prefer_upgrade = matches!(policy, Some(H2UpgradePolicy::Upgrade)) && !known_unsupported;
    supports || requires_sni || prefer_upgrade
}

pub(crate) fn supports_native_http3_backend(
    state: &ProxyState,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> bool {
    // Cheap gate FIRST — this runs per request and per retry rotation on the
    // H1/H2 dispatch path. `dispatch_kind` is not target-overridable: the
    // per-target projection (`resolve_effective_proxy_for_target`) writes only
    // connect timeout / pool knobs / `resolved_tls` / `h2_upgrade_policy`, and
    // `resolve_backend_connection_proxy_for_target` only rebases host/port —
    // so the common non-HttpsPool case returns before any per-target
    // capability-key resolution work.
    proxy.dispatch_kind == DispatchKind::HttpsPool
        && get_backend_capability_for_target(
            state.backend_capabilities.as_ref(),
            proxy,
            upstream_target,
        )
        .is_some_and(|record| record.plain_http.h3.is_supported())
}

/// Resolve the proxy shape used to build backend capability keys for a concrete
/// target. Startup probing uses [`BackendCapabilityProbeTarget::from_proxy`],
/// which first applies the full target-scoped override projection
/// (`resolve_effective_proxy_for_target`) and then keys the registry from that
/// effective proxy plus the target host/port. Request-path lookups and live
/// downgrades must mirror that key exactly or they can miss a Supported probe
/// record and/or write Unsupported to the base proxy key.
///
/// Hot-path discipline: capability keys read exactly these proxy fields
/// (`write_capability_key`): `backend_scheme`, `backend_host`/`backend_port`
/// (superseded by the target's host/port when a target is present),
/// `dns_override`, and `resolved_tls`. Of those, the ONLY field the per-target
/// projection can change is `resolved_tls` (DestinationRule
/// `portLevelSettings[].tls`; the SD top-level fallback slot carries
/// `connectionPool.http` fields only — see
/// `dispatch_port_override_fallback_from_upstream`). So this resolver projects
/// ONLY the effective TLS override — mirroring
/// `resolve_effective_proxy_for_target`'s merged-override `tls` semantics (a
/// present per-port entry's `tls` governs; the fallback slot's `tls` applies
/// only when the port has no per-port entry) — and skips the full-proxy clone
/// a non-key-relevant delta (per-port `connectTimeout`, the most common DR
/// knob) would otherwise force onto every per-request capability lookup. Keys
/// built from this resolver are identical to keys built from the full
/// effective proxy (pinned by
/// `capability_proxy_resolution_matches_effective_proxy_keys`).
fn resolve_backend_capability_proxy_for_target<'a>(
    proxy: &'a Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> std::borrow::Cow<'a, Proxy> {
    let Some(target) = upstream_target else {
        return std::borrow::Cow::Borrowed(proxy);
    };
    let per_port = proxy
        .dispatch_port_overrides
        .as_ref()
        .and_then(|overrides| overrides.get(&target.dispatch_policy_port()));
    let tls_override = match per_port {
        Some(override_config) => override_config.tls.as_ref(),
        None => proxy
            .dispatch_port_override_fallback
            .as_ref()
            .and_then(|fallback| fallback.tls.as_ref()),
    }
    .filter(|tls| **tls != proxy.resolved_tls);
    match tls_override {
        None => std::borrow::Cow::Borrowed(proxy),
        Some(tls) => {
            let mut owned = proxy.clone();
            owned.resolved_tls = tls.clone();
            std::borrow::Cow::Owned(owned)
        }
    }
}

pub(crate) fn get_backend_capability_for_target(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> Option<Arc<BackendCapabilityRecord>> {
    let capability_proxy = resolve_backend_capability_proxy_for_target(proxy, upstream_target);
    registry.get(capability_proxy.as_ref(), upstream_target)
}

fn mark_h3_unsupported_for_backend_target(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) {
    let capability_proxy = resolve_backend_capability_proxy_for_target(proxy, upstream_target);
    registry.mark_h3_unsupported(capability_proxy.as_ref(), upstream_target);
}

fn mark_h2_tls_unsupported_for_backend_target(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> bool {
    let capability_proxy = resolve_backend_capability_proxy_for_target(proxy, upstream_target);
    registry.mark_h2_tls_unsupported(capability_proxy.as_ref(), upstream_target)
}

fn mark_hbone_unsupported_for_backend_target(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) {
    let capability_proxy = resolve_backend_capability_proxy_for_target(proxy, upstream_target);
    registry.mark_hbone_unsupported(capability_proxy.as_ref(), upstream_target);
}

/// True when an `ErrorClass` represents an H3 / QUIC transport-level
/// failure that should downgrade the cached H3 capability to
/// `Unsupported`. Excludes application-layer / client-side errors
/// (`ClientDisconnect`, `RequestBodyTooLarge`, `ResponseBodyTooLarge`,
/// `RequestError`) and backend response read timeouts, which do not prove
/// the backend has lost H3 capability.
pub(crate) fn is_h3_transport_error_class(class: retry::ErrorClass) -> bool {
    matches!(
        class,
        retry::ErrorClass::ConnectionRefused
            | retry::ErrorClass::ConnectionTimeout
            | retry::ErrorClass::ConnectionReset
            | retry::ErrorClass::ConnectionClosed
            | retry::ErrorClass::TlsError
            | retry::ErrorClass::ProtocolError
            | retry::ErrorClass::DnsLookupError
            | retry::ErrorClass::PortExhaustion
    )
}

/// Reachability-class probe failures that must not wipe a previously
/// `Supported` H2/H3 classification during periodic refresh.
///
/// Mirrors the HBONE probe's preserve-on-non-capability-failure contract:
/// DNS blips, connect timeouts, refused-during-restart, and port exhaustion
/// are transient — stamp `last_probe_error` for operators, but carry the prior
/// classification forward. Genuine protocol/ALPN evidence still downgrades.
pub(crate) fn is_transient_capability_probe_failure(class: retry::ErrorClass) -> bool {
    matches!(
        class,
        retry::ErrorClass::DnsLookupError
            | retry::ErrorClass::ConnectionTimeout
            | retry::ErrorClass::ConnectionRefused
            | retry::ErrorClass::PortExhaustion
    )
}

/// Decide whether an H3 probe failure is worth surfacing in
/// `last_probe_error`.
///
/// A failure against a target previously classified `Supported` is always
/// operator-relevant: either the classification was just downgraded, or it was
/// preserved across a transient fault and the cached record is now stale. Every
/// other outcome is the expected "this HTTPS backend has no QUIC listener"
/// case, which must stay silent so `GET /backend-capabilities` does not report
/// a phantom error for every healthy non-QUIC backend on every refresh
/// (documented in `openapi.yaml` / `docs/admin_api.md`).
fn h3_probe_failure_error(previous: Option<ProtocolSupport>, message: String) -> Option<String> {
    matches!(previous, Some(ProtocolSupport::Supported)).then_some(message)
}

pub fn websocket_origin_allowed(allowed_origins: &[String], origin: &str) -> bool {
    allowed_origins
        .iter()
        .any(|allowed| websocket_origin_matches(allowed, origin))
}

fn websocket_origin_matches(allowed: &str, origin: &str) -> bool {
    if allowed.eq_ignore_ascii_case(origin) {
        return true;
    }

    match (
        normalized_websocket_origin(allowed),
        normalized_websocket_origin(origin),
    ) {
        (Some(allowed), Some(origin)) => allowed.eq_ignore_ascii_case(&origin),
        _ => false,
    }
}

fn normalized_websocket_origin(raw: &str) -> Option<String> {
    let parsed = url::Url::parse(raw).ok()?;
    if parsed.path() != "/" || parsed.query().is_some() || parsed.fragment().is_some() {
        return None;
    }
    // RFC 6454 serialized origins are scheme://host[:port] and never carry
    // userinfo. Fail closed on credentials so an Origin like
    // `https://attacker@good.example` is not normalized down to the
    // allow-listed `https://good.example` and waved through admission.
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return None;
    }
    let default_port = match parsed.scheme() {
        "http" | "ws" => 80,
        "https" | "wss" => 443,
        _ => return None,
    };
    let host = parsed.host_str()?;

    let mut normalized = String::with_capacity(raw.len());
    normalized.push_str(&parsed.scheme().to_ascii_lowercase());
    normalized.push_str("://");
    if host.contains(':') && !host.starts_with('[') {
        normalized.push('[');
        normalized.push_str(&host.to_ascii_lowercase());
        normalized.push(']');
    } else {
        normalized.push_str(&host.to_ascii_lowercase());
    }
    if let Some(port) = parsed.port()
        && port != default_port
    {
        normalized.push(':');
        normalized.push_str(&port.to_string());
    }
    Some(normalized)
}

/// Is this H3 backend response the kind that should downgrade the cached
/// H3 capability to `Unsupported`? Only connection / protocol-level
/// failures — not 4xx/5xx application responses, not client disconnects,
/// not payload-size errors.
/// Classifies an H3 backend response as a transport-level failure based
/// on `error_class` ALONE — intentionally ignoring `connection_error`.
///
/// Rationale: `classify_h3_error` marks GOAWAY / stream reset / other
/// protocol errors with `connection_error=false`, yet they are still H3
/// transport failures. Routing the next request through the same native H3
/// pool would just repeat them. Application-layer outcomes and backend
/// response read timeouts leave the capability untouched — those reflect
/// the request or backend latency, not whether the backend speaks H3.
fn is_h3_transport_failure(resp: &retry::BackendResponse) -> bool {
    resp.error_class.is_some_and(is_h3_transport_error_class)
}

fn can_use_hbone_pool(
    retain_request_body: bool,
    requires_request_body_buffering: bool,
    stream_request_body: bool,
) -> bool {
    !retain_request_body && !requires_request_body_buffering && stream_request_body
}

fn proxy_can_dispatch_hbone(proxy: &Proxy) -> bool {
    proxy.dispatch_kind == DispatchKind::HttpPool
}

fn can_attempt_hbone_backend(
    registry: &BackendCapabilityRegistry,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
    gateway_svid_loaded: bool,
) -> bool {
    let Some(target) = upstream_target else {
        return false;
    };
    // CROSS-CLUSTER HBONE targets BYPASS the capability registry: such a target
    // dials the operator-declared east-west GATEWAY (`:15443`), not a probeable
    // workload `:15008`, so no capability record is ever collected for it (the
    // gateway is never enrolled in `collect_mesh_*_capability_targets`) and a
    // registry-gated dispatch would fail closed forever. Trust the
    // operator-declared gateway infra — the same assumption the Sidecar mesh-mTLS
    // egress path makes (it has no capability registry at all). The SVID-present
    // + HttpPool + `mesh.hbone` tag checks still apply.
    let registry_ok = if hbone_pool::target_hbone_cross_cluster(target) {
        true
    } else {
        // Target-effective keying: probes (`BackendCapabilityProbeTarget::
        // from_proxy`) and live downgrades (`mark_hbone_unsupported_for_
        // backend_target`) key records under the target-effective proxy, so
        // this fail-open gate must read the SAME key or it never sees an
        // Unsupported downgrade when a per-port DR TLS override shifts the key
        // off the base proxy — resetting HBONE failure dampening every dial.
        get_backend_capability_for_target(registry, proxy, Some(target))
            .is_none_or(|record| !matches!(record.hbone, ProtocolSupport::Unsupported))
    };
    proxy_can_dispatch_hbone(proxy)
        && hbone_pool::target_hbone_enabled(target)
        && gateway_svid_loaded
        && registry_ok
}

/// Whether a target dispatches over the Sidecar egress SVID-mTLS HTTP/2 pool
/// (`mesh.mtls=true` tag). Unlike HBONE there is no capability-registry gate:
/// `mesh.mtls` targets are produced only by the mesh outbound materializer and
/// by `sidecar`-topology mesh service discovery, both for slice-declared
/// sidecar peers, so the peer's transport is known by construction — a failed
/// dial is a connection error, not a capability classification signal.
fn supports_mesh_mtls_backend(
    state: &ProxyState,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> bool {
    let Some(target) = upstream_target else {
        return false;
    };
    // Same dispatch-kind gate as HBONE: only plaintext HttpPool proxies carry
    // mesh egress routes.
    proxy_can_dispatch_hbone(proxy)
        && mesh_mtls_pool::target_mesh_mtls_enabled(target)
        && state.gateway_svid_bundle.load().is_some()
}

fn should_fallback_to_reqwest_after_http2_pool_error(err: &http2_pool::Http2PoolError) -> bool {
    matches!(err, http2_pool::Http2PoolError::BackendSelectedHttp1 { .. })
}

fn http2_pool_sender_error_response(
    state: &ProxyState,
    proxy: &Proxy,
    err: &http2_pool::Http2PoolError,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let msg = err.message().to_string();
    let h2_error_class = http2_pool::classify_http2_pool_error(err);
    if matches!(h2_error_class, retry::ErrorClass::PortExhaustion) {
        state.overload.record_port_exhaustion();
    }
    let error_body = r#"{"error":"Backend unavailable"}"#.to_string();
    error!(proxy_id = %proxy.id, error = %msg, "HTTP/2 pool connection failed");
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(error_body.into_bytes()),
        headers: HashMap::new(),
        // Derive connection_error from the class so a gateway-side egress denial
        // (DispatchPolicyRejected — a hostname/dns_override that resolves or
        // rebinds to a blocked IP) is non-retryable and neutral to backend
        // health: request_reached_wire(DispatchPolicyRejected) is true, so this
        // is false (no backend was dialed) instead of a hard-coded connect error.
        connection_error: !retry::request_reached_wire(h2_error_class),
        backend_resolved_ip: resolved_ip,
        error_class: Some(h2_error_class),
    }
}

fn backend_tls_sni_requires_direct_h2_response(
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let mut headers = HashMap::with_capacity(1);
    headers.insert(
        "gateway-error-reason".to_string(),
        BACKEND_TLS_SNI_REQUIRES_DIRECT_H2_REASON.to_string(),
    );
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(r#"{"error":"Bad Gateway"}"#.as_bytes().to_vec()),
        headers,
        // reqwest cannot apply per-request backend SNI. Mark this terminal
        // gateway policy response as non-retryable so a 502 retry policy
        // cannot amplify it or trip the backend circuit breaker repeatedly.
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
    }
}

pub(crate) const BACKEND_TLS_SNI_REQUIRES_DIRECT_H2_REASON: &str =
    "backend_tls_sni_requires_direct_h2";

enum ClientRequestBody {
    Streaming(Box<Request<Incoming>>),
    Buffered(BufferedClientRequestBody),
}

/// A request body collected before backend dispatch together with the pristine
/// request-line metadata needed by transports that do not dispatch through
/// reqwest. Keeping the original `HeaderMap` is important for native gRPC:
/// binary metadata and repeated field lines cannot be reconstructed from the
/// plugin-facing `HashMap<String, String>` without losing information.
struct BufferedClientRequestBody {
    method: hyper::Method,
    headers: hyper::HeaderMap,
    body: Vec<u8>,
}

enum RequestBodyBufferError {
    TooLarge,
    ClientDisconnected(String),
    TimedOut,
    DeadlineExceeded,
}

#[derive(Debug, PartialEq, Eq)]
pub(crate) enum RequestBodyWaitError {
    TimedOut,
    DeadlineExceeded,
}

/// Which ceiling won when composing an absolute RPC deadline with the
/// operator whole-upload `backend_read_timeout_ms` bound.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum EarlyUploadBoundKind {
    /// Fresh operator whole-upload stall guard (`backend_read_timeout_ms > 0`).
    OperatorTimeout,
    /// Absolute client/RPC deadline (`grpc-timeout` / prepared budget).
    RpcDeadline,
}

/// Compose the earliest applicable early-upload ceiling.
///
/// - `operator_timeout_ms == 0` disables the fresh operator bound.
/// - A present absolute deadline still caps the drain when the operator bound
///   is disabled.
/// - When both are present, the earlier instant wins; the operator bound is
///   measured from `now` once per drain (later phases must reuse a prebuffer
///   instead of starting a second fresh operator window).
pub(crate) fn compose_early_upload_bound(
    absolute_deadline: Option<tokio::time::Instant>,
    operator_timeout_ms: u64,
) -> Option<(tokio::time::Instant, EarlyUploadBoundKind)> {
    match absolute_deadline {
        Some(deadline) if operator_timeout_ms > 0 => {
            match tokio::time::Instant::now()
                .checked_add(Duration::from_millis(operator_timeout_ms))
            {
                Some(read_deadline) if read_deadline < deadline => {
                    Some((read_deadline, EarlyUploadBoundKind::OperatorTimeout))
                }
                _ => Some((deadline, EarlyUploadBoundKind::RpcDeadline)),
            }
        }
        Some(deadline) => Some((deadline, EarlyUploadBoundKind::RpcDeadline)),
        None if operator_timeout_ms > 0 => tokio::time::Instant::now()
            .checked_add(Duration::from_millis(operator_timeout_ms))
            .map(|read_deadline| (read_deadline, EarlyUploadBoundKind::OperatorTimeout)),
        None => None,
    }
}

/// Decision for a direct-H2 request whose backend response headers arrived
/// before the client upload reached a terminal state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum DirectH2UploadGate {
    /// The upload finished cleanly, so the backend response may be forwarded.
    Forward,
    /// The configured request body limit was exceeded — deterministic 413,
    /// never the backend's early response.
    RequestBodyTooLarge,
    /// No terminal outcome was reported at all, so the size decision is
    /// genuinely unknown. Fail closed: an unvetted early backend response must
    /// not reach the client.
    FailClosed,
}

/// Map a terminal request-body outcome onto the direct-H2 response gate.
///
/// `Errored` / `Abandoned` forward the backend response. Both provably imply
/// the limit was *not* exceeded: overflow stores `exceeded` and reports
/// `RequestBodyOutcome::Exceeded` from the same `poll_frame`, taking the
/// completion sender so neither a later poll nor `Drop` can relabel it. Failing
/// closed on them instead would turn two ordinary flows into 502s — a backend
/// that answers early (401/403/413) and `RST_STREAM`s the unread upload, which
/// is what Go's and Envoy's HTTP/2 servers do by default, and a client that
/// disconnects mid-upload — while buying no additional enforcement.
///
/// `None` models a completion sender dropped without reporting. The adapter's
/// `Drop` impl makes that unreachable in practice, but it must still fail
/// closed rather than default to forwarding.
pub(crate) fn classify_direct_h2_upload_outcome(
    outcome: Option<body::RequestBodyOutcome>,
) -> DirectH2UploadGate {
    let Some(outcome) = outcome else {
        return DirectH2UploadGate::FailClosed;
    };
    match outcome {
        body::RequestBodyOutcome::Exceeded => DirectH2UploadGate::RequestBodyTooLarge,
        body::RequestBodyOutcome::Completed
        | body::RequestBodyOutcome::Errored
        | body::RequestBodyOutcome::Abandoned => DirectH2UploadGate::Forward,
    }
}

/// Later early-phase consumers must reuse one already-drained prebuffer rather
/// than starting (and deducting) a second fresh whole-upload timeout.
#[inline]
pub(crate) fn early_upload_phase_needs_fresh_drain(prebuffered_body: &Option<Vec<u8>>) -> bool {
    prebuffered_body.is_none()
}

impl From<RequestBodyWaitError> for RequestBodyBufferError {
    fn from(error: RequestBodyWaitError) -> Self {
        match error {
            RequestBodyWaitError::TimedOut => Self::TimedOut,
            RequestBodyWaitError::DeadlineExceeded => Self::DeadlineExceeded,
        }
    }
}

pub(crate) async fn collect_request_body_with_timeout<F, T, E>(
    collect: F,
    request_body_read_timeout_ms: u64,
) -> Result<Result<T, E>, RequestBodyWaitError>
where
    F: std::future::Future<Output = Result<T, E>>,
{
    if request_body_read_timeout_ms == 0 {
        return Ok(collect.await);
    }

    tokio::time::timeout(Duration::from_millis(request_body_read_timeout_ms), collect)
        .await
        .map_err(|_| RequestBodyWaitError::TimedOut)
}

pub(crate) async fn collect_request_body_with_deadline<F, T, E>(
    collect: F,
    deadline: Option<tokio::time::Instant>,
    request_body_read_timeout_ms: u64,
) -> Result<Result<T, E>, RequestBodyWaitError>
where
    F: std::future::Future<Output = Result<T, E>>,
{
    // The RPC deadline is an end-to-end ceiling, while the configured read
    // timeout remains the operator's client-upload stall guard. Keep both by
    // waiting only until the earlier instant; a very large grpc-timeout must
    // not disable the operator bound.
    match compose_early_upload_bound(deadline, request_body_read_timeout_ms) {
        Some((effective_deadline, EarlyUploadBoundKind::OperatorTimeout)) => {
            tokio::time::timeout_at(effective_deadline, collect)
                .await
                .map_err(|_| RequestBodyWaitError::TimedOut)
        }
        Some((effective_deadline, EarlyUploadBoundKind::RpcDeadline)) => {
            tokio::time::timeout_at(effective_deadline, collect)
                .await
                .map_err(|_| RequestBodyWaitError::DeadlineExceeded)
        }
        None => collect_request_body_with_timeout(collect, request_body_read_timeout_ms).await,
    }
}

pub(crate) fn request_may_have_body(method: &str, headers: &HashMap<String, String>) -> bool {
    !matches!(method, "GET" | "HEAD" | "OPTIONS")
        || headers.contains_key("content-length")
        || headers.contains_key("transfer-encoding")
}

pub(crate) fn http_flavor_allows_request_body_buffering(flavor: HttpFlavor) -> bool {
    !matches!(flavor, HttpFlavor::WebSocket)
}

async fn buffer_request_body_for_before_proxy(
    request: Request<Incoming>,
    method: &str,
    headers: &HashMap<String, String>,
    max_request_body_size_bytes: usize,
    request_body_read_timeout_ms: u64,
    grpc_deadline_at: Option<tokio::time::Instant>,
) -> Result<ClientRequestBody, RequestBodyBufferError> {
    // Keep the existing no-collection fast path only when the method/header
    // classification and the protocol body state agree that the request is
    // empty. In particular, an H2 GET/HEAD/OPTIONS request can omit
    // Content-Length while keeping the stream open for DATA, so method/header
    // heuristics alone must not infer an empty body.
    if !request_may_have_body(method, headers) && hyper::body::Body::is_end_stream(request.body()) {
        return Ok(ClientRequestBody::Streaming(Box::new(request)));
    }

    if max_request_body_size_bytes > 0
        && let Some(content_length) = headers.get("content-length")
        && let Ok(len) = content_length.parse::<usize>()
        && len > max_request_body_size_bytes
    {
        return Err(RequestBodyBufferError::TooLarge);
    }

    let (parts, body) = request.into_parts();
    let body_bytes = if max_request_body_size_bytes > 0 {
        let limited = http_body_util::Limited::new(body, max_request_body_size_bytes);
        let collected = collect_request_body_with_deadline(
            limited.collect(),
            grpc_deadline_at,
            request_body_read_timeout_ms,
        )
        .await?;
        collected
            .map_err(|e| {
                // Limited::collect() returns either a LengthLimitError (the body
                // actually exceeded the cap -> 413) or the underlying transport
                // error (the client dropped the connection mid-upload -> 499).
                // Distinguish them so a client disconnect is not misreported and
                // logged as "Request body exceeds maximum size", mirroring the
                // unlimited branch below.
                if e.downcast_ref::<http_body_util::LengthLimitError>()
                    .is_some()
                {
                    RequestBodyBufferError::TooLarge
                } else {
                    RequestBodyBufferError::ClientDisconnected(e.to_string())
                }
            })?
            .to_bytes()
            .to_vec()
    } else {
        let collected = collect_request_body_with_deadline(
            body.collect(),
            grpc_deadline_at,
            request_body_read_timeout_ms,
        )
        .await?;
        collected
            .map_err(|e| RequestBodyBufferError::ClientDisconnected(e.to_string()))?
            .to_bytes()
            .to_vec()
    };

    Ok(ClientRequestBody::Buffered(BufferedClientRequestBody {
        method: parts.method,
        headers: parts.headers,
        body: body_bytes,
    }))
}

pub(crate) fn store_request_body_metadata(
    ctx: &mut RequestContext,
    body: &[u8],
    needs_body_text: bool,
    needs_body_bytes: bool,
    needs_body_digests: bool,
) {
    ctx.metadata.insert(
        "request_body_size_bytes".to_string(),
        body.len().to_string(),
    );
    if needs_body_text && !ctx.metadata.contains_key("request_body") {
        if let Ok(body_str) = std::str::from_utf8(body) {
            ctx.metadata
                .insert("request_body".to_string(), body_str.to_string());
        } else {
            ctx.metadata.remove("request_body");
        }
    }
    // Allocate each representation only when an applicable plugin needs it.
    // Binary-only consumers (including OPA) therefore avoid retaining a
    // second full UTF-8 String alongside request_body_bytes.
    if needs_body_bytes && ctx.request_body_bytes.is_none() {
        ctx.request_body_bytes = Some(bytes::Bytes::copy_from_slice(body));
    }
    if needs_body_digests
        && (ctx.request_body_sha256.is_none() || ctx.request_body_sha512.is_none())
    {
        use sha2::{Digest, Sha256, Sha512};
        ctx.request_body_sha256 = Some(Sha256::digest(body).into());
        ctx.request_body_sha512 = Some(Sha512::digest(body).into());
    }
}

/// Refresh body-derived request views after an early normalization rewrite.
///
/// Digests are intentionally left untouched: authenticate may already have
/// verified integrity over the original wire bytes. Size/text/bytes views must
/// track the normalized plaintext so later `before_proxy` consumers (SOAP,
/// mirrors, etc.) inspect the same bytes the backend will receive.
pub(crate) fn refresh_request_body_views_after_normalization(
    ctx: &mut RequestContext,
    body: &[u8],
    needs_body_text: bool,
    needs_body_bytes: bool,
) {
    ctx.metadata.insert(
        "request_body_size_bytes".to_string(),
        body.len().to_string(),
    );
    if needs_body_bytes || ctx.request_body_bytes.is_some() {
        ctx.request_body_bytes = Some(bytes::Bytes::copy_from_slice(body));
    }
    if needs_body_text || ctx.metadata.contains_key("request_body") {
        if let Ok(body_str) = std::str::from_utf8(body) {
            ctx.metadata
                .insert("request_body".to_string(), body_str.to_string());
        } else {
            ctx.metadata.remove("request_body");
        }
    }
}

/// Run opt-in buffered-body normalizers after the pre-`before_proxy` buffer is
/// stored and before any `before_proxy` hook.
///
/// Configured request decompression lives here so earlier body consumers see
/// validated plaintext without each plugin reimplementing gzip/Brotli decode.
pub(crate) async fn apply_buffered_request_body_normalization_before_before_proxy(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    headers: &mut HashMap<String, String>,
    body: &mut Vec<u8>,
    needs_body_text: bool,
    needs_body_bytes: bool,
) -> PluginResult {
    let was_decoded = ctx
        .metadata
        .contains_key(crate::plugins::compression::REQUEST_DECODED_METADATA_KEY);
    for plugin in plugins {
        if !plugin.normalizes_buffered_request_body_before_before_proxy() {
            continue;
        }
        let deadline = ctx.grpc_deadline_at();
        match crate::plugins::await_request_plugin_deadline_with_provenance(
            deadline,
            plugin.normalize_buffered_request_body_before_before_proxy(ctx, headers, body),
        )
        .await
        .into_plugin_result(ctx)
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                return reject;
            }
        }
    }
    let body_was_rewritten = !was_decoded
        && ctx
            .metadata
            .contains_key(crate::plugins::compression::REQUEST_DECODED_METADATA_KEY);
    if body_was_rewritten {
        refresh_request_body_views_after_normalization(
            ctx,
            body,
            needs_body_text,
            needs_body_bytes,
        );
    }
    PluginResult::Continue
}

#[derive(Clone, Copy, Default)]
pub(crate) struct RequestBodyPhaseRequirements {
    pub required: bool,
    pub needs_text: bool,
    pub needs_bytes: bool,
    pub needs_digests: bool,
    pub plugin_limit: Option<usize>,
}

pub(crate) fn request_body_requirements_before_authorize(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
) -> RequestBodyPhaseRequirements {
    let mut requirements = RequestBodyPhaseRequirements::default();
    for plugin in plugins {
        if !plugin.requires_request_body_before_authorize()
            || !plugin.should_buffer_request_body(ctx)
        {
            continue;
        }
        requirements.required = true;
        requirements.needs_text |= plugin.needs_request_body_text();
        requirements.needs_bytes |= plugin.needs_request_body_bytes();
        requirements.needs_digests |= plugin.needs_request_body_digests();
        if let Some(limit) = plugin.request_body_buffer_limit() {
            requirements.plugin_limit = Some(
                requirements
                    .plugin_limit
                    .map_or(limit, |current| current.min(limit)),
            );
        }
    }
    requirements
}

pub(crate) fn request_body_requirements_before_before_proxy(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
) -> RequestBodyPhaseRequirements {
    let mut requirements = RequestBodyPhaseRequirements::default();
    for plugin in plugins {
        if !plugin.requires_request_body_before_before_proxy()
            || !plugin.should_buffer_request_body(ctx)
        {
            continue;
        }
        requirements.required = true;
        requirements.needs_text |= plugin.needs_request_body_text();
        requirements.needs_bytes |= plugin.needs_request_body_bytes();
        requirements.needs_digests |= plugin.needs_request_body_digests();
        if let Some(limit) = plugin.request_body_buffer_limit() {
            requirements.plugin_limit = Some(
                requirements
                    .plugin_limit
                    .map_or(limit, |current| current.min(limit)),
            );
        }
    }
    requirements
}

/// Resolve request-time body buffering and terminal-dispatch applicability.
///
/// Callers run this once against the client headers for phases that precede
/// `before_proxy`, then again against the effective header map when a plugin
/// transformed headers. This keeps a header transformer that exposes a JSON AI
/// request from accidentally bypassing terminal federation dispatch.
pub(crate) fn final_request_body_requirements(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    request_may_need_buffering: bool,
    has_terminal_body_dispatch: bool,
    has_contextual_final_body_hook: bool,
) -> (bool, bool, bool) {
    if request_may_need_buffering && (has_terminal_body_dispatch || has_contextual_final_body_hook)
    {
        let mut requires_buffering = false;
        let mut terminal_dispatch = false;
        let mut needs_final_context = false;
        for plugin in plugins {
            if plugin.should_buffer_request_body(ctx) {
                requires_buffering = true;
                terminal_dispatch |= plugin.requires_final_request_body_before_backend_dispatch();
                needs_final_context |= plugin.needs_final_request_body_context();
            }
        }
        (requires_buffering, terminal_dispatch, needs_final_context)
    } else if request_may_need_buffering {
        (
            plugins
                .iter()
                .any(|plugin| plugin.should_buffer_request_body(ctx)),
            false,
            false,
        )
    } else {
        (false, false, false)
    }
}

pub(crate) fn request_body_requirements_before_authenticate(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    consumer_index: &ConsumerIndex,
) -> RequestBodyPhaseRequirements {
    let mut requirements = RequestBodyPhaseRequirements::default();
    for plugin in plugins {
        if !plugin.requires_request_body_before_authenticate()
            || !plugin.should_buffer_request_body_before_authenticate(ctx, consumer_index)
        {
            continue;
        }
        requirements.required = true;
        requirements.needs_text |= plugin.needs_request_body_text();
        requirements.needs_bytes |= plugin.needs_request_body_bytes();
        requirements.needs_digests |= plugin.needs_request_body_digests();
        if let Some(limit) = plugin.request_body_buffer_limit() {
            requirements.plugin_limit = Some(
                requirements
                    .plugin_limit
                    .map_or(limit, |current| current.min(limit)),
            );
        }
    }
    requirements
}

pub(crate) fn effective_request_body_limit(
    global_limit: usize,
    plugin_limit: Option<usize>,
) -> usize {
    match (global_limit, plugin_limit) {
        (0, Some(plugin_limit)) => plugin_limit,
        (global_limit, Some(plugin_limit)) => global_limit.min(plugin_limit),
        (global_limit, None) => global_limit,
    }
}

/// Select the protocol receive ceiling before composing a plugin-local body
/// cap. Native gRPC must use `FERRUM_MAX_GRPC_RECV_SIZE_BYTES` in every early
/// buffering phase; applying only the ordinary HTTP body ceiling would let an
/// auth or before-proxy prebuffer bypass the gRPC limit before dispatch.
pub(crate) fn effective_request_body_limit_for_protocol(
    is_grpc_request: bool,
    http_limit: usize,
    grpc_limit: usize,
    plugin_limit: Option<usize>,
) -> usize {
    effective_request_body_limit(
        if is_grpc_request {
            grpc_limit
        } else {
            http_limit
        },
        plugin_limit,
    )
}

pub(crate) fn redact_request_body_from_log_metadata(metadata: &mut HashMap<String, String>) {
    metadata.remove("request_body");
    metadata.remove(ORIGINAL_RESPONSE_METADATA_STAMPED_KEY);
    metadata.remove(ORIGINAL_RESPONSE_CONTENT_TYPE_METADATA_KEY);
    metadata.remove(ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY);
    metadata.remove(ORIGIN_ENCODED_RESPONSE_METADATA_KEY);
    metadata.remove(ORIGIN_FRAGMENT_RESPONSE_METADATA_KEY);
    // ai_tool_governor uses these request-scoped markers to select the
    // inspectable streaming path and seed approval correlation. They are
    // lifecycle bookkeeping, not observability metadata, and must never make
    // `observability.emit_metadata: false` ineffective.
    metadata.remove(crate::plugins::ai_tool_governor::STREAM_REQUESTED_KEY);
    metadata.remove(crate::plugins::ai_tool_governor::STREAM_MODEL_KEY);
    crate::plugins::ai_transcript_audit::redact_internal_log_metadata(metadata);
    // SSE Last-Event-ID is origin-defined resume state: omit the raw value from
    // transaction logs and retain only safe present/length correlation hints.
    crate::plugins::sse::redact_sse_log_metadata(metadata);
    crate::plugins::mcp_gateway::redact_internal_log_metadata(metadata);
}

pub(crate) fn clone_log_metadata(ctx: &RequestContext) -> HashMap<String, String> {
    let mut metadata = ctx.metadata.clone();
    ctx.project_correlation_ids(&mut metadata);
    redact_request_body_from_log_metadata(&mut metadata);
    ctx.apply_waf_owned_log_metadata(&mut metadata);
    metadata
}

/// Parse an HTTP method string into a `hyper::Method`.
fn parse_hyper_method(method: &str) -> Result<hyper::Method, ()> {
    match method {
        "GET" => Ok(hyper::Method::GET),
        "POST" => Ok(hyper::Method::POST),
        "PUT" => Ok(hyper::Method::PUT),
        "DELETE" => Ok(hyper::Method::DELETE),
        "PATCH" => Ok(hyper::Method::PATCH),
        "HEAD" => Ok(hyper::Method::HEAD),
        "OPTIONS" => Ok(hyper::Method::OPTIONS),
        other => hyper::Method::from_bytes(other.as_bytes()).map_err(|_| ()),
    }
}

fn warn_invalid_backend_method(proxy_id: &str, backend_path: &'static str, method: &str) {
    warn!(
        proxy_id = %proxy_id,
        backend_path,
        method_len = method.len(),
        "Invalid HTTP method for backend dispatch"
    );
}

fn insert_outbound_header_or_warn(
    headers: &mut hyper::HeaderMap,
    proxy_id: &str,
    backend_path: &'static str,
    source: &'static str,
    name: &str,
    value: &str,
) {
    let header_name = match hyper::header::HeaderName::from_bytes(name.as_bytes()) {
        Ok(name) => name,
        Err(e) => {
            warn!(
                proxy_id = %proxy_id,
                backend_path,
                source,
                header_name_len = name.len(),
                reason = "invalid_name",
                error = %e,
                "Dropped invalid outbound header"
            );
            return;
        }
    };
    let header_value = match hyper::header::HeaderValue::from_str(value) {
        Ok(value) => value,
        Err(e) => {
            warn!(
                proxy_id = %proxy_id,
                backend_path,
                source,
                header_name = %header_name,
                reason = "invalid_value",
                error = %e,
                "Dropped invalid outbound header"
            );
            return;
        }
    };
    headers.insert(header_name, header_value);
}

/// Build the outbound X-Forwarded-For header value.
///
/// Standard `proxy_add_x_forwarded_for` semantics: append the immediate
/// socket peer (`peer_ip`) to the inbound chain. When there is no inbound
/// chain but trusted-proxy resolution produced a real client IP that differs
/// from the peer (e.g. `FERRUM_REAL_IP_HEADER` from a trusted LB that does
/// not send XFF), seed the generated chain with the resolved client so the
/// real client is not lost.
///
/// Trust gate: when `FERRUM_TRUSTED_PROXIES` is configured and the immediate
/// peer is NOT in it, the inbound XFF is attacker-controlled and is dropped —
/// the same rule `client_ip::resolve_client_ip` applies when resolving
/// `ctx.client_ip`. Forwarding it (`spoofed, peer`) would hand backends an
/// attacker-seeded chain the gateway itself refused to trust. With no
/// trusted-proxy policy configured, the inbound chain passes through
/// untouched (transparent nginx-style behavior).
///
/// Truth table (identical across H1/H2/H3 frontends):
///
/// | Deployment shape                   | inbound XFF | client vs peer | outbound XFF          |
/// |------------------------------------|-------------|----------------|-----------------------|
/// | no proxy in front                  | none        | equal          | `peer`                |
/// | trusted LB sending XFF             | `…, client` | differ         | `…, client, peer`     |
/// | trusted LB sending real-IP header  | none        | differ         | `client, peer`        |
/// | real-IP header + passthrough XFF   | `…` (no client) | differ     | `…, client, peer`     |
/// | untrusted peer (spoofed XFF)       | dropped     | equal          | `peer`                |
///
/// When inbound XFF exists the resolved client is already in the chain, so
/// only the peer is appended — never the resolved client (which would
/// duplicate it; see issue #1571).
///
/// Uses pre-allocated buffers instead of `format!()` to avoid format
/// machinery overhead.
pub(crate) fn build_xff_value(
    existing_xff: Option<&str>,
    client_ip: &str,
    peer_ip: &str,
    trusted_proxies: &client_ip::TrustedProxies,
) -> String {
    // Drop attacker-controlled inbound XFF: a trust policy exists and the
    // immediate peer is not part of it. The peer-IP parse only runs when an
    // inbound chain is present AND a policy is configured.
    let existing_xff = existing_xff.filter(|_| {
        trusted_proxies.is_empty()
            || peer_ip
                .parse::<std::net::IpAddr>()
                .map(|ip| trusted_proxies.contains(&ip))
                .unwrap_or(false)
    });
    match existing_xff {
        Some(xff) => {
            // Real-IP-header deployments: a trusted proxy can resolve the
            // client via `FERRUM_REAL_IP_HEADER` while ALSO forwarding an XFF
            // chain that does not contain that client (e.g. a client-supplied
            // chain it passed through verbatim). Resolution ignored the chain
            // in favor of the real-IP header, so the authenticated client
            // must be seeded before the peer or backends consuming XFF lose
            // it entirely. When resolution walked the chain itself the client
            // is already present and only the peer is appended.
            let seed_client = client_ip != peer_ip && !xff_chain_contains(xff, client_ip);
            let mut val =
                String::with_capacity(xff.len() + 2 + client_ip.len() + 2 + peer_ip.len());
            val.push_str(xff);
            val.push_str(", ");
            if seed_client {
                val.push_str(client_ip);
                val.push_str(", ");
            }
            val.push_str(peer_ip);
            val
        }
        None if client_ip != peer_ip => {
            let mut val = String::with_capacity(client_ip.len() + 2 + peer_ip.len());
            val.push_str(client_ip);
            val.push_str(", ");
            val.push_str(peer_ip);
            val
        }
        None => peer_ip.to_string(),
    }
}

/// True when `chain` (a comma-separated XFF value) already lists `client_ip`.
/// Compares both textually and by parsed `IpAddr` so canonicalization
/// differences (case, IPv6 zero-compression) don't produce duplicates.
fn xff_chain_contains(chain: &str, client_ip: &str) -> bool {
    let client_addr: Option<IpAddr> = client_ip.parse().ok();
    chain.split(',').any(|entry| {
        let entry = entry.trim();
        entry == client_ip || (client_addr.is_some() && entry.parse::<IpAddr>().ok() == client_addr)
    })
}

/// RAII guard that decrements the per-IP concurrent request counter on drop.
/// Created after client IP resolution; guarantees decrement on every exit path
/// (including early returns and panics).
pub struct PerIpRequestGuard {
    pub ip: String,
    pub counts: Arc<dashmap::DashMap<String, AtomicU64>>,
}

impl Drop for PerIpRequestGuard {
    fn drop(&mut self) {
        if let Some(entry) = self.counts.get(&self.ip) {
            entry.value().fetch_sub(1, Ordering::Relaxed);
        }
    }
}

/// RAII guard for load-balancer connection accounting on upgraded sessions.
///
/// WebSocket proxying runs in a spawned task after the HTTP handler returns.
/// Keeping the accounting in a guard makes the end event fire on normal close,
/// upgrade failure, task cancellation, or panic unwind.
pub(crate) struct LoadBalancerConnectionGuard {
    target: Option<Arc<UpstreamTarget>>,
    balancer: Option<Arc<LoadBalancer>>,
}

impl LoadBalancerConnectionGuard {
    pub(crate) fn new(
        target: Option<Arc<UpstreamTarget>>,
        balancer: Option<Arc<LoadBalancer>>,
    ) -> Self {
        if let (Some(target), Some(balancer)) = (target.as_ref(), balancer.as_ref()) {
            balancer.record_connection_start(target);
        }
        Self { target, balancer }
    }
}

impl Drop for LoadBalancerConnectionGuard {
    fn drop(&mut self) {
        if let (Some(target), Some(balancer)) = (self.target.as_ref(), self.balancer.as_ref()) {
            balancer.record_connection_end(target);
        }
    }
}

/// RAII guard that releases a half-open circuit-breaker probe slot on drop
/// unless an explicit outcome was recorded first (`disarm`).
///
/// The gRPC dispatch block has many early-return paths (plugin rejects,
/// body-too-large, internal errors) reached AFTER `check_circuit_breaker` may
/// have admitted a HALF_OPEN probe. The gRPC path historically recorded no
/// outcome on those paths, leaking the probe slot and wedging the breaker. On
/// such early returns this guard records a NEUTRAL outcome (a gateway-side
/// decision is neither a backend success nor failure), releasing the slot
/// without changing breaker health. The success/failure paths disarm it and
/// record the real outcome instead.
struct GrpcProbeReleaseGuard {
    cb: Option<Arc<crate::circuit_breaker::CircuitBreaker>>,
    armed: bool,
}

impl GrpcProbeReleaseGuard {
    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for GrpcProbeReleaseGuard {
    fn drop(&mut self) {
        if self.armed
            && let Some(cb) = &self.cb
        {
            cb.record_neutral(true);
        }
    }
}

/// Record a gRPC backend outcome to the circuit breaker, classified by the
/// backend's HTTP status (mirrors the HTTP path). gRPC application errors ride
/// as `grpc-status` trailers over HTTP 200 (not a transport failure), so a
/// status outside `failure_status_codes` is a success that advances HALF_OPEN
/// recovery; only a genuine HTTP failure status (e.g. a sandwiched LB /
/// overloaded backend 5xx) trips the breaker. `record_failure` with a
/// non-failure status only releases the probe slot, so it cannot stand in for
/// `record_success` on a 2xx HALF_OPEN probe.
fn record_grpc_backend_status_outcome(
    cb: &crate::circuit_breaker::CircuitBreaker,
    backend_status: u16,
    is_half_open_probe: bool,
) {
    if cb.config().failure_status_codes.contains(&backend_status) {
        cb.record_failure(backend_status, false, is_half_open_probe);
    } else {
        cb.record_success(is_half_open_probe);
    }
}

#[allow(clippy::too_many_arguments)]
fn record_grpc_backend_dispatch_outcome(
    state: &ProxyState,
    proxy: &Proxy,
    lb_snapshot: &LoadBalancerCacheInner,
    selected_balancer: Option<&Arc<LoadBalancer>>,
    upstream_target: Option<&Arc<UpstreamTarget>>,
    final_cb_target_key: Option<&str>,
    response_status: u16,
    connection_error: bool,
    error_class: Option<retry::ErrorClass>,
    backend_elapsed: Duration,
) {
    backend_dispatch::record_backend_outcome_no_conn_end(
        state,
        proxy,
        lb_snapshot,
        selected_balancer,
        upstream_target.map(Arc::as_ref),
        final_cb_target_key,
        response_status,
        connection_error,
        error_class,
        false,
        true,
        backend_elapsed,
    );
}

/// Load a gRPC streaming late client-upload overflow flag with `Acquire`
/// ordering, pairing with the `Release` store in
/// `GrpcBody::Streaming::poll_frame`. A `None` flag (no request-body limit
/// configured) reads as `false`. Takes the flag field directly rather than
/// `&GrpcStreamingResponse` so callers can read it after `headers`/`body` have
/// been moved out of the response. Point-in-time read: for bidi/client-streaming
/// RPCs the flag can still flip `true` afterward as request frames keep
/// uploading concurrently with the response body.
fn grpc_request_body_limit_exceeded(flag: &Option<Arc<std::sync::atomic::AtomicBool>>) -> bool {
    flag.as_ref().is_some_and(|f| f.load(Ordering::Acquire))
}

/// Whether `status` is a no-body response status (`204 No Content` /
/// `304 Not Modified`) whose body is suppressed regardless of the backend
/// stream's `END_STREAM` state — RFC 7230 §3.3.3 / RFC 7232 §4.1. Same statuses
/// the canonical [`crate::http3::client::is_response_body_complete`] no-body
/// predicate uses (minus the method-side `HEAD` check, handled separately).
fn response_is_no_body_status(status: u16) -> bool {
    status == 204 || status == 304
}

/// Whether a streaming response's backend-dispatch outcome (CB / passive-health /
/// least-latency) should be DEFERRED to body completion rather than recorded at
/// response-header time (#1649 items 2 & 3).
///
/// Defer a response whose header-time status is not already a configured
/// failure/unhealthy signal AND has an open body that can still fail post-wire —
/// i.e. any `< 500` status (not a configured CB `failure_status_codes` and not
/// passively unhealthy) whose body is NOT already end-of-stream. Everything else
/// is header-time-final and must be recorded eagerly:
///   * **5xx / configured failures** (including a passive `unhealthy_status_codes`
///     entry like `429` or a CB failure status): the outcome is known now, so
///     trip the breaker / report passive health promptly instead of waiting for a
///     possibly long-lived/stalled body. Deferring streamable non-failure 3xx/4xx
///     responses preserves post-wire body timeout/reset accounting instead of
///     banking a header-time success before the body can fail.
///   * **Already-ended body** (`is_end_stream()` — empty `200`, gRPC
///     Trailers-Only, `content-length: 0`) OR a **no-body status / HEAD request**
///     (a `204`/`304` response or a `HEAD` request suppresses the body regardless
///     of the backend stream's `END_STREAM` state at header time — RFC 7230 §3.3.3
///     / RFC 7232 §4.1): nothing streams to the client, so a deferred outcome would
///     be misread as a client disconnect by the never-polled `ProxyBody::Drop` path
///     (`src/proxy/body.rs`) and a successful no-body probe would never heal a
///     HALF_OPEN breaker. A backend that emits a `304`/`204` header frame WITHOUT
///     `END_STREAM` would otherwise slip past the `is_end_stream()` guard and into
///     the deferred path (the `< 500` predicate admits it), so gate on the status
///     explicitly here as well (#1649 R7 finding 1, R8 304 no-body finding).
///   * **Passively-unhealthy status** (`status_is_passively_unhealthy`): an
///     operator may list an otherwise streamable status (e.g. `206`/`299`/`429`)
///     in the target's resolved passive `unhealthy_status_codes`. That header is
///     already a configured unhealthy outcome, so report it eagerly instead of
///     leaving the target in rotation until a long-lived/stalled body terminates
///     (#1649 R7 finding 3).
fn streaming_dispatch_should_defer(
    proxy: &Proxy,
    response_status: u16,
    body_already_ended: bool,
    request_is_head: bool,
    status_is_passively_unhealthy: bool,
) -> bool {
    // A `204`/`304` response carries no body regardless of whether the backend
    // set `END_STREAM` on its header frame, so it must never be deferred — hyper
    // may never poll the body, and `ProxyBody::Drop` would then record the
    // never-polled streaming body as a client disconnect, dropping the header-time
    // success and preventing a HALF_OPEN breaker from healing on cache-validation
    // traffic. Mirrors the `HEAD` body-suppression case and the canonical no-body
    // predicate in `http3::client::is_response_body_complete`.
    if body_already_ended || request_is_head || response_is_no_body_status(response_status) {
        return false;
    }
    response_status < 500
        && !proxy
            .circuit_breaker
            .as_ref()
            .is_some_and(|cb| cb.failure_status_codes.contains(&response_status))
        && !status_is_passively_unhealthy
}

fn grpc_streaming_dispatch_should_defer(
    proxy: &Proxy,
    response_status: u16,
    body_already_ended: bool,
) -> bool {
    // gRPC streaming terminal failures are classified at response-body
    // completion (including reset/timeout/trailer-derived backend failures).
    // Do not apply the passive-unhealthy-2xx eager shortcut here: the gRPC eager
    // branch records only the HTTP status to the circuit breaker and then skips
    // terminal CB accounting, so a passive-only unhealthy 2xx could otherwise be
    // banked as success and mask the real stream failure.
    streaming_dispatch_should_defer(proxy, response_status, body_already_ended, false, false)
}

/// Whether `response_status` is in the dispatched target's effective passive
/// `unhealthy_status_codes`, resolved with the SAME precedence as the
/// passive-health reporter ([`backend_dispatch::passive_health_for_target`]) so
/// the header-time eager-vs-defer decision and the eventual passive-health report
/// agree (#1649 R7 finding 3). Returns false for direct-backend proxies (no
/// upstream) or when no passive health is configured.
fn streaming_response_status_is_passively_unhealthy(
    lb_snapshot: &crate::load_balancer::LoadBalancerCacheInner,
    proxy: &Proxy,
    target: Option<&UpstreamTarget>,
    response_status: u16,
) -> bool {
    let (Some(upstream_id), Some(target)) = (proxy.upstream_id.as_deref(), target) else {
        return false;
    };
    let Some(upstream) =
        crate::load_balancer::LoadBalancerCache::get_upstream_from(lb_snapshot, upstream_id)
    else {
        return false;
    };
    backend_dispatch::passive_health_for_target(proxy, &upstream, target)
        .is_some_and(|passive| passive.unhealthy_status_codes.contains(&response_status))
}

fn h3_success_on_drop_after_response_bytes(
    inbound_version: hyper::Version,
    content_length: Option<u64>,
) -> Option<u64> {
    if matches!(
        inbound_version,
        hyper::Version::HTTP_10 | hyper::Version::HTTP_11
    ) {
        content_length
    } else {
        None
    }
}

/// Owns the gRPC **streaming** circuit-breaker outcome, settling it at the join of
/// request-upload termination and response-body completion so a streaming RPC is
/// classified correctly without pinning a HALF_OPEN probe slot (#1649 item 3,
/// building on the #1640 upload-termination machinery).
///
/// A streaming RPC has three signals that arrive at different times: the response
/// can send `2xx` headers then stall / reset / carry a non-OK `grpc-status`
/// trailer (response-body completion), the client upload can overflow
/// `max_grpc_recv_size_bytes` at any point (the shared `request_body_exceeded`
/// flag), and either of upload or response can finish first (bidi /
/// client-streaming). The recorder reconciles them:
///
///  * **Probe-slot release** (HALF_OPEN only) happens at the join of
///    `headers_seen` + `upload_terminated` (or the post-header upload guard) —
///    the #1640 timing, so the single slot is freed as soon as the upload ends
///    and never pinned for a long-lived response stream. It is a NEUTRAL release
///    (`record_neutral`), decoupled from the health outcome.
///  * **A backend FAILURE** (post-wire body error / non-OK grpc-status trailer)
///    is recorded as soon as the response terminates — a real failure should trip
///    promptly and need not wait for the upload — UNLESS the client upload
///    already overflowed (client-side → NEUTRAL).
///  * **A clean SUCCESS** is deferred until upload termination so the overflow
///    flag is final: a backend can legally complete `200`/`grpc-status: 0` before
///    the client finishes uploading, and a late overflow must not be able to
///    falsely heal a HALF_OPEN breaker.
///
/// `health_recorded` is a single exactly-once CAS shared by every settle path
/// (eager known-failure record at header time via `mark_health_recorded`, the
/// prompt-failure path, the clean-success join, and the post-header guard's
/// NEUTRAL fallback). The response outcome is delivered by
/// [`body::GrpcResponseTerminalObserver`]; upload termination by
/// [`grpc_proxy::GrpcUploadTerminationObserver`].
struct GrpcStreamingProbeRecorder {
    cb: Arc<crate::circuit_breaker::CircuitBreaker>,
    is_half_open_probe: bool,
    /// Shared with `GrpcBody::Streaming.exceeded`: a late client-upload overflow.
    /// Re-read at every settle point so an overflow that trips after a clean
    /// response is still classified NEUTRAL.
    request_body_exceeded: Arc<std::sync::atomic::AtomicBool>,
    headers_seen: std::sync::atomic::AtomicBool,
    upload_terminated: std::sync::atomic::AtomicBool,
    /// Set when the response body terminated CLEAN (no failure outcome). The
    /// clean success is then recorded at the upload-termination join.
    response_clean: std::sync::atomic::AtomicBool,
    /// The clean response's effective status (grpc-trailer-mapped), captured for
    /// the deferred clean-success record.
    clean_response_status: std::sync::atomic::AtomicU16,
    /// HALF_OPEN probe-slot release (NEUTRAL), exactly-once.
    slot_released: std::sync::atomic::AtomicBool,
    /// Backend-health outcome (success / failure / neutral), exactly-once across
    /// all settle paths.
    health_recorded: std::sync::atomic::AtomicBool,
    /// Set when the post-header upload guard expired while the response was still
    /// streaming (#1649 R5 finding 5). A clean completion that arrives AFTER the
    /// upload missed its deadline must settle NEUTRAL rather than heal — the
    /// upload's late termination can't be trusted to confirm a HALF_OPEN probe.
    /// A backend FAILURE after expiry is unaffected (it records promptly via
    /// `on_response_terminal`, not the clean-success join).
    upload_guard_expired: std::sync::atomic::AtomicBool,
    /// Post-header upload guard window in milliseconds, or `None` when no guard
    /// applies. Measured from response-header arrival (in
    /// `start_post_header_upload_timeout`), not dispatch start, so a slow-header
    /// backend does not consume the window.
    post_header_upload_timeout_ms: Option<u64>,
    /// The breaker's open generation captured at admission. The settled outcome
    /// is recorded NEUTRAL if the breaker has since opened a new cycle (#1649
    /// round-4 B) so a stream admitted under one generation cannot heal/reopen a
    /// later HALF_OPEN cycle it never probed.
    admission_open_epoch: u64,
}

impl GrpcStreamingProbeRecorder {
    fn new(
        cb: Arc<crate::circuit_breaker::CircuitBreaker>,
        is_half_open_probe: bool,
        request_body_exceeded: Arc<std::sync::atomic::AtomicBool>,
        post_header_upload_timeout_ms: Option<u64>,
        admission_open_epoch: u64,
    ) -> Self {
        Self {
            cb,
            is_half_open_probe,
            request_body_exceeded,
            headers_seen: std::sync::atomic::AtomicBool::new(false),
            upload_terminated: std::sync::atomic::AtomicBool::new(false),
            response_clean: std::sync::atomic::AtomicBool::new(false),
            clean_response_status: std::sync::atomic::AtomicU16::new(0),
            slot_released: std::sync::atomic::AtomicBool::new(false),
            health_recorded: std::sync::atomic::AtomicBool::new(false),
            upload_guard_expired: std::sync::atomic::AtomicBool::new(false),
            post_header_upload_timeout_ms,
            admission_open_epoch,
        }
    }

    /// Activate the recorder once response headers are known. Settles the probe
    /// slot / clean success if their other join input is already present, and
    /// starts the post-header upload guard.
    fn note_headers_arrived(self: &Arc<Self>) {
        self.headers_seen.store(true, Ordering::Release);
        self.start_post_header_upload_timeout();
        self.try_release_slot();
        self.try_record_clean_success();
    }

    /// Mark the breaker outcome as already recorded (used by the eager
    /// known-failure-status header-time path) so no settle path double-records.
    fn mark_health_recorded(&self) {
        self.health_recorded.store(true, Ordering::Release);
    }

    /// Release the HALF_OPEN probe slot (NEUTRAL) at the join of headers + upload
    /// termination, exactly once. Decoupled from the health outcome.
    fn try_release_slot(&self) {
        if !self.is_half_open_probe {
            return;
        }
        if !self.headers_seen.load(Ordering::Acquire)
            || !self.upload_terminated.load(Ordering::Acquire)
        {
            return;
        }
        if self.slot_released.swap(true, Ordering::AcqRel) {
            return;
        }
        self.cb.record_neutral(true);
    }

    /// Record a clean SUCCESS at the join of a clean response + upload
    /// termination, re-checking the overflow flag (a late overflow → NEUTRAL).
    fn try_record_clean_success(&self) {
        if !self.response_clean.load(Ordering::Acquire)
            || !self.upload_terminated.load(Ordering::Acquire)
        {
            return;
        }
        if self.request_body_exceeded.load(Ordering::Acquire) {
            // Late client-upload overflow after a clean response → NEUTRAL.
            self.health_recorded.store(true, Ordering::Release);
            return;
        }
        if self.upload_guard_expired.load(Ordering::Acquire) {
            // #1649 R5 finding 5: the post-header upload guard already expired while
            // the response was still streaming. The upload missed its deadline, so
            // this late clean completion (clean trailers + an eventual upload
            // termination) must NOT heal the breaker — settle NEUTRAL.
            self.health_recorded.store(true, Ordering::Release);
            return;
        }
        if self.health_recorded.swap(true, Ordering::AcqRel) {
            return;
        }
        backend_dispatch::apply_deferred_circuit_breaker_outcome(
            &self.cb,
            self.clean_response_status.load(Ordering::Acquire),
            false,
            None,
            false,
            self.admission_open_epoch,
        );
    }

    fn start_post_header_upload_timeout(self: &Arc<Self>) {
        let Some(timeout_ms) = self.post_header_upload_timeout_ms else {
            return;
        };
        if self.upload_terminated.load(Ordering::Acquire) {
            return;
        }
        let Some(timeout) = grpc_post_header_upload_guard_duration(timeout_ms) else {
            self.settle_neutral_if_upload_still_open();
            return;
        };
        let recorder = Arc::clone(self);
        std::mem::drop(tokio::spawn(async move {
            tokio::time::sleep(timeout).await;
            recorder.settle_neutral_if_upload_still_open();
        }));
    }

    /// Post-header upload guard: if the upload has not terminated by the deadline,
    /// release the probe slot and settle the health outcome NEUTRAL. A clean
    /// success cannot be confirmed without upload termination (overflow check),
    /// and any backend FAILURE already recorded health promptly (so the
    /// `health_recorded` CAS no-ops here).
    fn settle_neutral_if_upload_still_open(&self) {
        if !self.headers_seen.load(Ordering::Acquire) {
            return;
        }
        if self.upload_terminated.load(Ordering::Acquire) {
            return;
        }
        // #1649 R5 finding 5: remember the guard expired with the upload still
        // open. If the backend LATER sends clean trailers and the client upload
        // eventually terminates, `try_record_clean_success` must settle NEUTRAL
        // instead of healing on that stale timing. Set before the slot release so
        // any concurrent upload-termination join observes it.
        self.upload_guard_expired.store(true, Ordering::Release);
        // Release the slot the unended upload is pinning (NEUTRAL), once.
        if self.is_half_open_probe && !self.slot_released.swap(true, Ordering::AcqRel) {
            self.cb.record_neutral(true);
        }
        // #1649 round-4 finding A: only CONSUME the health outcome when the
        // response already completed CLEAN — that clean success cannot be
        // confirmed without upload termination (overflow check), so it settles
        // NEUTRAL. If the response has NOT terminated, do NOT mark health here:
        // a still-streaming response may yet FAIL (a 2xx-then-stall), and that
        // failure — recorded promptly by `on_response_terminal` — must not be
        // masked by an unended-upload guard (this guard now runs for every
        // streaming RPC with a breaker, not just HALF_OPEN probes).
        if self.response_clean.load(Ordering::Acquire)
            && !self.health_recorded.swap(true, Ordering::AcqRel)
        {
            warn!(
                "gRPC streaming probe upload did not terminate before its deadline; settling clean response neutral",
            );
        }
    }
}

impl crate::proxy::grpc_proxy::GrpcUploadTerminationObserver for GrpcStreamingProbeRecorder {
    fn on_upload_terminated(&self) {
        self.upload_terminated.store(true, Ordering::Release);
        self.try_release_slot();
        self.try_record_clean_success();
    }
}

impl crate::proxy::body::GrpcResponseTerminalObserver for GrpcStreamingProbeRecorder {
    fn on_response_terminal(
        &self,
        response_status: u16,
        connection_error: bool,
        error_class: Option<retry::ErrorClass>,
    ) {
        // A client-upload overflow (set before/at the terminating reset) is a
        // client-side size violation → NEUTRAL, never a backend failure.
        if self.request_body_exceeded.load(Ordering::Acquire) {
            self.health_recorded.store(true, Ordering::Release);
            return;
        }
        // #1649 R5 finding 4: a client-side terminal (downstream disconnect /
        // request-body-too-large) carries NO backend health signal → settle
        // NEUTRAL. `circuit_breaker_outcome_is_failure` returns false for these
        // classes, so without this guard the clean branch below would bank a
        // phantom SUCCESS — and a client that cancels a stream during HALF_OPEN
        // could then falsely heal an unhealthy backend (or reset closed-state
        // failures). The probe slot is still released via the headers+upload-term
        // join / guard; only the health outcome is consumed here.
        if backend_dispatch::client_side_no_backend_signal(error_class) {
            self.health_recorded.store(true, Ordering::Release);
            return;
        }
        if backend_dispatch::circuit_breaker_outcome_is_failure(
            &self.cb.config().failure_status_codes,
            response_status,
            connection_error,
            error_class,
        ) {
            // A real backend failure (post-wire body error / non-OK grpc-status
            // trailer) trips promptly — no need to wait for upload termination.
            // Still epoch-checked: a stream admitted before a new open cycle must
            // not reopen a later HALF_OPEN cycle it never probed (round-4 B).
            if !self.health_recorded.swap(true, Ordering::AcqRel) {
                backend_dispatch::apply_deferred_circuit_breaker_outcome(
                    &self.cb,
                    response_status,
                    connection_error,
                    error_class,
                    false,
                    self.admission_open_epoch,
                );
            }
            return;
        }
        // Clean response: defer the SUCCESS to upload termination so a late
        // overflow can't falsely heal the breaker.
        self.clean_response_status
            .store(response_status, Ordering::Release);
        self.response_clean.store(true, Ordering::Release);
        self.try_record_clean_success();
    }
}

// A multi-year client grpc-timeout is functionally unbounded for a HALF_OPEN
// probe slot and can exceed Tokio timer internals on some platforms. Treat
// anything larger as elapsed so the guard records NEUTRAL instead of spawning an
// unenforceable timer.
const MAX_GRPC_POST_HEADER_UPLOAD_GUARD_MS: u64 = 2 * 365 * 24 * 60 * 60 * 1_000;

fn grpc_post_header_upload_guard_duration(timeout_ms: u64) -> Option<Duration> {
    if timeout_ms > MAX_GRPC_POST_HEADER_UPLOAD_GUARD_MS {
        return None;
    }
    Some(Duration::from_millis(timeout_ms))
}

/// Finalize a gRPC streaming probe's circuit-breaker outcome once the response
/// headers are known, before response hooks run.
///
/// #1649 item 3: the streaming probe's backend-health outcome is no longer
/// recorded here — it is deferred to response-**body** completion via the
/// streaming body's `with_deferred_backend_dispatch_outcome` (as a non-probe),
/// so a `2xx`-then-stall / mid-stream reset / non-OK grpc-status trailer is
/// recorded as the failure it is instead of a phantom header-time success. This
/// function only settles the HALF_OPEN **probe slot**: with a deferred `recorder`
/// (a HALF_OPEN probe on the fully-streaming fast path) the eager probe guard is
/// disarmed and slot release is handed to [`GrpcStreamingProbeRecorder`], which
/// frees the slot (NEUTRAL) at request-upload termination (or when the
/// post-header upload guard expires). Without one (buffered-request streaming
/// path, or a CLOSED-state non-probe request) there is no probe slot to settle
/// here and the outcome is recorded solely at body completion.
fn finalize_grpc_streaming_probe_outcome(
    recorder: Option<&Arc<GrpcStreamingProbeRecorder>>,
    probe_guard: &mut GrpcProbeReleaseGuard,
) {
    if let Some(recorder) = recorder {
        // The recorder owns the probe-slot release (NEUTRAL at upload
        // termination, or when the post-header upload guard expires), so disarm
        // the eager guard to avoid a double release.
        probe_guard.disarm();
        recorder.note_headers_arrived();
    }
}

/// Build RFC 7239 Forwarded header value.
/// IPv6 addresses are quoted per RFC 7239 §6.
/// Writes directly into a single pre-allocated buffer to avoid intermediate
/// `format!()` String allocations.
pub fn build_forwarded_value(client_ip: &str, proto: &str, host: Option<&str>) -> String {
    let mut val = String::with_capacity(64);
    // Quote IPv6 addresses: for="[2001:db8::1]"
    if client_ip.contains(':') {
        val.push_str("for=\"[");
        val.push_str(client_ip);
        val.push_str("]\"");
    } else {
        val.push_str("for=");
        val.push_str(client_ip);
    }
    val.push_str(";proto=");
    val.push_str(proto);
    if let Some(h) = host {
        val.push_str(";host=");
        push_forwarded_param_value(&mut val, h);
    }
    val
}

/// Replace proxy-managed scheme metadata with the effective browser-facing
/// request scheme. Direct gRPC and WebSocket dispatch start from a sanitized
/// request map instead of the canonical HTTP backend builders, so normalize
/// these fields before those protocol-specific paths merge or forward it.
/// Remove every case-insensitive variant first because this string-keyed map
/// does not otherwise provide HTTP header-name equality.
pub(crate) fn apply_effective_backend_scheme_headers(
    headers: &mut HashMap<String, String>,
    client_ip: &str,
    request_is_secure: bool,
    add_forwarded_header: bool,
) {
    let scheme = if request_is_secure { "https" } else { "http" };
    let forwarded = add_forwarded_header
        .then(|| build_forwarded_value(client_ip, scheme, headers.get("host").map(String::as_str)));
    headers.retain(|name, _| {
        !name.eq_ignore_ascii_case("x-forwarded-proto")
            && (!add_forwarded_header || !name.eq_ignore_ascii_case("forwarded"))
    });
    headers.insert("x-forwarded-proto".to_string(), scheme.to_string());
    if let Some(forwarded) = forwarded {
        headers.insert("forwarded".to_string(), forwarded);
    }
}

fn push_forwarded_param_value(buf: &mut String, value: &str) {
    if is_forwarded_token(value) {
        buf.push_str(value);
        return;
    }

    buf.push('"');
    for ch in value.chars() {
        if ch == '"' || ch == '\\' {
            buf.push('\\');
        }
        buf.push(ch);
    }
    buf.push('"');
}

fn is_forwarded_token(value: &str) -> bool {
    !value.is_empty()
        && value.bytes().all(|b| {
            b.is_ascii_alphanumeric()
                || matches!(
                    b,
                    b'!' | b'#'
                        | b'$'
                        | b'%'
                        | b'&'
                        | b'\''
                        | b'*'
                        | b'+'
                        | b'-'
                        | b'.'
                        | b'^'
                        | b'_'
                        | b'`'
                        | b'|'
                        | b'~'
                )
        })
}

pub(crate) async fn apply_request_body_plugins_with_context(
    plugins: &[Arc<dyn Plugin>],
    mut ctx: Option<&mut RequestContext>,
    grpc_deadline_at: Option<tokio::time::Instant>,
    headers: &HashMap<String, String>,
    body_bytes: Vec<u8>,
) -> Vec<u8> {
    if body_bytes.is_empty() || !plugins.iter().any(|plugin| plugin.modifies_request_body()) {
        return body_bytes;
    }

    let content_type = headers.get("content-type").map(|value| value.as_str());
    let mut current = body_bytes;
    for plugin in plugins {
        if plugin.modifies_request_body() {
            let deadline = ctx
                .as_deref()
                .and_then(RequestContext::grpc_deadline_at)
                .or(grpc_deadline_at);
            let transformed = if let Some(ctx) = ctx.as_deref_mut() {
                if let Some(deadline) = deadline {
                    match tokio::time::timeout_at(
                        deadline,
                        plugin.transform_request_body_with_context(
                            ctx,
                            &current,
                            content_type,
                            headers,
                        ),
                    )
                    .await
                    {
                        Ok(transformed) => transformed,
                        Err(_) => {
                            ctx.metadata.insert(
                                "grpc_deadline.request_body_transform_timed_out".to_string(),
                                "true".to_string(),
                            );
                            break;
                        }
                    }
                } else {
                    plugin
                        .transform_request_body_with_context(ctx, &current, content_type, headers)
                        .await
                }
            } else if let Some(deadline) = deadline {
                match tokio::time::timeout_at(
                    deadline,
                    plugin.transform_request_body(&current, content_type, headers),
                )
                .await
                {
                    Ok(transformed) => transformed,
                    Err(_) => break,
                }
            } else {
                plugin
                    .transform_request_body(&current, content_type, headers)
                    .await
            };
            if let Some(transformed) = transformed {
                current = transformed;
            }
        }
    }
    current
}

pub(crate) async fn run_final_request_body_hooks(
    plugins: &[Arc<dyn Plugin>],
    mut ctx: Option<&mut RequestContext>,
    grpc_deadline_at: Option<tokio::time::Instant>,
    headers: &HashMap<String, String>,
    body: &[u8],
) -> PluginResult {
    match run_final_request_body_hooks_with_provenance(
        plugins,
        ctx.as_deref_mut(),
        grpc_deadline_at,
        headers,
        body,
    )
    .await
    {
        crate::plugins::RequestPluginDeadlineResult::Completed(result) => result,
        crate::plugins::RequestPluginDeadlineResult::DeadlineExceeded => {
            if let Some(ctx) = ctx {
                ctx.mark_gateway_deadline_response_selected();
            }
            crate::plugins::grpc_deadline_exceeded_plugin_result()
        }
    }
}

pub(crate) async fn run_final_request_body_hooks_with_provenance(
    plugins: &[Arc<dyn Plugin>],
    mut ctx: Option<&mut RequestContext>,
    grpc_deadline_at: Option<tokio::time::Instant>,
    headers: &HashMap<String, String>,
    body: &[u8],
) -> crate::plugins::RequestPluginDeadlineResult {
    let deadline_expired = grpc_deadline_at
        .is_some_and(|deadline| deadline <= tokio::time::Instant::now())
        || ctx.as_deref().is_some_and(|ctx| {
            ctx.metadata
                .get("grpc_deadline.request_body_transform_timed_out")
                .is_some_and(|value| value == "true")
                || ctx
                    .grpc_deadline_at()
                    .is_some_and(|deadline| deadline <= tokio::time::Instant::now())
        });
    if deadline_expired {
        return crate::plugins::RequestPluginDeadlineResult::DeadlineExceeded;
    }
    for plugin in plugins {
        let deadline = ctx
            .as_deref()
            .and_then(RequestContext::grpc_deadline_at)
            .or(grpc_deadline_at);
        let result = if let Some(ctx) = ctx.as_deref_mut() {
            match crate::plugins::await_grpc_deadline(
                deadline,
                plugin.on_final_request_body_with_context(ctx, headers, body),
            )
            .await
            {
                Ok(result) => crate::plugins::RequestPluginDeadlineResult::Completed(result),
                Err(()) => crate::plugins::RequestPluginDeadlineResult::DeadlineExceeded,
            }
        } else {
            crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.on_final_request_body(headers, body),
            )
            .await
        };
        match result {
            crate::plugins::RequestPluginDeadlineResult::Completed(PluginResult::Continue) => {}
            crate::plugins::RequestPluginDeadlineResult::Completed(
                reject @ PluginResult::Reject { .. },
            )
            | crate::plugins::RequestPluginDeadlineResult::Completed(
                reject @ PluginResult::RejectBinary { .. },
            ) => {
                return crate::plugins::RequestPluginDeadlineResult::Completed(reject);
            }
            crate::plugins::RequestPluginDeadlineResult::DeadlineExceeded => {
                return crate::plugins::RequestPluginDeadlineResult::DeadlineExceeded;
            }
        }
    }
    crate::plugins::RequestPluginDeadlineResult::Completed(PluginResult::Continue)
}

pub(crate) struct RejectedResponseParts {
    pub status_code: u16,
    pub body: Vec<u8>,
    pub headers: HashMap<String, String>,
}

pub(crate) fn plugin_result_into_reject_parts(
    reject: PluginResult,
) -> Option<RejectedResponseParts> {
    match reject {
        PluginResult::Reject {
            status_code,
            body,
            headers,
        } => Some(RejectedResponseParts {
            status_code,
            body: body.into_bytes(),
            headers,
        }),
        PluginResult::RejectBinary {
            status_code,
            body,
            headers,
        } => Some(RejectedResponseParts {
            status_code,
            body: body.to_vec(),
            headers,
        }),
        PluginResult::Continue => None,
    }
}

fn reject_result_to_backend_response(
    reject: PluginResult,
    backend_resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let reject = plugin_result_into_reject_parts(reject)
        .expect("continue result cannot be converted to a reject");
    retry::BackendResponse {
        status_code: reject.status_code,
        body: ResponseBody::Buffered(reject.body),
        headers: reject.headers,
        connection_error: false,
        backend_resolved_ip,
        // Final request-body hooks run before backend dispatch. Keep their
        // synthetic responses terminal and neutral to backend health.
        error_class: Some(if reject.status_code == 413 {
            retry::ErrorClass::RequestBodyTooLarge
        } else {
            retry::ErrorClass::DispatchPolicyRejected
        }),
    }
}

/// Outcome of applying a candidate gateway configuration.
///
/// `Applied` and `Unchanged` both mean the candidate was accepted. `Rejected`
/// means validation/building failed and callers must keep their previous
/// bookkeeping (poll cursor, known-ID sets, staged side effects) unchanged.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConfigApplyOutcome {
    /// Changes were published to in-memory config.
    Applied,
    /// Candidate was valid and equivalent to the active runtime config.
    Unchanged,
    /// Validation or cache construction rejected the candidate.
    Rejected { errors: Vec<String> },
}

impl ConfigApplyOutcome {
    #[inline]
    pub fn accepted(&self) -> bool {
        matches!(self, Self::Applied | Self::Unchanged)
    }

    #[inline]
    pub fn applied(&self) -> bool {
        matches!(self, Self::Applied)
    }

    fn rejected(errors: Vec<String>) -> Self {
        Self::Rejected { errors }
    }

    fn rejected_one(error: impl Into<String>) -> Self {
        Self::Rejected {
            errors: vec![error.into()],
        }
    }
}

struct StagedIncrementalRequestEpoch {
    request_epoch: StagedRequestEpoch,
    proxy_plugin_rebuild_count: usize,
}

pub(crate) fn plugin_rebuild_targets_for_incremental_stage(
    current_config: &GatewayConfig,
    candidate_config: &GatewayConfig,
    delta: &crate::config_delta::ConfigDelta,
) -> HashSet<String> {
    delta.proxy_ids_needing_plugin_rebuild(current_config, candidate_config)
}

/// Shared state for the proxy engine.
#[derive(Clone)]
pub struct ProxyState {
    pub config: Arc<ArcSwap<GatewayConfig>>,
    pub request_epoch: Arc<RequestEpochStore>,
    pub dns_cache: DnsCache,
    pub connection_pool: Arc<ConnectionPool>,
    pub router_cache: Arc<RouterCache>,
    pub plugin_cache: Arc<PluginCache>,
    /// Runtime plugin HTTP client built from resolved gateway config. Admin
    /// validation reuses this so constructor-time endpoint policy checks match
    /// plugin-cache rebuilds.
    pub plugin_http_client: crate::plugins::PluginHttpClient,
    pub consumer_index: Arc<ConsumerIndex>,
    pub request_count: Arc<AtomicU64>,
    pub status_counts: Arc<dashmap::DashMap<u16, AtomicU64>>,
    /// gRPC-specific HTTP/2 connection pool (h2c + h2 with trailer support)
    pub grpc_pool: Arc<GrpcConnectionPool>,
    /// HTTP/2 connection pool for HTTPS backends (proper stream multiplexing)
    pub http2_pool: Arc<Http2ConnectionPool>,
    /// HBONE connection pool for gateway-to-mesh outbound tunnels.
    pub hbone_pool: Arc<HboneConnectionPool>,
    /// Sidecar egress SVID-mTLS HTTP/2 pool (`mesh.mtls` targets).
    pub mesh_mtls_pool: Arc<mesh_mtls_pool::MeshMtlsConnectionPool>,
    /// HTTP/3 connection pool for QUIC backends (reuses QUIC connections)
    pub h3_pool: Arc<Http3ConnectionPool>,
    /// Startup-classified backend protocol capabilities keyed by real backend target identity.
    pub backend_capabilities: SharedBackendCapabilityRegistry,
    /// Single-flight guard for the capability refresh task. Coalesces bursts
    /// of config-reload triggers into at most one in-flight refresh plus one
    /// queued re-run so rapid `apply_incremental` calls do not spawn N
    /// duplicate background probes.
    pub backend_capabilities_refresh: SharedRefreshCoalescer,
    /// Load balancer cache for upstream target selection.
    pub load_balancer_cache: Arc<LoadBalancerCache>,
    /// Health checker for upstream targets.
    pub health_checker: Arc<HealthChecker>,
    /// Shutdown receiver reused when config reloads restart health-check tasks.
    pub health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    /// Circuit breaker cache for proxy-level circuit breaking.
    pub circuit_breaker_cache: Arc<CircuitBreakerCache>,
    /// Service discovery manager for dynamic upstream target resolution.
    pub service_discovery_manager: Arc<ServiceDiscoveryManager>,
    /// Pre-computed Alt-Svc header value for HTTP/3 advertisement.
    /// `None` when HTTP/3 is disabled; avoids a `format!()` allocation per response.
    pub alt_svc_header: Option<String>,
    /// Pre-computed Via header values per protocol version (RFC 9110 §7.6.3).
    /// `None` when `FERRUM_ADD_VIA_HEADER=false` (default). Keyed by protocol version string.
    pub via_header_http11: Option<String>,
    pub via_header_http2: Option<String>,
    pub via_header_http3: Option<String>,
    /// Whether to add Forwarded header (RFC 7239) alongside X-Forwarded-*.
    pub add_forwarded_header: bool,
    /// Environment config for backend TLS settings (WebSocket, etc.)
    pub env_config: Arc<crate::config::EnvConfig>,
    /// Gateway-owned listener ports used for stream proxy conflict validation.
    ///
    /// Most modes derive this from [`EnvConfig::reserved_gateway_ports`]. File
    /// mode can adopt pre-bound listeners whose live ports differ from
    /// `EnvConfig`; storing the effective startup set here keeps later reload
    /// validation aligned with the sockets the process actually owns.
    pub reserved_gateway_ports: Arc<HashSet<u16>>,
    // Size limits
    pub max_header_size_bytes: usize,
    pub max_single_header_size_bytes: usize,
    pub max_header_count: usize,
    pub max_request_body_size_bytes: usize,
    pub max_response_body_size_bytes: usize,
    pub response_buffer_cutoff_bytes: usize,
    pub h2_coalesce_target_bytes: usize,
    pub max_url_length_bytes: usize,
    pub max_query_params: usize,
    pub max_grpc_recv_size_bytes: usize,
    pub max_websocket_frame_size_bytes: usize,
    pub websocket_write_buffer_size: usize,
    pub websocket_tunnel_mode: bool,
    /// Parsed trusted proxy CIDRs for X-Forwarded-For client IP resolution.
    /// Pre-parsed from `env_config.trusted_proxies` to avoid re-parsing on every request.
    pub trusted_proxies: Arc<client_ip::TrustedProxies>,
    /// Optional dedicated WebSocket admission control.
    /// Enforced only on the upgrade path, never on the frame-forwarding hot path.
    pub websocket_conn_limit: Option<Arc<tokio::sync::Semaphore>>,
    /// True only after the serving mode actually starts an H3 listener whose
    /// extended CONNECT/WebSocket support is enabled.
    ///
    /// `EnvConfig::enable_http3` alone is not enough: serving modes also gate
    /// listener startup on HTTPS port and frontend TLS availability.
    pub h3_websocket_reachable: Arc<AtomicBool>,
    /// Per-IP concurrent request counters. Each IP gets an AtomicU64 tracking
    /// active requests. `None` when `FERRUM_MAX_CONCURRENT_REQUESTS_PER_IP=0` (disabled).
    pub per_ip_request_counts: Option<Arc<dashmap::DashMap<String, AtomicU64>>>,
    /// Maximum concurrent requests per resolved client IP. 0 = disabled.
    pub max_concurrent_requests_per_ip: u64,
    /// Manages TCP/UDP stream proxy listeners (dedicated port per proxy).
    pub stream_listener_manager: Arc<stream_listener::StreamListenerManager>,
    /// Windowed per-second rate metrics computed by a background task.
    /// Read by the admin `/status` endpoint; written by `metrics::start_metrics_monitor`.
    pub windowed_metrics: Arc<crate::metrics::WindowedMetrics>,
    /// Monotonic instant captured at ProxyState creation for uptime calculation.
    pub started_at: Instant,
    /// Monotonic counter for generating unique WebSocket connection IDs.
    /// Used by frame-level plugins (e.g., ws_rate_limiting) for per-connection state.
    pub ws_connection_counter: Arc<AtomicU64>,
    /// TLS hardening policy for backend/outbound connections.
    /// When set, all backend TLS connections use the same cipher suites,
    /// protocol versions, and key exchange groups as inbound listeners.
    pub tls_policy: Option<Arc<TlsPolicy>>,
    /// Certificate Revocation Lists for backend TLS verification.
    /// Preserved as the startup snapshot for surfaces that still take an
    /// immutable CRL list.
    pub crls: crate::tls::CrlList,
    /// Hot-swappable backend CRL list consumed by backend HTTP/H2/gRPC pools.
    pub shared_crls: crate::tls::SharedCrlList,
    /// Overload state for progressive load shedding and graceful drain tracking.
    /// Shared across all accept loops and the background monitor.
    pub overload: Arc<crate::overload::OverloadState>,
    /// Adaptive buffer size and batch limit tracker for TCP/WS tunnel/UDP.
    /// Tracks EWMA of bytes per connection and datagrams per batch cycle per proxy.
    pub adaptive_buffer: Arc<crate::adaptive_buffer::AdaptiveBufferTracker>,
    /// HTTP methods allowed as TLS 1.3 0-RTT early data (O(1) lookup).
    /// Empty = 0-RTT disabled (`max_early_data_size=0`). Non-empty = 0-RTT enabled
    /// and requests arriving via early data are rejected with 425 Too Early if
    /// their method is not in this set. Pre-computed at config load time.
    pub early_data_methods: Arc<std::collections::HashSet<String>>,
    /// W3C `baggage` key prefixes stripped from outbound requests at the
    /// dispatch boundary. Empty = no-op (default). Set via
    /// `FERRUM_MESH_EGRESS_STRIP_BAGGAGE_KEYS`. Operators set this to keep
    /// mesh-internal identity claims (e.g. `source.principal`) from leaking
    /// to non-mesh upstream services.
    pub mesh_egress_strip_baggage_keys: Arc<Vec<String>>,
    /// Node-waypoint source identity resolver. Outbound capture sockets accepted
    /// from per-pod in-netns listeners must carry a node-agent/eBPF cookie record
    /// or the connection is dropped fail-closed before request processing.
    /// Inbound HBONE sockets from peer proxies do not carry those pod-loopback
    /// cookies and are authenticated by the HBONE/TLS path instead.
    pub node_waypoint_identity_resolver: Option<Arc<NodeWaypointIdentityResolver>>,
    /// Gateway SPIFFE identity for gateway/sidecar-to-mesh outbound HBONE.
    /// This is live, not staged: `can_attempt_hbone_backend` gates HBONE
    /// dispatch on this slot being loaded (see `current_dispatch_hbone` →
    /// `proxy_to_backend_hbone`), and `build_spiffe_outbound_config` consumes
    /// it to originate peer mTLS automatically. The slot shape matches mesh
    /// SVID rotation so trust-bundle updates hot-swap without blocking proxy
    /// readers.
    pub gateway_svid_bundle: SharedSvidBundle,
    /// Latest SVID bundle loaded from files. CP-delivered trust bundles are an
    /// override; when a CP snapshot removes them, this restores file trust.
    pub gateway_file_svid_bundle: SharedSvidBundle,
    /// Latest CP-delivered gateway trust bundles, stored even when this DP has
    /// no local SVID so later bridge phases can verify mesh peers from CP state.
    pub gateway_trust_bundles: SharedGatewayTrustBundles,
    /// Serializes the cold-path gateway SVID writers:
    /// CP-delivered trust-bundle apply, CP trust clear, and file SVID reload.
    pub gateway_svid_update_lock: Arc<std::sync::Mutex<()>>,
    /// Listener-wide compatibility view of the dynamic mesh inbound TLS config.
    /// Mesh HTTP/HBONE accept loops use `mesh_inbound_tls_policy` as the single
    /// authoritative source; this derived slot remains for shared stream TLS
    /// publication/status compatibility and is written alongside that policy.
    pub mesh_inbound_tls: SharedMeshInboundTls,
    /// Authoritative coherent listener-wide + per-app-port mesh inbound TLS and
    /// effective-mode snapshot. Captured traffic selects before the handshake;
    /// direct traffic checks the resolved app-port mode after routing.
    pub mesh_inbound_tls_policy: SharedMeshInboundTlsPolicy,
    /// Whether the current mesh inbound TLS posture is actually terminating
    /// inbound TLS with a SPIFFE peer verifier. This is operator status, not a
    /// dispatch hot-path flag: it distinguishes inbound trust from the outbound
    /// gateway SVID slot and stays false for plaintext or passthrough
    /// topologies.
    pub mesh_inbound_spiffe_verifier_active: Arc<AtomicBool>,
    /// Mesh `outboundTrafficPolicy: REGISTRY_ONLY` enforcement for stream-
    /// family egress (TCP / UDP / TCP+TLS / UDP+DTLS). `Some` only when
    /// (a) the gateway runs in mesh mode, (b) the resolved policy is
    /// `RegistryOnly`, and (c) at least one mesh outbound capture
    /// listener port is configured. Slice apply hot-swaps the contents
    /// atomically; non-mesh modes leave the slot at `None` so the hot
    /// path pays only one `ArcSwap::load()` plus an `Option::None` test.
    ///
    /// HTTP-family egress goes through the
    /// [`crate::plugins::mesh::outbound_registry`] plugin instead — both
    /// surfaces consume the same slice-derived registry, so behaviour
    /// stays consistent.
    pub mesh_outbound_enforcement:
        crate::modes::mesh::outbound_enforcement::SharedMeshOutboundEnforcement,
    /// Backend client SVID revision channel.
    ///
    /// The internal consumer side ([`spawn_backend_svid_rotation_task`]) holds
    /// a `Receiver` and drives `backend_svid_generation` plus pool drains.
    ///
    /// The gateway SVID file watcher publishes to this sender when
    /// `FERRUM_GATEWAY_SVID_*` files are configured and a validated reload
    /// succeeds. Future in-memory producers can also wire in by cloning the
    /// sender and handing the clone to `RotationConfig.revision_tx`
    /// ([`crate::identity::rotation::RotationConfig::new`]) or
    /// `SvidFetchHandle::with_revision_tx`. Until at least one producer is
    /// bound, the channel stays at generation 0 — pool keys carry `|svidg=0`
    /// and no rotation drain fires.
    #[allow(dead_code)]
    pub backend_svid_rotation_tx: tokio::sync::watch::Sender<u64>,
    /// Current backend client SVID generation shared by backend pools.
    #[allow(dead_code)] // Observability/test surface; runtime pools hold their own Arc clone.
    pub backend_svid_generation: BackendSvidGeneration,
    /// Shared SOCK_OPS metrics state populated by the kernel ringbuf
    /// consumer. `Some(_)` only when the gateway runs the SOCK_OPS event
    /// consumer (mesh-mode + node-waypoint topology). The same Arc is
    /// attached to [`PluginHttpClient`] so the auto-injected
    /// `__mesh_bpf_metrics` plugin reads from the live counters.
    /// `None` elsewhere; the plugin falls back to an unattached fresh
    /// state and emits zeros.
    ///
    /// The field is held on `ProxyState` so the Arc outlives a config
    /// reload that rebuilds `PluginHttpClient` — the plugin factory
    /// reads the live Arc via the http_client; the field itself is
    /// retained as a lifetime anchor and observability surface.
    #[allow(dead_code)]
    pub bpf_metrics_state: Option<Arc<crate::ebpf::bpf_metrics::BpfMetricsState>>,
    /// Per-destination open-connection limiter enforcing DestinationRule
    /// `connectionPool.tcp.maxConnections` for the HTTP-family WebSocket
    /// dispatch path (H1/H2 here and H3 in `src/http3/websocket.rs`). A
    /// proxied WebSocket session opens one dedicated, non-pooled backend
    /// connection whose lifetime equals the session, so an RAII
    /// [`crate::backend_conn_limit::BackendConnectionGuard`] held for the
    /// session bounds concurrent open connections per `(host, port)` —
    /// matching Envoy `maxConnections` semantics and the raw-TCP path's
    /// `BackendInflightGuard`. The pooled, multiplexed HTTP-family
    /// transports (reqwest H1/H2, direct H2, gRPC, H3, HBONE) do not
    /// consume this limiter; see `docs/mesh.md` and the module docs in
    /// `src/backend_conn_limit.rs` for why their pool-internal connection
    /// lifecycle makes a request-keyed counter the wrong control.
    pub backend_conn_limit: Arc<crate::backend_conn_limit::BackendConnectionLimiter>,
    /// Per-destination *pending-request* limiter enforcing DestinationRule
    /// `connectionPool.http.http1MaxPendingRequests` on the reqwest/HTTP-1.1
    /// backend-dispatch path. Bounds how many requests can be simultaneously
    /// waiting on connection capacity for a `(host, port)`; an over-cap request
    /// is shed with a 503 ("upstream overflow") in the connection-pending phase
    /// via an RAII [`crate::backend_pending_limit::BackendPendingGuard`] held
    /// only until dispatch returns. HTTP/1.1-scoped: the multiplexed transports
    /// (direct H2, gRPC, H3, HBONE, mesh-mTLS) do NOT consume it — their
    /// concurrency is governed by `h2_max_concurrent_streams`. See
    /// `docs/mesh.md` and `src/backend_pending_limit.rs`.
    pub backend_pending_limit: Arc<crate::backend_pending_limit::BackendPendingLimiter>,
}

#[inline]
fn via_header_for_inbound_version(state: &ProxyState, version: hyper::Version) -> &Option<String> {
    match version {
        hyper::Version::HTTP_2 => &state.via_header_http2,
        hyper::Version::HTTP_3 => &state.via_header_http3,
        _ => &state.via_header_http11,
    }
}

#[inline]
fn via_header_for_backend_response_body<'a>(
    state: &'a ProxyState,
    response_body: &ResponseBody,
) -> &'a Option<String> {
    match response_body {
        ResponseBody::Streaming { response, .. } => {
            via_header_for_inbound_version(state, response.version())
        }
        ResponseBody::StreamingH2(_) => &state.via_header_http2,
        ResponseBody::StreamingH3(_) => &state.via_header_http3,
        ResponseBody::Buffered(_) => &state.via_header_http11,
    }
}

#[derive(Clone, Default)]
struct RequestConnectionMetadata {
    frontend_listen_port: Option<u16>,
    frontend_sni_hostname: Option<String>,
    node_waypoint_identity: Option<Arc<NodeWaypointIdentity>>,
    /// Direction stamped at listener-spawn time for mesh listeners.
    /// `None` outside mesh mode.
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    /// Pre-NAT original destination of an iptables-REDIRECTed connection,
    /// read once at accept on mesh outbound capture listeners
    /// (`SO_ORIGINAL_DST`). NodeWaypoint eBPF capture can also supply this from
    /// the resolver cookie record because cgroup/connect rewrites do not create
    /// conntrack state. `None` everywhere else — see
    /// [`crate::socket_opts::original_dst`] for the exact contract.
    orig_dst: Option<SocketAddr>,
    /// Captured inbound app port actually used for accept-time mesh TLS policy
    /// selection, after applying any Sidecar ingress listener-to-app alias.
    /// `None` for direct dials and non-mesh listeners.
    mesh_inbound_pre_handshake_app_port: Option<u16>,
    /// Connection-scoped cache of the peer-cert SPIFFE extraction outcome,
    /// created when the connection presented a client certificate. Arc-shared
    /// so `spiffe_identity` derives the peer SPIFFE ID at most once per
    /// connection instead of re-parsing the DER on every multiplexed request.
    peer_spiffe_extraction_cache:
        Option<Arc<crate::plugins::mesh::spiffe_identity::SpiffeIdentityConnectionCache>>,
}

fn empty_svid_bundle_slot() -> SharedSvidBundle {
    Arc::new(ArcSwap::new(Arc::new(None)))
}

fn clone_svid_bundle_slot(slot: &SharedSvidBundle) -> SharedSvidBundle {
    Arc::new(ArcSwap::new(slot.load_full()))
}

pub type SharedGatewayTrustBundles = Arc<ArcSwap<Option<RuntimeTrustBundleSet>>>;
pub type SharedMeshInboundTls = Arc<ArcSwap<Option<Arc<rustls::ServerConfig>>>>;

pub struct MeshInboundTlsPolicy {
    pub default: Option<Arc<rustls::ServerConfig>>,
    pub by_port: HashMap<u16, Option<Arc<rustls::ServerConfig>>>,
    pub default_mode: crate::modes::mesh::config::MtlsMode,
    pub modes_by_port: std::collections::BTreeMap<u16, crate::modes::mesh::config::MtlsMode>,
    /// Translate a captured Sidecar ingress[] listener port to its
    /// defaultEndpoint backend app port before selecting PeerAuthentication.
    /// Ordinary captured inbound routes need no entry because their original
    /// destination already is the app/container port.
    pub app_port_by_orig_dst_port: std::collections::BTreeMap<u16, u16>,
}

impl Default for MeshInboundTlsPolicy {
    fn default() -> Self {
        Self {
            default: None,
            by_port: HashMap::new(),
            default_mode: crate::modes::mesh::config::MtlsMode::Permissive,
            modes_by_port: std::collections::BTreeMap::new(),
            app_port_by_orig_dst_port: std::collections::BTreeMap::new(),
        }
    }
}

pub type SharedMeshInboundTlsPolicy = Arc<ArcSwap<MeshInboundTlsPolicy>>;

fn empty_gateway_trust_bundle_slot() -> SharedGatewayTrustBundles {
    Arc::new(ArcSwap::new(Arc::new(None)))
}

fn empty_mesh_inbound_tls_slot() -> SharedMeshInboundTls {
    Arc::new(ArcSwap::new(Arc::new(None)))
}

fn empty_mesh_inbound_tls_policy_slot() -> SharedMeshInboundTlsPolicy {
    Arc::new(ArcSwap::new(Arc::new(MeshInboundTlsPolicy::default())))
}

fn load_gateway_svid_bundle(env_config: &EnvConfig) -> Result<SharedSvidBundle, anyhow::Error> {
    let configured = (
        env_config.gateway_svid_cert_path.as_deref(),
        env_config.gateway_svid_key_path.as_deref(),
        env_config.gateway_svid_trust_bundle_path.as_deref(),
    );
    let (cert_path, key_path, trust_bundle_path) = match configured {
        (None, None, None) => return Ok(empty_svid_bundle_slot()),
        (Some(cert_path), Some(key_path), Some(trust_bundle_path)) => {
            (cert_path, key_path, trust_bundle_path)
        }
        _ => {
            return Err(anyhow::anyhow!(
                "gateway SVID configuration requires FERRUM_GATEWAY_SVID_CERT_PATH, \
             FERRUM_GATEWAY_SVID_KEY_PATH, and FERRUM_GATEWAY_SVID_TRUST_BUNDLE_PATH together"
            ));
        }
    };

    let bundle = crate::identity::file_loader::load_svid_bundle_from_sources(
        cert_path,
        key_path,
        trust_bundle_path,
        env_config.gateway_spiffe_id.as_deref(),
    )
    .map_err(|e| anyhow::anyhow!("failed to load gateway SVID bundle: {e}"))?;

    info!(
        spiffe_id = %bundle.spiffe_id,
        trust_domain = %bundle.trust_domain(),
        trust_anchors = bundle.trust_bundles.local.x509_authorities.len(),
        "Loaded gateway SPIFFE SVID bundle"
    );
    Ok(Arc::new(ArcSwap::new(Arc::new(Some(bundle)))))
}

#[derive(Debug, Clone)]
struct GatewaySvidFilePaths {
    cert: PathBuf,
    key: PathBuf,
    trust_bundle: PathBuf,
    expected_spiffe_id: Option<String>,
}

fn gateway_svid_file_paths_from_env(env_config: &EnvConfig) -> Option<GatewaySvidFilePaths> {
    let (Some(cert), Some(key), Some(trust_bundle)) = (
        env_config.gateway_svid_cert_path.as_deref(),
        env_config.gateway_svid_key_path.as_deref(),
        env_config.gateway_svid_trust_bundle_path.as_deref(),
    ) else {
        return None;
    };
    let cert_source = CertSource::parse(cert, MaterialKind::Cert);
    let key_source = CertSource::parse(key, MaterialKind::Key);
    let trust_bundle_source = CertSource::parse(trust_bundle, MaterialKind::CaBundle);

    let (Some(cert), Some(key), Some(trust_bundle)) = (
        cert_source.as_file_path(),
        key_source.as_file_path(),
        trust_bundle_source.as_file_path(),
    ) else {
        info!("Gateway SVID source includes non-file material; file rotation watcher disabled");
        return None;
    };

    Some(GatewaySvidFilePaths {
        cert,
        key,
        trust_bundle,
        expected_spiffe_id: env_config.gateway_spiffe_id.clone(),
    })
}

fn proxy_backend_uses_tls(proxy: &Proxy) -> bool {
    matches!(
        proxy.backend_scheme,
        Some(BackendScheme::Https | BackendScheme::Tcps | BackendScheme::Dtls)
    )
}

fn collect_frontend_dtls_watched_sources(
    env_config: &EnvConfig,
) -> Vec<crate::tls::source::subscription::WatchedMaterialSource> {
    let mut seen = BTreeSet::new();
    let mut sources = Vec::new();
    let (Some(cert_path), Some(key_path)) = (
        env_config.dtls_cert_path.as_deref(),
        env_config.dtls_key_path.as_deref(),
    ) else {
        return sources;
    };

    push_tls_material_source(
        &mut sources,
        &mut seen,
        "dtls_cert",
        Some(cert_path),
        MaterialKind::Cert,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "dtls_key",
        Some(key_path),
        MaterialKind::Key,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "dtls_client_ca",
        env_config.dtls_client_ca_cert_path.as_deref(),
        MaterialKind::CaBundle,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "dtls_crl",
        env_config.tls_crl_file_path.as_deref(),
        MaterialKind::Crl,
    );

    sources
}

fn collect_backend_tls_watched_sources(
    config: &GatewayConfig,
    env_config: &EnvConfig,
) -> Vec<crate::tls::source::subscription::WatchedMaterialSource> {
    let mut seen = BTreeSet::new();
    let mut sources = Vec::new();

    push_tls_material_source(
        &mut sources,
        &mut seen,
        "global_ca",
        env_config.tls_ca_bundle_path.as_deref(),
        MaterialKind::CaBundle,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "global_client_cert",
        env_config.backend_tls_client_cert_path.as_deref(),
        MaterialKind::Cert,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "global_client_key",
        env_config.backend_tls_client_key_path.as_deref(),
        MaterialKind::Key,
    );
    push_tls_material_source(
        &mut sources,
        &mut seen,
        "global_crl",
        env_config.tls_crl_file_path.as_deref(),
        MaterialKind::Crl,
    );

    for proxy in &config.proxies {
        push_backend_tls_config_sources(&mut sources, &mut seen, &proxy.resolved_tls);
    }
    for upstream in &config.upstreams {
        let tls = BackendTlsConfig::from_upstream(upstream);
        push_backend_tls_config_sources(&mut sources, &mut seen, &tls);
    }
    for plugin in &config.plugin_configs {
        if !plugin.enabled || plugin.plugin_name != "mesh_route_dispatch" {
            continue;
        }
        let Ok(dispatch_config) = MeshRouteDispatchConfig::from_value_normalized(&plugin.config)
        else {
            continue;
        };
        for rule in &dispatch_config.rules {
            if let Some(tls) = rule.destination.backend_tls.as_ref() {
                push_backend_tls_config_sources(&mut sources, &mut seen, tls);
            }
        }
    }

    sources
}

fn push_backend_tls_config_sources(
    sources: &mut Vec<crate::tls::source::subscription::WatchedMaterialSource>,
    seen: &mut BTreeSet<(MaterialKind, String)>,
    tls: &BackendTlsConfig,
) {
    push_tls_material_source(
        sources,
        seen,
        "backend_ca",
        tls.server_ca_cert_path.as_deref(),
        MaterialKind::CaBundle,
    );
    push_tls_material_source(
        sources,
        seen,
        "backend_client_cert",
        tls.client_cert_path.as_deref(),
        MaterialKind::Cert,
    );
    push_tls_material_source(
        sources,
        seen,
        "backend_client_key",
        tls.client_key_path.as_deref(),
        MaterialKind::Key,
    );
}

fn push_tls_material_source(
    sources: &mut Vec<crate::tls::source::subscription::WatchedMaterialSource>,
    seen: &mut BTreeSet<(MaterialKind, String)>,
    label: &'static str,
    value: Option<&str>,
    kind: MaterialKind,
) {
    let Some(value) = value else {
        return;
    };
    let source = CertSource::parse(value.to_string(), kind);
    if seen.insert((kind, source.pool_key_component())) {
        sources.push(
            crate::tls::source::subscription::WatchedMaterialSource::new(label, source, kind),
        );
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct GatewaySvidFileFingerprint {
    cert: GatewaySvidFileStamp,
    key: GatewaySvidFileStamp,
    trust_bundle: GatewaySvidFileStamp,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct GatewaySvidFileStamp {
    len: u64,
    modified_nanos: Option<u128>,
}

fn gateway_svid_file_stamp(path: &Path) -> Result<GatewaySvidFileStamp, anyhow::Error> {
    let metadata = std::fs::metadata(path)
        .map_err(|e| anyhow::anyhow!("failed to stat {}: {}", path.display(), e))?;
    let modified_nanos = metadata
        .modified()
        .ok()
        .and_then(|modified| modified.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_nanos());
    Ok(GatewaySvidFileStamp {
        len: metadata.len(),
        modified_nanos,
    })
}

fn gateway_svid_file_fingerprint(
    paths: &GatewaySvidFilePaths,
) -> Result<GatewaySvidFileFingerprint, anyhow::Error> {
    Ok(GatewaySvidFileFingerprint {
        cert: gateway_svid_file_stamp(&paths.cert)?,
        key: gateway_svid_file_stamp(&paths.key)?,
        trust_bundle: gateway_svid_file_stamp(&paths.trust_bundle)?,
    })
}

async fn run_gateway_svid_file_rotation_loop(
    state: ProxyState,
    paths: GatewaySvidFilePaths,
    mut shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
) {
    const GATEWAY_SVID_FILE_POLL_INTERVAL: Duration = Duration::from_secs(1);

    let mut last_fingerprint = match gateway_svid_file_fingerprint(&paths) {
        Ok(fingerprint) => Some(fingerprint),
        Err(error) => {
            warn!(
                error = %error,
                "Gateway SVID file watcher could not read startup fingerprint; continuing and will retry"
            );
            None
        }
    };
    let mut interval = tokio::time::interval(GATEWAY_SVID_FILE_POLL_INTERVAL);
    interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);

    loop {
        if shutdown_rx.as_ref().is_some_and(|rx| *rx.borrow()) {
            return;
        }

        if let Some(shutdown) = shutdown_rx.as_mut() {
            tokio::select! {
                _ = interval.tick() => {}
                changed = shutdown.changed() => {
                    if changed.is_err() || *shutdown.borrow() {
                        return;
                    }
                    continue;
                }
            }
        } else {
            interval.tick().await;
        }

        let next_fingerprint = match gateway_svid_file_fingerprint(&paths) {
            Ok(fingerprint) => fingerprint,
            Err(error) => {
                warn!(
                    error = %error,
                    "Gateway SVID file watcher could not inspect SVID files; keeping current backend identity"
                );
                continue;
            }
        };
        if last_fingerprint.as_ref() == Some(&next_fingerprint) {
            continue;
        }

        let bundle = match crate::identity::file_loader::load_svid_bundle_from_files(
            &paths.cert,
            &paths.key,
            &paths.trust_bundle,
            paths.expected_spiffe_id.as_deref(),
        ) {
            Ok(bundle) => bundle,
            Err(error) => {
                warn!(
                    error = %error,
                    cert_path = %paths.cert.display(),
                    key_path = %paths.key.display(),
                    trust_bundle_path = %paths.trust_bundle.display(),
                    "Gateway SVID files changed but reload failed; keeping current backend identity"
                );
                // Record the failing fingerprint so we don't re-warn every
                // poll while the bad state is stable. The next genuine
                // change (good or different-bad) will compare unequal and
                // re-attempt the load.
                last_fingerprint = Some(next_fingerprint);
                continue;
            }
        };

        let spiffe_id = bundle.spiffe_id.to_string();
        state.install_gateway_file_svid_bundle(bundle);
        state
            .backend_svid_rotation_tx
            .send_modify(|revision| *revision = revision.saturating_add(1));
        let revision = *state.backend_svid_rotation_tx.borrow();
        last_fingerprint = Some(next_fingerprint);
        info!(
            spiffe_id = %spiffe_id,
            svid_revision = revision,
            "Gateway SVID files reloaded; backend SVID rotation published"
        );
    }
}

/// Bundle of the backend pools whose entries are partitioned by SVID
/// generation. Grouping them keeps the rotation-task signature manageable and
/// makes "another pool joined the family" a one-line edit.
///
/// NOTE on the asymmetric drain calls: only `connection_pool`, `http2_pool`,
/// and `grpc_pool` get a `drain_backend_tls_config_cache_svid_generation()`
/// call on rotation — the H3 pool's TLS config cache is co-located on
/// `connection_pool.backend_h3_tls_configs`, so it is drained transitively,
/// and the HBONE and mesh mTLS pools build their SPIFFE client config per
/// connect (no cache to drain). All pools get a `force_drain_svid_generation()` call when
/// the operator-configured drain window elapses, because each pool keeps its
/// own `DashMap` of live connections.
#[derive(Clone)]
struct BackendPoolFamily {
    connection_pool: Arc<ConnectionPool>,
    http2_pool: Arc<Http2ConnectionPool>,
    grpc_pool: Arc<GrpcConnectionPool>,
    h3_pool: Arc<Http3ConnectionPool>,
    hbone_pool: Arc<HboneConnectionPool>,
    mesh_mtls_pool: Arc<mesh_mtls_pool::MeshMtlsConnectionPool>,
}

impl BackendPoolFamily {
    fn drain_tls_config_cache(&self, generation: u64) {
        self.connection_pool
            .drain_backend_tls_config_cache_svid_generation(generation);
        self.http2_pool
            .drain_backend_tls_config_cache_svid_generation(generation);
        self.grpc_pool
            .drain_backend_tls_config_cache_svid_generation(generation);
    }

    fn clear_tls_config_caches(&self) {
        self.connection_pool.clear_backend_tls_config_cache();
        self.http2_pool.clear_backend_tls_config_cache();
        self.grpc_pool.clear_backend_tls_config_cache();
    }

    fn force_drain(&self, generation: u64) {
        self.connection_pool.force_drain_svid_generation(generation);
        self.http2_pool.force_drain_svid_generation(generation);
        self.grpc_pool.force_drain_svid_generation(generation);
        self.h3_pool.force_drain_svid_generation(generation);
        self.hbone_pool.force_drain_svid_generation(generation);
        self.mesh_mtls_pool.force_drain_svid_generation(generation);
    }

    fn force_drain_all(&self) {
        self.connection_pool.force_drain_all();
        self.http2_pool.force_drain_all();
        self.grpc_pool.force_drain_all();
        self.h3_pool.force_drain_all();
        self.hbone_pool.force_drain_all();
        self.mesh_mtls_pool.force_drain_all();
    }
}

struct BackendSvidRotationConsumer {
    pools: BackendPoolFamily,
    health_checker: Arc<HealthChecker>,
    config: Arc<ArcSwap<GatewayConfig>>,
    health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
}

impl BackendSvidRotationConsumer {
    fn restart_health_checks(&self) {
        let config = self.config.load_full();
        self.health_checker
            .restart_with_shutdown(&config, self.health_check_shutdown_rx.clone());
    }
}

fn spawn_backend_svid_rotation_task(
    mut revision_rx: tokio::sync::watch::Receiver<u64>,
    generation: BackendSvidGeneration,
    consumer: BackendSvidRotationConsumer,
    drain_seconds: u64,
    shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let mut current_generation = *revision_rx.borrow();
        generation.store(current_generation, Ordering::Release);
        let mut shutdown_rx = shutdown_rx;

        // Each rotation spawns its own delayed force-drain task targeting the
        // outgoing generation. Tasks are tracked here so they can be aborted
        // on graceful shutdown; otherwise each runs to completion independently
        // so the operator's `drain_seconds` window is honoured per-generation
        // even under rotation storms (e.g. a misbehaving CA issuing 30s certs).
        // Each task only retains the family's `Arc` pool handles and ends with
        // a single `invalidate_matching` pass per pool, so memory + CPU cost
        // remains O(rotations within drain_seconds) which is bounded by the
        // operator-chosen window.
        let mut pending_force_drains: std::collections::VecDeque<tokio::task::JoinHandle<()>> =
            std::collections::VecDeque::new();

        loop {
            // Reap finished tasks before each tick so the deque doesn't grow
            // beyond the actually-in-flight count.
            while let Some(front) = pending_force_drains.front() {
                if front.is_finished() {
                    pending_force_drains.pop_front();
                } else {
                    break;
                }
            }

            let changed = if let Some(shutdown) = shutdown_rx.as_mut() {
                tokio::select! {
                    changed = revision_rx.changed() => changed,
                    _ = shutdown.changed() => {
                        for handle in pending_force_drains.drain(..) {
                            handle.abort();
                        }
                        return;
                    }
                }
            } else {
                revision_rx.changed().await
            };
            if changed.is_err() {
                for handle in pending_force_drains.drain(..) {
                    handle.abort();
                }
                return;
            }

            let next_generation = *revision_rx.borrow();
            if next_generation == current_generation {
                continue;
            }

            let old_generation = current_generation;
            current_generation = next_generation;
            generation.store(next_generation, Ordering::Release);
            consumer.pools.drain_tls_config_cache(old_generation);
            consumer.restart_health_checks();

            info!(
                old_svid_generation = old_generation,
                new_svid_generation = next_generation,
                drain_seconds,
                "Backend client SVID rotation observed; new backend TLS connections will use fresh identity"
            );

            if drain_seconds > 0 {
                let pools_for_drain = consumer.pools.clone();
                let mut inner_shutdown = shutdown_rx.clone();
                pending_force_drains.push_back(tokio::spawn(async move {
                    let sleep = tokio::time::sleep(Duration::from_secs(drain_seconds));
                    tokio::pin!(sleep);
                    if let Some(shutdown) = inner_shutdown.as_mut() {
                        tokio::select! {
                            _ = &mut sleep => {}
                            _ = shutdown.changed() => return,
                        }
                    } else {
                        sleep.as_mut().await;
                    }
                    pools_for_drain.force_drain(old_generation);
                    info!(
                        old_svid_generation = old_generation,
                        "Forced drain of backend pool entries from previous SVID generation completed"
                    );
                }));
            }
        }
    })
}

impl ProxyState {
    /// Apply a full snapshot on Tokio's blocking pool. DP snapshots cannot
    /// carry a CP-side node-local MMDB handoff, so their plugin-cache build may
    /// synchronously hash, verify, and scan the configured database.
    pub async fn update_config_off_thread(&self, new_config: GatewayConfig) -> ConfigApplyOutcome {
        let proxy_state = self.clone();
        match tokio::task::spawn_blocking(move || proxy_state.update_config(new_config)).await {
            Ok(outcome) => outcome,
            Err(error) => {
                let message = format!("configuration update worker failed: {error}");
                error!("Config reload rejected: {}", message);
                ConfigApplyOutcome::rejected_one(message)
            }
        }
    }

    /// Install CP-delivered trust bundles for gateway-to-mesh TLS.
    ///
    /// If the gateway already has a file-loaded SVID, rebuild the SVID bundle
    /// with the new trust material so TLS builders see the update through the
    /// same lock-free slot. If there is no SVID, keep the bundles separately
    /// for future gateway-mesh features.
    ///
    /// This is called from the DP config-apply loop, which is single-writer for
    /// CP-delivered gateway trust. The gateway SVID file watcher can also swap
    /// the SVID bundle, so all gateway SVID slot writes are serialized by
    /// `gateway_svid_update_lock`.
    pub fn update_gateway_trust_bundles(&self, trust_bundles: RuntimeTrustBundleSet) {
        let _guard = self
            .gateway_svid_update_lock
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        self.gateway_trust_bundles
            .store(Arc::new(Some(trust_bundles.clone())));

        let current = self.gateway_svid_bundle.load_full();
        if let Some(mut bundle) = current.as_ref().clone() {
            bundle.trust_bundles = trust_bundles;
            self.gateway_svid_bundle.store(Arc::new(Some(bundle)));
        }
    }

    /// Clear CP-delivered trust bundles and restore the latest file-loaded SVID.
    pub fn clear_gateway_trust_bundles(&self) {
        let _guard = self
            .gateway_svid_update_lock
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        self.gateway_trust_bundles.store(Arc::new(None));
        self.gateway_svid_bundle
            .store(self.gateway_file_svid_bundle.load_full());
    }

    pub(crate) fn install_gateway_runtime_svid_bundle(&self, bundle: SvidBundle) {
        let _guard = self
            .gateway_svid_update_lock
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());

        self.gateway_file_svid_bundle
            .store(Arc::new(Some(bundle.clone())));

        let mut active_bundle = bundle;
        let trust_snapshot = self.gateway_trust_bundles.load_full();
        if let Some(trust_bundles) = trust_snapshot.as_ref() {
            active_bundle.trust_bundles = trust_bundles.clone();
        }
        self.gateway_svid_bundle
            .store(Arc::new(Some(active_bundle)));
    }

    fn install_gateway_file_svid_bundle(&self, file_bundle: SvidBundle) {
        self.install_gateway_runtime_svid_bundle(file_bundle);
    }

    /// Force a gateway SVID reload from the currently configured sources.
    ///
    /// This is the admin-triggered equivalent of the file watcher path. It
    /// accepts any source form supported by `load_svid_bundle_from_sources`
    /// (file path, inline PEM, typed URI), preserves any CP-delivered trust
    /// override, and publishes a backend SVID generation bump so backend pools
    /// rebuild/drain through the existing rotation consumer.
    pub fn force_reload_gateway_svid(&self) -> Result<u64, anyhow::Error> {
        let (Some(cert_source), Some(key_source), Some(trust_bundle_source)) = (
            self.env_config.gateway_svid_cert_path.as_deref(),
            self.env_config.gateway_svid_key_path.as_deref(),
            self.env_config.gateway_svid_trust_bundle_path.as_deref(),
        ) else {
            anyhow::bail!(
                "gateway SVID sources are not configured; set FERRUM_GATEWAY_SVID_CERT_SOURCE, FERRUM_GATEWAY_SVID_KEY_SOURCE, and FERRUM_GATEWAY_SVID_TRUST_BUNDLE_SOURCE"
            );
        };

        let bundle = crate::identity::file_loader::load_svid_bundle_from_sources(
            cert_source,
            key_source,
            trust_bundle_source,
            self.env_config.gateway_spiffe_id.as_deref(),
        )
        .map_err(|error| anyhow::anyhow!("failed to reload gateway SVID sources: {error}"))?;
        let spiffe_id = bundle.spiffe_id.to_string();
        self.install_gateway_file_svid_bundle(bundle);
        self.backend_svid_rotation_tx
            .send_modify(|revision| *revision = revision.saturating_add(1));
        let revision = *self.backend_svid_rotation_tx.borrow();

        info!(
            spiffe_id = %spiffe_id,
            svid_revision = revision,
            "Gateway SVID force reload completed; backend SVID rotation published"
        );

        Ok(revision)
    }

    fn validate_backend_tls_material(
        &self,
        crls: &[rustls::pki_types::CertificateRevocationListDer<'static>],
    ) -> Result<usize, anyhow::Error> {
        let config = self.config.load_full();
        let mut validated = 0usize;
        for proxy in config
            .proxies
            .iter()
            .filter(|proxy| proxy_backend_uses_tls(proxy))
        {
            BackendTlsConfigBuilder {
                proxy,
                policy: self.tls_policy.as_deref(),
                global_ca: self.env_config.tls_ca_bundle_path.as_deref().map(Path::new),
                global_no_verify: self.env_config.tls_no_verify,
                global_client_cert: self
                    .env_config
                    .backend_tls_client_cert_path
                    .as_deref()
                    .map(Path::new),
                global_client_key: self
                    .env_config
                    .backend_tls_client_key_path
                    .as_deref()
                    .map(Path::new),
                crls,
            }
            .build_rustls()
            .map_err(|error| {
                anyhow::anyhow!(
                    "backend TLS validation failed for proxy '{}': {}",
                    proxy.id,
                    error
                )
            })?;
            validated = validated.saturating_add(1);
        }
        let proxy_map = config
            .proxies
            .iter()
            .map(|proxy| (proxy.id.as_str(), proxy))
            .collect::<HashMap<_, _>>();
        for plugin in &config.plugin_configs {
            if !plugin.enabled || plugin.plugin_name != "mesh_route_dispatch" {
                continue;
            }
            let dispatch_config = MeshRouteDispatchConfig::from_value_normalized(&plugin.config)
                .map_err(|error| {
                    anyhow::anyhow!(
                        "mesh_route_dispatch backend TLS validation failed for plugin '{}': {}",
                        plugin.id,
                        error
                    )
                })?;
            let base_proxy = plugin
                .proxy_id
                .as_deref()
                .and_then(|proxy_id| proxy_map.get(proxy_id).copied())
                .or_else(|| config.proxies.first());
            let Some(base_proxy) = base_proxy else {
                continue;
            };
            for (rule_idx, rule) in dispatch_config.rules.iter().enumerate() {
                let Some(tls) = rule.destination.backend_tls.as_ref() else {
                    continue;
                };
                let mut validation_proxy = base_proxy.clone();
                validation_proxy.id = format!(
                    "{}:mesh_route_dispatch.rules[{rule_idx}].destination.backend_tls",
                    plugin.id
                );
                validation_proxy.backend_scheme = Some(BackendScheme::Https);
                validation_proxy.resolved_tls = tls.clone();
                BackendTlsConfigBuilder {
                    proxy: &validation_proxy,
                    policy: self.tls_policy.as_deref(),
                    global_ca: self.env_config.tls_ca_bundle_path.as_deref().map(Path::new),
                    global_no_verify: self.env_config.tls_no_verify,
                    global_client_cert: self
                        .env_config
                        .backend_tls_client_cert_path
                        .as_deref()
                        .map(Path::new),
                    global_client_key: self
                        .env_config
                        .backend_tls_client_key_path
                        .as_deref()
                        .map(Path::new),
                    crls,
                }
                .build_rustls()
                .map_err(|error| {
                    anyhow::anyhow!(
                        "mesh_route_dispatch backend TLS validation failed for plugin '{}' rule {}: {}",
                        plugin.id,
                        rule_idx,
                        error
                    )
                })?;
                validated = validated.saturating_add(1);
            }
        }
        Ok(validated)
    }

    fn reload_backend_tls_material(&self) -> Result<(), anyhow::Error> {
        let active_crls = crate::tls::load_crls(self.env_config.tls_crl_file_path.as_deref())?;
        let validated = self.validate_backend_tls_material(active_crls.as_ref().as_slice())?;
        self.shared_crls.store(active_crls);
        let pools = BackendPoolFamily {
            connection_pool: self.connection_pool.clone(),
            http2_pool: self.http2_pool.clone(),
            grpc_pool: self.grpc_pool.clone(),
            h3_pool: self.h3_pool.clone(),
            hbone_pool: self.hbone_pool.clone(),
            mesh_mtls_pool: self.mesh_mtls_pool.clone(),
        };
        pools.clear_tls_config_caches();
        pools.force_drain_all();
        // UDP/DTLS listeners keep listener-local backend DTLS config caches
        // keyed by paths/options; bump the shared epoch so new sessions
        // rebuild from the rotated bytes instead of serving stale params.
        self.stream_listener_manager.bump_backend_tls_reload_epoch();
        // Publish the reloaded CRLs to the stream listener manager BEFORE the
        // reconcile below: TCP+TLS reload keys fold in the CRL content
        // fingerprint, so this swap is what makes a CRL-only rotation restart
        // those listeners with the new revocation list (and what makes any
        // restarted listener rebuild against the rotated CRLs rather than the
        // startup snapshot).
        self.stream_listener_manager
            .set_crls(self.shared_crls.load_full());

        let config = self.config.load_full();
        self.health_checker
            .restart_with_shutdown(&config, self.health_check_shutdown_rx.clone());

        // TCP+TLS stream listeners cache their backend `ClientConfig` at
        // spawn and only recompute the content fingerprints in their reload
        // keys inside `StreamListenerManager::reconcile()`. The live-reload
        // watcher observes the same stream-proxy TLS sources (see
        // `collect_backend_tls_watched_sources`), so a same-path CA / client
        // cert rotation must also drive a stream reconcile here — otherwise
        // stream listeners keep the stale cached config until an unrelated
        // config delta or a restart. Spawned so this synchronous rebuild
        // callback (invoked from the watcher task) never blocks on the
        // listeners mutex; reconcile itself never crashes and reports
        // per-listener failures, which we surface as warnings.
        let stream_listener_manager = self.stream_listener_manager.clone();
        tokio::spawn(async move {
            let failures = stream_listener_manager.reconcile().await;
            for (proxy_id, port, err) in &failures {
                warn!(
                    proxy_id = %proxy_id,
                    port = port,
                    "Stream listener reconcile after backend TLS material reload reported a failure: {}",
                    err
                );
            }
        });

        info!(
            validated_backend_tls_configs = validated,
            "Backend TLS material reloaded; backend client pools and DTLS config caches were drained and stream listeners reconciled"
        );
        Ok(())
    }

    fn reload_frontend_dtls_material(&self) -> Result<(), anyhow::Error> {
        let (Some(cert_path), Some(key_path)) = (
            self.env_config.dtls_cert_path.clone(),
            self.env_config.dtls_key_path.clone(),
        ) else {
            return Ok(());
        };
        let client_ca_cert_path = self.env_config.dtls_client_ca_cert_path.clone();
        let active_crls = crate::tls::load_crls(self.env_config.tls_crl_file_path.as_deref())?;
        crate::dtls::build_frontend_dtls_config(
            &cert_path,
            &key_path,
            client_ca_cert_path.as_deref(),
            active_crls.as_ref().as_slice(),
        )?;

        let manager = self.stream_listener_manager.clone();
        tokio::spawn(async move {
            let swapped = manager
                .swap_active_dtls_frontend_configs(|| {
                    crate::dtls::build_frontend_dtls_config(
                        &cert_path,
                        &key_path,
                        client_ca_cert_path.as_deref(),
                        active_crls.as_ref().as_slice(),
                    )
                })
                .await;
            info!(
                swapped_dtls_listeners = swapped,
                "Frontend DTLS material reloaded; new DTLS sessions will use rotated material"
            );
        });
        Ok(())
    }

    fn start_frontend_dtls_source_reload_task(
        &self,
        shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Option<tokio::task::JoinHandle<()>> {
        if !self.env_config.frontend_tls_live_reload_enabled {
            return None;
        }
        if tokio::runtime::Handle::try_current().is_err() {
            warn!(
                "FERRUM_FRONTEND_TLS_LIVE_RELOAD_ENABLED=true but no tokio runtime is active; frontend DTLS live reload disabled"
            );
            return None;
        }
        let watched_sources = collect_frontend_dtls_watched_sources(&self.env_config);
        if !watched_sources
            .iter()
            .any(|source| crate::tls::source::subscription::source_is_refreshable(&source.source))
        {
            return None;
        }
        let interval = crate::tls::source::subscription::material_set_poll_interval(
            &watched_sources,
            Duration::from_secs(self.env_config.frontend_tls_watch_interval_seconds.max(1)),
            Duration::from_secs(self.env_config.secret_refresh_interval_seconds.max(1)),
        );
        let (revision_tx, _revision_rx) = tokio::sync::watch::channel(0u64);
        let state = self.clone();
        Some(
            crate::tls::source::subscription::spawn_material_set_reload_task(
                crate::tls::source::subscription::MaterialSetReloadConfig {
                    surface: "dtls",
                    sources: watched_sources,
                    interval,
                    revision_tx,
                    rebuild: Box::new(move || state.reload_frontend_dtls_material()),
                },
                shutdown_rx,
            ),
        )
    }

    fn start_backend_tls_source_reload_task(
        &self,
        shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Option<tokio::task::JoinHandle<()>> {
        if !self.env_config.backend_tls_live_reload_enabled {
            return None;
        }
        if tokio::runtime::Handle::try_current().is_err() {
            warn!(
                "FERRUM_BACKEND_TLS_LIVE_RELOAD_ENABLED=true but no tokio runtime is active; backend TLS live reload disabled"
            );
            return None;
        }

        let (revision_tx, _revision_rx) = tokio::sync::watch::channel(0u64);
        let collect_state = self.clone();
        let rebuild_state = self.clone();
        Some(
            crate::tls::source::subscription::spawn_dynamic_material_set_reload_task(
                crate::tls::source::subscription::DynamicMaterialSetReloadConfig {
                    surface: "backend_tls",
                    collect_sources: Box::new(move || {
                        let config = collect_state.config.load_full();
                        collect_backend_tls_watched_sources(&config, &collect_state.env_config)
                    }),
                    file_default_interval: Duration::from_secs(
                        self.env_config.backend_tls_watch_interval_seconds.max(1),
                    ),
                    provider_default_interval: Duration::from_secs(
                        self.env_config.secret_refresh_interval_seconds.max(1),
                    ),
                    revision_tx,
                    rebuild: Box::new(move || rebuild_state.reload_backend_tls_material()),
                },
                shutdown_rx,
            ),
        )
    }

    fn start_gateway_svid_file_rotation_task(
        &self,
        shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Option<tokio::task::JoinHandle<()>> {
        let paths = gateway_svid_file_paths_from_env(&self.env_config)?;
        let state = self.clone();
        Some(tokio::spawn(run_gateway_svid_file_rotation_loop(
            state,
            paths,
            shutdown_rx,
        )))
    }

    /// Construct the gateway state and start the health checker.
    ///
    /// `health_check_shutdown_rx` is forwarded to
    /// [`HealthChecker::start_with_shutdown`] so active HTTP probes and the
    /// passive recovery timer observe gateway shutdown via `tokio::select!`
    /// and exit cleanly. Pass `Some(shutdown_tx.subscribe())` from each
    /// mode's startup; tests that don't drive shutdown can pass `None`.
    ///
    /// Returns `(ProxyState, Vec<JoinHandle>)`. The handle vec is populated
    /// by [`HealthChecker::take_active_check_handles`] — they wrap the
    /// spawned active-check / passive-recovery tasks. Modes must `await`
    /// them in the per-mode background-drain phase (alongside DNS / metrics
    /// / overload). Taking handles drains JoinHandles for await only;
    /// `HealthChecker` retains AbortHandles so config reload can still
    /// cancel the drained startup generation. Without that retained cancel
    /// path, reload would orphan startup probes. Without the mode-side
    /// await, cleanup falls back to `Drop for HealthChecker`, which only
    /// aborts tasks once the last `Arc<HealthChecker>` clone is dropped —
    /// at process exit, AFTER the drain window has already closed. That
    /// late abort lets a probe mid-`http_probe` finish its TCP / TLS /
    /// HTTP round-trip and emit a misleading "unhealthy" log line right
    /// before tear-down.
    pub fn new(
        config: GatewayConfig,
        dns_cache: DnsCache,
        env_config: crate::config::EnvConfig,
        tls_policy: Option<TlsPolicy>,
        health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Result<(Self, Vec<tokio::task::JoinHandle<()>>), anyhow::Error> {
        let reserved_gateway_ports = env_config.reserved_gateway_ports();
        Self::new_with_bpf_metrics_and_reserved_gateway_ports(
            config,
            dns_cache,
            env_config,
            tls_policy,
            health_check_shutdown_rx,
            None,
            reserved_gateway_ports,
        )
    }

    /// Constructor variant that accepts the effective gateway-owned listener
    /// ports for stream proxy conflict validation.
    ///
    /// File mode uses this when adopting pre-bound listeners so initial
    /// validation, SIGHUP reloads, and programmatic `update_config` calls all
    /// use the same actual socket set instead of recalculating from `EnvConfig`.
    pub fn new_with_reserved_gateway_ports(
        config: GatewayConfig,
        dns_cache: DnsCache,
        env_config: crate::config::EnvConfig,
        tls_policy: Option<TlsPolicy>,
        health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
        reserved_gateway_ports: HashSet<u16>,
    ) -> Result<(Self, Vec<tokio::task::JoinHandle<()>>), anyhow::Error> {
        Self::new_with_bpf_metrics_and_reserved_gateway_ports(
            config,
            dns_cache,
            env_config,
            tls_policy,
            health_check_shutdown_rx,
            None,
            reserved_gateway_ports,
        )
    }

    /// Constructor variant that also accepts a pre-built
    /// `Arc<BpfMetricsState>` so the auto-injected `__mesh_bpf_metrics`
    /// plugin can read live SOCK_OPS counters from the kernel ringbuf
    /// consumer.
    ///
    /// All other modes pass `None` (or call [`Self::new`] which forwards
    /// `None`); only mesh-mode + node-waypoint topology builds the shared
    /// metrics state at startup. Keeping the parameter optional avoids
    /// forcing every other entry point to plumb a placeholder.
    pub fn new_with_bpf_metrics(
        config: GatewayConfig,
        dns_cache: DnsCache,
        env_config: crate::config::EnvConfig,
        tls_policy: Option<TlsPolicy>,
        health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
        bpf_metrics_state: Option<Arc<crate::ebpf::bpf_metrics::BpfMetricsState>>,
    ) -> Result<(Self, Vec<tokio::task::JoinHandle<()>>), anyhow::Error> {
        let reserved_gateway_ports = env_config.reserved_gateway_ports();
        Self::new_with_bpf_metrics_and_reserved_gateway_ports(
            config,
            dns_cache,
            env_config,
            tls_policy,
            health_check_shutdown_rx,
            bpf_metrics_state,
            reserved_gateway_ports,
        )
    }

    fn new_with_bpf_metrics_and_reserved_gateway_ports(
        mut config: GatewayConfig,
        dns_cache: DnsCache,
        env_config: crate::config::EnvConfig,
        tls_policy: Option<TlsPolicy>,
        health_check_shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
        bpf_metrics_state: Option<Arc<crate::ebpf::bpf_metrics::BpfMetricsState>>,
        reserved_gateway_ports: HashSet<u16>,
    ) -> Result<(Self, Vec<tokio::task::JoinHandle<()>>), anyhow::Error> {
        if let Err(errors) = validate_mesh_route_dispatch_upstream_references(&config) {
            for msg in &errors {
                error!("Initial config rejected: {}", msg);
            }
            return Err(anyhow::anyhow!(
                "Initial config has invalid mesh_route_dispatch upstream references"
            ));
        }

        let alt_svc_header = if env_config.enable_http3 {
            Some(format!("h3=\":{}\"; ma=86400", env_config.proxy_https_port))
        } else {
            None
        };
        let (via_header_http11, via_header_http2, via_header_http3) = if env_config.add_via_header {
            let p = &env_config.via_pseudonym;
            (
                Some(format!("1.1 {p}")),
                Some(format!("2.0 {p}")),
                Some(format!("3.0 {p}")),
            )
        } else {
            (None, None, None)
        };
        let add_forwarded_header = env_config.add_forwarded_header;
        let max_header_size_bytes = env_config.max_header_size_bytes;
        let max_single_header_size_bytes = env_config.max_single_header_size_bytes;
        let max_header_count = env_config.max_header_count;
        let max_request_body_size_bytes = env_config.max_request_body_size_bytes;
        let max_response_body_size_bytes = env_config.max_response_body_size_bytes;
        let response_buffer_cutoff_bytes = env_config.response_buffer_cutoff_bytes;
        let h2_coalesce_target_bytes = env_config.h2_coalesce_target_bytes;
        let max_url_length_bytes = env_config.max_url_length_bytes;
        let max_query_params = env_config.max_query_params;
        let max_grpc_recv_size_bytes = env_config.max_grpc_recv_size_bytes;
        let max_websocket_frame_size_bytes = env_config.max_websocket_frame_size_bytes;
        let websocket_write_buffer_size = env_config.websocket_write_buffer_size;
        let websocket_tunnel_mode = env_config.websocket_tunnel_mode;
        let max_concurrent_requests_per_ip = env_config.max_concurrent_requests_per_ip;
        let mesh_egress_strip_baggage_keys =
            Arc::new(env_config.mesh_egress_strip_baggage_keys.clone());
        let pool_shard_amount =
            crate::util::sharding::pool_shard_amount(env_config.pool_shard_amount);
        // Strict: a malformed entry must never yield a partially parsed
        // forwarding trust boundary (advisory GHSA-pvj7-hhqj-rpv5).
        // `EnvConfig::validate()` already rejects this at parse time, so a
        // failure here means a hand-built config; either way construction fails
        // before any listener binds, and a live `ProxyState` keeps its existing
        // (last-known-good) trust set because `update_config` never rebuilds it.
        let trusted_proxies = Arc::new(
            client_ip::TrustedProxies::parse_strict(
                &env_config.trusted_proxies,
                "FERRUM_TRUSTED_PROXIES",
            )
            .map_err(|e| anyhow::anyhow!("FERRUM_TRUSTED_PROXIES: {e}"))?,
        );
        let websocket_conn_limit = if env_config.websocket_max_connections > 0 {
            Some(Arc::new(tokio::sync::Semaphore::new(
                env_config.websocket_max_connections,
            )))
        } else {
            None
        };
        warn_if_websocket_idle_disabled(&config, env_config.websocket_idle_timeout_seconds);
        // Create connection pools with global configuration from environment
        let global_pool_config = PoolConfig::from_env();
        let tls_policy_arc = tls_policy.map(Arc::new);
        warn_if_h3_backend_tls_policy_incompatible(&config, tls_policy_arc.as_deref());
        let crls = crate::tls::load_crls(env_config.tls_crl_file_path.as_deref())?;
        let shared_crls = crate::tls::shared_crl_list(crls.clone());
        let backend_svid_generation = Arc::new(AtomicU64::new(0));
        let (backend_svid_rotation_tx, backend_svid_rotation_rx) =
            tokio::sync::watch::channel(0u64);
        let grpc_pool = Arc::new(
            GrpcConnectionPool::new_with_svid_generation_and_shared_crls(
                global_pool_config.clone(),
                env_config.clone(),
                dns_cache.clone(),
                tls_policy_arc.clone(),
                shared_crls.clone(),
                backend_svid_generation.clone(),
            ),
        );
        let http2_pool = Arc::new(
            Http2ConnectionPool::new_with_svid_generation_and_shared_crls(
                global_pool_config.clone(),
                env_config.clone(),
                dns_cache.clone(),
                tls_policy_arc.clone(),
                shared_crls.clone(),
                backend_svid_generation.clone(),
            ),
        );
        let env_config_arc = Arc::new(env_config.clone());
        let gateway_svid_bundle = load_gateway_svid_bundle(&env_config_arc)?;
        inject_gateway_workload_metrics_if_svid(
            &mut config,
            &gateway_svid_bundle,
            &env_config_arc.namespace,
        );
        let gateway_file_svid_bundle = clone_svid_bundle_slot(&gateway_svid_bundle);
        let gateway_trust_bundles = empty_gateway_trust_bundle_slot();
        let mesh_inbound_tls = empty_mesh_inbound_tls_slot();
        let mesh_inbound_tls_policy = empty_mesh_inbound_tls_policy_slot();
        let mesh_inbound_spiffe_verifier_active = Arc::new(AtomicBool::new(false));
        let mesh_outbound_enforcement = crate::modes::mesh::outbound_enforcement::empty_slot();
        let hbone_pool = Arc::new(
            HboneConnectionPool::new_with_svid_generation_and_shared_crls(
                global_pool_config.clone(),
                dns_cache.clone(),
                gateway_svid_bundle.clone(),
                shared_crls.clone(),
                pool_shard_amount,
                backend_svid_generation.clone(),
            ),
        );
        let mesh_mtls_pool = Arc::new(
            mesh_mtls_pool::MeshMtlsConnectionPool::new_with_svid_generation_and_shared_crls(
                global_pool_config.clone(),
                dns_cache.clone(),
                gateway_svid_bundle.clone(),
                shared_crls.clone(),
                pool_shard_amount,
                backend_svid_generation.clone(),
            ),
        );
        let h3_pool = Arc::new(Http3ConnectionPool::new_with_svid_generation(
            env_config_arc.clone(),
            dns_cache.clone(),
            backend_svid_generation.clone(),
        ));
        let backend_capabilities = Arc::new(BackendCapabilityRegistry::with_shard_amount(
            pool_shard_amount,
        ));
        let backend_capabilities_refresh = Arc::new(RefreshCoalescer::new());
        let connection_pool = Arc::new(ConnectionPool::new_with_svid_generation_and_shared_crls(
            global_pool_config.clone(),
            env_config,
            dns_cache.clone(),
            tls_policy_arc.clone(),
            shared_crls.clone(),
            backend_svid_generation.clone(),
        ));
        // Build router cache with pre-sorted route table and HashMap prefix index.
        // Cache size: explicit env var if set (>0), otherwise pass through 0 so
        // the RouterCache constructor resolves the auto sentinel (single source of truth).
        let max_cache_entries = if env_config_arc.router_cache_max_entries > 0 {
            env_config_arc
                .router_cache_max_entries
                .clamp(1_000, 10_000_000)
        } else {
            0
        };
        let router_cache = Arc::new(RouterCache::with_shard_amount(
            &config,
            max_cache_entries,
            pool_shard_amount,
        ));
        // Pre-resolve plugins per proxy (fixes rate_limiting state persistence bug).
        // All plugins that make outbound HTTP calls share a pooled client configured
        // with the gateway's connection pool settings (keepalive, idle timeout, etc.).
        let mut plugin_http_client = crate::plugins::PluginHttpClient::new(
            &global_pool_config,
            dns_cache.clone(),
            env_config_arc.plugin_http_slow_threshold_ms,
            env_config_arc.plugin_http_max_retries,
            env_config_arc.plugin_http_retry_delay_ms,
            env_config_arc.tls_no_verify,
            env_config_arc.tls_ca_bundle_path.as_deref(),
            crls.clone(),
            &env_config_arc.namespace,
            env_config_arc.backend_allow_ips.clone(),
            mesh_egress_strip_baggage_keys.clone(),
            env_config_arc.pool_shard_amount,
        )
        .with_real_ip_header(env_config_arc.real_ip_header.clone())
        .with_compression_algorithms(
            env_config_arc.compression_gzip_enabled,
            env_config_arc.compression_brotli_enabled,
        )
        .with_max_request_body_size_bytes(env_config_arc.max_request_body_size_bytes)
        .with_tls_crl_source(env_config_arc.tls_crl_file_path.clone());
        // Attach the shared SOCK_OPS metrics state when present (mesh
        // node-waypoint only). Plugin construction further down will
        // route `__mesh_bpf_metrics` to use it via `with_state`.
        if let Some(ref state) = bpf_metrics_state {
            plugin_http_client = plugin_http_client.with_bpf_metrics_state(state.clone());
        }
        let plugin_cache = Arc::new(
            PluginCache::with_http_client(&config, plugin_http_client.clone())
                .map_err(|e| anyhow::anyhow!("{}", e))?,
        );
        let plugin_http_client_for_state = plugin_http_client.clone();
        // Build credential-indexed consumer lookup for O(1) auth
        let consumer_index = Arc::new(ConsumerIndex::new(&config.consumers));
        // Build load balancer cache for upstream target selection
        let load_balancer_cache = Arc::new(LoadBalancerCache::new(&config));
        let request_epoch = Arc::new(RequestEpochStore::new(RequestEpoch {
            config: Arc::new(config.clone()),
            proxy_index_by_id: crate::request_epoch::build_proxy_index_by_id(&config),
            route_table: RouterCache::build_route_table_snapshot(&config),
            plugin_cache: plugin_cache.load_inner(),
            consumer_index: consumer_index.load_inner(),
            load_balancer: load_balancer_cache.load_inner(),
            config_generation: 1,
            route_generation: 1,
            lb_generation: 1,
        }));
        // Initialize health checker with the gateway's pool settings so active
        // probes share connection tuning (keep-alive, idle timeout, HTTP/2) with
        // regular proxy traffic.
        let mut health_checker =
            HealthChecker::with_pool_config(&global_pool_config, dns_cache.clone());
        health_checker.set_global_tls_config(
            env_config_arc.tls_ca_bundle_path.clone(),
            env_config_arc.backend_tls_client_cert_path.clone(),
            env_config_arc.backend_tls_client_key_path.clone(),
            env_config_arc.tls_no_verify,
        );
        health_checker.set_load_balancer_cache(load_balancer_cache.clone());
        // Use `start_with_shutdown` so active HTTP probes and the passive
        // recovery timer race their `interval.tick()` against the shutdown
        // watch channel. Without the receiver the inner tasks exit only when
        // `Drop for HealthChecker` aborts them — and `Drop` runs at process
        // exit, after the background-drain phase has already given up. That
        // late abort lets a probe that's mid-`http_probe` finish its TCP /
        // TLS / HTTP round-trip and emit a misleading "unhealthy" log line
        // immediately before the process tears down.
        let health_check_restart_rx = health_check_shutdown_rx.clone();
        health_checker.start_with_shutdown(&config, health_check_shutdown_rx);
        // Drain JoinHandles for mode-side graceful await. AbortHandles stay
        // with HealthChecker so config reload can still cancel this
        // generation; Drop remains a safety net for any undrained tasks.
        let mut health_check_handles = health_checker.take_active_check_handles();
        let health_checker = Arc::new(health_checker);
        // Circuit breaker cache
        let circuit_breaker_cache =
            Arc::new(CircuitBreakerCache::with_max_entries_and_shard_amount(
                env_config_arc.circuit_breaker_cache_max_entries,
                crate::util::sharding::pool_shard_amount(env_config_arc.pool_shard_amount),
            ));
        // Service discovery manager (tasks started later via start_service_discovery)
        let service_discovery_manager = Arc::new(ServiceDiscoveryManager::new(
            load_balancer_cache.clone(),
            dns_cache.clone(),
            health_checker.clone(),
            plugin_http_client,
            Some(request_epoch.clone()),
        ));

        let config_arc = Arc::new(ArcSwap::new(Arc::new(config)));
        health_check_handles.push(spawn_backend_svid_rotation_task(
            backend_svid_rotation_rx,
            backend_svid_generation.clone(),
            BackendSvidRotationConsumer {
                pools: BackendPoolFamily {
                    connection_pool: connection_pool.clone(),
                    http2_pool: http2_pool.clone(),
                    grpc_pool: grpc_pool.clone(),
                    h3_pool: h3_pool.clone(),
                    hbone_pool: hbone_pool.clone(),
                    mesh_mtls_pool: mesh_mtls_pool.clone(),
                },
                health_checker: health_checker.clone(),
                config: config_arc.clone(),
                health_check_shutdown_rx: health_check_restart_rx.clone(),
            },
            env_config_arc.mesh_svid_rotation_drain_seconds,
            health_check_restart_rx.clone(),
        ));

        // Parse stream proxy bind address
        let stream_bind_addr: std::net::IpAddr = env_config_arc
            .stream_proxy_bind_address
            .parse()
            .unwrap_or_else(|_| {
                // Fall back to the proxy bind address, then to IPv4 unspecified
                env_config_arc
                    .proxy_bind_address
                    .parse()
                    .unwrap_or(std::net::IpAddr::V4(std::net::Ipv4Addr::UNSPECIFIED))
            });

        let adaptive_buffer = Arc::new(crate::adaptive_buffer::AdaptiveBufferTracker::new(
            env_config_arc.adaptive_buffer_enabled,
            env_config_arc.adaptive_batch_limit_enabled,
            env_config_arc.adaptive_buffer_ewma_alpha,
            env_config_arc.adaptive_buffer_min_size,
            env_config_arc.adaptive_buffer_max_size,
            env_config_arc.adaptive_buffer_default_size,
            env_config_arc.adaptive_batch_limit_default,
        ));

        let overload = Arc::new(crate::overload::OverloadState::new());

        let stream_listener_manager = Arc::new(
            stream_listener::StreamListenerManager::new_with_epoch_and_mesh_enforcement(
                stream_bind_addr,
                config_arc.clone(),
                dns_cache.clone(),
                request_epoch.clone(),
                circuit_breaker_cache.clone(),
                None, // Frontend TLS for stream proxies is configured per-listener in reconcile()
                env_config_arc.tls_no_verify,
                env_config_arc.tls_ca_bundle_path.clone(),
                env_config_arc.tcp_idle_timeout_seconds,
                env_config_arc.tcp_half_close_max_wait_seconds,
                env_config_arc.frontend_tls_handshake_timeout_seconds,
                env_config_arc.udp_max_sessions,
                env_config_arc.udp_cleanup_interval_seconds,
                tls_policy_arc.clone(),
                crls.clone(),
                adaptive_buffer.clone(),
                env_config_arc.udp_recvmmsg_batch_size,
                {
                    let v = env_config_arc
                        .tcp_fastopen_enabled
                        .resolve(crate::socket_opts::is_tcp_fastopen_available);
                    tracing::info!(enabled = v, config = %env_config_arc.tcp_fastopen_enabled, "TCP_FASTOPEN auto-detection");
                    v
                },
                env_config_arc.tcp_listen_backlog,
                env_config_arc.accept_threads,
                env_config_arc.tcp_fastopen_queue_len,
                overload.clone(),
                {
                    let v = env_config_arc
                        .ktls_enabled
                        .resolve(crate::socket_opts::ktls::is_ktls_available);
                    if v {
                        tracing::info!(
                            "kTLS auto-detection: enabled (full key install probe passed)"
                        );
                    } else {
                        tracing::info!(config = %env_config_arc.ktls_enabled, "kTLS auto-detection: disabled");
                    }
                    v
                },
                {
                    let v = env_config_arc
                        .io_uring_splice_enabled
                        .resolve(crate::socket_opts::io_uring_splice::check_io_uring_available);
                    if v {
                        tracing::info!(
                            "io_uring splice auto-detection: enabled (IORING_OP_SPLICE probe passed)"
                        );
                        // io_uring splice spawns 2 `spawn_blocking` tasks per relayed
                        // TCP connection (one per direction), but concurrent io_uring
                        // relays are semaphore-capped at IO_URING_SPLICE_MAX_CONCURRENT
                        // (128) in tcp_proxy.rs — beyond the cap, additional relays
                        // transparently fall back to the async splice path instead of
                        // queueing on the blocking pool. Worst-case io_uring usage is
                        // therefore 256 blocking threads. Warn only when the configured
                        // pool is smaller than the default 512: 256 io_uring threads
                        // would then crowd out other `spawn_blocking` users.
                        let effective_blocking_threads =
                            env_config_arc.blocking_threads.unwrap_or(512);
                        if effective_blocking_threads < 512 {
                            tracing::warn!(
                                blocking_threads = effective_blocking_threads,
                                "FERRUM_IO_URING_SPLICE_ENABLED=true with FERRUM_BLOCKING_THREADS={} below the 512 default; \
                             io_uring splice can occupy up to 256 blocking threads (128 concurrent relays x 2 directions; \
                             further relays fall back to async splice). \
                             Recommended: FERRUM_BLOCKING_THREADS >= 512 so other spawn_blocking work keeps headroom.",
                                effective_blocking_threads
                            );
                        }
                    } else {
                        tracing::info!(config = %env_config_arc.io_uring_splice_enabled, "io_uring splice auto-detection: disabled");
                    }
                    v
                },
                // Mesh-mode TCP/UDP stream listeners may terminate inbound mTLS
                // (sidecar, east-west, egress); their handshake failures must
                // increment the same mesh-mTLS handshake-failure metric as the
                // HBONE/HTTP mesh listeners so operator alerts cover every
                // mesh-frontend TLS surface.
                matches!(
                    env_config_arc.mode,
                    crate::config::env_config::OperatingMode::Mesh
                ),
                env_config_arc.so_busy_poll_us,
                {
                    let v = env_config_arc
                        .udp_gro_enabled
                        .resolve(crate::socket_opts::is_udp_gro_available);
                    // GRO is probed but not active (recv_from lacks cmsg) — log for completeness.
                    tracing::info!(enabled = v, config = %env_config_arc.udp_gro_enabled, "UDP GRO auto-detection (reserved, not active)");
                    v
                },
                {
                    let v = env_config_arc
                        .udp_gso_enabled
                        .resolve(crate::socket_opts::is_udp_gso_available);
                    if v {
                        tracing::info!("UDP GSO auto-detection: enabled (setsockopt probe passed)");
                    } else {
                        tracing::info!(config = %env_config_arc.udp_gso_enabled, "UDP GSO auto-detection: disabled");
                    }
                    v
                },
                {
                    let v = env_config_arc
                        .udp_pktinfo_enabled
                        .resolve(crate::socket_opts::is_udp_pktinfo_available);
                    if v {
                        tracing::info!(
                            "UDP IP_PKTINFO auto-detection: enabled (setsockopt probe passed)"
                        );
                    } else {
                        tracing::info!(config = %env_config_arc.udp_pktinfo_enabled, "UDP IP_PKTINFO auto-detection: disabled");
                    }
                    v
                },
                env_config_arc.pool_shard_amount,
                health_checker.clone(),
                mesh_outbound_enforcement.clone(),
                trusted_proxies.clone(),
            ),
        );

        let state = Self {
            config: config_arc,
            request_epoch,
            dns_cache,
            connection_pool,
            router_cache,
            plugin_cache,
            plugin_http_client: plugin_http_client_for_state,
            consumer_index,
            load_balancer_cache,
            health_checker,
            health_check_shutdown_rx: health_check_restart_rx.clone(),
            circuit_breaker_cache,
            service_discovery_manager,
            request_count: Arc::new(AtomicU64::new(0)),
            status_counts: {
                // Pre-populate common HTTP status codes so the hot path uses
                // DashMap::get() (shared read lock) instead of entry() (write lock).
                // After warmup, virtually all requests hit the fast read path.
                let map = dashmap::DashMap::with_capacity(16);
                for code in [
                    200u16, 201, 204, 301, 302, 304, 400, 401, 403, 404, 405, 408, 429, 500, 502,
                    503, 504,
                ] {
                    map.insert(code, AtomicU64::new(0));
                }
                Arc::new(map)
            },
            grpc_pool,
            http2_pool,
            hbone_pool,
            mesh_mtls_pool,
            h3_pool,
            backend_capabilities,
            backend_capabilities_refresh,
            alt_svc_header,
            via_header_http11,
            via_header_http2,
            via_header_http3,
            add_forwarded_header,
            windowed_metrics: Arc::new(crate::metrics::WindowedMetrics::new(
                env_config_arc.status_metrics_window_seconds,
            )),
            early_data_methods: Arc::new(env_config_arc.tls_early_data_methods.clone()),
            env_config: env_config_arc,
            reserved_gateway_ports: Arc::new(reserved_gateway_ports),
            max_header_size_bytes,
            max_single_header_size_bytes,
            max_header_count,
            max_request_body_size_bytes,
            max_response_body_size_bytes,
            response_buffer_cutoff_bytes,
            h2_coalesce_target_bytes,
            max_url_length_bytes,
            max_query_params,
            max_grpc_recv_size_bytes,
            max_websocket_frame_size_bytes,
            websocket_write_buffer_size,
            websocket_tunnel_mode,
            trusted_proxies,
            websocket_conn_limit,
            h3_websocket_reachable: Arc::new(AtomicBool::new(false)),
            per_ip_request_counts: if max_concurrent_requests_per_ip > 0 {
                Some(Arc::new(dashmap::DashMap::with_shard_amount(
                    pool_shard_amount,
                )))
            } else {
                None
            },
            max_concurrent_requests_per_ip,
            stream_listener_manager,
            started_at: Instant::now(),
            ws_connection_counter: Arc::new(AtomicU64::new(0)),
            tls_policy: tls_policy_arc,
            crls,
            shared_crls,
            overload,
            adaptive_buffer,
            mesh_egress_strip_baggage_keys,
            node_waypoint_identity_resolver: None,
            gateway_svid_bundle,
            gateway_file_svid_bundle,
            gateway_trust_bundles,
            gateway_svid_update_lock: Arc::new(std::sync::Mutex::new(())),
            mesh_inbound_tls,
            mesh_inbound_tls_policy,
            mesh_inbound_spiffe_verifier_active,
            mesh_outbound_enforcement,
            backend_svid_rotation_tx,
            backend_svid_generation,
            bpf_metrics_state,
            backend_conn_limit: Arc::new(
                crate::backend_conn_limit::BackendConnectionLimiter::with_shard_amount(
                    pool_shard_amount,
                ),
            ),
            backend_pending_limit: Arc::new(
                crate::backend_pending_limit::BackendPendingLimiter::with_shard_amount(
                    pool_shard_amount,
                ),
            ),
        };
        if let Some(handle) =
            state.start_gateway_svid_file_rotation_task(health_check_restart_rx.clone())
        {
            health_check_handles.push(handle);
        }
        if let Some(handle) =
            state.start_frontend_dtls_source_reload_task(health_check_restart_rx.clone())
        {
            health_check_handles.push(handle);
        }
        if let Some(handle) = state.start_backend_tls_source_reload_task(health_check_restart_rx) {
            health_check_handles.push(handle);
        }
        Ok((state, health_check_handles))
    }

    /// Return a copy of this state with node-waypoint identity resolution
    /// installed before listeners start accepting traffic.
    pub fn with_node_waypoint_identity_resolver(
        mut self,
        resolver: Arc<NodeWaypointIdentityResolver>,
    ) -> Self {
        self.node_waypoint_identity_resolver = Some(resolver);
        self
    }

    /// Start a background task that periodically removes stale zero-count
    /// entries from `per_ip_request_counts`. Normally entries are cleaned via
    /// the `PerIpRequestGuard` RAII drop, but this sweep catches edge cases
    /// (e.g., task cancellation without guard drop).
    ///
    /// Returns `Some(JoinHandle)` when per-IP tracking is enabled so the
    /// caller can join the task during the background-task drain phase of
    /// graceful shutdown. Returns `None` when
    /// `FERRUM_MAX_CONCURRENT_REQUESTS_PER_IP=0` (no tracking, no task to
    /// spawn). The task exits cleanly on `shutdown_rx` change so it doesn't
    /// wedge shutdown — consistent with `start_backend_capability_refresh_task`,
    /// `dns_cache.start_background_refresh_with_shutdown`, and the overload /
    /// metrics monitors.
    pub fn start_per_ip_cleanup_task(
        &self,
        shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
    ) -> Option<tokio::task::JoinHandle<()>> {
        let counts = self.per_ip_request_counts.as_ref()?.clone();
        let interval_secs = self.env_config.per_ip_cleanup_interval_seconds.max(1);
        Some(tokio::spawn(run_per_ip_cleanup_loop(
            counts,
            interval_secs,
            shutdown_rx,
        )))
    }

    /// Reconcile stream proxy listeners at startup.
    ///
    /// This must be called after `ProxyState::new()` to start TCP/UDP listeners
    /// for any stream proxies in the initial config. Returns an error if any
    /// listener failed to bind its port (e.g., port already in use by another
    /// process). The caller should fail startup on error.
    pub async fn initial_reconcile_stream_listeners(&self) -> Result<(), anyhow::Error> {
        let failures = self.stream_listener_manager.reconcile().await;
        if failures.is_empty() {
            return Ok(());
        }
        let mut msg = String::from("Stream listener(s) failed to bind:\n");
        for (proxy_id, port, err) in &failures {
            msg.push_str(&format!(
                "  - proxy '{}' port {}: {}\n",
                proxy_id, port, err
            ));
        }
        Err(anyhow::anyhow!("{}", msg.trim_end()))
    }

    fn collect_backend_capability_targets(
        &self,
        config: &GatewayConfig,
    ) -> Vec<BackendCapabilityProbeTarget> {
        let upstream_map: HashMap<&str, &Upstream> = config
            .upstreams
            .iter()
            .map(|upstream| (upstream.id.as_str(), upstream))
            .collect();
        let proxy_map: HashMap<&str, &Proxy> = config
            .proxies
            .iter()
            .map(|proxy| (proxy.id.as_str(), proxy))
            .collect();
        let mut seen = std::collections::HashSet::new();
        let mut targets = Vec::new();

        for proxy in &config.proxies {
            if !proxy.dispatch_kind.is_http_family() {
                continue;
            }

            if let Some(ref upstream_id) = proxy.upstream_id
                && let Some(upstream) = upstream_map.get(upstream_id.as_str())
            {
                for target in &upstream.targets {
                    // SKIP cross-cluster east-west HBONE targets: they dial the
                    // operator-declared east-west gateway (`:15443`), never a
                    // probeable workload `:15008`, so a capability probe would
                    // dial the gateway with the WRONG (dial-host) SNI and no
                    // trust-domain scope, AND dispatch already BYPASSES the
                    // registry for them (`can_attempt_hbone_backend`). Enrolling
                    // them would only produce wrong-SNI gateway dials and
                    // reload/startup probe delays. They are emitted onto the
                    // HTTP mesh-egress upstream a config proxy references, so
                    // this proxy-driven walk is where they would otherwise be
                    // collected.
                    if crate::proxy::hbone_pool::target_hbone_cross_cluster(target) {
                        continue;
                    }
                    let probe_target =
                        BackendCapabilityProbeTarget::from_proxy(proxy, Some(target));
                    if seen.insert(probe_target.key.clone()) {
                        targets.push(probe_target);
                    }
                }
                continue;
            }

            let probe_target = BackendCapabilityProbeTarget::from_proxy(proxy, None);
            if seen.insert(probe_target.key.clone()) {
                targets.push(probe_target);
            }
        }

        self.collect_mesh_route_dispatch_capability_targets(
            config,
            &proxy_map,
            &upstream_map,
            &mut seen,
            &mut targets,
        );
        Self::collect_mesh_tcp_egress_capability_targets(
            config,
            &upstream_map,
            &mut seen,
            &mut targets,
        );

        self.backend_capabilities.retain_keys(&seen);

        // Screen denied-literal probe targets: capability classification dials
        // backends with reqwest/H2/H3 probes that skip the DnsCacheResolver for
        // IP literals, so a blocked address (e.g. 169.254.169.254) would be
        // probed at startup/reload even when a DB-sourced row only warned at
        // load. Dropping it leaves the target `Unknown`, which routes via
        // reqwest at dispatch and is rejected there by the same policy.
        {
            let egress_policy = &self.env_config.backend_allow_ips;
            targets.retain(|target| {
                // Screen BOTH the probe's backend host literal AND a literal
                // `dns_override`: the H3/H2/reqwest capability probes dial via
                // `resolve_backend_addr_cached`, whose IP-literal fast path skips
                // the `DnsCacheResolver`, so a denied literal in EITHER field would
                // be dialed at startup/reload (e.g. a QUIC probe to 169.254.169.254)
                // even when a DB-sourced row only warned at load. Mirrors the
                // request-path `denied_literal_backend_or_dns_override` guard;
                // dropping the target leaves it `Unknown`, which routes via reqwest
                // at dispatch and is rejected there by the same policy.
                match denied_literal_backend_or_dns_override(
                    target.host(),
                    &target.proxy,
                    egress_policy,
                ) {
                    Some(reason) => {
                        warn!(
                            host = %target.host(),
                            dns_override = ?target.proxy.dns_override,
                            reason,
                            "Skipping capability probe for egress-policy-denied backend"
                        );
                        false
                    }
                    None => true,
                }
            });
        }
        targets
    }

    /// Enroll the raw-TCP mesh egress upstreams' targets for HBONE capability
    /// probing. These upstreams are referenced by NO config proxy (the relay
    /// proxy is synthesized at route-table build, never pushed into
    /// `config.proxies`), so the proxy-driven walk above never sees them —
    /// without this pass their records would never be probed AND
    /// `retain_keys` would evict them, permanently failing the raw-TCP
    /// dispatch gate closed. Probe targets are built from the SAME
    /// deterministic relay-proxy builder the dispatch table uses, so probe
    /// and dispatch capability keys agree by construction.
    fn collect_mesh_tcp_egress_capability_targets(
        config: &GatewayConfig,
        upstream_map: &HashMap<&str, &Upstream>,
        seen: &mut std::collections::HashSet<String>,
        targets: &mut Vec<BackendCapabilityProbeTarget>,
    ) {
        let Some(mesh) = config.mesh.as_deref() else {
            return;
        };
        for service in &mesh.services {
            for sp in crate::modes::mesh::service_tcp_stream_ports(service) {
                let upstream_id = crate::modes::mesh::mesh_outbound_tcp_upstream_id(
                    &service.namespace,
                    &service.name,
                    sp.port,
                );
                let Some(upstream) = upstream_map.get(upstream_id.as_str()) else {
                    continue;
                };
                let mut relay_proxy = crate::modes::mesh::mesh_outbound_tcp_relay_proxy(
                    &service.namespace,
                    &service.name,
                    sp.port,
                    &upstream_id,
                );
                relay_proxy.dispatch_port_overrides =
                    Self::projected_dispatch_overrides_for_upstream(config, &upstream_id);
                for target in &upstream.targets {
                    // Only Ambient `mesh.hbone` targets use the HBONE capability
                    // registry. Sidecar `mesh.mtls` raw-TCP targets dispatch over
                    // a mesh-mTLS CONNECT tunnel with NO capability probe
                    // (slice-declared sidecars speak mesh-mTLS by construction),
                    // so enrolling them would dial a non-existent `:15008` HBONE
                    // listener and record a spurious unsupported verdict. Also
                    // skip cross-cluster east-west targets: they dial the
                    // operator gateway `:15443`, never a probeable workload
                    // `:15008`, and L4 dispatch bypasses the registry.
                    if !crate::proxy::hbone_pool::target_hbone_enabled(target)
                        || crate::proxy::hbone_pool::target_hbone_cross_cluster(target)
                    {
                        continue;
                    }
                    let probe_target =
                        BackendCapabilityProbeTarget::from_proxy(&relay_proxy, Some(target));
                    if seen.insert(probe_target.key.clone()) {
                        targets.push(probe_target);
                    }
                }
            }
        }

        // Second pass: the DIRECT-pod-IP / headless per-workload raw-TCP egress
        // upstreams (F3 §3.4). Same trap as the VIP upstreams — referenced by NO
        // config proxy, so without enrollment `retain_keys` evicts their HBONE
        // records and every Ambient by-workload dial 502s `hbone_required`
        // forever. Built from the SAME deterministic per-workload relay proxy the
        // index/dispatch use, so probe and dispatch capability keys agree.
        // `mesh.mtls` (Sidecar) per-workload targets are skipped (no probe),
        // exactly like the VIP pass.
        for spec in crate::modes::mesh::mesh_outbound_tcp_bywl_upstreams(
            &mesh.services,
            &mesh.workloads,
            mesh.multi_cluster.as_ref(),
        ) {
            let Some(upstream) = upstream_map.get(spec.upstream_id.as_str()) else {
                continue;
            };
            let mut relay_proxy = crate::modes::mesh::mesh_outbound_tcp_bywl_relay_proxy(
                &spec.service.namespace,
                &spec.service.name,
                spec.service_port.port,
                spec.canonical_ip,
                &spec.upstream_id,
            );
            relay_proxy.dispatch_port_overrides =
                Self::projected_dispatch_overrides_for_upstream(config, &spec.upstream_id);
            for target in &upstream.targets {
                // Ambient `mesh.hbone` per-workload targets only; Sidecar
                // `mesh.mtls` (no probe) and cross-cluster east-west targets
                // (gateway-dialed, registry-bypassed) are excluded — same
                // rationale as the VIP pass above.
                if !crate::proxy::hbone_pool::target_hbone_enabled(target)
                    || crate::proxy::hbone_pool::target_hbone_cross_cluster(target)
                {
                    continue;
                }
                let probe_target =
                    BackendCapabilityProbeTarget::from_proxy(&relay_proxy, Some(target));
                if seen.insert(probe_target.key.clone()) {
                    targets.push(probe_target);
                }
            }
        }

        // Third pass: the UDP egress upstreams (F3 §3.3 Stage 4). Same trap as
        // the raw-TCP VIP upstreams — referenced by NO config proxy, so without
        // enrollment `retain_keys` evicts their HBONE records and every Ambient
        // UDP dial 502s `hbone_required` forever. Built from the SAME
        // deterministic UDP relay proxy the route table / dispatch use, so probe
        // and dispatch capability keys agree. UDP egress is now dual-transport
        // (#1808): Ambient `mesh.hbone` UDP targets ARE enrolled (HBONE capability
        // registry), Sidecar `mesh.mtls` UDP targets are SKIPPED below — they
        // dispatch over a mesh-mTLS CONNECT with NO capability probe (a
        // slice-declared sidecar speaks mesh-mTLS by construction), and probing
        // them would dial a non-existent `:15008` HBONE listener and record a
        // spurious unsupported verdict (mirrors the raw-TCP passes).
        for service in &mesh.services {
            for sp in crate::modes::mesh::service_udp_stream_ports(service) {
                let upstream_id = crate::modes::mesh::mesh_outbound_udp_upstream_id(
                    &service.namespace,
                    &service.name,
                    sp.port,
                );
                let Some(upstream) = upstream_map.get(upstream_id.as_str()) else {
                    continue;
                };
                let mut relay_proxy = crate::modes::mesh::mesh_outbound_udp_relay_proxy(
                    &service.namespace,
                    &service.name,
                    sp.port,
                    &upstream_id,
                );
                relay_proxy.dispatch_port_overrides =
                    Self::projected_dispatch_overrides_for_upstream(config, &upstream_id);
                for target in &upstream.targets {
                    // Ambient `mesh.hbone` UDP targets only; Sidecar `mesh.mtls`
                    // (no probe) and cross-cluster east-west targets
                    // (gateway-dialed, registry-bypassed) are excluded — same
                    // rationale as the raw-TCP passes above.
                    if !crate::proxy::hbone_pool::target_hbone_enabled(target)
                        || crate::proxy::hbone_pool::target_hbone_cross_cluster(target)
                    {
                        continue;
                    }
                    let probe_target =
                        BackendCapabilityProbeTarget::from_proxy(&relay_proxy, Some(target));
                    if seen.insert(probe_target.key.clone()) {
                        targets.push(probe_target);
                    }
                }
            }
        }
    }

    fn collect_mesh_route_dispatch_capability_targets(
        &self,
        config: &GatewayConfig,
        proxy_map: &HashMap<&str, &Proxy>,
        upstream_map: &HashMap<&str, &Upstream>,
        seen: &mut std::collections::HashSet<String>,
        targets: &mut Vec<BackendCapabilityProbeTarget>,
    ) {
        for plugin in &config.plugin_configs {
            if !plugin.enabled || plugin.plugin_name != "mesh_route_dispatch" {
                continue;
            }
            let Some(proxy_id) = plugin.proxy_id.as_deref() else {
                continue;
            };
            let Some(base_proxy) = proxy_map.get(proxy_id) else {
                continue;
            };
            if !base_proxy.dispatch_kind.is_http_family() {
                continue;
            }
            let Ok(dispatch_config) =
                MeshRouteDispatchConfig::from_value_normalized(&plugin.config)
            else {
                warn!(
                    plugin_id = %plugin.id,
                    proxy_id = %proxy_id,
                    "Skipping mesh_route_dispatch capability targets: config failed to parse"
                );
                continue;
            };

            for rule in dispatch_config.rules {
                let destination = rule.destination;
                let direct_backend_override = destination.upstream_id.is_none()
                    && (destination.backend_host.is_some() || destination.backend_port.is_some());
                let mut effective_proxy = (*base_proxy).clone();
                if let Some(upstream_id) = destination.upstream_id {
                    effective_proxy.upstream_id = Some(upstream_id.clone());
                    let Some(upstream) = upstream_map.get(upstream_id.as_str()) else {
                        continue;
                    };
                    effective_proxy.resolved_tls = BackendTlsConfig::from_upstream(upstream);
                    for target in &upstream.targets {
                        // SKIP cross-cluster east-west HBONE targets — a
                        // mesh_route_dispatch rule could point at the same mesh
                        // egress upstream; same rationale as the proxy-driven
                        // walk above (dispatch bypasses the registry for them,
                        // probing dials the gateway with the wrong SNI).
                        if crate::proxy::hbone_pool::target_hbone_cross_cluster(target) {
                            continue;
                        }
                        let probe_target = BackendCapabilityProbeTarget::from_proxy(
                            &effective_proxy,
                            Some(target),
                        );
                        if seen.insert(probe_target.key.clone()) {
                            targets.push(probe_target);
                        }
                    }
                    continue;
                }

                if let Some(host) = destination.backend_host {
                    effective_proxy.backend_host = host;
                }
                if let Some(port) = destination.backend_port {
                    effective_proxy.backend_port = port;
                }
                if direct_backend_override {
                    let reset_direct_tls = effective_proxy.upstream_id.is_some();
                    effective_proxy.upstream_id = None;
                    if reset_direct_tls {
                        effective_proxy.resolved_tls = BackendTlsConfig::from_proxy(base_proxy);
                    }
                }
                if let Some(tls) = destination.backend_tls {
                    effective_proxy.resolved_tls = tls;
                }

                let probe_target = BackendCapabilityProbeTarget::from_proxy(&effective_proxy, None);
                if seen.insert(probe_target.key.clone()) {
                    targets.push(probe_target);
                }
            }
        }
    }

    fn build_backend_capability_probe_proxy(proxy: &Proxy) -> Proxy {
        let mut probe_proxy = proxy.clone();
        probe_proxy.backend_connect_timeout_ms = probe_proxy
            .backend_connect_timeout_ms
            .clamp(1, BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP);
        if let Some(overrides) = probe_proxy.dispatch_port_overrides.as_mut() {
            for override_config in overrides.values_mut() {
                if let Some(connect_timeout_ms) = override_config.connect_timeout_ms.as_mut() {
                    *connect_timeout_ms =
                        (*connect_timeout_ms).clamp(1, BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP);
                }
            }
        }
        if let Some(fallback) = probe_proxy.dispatch_port_override_fallback.as_mut()
            && let Some(connect_timeout_ms) = fallback.connect_timeout_ms.as_mut()
        {
            *connect_timeout_ms =
                (*connect_timeout_ms).clamp(1, BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP);
        }
        probe_proxy
    }

    /// Probe one target and build its fresh record.
    ///
    /// `previous` is the caller's pre-probe snapshot, taken once via
    /// `BackendCapabilityRegistry::snapshot_for_probe` and reused as the
    /// compare expectation when the result is committed. Re-reading the
    /// registry here would split the merge input from the commit expectation
    /// and reopen the window this design closes.
    async fn probe_backend_capabilities(
        &self,
        target: &BackendCapabilityProbeTarget,
        previous: &BackendCapabilitySnapshot,
    ) -> BackendCapabilityRecord {
        let scheme = target.scheme();
        let mut record = BackendCapabilityRecord::default();
        // Accumulates *unexpected* probe failures only — connection errors on
        // TLS backends, TLS-config setup errors, and any probe failure against
        // a protocol this target was already proven to support. Expected
        // "backend doesn't speak protocol X" outcomes (e.g., h2c not deployed
        // on a plaintext backend, QUIC not deployed on a TLS backend) drop to
        // debug and record a definitive `Unsupported`, which keeps operators
        // from chasing phantom errors on every refresh cycle.
        let mut errors = Vec::new();
        let probe_proxy = Self::build_backend_capability_probe_proxy(&target.proxy);
        let probe_timeout = Duration::from_millis(probe_proxy.backend_connect_timeout_ms);
        let host = target.host();
        let port = target.port();
        let previous = previous.previous();
        let previous_hbone = previous.map(|record| record.hbone);
        let previous_h2_tls = previous.map(|record| record.plain_http.h2_tls);
        let previous_grpc_h2_tls = previous.map(|record| record.grpc_transport.h2_tls);
        let previous_h1 = previous.map(|record| record.plain_http.h1);
        let previous_h3 = previous.map(|record| record.plain_http.h3);

        match scheme {
            BackendScheme::Http => {
                record.plain_http.h1 = ProtocolSupport::Supported;
                self.probe_h2c(&probe_proxy, probe_timeout, host, port, &mut record)
                    .await;
            }
            BackendScheme::Https => {
                // Run the H2 and H3 probes concurrently against the same
                // backend target. They hit independent transports (TCP+TLS
                // vs. UDP+QUIC), independent pools, and independent rustls
                // configs, so there's no shared state to serialize on.
                // Without this, a backend with slow TLS + slow QUIC would
                // double the per-target wall-clock; `for_each_concurrent`
                // only parallelizes *across* targets, not within one.
                let tls_config_result = self
                    .connection_pool
                    .get_tls_config_for_backend(&probe_proxy);
                let h2_fut = self.probe_h2_tls(
                    H2TlsProbeTarget {
                        probe_proxy: &probe_proxy,
                        probe_timeout,
                        host,
                        port,
                        previous_h2_tls,
                        previous_grpc_h2_tls,
                        previous_h1,
                    },
                    &mut record,
                );
                let h3_fut = Self::probe_h3(
                    &self.h3_pool,
                    &probe_proxy,
                    probe_timeout,
                    tls_config_result,
                    host,
                    port,
                    previous_h3,
                );
                let (_, h3_outcome) = tokio::join!(h2_fut, h3_fut);
                h3_outcome.apply(&mut record, &mut errors);
            }
            BackendScheme::Tcp | BackendScheme::Tcps | BackendScheme::Udp | BackendScheme::Dtls => {
            }
        }
        // `Tcp` and `Udp` join `Http` here for the mesh egress relay targets:
        // their scheme keeps the plain-HTTP/h2c probes away from a raw-TCP /
        // UDP app port (nothing above probes those arms), but HBONE support
        // must still be proven — a UDP egress target rides a `udp`-marked HBONE
        // CONNECT, so without this its HBONE record is never probed AND
        // `retain_keys` evicts it, permanently failing the UDP dispatch gate
        // closed (the same trap as raw-TCP). The probe only performs the CONNECT
        // handshake, identical for both transports.
        if target.hbone_hint
            && matches!(
                scheme,
                BackendScheme::Http | BackendScheme::Tcp | BackendScheme::Udp
            )
        {
            self.probe_hbone(
                &probe_proxy,
                HboneProbeTarget {
                    host,
                    dial_host: target.hbone_dial_host.as_str(),
                    port,
                    policy_port: target.dispatch_policy_port,
                    hbone_port: target.hbone_port,
                    expected_peer: target.hbone_expected_peer.as_ref(),
                    previous_hbone,
                    // A UDP egress target's destination relay expects the `udp`
                    // marker; probe it with the matching datagram CONNECT so the
                    // handshake reaches the right relay (codex r1 P1).
                    is_udp: matches!(scheme, BackendScheme::Udp),
                },
                &mut record,
            )
            .await;
        }

        record.last_probe_at_unix_secs = backend_capabilities::now_unix_secs();
        // `probe_h2_tls` writes its own errors into `record.last_probe_error`
        // directly (it owns `&mut record` alongside the join!-running H3
        // future). `probe_h3`'s errors come back via the outcome struct in
        // `errors`. Merge both sources here.
        if !errors.is_empty() {
            let joined = errors.join("; ");
            match record.last_probe_error.as_mut() {
                Some(existing) => {
                    existing.push_str("; ");
                    existing.push_str(&joined);
                }
                None => record.last_probe_error = Some(joined),
            }
        }
        record
    }

    /// h2c prior-knowledge probe for a plaintext HTTP backend. Borrows
    /// `record` so the outcome is written directly; genuine errors (none
    /// expected for h2c — "backend doesn't speak h2c" is the normal case)
    /// drop to `debug!` and classify as `Unsupported`.
    async fn probe_h2c(
        &self,
        probe_proxy: &Proxy,
        probe_timeout: Duration,
        host: &str,
        port: u16,
        record: &mut BackendCapabilityRecord,
    ) {
        match tokio::time::timeout(probe_timeout, self.grpc_pool.get_sender(probe_proxy)).await {
            Ok(Ok(_)) => {
                record.grpc_transport.h2c = ProtocolSupport::Supported;
            }
            Ok(Err(err)) => {
                record.grpc_transport.h2c = ProtocolSupport::Unsupported;
                debug!(
                    "h2c probe for {}:{} classified unsupported: {}",
                    host, port, err
                );
            }
            Err(_) => {
                debug!(
                    "h2c probe for {}:{} timed out after {}ms; leaving unknown",
                    host, port, probe_proxy.backend_connect_timeout_ms
                );
            }
        }
    }

    /// H2/TLS probe. Borrows `record` so the H2 + H1-fallback outcome is
    /// written directly; unexpected connection failures are surfaced to the
    /// caller via `errors` (this is the genuine "can't reach an HTTPS
    /// backend" signal the operator should see).
    ///
    /// Transient reachability failures (DNS/connect/refused/timeout) preserve
    /// any previously cached H2/H1 classification — matching the HBONE merge
    /// contract — and always stamp `last_probe_error` for operator visibility.
    /// Only ALPN-negotiated HTTP/1.1 is treated as definitive H2-capability
    /// evidence that may downgrade a prior `Supported` entry.
    async fn probe_h2_tls(
        &self,
        target: H2TlsProbeTarget<'_>,
        record: &mut BackendCapabilityRecord,
    ) {
        let H2TlsProbeTarget {
            probe_proxy,
            probe_timeout,
            host,
            port,
            previous_h2_tls,
            previous_grpc_h2_tls,
            previous_h1,
        } = target;
        match tokio::time::timeout(probe_timeout, self.http2_pool.get_sender(probe_proxy)).await {
            Ok(Ok(_)) => {
                record.plain_http.h2_tls = ProtocolSupport::Supported;
                record.grpc_transport.h2_tls = ProtocolSupport::Supported;
            }
            Ok(Err(http2_pool::Http2PoolError::BackendSelectedHttp1 { .. })) => {
                record.plain_http.h1 = ProtocolSupport::Supported;
                record.plain_http.h2_tls = ProtocolSupport::Unsupported;
                record.grpc_transport.h2_tls = ProtocolSupport::Unsupported;
            }
            Ok(Err(err)) => {
                // We need to collect this error for `last_probe_error`, but
                // the outer function writes `errors` and we can't borrow it
                // through the join! Thread the message via
                // `record.last_probe_error` directly instead — the outer
                // function merges this into the combined error string.
                let class = http2_pool::classify_http2_pool_error(&err);
                let preserve = is_transient_capability_probe_failure(class);
                record.plain_http.h2_tls =
                    backend_capabilities::merge_protocol_probe_classification(
                        previous_h2_tls,
                        ProtocolSupport::Unknown,
                        preserve,
                    );
                record.grpc_transport.h2_tls =
                    backend_capabilities::merge_protocol_probe_classification(
                        previous_grpc_h2_tls,
                        ProtocolSupport::Unknown,
                        preserve,
                    );
                record.plain_http.h1 = backend_capabilities::merge_protocol_probe_classification(
                    previous_h1,
                    ProtocolSupport::Unknown,
                    preserve,
                );
                append_probe_error(
                    record,
                    format!("HTTP/2 probe failed for {host}:{port}: {err}"),
                );
            }
            Err(_) => {
                // Timeout is always a transient reachability fault — carry any
                // prior Supported/Unsupported verdict forward instead of
                // resetting this target to Unknown for a whole refresh cycle.
                record.plain_http.h2_tls =
                    backend_capabilities::merge_protocol_probe_classification(
                        previous_h2_tls,
                        ProtocolSupport::Unknown,
                        true,
                    );
                record.grpc_transport.h2_tls =
                    backend_capabilities::merge_protocol_probe_classification(
                        previous_grpc_h2_tls,
                        ProtocolSupport::Unknown,
                        true,
                    );
                record.plain_http.h1 = backend_capabilities::merge_protocol_probe_classification(
                    previous_h1,
                    ProtocolSupport::Unknown,
                    true,
                );
                append_probe_error(
                    record,
                    format!(
                        "HTTP/2 probe timed out for {}:{} after {}ms",
                        host, port, probe_proxy.backend_connect_timeout_ms
                    ),
                );
            }
        }
    }

    async fn probe_hbone(
        &self,
        probe_proxy: &Proxy,
        target: HboneProbeTarget<'_>,
        record: &mut BackendCapabilityRecord,
    ) {
        let host = target.host;
        let dial_host = target.dial_host;
        let port = target.port;
        let hbone_port = target.hbone_port;
        if self.gateway_svid_bundle.load().is_none() {
            record.hbone = ProtocolSupport::Unknown;
            debug!(
                "HBONE probe for {}:{} skipped: gateway SVID is not configured",
                host, port
            );
            return;
        }

        // A UDP egress target rides a `udp`-marked datagram CONNECT, which the
        // destination unframes into a local `UdpSocket`; a byte-stream
        // (`hbone`-marked) probe would hit the wrong relay there. Probe with the
        // SAME marker the dispatch path uses so the handshake proves the
        // capability the egress datapath actually needs (codex r1 P1).
        let warmup = async {
            if target.is_udp {
                self.hbone_pool
                    .warmup_datagram_connection_via(
                        probe_proxy,
                        dial_host,
                        host,
                        port,
                        target.policy_port,
                        hbone_port,
                        target.expected_peer,
                    )
                    .await
            } else {
                self.hbone_pool
                    .warmup_connection_via(
                        probe_proxy,
                        dial_host,
                        host,
                        port,
                        target.policy_port,
                        hbone_port,
                        target.expected_peer,
                    )
                    .await
            }
        };
        let probe_timeout_ms = hbone_pool::effective_connect_timeout_ms_for_policy_port(
            probe_proxy,
            target.policy_port,
        );
        match tokio::time::timeout(Duration::from_millis(probe_timeout_ms), warmup).await {
            Ok(Ok(())) => {
                record.hbone = ProtocolSupport::Supported;
            }
            Ok(Err(err)) => {
                if err.is_capability_failure() {
                    record.hbone = ProtocolSupport::Unsupported;
                } else if let Some(previous) = target.previous_hbone {
                    record.hbone = previous;
                }
                append_probe_error(
                    record,
                    format!("HBONE probe failed for {host}:{port} via port {hbone_port}: {err}"),
                );
                debug!(
                    "HBONE probe for {}:{} via port {} classified unsupported: {}",
                    host, port, hbone_port, err
                );
            }
            Err(_) => {
                if let Some(previous) = target.previous_hbone {
                    record.hbone = previous;
                }
                append_probe_error(
                    record,
                    format!(
                        "HBONE probe timed out for {}:{} via port {} after {}ms",
                        host, port, hbone_port, probe_timeout_ms
                    ),
                );
                debug!(
                    "HBONE probe for {}:{} via port {} timed out after {}ms; leaving unknown",
                    host, port, hbone_port, probe_timeout_ms
                );
            }
        }
    }

    /// H3 / QUIC probe. Returns an outcome the caller merges into `record` +
    /// the outer `errors` vec. Takes `&Arc<Http3ConnectionPool>` plus a
    /// pre-computed `tls_config_result` so the synchronous TLS-config build
    /// (a real error case) is folded in without duplicating the timeout
    /// handling. Written as an associated fn so it can be polled via
    /// `tokio::join!` alongside `probe_h2_tls` (which borrows `&mut record`)
    /// without aliasing `self`.
    ///
    /// Transient DNS/connect/refused/timeout failures preserve an existing
    /// `previous_h3` classification (HBONE merge contract); only non-transient
    /// transport/protocol evidence downgrades a cached verdict to
    /// `Unsupported`. A first probe with no prior verdict still classifies
    /// definitively, so a plain HTTPS backend that never speaks QUIC keeps
    /// recording `Unsupported` instead of an unclassifiable `Unknown`.
    ///
    /// A probe failure against a target previously classified `Supported`
    /// stamps an operator-visible `last_probe_error` — that is either a real
    /// downgrade or a preserved-but-stale record, and both are worth seeing in
    /// `GET /backend-capabilities`. Expected "this backend has no QUIC
    /// listener" outcomes stay silent (see `probe_backend_capabilities`).
    async fn probe_h3(
        h3_pool: &Arc<Http3ConnectionPool>,
        probe_proxy: &Proxy,
        probe_timeout: Duration,
        tls_config_result: Result<Arc<rustls::ClientConfig>, anyhow::Error>,
        host: &str,
        port: u16,
        previous_h3: Option<ProtocolSupport>,
    ) -> H3ProbeOutcome {
        let tls_config = match tls_config_result {
            Ok(cfg) => cfg,
            Err(err) => {
                // TLS config build failures are local/config faults, not
                // evidence the backend lost QUIC — preserve any prior
                // classification and surface the error.
                return H3ProbeOutcome {
                    h3: backend_capabilities::merge_protocol_probe_classification(
                        previous_h3,
                        ProtocolSupport::Unknown,
                        true,
                    ),
                    error: Some(format!("HTTP/3 TLS config failed for {host}:{port}: {err}")),
                };
            }
        };

        match tokio::time::timeout(
            probe_timeout,
            h3_pool.warmup_connection(probe_proxy, &tls_config),
        )
        .await
        {
            Ok(Ok(())) => H3ProbeOutcome {
                h3: ProtocolSupport::Supported,
                error: None,
            },
            Ok(Err(err)) => {
                let class = crate::http3::client::classify_http3_error(err.as_ref());
                let preserve = is_transient_capability_probe_failure(class);
                let h3 = backend_capabilities::merge_protocol_probe_classification(
                    previous_h3,
                    ProtocolSupport::Unsupported,
                    preserve,
                );
                if preserve && matches!(h3, ProtocolSupport::Supported) {
                    debug!(
                        "HTTP/3 probe for {}:{} transient failure ({:?}); preserving {:?}: {}",
                        host, port, class, h3, err
                    );
                } else {
                    debug!(
                        "HTTP/3 probe for {}:{} classified {:?}: {}",
                        host, port, h3, err
                    );
                }
                H3ProbeOutcome {
                    h3,
                    error: h3_probe_failure_error(
                        previous_h3,
                        format!("HTTP/3 probe failed for {host}:{port}: {err}"),
                    ),
                }
            }
            Err(_) => {
                let h3 = backend_capabilities::merge_protocol_probe_classification(
                    previous_h3,
                    ProtocolSupport::Unknown,
                    true,
                );
                debug!(
                    "HTTP/3 probe for {}:{} timed out after {}ms; classified {:?}",
                    host, port, probe_proxy.backend_connect_timeout_ms, h3
                );
                H3ProbeOutcome {
                    h3,
                    error: h3_probe_failure_error(
                        previous_h3,
                        format!(
                            "HTTP/3 probe timed out for {}:{} after {}ms",
                            host, port, probe_proxy.backend_connect_timeout_ms
                        ),
                    ),
                }
            }
        }
    }

    pub async fn refresh_backend_capabilities(&self) {
        let cap = self.env_config.pool_warmup_concurrency.max(1);
        let semaphore = Arc::new(Semaphore::new(cap));
        self.refresh_backend_capabilities_with_semaphore(semaphore, cap)
            .await;
    }

    /// Inner implementation of `refresh_backend_capabilities` that takes an
    /// externally-supplied semaphore plus the configured polling buffer
    /// size. The startup `warmup_connection_pools` path uses this entry
    /// point to share a single concurrency budget across the capability
    /// refresh AND the parallel HTTP reqwest warmup batch — without it,
    /// each `for_each_concurrent` independently honours its own
    /// `pool_warmup_concurrency` cap, doubling (or worse) the effective
    /// fanout when both batches run via `tokio::join!`. The public
    /// `refresh_backend_capabilities()` wrapper preserves the
    /// background-refresh semantics by minting a per-call semaphore.
    ///
    /// `polling_buffer` is the configured `pool_warmup_concurrency` cap,
    /// NOT `semaphore.available_permits()`. The semaphore can be
    /// momentarily drained by the parallel HTTP warmup batch at the
    /// moment this function is entered (or vice-versa), which would
    /// clamp the polling buffer and serialize subsequent work. Passing
    /// the configured cap keeps the polling window stable.
    pub(crate) async fn refresh_backend_capabilities_with_semaphore(
        &self,
        semaphore: Arc<Semaphore>,
        polling_buffer: usize,
    ) {
        use futures_util::stream;

        let config = self.config.load_full();
        let targets = self.collect_backend_capability_targets(&config);
        if targets.is_empty() {
            debug!("Backend capability refresh: no HTTP-family backends to classify");
            return;
        }

        let buffer = polling_buffer.max(1);
        let refreshed = Arc::new(AtomicU64::new(0));
        let h2_supported = Arc::new(AtomicU64::new(0));
        let h3_supported = Arc::new(AtomicU64::new(0));
        let h2c_supported = Arc::new(AtomicU64::new(0));
        let hbone_supported = Arc::new(AtomicU64::new(0));
        // Probes whose write-back lost to newer registry state (a request-path
        // downgrade, or a `retain_keys` eviction) during the probe window.
        let conflicts = Arc::new(AtomicU64::new(0));

        stream::iter(targets)
            .for_each_concurrent(buffer, |target| {
                let state = self.clone();
                let refreshed = refreshed.clone();
                let h2_supported = h2_supported.clone();
                let h3_supported = h3_supported.clone();
                let h2c_supported = h2c_supported.clone();
                let hbone_supported = hbone_supported.clone();
                let conflicts = conflicts.clone();
                let semaphore = semaphore.clone();
                async move {
                    // Same rule as `run_warmup_task_batch`: prefer
                    // explicit Err handling over `.expect()` so a
                    // future refactor that closes the semaphore can't
                    // panic the startup path. Skip the probe — the next
                    // periodic refresh will pick it up.
                    let _permit = match semaphore.acquire_owned().await {
                        Ok(permit) => permit,
                        Err(e) => {
                            warn!(
                                "Backend capability refresh: semaphore closed before acquire ({e}); skipping target {}:{}",
                                target.host(),
                                target.port()
                            );
                            return;
                        }
                    };
                    // ONE pre-probe observation, used both as the merge input
                    // (`previous_*` classifications inside the probe) and as
                    // the compare expectation for the write-back below. A
                    // second independent read would leave exactly the window
                    // this protocol closes.
                    let registry = &state.backend_capabilities;
                    let snapshot = registry.snapshot_for_probe(&target.key);
                    let record = state.probe_backend_capabilities(&target, &snapshot).await;
                    // Compare-and-commit: the probe may replace only the
                    // version it was computed against. A request-path
                    // downgrade (`mark_h3_unsupported` /
                    // `mark_h2_tls_unsupported` / `mark_hbone_unsupported`)
                    // landing during the probe window publishes a new `Arc`,
                    // so this write loses and the newer live record survives.
                    let outcome = registry.commit_probe(target.key.clone(), &snapshot, record);
                    let committed = match outcome {
                        CapabilityCommitOutcome::Committed(committed) => committed,
                        rejected => {
                            // Counters and the summary line describe committed
                            // registry state only — a discarded probe must not
                            // be reported as this target's classification.
                            conflicts.fetch_add(1, Ordering::Relaxed);
                            debug!(
                                proxy_id = %target.proxy.id,
                                backend_host = %target.host(),
                                backend_port = target.port(),
                                reason = rejected.reason(),
                                "Backend capability probe result discarded; live registry state is newer"
                            );
                            return;
                        }
                    };
                    if let Some(previous) = snapshot.previous() {
                        warn_capability_supported_regression(&target, previous, &committed);
                    }
                    if committed.plain_http.h2_tls.is_supported() {
                        h2_supported.fetch_add(1, Ordering::Relaxed);
                    }
                    if committed.plain_http.h3.is_supported() {
                        h3_supported.fetch_add(1, Ordering::Relaxed);
                    }
                    if committed.grpc_transport.h2c.is_supported() {
                        h2c_supported.fetch_add(1, Ordering::Relaxed);
                    }
                    if committed.hbone.is_supported() {
                        hbone_supported.fetch_add(1, Ordering::Relaxed);
                    }
                    refreshed.fetch_add(1, Ordering::Relaxed);
                }
            })
            .await;

        // Every tally below is drawn from records this refresh actually
        // committed. Targets whose probe lost the compare-and-commit are
        // reported separately as `discarded` — they keep the newer live
        // classification, so folding them into the protocol counts would
        // misreport the registry.
        info!(
            "Backend capability refresh complete: {} backends classified (h2_tls={}, h3={}, h2c={}, hbone={}), {} probe results discarded in favor of newer live state",
            refreshed.load(Ordering::Relaxed),
            h2_supported.load(Ordering::Relaxed),
            h3_supported.load(Ordering::Relaxed),
            h2c_supported.load(Ordering::Relaxed),
            hbone_supported.load(Ordering::Relaxed),
            conflicts.load(Ordering::Relaxed),
        );
    }

    /// Request a capability refresh in the background, coalescing overlapping
    /// requests. Callers are fire-and-forget: if a refresh is already running,
    /// this returns immediately and the in-flight task re-drains `pending`
    /// after it completes, so config changes that arrived mid-refresh are
    /// still picked up without spawning N duplicate tasks or orphaning the
    /// queued request.
    pub(crate) fn spawn_backend_capability_refresh(&self) {
        if !self.backend_capabilities_refresh.request() {
            debug!("Backend capability refresh coalesced into in-flight task");
            return;
        }
        let state = self.clone();
        tokio::spawn(async move {
            loop {
                while state.backend_capabilities_refresh.take_pending() {
                    state.refresh_backend_capabilities().await;
                }
                // Handoff-safe finish: if a caller set `pending` between
                // our last `take_pending()` and `try_finish()`, we either
                // re-acquire the runner role (return `false`, loop back to
                // drain again) or observe that someone else has become the
                // runner in the meantime (return `true`, exit).
                if state.backend_capabilities_refresh.try_finish() {
                    break;
                }
            }
        });
    }

    /// Start the periodic background refresh task.
    ///
    /// `run_initial_refresh` controls whether this method kicks off an
    /// immediate refresh before the first interval tick:
    /// - Callers that already populated the registry via
    ///   `warmup_connection_pools().await` should pass `false` (the skip
    ///   avoids a duplicate probe at startup).
    /// - Callers that did NOT run warmup (DP mode always, or file/db mode
    ///   when `FERRUM_POOL_WARMUP_ENABLED=false`) must pass `true` —
    ///   otherwise the registry stays empty until the first periodic tick
    ///   (default 24 h), which means `supports_native_http3_backend` /
    ///   `supports_direct_http2_backend` return `false` for every
    ///   HTTPS request during that window and H3-only backends see
    ///   persistent cross-protocol-bridge failures.
    pub fn start_backend_capability_refresh_task(
        &self,
        run_initial_refresh: bool,
        shutdown: Option<tokio::sync::watch::Receiver<bool>>,
    ) {
        if run_initial_refresh {
            self.spawn_backend_capability_refresh();
        }
        let state = self.clone();
        let interval_secs = self
            .env_config
            .backend_capability_refresh_interval_secs
            .max(1);

        tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_secs(interval_secs));
            // Skip the first immediate tick: either warmup or the explicit
            // `run_initial_refresh` call above has already kicked off a
            // probe, or the operator genuinely has no HTTP-family backends
            // and a no-op tick is harmless. From here on, only the
            // periodic cadence matters.
            interval.tick().await;

            match shutdown {
                Some(mut shutdown_rx) => loop {
                    tokio::select! {
                        _ = interval.tick() => {
                            state.spawn_backend_capability_refresh();
                        }
                        _ = shutdown_rx.changed() => break,
                    }
                },
                None => loop {
                    interval.tick().await;
                    state.spawn_backend_capability_refresh();
                },
            }
        });
    }

    /// Pre-establish backend connections for all HTTP-family proxies.
    ///
    /// Two-phase startup:
    ///
    /// 1. **Capability refresh in parallel with HTTP-only reqwest warmup.**
    ///    The capability probes warm the gRPC, direct HTTP/2, and HTTP/3
    ///    pools for targets that support those transports. They classify
    ///    backends so the request hot path can decide between the native
    ///    H2/H3 pools and the reqwest fallback. The reqwest HEAD warmup
    ///    for plain-HTTP backends has no capability dependency (h2c is
    ///    only consulted for gRPC dispatch), so it overlaps the refresh
    ///    via `tokio::join!` — both batches share `for_each_concurrent`
    ///    parallelism but the wall-clock costs no longer stack.
    ///
    /// 2. **HTTPS reqwest warmup with capability + needs-reqwest +
    ///    H3-frontend gating.** After the refresh has populated the
    ///    registry, an HTTPS target's reqwest HEAD is skipped iff ALL
    ///    three guards pass; if any fails we warm reqwest. The guards:
    ///
    ///    **(1) Capability**: registry classifies the target
    ///    `plain_http.h2_tls = Supported`, so the direct H2 pool can
    ///    talk to it for H1/H2 frontend traffic.
    ///
    ///    **(2) Needs-reqwest**: no proxy routing to the target has a
    ///    configuration that forces reqwest dispatch — i.e.
    ///    `requires_reqwest_warmup` is `false` after OR-merging across
    ///    every sharing proxy. See `proxy_config_forces_reqwest_dispatch`
    ///    for the guard set: `pool_enable_http2`, retain-request-body
    ///    retries, request-body-buffering plugins.
    ///
    ///    **(3) H3 frontend disabled** (`env_config.enable_http3 == false`):
    ///    the `http3::cross_protocol::run` bridge sends ALL non-native-H3
    ///    backend traffic from H3 frontend clients through reqwest (gRPC
    ///    over H3 always; Plain over H3 when backend `h3=Unsupported`),
    ///    regardless of what the direct H2 pool would do for the same
    ///    request from an H1/H2 frontend client. With H3 enabled we
    ///    conservatively warm reqwest for every HTTPS target.
    ///
    ///    If H2/TLS silently downgrades at runtime (handled by
    ///    `mark_h2_tls_unsupported`), the first fallback request pays a
    ///    cold connect — acceptable recovery cost vs. paying a redundant
    ///    TLS handshake at startup for every H2/TLS-capable target.
    pub async fn warmup_connection_pools(&self) {
        let config = self.config.load_full();
        let concurrency = self.env_config.pool_warmup_concurrency.max(1);
        // Single shared semaphore for the whole warmup. Phase-1 hands one
        // copy to the capability refresh and another to the HTTP reqwest
        // warmup batch (running in `tokio::join!`); phase-2 gets the same
        // semaphore. Without this, each `for_each_concurrent` would
        // independently honour `pool_warmup_concurrency` and the joined
        // batches would burst to ~2× (or more, since per-HTTPS-target
        // probes also `tokio::join!` H2 + H3 internally) — overloading
        // backends and breaking the operator-set cap.
        let warmup_semaphore = Arc::new(Semaphore::new(concurrency));
        let upstream_map: HashMap<&str, &crate::config::types::Upstream> = config
            .upstreams
            .iter()
            .map(|upstream| (upstream.id.as_str(), upstream))
            .collect();

        // Collect ALL reqwest warmup candidates upfront, partitioned by
        // scheme so each phase can build its own task list. Each bucket is
        // a `HashMap<dedup_key, ReqwestWarmupCandidate>` keyed by
        // `{pool_key}|{host}:{port}` — the connection pool's TLS-aware
        // client identity composed with the per-target host:port. This
        // dedup contract:
        //   - Same pool_key + same target → one HEAD (multiple proxies
        //     sharing identical TLS + backend collapse correctly).
        //   - Same pool_key + different targets → one HEAD per target
        //     (a load-balanced upstream warms each backend connection
        //     in the shared `reqwest::Client`'s internal pool).
        //   - Different pool_keys + same target → one HEAD per pool
        //     (proxies that point at the same backend with divergent TLS
        //     end up with separate `reqwest::Client`s — each one needs
        //     its own warm connection or the first request through
        //     whichever client wasn't warmed pays a cold connect).
        // Upper-bound capacity at proxy count. Real candidate count can
        // exceed this when upstreams expand multiple targets, but the
        // hint avoids the ~log2(N) rehashes default-sized maps would do
        // under N inserts; if it's an undercount the HashMap auto-grows
        // exactly once or twice — still cheaper than starting from 4.
        let cap_hint = config.proxies.len();
        let mut http_candidates: HashMap<String, ReqwestWarmupCandidate> =
            HashMap::with_capacity(cap_hint);
        let mut https_candidates: HashMap<String, ReqwestWarmupCandidate> =
            HashMap::with_capacity(cap_hint);
        let pool_config = self.connection_pool.global_pool_config();
        // Candidates are computed from the BASE `proxy` here — before any
        // `resolve_effective_proxy_for_target` per-port resolution. One
        // consequence (P3, intentional): a DestinationRule
        // `h2UpgradePolicy: DO_NOT_UPGRADE` per-port override builds a SEPARATE
        // force-H1 reqwest client (ALPN restricted to `http/1.1`, distinct
        // force-H1 pool key) that is NOT pre-warmed here. This is correct, only
        // unoptimized: that client is built LAZILY on its first real dispatch
        // under its own pool key, so behavior is identical — only the one-time
        // warm-connection is missed for the force-H1 client. Resolving effective
        // proxies during warmup is a broader change tracked as a follow-up; see
        // `docs/mesh.md` "Warmup pre-warm of DR force-H1 clients".
        for proxy in &config.proxies {
            if !proxy.dispatch_kind.is_http_family() {
                continue;
            }
            // Mirror the runtime dispatch decision: would this proxy ever
            // route a request via reqwest? If yes, the warmup gating must
            // keep the reqwest HEAD even when the capability registry says
            // h2_tls=Supported. The flag is OR-merged across every proxy
            // sharing the dedup key — one reqwest-forcing proxy is enough
            // to keep the pool warm.
            let per_proxy_pool = pool_config.for_proxy(proxy);
            let requires_request_body_buffering =
                self.plugin_cache.requires_request_body_buffering(&proxy.id);
            let forces_reqwest = proxy_config_forces_reqwest_dispatch(
                proxy,
                per_proxy_pool.enable_http2,
                requires_request_body_buffering,
            );
            let pool_key = self.connection_pool.pool_key_for_warmup(proxy);
            collect_reqwest_warmup_candidates_for_proxy(
                proxy,
                &pool_key,
                forces_reqwest,
                &upstream_map,
                &mut http_candidates,
                &mut https_candidates,
            );
        }

        // Drop any warmup candidate whose backend is a literal IP denied by the
        // egress policy: startup must never issue a HEAD/capability probe to a
        // blocked address (e.g. 169.254.169.254) even when a DB-sourced row only
        // warned at load. Hostname candidates are screened at resolve time by the
        // DnsCacheResolver plugged into every warmup client.
        {
            let egress_policy = &self.env_config.backend_allow_ips;
            let denied_literal = |candidate: &ReqwestWarmupCandidate| -> bool {
                // Warmup dials are reqwest HEAD/capability probes, so screen with
                // the URL-canonicalizing `egress_literal_ip` (matches the request
                // path) — a non-canonical literal like `2852039166` would
                // otherwise be probed straight to the metadata IP.
                crate::config::types::egress_literal_ip(&candidate.host)
                    .and_then(|ip| egress_policy.deny_reason(&ip))
                    .inspect(|reason| {
                        warn!(
                            host = %candidate.host,
                            port = candidate.port,
                            reason,
                            "Skipping warmup probe for egress-policy-denied backend"
                        );
                    })
                    .is_some()
            };
            http_candidates.retain(|_, candidate| !denied_literal(candidate));
            https_candidates.retain(|_, candidate| !denied_literal(candidate));
        }

        // Phase 1: capability refresh ‖ HTTP-only reqwest warmup. HTTP
        // candidates always warm — the direct H2 pool is HTTPS-only, so
        // HTTP backends have no alternative dispatch path. Both batches
        // share the same semaphore (concurrency cap) AND get the same
        // configured polling buffer — see `run_warmup_task_batch` for
        // why we don't size the buffer from `available_permits()`.
        let http_tasks: Vec<WarmupTask> = http_candidates
            .into_values()
            .map(|c| Self::build_reqwest_warmup_task(self.connection_pool.clone(), c))
            .collect();
        let http_label = "reqwest http";
        let refresh_fut =
            self.refresh_backend_capabilities_with_semaphore(warmup_semaphore.clone(), concurrency);
        let http_warmup_fut = run_warmup_task_batch(
            http_tasks,
            warmup_semaphore.clone(),
            concurrency,
            http_label,
        );
        tokio::join!(refresh_fut, http_warmup_fut);

        // Phase 2: HTTPS reqwest warmup with capability + needs-reqwest
        // gating. Skip iff ALL of these hold for the target:
        //   1. The capability registry classifies it h2_tls=Supported (so
        //      the direct H2 pool can talk to the backend for H1/H2
        //      frontend traffic), AND
        //   2. No proxy routing to this target has a configuration that
        //      forces reqwest dispatch — i.e. `requires_reqwest_warmup`
        //      is `false` after OR-merging all sharing proxies, AND
        //   3. The HTTP/3 frontend listener is NOT enabled. The
        //      `http3::cross_protocol::run` bridge sends ALL non-native-H3
        //      backend traffic from H3 frontend clients through
        //      `connection_pool.get_client(proxy)` (reqwest), regardless of
        //      whether the direct H2 pool would have served the same
        //      request from an H1/H2 frontend client. That means:
        //      - gRPC over H3 frontend → reqwest (always cross-protocol)
        //      - Plain over H3 frontend when backend `h3=Unsupported` →
        //        reqwest (cross-protocol fallback)
        //      We can't predict at warmup time whether a proxy will see
        //      H3 frontend traffic of either flavor, so the safe rule is:
        //      H3 enabled ⇒ keep reqwest warm for every HTTPS target.
        // If any condition is false we warm reqwest.
        let h3_frontend_enabled = self.env_config.enable_http3;
        let total_https_candidates = https_candidates.len();
        let mut https_tasks: Vec<WarmupTask> = Vec::with_capacity(total_https_candidates);
        let mut skipped_h2_tls = 0usize;
        for (_key, candidate) in https_candidates {
            let h2_tls_covered = target_uses_direct_h2_pool(
                &self.backend_capabilities,
                &candidate.proxy,
                &candidate.host,
                candidate.port,
            );
            if h2_tls_covered && !candidate.requires_reqwest_warmup && !h3_frontend_enabled {
                debug!(
                    "Pool warmup: skipping reqwest HEAD for {}:{} (direct H2 pool covers every routing proxy, H3 frontend disabled)",
                    candidate.host, candidate.port
                );
                skipped_h2_tls += 1;
                continue;
            }
            https_tasks.push(Self::build_reqwest_warmup_task(
                self.connection_pool.clone(),
                candidate,
            ));
        }
        if skipped_h2_tls > 0 {
            info!(
                "Pool warmup: gating skipped {} of {} HTTPS reqwest targets (direct H2 pool covers them and no routing proxy forces reqwest)",
                skipped_h2_tls, total_https_candidates
            );
        } else if h3_frontend_enabled && total_https_candidates > 0 {
            debug!(
                "Pool warmup: H3 frontend enabled, keeping reqwest warm for all {} HTTPS targets (cross-protocol bridge dispatches non-native-H3 backend traffic via reqwest)",
                total_https_candidates
            );
        }
        run_warmup_task_batch(https_tasks, warmup_semaphore, concurrency, "reqwest https").await;
    }

    /// Build a single reqwest HEAD warmup task from a candidate. The
    /// classification logic is identical across HTTP/HTTPS — the gating
    /// happens in the caller (which decides whether to build the task at
    /// all).
    fn build_reqwest_warmup_task(
        pool: Arc<ConnectionPool>,
        candidate: ReqwestWarmupCandidate,
    ) -> WarmupTask {
        let ReqwestWarmupCandidate {
            proxy,
            host,
            port,
            scheme,
            requires_reqwest_warmup: _,
        } = candidate;
        Box::pin(async move {
            let desc = format!("reqwest {}:{}", host, port);
            let client = pool
                .get_client(&proxy)
                .await
                .map_err(|e| format!("{}: {}", desc, e))?;

            let url = format!("{}://{}:{}/", scheme, host, port);
            // Apply the proxy's `backend_connect_timeout_ms` as a per-request
            // connect timeout, capped by the 5s overall warmup budget. Without
            // this, the shared `reqwest::Client` carries no client-level
            // connect timeout (we removed it so per-request overrides can
            // diverge across pool-sharing siblings), so unreachable backends
            // would consume the full 5s overall timeout per probe. Operators
            // who set a tight `backend_connect_timeout_ms` (e.g. 500ms) get
            // that bound at startup too. `0` disables — fall back to the 5s
            // overall cap.
            let mut req = client.head(&url).timeout(Duration::from_secs(5));
            if proxy.backend_connect_timeout_ms > 0 {
                let warmup_cap = Duration::from_secs(5);
                let configured = Duration::from_millis(proxy.backend_connect_timeout_ms);
                req = req.connect_timeout(configured.min(warmup_cap));
            }
            let result = req.send().await;

            match result {
                Ok(_) => Ok(desc),
                // Pool-warmup classification: this is the startup
                // HEAD probe, not a retry decision. We only want to
                // surface "couldn't reach the backend at all" as an
                // error here; a backend that responds with any HTTP
                // status (including 5xx) is reachable enough to keep
                // the pool warm. `e.is_connect() || e.is_timeout()`
                // is the right predicate for that narrow purpose,
                // and intentionally diverges from the unified
                // `request_reached_wire` boundary used by the
                // request-time retry path — different decision,
                // different criteria. Don't "unify" this call to
                // the shared classifier without revisiting what the
                // warmup probe actually needs to gate.
                Err(e) if e.is_connect() || e.is_timeout() => Err(format!("{}: {}", desc, e)),
                Err(_) => Ok(desc),
            }
        })
    }

    /// Run the full validation pipeline against a candidate config and reject
    /// it if any rejecting validator fails. Should be called AFTER
    /// `resolve_upstream_tls()` / `resolve_dispatch_kind()` and BEFORE the
    /// `ArcSwap::store()` that publishes the new config to the hot path.
    ///
    /// **Validator categories** (matching the long-standing semantics of
    /// `apply_incremental` — see `db_loader.rs::load_full_config()` and
    /// `dp_client.rs::handle_full_snapshot` for the corresponding call-site
    /// gates that pre-filter before this helper runs):
    ///
    /// - *Warn-only* — emit `warn!` but never reject:
    ///   - `validate_all_fields_with_ip_policy` (TLS cert paths, expiry,
    ///     `FERRUM_BACKEND_ALLOW_IPS` policy). The DB / DP contract is
    ///     "data is already persisted; warn rather than block reload" so a
    ///     stale TLS path or a single misconfigured backend IP doesn't
    ///     freeze the entire control plane.
    ///   - `validate_hosts` (hostname syntax). Same rationale.
    ///
    /// - *Reject* — accumulate into the returned error vector and abort
    ///   the reload:
    ///   - `validate_regex_listen_paths` — uncompilable regex would
    ///     silently skip routes at runtime.
    ///   - `validate_unique_listen_paths` — overlapping listen paths
    ///     would route non-deterministically.
    ///   - `validate_stream_proxies` — stream-family invariants (no
    ///     `listen_path`, mandatory `listen_port`, etc.).
    ///   - `validate_upstream_references` — dangling upstream IDs would
    ///     500 every request through that proxy.
    ///   - `validate_plugin_references` — dangling plugin IDs / wrong
    ///     scope.
    ///   - `validate_unique_mtls_dns_identities` — case-variant identities
    ///     would collapse into one `ConsumerIndex` DNS key when an effective
    ///     `mtls_auth` `san_dns` policy is enabled.
    ///   - `validate_mesh_route_dispatch_upstream_references` — dangling
    ///     `mesh_route_dispatch.destination.upstream_id` references are
    ///     observationally identical to a dangling `Proxy.upstream_id`:
    ///     `apply_route_overrides_with_upstreams` bakes the missing id
    ///     into the request proxy, `select_upstream_target` returns no
    ///     target, and dispatch silently falls back to the proxy's
    ///     default backend host/port. Reject before swap so the typo
    ///     surfaces as a config error instead of silent traffic
    ///     misrouting.
    ///   - `validate_stream_proxy_port_conflicts` — rejects in non-DP
    ///     modes, warns in DP mode (the DP doesn't control its config and
    ///     one bad stream proxy port shouldn't block all other config
    ///     updates pushed by the CP).
    ///
    /// **Why this lives inside the swap path:** every existing caller
    /// (`file_loader`, `db_loader`, `dp_client`) already validates before
    /// calling `update_config` / `apply_incremental`, but the contract
    /// "validate fully BEFORE swap" must be honored by the swap function
    /// itself so a future call site (e.g. an admin "import config" handler)
    /// cannot publish an invalid config to the hot path. Existing call-site
    /// validation becomes defense-in-depth — the canonical guard is here.
    ///
    /// Reject errors are accumulated into a single `Vec<String>` so callers
    /// can log every reason in one pass instead of discovering them
    /// iteratively across reloads.
    fn validate_full_config(&self, config: &GatewayConfig) -> Result<(), Vec<String>> {
        // Warn-only — TLS field validation (cert paths, expiry, IP policy).
        if let Err(errors) = config.validate_all_fields_with_ip_policy(
            self.env_config.tls_cert_expiry_warning_days,
            &self.env_config.backend_allow_ips,
        ) {
            for msg in &errors {
                warn!("Config field validation: {}", msg);
            }
        }

        // Warn-only — hostname syntax.
        if let Err(errors) = config.validate_hosts() {
            for msg in &errors {
                warn!("Config validation: {}", msg);
            }
        }

        // Reject — collect all rejecting-validator failures into a single
        // error vector so callers can log every reason at once instead of
        // discovering them iteratively across reloads.
        let mut errors: Vec<String> = Vec::new();
        if let Err(errs) = config.validate_regex_listen_paths() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_listen_path_encodings() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_unique_listen_paths() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_stream_proxies() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_upstream_references() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_plugin_references() {
            errors.extend(errs);
        }
        if let Err(errs) = config.validate_unique_mtls_dns_identities() {
            errors.extend(errs);
        }
        if let Err(errs) = validate_mesh_route_dispatch_upstream_references(config) {
            errors.extend(errs);
        }

        // Stream proxy port conflicts — reject in non-DP modes, warn in DP
        // mode. The DP doesn't control its config and one bad stream proxy
        // port shouldn't block all other config updates pushed by the CP.
        if let Err(errs) =
            config.validate_stream_proxy_port_conflicts(self.reserved_gateway_ports.as_ref())
        {
            if matches!(
                self.env_config.mode,
                crate::config::env_config::OperatingMode::DataPlane
            ) {
                for msg in &errs {
                    warn!("Stream proxy port conflict (non-fatal in DP mode): {}", msg);
                }
            } else {
                errors.extend(errs);
            }
        }

        if errors.is_empty() {
            Ok(())
        } else {
            Err(errors)
        }
    }

    /// Apply a new configuration, using incremental (surgical) updates when
    /// possible to avoid disrupting the hot request path.
    ///
    /// The delta between the old and new config is computed first. If nothing
    /// changed, this is a no-op. For typical admin API edits (1-2 resources),
    /// only the affected cache entries are updated while the rest of the
    /// caches — including stateful plugin instances, warm path caches, and
    /// load balancer counters — remain completely untouched.
    ///
    /// Falls back to a full rebuild only on the very first config load (when
    /// there is no previous config to diff against).
    fn delta_routes_changed(
        delta: &crate::config_delta::ConfigDelta,
        old_config: &GatewayConfig,
        new_config: &GatewayConfig,
    ) -> bool {
        let is_route_indexed = |proxy: &Proxy| !proxy.dispatch_kind.is_stream();

        if delta.added_proxies.iter().any(is_route_indexed)
            || delta.modified_proxies.iter().any(is_route_indexed)
        {
            return true;
        }

        if delta.modified_proxies.is_empty() && delta.removed_proxy_ids.is_empty() {
            return Self::projected_route_proxy_content_changed(old_config, new_config);
        }

        let old_route_indexed_proxy_ids: std::collections::HashSet<&str> = old_config
            .proxies
            .iter()
            .filter(|proxy| is_route_indexed(proxy))
            .map(|proxy| proxy.id.as_str())
            .collect();

        delta
            .modified_proxies
            .iter()
            .map(|proxy| proxy.id.as_str())
            .chain(delta.removed_proxy_ids.iter().map(String::as_str))
            .any(|id| old_route_indexed_proxy_ids.contains(id))
            || Self::projected_route_proxy_content_changed(old_config, new_config)
    }

    /// Whether a route-indexed proxy's effective route-table content changed
    /// without a serialized proxy delta.
    ///
    /// `ConfigDelta` detects proxy changes by `updated_at`, but DR-derived
    /// projections such as `dispatch_port_overrides` and
    /// `dispatch_port_override_fallback` are `#[serde(skip)]` fields populated by
    /// `GatewayConfig::resolve_dispatch_port_overrides()`. A DestinationRule-only
    /// edit can therefore leave `delta.modified_proxies` empty while the route
    /// table's stored `Arc<Proxy>` needs to carry new dispatch policy.
    fn projected_route_proxy_content_changed(
        old_config: &GatewayConfig,
        new_config: &GatewayConfig,
    ) -> bool {
        let old_route_indexed: HashMap<&str, &Proxy> = old_config
            .proxies
            .iter()
            .filter(|proxy| !proxy.dispatch_kind.is_stream())
            .map(|proxy| (proxy.id.as_str(), proxy))
            .collect();

        new_config
            .proxies
            .iter()
            .filter(|proxy| !proxy.dispatch_kind.is_stream())
            .any(|new_proxy| {
                old_route_indexed
                    .get(new_proxy.id.as_str())
                    .is_some_and(|old_proxy| !Self::proxy_content_eq(old_proxy, new_proxy))
            })
            || Self::projected_mesh_stream_relay_dispatch_content_changed(old_config, new_config)
    }

    /// Timestamp-neutral proxy content comparison for route-table reuse.
    ///
    /// Serialized proxy content catches ordinary route/backend/policy edits while
    /// ignoring volatile timestamps. The two DR-derived dispatch projection
    /// fields are skipped by serde and therefore compared explicitly for every
    /// value that can alter dispatch, including LB fields used to decide whether
    /// stream-family mesh relays enter a per-port selection lane.
    fn proxy_content_eq(a: &Proxy, b: &Proxy) -> bool {
        if a.resolved_tls != b.resolved_tls {
            return false;
        }

        if !Self::route_dispatch_overrides_eq(
            &a.dispatch_port_overrides,
            &b.dispatch_port_overrides,
        ) || !Self::route_dispatch_override_options_eq(
            a.dispatch_port_override_fallback.as_ref(),
            b.dispatch_port_override_fallback.as_ref(),
        ) {
            return false;
        }

        fn content_value(proxy: &Proxy) -> Option<serde_json::Value> {
            let mut normalized = proxy.clone();
            let epoch = chrono::DateTime::<chrono::Utc>::from_timestamp(0, 0)
                .unwrap_or_else(chrono::Utc::now);
            normalized.created_at = epoch;
            normalized.updated_at = epoch;
            serde_json::to_value(&normalized).ok()
        }

        match (content_value(a), content_value(b)) {
            (Some(a_value), Some(b_value)) => a_value == b_value,
            _ => false,
        }
    }

    fn projected_mesh_stream_relay_dispatch_content_changed(
        old_config: &GatewayConfig,
        new_config: &GatewayConfig,
    ) -> bool {
        let old_projection = Self::mesh_stream_relay_dispatch_overrides(old_config);
        let new_projection = Self::mesh_stream_relay_dispatch_overrides(new_config);
        !Self::mesh_stream_relay_dispatch_overrides_eq(&old_projection, &new_projection)
    }

    fn mesh_stream_relay_dispatch_overrides(
        config: &GatewayConfig,
    ) -> HashMap<String, Option<HashMap<u16, crate::config::types::ResolvedPortOverride>>> {
        let Some(mesh) = config.mesh.as_deref() else {
            return HashMap::new();
        };
        let upstream_ids: std::collections::HashSet<&str> =
            config.upstreams.iter().map(|u| u.id.as_str()).collect();
        let mut projection = HashMap::new();

        for service in &mesh.services {
            if service.cluster_ips.is_empty() {
                continue;
            }
            for sp in crate::modes::mesh::service_tcp_stream_ports(service) {
                let upstream_id = crate::modes::mesh::mesh_outbound_tcp_upstream_id(
                    &service.namespace,
                    &service.name,
                    sp.port,
                );
                if upstream_ids.contains(upstream_id.as_str()) {
                    projection.insert(
                        upstream_id.clone(),
                        Self::projected_dispatch_overrides_for_upstream(config, &upstream_id),
                    );
                }
            }
            for sp in crate::modes::mesh::service_udp_stream_ports(service) {
                let upstream_id = crate::modes::mesh::mesh_outbound_udp_upstream_id(
                    &service.namespace,
                    &service.name,
                    sp.port,
                );
                if upstream_ids.contains(upstream_id.as_str()) {
                    projection.insert(
                        upstream_id.clone(),
                        Self::projected_dispatch_overrides_for_upstream(config, &upstream_id),
                    );
                }
            }
        }

        for spec in crate::modes::mesh::mesh_outbound_tcp_bywl_upstreams(
            &mesh.services,
            &mesh.workloads,
            mesh.multi_cluster.as_ref(),
        ) {
            if upstream_ids.contains(spec.upstream_id.as_str()) {
                projection.insert(
                    spec.upstream_id.clone(),
                    Self::projected_dispatch_overrides_for_upstream(config, &spec.upstream_id),
                );
            }
        }

        projection
    }

    fn projected_dispatch_overrides_for_upstream(
        config: &GatewayConfig,
        upstream_id: &str,
    ) -> Option<HashMap<u16, crate::config::types::ResolvedPortOverride>> {
        let upstream = config.upstreams.iter().find(|u| u.id == upstream_id)?;
        if upstream.port_overrides.is_empty() {
            return None;
        }
        let resolved = upstream
            .port_overrides
            .iter()
            .filter_map(|(port, override_config)| {
                crate::config::types::ResolvedPortOverride::from_upstream_override(override_config)
                    .map(|resolved| (*port, resolved))
            })
            .collect::<HashMap<_, _>>();
        (!resolved.is_empty()).then_some(resolved)
    }

    fn mesh_stream_relay_dispatch_overrides_eq(
        a: &HashMap<String, Option<HashMap<u16, crate::config::types::ResolvedPortOverride>>>,
        b: &HashMap<String, Option<HashMap<u16, crate::config::types::ResolvedPortOverride>>>,
    ) -> bool {
        a.len() == b.len()
            && a.iter().all(|(upstream_id, a_overrides)| {
                b.get(upstream_id).is_some_and(|b_overrides| {
                    Self::route_dispatch_overrides_eq(a_overrides, b_overrides)
                })
            })
    }

    fn route_dispatch_overrides_eq(
        a: &Option<HashMap<u16, crate::config::types::ResolvedPortOverride>>,
        b: &Option<HashMap<u16, crate::config::types::ResolvedPortOverride>>,
    ) -> bool {
        match (a, b) {
            (None, None) => true,
            (Some(a), Some(b)) => {
                a.len() == b.len()
                    && a.iter().all(|(port, a_override)| {
                        b.get(port).is_some_and(|b_override| {
                            Self::route_dispatch_override_eq(a_override, b_override)
                        })
                    })
            }
            (None, Some(_)) | (Some(_), None) => false,
        }
    }

    fn route_dispatch_override_options_eq(
        a: Option<&crate::config::types::ResolvedPortOverride>,
        b: Option<&crate::config::types::ResolvedPortOverride>,
    ) -> bool {
        match (a, b) {
            (None, None) => true,
            (Some(a), Some(b)) => Self::route_dispatch_override_eq(a, b),
            (None, Some(_)) | (Some(_), None) => false,
        }
    }

    fn route_dispatch_override_eq(
        a: &crate::config::types::ResolvedPortOverride,
        b: &crate::config::types::ResolvedPortOverride,
    ) -> bool {
        a.connect_timeout_ms == b.connect_timeout_ms
            && a.algorithm == b.algorithm
            && a.hash_on == b.hash_on
            && a.passive_health_check == b.passive_health_check
            && a.locality_lb_setting == b.locality_lb_setting
            && a.max_connections == b.max_connections
            && a.tcp_keepalive == b.tcp_keepalive
            && a.http_max_requests_per_connection == b.http_max_requests_per_connection
            && a.http_idle_timeout_ms == b.http_idle_timeout_ms
            && a.h2_max_concurrent_streams == b.h2_max_concurrent_streams
            && a.tls == b.tls
            && a.h2_upgrade_policy == b.h2_upgrade_policy
            && a.max_retries == b.max_retries
            && a.http1_max_pending_requests == b.http1_max_pending_requests
    }

    /// Whether the `config.mesh` block changed in a way that requires a route
    /// table rebuild.
    ///
    /// `ConfigDelta` only diffs proxies/upstreams/consumers/plugins (keyed on
    /// `id`/`updated_at`); it never inspects `config.mesh`. But the route table
    /// snapshot materializes several MESH-derived lookup maps that are NOT a
    /// function of `config.proxies` — most notably the raw-TCP inbound port map
    /// (`mesh_tcp_inbound`, derived from `mesh.local_inbound_tcp_routes`, a
    /// `#[serde(skip)]` runtime field invisible to `ConfigDelta`), plus the
    /// raw-TCP / UDP VIP egress tables (derived from `mesh.services`) and the
    /// outbound/inbound/ingress sibling port groups. So a mesh slice update that
    /// retargets/adds/removes a local stream-family service port (or any other
    /// route-table mesh input) without changing a route-indexed proxy leaves
    /// `delta_routes_changed` false, and the published epoch would reuse the STALE
    /// `HostRouteTable` — the inbound accept loop would keep relaying removed/
    /// retargeted raw-TCP ports to the old loopback backend, or fall through to
    /// Hyper for newly added ports.
    ///
    /// The route table is a pure function of `config` (including `config.mesh`),
    /// so comparing the whole mesh block here is the maintenance-safe signal: any
    /// future addition to a route-table mesh map is covered automatically, with no
    /// risk of an under-inclusive field list silently reintroducing the staleness.
    /// A mesh-only change that does not actually alter the route table (e.g. a
    /// `peer_authentications` edit) merely recomputes an equivalent snapshot — a
    /// bounded, off-hot-path cost paid at config-application time only.
    fn mesh_route_table_inputs_changed(
        old_config: &GatewayConfig,
        new_config: &GatewayConfig,
    ) -> bool {
        old_config.mesh != new_config.mesh
    }

    fn delta_consumers_changed(delta: &crate::config_delta::ConfigDelta) -> bool {
        !delta.added_consumers.is_empty()
            || !delta.modified_consumers.is_empty()
            || !delta.removed_consumer_ids.is_empty()
    }

    fn delta_load_balancers_changed(delta: &crate::config_delta::ConfigDelta) -> bool {
        !delta.added_upstreams.is_empty()
            || !delta.modified_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
    }

    fn stage_incremental_request_epoch(
        &self,
        current: &RequestEpoch,
        new_config: &GatewayConfig,
        staged_config: Arc<GatewayConfig>,
        delta: &crate::config_delta::ConfigDelta,
        country_mmdb_load_mode: crate::plugin_cache::CountryMmdbLoadMode,
    ) -> Result<StagedIncrementalRequestEpoch, String> {
        let proxy_ids_to_rebuild =
            plugin_rebuild_targets_for_incremental_stage(&current.config, new_config, delta);
        let proxy_plugin_rebuild_count = proxy_ids_to_rebuild.len();
        let rebuild_globals = delta.global_plugin_configs_changed;
        // A route-indexed proxy delta OR a change to the route table's mesh
        // inputs (e.g. `mesh.local_inbound_tcp_routes`, invisible to `ConfigDelta`)
        // must rebuild the route table; otherwise the stale snapshot's mesh maps
        // (raw-TCP inbound port map, VIP egress tables, sibling port groups) leak.
        let route_changed = Self::delta_routes_changed(delta, &current.config, new_config)
            || Self::mesh_route_table_inputs_changed(&current.config, new_config);
        let consumer_changed = Self::delta_consumers_changed(delta);
        let lb_changed = Self::delta_load_balancers_changed(delta);

        let plugin_inner = self.plugin_cache.build_delta_inner(
            &current.plugin_cache,
            new_config,
            &proxy_ids_to_rebuild,
            &delta.removed_proxy_ids,
            rebuild_globals,
            country_mmdb_load_mode,
        )?;
        let consumer_inner = if consumer_changed {
            ConsumerIndex::build_inner(&new_config.consumers)
        } else {
            Arc::clone(&current.consumer_index)
        };
        let load_balancer = if lb_changed {
            LoadBalancerCache::build_delta_inner(
                &current.load_balancer,
                new_config,
                &delta.added_upstreams,
                &delta.removed_upstream_ids,
                &delta.modified_upstreams,
            )
        } else {
            Arc::clone(&current.load_balancer)
        };
        let route_table = if route_changed {
            RouterCache::build_route_table_snapshot(new_config)
        } else {
            Arc::clone(&current.route_table)
        };

        Ok(StagedIncrementalRequestEpoch {
            request_epoch: StagedRequestEpoch {
                config: staged_config,
                route_table,
                plugin_cache: plugin_inner,
                consumer_index: consumer_inner,
                load_balancer,
                route_changed,
                lb_changed,
            },
            proxy_plugin_rebuild_count,
        })
    }

    fn mirror_request_epoch_wrappers(
        &self,
        published: &RequestEpoch,
        route_changed: bool,
        clear_route_caches: bool,
    ) {
        if route_changed {
            self.router_cache.store_route_table_snapshot(
                Arc::clone(&published.route_table),
                published.route_generation,
            );
            if clear_route_caches {
                self.router_cache.clear_lookup_caches();
            }
        }
        self.plugin_cache
            .store_inner(Arc::clone(&published.plugin_cache));
        self.consumer_index
            .store_inner(Arc::clone(&published.consumer_index));
        self.load_balancer_cache
            .store_inner(Arc::clone(&published.load_balancer));
        // Single chokepoint for every config apply path (initial-load, delta,
        // and incremental). Reload swaps config in place here rather than
        // rebuilding `ProxyState`, so the startup-only `warn_if_websocket_idle_disabled`
        // never sees runtime opt-outs. Diff against the still-live config so a
        // reload that makes a proxy's WebSocket idle bound *newly* disabled emits
        // the same resource-hoarding warning, without re-warning on every
        // unrelated reload while a persistent opt-out is in place.
        let previous_config = self.config.load_full();
        warn_if_websocket_idle_newly_disabled(
            &previous_config,
            &published.config,
            self.env_config.websocket_idle_timeout_seconds,
        );
        warn_if_h3_websocket_new_quic_idle_mismatch(
            &previous_config,
            &published.config,
            self.h3_websocket_reachable.load(Ordering::Acquire),
            self.env_config.websocket_idle_timeout_seconds,
            self.env_config.http3_idle_timeout,
        );
        self.config.store(Arc::clone(&published.config));
        // Config publications can add, remove, or repoint certificate-family
        // sources without producing a TLS source-watcher event. Invalidate the
        // metrics-safe snapshot only after the validated epoch is published so
        // the next scrape refreshes against the accepted config, while rejected
        // and unchanged candidates leave the current snapshot undisturbed.
        crate::tls::inventory_cache::mark_stale();
    }

    /// Record whether the serving mode actually started an H3 listener.
    ///
    /// This must be set by mode startup after it evaluates the same gates used
    /// to spawn the listener: H3 enabled, HTTPS port available, and frontend
    /// TLS material or a dynamic TLS slot. Keeping this as a listener-start
    /// signal avoids warning about H3 WebSocket behavior in HTTP-only
    /// deployments where env flags are enabled but no QUIC listener exists.
    pub(crate) fn set_h3_websocket_listener_started(&self, h3_listener_started: bool) {
        let reachable = h3_websocket_reachable_from_listener(&self.env_config, h3_listener_started);
        let was_reachable = self
            .h3_websocket_reachable
            .swap(reachable, Ordering::AcqRel);
        if reachable && !was_reachable {
            warn_if_h3_websocket_quic_idle_mismatch(
                &self.config.load_full(),
                true,
                self.env_config.websocket_idle_timeout_seconds,
                self.env_config.http3_idle_timeout,
            );
        }
    }

    /// Update the proxy configuration.
    pub fn update_config(&self, mut new_config: GatewayConfig) -> ConfigApplyOutcome {
        use crate::config_delta::ConfigDelta;

        // Normalize hostnames (ASCII-lowercase) and pre-compute each
        // proxy's `dispatch_kind` for O(1) hot-path dispatch. Both must run
        // before any request reads `proxy.dispatch_kind`.
        // `normalize_fields()` calls `resolve_dispatch_kind()` internally
        // (see `GatewayConfig::normalize_fields` rustdoc) so we don't need
        // a separate call here.
        new_config.normalize_fields();
        // Resolve upstream TLS into each proxy's resolved_tls before applying.
        new_config.resolve_upstream_tls();
        // Full snapshots can arrive from sources that bypass the SQL/Mongo
        // loaders, notably CP-to-DP config sync. Quarantine malformed, weak,
        // or cross-Consumer duplicate HMAC credentials at the common swap
        // boundary so none can reach the runtime ConsumerIndex.
        for message in new_config.quarantine_invalid_hmac_credentials() {
            error!("Config reload: {}", message);
        }
        inject_gateway_workload_metrics_if_svid(
            &mut new_config,
            &self.gateway_svid_bundle,
            &self.env_config.namespace,
        );

        // Run the full validation pipeline before swapping. Existing call
        // sites (`file_loader`, `db_loader`, `dp_client`) validate first, so
        // this is defense-in-depth for them — but the canonical "validate
        // fully BEFORE swap" guard must live inside the swap function so a
        // future caller (e.g. an admin "import config" handler) cannot
        // publish an invalid config to the hot path.
        if let Err(errors) = self.validate_full_config(&new_config) {
            for msg in &errors {
                error!("Config reload rejected: {}", msg);
            }
            return ConfigApplyOutcome::rejected(errors);
        }

        let old_config = self.config.load_full();

        // If this is the initial load (old config empty, new config has data),
        // do a full rebuild of all caches instead of computing a delta.
        let old_is_empty = config_empty_ignoring_gateway_managed_plugins(&old_config);
        let new_is_empty = config_empty_ignoring_gateway_managed_plugins(&new_config);

        if old_is_empty && !new_is_empty {
            let route_table = RouterCache::build_route_table_snapshot(&new_config);
            let plugin_inner = match self
                .plugin_cache
                .build_inner_with_existing_client(&new_config)
            {
                Ok(inner) => inner,
                Err(e) => {
                    let message = format!("security plugin validation failed: {e}");
                    error!(
                        "Config reload rejected — security plugin validation failed: {}",
                        e
                    );
                    return ConfigApplyOutcome::rejected_one(message);
                }
            };
            let consumer_inner = ConsumerIndex::build_inner(&new_config.consumers);
            let lb_inner = LoadBalancerCache::build_inner(&new_config);
            let staged_config = Arc::new(new_config.clone());
            let published = match self.request_epoch.update_config(
                |_| {
                    Ok(Some(StagedRequestEpoch {
                        config: Arc::clone(&staged_config),
                        route_table: Arc::clone(&route_table),
                        plugin_cache: Arc::clone(&plugin_inner),
                        consumer_index: Arc::clone(&consumer_inner),
                        load_balancer: Arc::clone(&lb_inner),
                        route_changed: true,
                        lb_changed: true,
                    }))
                },
                |published| {
                    self.mirror_request_epoch_wrappers(published, true, true);
                },
            ) {
                Ok(Some(epoch)) => epoch,
                Ok(None) => return ConfigApplyOutcome::Unchanged,
                Err(e) => {
                    let message = e.to_string();
                    error!("Config reload rejected: {}", e);
                    return ConfigApplyOutcome::rejected_one(message);
                }
            };
            PluginCache::retain_active_uris_for_inner(&published.plugin_cache);
            PluginCache::retain_active_proxy_lifecycle_for_inner(
                &published.plugin_cache,
                &published.config,
            );

            // DNS warmup for all hostnames in the new config
            let mut hostnames: Vec<(String, Option<String>, Option<u64>)> = new_config
                .proxies
                .iter()
                .map(|p| {
                    (
                        p.backend_host.clone(),
                        p.dns_override.clone(),
                        p.dns_cache_ttl_seconds,
                    )
                })
                .collect();
            for upstream in &new_config.upstreams {
                for target in &upstream.targets {
                    // Skip CROSS-CLUSTER HBONE targets: `target.host` is a scoped
                    // synthetic identity (never a resolvable address — the
                    // transport dials `mesh.hbone_dial_host`), so warming it just
                    // logs a failed lookup and adds startup/reload latency.
                    if hbone_pool::target_hbone_cross_cluster(target) {
                        continue;
                    }
                    hostnames.push((target.host.clone(), None, None));
                }
            }
            if !hostnames.is_empty() {
                let dns = self.dns_cache.clone();
                tokio::spawn(async move {
                    dns.warmup(hostnames).await;
                });
            }

            // Prune adaptive buffer state for removed proxies.
            {
                let active_ids: Vec<&str> =
                    new_config.proxies.iter().map(|p| p.id.as_str()).collect();
                self.adaptive_buffer.prune_missing(&active_ids);
            }

            warn_if_h3_backend_tls_policy_incompatible(&new_config, self.tls_policy.as_deref());
            self.spawn_backend_capability_refresh();

            // Reconcile stream proxy listeners (TCP/UDP)
            let slm = self.stream_listener_manager.clone();
            tokio::spawn(async move {
                let failures = slm.reconcile().await;
                for (proxy_id, port, err) in &failures {
                    tracing::error!(
                        proxy_id = %proxy_id,
                        port = port,
                        "Stream listener failed to bind on config reload: {}",
                        err
                    );
                }
            });

            // Reconcile service discovery tasks
            let new_cfg = self.config.load_full();
            self.service_discovery_manager.reconcile(&new_cfg, None);

            // Restart active health-check probes against the new config so
            // upstreams added by this reload get their probes spawned and
            // probe parameters (interval, timeout, threshold, probe_type,
            // TLS config) for existing upstreams are picked up.
            self.health_checker
                .restart_with_shutdown(&new_cfg, self.health_check_shutdown_rx.clone());

            info!(
                "Proxy configuration loaded (full build: router + plugins + consumers + load balancers)"
            );
            return ConfigApplyOutcome::Applied;
        }

        // Both empty — nothing to do
        if old_is_empty && new_is_empty {
            return ConfigApplyOutcome::Unchanged;
        }

        let mut applied_delta = None;
        // `Cell` lets the staging closure carry accepted-snapshot facts into
        // the publish mirror and post-publish maintenance. Plain mutable locals
        // would force incompatible mutable/immutable captures across the two
        // `FnOnce` closures even though they never run concurrently.
        let route_changed = std::cell::Cell::new(false);
        let proxy_plugin_rebuild_count = std::cell::Cell::new(0usize);
        let staged_config = Arc::new(new_config.clone());
        let publish_result = self.request_epoch.update_config(
            |current| {
                let delta = ConfigDelta::compute(&current.config, &new_config);
                if delta.is_empty() {
                    // ConfigDelta does not represent node-local plugin-file
                    // contents or the mesh block. Claim an accepted MMDB
                    // validation handoff before deciding this generation is a
                    // no-op: a same-path file replacement must atomically
                    // publish fresh geo readers even though every serialized
                    // config field and timestamp is unchanged.
                    let country_mmdb_plugin_cache =
                        self.plugin_cache.build_country_mmdb_reload_inner(
                            &current.plugin_cache,
                            &new_config,
                            matches!(
                                self.env_config.mode,
                                crate::config::env_config::OperatingMode::DataPlane
                            ),
                        )?;
                    let mesh_changed = current.config.mesh != new_config.mesh;
                    if !mesh_changed && country_mmdb_plugin_cache.is_none() {
                        return Ok(None);
                    }

                    // Mesh endpoints (`mesh.workloads`/`mesh.services`) are
                    // resolved at REQUEST time from the request epoch's live
                    // `config.mesh`, not materialized `Upstream.targets`. A
                    // mesh-only change therefore also needs an epoch publish.
                    //
                    // Without this, the `Ok(None)` no-delta path below updates
                    // only `ProxyState.config` (the ArcSwap the request path
                    // does NOT read for mesh), leaving `request_epoch.config`
                    // stale — so a remote scale-up / trust-bundle overlay never
                    // reaches the live proxy until an unrelated proxy/upstream
                    // delta forces a republish (codex F7.2 round-5, finding 3).
                    // When the mesh block changed, the route table snapshot
                    // must also refresh because it materializes mesh-derived maps
                    // (raw-TCP inbound port map from the `#[serde(skip)]`
                    // `mesh.local_inbound_tcp_routes`, VIP egress tables, sibling
                    // port groups). Without this,
                    // a mesh slice update that retargets/adds/removes a local
                    // stream-family port would leave the inbound accept loop relaying
                    // to a stale loopback backend (or falling through to Hyper for a
                    // newly added port). An MMDB-only publish reuses that table.
                    route_changed.set(mesh_changed);
                    return Ok(Some(StagedRequestEpoch {
                        config: Arc::clone(&staged_config),
                        route_table: if mesh_changed {
                            RouterCache::build_route_table_snapshot(&new_config)
                        } else {
                            Arc::clone(&current.route_table)
                        },
                        plugin_cache: country_mmdb_plugin_cache
                            .unwrap_or_else(|| Arc::clone(&current.plugin_cache)),
                        consumer_index: Arc::clone(&current.consumer_index),
                        load_balancer: Arc::clone(&current.load_balancer),
                        route_changed: mesh_changed,
                        lb_changed: false,
                    }));
                }
                let country_mmdb_load_mode = if matches!(
                    self.env_config.mode,
                    crate::config::env_config::OperatingMode::DataPlane
                ) {
                    crate::plugin_cache::CountryMmdbLoadMode::NodeLocalRefresh
                } else {
                    crate::plugin_cache::CountryMmdbLoadMode::Standard
                };
                let staged = self.stage_incremental_request_epoch(
                    current,
                    &new_config,
                    Arc::clone(&staged_config),
                    &delta,
                    country_mmdb_load_mode,
                )?;
                route_changed.set(staged.request_epoch.route_changed);
                proxy_plugin_rebuild_count.set(staged.proxy_plugin_rebuild_count);
                applied_delta = Some(delta);
                Ok(Some(staged.request_epoch))
            },
            |published| {
                self.mirror_request_epoch_wrappers(published, route_changed.get(), false);
            },
        );
        let published = match publish_result {
            Ok(Some(epoch)) => epoch,
            Ok(None) => {
                debug!("Config poll: candidate valid but unchanged, skipping update");
                // Still update loaded_at timestamp
                self.config.store(Arc::new(new_config));
                return ConfigApplyOutcome::Unchanged;
            }
            Err(e) => {
                let message = format!("security plugin validation failed: {e}");
                error!(
                    "Config reload rejected — security plugin validation failed: {}",
                    e
                );
                return ConfigApplyOutcome::rejected_one(message);
            }
        };
        PluginCache::retain_active_uris_for_inner(&published.plugin_cache);
        PluginCache::retain_active_proxy_lifecycle_for_inner(
            &published.plugin_cache,
            &published.config,
        );

        // Out-of-band republish (mesh-only and/or accepted MMDB-only reload):
        // there is no resource delta to drive pruning, DNS warmup, listener
        // reconciliation, or health-check restarts. The request epoch already
        // carries the new mesh config and/or geo plugin snapshot, and
        // `mirror_request_epoch_wrappers` published its wrapper views above.
        let Some(delta) = applied_delta else {
            debug!("Config update: out-of-band mesh/MMDB generation republished");
            return ConfigApplyOutcome::Applied;
        };
        let proxy_plugin_rebuild_count = proxy_plugin_rebuild_count.get();

        // --- CircuitBreakerCache: prune breakers for deleted proxies ---
        if !delta.removed_proxy_ids.is_empty() {
            self.circuit_breaker_cache.prune(&delta.removed_proxy_ids);
        }

        // --- CircuitBreakerCache: prune stale upstream targets ---
        // Removes breakers for host:port combos no longer in any upstream,
        // preventing unbounded growth from target churn (e.g., K8s pod cycling).
        {
            let mut active_keys = std::collections::HashSet::new();
            for proxy in &new_config.proxies {
                if let Some(ref upstream_id) = proxy.upstream_id
                    && let Some(upstream) =
                        new_config.upstreams.iter().find(|u| u.id == *upstream_id)
                {
                    for target in &upstream.targets {
                        active_keys
                            .insert(format!("{}::{}:{}", proxy.id, target.host, target.port));
                    }
                }
            }
            self.circuit_breaker_cache.prune_stale_targets(&active_keys);
        }

        // --- HealthChecker: prune passive health state for removed proxies ---
        if !delta.removed_proxy_ids.is_empty() {
            self.health_checker
                .prune_removed_proxies(&delta.removed_proxy_ids);
        }
        for proxy in &new_config.proxies {
            if let Some(ref upstream_id) = proxy.upstream_id
                && let Some(upstream) = new_config.upstreams.iter().find(|u| u.id == *upstream_id)
            {
                self.health_checker
                    .remove_stale_passive_targets_for_proxy(&proxy.id, &upstream.targets);
            }
        }

        // --- DNS warmup for new/modified hostnames ---
        // Collect backend hostnames from added/modified proxies and upstreams
        // so the DNS cache is warm before the first request hits them.
        let mut new_hostnames: Vec<(String, Option<String>, Option<u64>)> = Vec::new();
        for proxy in delta
            .added_proxies
            .iter()
            .chain(delta.modified_proxies.iter())
        {
            new_hostnames.push((
                proxy.backend_host.clone(),
                proxy.dns_override.clone(),
                proxy.dns_cache_ttl_seconds,
            ));
        }
        for upstream in delta
            .added_upstreams
            .iter()
            .chain(delta.modified_upstreams.iter())
        {
            for target in &upstream.targets {
                // Skip CROSS-CLUSTER HBONE targets — `target.host` is a scoped
                // synthetic identity, never a resolvable address (see the
                // full-config warmup above).
                if hbone_pool::target_hbone_cross_cluster(target) {
                    continue;
                }
                new_hostnames.push((target.host.clone(), None, None));
            }
        }
        if !new_hostnames.is_empty() {
            let dns = self.dns_cache.clone();
            tokio::spawn(async move {
                dns.warmup(new_hostnames).await;
            });
        }

        // Prune adaptive buffer state for removed proxies.
        {
            let active_ids: Vec<&str> = new_config.proxies.iter().map(|p| p.id.as_str()).collect();
            self.adaptive_buffer.prune_missing(&active_ids);
        }

        warn_if_h3_backend_tls_policy_incompatible(&new_config, self.tls_policy.as_deref());
        self.spawn_backend_capability_refresh();

        // Reconcile stream proxy listeners if any proxies changed.
        //
        // Upstream changes must also trigger reconcile: a TCP+TLS stream
        // proxy's backend TLS (CA / client cert / verify / SAN list) can be
        // supplied by its referenced upstream via `resolved_tls`, and an
        // upstream-only update never marks the proxy itself as modified
        // (delta diffing is `updated_at`-based). Conservative trigger — any
        // upstream change while stream proxies exist — is fine: reconcile is
        // idempotent and only restarts listeners whose reload key actually
        // changed.
        let upstreams_changed = !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty();
        let stream_proxies_changed = delta
            .added_proxies
            .iter()
            .chain(delta.modified_proxies.iter())
            .any(|p| p.dispatch_kind.is_stream())
            || !delta.removed_proxy_ids.is_empty()
            || (upstreams_changed
                && new_config
                    .proxies
                    .iter()
                    .any(|p| p.dispatch_kind.is_stream()));
        if stream_proxies_changed {
            let slm = self.stream_listener_manager.clone();
            tokio::spawn(async move {
                let failures = slm.reconcile().await;
                for (proxy_id, port, err) in &failures {
                    tracing::error!(
                        proxy_id = %proxy_id,
                        port = port,
                        "Stream listener failed to bind on config update: {}",
                        err
                    );
                }
            });
        }

        // Log a concise summary of what changed
        let total_changes = delta.added_proxies.len()
            + delta.removed_proxy_ids.len()
            + delta.modified_proxies.len()
            + delta.added_consumers.len()
            + delta.removed_consumer_ids.len()
            + delta.modified_consumers.len()
            + delta.added_plugin_configs.len()
            + delta.removed_plugin_config_ids.len()
            + delta.modified_plugin_configs.len()
            + delta.plugin_association_changed_proxy_ids.len()
            + delta.added_upstreams.len()
            + delta.removed_upstream_ids.len()
            + delta.modified_upstreams.len();
        info!(
            "Config updated incrementally: {} changes (proxies: +{} -{} ~{}, consumers: +{} -{} ~{}, plugins: +{} -{} ~{}, plugin associations: ~{}, upstreams: +{} -{} ~{}, {} proxy plugin lists rebuilt)",
            total_changes,
            delta.added_proxies.len(),
            delta.removed_proxy_ids.len(),
            delta.modified_proxies.len(),
            delta.added_consumers.len(),
            delta.removed_consumer_ids.len(),
            delta.modified_consumers.len(),
            delta.added_plugin_configs.len(),
            delta.removed_plugin_config_ids.len(),
            delta.modified_plugin_configs.len(),
            delta.plugin_association_changed_proxy_ids.len(),
            delta.added_upstreams.len(),
            delta.removed_upstream_ids.len(),
            delta.modified_upstreams.len(),
            proxy_plugin_rebuild_count,
        );

        // Reconcile service discovery tasks for changed upstreams
        if !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty()
        {
            let new_cfg = self.config.load_full();
            self.service_discovery_manager.reconcile(&new_cfg, None);
        }

        // Restart active health-check probes when upstreams or their probe
        // configuration changed. Without this, probe tasks spawned at startup
        // keep running with stale parameters, removed upstreams keep probing
        // forever, and newly added upstreams never get probes.
        if !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty()
        {
            let new_cfg = self.config.load_full();
            self.health_checker
                .restart_with_shutdown(&new_cfg, self.health_check_shutdown_rx.clone());
        }

        ConfigApplyOutcome::Applied
    }

    /// Start service discovery background tasks for all upstreams in the config.
    ///
    /// Should be called once after `ProxyState::new()` in each mode's startup,
    /// similar to `HealthChecker::start_with_shutdown` (which `ProxyState::new`
    /// invokes internally).
    pub fn start_service_discovery(&self, shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>) {
        let config = self.config.load_full();
        self.service_discovery_manager.start(&config, shutdown_rx);
    }

    /// Apply an incremental config update from the database polling loop.
    ///
    /// Unlike `update_config()` which takes a full `GatewayConfig` and diffs it
    /// against the current config, this method receives pre-computed changes
    /// directly from the DB layer's `load_incremental_config()`. This avoids
    /// loading and diffing the full config on every poll cycle.
    ///
    /// Returns a [`ConfigApplyOutcome`] so callers can distinguish accepted
    /// no-op candidates (`Unchanged`) from validation/build rejections
    /// (`Rejected`). The DB poller relies on this to avoid advancing
    /// `last_poll_at` on rejection — see `src/modes/database.rs`.
    pub async fn apply_incremental(
        &self,
        result: crate::config::db_loader::IncrementalResult,
    ) -> ConfigApplyOutcome {
        if result.is_empty() {
            return ConfigApplyOutcome::Unchanged;
        }

        // Patch the stored GatewayConfig: clone current, apply mutations, store.
        // Hold the pre-mutation snapshot so we can interrogate removed proxies'
        // `dispatch_kind` after `new_config.proxies` has had them retained-out.
        let old_config = self.config.load_full();
        let mut new_config = (*old_config).clone();

        // Remove deleted resources by (namespace, id) so a misrouted removal
        // cannot delete a same-id object belonging to another namespace.
        if !result.removed_proxy_ids.is_empty() {
            let removed: std::collections::HashSet<(&str, &str)> = result
                .removed_proxy_ids
                .iter()
                .map(|key| (key.namespace.as_str(), key.id.as_str()))
                .collect();
            new_config
                .proxies
                .retain(|p| !removed.contains(&(p.namespace.as_str(), p.id.as_str())));
        }
        if !result.removed_consumer_ids.is_empty() {
            let removed: std::collections::HashSet<(&str, &str)> = result
                .removed_consumer_ids
                .iter()
                .map(|key| (key.namespace.as_str(), key.id.as_str()))
                .collect();
            new_config.consumers.retain(|consumer| {
                !removed.contains(&(consumer.namespace.as_str(), consumer.id.as_str()))
            });
        }
        if !result.removed_plugin_config_ids.is_empty() {
            let removed: std::collections::HashSet<(&str, &str)> = result
                .removed_plugin_config_ids
                .iter()
                .map(|key| (key.namespace.as_str(), key.id.as_str()))
                .collect();
            new_config
                .plugin_configs
                .retain(|pc| !removed.contains(&(pc.namespace.as_str(), pc.id.as_str())));
            for proxy in &mut new_config.proxies {
                proxy.plugins.retain(|assoc| {
                    !removed.contains(&(proxy.namespace.as_str(), assoc.plugin_config_id.as_str()))
                });
            }
        }
        if !result.removed_upstream_ids.is_empty() {
            let removed: std::collections::HashSet<(&str, &str)> = result
                .removed_upstream_ids
                .iter()
                .map(|key| (key.namespace.as_str(), key.id.as_str()))
                .collect();
            new_config
                .upstreams
                .retain(|u| !removed.contains(&(u.namespace.as_str(), u.id.as_str())));
        }

        // Upsert added/modified resources using HashMap index for O(1) lookups
        // instead of O(n) linear scan per resource. Move values to avoid cloning.

        if !result.added_or_modified_proxies.is_empty() {
            let mut idx: std::collections::HashMap<(String, String), usize> = new_config
                .proxies
                .iter()
                .enumerate()
                .map(|(i, p)| ((p.namespace.clone(), p.id.clone()), i))
                .collect();
            for proxy in result.added_or_modified_proxies {
                let key = (proxy.namespace.clone(), proxy.id.clone());
                if let Some(&pos) = idx.get(&key) {
                    new_config.proxies[pos] = proxy;
                } else {
                    idx.insert(key, new_config.proxies.len());
                    new_config.proxies.push(proxy);
                }
            }
        }

        if !result.added_or_modified_consumers.is_empty() {
            let mut idx: std::collections::HashMap<(String, String), usize> = new_config
                .consumers
                .iter()
                .enumerate()
                .map(|(i, consumer)| ((consumer.namespace.clone(), consumer.id.clone()), i))
                .collect();
            for consumer in result.added_or_modified_consumers {
                let key = (consumer.namespace.clone(), consumer.id.clone());
                if let Some(&pos) = idx.get(&key) {
                    new_config.consumers[pos] = consumer;
                } else {
                    idx.insert(key, new_config.consumers.len());
                    new_config.consumers.push(consumer);
                }
            }
        }

        if !result.added_or_modified_plugin_configs.is_empty() {
            let mut idx: std::collections::HashMap<(String, String), usize> = new_config
                .plugin_configs
                .iter()
                .enumerate()
                .map(|(i, pc)| ((pc.namespace.clone(), pc.id.clone()), i))
                .collect();
            for pc in result.added_or_modified_plugin_configs {
                let key = (pc.namespace.clone(), pc.id.clone());
                if let Some(&pos) = idx.get(&key) {
                    new_config.plugin_configs[pos] = pc;
                } else {
                    idx.insert(key, new_config.plugin_configs.len());
                    new_config.plugin_configs.push(pc);
                }
            }
        }

        if !result.added_or_modified_upstreams.is_empty() {
            let mut idx: std::collections::HashMap<(String, String), usize> = new_config
                .upstreams
                .iter()
                .enumerate()
                .map(|(i, u)| ((u.namespace.clone(), u.id.clone()), i))
                .collect();
            for upstream in result.added_or_modified_upstreams {
                let key = (upstream.namespace.clone(), upstream.id.clone());
                if let Some(&pos) = idx.get(&key) {
                    new_config.upstreams[pos] = upstream;
                } else {
                    idx.insert(key, new_config.upstreams.len());
                    new_config.upstreams.push(upstream);
                }
            }
        }

        new_config.loaded_at = result.poll_timestamp;

        // Validate the patched config before applying. `validate_full_config`
        // is the shared validation pipeline used by both `update_config` and
        // `apply_incremental` so the two swap paths cannot drift in what they
        // accept. Normalize + resolve must run first so the validators see
        // canonicalized fields.
        new_config.normalize_fields();
        new_config.resolve_upstream_tls();
        // Fail-closed hmac_auth secret policy for point-loaded consumer rows:
        // full snapshots quarantine weak/duplicate HMAC secrets in
        // `update_config`, but deltas from non-database or older control-plane
        // sources can still merge raw consumer rows through this separate
        // path. Storage constraints backstop normal admin races; this boundary
        // retains defense in depth for out-of-band data.
        for message in new_config.quarantine_invalid_hmac_credentials() {
            error!("Incremental config: {}", message);
        }
        inject_gateway_workload_metrics_if_svid(
            &mut new_config,
            &self.gateway_svid_bundle,
            &self.env_config.namespace,
        );
        if let Err(errors) = self.validate_full_config(&new_config) {
            return ConfigApplyOutcome::rejected(errors);
        }

        // Incremental database and CP/DP deltas stage plugin caches directly
        // on this async call path. Expand the prospective rebuild scope using
        // the same adaptive-concurrency route-definition logic as cache
        // staging, validate every MMDB or body-validator descriptor that exact
        // scope reconstructs on the blocking pool, then require MMDB cache
        // staging to claim its validated handoff without synchronous file work.
        let prospective_delta = crate::config_delta::ConfigDelta::compute(&old_config, &new_config);
        let prospective_proxy_rebuilds =
            prospective_delta.proxy_ids_needing_plugin_rebuild(&old_config, &new_config);
        let country_mmdb_preload_required = self.plugin_cache.country_mmdb_preload_required(
            &new_config,
            &prospective_proxy_rebuilds,
            prospective_delta.global_plugin_configs_changed,
        );
        let body_validator_descriptor_preload_required = self
            .plugin_cache
            .body_validator_descriptor_preload_required(
                &new_config,
                &prospective_proxy_rebuilds,
                prospective_delta.global_plugin_configs_changed,
            );
        if country_mmdb_preload_required || body_validator_descriptor_preload_required {
            new_config = match crate::config::validation_pipeline::validate_plugin_file_dependencies_off_thread(
                new_config,
                crate::config::validation_pipeline::ValidationAction::Warn,
            )
            .await
            {
                Ok(config) => config,
                Err(error) => {
                    let message = format!("incremental plugin file validation failed: {error}");
                    error!("Incremental config rejected: {}", message);
                    return ConfigApplyOutcome::rejected_one(message);
                }
            };
        }

        let mut applied_delta = None;
        // See `update_config` rustdoc nearby for why this is a `Cell` and not
        // a plain `let mut bool`.
        let route_changed = std::cell::Cell::new(false);
        let staged_config = Arc::new(new_config.clone());
        let publish_result = self.request_epoch.update_config(
            |current| {
                let delta = crate::config_delta::ConfigDelta::compute(&current.config, &new_config);
                if delta.is_empty() {
                    // A concurrent writer can make the prospective delta above
                    // disappear after its off-thread MMDB generation was
                    // accepted. Claim and publish that handoff rather than
                    // leaving it unowned or retaining stale geo readers.
                    let Some(plugin_cache) = self.plugin_cache.build_country_mmdb_reload_inner(
                        &current.plugin_cache,
                        &new_config,
                        false,
                    )?
                    else {
                        return Ok(None);
                    };
                    return Ok(Some(StagedRequestEpoch {
                        config: Arc::clone(&staged_config),
                        route_table: Arc::clone(&current.route_table),
                        plugin_cache,
                        consumer_index: Arc::clone(&current.consumer_index),
                        load_balancer: Arc::clone(&current.load_balancer),
                        route_changed: false,
                        lb_changed: false,
                    }));
                }
                let staged = self.stage_incremental_request_epoch(
                    current,
                    &new_config,
                    Arc::clone(&staged_config),
                    &delta,
                    crate::plugin_cache::CountryMmdbLoadMode::PreloadedOnly,
                )?;
                route_changed.set(staged.request_epoch.route_changed);
                applied_delta = Some(delta);
                Ok(Some(staged.request_epoch))
            },
            |published| {
                self.mirror_request_epoch_wrappers(published, route_changed.get(), false);
            },
        );
        let published = match publish_result {
            Ok(Some(epoch)) => epoch,
            Ok(None) => return ConfigApplyOutcome::Unchanged,
            Err(e) => {
                let message = format!("security plugin validation failed: {e}");
                return ConfigApplyOutcome::rejected_one(message);
            }
        };
        PluginCache::retain_active_uris_for_inner(&published.plugin_cache);
        PluginCache::retain_active_proxy_lifecycle_for_inner(
            &published.plugin_cache,
            &published.config,
        );

        let Some(delta) = applied_delta else {
            debug!("Incremental config: accepted MMDB-only generation republished");
            return ConfigApplyOutcome::Applied;
        };

        // --- CircuitBreakerCache ---
        if !delta.removed_proxy_ids.is_empty() {
            self.circuit_breaker_cache.prune(&delta.removed_proxy_ids);
        }

        // Prune stale upstream targets from circuit breaker cache
        {
            let mut active_keys = std::collections::HashSet::new();
            for proxy in &new_config.proxies {
                if let Some(ref upstream_id) = proxy.upstream_id
                    && let Some(upstream) =
                        new_config.upstreams.iter().find(|u| u.id == *upstream_id)
                {
                    for target in &upstream.targets {
                        active_keys
                            .insert(format!("{}::{}:{}", proxy.id, target.host, target.port));
                    }
                }
            }
            self.circuit_breaker_cache.prune_stale_targets(&active_keys);
        }

        // --- HealthChecker: prune passive health state for removed proxies ---
        if !delta.removed_proxy_ids.is_empty() {
            self.health_checker
                .prune_removed_proxies(&delta.removed_proxy_ids);
        }
        for proxy in &new_config.proxies {
            if let Some(ref upstream_id) = proxy.upstream_id
                && let Some(upstream) = new_config.upstreams.iter().find(|u| u.id == *upstream_id)
            {
                self.health_checker
                    .remove_stale_passive_targets_for_proxy(&proxy.id, &upstream.targets);
            }
        }

        // --- DNS warmup for new/modified hostnames ---
        let mut new_hostnames: Vec<(String, Option<String>, Option<u64>)> = Vec::new();
        for proxy in delta
            .added_proxies
            .iter()
            .chain(delta.modified_proxies.iter())
        {
            new_hostnames.push((
                proxy.backend_host.clone(),
                proxy.dns_override.clone(),
                proxy.dns_cache_ttl_seconds,
            ));
        }
        for upstream in delta
            .added_upstreams
            .iter()
            .chain(delta.modified_upstreams.iter())
        {
            for target in &upstream.targets {
                // Skip CROSS-CLUSTER HBONE targets — `target.host` is a scoped
                // synthetic identity, never a resolvable address (see the
                // full-config warmup above).
                if hbone_pool::target_hbone_cross_cluster(target) {
                    continue;
                }
                new_hostnames.push((target.host.clone(), None, None));
            }
        }
        if !new_hostnames.is_empty() {
            let dns = self.dns_cache.clone();
            tokio::spawn(async move {
                dns.warmup(new_hostnames).await;
            });
        }

        // Prune adaptive buffer state for removed proxies.
        {
            let active_ids: Vec<&str> = new_config.proxies.iter().map(|p| p.id.as_str()).collect();
            self.adaptive_buffer.prune_missing(&active_ids);
        }

        warn_if_h3_backend_tls_policy_incompatible(&new_config, self.tls_policy.as_deref());

        // Trigger a coalesced capability refresh so added/modified HTTPS
        // backends get classified immediately instead of waiting up to the
        // periodic interval (default 24 h). Database polling and DP gRPC
        // delta updates both flow through this path, so a brand-new
        // H3-only backend would otherwise keep 502-ing via reqwest until
        // the next periodic tick. The coalescer absorbs bursts so a DB
        // poll storm or rapid CP push sequence still fans out to at most
        // one in-flight probe + one queued re-run.
        self.spawn_backend_capability_refresh();

        // Reconcile stream proxy listeners if any stream proxies changed.
        //
        // Upstream changes must also trigger reconcile: a TCP+TLS stream
        // proxy's backend TLS (CA / client cert / verify / SAN list) can be
        // supplied by its referenced upstream via `resolved_tls`, and an
        // upstream-only update never marks the proxy itself as modified
        // (delta diffing is `updated_at`-based). Conservative trigger — any
        // upstream change while stream proxies exist — is fine: reconcile is
        // idempotent and only restarts listeners whose reload key actually
        // changed.
        let removed_had_stream = if !delta.removed_proxy_ids.is_empty() {
            let removed_set: std::collections::HashSet<&str> =
                delta.removed_proxy_ids.iter().map(|s| s.as_str()).collect();
            old_config
                .proxies
                .iter()
                .any(|p| removed_set.contains(p.id.as_str()) && p.dispatch_kind.is_stream())
        } else {
            false
        };
        let upstreams_changed = !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty();
        let stream_proxies_changed = delta
            .added_proxies
            .iter()
            .chain(delta.modified_proxies.iter())
            .any(|p| p.dispatch_kind.is_stream())
            || removed_had_stream
            || (upstreams_changed
                && new_config
                    .proxies
                    .iter()
                    .any(|p| p.dispatch_kind.is_stream()));
        if stream_proxies_changed {
            let failures = self.stream_listener_manager.reconcile().await;
            for (proxy_id, port, err) in &failures {
                tracing::error!(
                    proxy_id = %proxy_id,
                    port = port,
                    "Stream listener failed to bind on incremental config update: {}",
                    err
                );
            }
        }

        info!(
            "Incremental config applied: proxies: +{} -{} ~{}, consumers: +{} -{} ~{}, plugins: +{} -{} ~{}, upstreams: +{} -{} ~{}",
            delta.added_proxies.len(),
            delta.removed_proxy_ids.len(),
            delta.modified_proxies.len(),
            delta.added_consumers.len(),
            delta.removed_consumer_ids.len(),
            delta.modified_consumers.len(),
            delta.added_plugin_configs.len(),
            delta.removed_plugin_config_ids.len(),
            delta.modified_plugin_configs.len(),
            delta.added_upstreams.len(),
            delta.removed_upstream_ids.len(),
            delta.modified_upstreams.len(),
        );

        // Reconcile service discovery tasks for changed upstreams
        if !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty()
        {
            let new_cfg = self.config.load_full();
            self.service_discovery_manager.reconcile(&new_cfg, None);
        }

        // Restart active health-check probes when upstreams or their probe
        // configuration changed. Same rationale as the corresponding block
        // in `update_config` — incremental DB polls and CP gRPC pushes both
        // route through this method, so without it any upstream churn after
        // startup is invisible to the probe layer.
        if !delta.added_upstreams.is_empty()
            || !delta.removed_upstream_ids.is_empty()
            || !delta.modified_upstreams.is_empty()
        {
            let new_cfg = self.config.load_full();
            self.health_checker
                .restart_with_shutdown(&new_cfg, self.health_check_shutdown_rx.clone());
        }

        ConfigApplyOutcome::Applied
    }

    pub fn current_config(&self) -> Arc<GatewayConfig> {
        self.config.load_full()
    }

    /// Canonicalize a candidate snapshot exactly as [`Self::update_config`]
    /// does before it swaps, so the result is content-comparable against
    /// [`Self::current_config`].
    ///
    /// `update_config` normalizes fields, resolves upstream TLS, quarantines
    /// invalid HMAC credentials, and injects gateway workload-metrics identity
    /// **before** storing the snapshot. A raw CP-delivered candidate has not
    /// been through those node-local steps, so comparing it directly against
    /// the applied config reports a spurious mismatch on any node whose
    /// identity or credential state triggers one of them — most visibly a DP
    /// with a gateway SVID, where the injected `__gateway_workload_metrics`
    /// plugin config exists only on the applied side.
    ///
    /// The ConfigSync older-cross-source identical-payload exception
    /// (`configsync_lifecycle::authoritative_snapshot_payload_matches`) depends
    /// on that comparison, so it must canonicalize first or the exception is
    /// silently inert and every equivalent failover snapshot is fenced.
    ///
    /// Quarantine diagnostics are intentionally discarded: this is a read-only
    /// comparison helper on a clone, and `update_config` logs them on the real
    /// apply path.
    pub fn canonicalize_snapshot_for_comparison(&self, config: &GatewayConfig) -> GatewayConfig {
        let mut candidate = config.clone();
        candidate.normalize_fields();
        candidate.resolve_upstream_tls();
        let _ = candidate.quarantine_invalid_hmac_credentials();
        inject_gateway_workload_metrics_if_svid(
            &mut candidate,
            &self.gateway_svid_bundle,
            &self.env_config.namespace,
        );
        candidate
    }
}

/// Drives the per-IP cleanup interval loop.
///
/// Pulled out of `start_per_ip_cleanup_task` so the shutdown semantics can be
/// unit-tested without constructing a full `ProxyState` (which requires a TLS
/// policy, listener manager, etc.). When `shutdown_rx` is `Some`, the loop
/// exits cleanly on watch-channel change so the spawned task can be drained
/// during graceful shutdown alongside DNS / overload / metrics handles.
async fn run_per_ip_cleanup_loop(
    counts: Arc<dashmap::DashMap<String, AtomicU64>>,
    interval_secs: u64,
    shutdown_rx: Option<tokio::sync::watch::Receiver<bool>>,
) {
    let mut timer = tokio::time::interval(std::time::Duration::from_secs(interval_secs));
    match shutdown_rx {
        Some(mut shutdown_rx) => loop {
            tokio::select! {
                _ = timer.tick() => {
                    counts.retain(|_, count| count.load(Ordering::Relaxed) > 0);
                }
                _ = shutdown_rx.changed() => {
                    info!("Per-IP cleanup task shutting down");
                    break;
                }
            }
        },
        None => loop {
            timer.tick().await;
            counts.retain(|_, count| count.load(Ordering::Relaxed) > 0);
        },
    }
}

/// Handle a plain HTTP TCP connection (HTTP/1.1 and HTTP/2 cleartext via h2c).
///
/// Uses hyper-util's auto builder which accepts both HTTP/1.1 and HTTP/2
/// connections. h2c (cleartext HTTP/2) is required for gRPC clients that
/// connect without TLS.
///
/// On shutdown, calls `graceful_shutdown()` on the hyper connection so that
/// HTTP/2 clients receive a GOAWAY frame and HTTP/1.1 keepalive connections
/// stop accepting new requests. Without this, persistent H2/keepalive
/// connections continue to accept new streams indefinitely after the listener
/// exits, forcing every shutdown to wait the full
/// `FERRUM_SHUTDOWN_DRAIN_SECONDS` timeout.
#[allow(clippy::too_many_arguments)]
async fn handle_connection(
    stream: tokio::net::TcpStream,
    remote_addr: SocketAddr,
    state: Arc<ProxyState>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
    frontend_listen_port: Option<u16>,
    node_waypoint_identity: Option<Arc<NodeWaypointIdentity>>,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    orig_dst: Option<SocketAddr>,
    mesh_inbound_pre_handshake_app_port: Option<u16>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    // Set TCP keepalive on inbound connection to detect stale clients
    set_tcp_keepalive(&stream);

    // Use TokioIo to adapt the TCP stream for hyper
    let io = TokioIo::new(stream);

    // Use auto builder to support both HTTP/1.1 and HTTP/2 cleartext (h2c).
    // This is needed for gRPC clients that use h2c prior knowledge.
    let mut builder =
        hyper_util::server::conn::auto::Builder::new(hyper_util::rt::TokioExecutor::new());
    {
        let mut http1 = builder.http1();
        http1.max_buf_size(http1_parser_max_buf_size(state.max_header_size_bytes));
        http1.writev(true);
        // Slowloris protection: close connections that take too long to send headers.
        if state.env_config.http_header_read_timeout_seconds > 0 {
            http1.timer(hyper_util::rt::TokioTimer::new());
            http1.header_read_timeout(std::time::Duration::from_secs(
                state.env_config.http_header_read_timeout_seconds,
            ));
        }
    }
    builder
        .http2()
        .max_header_list_size(h2_parser_max_header_list_size(state.max_header_size_bytes))
        .initial_stream_window_size(state.env_config.frontend_h2_initial_stream_window_size)
        .initial_connection_window_size(state.env_config.frontend_h2_initial_connection_window_size)
        .adaptive_window(false)
        .max_frame_size(state.env_config.frontend_h2_max_frame_size)
        .max_concurrent_streams(state.env_config.server_http2_max_concurrent_streams)
        .max_pending_accept_reset_streams(Some(
            state
                .env_config
                .server_http2_max_pending_accept_reset_streams,
        ))
        .max_local_error_reset_streams(Some(
            state.env_config.server_http2_max_local_error_reset_streams,
        ))
        // RFC 8441: Advertise SETTINGS_ENABLE_CONNECT_PROTOCOL so HTTP/2 clients
        // can initiate WebSocket connections via Extended CONNECT.
        .enable_connect_protocol();

    // WebSocket requests flow through handle_proxy_request so that authentication
    // and authorization plugins execute before the upgrade handshake.
    let svc = service_fn(move |req: Request<Incoming>| {
        let state = Arc::clone(&state);
        let addr = remote_addr;
        let connection_metadata = RequestConnectionMetadata {
            frontend_listen_port,
            frontend_sni_hostname: None,
            node_waypoint_identity: node_waypoint_identity.clone(),
            mesh_direction,
            orig_dst,
            mesh_inbound_pre_handshake_app_port,
            // Plaintext connections carry no client certificate.
            peer_spiffe_extraction_cache: None,
        };
        async move {
            handle_proxy_request_on_frontend_port(
                req,
                state,
                addr,
                false,
                None,
                None,
                None,
                connection_metadata,
            )
            .await
        }
    });

    let conn = builder.serve_connection_with_upgrades(io, svc);
    tokio::pin!(conn);

    let result = tokio::select! {
        biased;
        res = conn.as_mut() => res,
        _ = shutdown_rx.changed() => {
            // Send GOAWAY (H2) / signal end-of-keepalive (H1) and wait for
            // in-flight requests to complete on this connection. Continuing
            // to poll the connection lets streams finish before the connection
            // future resolves.
            conn.as_mut().graceful_shutdown();
            conn.as_mut().await
        }
    };

    if let Err(e) = result {
        let err_string = e.to_string();
        if is_client_disconnect_error(&err_string) {
            debug!(
                remote_addr = %remote_addr.ip(),
                error_kind = "client_disconnect",
                error = %e,
                "Client disconnected before response completed"
            );
        } else {
            error!(
                remote_addr = %remote_addr,
                listen_port = frontend_listen_port,
                tls = false,
                error = %e,
                "HTTP connection error"
            );
        }
    }

    Ok(())
}

/// Check if a hyper connection error indicates a client disconnect.
fn is_client_disconnect_error(err: &str) -> bool {
    let err = err.to_ascii_lowercase();
    err.contains("connection reset")
        || err.contains("broken pipe")
        || err.contains("connection abort")
        || err.contains("not connected")
        || err.contains("early eof")
        || err.contains("incomplete message")
        || err.contains("connection closed before")
}

/// Set TCP keepalive on a stream to detect dead connections.
fn set_tcp_keepalive(stream: &tokio::net::TcpStream) {
    #[cfg(unix)]
    use std::os::fd::AsFd;
    #[cfg(windows)]
    use std::os::windows::io::AsSocket;

    // Disable Nagle's algorithm for lower latency on small responses
    if let Err(e) = stream.set_nodelay(true) {
        warn!("Failed to set TCP_NODELAY on accepted HTTP stream: {}", e);
    }
    #[cfg(unix)]
    let borrowed = stream.as_fd();
    #[cfg(windows)]
    let borrowed = stream.as_socket();
    let socket = socket2::SockRef::from(&borrowed);
    let keepalive = socket2::TcpKeepalive::new().with_time(std::time::Duration::from_secs(60));
    if let Err(e) = socket.set_tcp_keepalive(&keepalive) {
        debug!("Failed to set TCP keepalive: {}", e);
    }
}

pub fn try_acquire_websocket_connection_permit(
    limit: Option<&Arc<tokio::sync::Semaphore>>,
) -> Result<Option<tokio::sync::OwnedSemaphorePermit>, tokio::sync::TryAcquireError> {
    match limit {
        Some(limit) => limit.clone().try_acquire_owned().map(Some),
        None => Ok(None),
    }
}

const WEBSOCKET_TRANSPORT_MANAGED_RESPONSE_HEADERS: [&str; 14] = [
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-connection",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
    "content-length",
    "sec-websocket-accept",
    "sec-websocket-key",
    "sec-websocket-version",
    "sec-websocket-protocol",
    "sec-websocket-extensions",
];

fn is_websocket_transport_managed_response_header(name: &str) -> bool {
    // The ordinary backend response strip predicate is lowercase-only because
    // backend maps are canonical. Plugin rejection maps can retain caller case,
    // so keep the boundary comparison case-insensitive without allocating a
    // lowercased copy on every WebSocket handshake.
    WEBSOCKET_TRANSPORT_MANAGED_RESPONSE_HEADERS
        .iter()
        .any(|reserved| name.eq_ignore_ascii_case(reserved))
}

pub(crate) fn strip_websocket_transport_managed_response_header_map(
    response_headers: &mut HashMap<String, String>,
) {
    response_headers.retain(|name, _| !is_websocket_transport_managed_response_header(name));
}

/// Apply deterministic initial-response policy at the WebSocket boundary, then
/// remove transport-managed fields. Successful handshake builders add their
/// protocol-required Upgrade / Extended CONNECT metadata after this returns, so
/// a configured remove or hostile replacement cannot corrupt H1, H2, or H3
/// handshake semantics. Negotiated subprotocol metadata is likewise added only
/// from the verified backend handshake.
pub(crate) fn finalize_websocket_response_headers(
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
    response_headers: &mut HashMap<String, String>,
) {
    crate::plugins::apply_initial_response_header_policies(
        initial_response_header_policy_plugins,
        response_headers,
    );
    strip_websocket_transport_managed_response_header_map(response_headers);
}

/// Apply the successful-handshake response chain in configured plugin order.
///
/// Static initial-response policies and request-local WebSocket decorators
/// share this pass so priority overrides remain authoritative across both
/// categories. The hook contract is non-rejecting; once the backend handshake
/// succeeds, this boundary always proceeds to a protocol-correct client
/// handshake after transport-managed fields are stripped.
pub(crate) fn finalize_successful_websocket_response_headers(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    response_status: u16,
    response_headers: &mut HashMap<String, String>,
) {
    for plugin in plugins {
        plugin.apply_websocket_handshake_response_headers(ctx, response_status, response_headers);
        if plugin.is_initial_response_header_policy() {
            plugin.apply_initial_response_header_policy(response_headers);
        }
    }
    strip_websocket_transport_managed_response_header_map(response_headers);
}

fn build_websocket_error_response(
    status: StatusCode,
    body: &str,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> Response<ProxyBody> {
    let mut response_headers =
        HashMap::from([("content-type".to_string(), "application/json".to_string())]);
    finalize_websocket_response_headers(
        initial_response_header_policy_plugins,
        &mut response_headers,
    );
    headers_mod::apply_response_headers(Response::builder().status(status), &response_headers)
        .body(ProxyBody::from_string(body))
        .unwrap_or_else(|_| build_websocket_error_fallback_response(status))
}

fn build_websocket_error_fallback_response(status: StatusCode) -> Response<ProxyBody> {
    let mut response = Response::new(ProxyBody::from_string(
        r#"{"error":"Internal server error"}"#,
    ));
    *response.status_mut() = status;
    response
}

/// Handle WebSocket requests AFTER authentication and authorization plugins have run.
///
/// Supports both HTTP/1.1 Upgrade (101 Switching Protocols) and HTTP/2 Extended CONNECT
/// (RFC 8441, 200 OK). The `is_h2_websocket` flag selects the response path; the backend
/// connection, bidirectional relay, and frame-level plugins are identical for both.
#[allow(clippy::too_many_arguments)]
async fn handle_websocket_request_authenticated(
    req: Request<Incoming>,
    state: Arc<ProxyState>,
    remote_addr: SocketAddr,
    proxy: Arc<Proxy>,
    ctx: RequestContext,
    proxy_headers: HashMap<String, String>,
    plugins: Arc<Vec<Arc<dyn Plugin>>>,
    initial_response_header_policy_plugins: Arc<Vec<Arc<dyn Plugin>>>,
    backend_admission_plugins: Arc<Vec<Arc<dyn Plugin>>>,
    plugin_execution_ns: u64,
    epoch: Arc<RequestEpoch>,
    upstream_target: Option<Arc<UpstreamTarget>>,
    upstream_balancer: Option<Arc<LoadBalancer>>,
    lb_hash_key: Option<String>,
    sticky_cookie_needed: bool,
    start_time: Instant,
    is_h2_websocket: bool,
    is_tls: bool,
    mesh_inbound_pre_handshake_app_port: Option<u16>,
    cb_target_key: Option<String>,
    cb_is_half_open_probe: bool,
    requires_websocket_framing: bool,
    query_string: String,
    strip_len: usize,
    backend_path_is_policy_bound: bool,
    // The client-requested path before any VirtualService `rewrite.uri`
    // was applied. Used for `request_path` in transaction logs so that
    // access logs record what the client sent, not the backend-rewritten
    // path stored in `ctx.path`.
    original_request_path: String,
) -> Result<Response<ProxyBody>, hyper::Error> {
    info!(
        "WebSocket upgrade request authenticated for proxy: {} from: {}",
        proxy.id,
        remote_addr.ip()
    );
    let mut ctx = ctx;
    // This dedicated handler is itself the authoritative flavor boundary.
    // Stamp it again here so every rejection it owns is stripped before the
    // generic finalizer invokes committed-response observers, independent of
    // how the caller classified or constructed the request context.
    ctx.set_websocket_response_boundary(true);
    let mut current_cb_target_key = cb_target_key;

    // Build backend URL using upstream target if available
    let (effective_host, effective_port) = if let Some(ref target) = upstream_target {
        (target.host.as_str(), target.port)
    } else {
        (proxy.backend_host.as_str(), proxy.backend_port)
    };
    let backend_url = build_websocket_backend_url_with_target(
        &proxy,
        &ctx.path,
        &query_string,
        effective_host,
        effective_port,
        strip_len,
        upstream_target.as_ref().and_then(|t| t.path.as_deref()),
    );

    // Get the upgrade parts from the request
    let (mut parts, _body) = req.into_parts();
    let mut client_headers = collect_forwardable_websocket_headers(&parts.headers, &proxy_headers);

    // Extract the OnUpgrade future
    let on_upgrade = match parts.extensions.remove::<OnUpgrade>() {
        Some(on_upgrade) => on_upgrade,
        None => {
            error!("Failed to extract OnUpgrade extension from WebSocket request");
            // The caller's CB check may have claimed a HALF_OPEN probe slot —
            // release it (gateway-side reject, not a backend outcome) so the
            // breaker can admit the next probe instead of wedging.
            release_circuit_breaker_probe_on_admission_reject(
                &state,
                &proxy,
                current_cb_target_key.as_deref(),
                cb_is_half_open_probe,
            );
            return Ok(build_websocket_error_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                r#"{"error":"Internal server error during WebSocket upgrade"}"#,
                &initial_response_header_policy_plugins,
            ));
        }
    };

    // Reject upgrades once the dedicated WebSocket pool is full.
    // This protects against idle upgraded-connection exhaustion without adding
    // any work to the per-frame forwarding path.
    let ws_connection_permit =
        match try_acquire_websocket_connection_permit(state.websocket_conn_limit.as_ref()) {
            Ok(permit) => permit,
            Err(_) => {
                warn!(
                    proxy_id = %proxy.id,
                    client_ip = %ctx.client_ip,
                    websocket_limit = state.env_config.websocket_max_connections,
                    "Rejecting WebSocket upgrade: connection limit reached"
                );
                // Use `original_request_path` — `ctx.path` may already be the
                // VirtualService-rewritten backend path at this point.
                log_rejected_request_with_path(
                    &plugins,
                    &ctx,
                    503,
                    start_time,
                    "websocket_connection_limit",
                    plugin_execution_ns,
                    Some(&original_request_path),
                )
                .await;
                record_request(&state, 503);
                // Gateway-side reject after the CB check — release a claimed
                // HALF_OPEN probe slot so the breaker doesn't wedge.
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    current_cb_target_key.as_deref(),
                    cb_is_half_open_probe,
                );
                return Ok(build_websocket_error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    r#"{"error":"WebSocket connection limit exceeded"}"#,
                    &initial_response_header_policy_plugins,
                ));
            }
        };

    // Inject authenticated identity headers for WebSocket connections.
    if let Some(username) = ctx.backend_consumer_username() {
        push_forwardable_header_override(
            &mut client_headers,
            "x-consumer-username",
            username.to_string(),
        );
    }
    if let Some(custom_id) = ctx.backend_consumer_custom_id() {
        push_forwardable_header_override(
            &mut client_headers,
            "x-consumer-custom-id",
            custom_id.to_string(),
        );
    }
    if let Some(country) = ctx.backend_geo_country() {
        push_forwardable_header_override(&mut client_headers, "x-geo-country", country.to_string());
    }

    // Egress baggage strip — see `FERRUM_MESH_EGRESS_STRIP_BAGGAGE_KEYS`.
    // The WebSocket handshake gets the same sanitized `proxy_headers` as the
    // HTTP/gRPC dispatch paths. Keep applying the vector helper here because
    // this function may append gateway assertions before backend dial.
    hbone_proxy::strip_egress_baggage_in_vec(
        &mut client_headers,
        &state.mesh_egress_strip_baggage_keys,
    );

    // Connect to backend BEFORE sending 101 to client.
    // If the backend is unreachable, we return 502 instead of a premature 101.
    // Supports retry with upstream target rotation for connection failures.
    let env_config = state.env_config.clone();
    // Compute the strictest parser limits before the backend handshake so its
    // framer is born with the same per-proxy bounds as the client-side framer.
    // This precedes every retry attempt and uses the immutable request plugin
    // generation, so target rotation cannot change policy mid-upgrade.
    let ws_size_limits =
        EffectiveWsSizeLimits::from_plugins(state.max_websocket_frame_size_bytes, &plugins);
    // The client-sent Host: the mesh egress Extended CONNECT `:authority` is
    // derived from it (the egress route is `preserve_host_header`) so the peer's
    // inbound route matches on the SERVICE host, exactly like HTTP egress. Read
    // from `ctx.headers` (the WS framing headers, incl. Host, are stripped from
    // `client_headers`). Stable across retry attempts.
    let ws_client_host = ctx.headers.get("host").cloned();
    let mut current_backend_url = backend_url;
    let mut current_target = upstream_target;
    let mut backend_admission_permits: Option<BackendAdmissionPermitSet>;
    let mut backend_admission_start: Instant;
    let mut ws_cb_probe_slot_available = cb_is_half_open_probe;
    let mut ws_attempt = 0u32;

    // Connection-wide idle tracker created BEFORE the backend dial so the
    // byte-level activity adapter can be installed under the backend framer
    // inside `connect_websocket_backend`; the same tracker is later wired
    // under the client framer by `run_websocket_proxy`. `None` disables the
    // idle bound entirely.
    let ws_idle_tracker =
        WsIdleTracker::from_timeout_seconds(proxy.effective_websocket_idle_timeout_seconds(
            state.env_config.websocket_idle_timeout_seconds,
        ));
    // The backend WebSocket connection acquired below is held for the full
    // session lifetime (moved into the spawned task), so this guard's slot is
    // released exactly when the dedicated backend connection closes. Captured
    // out of the loop alongside the handshake.
    let backend_conn_guard;
    let backend_handshake = loop {
        // Enforce DestinationRule `connectionPool.tcp.maxConnections` for this
        // destination port BEFORE dialing. A proxied WebSocket opens one
        // dedicated backend connection, so capping concurrent open connections
        // per `(host, policy-port)` keeps targetPort-remapped service lanes
        // isolated while the socket still dials `(host, dial-port)`. No cap
        // configured => `Ok(None)`, a single check with no map touch.
        let (ws_dial_host, ws_dial_port, ws_policy_port) = match &current_target {
            Some(target) => (
                target.host.as_str(),
                target.port,
                target.dispatch_policy_port(),
            ),
            None => (
                proxy.backend_host.as_str(),
                proxy.backend_port,
                proxy.backend_port,
            ),
        };
        let ws_max_connections = resolve_backend_max_connections(&proxy, ws_policy_port);
        let conn_slot = match state.backend_conn_limit.try_acquire(
            ws_dial_host,
            ws_policy_port,
            ws_max_connections,
        ) {
            Ok(slot) => slot,
            Err(limit) => {
                warn!(
                    proxy_id = %proxy.id,
                    client_ip = %ctx.client_ip,
                    backend_host = %ws_dial_host,
                    backend_port = ws_dial_port,
                    open_connections = limit.current,
                    max_connections = limit.cap,
                    "Rejecting WebSocket upgrade: DestinationRule maxConnections reached for backend"
                );
                log_rejected_request_with_path(
                    &plugins,
                    &ctx,
                    503,
                    start_time,
                    "backend_max_connections",
                    plugin_execution_ns,
                    Some(&original_request_path),
                )
                .await;
                record_request(&state, 503);
                // Gateway-side reject after the CB check — release a claimed
                // HALF_OPEN probe slot so the breaker doesn't wedge.
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    current_cb_target_key.as_deref(),
                    ws_cb_probe_slot_available,
                );
                return Ok(build_websocket_error_response(
                    StatusCode::SERVICE_UNAVAILABLE,
                    r#"{"error":"Backend connection limit exceeded"}"#,
                    &initial_response_header_policy_plugins,
                ));
            }
        };

        backend_admission_start = Instant::now();
        backend_admission_permits = match backend_dispatch::run_backend_admission_plugins(
            backend_admission_plugins.as_ref(),
            &ctx,
            &proxy,
            current_target.as_deref(),
            ProxyProtocol::WebSocket,
        ) {
            Ok(permits) => permits,
            Err(rejection) => {
                drop(conn_slot);
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    current_cb_target_key.as_deref(),
                    ws_cb_probe_slot_available,
                );
                let response = handle_backend_admission_rejection(
                    rejection,
                    &plugins,
                    &mut ctx,
                    &state,
                    start_time,
                    plugin_execution_ns,
                    Some(&original_request_path),
                    false,
                    None,
                )
                .await;
                return Ok(response);
            }
        };

        // Mesh egress (Sidecar `mesh.mtls` / Ambient `mesh.hbone`): route the WS
        // upgrade through an RFC 8441 Extended CONNECT over the SVID-mTLS / HBONE
        // tunnel instead of a direct plaintext/TLS dial. Fail-closed — a
        // mesh-tagged target that cannot dispatch over its secured transport
        // (missing SVID, unpinned peer, peer without Extended CONNECT) errors and
        // is NEVER dialed in plaintext (`connect_mesh_websocket_backend` never
        // calls `connect_websocket_backend`). Recomputed per attempt because the
        // retry loop may rotate `current_target`.
        let ws_mesh_egress = current_target.as_deref().and_then(websocket_mesh_egress);
        // The client's request target (`:path`), preserved byte-for-byte into the
        // mesh WS dial so `ws://svc-b/ws?room=1` reaches the destination as
        // `/ws?room=1` (not `/`). Derived from the SAME computed backend URL the
        // direct path dials (`build_websocket_backend_url_with_target`, which
        // already applied `strip_listen_path` + any target path override), so the
        // mesh path and the direct path forward the identical path+query. Default
        // to `/` if the URL somehow carries none (Extended CONNECT / inner H1
        // both require a leading `/`).
        //
        // For a CROSS-CLUSTER Ambient HBONE target `current_backend_url`'s
        // authority is the SCOPED SYNTHETIC identity (`mesh-xc-hbone|...`, with `|`
        // separators) — NOT a valid URI authority — so the parse below would fail
        // and silently collapse a real `/ws?room=1` to `/`. Mirror
        // `proxy_to_backend_hbone`: swap the synthetic authority for the real
        // `app_host` (the `mesh.hbone_authority_host` CONNECT authority) FIRST so
        // the URI parses and the client path is preserved through the tunnel. Only
        // `path_and_query` is read out (the host is dropped — the inner CONNECT
        // already targets the pod), so the rewritten authority is parse-only.
        // In-cluster targets have no synthetic host, so this is a byte-identical
        // no-op for them (the branch is gated on `target_hbone_cross_cluster`).
        let ws_backend_url_for_parse: std::borrow::Cow<'_, str> = match current_target.as_deref() {
            Some(target)
                if matches!(&ws_mesh_egress, Some(MeshWsEgress::AmbientHbone))
                    && hbone_pool::target_hbone_cross_cluster(target) =>
            {
                match hbone_pool::target_hbone_authority_host(target) {
                    Ok(app_host) => std::borrow::Cow::Owned(rewrite_backend_url_authority_host(
                        &current_backend_url,
                        &target.host,
                        app_host,
                    )),
                    // A malformed cross-cluster target (missing/invalid
                    // `mesh.hbone_authority_host`) fails CLOSED in the dial branch
                    // below with a typed pre-wire error; leave the URL as-is so the
                    // parse falls back to `/` and the branch surfaces the reject.
                    Err(_) => std::borrow::Cow::Borrowed(current_backend_url.as_str()),
                }
            }
            _ => std::borrow::Cow::Borrowed(current_backend_url.as_str()),
        };
        let ws_path_and_query: std::borrow::Cow<'_, str> = ws_backend_url_for_parse
            .parse::<hyper::Uri>()
            .ok()
            .and_then(|uri| uri.path_and_query().map(|pq| pq.as_str().to_string()))
            .map(std::borrow::Cow::Owned)
            .unwrap_or(std::borrow::Cow::Borrowed("/"));
        let ws_dial_result: Result<WsBackendHandshake, Box<dyn std::error::Error + Send + Sync>> =
            match (&ws_mesh_egress, current_target.as_deref()) {
                (Some(egress), Some(target)) => connect_mesh_websocket_backend(
                    &state,
                    &proxy,
                    target,
                    egress,
                    ws_client_host.as_deref(),
                    ws_path_and_query.as_ref(),
                    &client_headers,
                    ws_size_limits.max_frame_bytes,
                    ws_size_limits.max_message_bytes,
                    state.websocket_write_buffer_size,
                    ws_idle_tracker.clone(),
                    // Preserve the original authenticated mesh peer's identity into
                    // the Ambient HBONE baggage (Finding B / issue #2010 codex):
                    // for a WS request forwarded from an authenticated source
                    // workload, `ctx.peer_spiffe_id` is stamped as the asserted
                    // source so the remote AuthorizationPolicy / telemetry see the
                    // source workload, not the gateway SVID. `None` on an
                    // unauthenticated client → gateway SVID (HTTP-path parity).
                    ctx.peer_spiffe_id.as_ref(),
                )
                .await
                .map(|handshake| WsBackendHandshake::Mesh(Box::new(handshake))),
                _ => connect_websocket_backend(
                    &current_backend_url,
                    &proxy,
                    &env_config,
                    &client_headers,
                    state.tls_policy.as_deref(),
                    &state.crls,
                    ws_size_limits.max_frame_bytes,
                    ws_size_limits.max_message_bytes,
                    state.websocket_write_buffer_size,
                    ws_idle_tracker.clone(),
                    Some(&state.dns_cache),
                )
                .await
                .map(|handshake| WsBackendHandshake::Direct(Box::new(handshake))),
            };
        match ws_dial_result {
            Ok(handshake) => {
                backend_conn_guard = conn_slot;
                break handshake;
            }
            Err(e) => {
                // Connect/handshake failed: free this destination's slot before
                // a retry so a rotated target acquires its own slot and a
                // failed attempt never leaks a count.
                drop(conn_slot);
                // `connect_websocket_backend` covers more than TCP+TLS setup:
                // `connect_async_tls_with_config` ALSO sends the WebSocket
                // upgrade request and reads the backend's response. A failure
                // here can be either pre-wire (DNS / TCP connect / TLS
                // handshake — request bytes never crossed) or post-wire (the
                // backend received the upgrade request and rejected it with a
                // protocol error / non-101 response). Use the setup-phase
                // classifier so handshake-time rustls errors stay pre-wire
                // (`TlsError`), then gate the retry decision and the
                // circuit-breaker connect-flag on the unified
                // `request_reached_wire` boundary so genuinely post-wire
                // failures (ProtocolError, RequestError surfaced from
                // tungstenite::Error::Http / Protocol) do NOT replay under
                // `retry_on_connect_failure` and do NOT charge passive
                // health as a connect-class failure.
                let ws_error_class = retry::classify_boxed_setup_error(e.as_ref());
                let ws_is_pre_wire = !retry::request_reached_wire(ws_error_class);
                // A gateway-side egress-policy rejection (denied literal-IP
                // backend) never reached a backend: it must be non-retryable AND
                // neutral to backend health — no circuit-breaker trip and no
                // backend-admission failure — matching the HTTP/H3
                // DispatchPolicyRejected dispatch path.
                let ws_egress_denied =
                    matches!(ws_error_class, retry::ErrorClass::DispatchPolicyRejected);

                // Retry only on PRE-WIRE failures (DNS / TCP refused / TLS
                // handshake / port exhaustion). A backend that got the
                // upgrade request and chose to reject it must not be
                // retried under retry_on_connect_failure — that bypasses
                // retry_on_methods and would also lie in transaction logs.
                let should_retry_ws = if let Some(retry_config) = &proxy.retry {
                    ws_attempt < retry_config.max_retries
                        && retry_config.retry_on_connect_failure
                        && ws_is_pre_wire
                        && !ws_egress_denied
                } else {
                    false
                };

                let mut cb_failure_already_recorded = false;
                let mut backend_outcome_already_recorded = false;

                if should_retry_ws {
                    if let Some(permits) = backend_admission_permits.take() {
                        permits.record_backend_outcome(BackendAdmissionOutcome {
                            response_status: 502,
                            connection_error: ws_is_pre_wire,
                            error_class: Some(ws_error_class),
                            backend_elapsed: backend_admission_start.elapsed(),
                        });
                        backend_outcome_already_recorded = true;
                    }
                    // Safety: should_retry_ws is only true when proxy.retry.is_some()
                    // (see condition above). Fall through to 502 if the invariant
                    // ever breaks due to a refactor, rather than panicking.
                    let retry_config = match proxy.retry.as_ref() {
                        Some(rc) => rc,
                        None => {
                            let ws_body = r#"{"error":"Backend WebSocket connection failed"}"#;
                            return Ok(build_websocket_error_response(
                                StatusCode::BAD_GATEWAY,
                                ws_body,
                                &initial_response_header_policy_plugins,
                            ));
                        }
                    };

                    // Record circuit breaker failure for current target.
                    // The second argument is the "is_connect_error" flag
                    // that drives passive-health connect-class accounting
                    // — pass `ws_is_pre_wire` so a backend-side upgrade
                    // rejection (post-wire) doesn't charge the breaker as
                    // a connect failure. (We're inside the
                    // `should_retry_ws` branch so `ws_is_pre_wire == true`
                    // here by construction, but using the same predicate
                    // value keeps the invariant readable and survives a
                    // future refactor that moves this block.)
                    if let Some(cb_config) = &proxy.circuit_breaker {
                        let cb = state.circuit_breaker_cache.get_or_create(
                            &proxy.id,
                            current_cb_target_key.as_deref(),
                            cb_config,
                        );
                        cb.record_failure(502, ws_is_pre_wire, ws_cb_probe_slot_available);
                        ws_cb_probe_slot_available = false;
                        cb_failure_already_recorded = true;
                    }

                    let mut retry_backend_url = current_backend_url.clone();
                    let mut retry_target = current_target.clone();
                    let mut retry_cb_target_key = current_cb_target_key.clone();
                    let mut retry_path_mismatch = false;

                    // Try a different target on retry if load balancing is configured
                    if let (Some(_upstream_id), Some(prev_target)) =
                        (&proxy.upstream_id, &current_target)
                        && let Some(ref hash_key) = lb_hash_key
                        && let Some(next) = backend_dispatch::select_next_retry_target(
                            &state,
                            &epoch,
                            &proxy,
                            prev_target,
                            hash_key,
                            &ctx.client_ip,
                            &ctx.headers,
                        )
                    {
                        if !retry_target_preserves_backend_path(
                            backend_path_is_policy_bound,
                            &proxy,
                            &ctx.path,
                            strip_len,
                            prev_target,
                            &next,
                        ) {
                            retry_path_mismatch = true;
                            warn!(
                                proxy_id = %proxy.id,
                                "Aborting WebSocket retry because the candidate would change the authorized backend method path"
                            );
                        } else {
                            retry_backend_url = build_websocket_backend_url_with_target(
                                &proxy,
                                &ctx.path,
                                &query_string,
                                &next.host,
                                next.port,
                                strip_len,
                                next.path.as_deref(),
                            );
                            retry_cb_target_key =
                                Some(crate::circuit_breaker::target_key(&next.host, next.port));
                            retry_target = Some(next);
                        }
                    }

                    if !retry_path_mismatch {
                        let delay = retry::retry_delay(retry_config, ws_attempt);
                        tokio::time::sleep(delay).await;
                        ws_attempt += 1;
                    }

                    // A retry may rotate to a different app-port lane, and a
                    // live PeerAuthentication reload may also tighten the
                    // current lane during the retry backoff. Re-check before
                    // acquiring any admission or circuit-breaker state for the
                    // next target and before attempting its backend handshake.
                    if !retry_path_mismatch
                        && let Some(mismatch) = mesh_inbound_peer_auth_transport_mismatch(
                            &state,
                            ctx.mesh_direction,
                            mesh_inbound_pre_handshake_app_port,
                            &proxy,
                            retry_target.as_deref(),
                            is_tls,
                            ctx.tls_client_cert_der.is_some(),
                        )
                    {
                        return Ok(reject_mesh_inbound_peer_auth_transport_mismatch(
                            &state,
                            plugins.as_ref(),
                            &mut ctx,
                            &proxy,
                            mismatch,
                            is_tls,
                            false,
                            start_time,
                            plugin_execution_ns,
                            "mesh_inbound_peer_auth_retry_target_mismatch",
                            Some(&original_request_path),
                        )
                        .await);
                    }

                    let mut retry_admitted_by_cb = true;
                    if !retry_path_mismatch && let Some(cb_config) = &proxy.circuit_breaker {
                        match state.circuit_breaker_cache.can_execute(
                            &proxy.id,
                            retry_cb_target_key.as_deref(),
                            cb_config,
                        ) {
                            Ok((_cb, is_half_open_probe)) => {
                                ws_cb_probe_slot_available = is_half_open_probe;
                            }
                            Err(_) => {
                                retry_admitted_by_cb = false;
                                warn!(
                                    proxy_id = %proxy.id,
                                    attempt = ws_attempt,
                                    "WebSocket retry target rejected by circuit breaker"
                                );
                            }
                        }
                    }

                    if retry_admitted_by_cb && !retry_path_mismatch {
                        current_backend_url = retry_backend_url;
                        current_target = retry_target;
                        current_cb_target_key = retry_cb_target_key;

                        warn!(
                            proxy_id = %proxy.id,
                            attempt = ws_attempt,
                            max_retries = retry_config.max_retries,
                            error_class = %ws_error_class,
                            "Retrying WebSocket backend connection"
                        );
                        continue;
                    }
                }

                // No retry — return error. Use the unified
                // `error_class_log_kind` so the `error_kind` field matches
                // the per-protocol log labels emitted everywhere else
                // (operators grep one set of strings); a backend that
                // rejected the upgrade will now log
                // `error_kind=protocol_error` or `request_error` rather
                // than the misleading hardcoded `connect_failure`.
                error!(
                    proxy_id = %proxy.id,
                    backend_url = %current_backend_url,
                    error_kind = retry::error_class_log_kind(ws_error_class),
                    error_class = %ws_error_class,
                    error = %e,
                    "WebSocket backend connection failed"
                );
                // Record the failure so the breaker / passive health see it
                // and a claimed HALF_OPEN probe slot is released. Previously
                // only the retry branch recorded — with retries unconfigured
                // (the default), WS backend connect failures never fed the
                // breaker at all on H1/H2, and an admitted probe slot leaked
                // permanently.
                if !cb_failure_already_recorded && let Some(cb_config) = &proxy.circuit_breaker {
                    let cb = state.circuit_breaker_cache.get_or_create(
                        &proxy.id,
                        current_cb_target_key.as_deref(),
                        cb_config,
                    );
                    if ws_egress_denied {
                        // Gateway-side egress denial dialed no backend: release any
                        // admitted HALF_OPEN probe slot NEUTRALLY (no failure count)
                        // so the breaker can recover, rather than leaking it by
                        // skipping the record entirely.
                        cb.record_neutral(ws_cb_probe_slot_available);
                    } else {
                        cb.record_failure(502, ws_is_pre_wire, ws_cb_probe_slot_available);
                    }
                }
                if !backend_outcome_already_recorded
                    && !ws_egress_denied
                    && let Some(permits) = backend_admission_permits.take()
                {
                    permits.record_backend_outcome(BackendAdmissionOutcome {
                        response_status: 502,
                        connection_error: ws_is_pre_wire,
                        error_class: Some(ws_error_class),
                        backend_elapsed: backend_admission_start.elapsed(),
                    });
                }
                state.request_count.fetch_add(1, Ordering::Relaxed);
                record_status(&state, 502);

                // Log with error_class for WebSocket backend failures.
                // Dispatch to the full plugin chain — the default `.log()` impl
                // is a no-op, and plugins outside the logging priority band
                // (e.g., `otel_tracing` at priority 25) still need the hook so
                // rejected/error transactions reach tracing sinks.
                if !plugins.is_empty() {
                    {
                        // Use monotonic Instant rather than wall-clock to avoid NTP skew.
                        let ws_total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
                        let ws_plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
                        let ws_plugin_external_io_ms =
                            ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
                        let ws_gateway_overhead_ms =
                            (ws_total_ms - ws_plugin_execution_ms).max(0.0);
                        let mut metadata = clone_log_metadata(&ctx);
                        metadata.insert(
                            "rejection_phase".to_string(),
                            "websocket_backend_error".to_string(),
                        );
                        let ws_err_method = if is_h2_websocket { "CONNECT" } else { "GET" };
                        let summary = TransactionSummary {
                            namespace: proxy.namespace.clone(),
                            timestamp_received: ctx.timestamp_received.to_rfc3339(),
                            client_ip: ctx.client_ip.clone(),
                            consumer_username: ctx.effective_identity().map(str::to_owned),
                            auth_method: ctx.auth_method,
                            http_method: ws_err_method.to_string(),
                            // Record the path the client sent, not the
                            // VirtualService-rewritten backend path in ctx.path.
                            request_path: original_request_path.clone(),
                            proxy_id: Some(proxy.id.clone()),
                            proxy_name: proxy.name.clone(),
                            backend_target: Some(
                                strip_query_params(&current_backend_url).to_string(),
                            ),
                            response_status_code: 502,
                            latency_total_ms: ws_total_ms,
                            latency_gateway_processing_ms: ws_total_ms,
                            latency_backend_ttfb_ms: -1.0,
                            latency_backend_total_ms: -1.0,
                            latency_plugin_execution_ms: ws_plugin_execution_ms,
                            latency_plugin_external_io_ms: ws_plugin_external_io_ms,
                            latency_gateway_overhead_ms: ws_gateway_overhead_ms,
                            request_user_agent: ctx.headers.get("user-agent").cloned(),
                            error_class: Some(ws_error_class),
                            metadata,
                            ai_usage_export: ctx.ai_usage_export.clone(),
                            proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
                            ..TransactionSummary::default()
                        };
                        crate::plugins::log_with_mirror_before_buffered_response(
                            &plugins, summary, &ctx,
                        )
                        .await;
                    }
                } else {
                    crate::runtime_metrics::global_ref()
                        .record_http_error(Some(&proxy.id), ws_error_class);
                }

                let ws_body = r#"{"error":"Backend WebSocket connection failed"}"#;
                return Ok(build_websocket_error_response(
                    StatusCode::BAD_GATEWAY,
                    ws_body,
                    &initial_response_header_policy_plugins,
                ));
            }
        }
    };

    // A successful CROSS-CLUSTER Ambient HBONE WS dial leaves `current_target.host`
    // and `current_backend_url` holding the SCOPED SYNTHETIC `mesh-xc-hbone|...`
    // authority (only the earlier `ws_backend_url_for_parse` rewrite recovered
    // `path_and_query`). The success path below reuses `current_backend_url` for
    // the transaction / disconnect `backend_target` and `current_target.host` for
    // `websocket_dns_resolution_host` — so without a fixup the session logs an
    // invalid backend URL and tries to DNS-resolve a non-DNS synthetic name.
    // Recompute a DISPLAY/RESOLVE target from the REAL dial `app_host`
    // (`mesh.hbone_authority_host`) for this branch only; in-cluster / Sidecar /
    // direct paths keep `current_backend_url` / `current_target.host` byte-for-byte
    // (issue #2010 codex Finding C). Gated on the FINAL rotated `current_target`.
    let ws_final_mesh_egress = current_target.as_deref().and_then(websocket_mesh_egress);
    let (ws_display_backend_url, ws_resolve_host_override): (
        std::borrow::Cow<'_, str>,
        Option<&str>,
    ) = match current_target.as_deref() {
        Some(target)
            if matches!(&ws_final_mesh_egress, Some(MeshWsEgress::AmbientHbone))
                && hbone_pool::target_hbone_cross_cluster(target) =>
        {
            match hbone_pool::target_hbone_authority_host(target) {
                // `app_host` is the real pod addr:app-port the tunnel dialed;
                // swap it into the URL authority (path/query preserved) and use
                // it as the DNS-resolve host. The dial succeeded, so the tag is
                // present and non-synthetic here.
                Ok(app_host) => (
                    std::borrow::Cow::Owned(rewrite_backend_url_authority_host(
                        &current_backend_url,
                        &target.host,
                        app_host,
                    )),
                    Some(app_host),
                ),
                // Unreachable on a successful dial (the pre-wire guard rejects a
                // missing/invalid authority host before dialing), but stay
                // fail-safe: fall back to the existing values rather than panic.
                Err(_) => (
                    std::borrow::Cow::Borrowed(current_backend_url.as_str()),
                    None,
                ),
            }
        }
        _ => (
            std::borrow::Cow::Borrowed(current_backend_url.as_str()),
            None,
        ),
    };

    // Backend handshake succeeded — record the success so the breaker sees a
    // healthy outcome and, when this request was admitted as a HALF_OPEN
    // probe, the probe slot is released and the breaker can close. Without
    // this, every successful WS upgrade admitted as a probe permanently
    // consumed a `half_open_in_flight` slot, and after `half_open_max_requests`
    // upgrades the breaker wedged in HALF_OPEN, 503ing ALL traffic to the
    // target. Mirrors the H3 WS path (`src/http3/websocket.rs`).
    if let Some(cb_config) = &proxy.circuit_breaker {
        let cb = state.circuit_breaker_cache.get_or_create(
            &proxy.id,
            current_cb_target_key.as_deref(),
            cb_config,
        );
        cb.record_success(ws_cb_probe_slot_available);
    }

    let ws_lb_guard =
        LoadBalancerConnectionGuard::new(current_target.clone(), upstream_balancer.clone());
    if let Some(permits) = backend_admission_permits.as_ref() {
        // The permit is held for the full session below, so this records the
        // backend-handshake latency without growing the limit — otherwise each
        // concurrent session ratchets the limit up and defeats the in-flight
        // WebSocket session cap.
        permits.record_backend_outcome_holding(BackendAdmissionOutcome {
            response_status: if is_h2_websocket { 200 } else { 101 },
            connection_error: false,
            error_class: None,
            backend_elapsed: backend_admission_start.elapsed(),
        });
    }

    // Backend verified — record status and log.
    // HTTP/2 Extended CONNECT returns 200 OK; HTTP/1.1 returns 101 Switching Protocols.
    let ws_status_code: u16 = if is_h2_websocket { 200 } else { 101 };
    state.request_count.fetch_add(1, Ordering::Relaxed);
    record_status(&state, ws_status_code);

    // Measure total latency using monotonic Instant (NTP-safe).
    let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;

    // Resolve backend IP from DNS cache for WebSocket tx log. Use the
    // effective LB target when present, not the proxy's static backend_host. For a
    // cross-cluster Ambient WS session `ws_resolve_host_override` carries the real
    // pod `app_host` so we don't try to resolve the synthetic `mesh-xc-hbone|...`
    // name (Finding C); it is `None` on every other path → the normal target host.
    let ws_resolve_host = ws_resolve_host_override
        .unwrap_or_else(|| websocket_dns_resolution_host(&proxy, current_target.as_deref()));
    let ws_resolved_ip = state
        .dns_cache
        .resolve(
            ws_resolve_host,
            proxy.dns_override.as_deref(),
            proxy.dns_cache_ttl_seconds,
        )
        .await
        .ok()
        .map(|ip| ip.to_string());

    let ws_plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
    let ws_plugin_external_io_ms =
        ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
    let ws_gateway_overhead_ms = (total_ms - ws_plugin_execution_ms).max(0.0);

    let ws_method = if is_h2_websocket { "CONNECT" } else { "GET" };
    let summary = TransactionSummary {
        namespace: proxy.namespace.clone(),
        timestamp_received: ctx.timestamp_received.to_rfc3339(),
        client_ip: ctx.client_ip.clone(),
        consumer_username: ctx.effective_identity().map(str::to_owned),
        auth_method: ctx.auth_method,
        http_method: ws_method.to_string(),
        // Record the path the client sent, not the VirtualService-rewritten
        // backend path stored in ctx.path after the rewrite in the caller.
        request_path: original_request_path.clone(),
        proxy_id: Some(proxy.id.clone()),
        proxy_name: proxy.name.clone(),
        // `ws_display_backend_url` == `current_backend_url` on every path except a
        // cross-cluster Ambient WS session, where it carries the real pod authority
        // instead of the synthetic `mesh-xc-hbone|...` key (Finding C).
        backend_target: Some(strip_query_params(&ws_display_backend_url).to_string()),
        backend_resolved_ip: ws_resolved_ip,
        response_status_code: ws_status_code,
        latency_total_ms: total_ms,
        latency_gateway_processing_ms: total_ms,
        latency_backend_ttfb_ms: 0.0,
        latency_backend_total_ms: 0.0,
        latency_plugin_execution_ms: ws_plugin_execution_ms,
        latency_plugin_external_io_ms: ws_plugin_external_io_ms,
        latency_gateway_overhead_ms: ws_gateway_overhead_ms,
        request_user_agent: ctx.headers.get("user-agent").cloned(),
        metadata: clone_log_metadata(&ctx),
        ai_usage_export: ctx.ai_usage_export.clone(),
        proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
        ..TransactionSummary::default()
    };

    crate::plugins::log_with_mirror_before_buffered_response(&plugins, summary, &ctx).await;

    // Apply response policy before gateway-owned affinity and transport fields.
    // This matches ordinary HTTP/gRPC ordering: operator policy governs backend
    // metadata, while the gateway's selected-target cookie and mandatory
    // handshake fields are committed at the client boundary afterward.
    let response_status = if is_h2_websocket {
        StatusCode::OK
    } else {
        StatusCode::SWITCHING_PROTOCOLS
    };
    let mut response_headers = HashMap::new();
    finalize_successful_websocket_response_headers(
        &plugins,
        &ctx,
        response_status.as_u16(),
        &mut response_headers,
    );
    if sticky_cookie_needed
        && let (Some(upstream_id), Some(target)) = (&proxy.upstream_id, &current_target)
    {
        let strategy = backend_dispatch::hash_on_strategy_for_selected_target(
            &proxy,
            &epoch.load_balancer,
            upstream_id,
            target,
        );
        if let HashOnStrategy::Cookie(ref cookie_name) = strategy {
            let upstream = LoadBalancerCache::get_upstream_from(&epoch.load_balancer, upstream_id);
            let default_cc = crate::config::types::HashOnCookieConfig::default();
            let cookie_config = upstream
                .as_ref()
                .and_then(|u| u.hash_on_cookie_config.as_ref())
                .unwrap_or(&default_cc);
            let cookie_val = build_sticky_cookie_header(cookie_name, target, cookie_config);
            headers_mod::append_set_cookie_header(&mut response_headers, cookie_val);
        }
    }

    // Build the upgrade response.
    // HTTP/2 Extended CONNECT (RFC 8441): 200 OK — the H2 stream becomes the WebSocket
    // transport. No Upgrade/Connection/Sec-WebSocket-Accept headers (those are HTTP/1.1).
    // HTTP/1.1: 101 Switching Protocols with standard WebSocket handshake headers.
    let mut ws_resp_builder = headers_mod::apply_response_headers(
        Response::builder().status(response_status),
        &response_headers,
    );
    if !is_h2_websocket {
        ws_resp_builder = ws_resp_builder
            .header("upgrade", "websocket")
            .header("connection", "upgrade")
            .header(
                "sec-websocket-accept",
                ws_accept_from_key(
                    parts
                        .headers
                        .get("sec-websocket-key")
                        .and_then(|k| k.to_str().ok())
                        .unwrap_or(""),
                ),
            );
    }

    // Forward the backend's negotiated subprotocol (RFC 6455 §11.3.4, RFC
    // 8441 §5.2). It is appended after response policy so configuration cannot
    // remove it or fabricate a value the backend did not negotiate.
    if let Some(proto) = backend_handshake.negotiated_subprotocol().cloned() {
        ws_resp_builder = ws_resp_builder.header("sec-websocket-protocol", proto);
    }

    let upgrade_response = ws_resp_builder
        .body(ProxyBody::empty())
        .unwrap_or_else(|_| {
            let mut response = Response::new(ProxyBody::empty());
            *response.status_mut() = response_status;
            response
        });

    // Keep parser-policy plugins out of the post-reassembly hook loop. The
    // lists come from the same request-cache snapshot, so neither path reloads
    // the cache or risks mixing generations.
    let (ws_framing_plugins, ws_frame_plugins) =
        collect_websocket_relay_plugins(&plugins, requires_websocket_framing);
    // Collect disconnect-hook plugins separately. These fire exactly once at
    // session end instead of per-frame, so keeping them in their own list
    // avoids the per-frame filter cost paid by the frame-hook path.
    let ws_disconnect_plugins: Vec<Arc<dyn Plugin>> = plugins
        .iter()
        .filter(|p| p.requires_ws_disconnect_hooks())
        .cloned()
        .collect();

    // Spawn bidirectional forwarding task (awaits client upgrade, then proxies)
    let proxy_id = proxy.id.clone();
    let ws_conn_id = state.ws_connection_counter.fetch_add(1, Ordering::Relaxed);
    let max_ws_frame = state.max_websocket_frame_size_bytes;
    let ws_write_buf = state.websocket_write_buffer_size;
    let ws_tunnel = state.websocket_tunnel_mode;
    let ws_tunnel_idle_disabled_safety_cap =
        websocket_tunnel_idle_disabled_safety_cap(state.env_config.tcp_half_close_max_wait_seconds);
    let adaptive_buf = state.adaptive_buffer.clone();
    // Track the upgraded WebSocket session in `OverloadState.active_connections`
    // so graceful drain waits for in-flight WS sessions before exiting.
    //
    // Why a fresh `ConnectionGuard` rather than reusing the request-side guard:
    //   - The originating HTTP request's `RequestGuard` is attached to the
    //     `ProxyBody::empty()` returned upstream (see `handle_proxy_request`).
    //     Hyper finishes flushing that empty body the moment the 101/200 is
    //     written, dropping the `RequestGuard` immediately. The HTTP request is
    //     genuinely complete at that point — its accounting should release.
    //   - The outer per-connection `_conn_guard` (created in the accept loop in
    //     `proxy_listener` / `handle_tls_connection`) covers the underlying TCP
    //     connection only until `serve_connection_with_upgrades` returns, which
    //     happens shortly after `OnUpgrade` hands off the I/O. The WS session
    //     lifetime extends well beyond the HTTP layer's view of the connection.
    //   - A WebSocket session is functionally a long-lived "connection" (one
    //     persistent client peer using the frontend's connection slot), so
    //     `ConnectionGuard` is the semantically correct counter.
    //
    // Captured by the spawned task below so it lives until the WS session ends.
    let ws_session_guard = crate::overload::ConnectionGuard::new(&state.overload);
    // Capture session metadata while the originating RequestContext + proxy are
    // still in scope. Passed to run_websocket_proxy so it can construct a
    // WsDisconnectContext at teardown for plugins that opted in to
    // on_ws_disconnect. Building this here (vs. inside run_websocket_proxy) is
    // effectively free when ws_disconnect_plugins is empty because the strings
    // are moved, not cloned, into an owned struct.
    // WebSocket upgrades arrive on either the plaintext HTTP proxy listener or
    // the TLS HTTPS/H2 listener. Choose the matching port so disconnect
    // metadata, logging plugins, and downstream alerts key on the port the
    // client actually connected to instead of always reporting the plaintext
    // port (which is misleading — or `0` — on TLS-only deployments).
    let listen_port = if is_tls {
        state.env_config.proxy_https_port
    } else {
        state.env_config.proxy_http_port
    };
    let session_meta = WsSessionMeta {
        namespace: proxy.namespace.clone(),
        proxy_name: proxy.name.clone(),
        client_ip: ctx.client_ip.clone(),
        // Real pod authority for a cross-cluster Ambient WS session, else the
        // unchanged `current_backend_url` (Finding C) — so the disconnect log
        // records a valid backend URL, not the synthetic `mesh-xc-hbone|...` key.
        backend_target: strip_query_params(&ws_display_backend_url).to_string(),
        listen_port,
        // Same admission ID passed into the relay / on_ws_frame so disconnect
        // hooks (including upgrade-handoff failure below) correlate without a
        // per-frame lookup map.
        connection_id: ws_conn_id,
        consumer_username: ctx.effective_identity().map(str::to_owned),
        auth_method: ctx.auth_method,
        metadata: clone_log_metadata(&ctx),
        proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
        session_start: chrono::Utc::now(),
        session_start_mono: Instant::now(),
    };
    tokio::spawn(async move {
        let _ws_lb_guard = ws_lb_guard;
        let _backend_admission_permits = backend_admission_permits;
        // Hold the connection guard for the full WS session lifetime. Drops on
        // every exit path (upgrade failure, run_websocket_proxy completion or
        // error), decrementing `active_connections` exactly once.
        let _ws_session_guard = ws_session_guard;
        // Hold the per-destination backend-connection slot (DestinationRule
        // `maxConnections`) for the same session lifetime. `Option`: `None`
        // when no cap is configured for the destination port. Dropping it on
        // any session-end path releases the slot exactly once — no leak.
        let _backend_conn_guard = backend_conn_guard;
        match on_upgrade.await {
            Ok(upgraded) => {
                // H1/H2 frontends adapt hyper's `Upgraded` (which is
                // `AsyncRead + AsyncWrite` in hyper-1 land) into the
                // tokio AsyncRead/AsyncWrite vocabulary via `TokioIo`.
                // The H3 frontend (`src/http3/websocket.rs`) bypasses
                // this wrap and passes its own duplex adapter directly
                // to `run_websocket_proxy`, which is now generic over
                // the client transport type.
                //
                // `run_websocket_proxy` is also generic over the backend
                // transport, so dispatch on the handshake variant: a direct
                // TCP/TLS backend stream, or a mesh egress
                // `WebSocketStream<H2ConnectTunnel>` over an Extended CONNECT
                // tunnel. Both share the same frame relay and plugin pipeline.
                let client_io = TokioIo::new(upgraded);
                let relay_result = match backend_handshake {
                    WsBackendHandshake::Direct(handshake) => {
                        let handshake = *handshake;
                        run_websocket_proxy(
                            client_io,
                            handshake.stream,
                            &proxy_id,
                            ws_conn_id,
                            ws_framing_plugins,
                            ws_frame_plugins,
                            ws_disconnect_plugins,
                            session_meta,
                            ws_connection_permit,
                            max_ws_frame,
                            ws_write_buf,
                            ws_tunnel,
                            ws_tunnel_idle_disabled_safety_cap,
                            // H1/H2: RFC 6455 / RFC 8441 mandate masked
                            // client-to-server frames. The H3 caller in
                            // `src/http3/websocket.rs` passes `true` for
                            // RFC 9220 §5 compliance.
                            false,
                            ws_idle_tracker,
                            &adaptive_buf,
                        )
                        .await
                    }
                    WsBackendHandshake::Mesh(handshake) => {
                        let handshake = *handshake;
                        run_websocket_proxy(
                            client_io,
                            handshake.stream,
                            &proxy_id,
                            ws_conn_id,
                            ws_framing_plugins,
                            ws_frame_plugins,
                            ws_disconnect_plugins,
                            session_meta,
                            ws_connection_permit,
                            max_ws_frame,
                            ws_write_buf,
                            ws_tunnel,
                            ws_tunnel_idle_disabled_safety_cap,
                            false,
                            ws_idle_tracker,
                            &adaptive_buf,
                        )
                        .await
                    }
                };
                if let Err(e) = relay_result {
                    error!("WebSocket proxying error for {}: {}", proxy_id, e);
                }
            }
            Err(e) => {
                error!(
                    "Failed to upgrade WebSocket connection for {}: {}",
                    proxy_id, e
                );
                // The handshake response (101 for H1, 200 for H2) was already
                // sent to the client, so a plugin that opted into
                // on_ws_disconnect must still observe a disconnect even though
                // the upgrade handoff failed before any frames flowed.
                // run_websocket_proxy (the only other site that fires these
                // hooks) never runs on this path, so fire them here directly
                // with zero frame/byte counts and an upgrade-failure tag,
                // reusing the same construction as the tunnel/frame paths.
                fire_ws_tunnel_disconnect_hooks(
                    &ws_disconnect_plugins,
                    &proxy_id,
                    &session_meta,
                    0,
                    0,
                    Some((
                        crate::plugins::Direction::Unknown,
                        retry::ErrorClass::ConnectionClosed,
                        None,
                    )),
                )
                .await;
            }
        }
    });

    info!(
        "WebSocket upgrade response sent for authenticated connection: {} -> {}",
        proxy.id, current_backend_url
    );

    Ok(upgrade_response)
}

/// Collect sanitized proxy headers that should be forwarded to the backend WebSocket.
/// Hop-by-hop headers and WebSocket handshake headers are excluded.
#[cfg(test)]
fn collect_forwardable_proxy_headers(headers: &HashMap<String, String>) -> Vec<(String, String)> {
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    headers
        .iter()
        .filter_map(|(name, value)| {
            let lower_name = name.to_ascii_lowercase();
            if headers_mod::is_backend_request_strip_header(lower_name.as_str())
                || is_websocket_backend_strip_header(lower_name.as_str())
                || connection_listed_strip
                    .iter()
                    .any(|listed| listed == lower_name.as_str())
            {
                return None;
            }
            Some((name.clone(), value.clone()))
        })
        .collect()
}

/// Collect backend WebSocket headers while preserving repeated client-provided
/// values when the sanitized proxy header map still represents the full raw set.
///
/// `RequestContext::headers` is a `HashMap`, so repeated fields are folded
/// after materialization (`; ` for cookie crumbs, `, ` otherwise). The raw
/// `HeaderMap` is still available from the upgrade request; use it to retain
/// handshake-equivalent repeated headers such as multiple
/// `Sec-WebSocket-Protocol` values, while still honoring plugin-driven strips
/// and rewrites reflected in `proxy_headers`.
pub(crate) fn collect_forwardable_websocket_headers(
    raw_headers: &hyper::HeaderMap,
    proxy_headers: &HashMap<String, String>,
) -> Vec<(String, String)> {
    let mut forwarded = Vec::new();
    let mut preserved_raw_names = HashSet::new();
    let raw_connection_listed_strip = headers_mod::parse_connection_listed_headers(raw_headers);
    let proxy_connection_listed_strip =
        headers_mod::parse_connection_listed_from_str_map(proxy_headers);

    for name in raw_headers.keys() {
        let lower_name = name.as_str().to_ascii_lowercase();
        if headers_mod::is_backend_request_strip_header(lower_name.as_str())
            || is_websocket_backend_strip_header(lower_name.as_str())
            || raw_connection_listed_strip
                .iter()
                .any(|listed| listed.as_str() == lower_name.as_str())
            || proxy_connection_listed_strip
                .iter()
                .any(|listed| listed == lower_name.as_str())
        {
            continue;
        }

        let Some((sanitized_name, sanitized_value)) =
            proxy_header_entry_case_insensitive(proxy_headers, lower_name.as_str())
        else {
            continue;
        };

        let raw_values: Vec<&str> = raw_headers
            .get_all(name)
            .iter()
            .filter_map(|value| value.to_str().ok())
            .collect();
        if sanitized_value_preserves_raw_values(name.as_str(), &raw_values, sanitized_value)
            || sanitized_value == &materialized_raw_header_value(name.as_str(), &raw_values)
        {
            preserved_raw_names.insert(lower_name);
            for value in raw_values {
                forwarded.push((name.as_str().to_string(), value.to_string()));
            }
        } else {
            forwarded.push((sanitized_name.clone(), sanitized_value.clone()));
        }
    }

    for (name, value) in proxy_headers {
        let lower_name = name.to_ascii_lowercase();
        if preserved_raw_names.contains(lower_name.as_str())
            || headers_mod::is_backend_request_strip_header(lower_name.as_str())
            || is_websocket_backend_strip_header(lower_name.as_str())
            || raw_connection_listed_strip
                .iter()
                .any(|listed| listed.as_str() == lower_name.as_str())
            || proxy_connection_listed_strip
                .iter()
                .any(|listed| listed == lower_name.as_str())
        {
            continue;
        }
        if raw_headers.contains_key(lower_name.as_str()) {
            continue;
        }
        forwarded.push((name.clone(), value.clone()));
    }

    forwarded
}

fn sanitized_value_preserves_raw_values(
    name: &str,
    raw_values: &[&str],
    sanitized_value: &str,
) -> bool {
    match raw_values {
        [] => false,
        [only] => *only == sanitized_value,
        _ => {
            // This exact fast-path only applies to list-style values where
            // individual raw values do not contain the fold delimiter. If
            // that is not true, callers fall back to the shared materialized
            // form.
            let delimiter = if name.eq_ignore_ascii_case("cookie") {
                ';'
            } else {
                ','
            };
            let mut sanitized_values = sanitized_value.split(delimiter).map(str::trim);
            raw_values
                .iter()
                .map(|value| value.trim())
                .all(|raw_value| sanitized_values.next() == Some(raw_value))
                && sanitized_values.next().is_none()
        }
    }
}

fn materialized_raw_header_value(name: &str, raw_values: &[&str]) -> String {
    raw_values.join(crate::plugins::repeated_request_header_separator(name))
}

fn proxy_header_entry_case_insensitive<'a>(
    headers: &'a HashMap<String, String>,
    name: &str,
) -> Option<(&'a String, &'a String)> {
    headers
        .iter()
        .find(|(header_name, _)| header_name.eq_ignore_ascii_case(name))
}

fn is_websocket_backend_strip_header(name: &str) -> bool {
    matches!(
        name,
        "host"
            | "proxy-authenticate"
            | "sec-websocket-key"
            | "sec-websocket-version"
            | "sec-websocket-accept"
            // The gateway's WebSocket bridge (tungstenite) cannot encode or
            // decode permessage-deflate, so the client's extension OFFER must
            // not reach the backend: a deflate-capable backend would accept it,
            // set rsv1 on data frames, and the bridge would tear the session
            // down with a protocol error. Strip the offer so no extension is
            // ever negotiated end to end.
            | "sec-websocket-extensions"
            | "x-consumer-username"
            | "x-consumer-custom-id"
            | "x-geo-country"
    )
}

fn push_forwardable_header_override(
    headers: &mut Vec<(String, String)>,
    name: &'static str,
    value: String,
) {
    headers.retain(|(existing_name, _)| !existing_name.eq_ignore_ascii_case(name));
    headers.push((name.to_string(), value));
}

fn sanitize_reserved_gateway_assertion_headers(headers: &mut HashMap<String, String>) {
    headers.retain(|name, _| {
        !name.eq_ignore_ascii_case("x-consumer-username")
            && !name.eq_ignore_ascii_case("x-consumer-custom-id")
            && !name.eq_ignore_ascii_case("x-geo-country")
    });
}

/// Remove plugin-controlled gateway assertion headers and restore only the
/// authenticated principal and private GeoIP lookup result for dispatch.
pub(crate) fn refresh_backend_gateway_assertion_headers(
    ctx: &RequestContext,
    headers: &mut HashMap<String, String>,
) {
    let principal_username = ctx.backend_consumer_username().map(str::to_string);
    let principal_custom_id = principal_username
        .as_ref()
        .and_then(|_| ctx.backend_consumer_custom_id().map(str::to_string));
    let geo_country = ctx.backend_geo_country().map(str::to_string);
    let source_has_reserved_assertion = principal_username.is_none()
        && geo_country.is_none()
        && headers.keys().any(|name| {
            name.eq_ignore_ascii_case("x-consumer-username")
                || name.eq_ignore_ascii_case("x-consumer-custom-id")
                || name.eq_ignore_ascii_case("x-geo-country")
        });
    if principal_username.is_none() && geo_country.is_none() && !source_has_reserved_assertion {
        return;
    }

    sanitize_reserved_gateway_assertion_headers(headers);
    if let Some(username) = principal_username {
        headers.insert("x-consumer-username".to_string(), username);
        if let Some(custom_id) = principal_custom_id {
            headers.insert("x-consumer-custom-id".to_string(), custom_id);
        }
    }
    if let Some(country) = geo_country {
        headers.insert("x-geo-country".to_string(), country);
    }
}

fn refresh_effective_backend_gateway_assertion_headers(
    ctx: &mut RequestContext,
    owned_proxy_headers: &mut Option<HashMap<String, String>>,
) {
    if let Some(headers) = owned_proxy_headers.as_mut() {
        refresh_backend_gateway_assertion_headers(ctx, headers);
    } else {
        let mut headers = std::mem::take(&mut ctx.headers);
        refresh_backend_gateway_assertion_headers(ctx, &mut headers);
        ctx.headers = headers;
    }
}

#[derive(Clone, Copy)]
struct BackendPathLayout {
    is_root: bool,
    needs_leading_slash: bool,
    needs_between_slash: bool,
    len: usize,
}

fn backend_path_layout(backend_path: &str, remaining_path: &str) -> BackendPathLayout {
    let is_root = backend_path.is_empty() && remaining_path.is_empty();
    let combined_starts_with_slash = if !backend_path.is_empty() {
        backend_path.starts_with('/')
    } else {
        remaining_path.starts_with('/')
    };
    let needs_leading_slash = !is_root && !combined_starts_with_slash;
    let needs_between_slash = !backend_path.is_empty()
        && !remaining_path.is_empty()
        && !backend_path.ends_with('/')
        && !remaining_path.starts_with('/');
    let len = if is_root {
        1
    } else {
        (if needs_leading_slash { 1 } else { 0 })
            + backend_path.len()
            + (if needs_between_slash { 1 } else { 0 })
            + remaining_path.len()
    };

    BackendPathLayout {
        is_root,
        needs_leading_slash,
        needs_between_slash,
        len,
    }
}

fn push_backend_path(url: &mut String, backend_path: &str, remaining_path: &str) {
    let layout = backend_path_layout(backend_path, remaining_path);
    if layout.is_root {
        url.push('/');
        return;
    }
    if layout.needs_leading_slash {
        url.push('/');
    }
    url.push_str(backend_path);
    if layout.needs_between_slash {
        url.push('/');
    }
    url.push_str(remaining_path);
}

fn with_backend_path_parts<R>(
    proxy: &Proxy,
    incoming_path: &str,
    strip_len: usize,
    target_path: Option<&str>,
    use_parts: impl FnOnce(&str, &str) -> R,
) -> R {
    // `strip_len` is measured by the router after encoded-slash
    // normalization, so stripping must use the same coordinate system.
    let normalized_path = if proxy.strip_listen_path {
        Some(crate::router_cache::normalize_encoded_slashes(
            incoming_path,
        ))
    } else {
        None
    };
    let remaining_path = match &normalized_path {
        Some(normalized) => &normalized[strip_len.min(normalized.len())..],
        None => incoming_path,
    };
    let backend_path = target_path.or(proxy.backend_path.as_deref()).unwrap_or("");
    use_parts(backend_path, remaining_path)
}

/// Assemble the exact path that URL construction will forward to the selected
/// backend target. This intentionally shares path segmentation with
/// [`build_backend_url_with_target`] so post-routing policy cannot authorize a
/// path that differs from the one placed on the wire.
pub fn build_backend_effective_path(
    proxy: &Proxy,
    incoming_path: &str,
    strip_len: usize,
    target_path: Option<&str>,
) -> String {
    with_backend_path_parts(
        proxy,
        incoming_path,
        strip_len,
        target_path,
        |backend_path, remaining_path| {
            let layout = backend_path_layout(backend_path, remaining_path);
            let mut path = String::with_capacity(layout.len);
            push_backend_path(&mut path, backend_path, remaining_path);
            path
        },
    )
}

/// Once a route-sensitive plugin has authorized the first target's assembled
/// path, retries may rotate hosts and ports but must not select a different
/// assembled effective path without rerunning policy and charging another
/// method. Comparing the URL-builder output includes the proxy backend-path
/// fallback used when a target omits its own path. Keeping the authorized path
/// immutable avoids turning transport retry into a second routing decision.
#[doc(hidden)]
pub fn retry_target_preserves_backend_path(
    backend_path_is_policy_bound: bool,
    proxy: &Proxy,
    incoming_path: &str,
    strip_len: usize,
    previous: &UpstreamTarget,
    next: &UpstreamTarget,
) -> bool {
    if !backend_path_is_policy_bound {
        return true;
    }
    let previous_path = previous.path.as_deref().or(proxy.backend_path.as_deref());
    let next_path = next.path.as_deref().or(proxy.backend_path.as_deref());
    previous_path == next_path
        || build_backend_effective_path(proxy, incoming_path, strip_len, previous.path.as_deref())
            == build_backend_effective_path(proxy, incoming_path, strip_len, next.path.as_deref())
}

fn url_render_host(host: &str) -> std::borrow::Cow<'_, str> {
    if host.contains(':') && !host.starts_with('[') {
        std::borrow::Cow::Owned(format!("[{host}]"))
    } else {
        std::borrow::Cow::Borrowed(host)
    }
}

/// Rewrite the AUTHORITY HOST of a `{scheme}://{host}:{port}{path}` backend URL,
/// replacing the rendered `from_host` (in the authority position only) with the
/// rendered `to_host`. Used by the CROSS-CLUSTER HBONE dispatch to turn a URL
/// whose authority is a non-parseable SCOPED SYNTHETIC identity into a parseable
/// one whose authority is the real pod addr (only `path_and_query` is read from
/// the result; the host part is dropped). The replacement is scoped to the
/// authority (the segment after `://`, before the next `/`, `?`, or `#`) so a
/// host substring that also appears in the path is never touched. If the URL has
/// no `://` or the authority does not start with the rendered `from_host`, the
/// URL is returned unchanged (defensive; the caller still fails closed on a
/// subsequent parse error).
fn rewrite_backend_url_authority_host(url: &str, from_host: &str, to_host: &str) -> String {
    let Some(scheme_end) = url.find("://") else {
        return url.to_string();
    };
    let authority_start = scheme_end + 3;
    let rest = &url[authority_start..];
    // The authority runs to the first '/', '?' or '#'.
    let authority_end_rel = rest.find(['/', '?', '#']).unwrap_or(rest.len());
    let authority = &rest[..authority_end_rel];
    let suffix = &rest[authority_end_rel..];
    let rendered_from = url_render_host(from_host);
    // The authority is `{rendered_host}:{port}` (or bare `{rendered_host}`).
    if let Some(after_host) = authority.strip_prefix(rendered_from.as_ref()) {
        let rendered_to = url_render_host(to_host);
        format!(
            "{}{}{}{}",
            &url[..authority_start],
            rendered_to,
            after_host,
            suffix
        )
    } else {
        url.to_string()
    }
}

/// Host used for WebSocket transaction-log DNS resolution. Load-balanced
/// WebSocket sessions dial the selected target host, not the proxy's static
/// `backend_host`, so `backend_resolved_ip` must follow the same effective
/// destination as `backend_target`.
pub(crate) fn websocket_dns_resolution_host<'a>(
    proxy: &'a Proxy,
    target: Option<&'a UpstreamTarget>,
) -> &'a str {
    target
        .map(|target| target.host.as_str())
        .unwrap_or(proxy.backend_host.as_str())
}

/// Build a WebSocket backend URL using a specific target host/port,
/// respecting strip_listen_path, backend_path, and query string.
///
/// Uses a single pre-sized `String` buffer to avoid intermediate allocations
/// from multiple `format!()` calls (matches `build_backend_url_with_target`).
pub(crate) fn build_websocket_backend_url_with_target(
    proxy: &Proxy,
    incoming_path: &str,
    query_string: &str,
    host: &str,
    port: u16,
    strip_len: usize,
    target_path: Option<&str>,
) -> String {
    use std::fmt::Write;

    // WebSocket URL scheme: TLS intent comes from `backend_scheme`; the
    // `ws` vs `wss` prefix is purely a function of whether the backend
    // connection is encrypted.
    let scheme = match proxy.backend_scheme {
        Some(BackendScheme::Http) => "ws",
        _ => "wss",
    };

    // Host-only proxies (listen_path == None) have no prefix to strip.
    // Exact listen_paths carry a leading '=' marker for routing; strip only
    // the literal path part so WebSocket forwarding matches HTTP forwarding.
    //
    // `strip_len` is computed by the router against the encoded-slash
    // NORMALIZED path, so slice the normalized path (not the raw one) to keep
    // routing and forwarding in the same coordinate system; slicing the raw
    // path mis-aligns by 2 bytes per %2f and can panic mid-UTF-8 codepoint.
    // See `build_backend_url_with_target` for the full rationale. For paths
    // without encoded slashes this is an allocation-free borrowed no-op.
    let normalized_path = if proxy.strip_listen_path {
        Some(crate::router_cache::normalize_encoded_slashes(
            incoming_path,
        ))
    } else {
        None
    };
    let remaining_path = match &normalized_path {
        Some(normalized) => &normalized[strip_len.min(normalized.len())..],
        None => incoming_path,
    };

    let backend_path = target_path.or(proxy.backend_path.as_deref()).unwrap_or("");

    let path_layout = backend_path_layout(backend_path, remaining_path);
    let rendered_host = url_render_host(host);

    // Pre-calculate capacity and build in a single buffer.
    let capacity = scheme.len()
        + 3 // "://"
        + rendered_host.len()
        + 6 // ":PORT" (max 5 digits + colon)
        + path_layout.len
        + if query_string.is_empty() {
            0
        } else {
            1 + query_string.len()
        };

    let mut url = String::with_capacity(capacity);
    let _ = write!(url, "{}://{}:{}", scheme, rendered_host, port);
    push_backend_path(&mut url, backend_path, remaining_path);

    if !query_string.is_empty() {
        url.push('?');
        url.push_str(query_string);
    }

    url
}

/// Build a rustls TLS connector for WebSocket backends that respects
/// proxy-level and global TLS settings (CA bundles, client certs, cert verification).
/// When `tls_policy` is provided, outbound connections use the same cipher suites,
/// protocol versions, and key exchange groups as inbound listeners.
fn build_websocket_tls_connector(
    proxy: &Proxy,
    env_config: &crate::config::EnvConfig,
    tls_policy: Option<&TlsPolicy>,
    crls: &crate::tls::CrlList,
) -> Result<Option<tokio_tungstenite::Connector>, anyhow::Error> {
    // Only build a TLS connector when the backend scheme is TLS — a plaintext
    // `ws://` upgrade needs no TLS. WebSocket is a runtime flavor, so the
    // caller has already filtered to WebSocket requests; here we only decide
    // encrypted vs plaintext.
    if !matches!(proxy.backend_scheme, Some(BackendScheme::Https)) {
        return Ok(None);
    }

    let client_config = BackendTlsConfigBuilder {
        proxy,
        policy: tls_policy,
        global_ca: env_config.tls_ca_bundle_path.as_deref().map(Path::new),
        global_no_verify: env_config.tls_no_verify,
        global_client_cert: env_config
            .backend_tls_client_cert_path
            .as_deref()
            .map(Path::new),
        global_client_key: env_config
            .backend_tls_client_key_path
            .as_deref()
            .map(Path::new),
        crls,
    }
    .build_rustls()
    .map_err(|e| anyhow::anyhow!("Failed to build WebSocket backend TLS config: {}", e))?;

    Ok(Some(tokio_tungstenite::Connector::Rustls(Arc::new(
        client_config,
    ))))
}

/// Outcome of a successful backend WebSocket handshake. The stream carries
/// frames; `negotiated_subprotocol` preserves the backend's chosen value
/// (RFC 6455 §11.3.4, also applicable to RFC 8441 / RFC 9220 Extended CONNECT)
/// so the frontend can forward it to the client. Without forwarding, clients
/// that offered a subprotocol list see no negotiated value and fail
/// application-level handshakes.
///
/// `Sec-WebSocket-Extensions` is intentionally NOT forwarded: the bridge
/// doesn't speak `permessage-deflate` end-to-end, so signalling a negotiated
/// extension would lead the client to decode raw frames as compressed.
/// Backend WebSocket transport: TLS (or plain) over the byte-level idle
/// activity adapter over TCP. The `WsActivityIo` layer sits UNDER the
/// framer so fragmented-message read progress refreshes the shared idle
/// watermark (see `WsActivityIo`); with no tracker configured it is a pure
/// passthrough.
pub type BackendWsStream =
    WebSocketStream<tokio_tungstenite::MaybeTlsStream<WsActivityIo<tokio::net::TcpStream>>>;

pub(crate) struct BackendWsHandshake {
    pub stream: BackendWsStream,
    pub negotiated_subprotocol: Option<hyper::header::HeaderValue>,
}

/// Backend WebSocket transport for a mesh egress session: the raw WebSocket
/// frame stream carried over an HTTP/2 Extended CONNECT (RFC 8441) byte tunnel
/// (`H2ConnectTunnel`), wrapped in the byte-level idle adapter beneath the
/// framer exactly like the TCP/TLS backend path. The tunnel already rides
/// SVID-mTLS (Sidecar `:15006`) or HBONE (Ambient `:15008`); there is no second
/// TLS layer.
type MeshBackendWsStream = WebSocketStream<WsActivityIo<crate::proxy::hbone_pool::H2ConnectTunnel>>;

pub(crate) struct MeshBackendWsHandshake {
    pub stream: MeshBackendWsStream,
    pub negotiated_subprotocol: Option<hyper::header::HeaderValue>,
}

/// Unified backend WebSocket handshake: either a direct TCP/TLS upgrade (the
/// pre-mesh / non-mesh path) or a mesh egress Extended CONNECT tunnel (Sidecar
/// mesh-mTLS or Ambient HBONE). Both feed the SAME generic `run_websocket_proxy`
/// frame relay — only the backend transport type differs, so the session spawn
/// dispatches on the variant.
pub(crate) enum WsBackendHandshake {
    // Both variants are boxed: the direct TCP/TLS handshake is ~1.4 KB and the
    // mesh tunnel ~0.4 KB, so boxing keeps the enum (and every WS dispatch that
    // names it) pointer-sized.
    Direct(Box<BackendWsHandshake>),
    Mesh(Box<MeshBackendWsHandshake>),
}

impl WsBackendHandshake {
    fn negotiated_subprotocol(&self) -> Option<&hyper::header::HeaderValue> {
        match self {
            Self::Direct(handshake) => handshake.negotiated_subprotocol.as_ref(),
            Self::Mesh(handshake) => handshake.negotiated_subprotocol.as_ref(),
        }
    }
}

/// Connect to backend WebSocket server before sending 101 to client.
/// Returns the connected backend stream + negotiated handshake metadata,
/// or an error if the backend is unreachable.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn connect_websocket_backend(
    backend_url: &str,
    proxy: &Proxy,
    env_config: &crate::config::EnvConfig,
    client_headers: &[(String, String)],
    tls_policy: Option<&TlsPolicy>,
    crls: &crate::tls::CrlList,
    max_websocket_frame_size_bytes: usize,
    max_websocket_message_size_bytes: usize,
    websocket_write_buffer_size: usize,
    idle_tracker: Option<Arc<WsIdleTracker>>,
    // When `Some`, the backend host is resolved through the gateway DNS cache so
    // the egress policy is enforced on the *resolved* address (DNS-rebinding
    // safe) and that exact IP is dialed. `None` (test helpers only) keeps OS
    // resolution. Literal-IP backends are screened explicitly regardless.
    dns_cache: Option<&crate::dns::DnsCache>,
) -> Result<BackendWsHandshake, Box<dyn std::error::Error + Send + Sync>> {
    let mut ws_config = WebSocketConfig::default();
    ws_config.max_frame_size = Some(max_websocket_frame_size_bytes);
    ws_config.max_message_size = Some(max_websocket_message_size_bytes);
    ws_config.write_buffer_size = websocket_write_buffer_size;

    let mut ws_request = backend_url.into_client_request()?;
    for (name, value) in client_headers {
        if let (Ok(header_name), Ok(header_value)) = (
            hyper::header::HeaderName::from_bytes(name.as_bytes()),
            hyper::header::HeaderValue::from_str(value),
        ) {
            ws_request.headers_mut().append(header_name, header_value);
        }
    }

    // Enforce the backend egress policy for a literal-IP WebSocket backend
    // before dialing (the dial skips the DnsCacheResolver for IP literals).
    if let Ok(parsed) = url::Url::parse(backend_url) {
        let literal_ip = match parsed.host() {
            Some(url::Host::Ipv4(a)) => Some(std::net::IpAddr::V4(a)),
            Some(url::Host::Ipv6(a)) => Some(std::net::IpAddr::V6(a)),
            _ => None,
        };
        if let Some(ip) = literal_ip
            && let Some(reason) = env_config.backend_allow_ips.deny_reason(&ip)
        {
            return Err(format!(
                "backend egress policy denied literal-IP WebSocket backend {ip}: {reason}"
            )
            .into());
        }
    }

    let connector = build_websocket_tls_connector(proxy, env_config, tls_policy, crls)?;
    let connect_timeout = std::time::Duration::from_millis(proxy.backend_connect_timeout_ms);
    // Dial the TCP stream ourselves (instead of `connect_async_tls_with_config`)
    // so the byte-level `WsActivityIo` idle adapter can be installed UNDER the
    // TLS layer and WebSocket framer — read progress on a fragmented or large
    // backend message then refreshes the shared idle watermark even before
    // tungstenite yields a complete `Message`. Host/port resolution matches
    // what tungstenite's own dialer would use (request URI + scheme default).
    let uri = ws_request.uri();
    let dial_host = uri
        .host()
        .ok_or("WebSocket backend URL is missing a host")?
        // `TcpStream::connect` expects bare IPv6 addresses, not URI-bracketed.
        .trim_start_matches('[')
        .trim_end_matches(']')
        .to_string();
    let dial_port = uri.port_u16().unwrap_or_else(|| {
        if uri.scheme_str() == Some("wss") {
            443
        } else {
            80
        }
    });
    let connect_future = async {
        // Resolve through the gateway DNS cache when available so the egress
        // policy is enforced on the resolved address (a hostname that resolves —
        // or rebinds — to a denied IP such as 169.254.169.254 fails here) and we
        // dial that exact IP. The TLS connector still derives SNI from
        // `ws_request` (the hostname), so dialing the IP is transparent.
        let tcp = match dns_cache {
            Some(cache) => {
                let resolved_ip = cache
                    .resolve(
                        &dial_host,
                        proxy.dns_override.as_deref(),
                        proxy.dns_cache_ttl_seconds,
                    )
                    .await
                    .map_err(|e| -> Box<dyn std::error::Error + Send + Sync> {
                        format!("WebSocket backend resolution failed for {dial_host}: {e}").into()
                    })?;
                tokio::net::TcpStream::connect((resolved_ip, dial_port)).await?
            }
            None => tokio::net::TcpStream::connect((dial_host.as_str(), dial_port)).await?,
        };
        // Without nodelay, 70 KB WS messages hit Nagle + delayed-ACK
        // (~40 ms/msg); keepalive bounds dead-peer detection on idle
        // long-lived sessions.
        set_tcp_keepalive(&tcp);
        client_async_tls_with_config(
            ws_request,
            WsActivityIo::new(tcp, idle_tracker),
            Some(ws_config),
            connector,
        )
        .await
        .map_err(Box::<dyn std::error::Error + Send + Sync>::from)
    };

    let (backend_ws_stream, backend_response) =
        match tokio::time::timeout(connect_timeout, connect_future).await {
            Ok(result) => result?,
            Err(_) => {
                error!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    timeout_ms = proxy.backend_connect_timeout_ms,
                    error_kind = "connect_timeout",
                    "WebSocket backend connect timeout"
                );
                return Err(format!(
                    "WebSocket backend connect timeout ({}ms) for proxy {}",
                    proxy.backend_connect_timeout_ms, proxy.id
                )
                .into());
            }
        };

    debug!("Connected to backend WebSocket server: {}", backend_url);
    debug!("Backend response status: {}", backend_response.status());

    let negotiated_subprotocol = backend_response
        .headers()
        .get(hyper::header::SEC_WEBSOCKET_PROTOCOL)
        .cloned();

    Ok(BackendWsHandshake {
        stream: backend_ws_stream,
        negotiated_subprotocol,
    })
}

/// The mesh egress transport a WebSocket upgrade should ride, derived from the
/// LB-selected upstream target's tags. `None` means the target is not mesh-egress
/// tagged, so the ordinary direct TCP/TLS WebSocket path is used.
enum MeshWsEgress {
    /// Sidecar SVID-mTLS (`mesh.mtls`): dial the peer sidecar's inbound mTLS
    /// listener over a fresh mesh-mTLS H2 connection and RFC 8441 Extended
    /// CONNECT (Sidecar materializes inbound WS routes).
    SidecarMtls,
    /// Ambient HBONE (`mesh.hbone`): dial the peer's `:15008` HBONE listener
    /// over a fresh SVID-mTLS H2 connection and a BARE HBONE CONNECT byte tunnel
    /// to the workload's app addr:port, then an inner H1 WebSocket handshake
    /// THROUGH the tunnel — Ambient/Waypoint materialize NO inbound routes, so
    /// the transparent HBONE relay (bare-CONNECT-gated) byte-copies the upgrade
    /// to the loopback app (an Extended CONNECT to `:15008` would 404).
    AmbientHbone,
}

/// Decide whether a WebSocket upgrade to `target` must ride a mesh egress
/// transport, keyed purely on the target's transport tag. Returns `None` only
/// for non-mesh targets (the direct TCP/TLS path applies). A mesh-tagged target
/// is ALWAYS reported as mesh egress — even when the gateway SVID is missing —
/// so the upgrade fails closed in `connect_mesh_websocket_backend` (where the
/// pool errors `NoSvid` before any dial) rather than silently falling back to a
/// plaintext dial of a `mesh.mtls`/`mesh.hbone` destination. This is the
/// WebSocket analogue of the `supports_mesh_mtls_backend` / `can_attempt_hbone_backend`
/// fail-closed contract, but the SVID/capability check is deferred to the dial
/// because returning `None` here would route to the plaintext path.
fn websocket_mesh_egress(target: &UpstreamTarget) -> Option<MeshWsEgress> {
    // HBONE is checked FIRST so a corrupted target carrying BOTH transport tags
    // (`mesh.hbone` + `mesh.mtls`) resolves to the Ambient branch, mirroring the
    // gRPC classifier's HBONE-wins precedence (`classify_grpc_mesh_dispatch`).
    // Without this, `mesh_mtls` won and a mixed-tag CROSS-CLUSTER target would be
    // dispatched over mesh-mTLS — bypassing the fail-closed cross-cluster HBONE
    // WebSocket refusal; the Ambient branch instead fails such a target closed
    // (issue #2010 codex). Legitimate targets carry exactly one transport tag, so
    // this only re-routes corrupted shapes.
    if hbone_pool::target_hbone_enabled(target) {
        Some(MeshWsEgress::AmbientHbone)
    } else if mesh_mtls_pool::target_mesh_mtls_enabled(target) {
        Some(MeshWsEgress::SidecarMtls)
    } else {
        None
    }
}

/// Open a backend WebSocket transport over a mesh egress tunnel for a
/// `mesh.mtls`-tagged (Sidecar) or `mesh.hbone`-tagged (Ambient) destination.
/// The returned stream carries raw WebSocket frames over the SVID-mTLS / HBONE
/// byte tunnel; the destination bridges/relays it to the local app's WebSocket
/// (transport-agnostic on the destination side — no peer change needed).
///
/// **The two topologies ride DIFFERENT inbound primitives** (this is the trap
/// the original implementation fell into):
///
///   * **Sidecar (`mesh.mtls`)** — an **RFC 8441 Extended CONNECT**
///     (`:protocol=websocket`) on the peer's `:15006` mTLS listener. Sidecar
///     materializes inbound WebSocket routes, so its `:15006` listener
///     (`enable_connect_protocol`) recognizes the Extended CONNECT as a
///     client-originated upgrade and bridges it to the local app. The Extended
///     CONNECT 200 IS the WS upgrade, so the tunnel is the raw frame transport
///     directly (no inner H1 handshake).
///   * **Ambient/Waypoint (`mesh.hbone`)** — a **BARE HBONE CONNECT byte tunnel**
///     to the destination workload's app addr:port, then an INNER HTTP/1.1
///     WebSocket handshake spoken THROUGH the tunnel. Ambient/Waypoint
///     materialize NO inbound routes; the route-miss transparent-relay fallback
///     (`build_inbound_hbone_relay_proxy`) is gated on a BARE CONNECT
///     (`is_connect_request` requires `:protocol` ABSENT), so a `:protocol=
///     websocket` Extended CONNECT to `:15008` would 404 before any WS handler
///     runs. Instead we open the same byte tunnel raw-TCP egress uses and run a
///     client WebSocket handshake over it; the destination's transparent HBONE
///     relay byte-copies the upgrade to the loopback app, which performs the WS
///     handshake. This makes Ambient WS egress actually work end-to-end.
///
/// For Sidecar the connection is dialed to the peer's pod address + `:15006`,
/// while the Extended CONNECT `:authority` is the SERVICE routing key the peer's
/// inbound route matches on — computed exactly like `proxy_to_backend_mesh_mtls`'s
/// inner `:authority`: the preserved client `Host` (the egress route sets
/// `preserve_host_header`), rewritten to `<host>:<service_port>` for a
/// multi-port Sidecar destination (`mesh.mtls_authority_port`), or the dial
/// authority (`<target.host>:<target.port>`) when no client Host is available.
/// For Ambient the bare CONNECT `:authority` IS the dial app addr:port
/// (`<target.host>:<target.port>`) the relay byte-copies to, and the SERVICE
/// `:authority` rides the inner H1 `Host` header instead. `path_and_query` (the
/// client's `:path`) is preserved on both transports.
///
/// Identity is PINNED via `mesh.spiffe_id` (mandatory for `mesh.mtls`; carried
/// when present for `mesh.hbone`). Fails closed: a missing gateway SVID, an
/// absent/invalid pinned identity, a peer that never negotiated Extended CONNECT
/// (Sidecar), or a relay/handshake failure (Ambient) errors instead of falling
/// back to a plaintext dial.
#[allow(clippy::too_many_arguments)]
async fn connect_mesh_websocket_backend(
    state: &ProxyState,
    proxy: &Proxy,
    target: &UpstreamTarget,
    egress: &MeshWsEgress,
    client_host: Option<&str>,
    path_and_query: &str,
    client_headers: &[(String, String)],
    max_websocket_frame_size_bytes: usize,
    max_websocket_message_size_bytes: usize,
    websocket_write_buffer_size: usize,
    idle_tracker: Option<Arc<WsIdleTracker>>,
    // The ASSERTED source identity to stamp into the Ambient HBONE baggage — the
    // request's `ctx.peer_spiffe_id` (the original authenticated mesh workload) so
    // the destination's AuthorizationPolicy / telemetry see the source workload,
    // not the gateway SVID. Consumed ONLY by the `AmbientHbone` branch (the
    // Sidecar mesh-mTLS WS transport carries no source-identity baggage — the mTLS
    // client cert authenticates the gateway; see `MeshMtlsConnectionPool`). `None`
    // falls back to the gateway SVID, mirroring the HTTP HBONE path.
    source_identity: Option<&crate::identity::SpiffeId>,
) -> Result<MeshBackendWsHandshake, Box<dyn std::error::Error + Send + Sync>> {
    let mut ws_config = WebSocketConfig::default();
    ws_config.max_frame_size = Some(max_websocket_frame_size_bytes);
    ws_config.max_message_size = Some(max_websocket_message_size_bytes);
    ws_config.write_buffer_size = websocket_write_buffer_size;

    match egress {
        MeshWsEgress::SidecarMtls => {
            // Compute the Extended CONNECT `:authority` the destination routes
            // on, mirroring `proxy_to_backend_mesh_mtls`'s inner `:authority`
            // BYTE-FOR-BYTE so the WS path and HTTP path are interchangeable on
            // the peer:
            //   * a `mesh.mtls_authority_host` tag (sidecar-topology mesh SD /
            //     gateway-to-mesh bridge) wins outright → `<service_host>` or
            //     `<service_host>:<service_port>` — the gateway's client Host
            //     is not a mesh service host the peer routes;
            //   * preserve-host + multi-port Sidecar → `<client_host>:<service_port>`
            //     (`mesh_mtls_request_authority`, the rewrite tag the peer's
            //     per-port inbound siblings disambiguate by — `:15006` dials are
            //     direct/never NATed);
            //   * preserve-host + single-port → the client Host VERBATIM (incl.
            //     any explicit port, and NO port when the client sent none —
            //     matching the HTTP single-port path exactly);
            //   * otherwise → the dial authority (`<target.host>:<target.port>`).
            // When the service-authority tag REPLACES the client Host outright,
            // the original Host would otherwise be lost on the WS path
            // (`collect_forwardable_websocket_headers` strips `Host`, unlike
            // the HTTP path which stamps `x-forwarded-host` unconditionally) —
            // so forward it as `x-forwarded-host` alongside the other client
            // headers, matching the HTTP dispatch's `client_host_forwarded`
            // behavior. The other authority branches keep the client Host as
            // (part of) the `:authority`, so nothing is lost there.
            let mut forwarded_headers_owned: Option<Vec<(String, String)>> = None;
            let authority = if let Some(service_host) =
                mesh_mtls_pool::target_mesh_mtls_authority_host(target)
            {
                if let Some(host) = client_host.filter(|host| !host.is_empty()) {
                    let mut augmented = client_headers.to_vec();
                    augmented.retain(|(name, _)| !name.eq_ignore_ascii_case("x-forwarded-host"));
                    augmented.push(("x-forwarded-host".to_string(), host.to_string()));
                    forwarded_headers_owned = Some(augmented);
                }
                match mesh_mtls_pool::target_mesh_mtls_authority_port(target) {
                    Some(service_port) => format!("{service_host}:{service_port}"),
                    None => service_host.to_string(),
                }
            } else {
                match client_host {
                    Some(host) if proxy.preserve_host_header && !host.is_empty() => {
                        match mesh_mtls_pool::target_mesh_mtls_authority_port(target) {
                            Some(service_port) => mesh_mtls_request_authority(host, service_port),
                            None => host.to_string(),
                        }
                    }
                    _ => hbone_pool::authority_for_host_port(&target.host, target.port),
                }
            };
            let forwarded_headers: &[(String, String)] =
                forwarded_headers_owned.as_deref().unwrap_or(client_headers);
            // Resolve the mesh-mTLS dial plan (issue #2010), shared with the
            // HTTP/gRPC path (`proxy_to_backend_mesh_mtls`):
            //   * IN-CLUSTER: pin the destination workload SPIFFE, SNI = dial
            //     host, no trust-domain scope.
            //   * CROSS-CLUSTER east-west: NO pinned pod SPIFFE
            //     (`expected_peer = None`), verification scoped to the remote
            //     `mesh.trust_domain`, and the ClientHello SNI OVERRIDDEN to the
            //     destination service FQDN (`mesh.eastwest_sni`) so the remote
            //     gateway's SNI passthrough routes to the destination sidecar's
            //     `:15006` Extended-CONNECT listener.
            // A missing pinned identity (in-cluster) or a malformed cross-cluster
            // target (missing SNI / trust domain) FAILS THE UPGRADE CLOSED here —
            // never a plaintext / wrong-SNI dial of a mesh destination.
            let dial_plan = match mesh_mtls_pool::MeshMtlsDialPlan::resolve(target) {
                Ok(plan) => plan,
                Err(err) => {
                    warn!(
                        proxy_id = %proxy.id,
                        target_host = %target.host,
                        error = %err,
                        "Refusing sidecar mesh-mTLS WebSocket egress: unresolved dial plan; \
                         failing the upgrade closed (no plaintext / wrong-SNI fallback)"
                    );
                    return Err(Box::new(err));
                }
            };
            let mtls_port = mesh_mtls_pool::target_mesh_mtls_port(target);
            let ws_tunnel = state
                .mesh_mtls_pool
                .open_ws_connect_tunnel(
                    proxy,
                    &target.host,
                    target.port,
                    target.dispatch_policy_port(),
                    mtls_port,
                    &authority,
                    path_and_query,
                    dial_plan.expected_peer.as_ref(),
                    dial_plan.expected_trust_domain.as_ref(),
                    dial_plan.sni_override,
                    forwarded_headers,
                )
                .await?;

            // The Extended CONNECT response (200) already confirmed the upgrade,
            // so the tunnel IS the raw WebSocket frame transport — wrap it as a
            // CLIENT-role framer directly (no inner H1 handshake). The byte-level
            // idle adapter sits under the framer, matching the TCP/TLS path.
            let stream = WebSocketStream::from_raw_socket(
                WsActivityIo::new(ws_tunnel.tunnel, idle_tracker),
                tokio_tungstenite::tungstenite::protocol::Role::Client,
                Some(ws_config),
            )
            .await;

            Ok(MeshBackendWsHandshake {
                stream,
                negotiated_subprotocol: ws_tunnel.negotiated_subprotocol,
            })
        }
        MeshWsEgress::AmbientHbone => {
            // Resolve the HBONE byte-tunnel dial (issue #2010), mirroring
            // `proxy_to_backend_hbone`'s cross-cluster branch so the WS and HTTP
            // HBONE paths cannot drift:
            //   * IN-CLUSTER: pin the destination pod SPIFFE, dial the pod addr,
            //     no SNI/trust-domain override; the inner CONNECT `:authority` is
            //     the pod addr:port.
            //   * CROSS-CLUSTER east-west (`mesh.cross_cluster`): dial the REMOTE
            //     gateway (`mesh.hbone_dial_host`) with the ClientHello SNI
            //     OVERRIDDEN to the destination service FQDN (`mesh.eastwest_sni`)
            //     and TRUST-DOMAIN-ONLY verification (`mesh.trust_domain`, no
            //     pinned pod SPIFFE); the inner CONNECT `:authority` is the REAL
            //     pod addr (`mesh.hbone_authority_host`, since `target.host` is a
            //     scoped synthetic identity) the dest relay byte-copies to.
            // A malformed cross-cluster target (missing SNI / trust domain) FAILS
            // THE UPGRADE CLOSED here — never a plaintext / wrong-SNI dial.
            let hbone_port = hbone_pool::target_hbone_port(target);
            let dial_host = hbone_pool::target_hbone_dial_host(target)?;
            // The inner CONNECT `:authority` host: the `mesh.hbone_authority_host`
            // tag for a cross-cluster target, else `target.host` in-cluster (the
            // tag is absent → returns `target.host`, byte-identical to before).
            let app_host = hbone_pool::target_hbone_authority_host(target)?;
            // FAIL CLOSED PRE-WIRE for a corrupted cross-cluster target that omits
            // `mesh.hbone_authority_host`: `target_hbone_authority_host` would then
            // fall back to `target.host` = the SCOPED SYNTHETIC `mesh-xc-hbone|...`
            // key (not a dialable authority). Without this guard the branch would
            // establish the east-west TLS/H2 connection first and only fail LATER
            // while building the HBONE CONNECT to the synthetic authority — a
            // dial-then-fail that violates the fail-closed invariant. Require the
            // real authority host BEFORE any dial (issue #2010 codex), typed so
            // `classify_boxed_setup_error` recognizes it as PRE-WIRE
            // (`ConnectionPoolError`) — mirrors the missing-SNI / missing-trust-
            // domain rejects below. A present-but-empty tag already fails closed as
            // `InvalidAuthorityHostTag` inside `target_hbone_authority_host`.
            if hbone_pool::target_hbone_cross_cluster(target)
                && !target
                    .tags
                    .contains_key(hbone_pool::HBONE_AUTHORITY_HOST_TAG)
            {
                warn!(
                    proxy_id = %proxy.id,
                    target_host = %target.host,
                    "Refusing cross-cluster Ambient WebSocket egress: missing \
                     mesh.hbone_authority_host (fail closed, never dial to the \
                     synthetic identity as CONNECT authority)"
                );
                return Err(Box::new(
                    hbone_pool::HbonePoolError::MissingCrossClusterAuthorityHost,
                ));
            }
            // The two cross-cluster fail-closed branches return a TYPED
            // `HbonePoolError` (not a boxed string) so `classify_boxed_setup_error`
            // → `classify_typed_chain` downcasts it to a PRE-WIRE class
            // (`ConnectionPoolError`) via `error_class()`. That keeps a metadata
            // reject retry-eligible under `retry_on_connect_failure` and recorded
            // as a mesh SETUP failure — not charged to the backend / circuit
            // breaker as a post-wire request failure (issue #2010 codex). Mirrors
            // the Sidecar `MeshMtlsDialError::MissingCrossCluster*` pattern.
            let (expected_peer, expected_trust_domain, sni_override) =
                if hbone_pool::target_hbone_cross_cluster(target) {
                    let sni = hbone_pool::target_hbone_eastwest_sni(target).ok_or_else(|| {
                        warn!(
                            proxy_id = %proxy.id,
                            target_host = %target.host,
                            "Refusing cross-cluster Ambient WebSocket egress: missing/empty \
                             mesh.eastwest_sni (fail closed, never dial the gateway IP as SNI)"
                        );
                        hbone_pool::HbonePoolError::MissingCrossClusterSni
                    })?;
                    let td = hbone_pool::target_hbone_cross_cluster_trust_domain(target)
                        .ok_or_else(|| {
                            warn!(
                                proxy_id = %proxy.id,
                                target_host = %target.host,
                                "Refusing cross-cluster Ambient WebSocket egress: missing/empty/\
                                 unparseable mesh.trust_domain (fail closed, never any-federated)"
                            );
                            hbone_pool::HbonePoolError::MissingCrossClusterTrustDomain
                        })?;
                    (None, Some(td), Some(sni))
                } else {
                    (hbone_pool::target_expected_peer_spiffe(target)?, None, None)
                };
            // Bare HBONE byte tunnel to the CONNECT `:authority` (the pod app
            // addr:port the relay byte-copies to) — NOT an Extended CONNECT (see
            // `get_ws_byte_tunnel`). For cross-cluster the outer TLS dials the
            // gateway with the SNI override + trust-domain scope resolved above.
            let tunnel = state
                .hbone_pool
                .get_ws_byte_tunnel(
                    proxy,
                    dial_host,
                    hbone_port,
                    app_host,
                    target.port,
                    target.dispatch_policy_port(),
                    expected_peer.as_ref(),
                    expected_trust_domain.as_ref(),
                    sni_override,
                    // Preserve the ASSERTED source identity: a WS request from an
                    // authenticated mesh peer stamps the ORIGINAL workload SPIFFE
                    // into the HBONE baggage (mirroring `proxy_to_backend_hbone`'s
                    // `source_identity_ctx.and_then(|ctx| ctx.peer_spiffe_id...)`),
                    // so the destination's AuthorizationPolicy / telemetry see the
                    // source workload, not the gateway's own SVID. `None` (ambient
                    // egress from an unauthenticated client) falls back to the
                    // gateway SVID inside `get_ws_byte_tunnel` (issue #2010 codex).
                    source_identity,
                )
                .await?;

            // Speak the WebSocket THROUGH the byte tunnel with an inner H1
            // client handshake (`Sec-WebSocket-Key`/`Upgrade`/`Connection`,
            // which tungstenite generates). The SERVICE `:authority` the
            // destination's app routes on rides the inner `Host` header
            // (mirroring `proxy_to_backend_hbone`, which forwards the client
            // Host over the relay); `path_and_query` is the preserved client
            // `:path`. The relay forwards these plaintext bytes to the loopback
            // app, which completes the upgrade.
            //
            // The non-preserved Host fallback uses `app_host` (the real pod
            // addr from `mesh.hbone_authority_host`), NOT `target.host`: for a
            // cross-cluster target `target.host` is the scoped synthetic
            // `mesh-xc-hbone|...` identity, so `ws://{target.host}...` is an
            // invalid WS URI that `into_client_request()` would REJECT after the
            // tunnel is already established. In-cluster `app_host == target.host`
            // (the tag is absent), so this stays byte-identical there. Mirrors
            // `proxy_to_backend_hbone`, whose backend Host header is
            // `authority_for_host_port(app_host, target.port)` when the client
            // Host is not preserved (issue #2010 codex).
            let inner_host = hbone_pool::hbone_ws_inner_host(
                client_host,
                proxy.preserve_host_header,
                app_host,
                target.port,
            );
            let ws_url = format!("ws://{inner_host}{path_and_query}");
            let mut ws_request = ws_url.into_client_request()?;
            // Force the routing Host the destination app matches on (the URL
            // host already sets it, but be explicit for bracketed-IPv6 / port
            // forms and to mirror the HTTP relay's preserved Host).
            ws_request.headers_mut().insert(
                hyper::header::HOST,
                hyper::header::HeaderValue::from_str(&inner_host)?,
            );
            for (name, value) in client_headers {
                if let (Ok(header_name), Ok(header_value)) = (
                    hyper::header::HeaderName::from_bytes(name.as_bytes()),
                    hyper::header::HeaderValue::from_str(value),
                ) {
                    ws_request.headers_mut().append(header_name, header_value);
                }
            }

            // Bound the inner handshake by the per-proxy connect budget: a relay
            // that wires the tunnel but whose app never answers the upgrade must
            // not stall the WS dispatch indefinitely. A timeout is a pre-wire
            // setup failure (the upgrade never completed), surfaced as a
            // `HbonePoolError::ConnectStream` so the WS failure handler keeps
            // connect-failure semantics via `classify_boxed_setup_error`'s
            // `HbonePoolError` downcast.
            let connect_timeout =
                std::time::Duration::from_millis(proxy.backend_connect_timeout_ms);
            // Use `app_host` (real pod addr) for the error surface too — for a
            // cross-cluster target `target.host` is the synthetic identity, not
            // a dialable authority; in-cluster this is byte-identical.
            let handshake_authority = hbone_pool::authority_for_host_port(app_host, target.port);
            let (stream, response) = match tokio::time::timeout(
                connect_timeout,
                client_async_with_config(
                    ws_request,
                    WsActivityIo::new(tunnel, idle_tracker),
                    Some(ws_config),
                ),
            )
            .await
            {
                Ok(result) => result?,
                Err(_) => {
                    return Err(Box::new(hbone_pool::HbonePoolError::ConnectStream {
                        authority: handshake_authority,
                        message: format!(
                            "timed out after {}ms waiting for HBONE WebSocket inner handshake \
                             response",
                            proxy.backend_connect_timeout_ms
                        ),
                    }));
                }
            };

            let negotiated_subprotocol = response
                .headers()
                .get(hyper::header::SEC_WEBSOCKET_PROTOCOL)
                .cloned();

            Ok(MeshBackendWsHandshake {
                stream,
                negotiated_subprotocol,
            })
        }
    }
}

/// Run bidirectional WebSocket proxying between upgraded client and connected backend.
///
/// Session-level metadata captured at WebSocket upgrade time and consumed at
/// teardown when firing `on_ws_disconnect`. Held as an owned struct (not
/// references) because the upgrade handler returns before the session ends,
/// so all fields must outlive the originating request context.
#[doc(hidden)]
pub struct WsSessionMeta {
    pub namespace: String,
    pub proxy_name: Option<String>,
    pub client_ip: String,
    pub backend_target: String,
    pub listen_port: u16,
    /// Process-local accepted session ID allocated at upgrade admission and
    /// preserved through every teardown path that builds `WsDisconnectContext`.
    /// Same value as the `connection_id` argument to `on_ws_frame` / the relay.
    pub connection_id: u64,
    pub consumer_username: Option<String>,
    pub auth_method: Option<&'static str>,
    pub metadata: HashMap<String, String>,
    /// Ownership generation captured at WebSocket upgrade admission.
    pub proxy_lifecycle_generation: Option<u64>,
    /// Civil/UTC connect time for human-readable `timestamp_connected` only.
    pub session_start: chrono::DateTime<chrono::Utc>,
    /// Process-monotonic connect instant used for `duration_ms`. Wall-clock
    /// corrections must not freeze, clamp, or inflate WebSocket session duration.
    pub session_start_mono: Instant,
}

/// Fire `on_ws_disconnect` for the tunnel-mode path, where raw
/// `copy_bidirectional` is used instead of frame-level parsing.
///
/// Tunnel mode does not track frame counts (all bytes flow as raw TCP), so
/// `frames_client_to_backend` / `frames_backend_to_client` are reported as
/// `0`. Callers pass raw byte counts from the relay. Direction attribution is
/// best-effort: residual-byte write errors to the client are attributed to
/// `BackendToClient`, and the raw relay supplies the first failure's
/// direction/side when available. Observers that require frame-count fidelity
/// should disable tunnel mode for the proxy.
///
/// The helper takes `ws_disconnect_plugins` by slice and `session_meta` by
/// reference so the caller keeps ownership for the duration of the call.
#[doc(hidden)]
pub async fn fire_ws_tunnel_disconnect_hooks(
    ws_disconnect_plugins: &[Arc<dyn Plugin>],
    proxy_id: &str,
    session_meta: &WsSessionMeta,
    bytes_client_to_backend: u64,
    bytes_backend_to_client: u64,
    failure: Option<(
        crate::plugins::Direction,
        retry::ErrorClass,
        Option<tcp_proxy::StreamIoSide>,
    )>,
) {
    if ws_disconnect_plugins.is_empty() {
        return;
    }
    let disconnect_duration_ms = session_meta.session_start_mono.elapsed().as_millis() as f64;
    let disconnected_at = chrono::Utc::now();
    let disconnect_ctx = crate::plugins::WsDisconnectContext {
        namespace: session_meta.namespace.clone(),
        proxy_id: proxy_id.to_string(),
        proxy_lifecycle_generation: session_meta.proxy_lifecycle_generation,
        proxy_name: session_meta.proxy_name.clone(),
        client_ip: session_meta.client_ip.clone(),
        backend_target: session_meta.backend_target.clone(),
        listen_port: session_meta.listen_port,
        connection_id: session_meta.connection_id,
        duration_ms: disconnect_duration_ms,
        frames_client_to_backend: 0,
        frames_backend_to_client: 0,
        bytes_client_to_backend,
        bytes_backend_to_client,
        timestamp_connected: session_meta.session_start.to_rfc3339(),
        timestamp_disconnected: disconnected_at.to_rfc3339(),
        direction: failure.as_ref().map(|(d, _, _)| *d),
        io_side: failure.as_ref().and_then(|(_, _, side)| *side),
        error_class: failure.map(|(_, c, _)| c),
        consumer_username: session_meta.consumer_username.clone(),
        auth_method: session_meta.auth_method,
        metadata: session_meta.metadata.clone(),
    };
    for plugin in ws_disconnect_plugins {
        plugin.on_ws_disconnect(&disconnect_ctx).await;
    }
}

/// Fire `on_ws_disconnect` for the framed (parsed) WebSocket path.
///
/// Unlike tunnel mode, framed mode reports real frame counters. Duration still
/// comes from `session_start_mono` (`Instant`); wall `session_start` is only
/// used for `timestamp_connected` rendering. Takes `session_meta` by value
/// because the framed relay consumes it at teardown.
#[doc(hidden)]
#[allow(clippy::too_many_arguments)]
pub async fn fire_ws_framed_disconnect_hooks(
    ws_disconnect_plugins: &[Arc<dyn Plugin>],
    proxy_id: &str,
    session_meta: WsSessionMeta,
    frames_client_to_backend: u64,
    frames_backend_to_client: u64,
    bytes_client_to_backend: u64,
    bytes_backend_to_client: u64,
    failure: Option<(
        crate::plugins::Direction,
        retry::ErrorClass,
        Option<tcp_proxy::StreamIoSide>,
    )>,
) {
    if ws_disconnect_plugins.is_empty() {
        return;
    }
    let disconnect_duration_ms = session_meta.session_start_mono.elapsed().as_millis() as f64;
    let disconnected_at = chrono::Utc::now();
    let disconnect_ctx = crate::plugins::WsDisconnectContext {
        namespace: session_meta.namespace,
        proxy_id: proxy_id.to_string(),
        proxy_lifecycle_generation: session_meta.proxy_lifecycle_generation,
        proxy_name: session_meta.proxy_name,
        client_ip: session_meta.client_ip,
        backend_target: session_meta.backend_target,
        listen_port: session_meta.listen_port,
        connection_id: session_meta.connection_id,
        duration_ms: disconnect_duration_ms,
        frames_client_to_backend,
        frames_backend_to_client,
        bytes_client_to_backend,
        bytes_backend_to_client,
        timestamp_connected: session_meta.session_start.to_rfc3339(),
        timestamp_disconnected: disconnected_at.to_rfc3339(),
        direction: failure.as_ref().map(|(d, _, _)| *d),
        io_side: failure.as_ref().and_then(|(_, _, side)| *side),
        error_class: failure.map(|(_, c, _)| c),
        consumer_username: session_meta.consumer_username,
        auth_method: session_meta.auth_method,
        metadata: session_meta.metadata,
    };
    for plugin in ws_disconnect_plugins {
        plugin.on_ws_disconnect(&disconnect_ctx).await;
    }
}

/// `connection_id` — unique per-connection identifier for stateful frame plugins.
/// `ws_framing_plugins` — plugins that require parsing for a parser-level
/// policy or post-reassembly hook. Pass an empty `Vec` for zero-overhead
/// forwarding when no plugin on this proxy needs WebSocket framing.
/// `ws_frame_plugins` — the subset that opted into post-reassembly hooks.
/// Parser-policy-only plugins must not enter the per-message loop.
/// `ws_disconnect_plugins` — plugins that opted into end-of-session hooks by
/// returning `true` from `requires_ws_disconnect_hooks()`. Pass an empty `Vec`
/// to skip disconnect bookkeeping entirely.
/// `session_meta` — captured at upgrade time; used to populate `WsDisconnectContext`
/// when the session ends. Cost is paid regardless of whether disconnect plugins
/// are present (one small allocation per upgrade) because the struct is small
/// and moving it has zero additional cost.
/// `websocket_tunnel_mode` — when true and no frame plugins are configured, bypass
/// WebSocket frame parsing and use raw TCP bidirectional copy for maximum throughput.
///
/// Polite-close bound used when the cancel branch of each forward loop fires.
/// The opposite direction has already cancelled, so a plain `.await` on the
/// polite-Close send could hang indefinitely if the peer socket is dead or
/// backpressured. A Close control frame is small and completes in microseconds
/// on a healthy TCP connection, so 100ms is generous for the happy path while
/// still bounding teardown for pathological peers.
const WS_CANCEL_CLOSE_TIMEOUT_MS: u64 = 100;

#[derive(Clone)]
struct WsSizeLimitRule {
    max_bytes: usize,
    close_reason: Arc<str>,
}

pub(crate) type WebSocketRelayPluginLists = (Vec<Arc<dyn Plugin>>, Vec<Arc<dyn Plugin>>);

pub(crate) struct EffectiveWsSizeLimits {
    pub(crate) max_frame_bytes: usize,
    pub(crate) max_message_bytes: usize,
    plugin_frame: Option<WsSizeLimitRule>,
    plugin_message: Option<WsSizeLimitRule>,
}

pub(crate) fn collect_websocket_relay_plugins(
    plugins: &[Arc<dyn Plugin>],
    requires_websocket_framing: bool,
) -> WebSocketRelayPluginLists {
    if !requires_websocket_framing {
        return (Vec::new(), Vec::new());
    }
    let framing_plugins: Vec<_> = plugins
        .iter()
        .filter(|plugin| plugin.requires_websocket_framing())
        .cloned()
        .collect();
    let frame_plugins = framing_plugins
        .iter()
        .filter(|plugin| plugin.requires_ws_frame_hooks())
        .cloned()
        .collect();
    (framing_plugins, frame_plugins)
}

impl EffectiveWsSizeLimits {
    pub(crate) fn from_plugins(global_frame_bytes: usize, plugins: &[Arc<dyn Plugin>]) -> Self {
        let mut plugin_frame: Option<WsSizeLimitRule> = None;
        let mut plugin_message: Option<WsSizeLimitRule> = None;

        for plugin in plugins {
            let Some(WebSocketSizeLimits {
                max_frame_bytes,
                max_message_bytes,
                close_reason,
            }) = plugin.websocket_size_limits()
            else {
                continue;
            };

            if plugin_frame
                .as_ref()
                .is_none_or(|current| max_frame_bytes < current.max_bytes)
            {
                plugin_frame = Some(WsSizeLimitRule {
                    max_bytes: max_frame_bytes,
                    close_reason: Arc::clone(&close_reason),
                });
            }
            if plugin_message
                .as_ref()
                .is_none_or(|current| max_message_bytes < current.max_bytes)
            {
                plugin_message = Some(WsSizeLimitRule {
                    max_bytes: max_message_bytes,
                    close_reason,
                });
            }
        }

        let global_message_bytes = global_frame_bytes.saturating_mul(4);
        let max_frame_bytes = plugin_frame
            .as_ref()
            .map(|rule| global_frame_bytes.min(rule.max_bytes))
            .unwrap_or(global_frame_bytes);
        let max_message_bytes = plugin_message
            .as_ref()
            .map(|rule| global_message_bytes.min(rule.max_bytes))
            .unwrap_or(global_message_bytes);
        Self {
            max_frame_bytes,
            max_message_bytes,
            // Keep only rules that actually determine an effective parser
            // ceiling. This prevents an inactive plugin frame rule from being
            // mistaken for a numerically equal global message rejection.
            plugin_frame: plugin_frame.filter(|rule| rule.max_bytes == max_frame_bytes),
            plugin_message: plugin_message.filter(|rule| rule.max_bytes == max_message_bytes),
        }
    }

    fn plugin_close_for_error(
        &self,
        error: &tokio_tungstenite::tungstenite::Error,
    ) -> Option<(CloseFrame, &'static str, usize, usize)> {
        use tokio_tungstenite::tungstenite::Error;
        use tokio_tungstenite::tungstenite::error::CapacityError;

        let (size, max_size, rule, kind) = match error {
            Error::Capacity(CapacityError::FrameTooLong { size, max_size }) => {
                let rule = self.plugin_frame.as_ref().filter(|rule| {
                    self.max_frame_bytes == *max_size && rule.max_bytes == *max_size
                })?;
                (*size, *max_size, rule, "frame")
            }
            Error::Capacity(CapacityError::MessageTooLong { size, max_size }) => {
                let rule = self.plugin_message.as_ref().filter(|rule| {
                    self.max_message_bytes == *max_size && rule.max_bytes == *max_size
                })?;
                (*size, *max_size, rule, "message")
            }
            _ => return None,
        };
        Some((
            CloseFrame {
                code: CloseCode::Size,
                reason: rule.close_reason.as_ref().to_owned().into(),
            },
            kind,
            size,
            max_size,
        ))
    }

    /// Global frame/message capacity overflow Close when no plugin rule supplied
    /// the binding ceiling. Bounded, non-secret empty reason (RFC 6455 1009).
    pub(crate) fn global_capacity_close_for_error(
        error: &tokio_tungstenite::tungstenite::Error,
    ) -> Option<(CloseFrame, &'static str, usize, usize)> {
        use tokio_tungstenite::tungstenite::Error;
        use tokio_tungstenite::tungstenite::error::CapacityError;

        let (size, max_size, kind) = match error {
            Error::Capacity(CapacityError::FrameTooLong { size, max_size }) => {
                (*size, *max_size, "frame")
            }
            Error::Capacity(CapacityError::MessageTooLong { size, max_size }) => {
                (*size, *max_size, "message")
            }
            _ => return None,
        };
        Some((ws_global_capacity_close_frame(), kind, size, max_size))
    }
}

/// Bounded, non-secret RFC 6455 Close 1009 for global parser capacity overflow.
pub(crate) fn ws_global_capacity_close_frame() -> CloseFrame {
    CloseFrame {
        code: CloseCode::Size,
        // Empty reason stays within the 123-byte control-frame budget and never
        // echoes peer-controlled or secret material.
        reason: "".into(),
    }
}

/// Defined idle-timeout policy Close published once for both relay halves.
pub(crate) fn ws_idle_timeout_policy_close_frame() -> CloseFrame {
    CloseFrame {
        code: CloseCode::Away,
        reason: "idle timeout".into(),
    }
}

fn ws_close_write_error_kind(error: &tokio_tungstenite::tungstenite::Error) -> &'static str {
    use tokio_tungstenite::tungstenite::Error;

    match error {
        Error::ConnectionClosed => "connection_closed",
        Error::AlreadyClosed => "already_closed",
        Error::Io(_) => "io",
        Error::Protocol(_) => "protocol",
        Error::Capacity(_) => "capacity",
        _ => "other",
    }
}

pub(crate) async fn send_bounded_ws_close<S>(sink: &mut S, close: Option<CloseFrame>)
where
    S: Sink<Message, Error = tokio_tungstenite::tungstenite::Error> + Unpin,
{
    use tokio_tungstenite::tungstenite::Error;
    use tokio_tungstenite::tungstenite::error::ProtocolError;

    let result = crate::lazy_timeout::lazy_timeout(
        Duration::from_millis(WS_CANCEL_CLOSE_TIMEOUT_MS),
        async {
            match sink.send(Message::Close(close)).await {
                Err(Error::Protocol(ProtocolError::SendAfterClosing)) => {
                    // Reading a peer Close makes tungstenite queue the required
                    // echo and enter ClosedByPeer. A second send is rejected,
                    // so drive the already-queued control frame out instead.
                    ("flush_queued_peer_echo", sink.flush().await)
                }
                result => ("send", result),
            }
        },
    )
    .await;

    // Timeout is an expected teardown bound and stays quiet. Completed
    // failures get a low-cardinality diagnostic without logging Close reasons
    // or any peer-controlled payload.
    if let Ok((phase, Err(error))) = result {
        debug!(
            phase,
            error_kind = ws_close_write_error_kind(&error),
            "Bounded WebSocket close write failed"
        );
    }
}

pub(crate) fn publish_ws_policy_close(
    policy_close: &std::sync::OnceLock<CloseFrame>,
    cancel: &tokio_util::sync::CancellationToken,
    close: Option<CloseFrame>,
) -> Option<CloseFrame> {
    if let Some(details) = close {
        let _ = policy_close.set(details);
    }
    // This helper is synchronous: callers cannot begin a bounded write until
    // the first detailed Close is published and both relay halves can observe
    // cancellation.
    cancel.cancel();
    policy_close.get().cloned()
}

/// Drain grace used after one WebSocket relay half exits and the other half is
/// cancelled. Also acts as the fallback safety bound for tunnel-mode residual
/// forwarding when both the WebSocket idle timeout and TCP half-close cap are
/// disabled by configuration.
pub(crate) const WS_DRAIN_GRACE: Duration = Duration::from_secs(30);

fn websocket_tunnel_idle_disabled_safety_cap(tcp_half_close_max_wait_seconds: u64) -> Duration {
    if tcp_half_close_max_wait_seconds == 0 {
        return WS_DRAIN_GRACE;
    }
    Duration::from_secs(tcp_half_close_max_wait_seconds).min(WS_DRAIN_GRACE)
}

#[inline]
fn ws_message_payload_bytes(msg: &Message) -> u64 {
    match msg {
        Message::Text(t) => t.len() as u64,
        Message::Binary(b) => b.len() as u64,
        Message::Ping(b) | Message::Pong(b) => b.len() as u64,
        // Close with a status code: 2 status bytes + UTF-8 reason length.
        // Matches `ws_frame_logging` `size_bytes` so success-only byte totals
        // reconcile with delivered Close frame events. Raw reason text is never
        // retained here.
        Message::Close(Some(frame)) => 2u64.saturating_add(frame.reason.len() as u64),
        Message::Close(None) => 0,
        Message::Frame(_) => 0,
    }
}

/// Prepare deferred delivery observations from the final post-plugin message
/// before `send()` moves it. Empty when no plugin wants a delivery record.
pub(crate) enum WsFrameDeliveryBatch {
    None,
    One(usize, crate::plugins::WsFrameDeliveryObservation),
    Many(Vec<(usize, crate::plugins::WsFrameDeliveryObservation)>),
}

impl WsFrameDeliveryBatch {
    fn push(&mut self, index: usize, observation: crate::plugins::WsFrameDeliveryObservation) {
        let previous = std::mem::replace(self, Self::None);
        *self = match previous {
            Self::None => Self::One(index, observation),
            Self::One(first_index, first_observation) => {
                Self::Many(vec![(first_index, first_observation), (index, observation)])
            }
            Self::Many(mut entries) => {
                entries.push((index, observation));
                Self::Many(entries)
            }
        };
    }
}

pub(crate) fn prepare_ws_frame_deliveries(
    plugins: &[Arc<dyn Plugin>],
    message: &Message,
) -> WsFrameDeliveryBatch {
    if plugins.is_empty() {
        return WsFrameDeliveryBatch::None;
    }
    // The normal deployment has one ws_frame_logging instance. Keep that path
    // stack-only; allocate only when multiple delivery observers are configured.
    let mut out = WsFrameDeliveryBatch::None;
    for (index, plugin) in plugins.iter().enumerate() {
        if let Some(observation) = plugin.prepare_ws_frame_delivery(message) {
            out.push(index, observation);
        }
    }
    out
}

/// Emit previously prepared delivery observations after the destination sink
/// accepted the frame. Discarded observations (cancel / write failure) must
/// never reach this helper — that keeps frame logs on the same success boundary
/// as `frames_*` / `bytes_*` counters.
pub(crate) fn emit_ws_frame_deliveries(
    plugins: &[Arc<dyn Plugin>],
    proxy_id: &str,
    connection_id: u64,
    direction: WebSocketFrameDirection,
    prepared: WsFrameDeliveryBatch,
) {
    let emit = |index: usize, observation: crate::plugins::WsFrameDeliveryObservation| {
        if let Some(plugin) = plugins.get(index) {
            plugin.emit_ws_frame_delivery(proxy_id, connection_id, direction, observation);
        }
    };
    match prepared {
        WsFrameDeliveryBatch::None => {}
        WsFrameDeliveryBatch::One(index, observation) => emit(index, observation),
        WsFrameDeliveryBatch::Many(entries) => {
            for (index, observation) in entries {
                emit(index, observation);
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WsControlKind {
    Ping,
    Pong,
}

fn ws_control_kind(message: &Message) -> Option<WsControlKind> {
    match message {
        Message::Ping(_) => Some(WsControlKind::Ping),
        Message::Pong(_) => Some(WsControlKind::Pong),
        _ => None,
    }
}

pub(crate) fn guard_ws_control_transform(
    original: &Message,
    transformed: Message,
    direction: WebSocketFrameDirection,
) -> Message {
    match (ws_control_kind(original), ws_control_kind(&transformed)) {
        (Some(WsControlKind::Ping), Some(WsControlKind::Pong))
        | (Some(WsControlKind::Pong), Some(WsControlKind::Ping)) => {
            warn!(
                ?direction,
                "WebSocket frame plugin attempted to flip Ping/Pong control frame type; forwarding original frame"
            );
            original.clone()
        }
        _ => transformed,
    }
}

/// Apply priority-ordered `on_ws_frame` hooks for one reassembled message.
///
/// The first terminal `Message::Close` from an admission/mutating plugin wins:
/// later mutating plugins are skipped so they cannot charge budget or replace
/// the Close, while observational hooks
/// ([`Plugin::observes_ws_frame_decisions`]) still receive the final decision.
/// The control-frame guard runs after the chain so Ping/Pong type flips are
/// restored before any post-send delivery observation sees the message.
/// Both relay directions and all H1/H2/H3 frontends share this helper.
///
/// Delivery-accurate frame logging uses [`prepare_ws_frame_deliveries`] /
/// [`emit_ws_frame_deliveries`] after a successful sink accept — not this
/// mutating chain — so cancelled or failed writes never appear as delivered.
pub(crate) async fn apply_ws_frame_plugins(
    plugins: &[Arc<dyn Plugin>],
    proxy_id: &str,
    connection_id: u64,
    direction: WebSocketFrameDirection,
    raw: Message,
) -> Message {
    if plugins.is_empty() {
        return raw;
    }
    let original = raw.clone();
    let mut current = raw;
    let mut terminal_close = false;
    for plugin in plugins {
        let observes_decisions = plugin.observes_ws_frame_decisions();
        if terminal_close && !observes_decisions {
            continue;
        }
        let transformed = plugin
            .on_ws_frame(proxy_id, connection_id, direction, &current)
            .await;
        if observes_decisions {
            // Enforce the observe-only capability instead of trusting a custom
            // implementation not to return an accidental replacement.
            continue;
        }
        if let Some(transformed) = transformed {
            if matches!(&transformed, Message::Close(_)) {
                terminal_close = true;
            }
            current = transformed;
        }
    }
    guard_ws_control_transform(&original, current, direction)
}

enum WsNextMessage {
    Item(Option<Result<Message, tokio_tungstenite::tungstenite::Error>>),
    IdleTimeout,
}

/// Connection-wide WebSocket idle tracker shared by both relay directions.
///
/// `last_activity_ms` holds milliseconds since `epoch`, refreshed whenever a
/// frame (data or control) arrives from EITHER side. Each direction derives
/// its wait from this shared watermark, so a timer expiry on one half is only
/// terminal when the OTHER half also produced no traffic inside the window.
/// This mirrors the shared `last_activity` idle watchdog used by the
/// tunnel-mode raw copy (`tcp_proxy::bidirectional_copy_for_relay`) and the
/// TCP relay: asymmetric sessions (quiet client, chatty backend pushing
/// notifications/pings) stay open, and the session is torn down only when the
/// connection as a whole is idle.
pub struct WsIdleTracker {
    timeout: Duration,
    epoch: Instant,
    last_activity_ms: AtomicU64,
}

impl WsIdleTracker {
    pub(crate) fn new(timeout: Duration) -> Self {
        Self {
            timeout,
            epoch: Instant::now(),
            last_activity_ms: AtomicU64::new(0),
        }
    }

    /// Build the shared tracker from the configured timeout seconds;
    /// `None` (idle timeout disabled) when the value is `0`.
    pub(crate) fn from_timeout_seconds(seconds: u64) -> Option<Arc<Self>> {
        (seconds > 0).then(|| Arc::new(Self::new(Duration::from_secs(seconds))))
    }

    fn now_ms(&self) -> u64 {
        u64::try_from(self.epoch.elapsed().as_millis()).unwrap_or(u64::MAX)
    }

    /// Record activity: bytes or a frame received from either direction.
    fn touch(&self) {
        self.last_activity_ms
            .store(self.now_ms(), Ordering::Relaxed);
    }

    /// Time left before the shared idle window elapses; `None` when expired.
    fn remaining(&self) -> Option<Duration> {
        let idle_ms = self
            .now_ms()
            .saturating_sub(self.last_activity_ms.load(Ordering::Relaxed));
        self.timeout
            .checked_sub(Duration::from_millis(idle_ms))
            .filter(|remaining| !remaining.is_zero())
    }
}

/// Byte-level activity adapter feeding [`WsIdleTracker`].
///
/// Wraps the raw transport UNDER the WebSocket framer (client: the upgraded
/// H1/H2 stream or the H3 duplex bridge; backend: the TCP stream beneath
/// `MaybeTlsStream`) and refreshes the shared idle watermark whenever read
/// progress is made. Tracking at the byte level — rather than only when
/// tungstenite yields a complete `Message` — keeps a slowly arriving large or
/// fragmented WebSocket message alive: continuation frames refresh the
/// watermark as their bytes land even though no complete message has been
/// assembled yet. This matches the byte-level shared idle timer used by the
/// tunnel-mode raw copy, so frame-parsed and tunnel sessions expire under the
/// same "no bytes in either direction" rule.
///
/// Writes don't touch the watermark: every byte written to one side was just
/// read from the other, so read-side tracking already covers both directions.
/// With `tracker == None` (idle timeout disabled) the adapter is a pure
/// passthrough.
pub struct WsActivityIo<S> {
    inner: S,
    tracker: Option<Arc<WsIdleTracker>>,
}

impl<S> WsActivityIo<S> {
    pub(crate) fn new(inner: S, tracker: Option<Arc<WsIdleTracker>>) -> Self {
        Self { inner, tracker }
    }

    /// Access the wrapped transport (socket-option tweaks, tests).
    #[allow(dead_code)] // Used by library consumers and external unit tests; the binary tree has no caller.
    pub fn get_ref(&self) -> &S {
        &self.inner
    }
}

impl<S: tokio::io::AsyncRead + Unpin> tokio::io::AsyncRead for WsActivityIo<S> {
    fn poll_read(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &mut tokio::io::ReadBuf<'_>,
    ) -> Poll<std::io::Result<()>> {
        let before = buf.filled().len();
        let result = std::pin::Pin::new(&mut self.inner).poll_read(cx, buf);
        if let Poll::Ready(Ok(())) = &result
            && buf.filled().len() > before
            && let Some(tracker) = &self.tracker
        {
            tracker.touch();
        }
        result
    }
}

impl<S: tokio::io::AsyncWrite + Unpin> tokio::io::AsyncWrite for WsActivityIo<S> {
    fn poll_write(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        std::pin::Pin::new(&mut self.inner).poll_write(cx, buf)
    }

    fn poll_flush(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> Poll<std::io::Result<()>> {
        std::pin::Pin::new(&mut self.inner).poll_flush(cx)
    }

    fn poll_shutdown(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> Poll<std::io::Result<()>> {
        std::pin::Pin::new(&mut self.inner).poll_shutdown(cx)
    }

    fn poll_write_vectored(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        bufs: &[std::io::IoSlice<'_>],
    ) -> Poll<std::io::Result<usize>> {
        std::pin::Pin::new(&mut self.inner).poll_write_vectored(cx, bufs)
    }

    fn is_write_vectored(&self) -> bool {
        self.inner.is_write_vectored()
    }
}

async fn next_websocket_message<S>(stream: &mut S, idle: Option<&WsIdleTracker>) -> WsNextMessage
where
    S: Stream<Item = Result<Message, tokio_tungstenite::tungstenite::Error>> + Unpin,
{
    let Some(idle) = idle else {
        // Idle timeout disabled: await the stream directly — no timer, no
        // atomics, zero added overhead.
        return WsNextMessage::Item(stream.next().await);
    };
    loop {
        // Re-derive the wait from the shared watermark each pass: the other
        // relay direction may have refreshed it while this half was parked,
        // in which case the local timer expiry is not terminal and the wait
        // continues for the remainder of the window.
        let Some(remaining) = idle.remaining() else {
            return WsNextMessage::IdleTimeout;
        };
        if let Ok(item) = tokio::time::timeout(remaining, stream.next()).await {
            if item.is_some() {
                idle.touch();
            }
            return WsNextMessage::Item(item);
        }
    }
}

/// Generic over the client transport type `C`. The H1/H2 frontend passes
/// `TokioIo::new(upgraded)` (hyper's `Upgraded` adapted to tokio AsyncRead+AsyncWrite);
/// the H3 frontend (RFC 9220 Extended CONNECT) passes a `tokio::io::DuplexStream`
/// half that is bridged to the QUIC stream by a pair of pump tasks in
/// `src/http3/websocket.rs`. The function is generic so both frontends share
/// the same frame relay, plugin pipeline, and disconnect bookkeeping —
/// only the bytes-on-the-wire transport differs.
///
/// `websocket_tunnel_mode` takes over the backend raw stream immediately after
/// the backend handshake boundary and replays any recovered backend bytes before
/// starting the bidirectional relay. H3 callers pass `websocket_tunnel_mode =
/// false` because RFC 9220 is already bridged as WebSocket frames over QUIC, not
/// a raw TCP socket.
///
/// `accept_unmasked_client_frames` controls whether the WebSocket framer
/// accepts client-to-server frames without the RFC 6455 mask bit set.
/// HTTP/1.1 and HTTP/2 callers pass `false` (RFC 6455 / RFC 8441 mandate
/// masked client frames). HTTP/3 callers pass `true` — RFC 9220 §5
/// REVERSES the masking requirement: client-to-server frames MUST NOT
/// be masked when the WebSocket runs over HTTP/3. The H3 bridge validates
/// that rule before bytes reach this shared tungstenite framer, then passes
/// `true` here so compliant unmasked client frames are accepted.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn run_websocket_proxy<C, B>(
    mut client_io: C,
    backend_ws_stream: WebSocketStream<B>,
    proxy_id: &str,
    connection_id: u64,
    ws_framing_plugins: Vec<Arc<dyn Plugin>>,
    ws_frame_plugins: Vec<Arc<dyn Plugin>>,
    ws_disconnect_plugins: Vec<Arc<dyn Plugin>>,
    session_meta: WsSessionMeta,
    _ws_connection_permit: Option<tokio::sync::OwnedSemaphorePermit>,
    max_websocket_frame_size_bytes: usize,
    websocket_write_buffer_size: usize,
    websocket_tunnel_mode: bool,
    websocket_tunnel_idle_disabled_safety_cap: Duration,
    accept_unmasked_client_frames: bool,
    ws_idle_tracker: Option<Arc<WsIdleTracker>>,
    adaptive_buffer: &crate::adaptive_buffer::AdaptiveBufferTracker,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>>
where
    C: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
    // Generic over the backend transport so the H1/H2/H3 paths (a TCP/TLS
    // backend stream via `connect_websocket_backend`) and the Sidecar/Ambient
    // mesh egress paths (a `WebSocketStream<H2ConnectTunnel>` over an Extended
    // CONNECT byte tunnel) share one frame relay. The tunnel-mode raw-copy
    // fast path is H1-only; both transports satisfy the bound, so the early
    // return below stays generic.
    B: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
{
    // Invariant: the tunnel-mode raw-copy fast path is only reachable from H1
    // frontends. RFC 6455 (H1.1) and RFC 8441 (H2 Extended CONNECT) mandate
    // masked client frames, so H1/H2 always pass `accept_unmasked_client_frames
    // = false`. RFC 9220 (H3 Extended CONNECT) reverses the rule and the H3
    // caller passes `true` — but H3 cannot tunnel raw bytes (there is no TCP
    // underneath QUIC) so the caller also passes `websocket_tunnel_mode =
    // false`. If both are ever `true` simultaneously, a refactor has wired a
    // non-TCP transport into the tunnel branch and `copy_bidirectional` would
    // silently elide frame parsing on traffic that needs it.
    debug_assert!(
        !(websocket_tunnel_mode && accept_unmasked_client_frames),
        "run_websocket_proxy: tunnel mode is incompatible with unmasked client \
         frames (H3 caller must pass websocket_tunnel_mode=false)"
    );
    let websocket_idle_timeout = ws_idle_tracker.as_ref().map(|tracker| tracker.timeout);

    // When tunnel mode is enabled and no plugins need parsed framing, bypass
    // WebSocket frame parsing entirely and do raw TCP bidirectional copy. This
    // avoids per-frame header parsing, masking validation, and opcode dispatch —
    // critical for large frames (9 MB+). Trade-off: FERRUM_MAX_WEBSOCKET_FRAME_SIZE_BYTES
    // is not enforced, but data streams through a fixed-size copy buffer so there
    // is no large-allocation DoS risk.
    if websocket_tunnel_mode && ws_framing_plugins.is_empty() {
        debug!(
            proxy_id = %proxy_id,
            connection_id,
            "WebSocket tunnel mode: no frame plugins, using raw bidirectional copy"
        );
        // The backend handshake has completed and no WebSocket frame has been
        // polled yet, so this is a frame-codec boundary. Recover any bytes the
        // backend coalesced with the 101 response and forward them before the
        // raw relay can read later backend bytes.
        let (backend, backend_read_buffer) = backend_ws_stream.into_inner_with_read_buffer();
        let recovered_backend_bytes_written;
        let residual_write_timeout =
            websocket_idle_timeout.unwrap_or(websocket_tunnel_idle_disabled_safety_cap);
        let pre_relay_failure = {
            use tokio::io::AsyncWriteExt;
            let mut offset = 0usize;
            let write_result = tokio::time::timeout(residual_write_timeout, async {
                while offset < backend_read_buffer.len() {
                    match client_io.write(&backend_read_buffer[offset..]).await {
                        Ok(0) => {
                            return Err(std::io::Error::new(
                                std::io::ErrorKind::WriteZero,
                                "client accepted zero bytes while forwarding WebSocket backend residual bytes",
                            ));
                        }
                        Ok(n) => {
                            offset = offset.saturating_add(n);
                        }
                        Err(err) => {
                            return Err(err);
                        }
                    }
                }
                Ok(())
            })
            .await;
            recovered_backend_bytes_written = offset as u64;
            match write_result {
                Ok(Ok(())) => None,
                Ok(Err(err)) => Some((
                    crate::plugins::Direction::BackendToClient,
                    crate::retry::ErrorClass::ClientDisconnect,
                    Some(tcp_proxy::StreamIoSide::Write),
                    format!("failed forwarding WebSocket backend residual bytes to client: {err}"),
                )),
                Err(_) => Some((
                    crate::plugins::Direction::BackendToClient,
                    crate::retry::ErrorClass::ReadWriteTimeout,
                    Some(tcp_proxy::StreamIoSide::Write),
                    format!(
                        "timed out after {}ms forwarding WebSocket backend residual bytes to client",
                        residual_write_timeout.as_millis()
                    ),
                )),
            }
        };
        if let Some((direction, class, side, message)) = pre_relay_failure {
            debug!(
                proxy_id = %proxy_id,
                connection_id,
                direction = ?direction,
                error_class = %class,
                io_side = ?side,
                error = %message,
                "WebSocket tunnel residual forward failed"
            );
            adaptive_buffer.record_connection(proxy_id, recovered_backend_bytes_written);
            fire_ws_tunnel_disconnect_hooks(
                &ws_disconnect_plugins,
                proxy_id,
                &session_meta,
                0,
                recovered_backend_bytes_written,
                Some((direction, class, side)),
            )
            .await;
            return Ok(());
        }
        let buf_size = adaptive_buffer.get_buffer_size(proxy_id);
        // With the WebSocket idle timeout disabled, pass a non-zero relay cap
        // so the shared TCP relay uses its direction-tracking path instead of
        // Tokio's opaque fast path. That preserves per-direction byte counters
        // when the relay exits with an error.
        let tunnel_half_close_cap = if websocket_idle_timeout.is_none() {
            Some(websocket_tunnel_idle_disabled_safety_cap)
        } else {
            None
        };
        let copy_result = tcp_proxy::bidirectional_copy_for_relay(
            client_io,
            backend,
            websocket_idle_timeout,
            tunnel_half_close_cap,
            None,
            None,
            buf_size,
        )
        .await;
        adaptive_buffer.record_connection(
            proxy_id,
            copy_result.bytes_client_to_backend.saturating_add(
                copy_result
                    .bytes_backend_to_client
                    .saturating_add(recovered_backend_bytes_written),
            ),
        );
        let tunnel_failure =
            copy_result
                .first_failure
                .as_ref()
                .map(|(direction, class, side, message)| {
                    debug!(
                        proxy_id = %proxy_id,
                        connection_id,
                        direction = ?direction,
                        error_class = %class,
                        io_side = ?side,
                        error = %message,
                        "WebSocket tunnel relay ended with failure"
                    );
                    (*direction, *class, *side)
                });
        // Fire on_ws_disconnect so plugins that opted into disconnect hooks see
        // the tunnel-mode session teardown. Frame counts are 0 because tunnel
        // mode does raw TCP bidirectional copy — no frames are parsed.
        fire_ws_tunnel_disconnect_hooks(
            &ws_disconnect_plugins,
            proxy_id,
            &session_meta,
            copy_result.bytes_client_to_backend,
            copy_result
                .bytes_backend_to_client
                .saturating_add(recovered_backend_bytes_written),
            tunnel_failure,
        )
        .await;
        return Ok(());
    }

    let effective_size_limits = Arc::new(EffectiveWsSizeLimits::from_plugins(
        max_websocket_frame_size_bytes,
        &ws_framing_plugins,
    ));
    let mut ws_config = WebSocketConfig::default();
    ws_config.max_frame_size = Some(effective_size_limits.max_frame_bytes);
    ws_config.max_message_size = Some(effective_size_limits.max_message_bytes);
    ws_config.write_buffer_size = websocket_write_buffer_size;
    // RFC 9220 §5: frames over HTTP/3 are NOT masked. H1/H2 callers
    // pass `false` (RFC 6455 / RFC 8441 mandate masked client frames);
    // H3 callers pass `true`.
    ws_config.accept_unmasked_frames = accept_unmasked_client_frames;

    // Byte-level idle activity adapter under the client-side framer, matching
    // the wrap applied beneath the backend stream at connect time: read
    // progress on a partially received (fragmented/large) client message
    // refreshes the shared watermark before a complete `Message` is yielded.
    let ws_stream = WebSocketStream::from_raw_socket(
        WsActivityIo::new(client_io, ws_idle_tracker.clone()),
        tokio_tungstenite::tungstenite::protocol::Role::Server,
        Some(ws_config),
    )
    .await;

    // Split streams for bidirectional communication
    let (mut ws_sink, mut ws_stream) = ws_stream.split();
    let (mut backend_sink, mut backend_stream) = backend_ws_stream.split();

    // Clone Arc'd plugin list for each direction task.
    // When ws_frame_plugins is empty these clones are zero-cost (empty Vec).
    let ctb_plugins = ws_frame_plugins.clone();
    let btc_plugins = ws_frame_plugins;
    let proxy_id_ctb = proxy_id.to_string();
    let proxy_id_btc = proxy_id.to_string();

    // Per-direction frame counters for the on_ws_disconnect summary. Kept as
    // plain atomics (not protected by any lock) so the forward tasks can bump
    // them without coordination. Reads happen exactly once at teardown.
    let frames_c2b = Arc::new(AtomicU64::new(0));
    let frames_b2c = Arc::new(AtomicU64::new(0));
    let bytes_c2b = Arc::new(AtomicU64::new(0));
    let bytes_b2c = Arc::new(AtomicU64::new(0));
    let frames_c2b_task = frames_c2b.clone();
    let frames_b2c_task = frames_b2c.clone();
    let bytes_c2b_task = bytes_c2b.clone();
    let bytes_b2c_task = bytes_b2c.clone();

    // First-failure recorder. Whichever forward direction hits an error first
    // wins the (Direction, ErrorClass) slot via OnceLock::set(); later errors
    // from the other direction (or from the write-side of the same direction)
    // are dropped. Both directions still publish their clean-close outcome
    // through the counter, so "no error + clean close" is distinguishable
    // from "error observed on one half".
    let first_failure: Arc<
        std::sync::OnceLock<(
            crate::plugins::Direction,
            retry::ErrorClass,
            Option<tcp_proxy::StreamIoSide>,
        )>,
    > = Arc::new(std::sync::OnceLock::new());
    let first_failure_ctb = first_failure.clone();
    let first_failure_btc = first_failure.clone();
    // Connection-wide idle tracker shared by both relay halves (see
    // `WsIdleTracker`). `None` when the timeout is disabled — the relay then
    // awaits `stream.next()` directly with zero added overhead. The same
    // tracker is wired into the byte-level `WsActivityIo` adapters under both
    // framers, so mid-message read progress also refreshes the watermark.
    let ws_idle_tracker_ctb = ws_idle_tracker.clone();
    let ws_idle_tracker_btc = ws_idle_tracker;
    let size_limits_ctb = Arc::clone(&effective_size_limits);
    let size_limits_btc = effective_size_limits;

    // Cancellation token for clean bidirectional close when a plugin triggers Close.
    // Each direction checks this token to know if the other side initiated a close.
    let cancel = tokio_util::sync::CancellationToken::new();
    let cancel_ctb = cancel.clone();
    let cancel_btc = cancel.clone();
    let policy_close: Arc<std::sync::OnceLock<CloseFrame>> = Arc::new(std::sync::OnceLock::new());
    let policy_close_ctb = Arc::clone(&policy_close);
    let policy_close_btc = policy_close;

    // Forward messages from client to backend
    let client_to_backend = async move {
        debug!("Starting client -> backend message forwarding");
        loop {
            tokio::select! {
                biased;
                _ = cancel_ctb.cancelled() => {
                    debug!("Client->backend: other direction triggered close");
                    // Bounded polite-close: the opposite direction has already
                    // cancelled us, so a plain `.await` on `backend_sink.send()`
                    // could hang forever if the backend socket is backpressured
                    // or dead. `lazy_timeout` pays zero cost when the send
                    // completes synchronously (common for small Close frames on
                    // healthy TCP) and only registers a timer on Pending.
                    // Cannot use select+cancel here — cancel is already signaled
                    // and would skip the Close entirely.
                    send_bounded_ws_close(
                        &mut backend_sink,
                        policy_close_ctb.get().cloned(),
                    )
                    .await;
                    break;
                }
                msg = next_websocket_message(&mut ws_stream, ws_idle_tracker_ctb.as_deref()) => {
                    let msg = match msg {
                        WsNextMessage::Item(Some(msg)) => msg,
                        WsNextMessage::Item(None) => break,
                        WsNextMessage::IdleTimeout => {
                            debug!(
                                proxy_id = %proxy_id_ctb,
                                connection_id,
                                idle_timeout_seconds = ws_idle_tracker_ctb
                                    .as_deref()
                                    .map(|idle| idle.timeout.as_secs())
                                    .unwrap_or_default(),
                                "WebSocket session idle timeout: no frames in either direction \
                                 (observed on client->backend half)"
                            );
                            // Connection-wide idle: neither direction produced
                            // a frame, so attribution matches the tunnel-mode
                            // shared idle watchdog (Unknown direction, no side).
                            let _ = first_failure_ctb.set((
                                crate::plugins::Direction::Unknown,
                                retry::ErrorClass::ReadWriteTimeout,
                                None,
                            ));
                            // Publish one defined policy Close before cancel so
                            // both halves attempt the same meaningful teardown
                            // (1001) instead of asymmetric 1005/1006.
                            let close = publish_ws_policy_close(
                                &policy_close_ctb,
                                &cancel_ctb,
                                Some(ws_idle_timeout_policy_close_frame()),
                            );
                            send_bounded_ws_close(&mut backend_sink, close).await;
                            break;
                        }
                    };
                    match msg {
                        Ok(raw @ (Message::Text(_) | Message::Binary(_) | Message::Ping(_) | Message::Pong(_))) => {
                            // Apply frame hooks when any plugin opted in (zero overhead when empty)
                            let outgoing = apply_ws_frame_plugins(
                                &ctb_plugins,
                                &proxy_id_ctb,
                                connection_id,
                                WebSocketFrameDirection::ClientToBackend,
                                raw,
                            )
                            .await;
                            // If a plugin transformed the message into a Close, publish its
                            // details and cancel both halves before any bounded polite write.
                            if let Message::Close(close_frame) = &outgoing {
                                debug!("Plugin triggered close on client->backend frame");
                                // Publish the detailed Close first, then cancel before the
                                // bounded destination write. The opposite half can therefore
                                // notify the offending sender immediately even if this sink is
                                // permanently backpressured.
                                let close = publish_ws_policy_close(
                                    &policy_close_ctb,
                                    &cancel_ctb,
                                    close_frame.clone(),
                                );
                                send_bounded_ws_close(
                                    &mut backend_sink,
                                    close,
                                )
                                .await;
                                break;
                            }
                            match &outgoing {
                                Message::Text(_) => trace!("Client -> Backend: Text message"),
                                Message::Binary(d) => {
                                    trace!(bytes = d.len(), "Client -> Backend: Binary message")
                                }
                                Message::Ping(_) => trace!("Client -> Backend: Ping"),
                                Message::Pong(_) => trace!("Client -> Backend: Pong"),
                                _ => {}
                            }
                            // Cancel-aware send: if the opposite direction has exited and
                            // cancelled us while this send is blocked on backend backpressure,
                            // `select!` breaks us out instead of hanging `tokio::join!` forever.
                            // Overhead is one atomic load per frame (CancellationToken state
                            // check); the send future is polled first on wakeup so successful
                            // sends pay no extra latency. No heap allocation, no timer wheel.
                            //
                            // Snapshot payload bytes and prepare delivery observations
                            // before `send(outgoing)` moves the frame. Prepared logs are
                            // emitted only on the success arm so they share the
                            // success-only boundary with frame/byte counters; cancel and
                            // write failure discard them (no "attempted" frame event).
                            let outgoing_payload_bytes = ws_message_payload_bytes(&outgoing);
                            let delivery =
                                prepare_ws_frame_deliveries(&ctb_plugins, &outgoing);
                            tokio::select! {
                                biased;
                                _ = cancel_ctb.cancelled() => {
                                    debug!("Client->backend: cancel fired mid-send");
                                    break;
                                }
                                res = backend_sink.send(outgoing) => {
                                    if let Err(e) = res {
                                        error!("Failed to send message to backend: {}", e);
                                        // Write-side failure on the c2b path means the
                                        // backend socket errored while we were pushing
                                        // into it — attribute to the c2b direction.
                                        let _ = first_failure_ctb.set((
                                            crate::plugins::Direction::ClientToBackend,
                                            retry::classify_boxed_error(&e),
                                            Some(tcp_proxy::StreamIoSide::Write),
                                        ));
                                        break;
                                    }
                                    // Count the frame that successfully reached the backend.
                                    frames_c2b_task.fetch_add(1, Ordering::Relaxed);
                                    bytes_c2b_task.fetch_add(
                                        outgoing_payload_bytes,
                                        Ordering::Relaxed,
                                    );
                                    emit_ws_frame_deliveries(
                                        &ctb_plugins,
                                        &proxy_id_ctb,
                                        connection_id,
                                        WebSocketFrameDirection::ClientToBackend,
                                        delivery,
                                    );
                                }
                            }
                        }
                        Ok(Message::Close(close_frame)) => {
                            debug!("Client sent close frame");
                            // Peer Close bypasses mutating admission hooks so a later
                            // plugin cannot replace the peer's code/reason. Observational
                            // delivery logging still records the forwarded Close after a
                            // successful sink accept (exactly once; not double-counted
                            // with policy_close records from plugin rejection).
                            let close_msg = Message::Close(close_frame);
                            let outgoing_payload_bytes = ws_message_payload_bytes(&close_msg);
                            let delivery =
                                prepare_ws_frame_deliveries(&ctb_plugins, &close_msg);
                            // Race cancel in case the opposite direction already exited while
                            // we were decoding this Close frame. The send future is polled
                            // first after the cancel check so the happy path does not block.
                            tokio::select! {
                                biased;
                                _ = cancel_ctb.cancelled() => {
                                    debug!("Client->backend: cancel fired during client-close forward");
                                }
                                res = backend_sink.send(close_msg) => {
                                    match res {
                                        Err(e) => {
                                            error!("Failed to send close to backend: {}", e);
                                            let _ = first_failure_ctb.set((
                                                crate::plugins::Direction::ClientToBackend,
                                                retry::classify_boxed_error(&e),
                                                Some(tcp_proxy::StreamIoSide::Write),
                                            ));
                                        }
                                        Ok(()) => {
                                            frames_c2b_task.fetch_add(1, Ordering::Relaxed);
                                            bytes_c2b_task.fetch_add(
                                                outgoing_payload_bytes,
                                                Ordering::Relaxed,
                                            );
                                            emit_ws_frame_deliveries(
                                                &ctb_plugins,
                                                &proxy_id_ctb,
                                                connection_id,
                                                WebSocketFrameDirection::ClientToBackend,
                                                delivery,
                                            );
                                        }
                                    }
                                }
                            }
                            break;
                        }
                        Ok(Message::Frame(_)) => {
                            trace!("Client -> Backend: Frame");
                        }
                        Err(e) => {
                            let error_class = if let Some((close, limit_kind, size, max_size)) =
                                size_limits_ctb.plugin_close_for_error(&e)
                            {
                                warn!(
                                    plugin = "ws_message_size_limiting",
                                    proxy_id = %proxy_id_ctb,
                                    connection_id,
                                    direction = "client->backend",
                                    limit_kind,
                                    size,
                                    max_size,
                                    "WebSocket size policy rejected input before forwarding"
                                );
                                // Cancellation precedes the bounded polite write so policy
                                // teardown cannot be held by a non-reading destination.
                                let close = publish_ws_policy_close(
                                    &policy_close_ctb,
                                    &cancel_ctb,
                                    Some(close),
                                );
                                send_bounded_ws_close(&mut backend_sink, close).await;
                                retry::ErrorClass::RequestBodyTooLarge
                            } else if let Some((close, limit_kind, size, max_size)) =
                                EffectiveWsSizeLimits::global_capacity_close_for_error(&e)
                            {
                                warn!(
                                    proxy_id = %proxy_id_ctb,
                                    connection_id,
                                    direction = "client->backend",
                                    limit_kind,
                                    size,
                                    max_size,
                                    "WebSocket global size limit rejected input before forwarding"
                                );
                                let close = publish_ws_policy_close(
                                    &policy_close_ctb,
                                    &cancel_ctb,
                                    Some(close),
                                );
                                send_bounded_ws_close(&mut backend_sink, close).await;
                                retry::ErrorClass::RequestBodyTooLarge
                            } else {
                                error!("Error receiving from client: {}", e);
                                retry::classify_boxed_error(&e)
                            };
                            // Read-side failure on the c2b path means the client
                            // dropped / reset the socket.
                            let _ = first_failure_ctb.set((
                                crate::plugins::Direction::ClientToBackend,
                                error_class,
                                Some(tcp_proxy::StreamIoSide::Read),
                            ));
                            break;
                        }
                    }
                }
            }
        }
        debug!("Client -> backend forwarding completed");
        // Signal the opposite direction to wind down so we can finish the
        // session together. If the other direction already cancelled this
        // token (plugin-triggered Close path), `cancel()` is idempotent.
        // Without this, a natural EOF / error / Close-frame exit on c2b
        // would leave b2c running; the outer coordinator would then have
        // to drop b2c (old `tokio::select!`) or hang on it indefinitely.
        cancel_ctb.cancel();
    };

    // Forward messages from backend to client
    let backend_to_client = async move {
        debug!("Starting backend -> client message forwarding");
        loop {
            tokio::select! {
                biased;
                _ = cancel_btc.cancelled() => {
                    debug!("Backend->client: other direction triggered close");
                    // Mirror of the c2b cancel branch: bounded polite-close with
                    // `lazy_timeout` so the client sink cannot hang `tokio::join!`
                    // forever if the client socket is dead or not reading. See
                    // `WS_CANCEL_CLOSE_TIMEOUT_MS` for the rationale.
                    send_bounded_ws_close(
                        &mut ws_sink,
                        policy_close_btc.get().cloned(),
                    )
                    .await;
                    break;
                }
                msg = next_websocket_message(&mut backend_stream, ws_idle_tracker_btc.as_deref()) => {
                    let msg = match msg {
                        WsNextMessage::Item(Some(msg)) => msg,
                        WsNextMessage::Item(None) => break,
                        WsNextMessage::IdleTimeout => {
                            debug!(
                                proxy_id = %proxy_id_btc,
                                connection_id,
                                idle_timeout_seconds = ws_idle_tracker_btc
                                    .as_deref()
                                    .map(|idle| idle.timeout.as_secs())
                                    .unwrap_or_default(),
                                "WebSocket session idle timeout: no frames in either direction \
                                 (observed on backend->client half)"
                            );
                            // Connection-wide idle: neither direction produced
                            // a frame, so attribution matches the tunnel-mode
                            // shared idle watchdog (Unknown direction, no side).
                            let _ = first_failure_btc.set((
                                crate::plugins::Direction::Unknown,
                                retry::ErrorClass::ReadWriteTimeout,
                                None,
                            ));
                            // Mirror of c2b: publish once, then bounded polite
                            // write so the client observes the same 1001 Close.
                            let close = publish_ws_policy_close(
                                &policy_close_btc,
                                &cancel_btc,
                                Some(ws_idle_timeout_policy_close_frame()),
                            );
                            send_bounded_ws_close(&mut ws_sink, close).await;
                            break;
                        }
                    };
                    match msg {
                        Ok(raw @ (Message::Text(_) | Message::Binary(_) | Message::Ping(_) | Message::Pong(_))) => {
                            // Apply frame hooks when any plugin opted in (zero overhead when empty)
                            let outgoing = apply_ws_frame_plugins(
                                &btc_plugins,
                                &proxy_id_btc,
                                connection_id,
                                WebSocketFrameDirection::BackendToClient,
                                raw,
                            )
                            .await;
                            // If a plugin transformed the message into a Close, publish its
                            // details and cancel both halves before any bounded polite write.
                            if let Message::Close(close_frame) = &outgoing {
                                debug!("Plugin triggered close on backend->client frame");
                                let close = publish_ws_policy_close(
                                    &policy_close_btc,
                                    &cancel_btc,
                                    close_frame.clone(),
                                );
                                send_bounded_ws_close(&mut ws_sink, close).await;
                                break;
                            }
                            match &outgoing {
                                Message::Text(_) => trace!("Backend -> Client: Text message"),
                                Message::Binary(d) => {
                                    trace!(bytes = d.len(), "Backend -> Client: Binary message")
                                }
                                Message::Ping(_) => trace!("Backend -> Client: Ping"),
                                Message::Pong(_) => trace!("Backend -> Client: Pong"),
                                _ => {}
                            }
                            // Cancel-aware send (mirror of c2b hot path): prevents
                            // `tokio::join!` from hanging when c2b has already exited and the
                            // client socket is backpressured so our `ws_sink.send()` would
                            // otherwise block indefinitely. One atomic load per frame; send
                            // polled first so successful frames pay no extra latency.
                            //
                            // Snapshot payload bytes and prepare delivery observations
                            // before `send(outgoing)` moves the frame (mirror of c2b).
                            let outgoing_payload_bytes = ws_message_payload_bytes(&outgoing);
                            let delivery =
                                prepare_ws_frame_deliveries(&btc_plugins, &outgoing);
                            tokio::select! {
                                biased;
                                _ = cancel_btc.cancelled() => {
                                    debug!("Backend->client: cancel fired mid-send");
                                    break;
                                }
                                res = ws_sink.send(outgoing) => {
                                    if let Err(e) = res {
                                        error!("Failed to send message to client: {}", e);
                                        // Write-side failure on the b2c path means the
                                        // client dropped/reset while we were pushing
                                        // bytes to it — attribute to b2c direction.
                                        let _ = first_failure_btc.set((
                                            crate::plugins::Direction::BackendToClient,
                                            retry::classify_boxed_error(&e),
                                            Some(tcp_proxy::StreamIoSide::Write),
                                        ));
                                        break;
                                    }
                                    // Count the frame that successfully reached the client.
                                    frames_b2c_task.fetch_add(1, Ordering::Relaxed);
                                    bytes_b2c_task.fetch_add(
                                        outgoing_payload_bytes,
                                        Ordering::Relaxed,
                                    );
                                    emit_ws_frame_deliveries(
                                        &btc_plugins,
                                        &proxy_id_btc,
                                        connection_id,
                                        WebSocketFrameDirection::BackendToClient,
                                        delivery,
                                    );
                                }
                            }
                        }
                        Ok(Message::Close(close_frame)) => {
                            debug!("Backend sent close frame");
                            // Peer Close bypasses mutating hooks; observational delivery
                            // logging records the forwarded Close after sink accept.
                            let close_msg = Message::Close(close_frame);
                            let outgoing_payload_bytes = ws_message_payload_bytes(&close_msg);
                            let delivery =
                                prepare_ws_frame_deliveries(&btc_plugins, &close_msg);
                            // Race cancel in case c2b has already exited.
                            tokio::select! {
                                biased;
                                _ = cancel_btc.cancelled() => {
                                    debug!("Backend->client: cancel fired during backend-close forward");
                                }
                                res = ws_sink.send(close_msg) => {
                                    match res {
                                        Err(e) => {
                                            error!("Failed to send close to client: {}", e);
                                            let _ = first_failure_btc.set((
                                                crate::plugins::Direction::BackendToClient,
                                                retry::classify_boxed_error(&e),
                                                Some(tcp_proxy::StreamIoSide::Write),
                                            ));
                                        }
                                        Ok(()) => {
                                            frames_b2c_task.fetch_add(1, Ordering::Relaxed);
                                            bytes_b2c_task.fetch_add(
                                                outgoing_payload_bytes,
                                                Ordering::Relaxed,
                                            );
                                            emit_ws_frame_deliveries(
                                                &btc_plugins,
                                                &proxy_id_btc,
                                                connection_id,
                                                WebSocketFrameDirection::BackendToClient,
                                                delivery,
                                            );
                                        }
                                    }
                                }
                            }
                            break;
                        }
                        Ok(Message::Frame(_)) => {
                            trace!("Backend -> Client: Frame");
                        }
                        Err(e) => {
                            let error_class = if let Some((close, limit_kind, size, max_size)) =
                                size_limits_btc.plugin_close_for_error(&e)
                            {
                                warn!(
                                    plugin = "ws_message_size_limiting",
                                    proxy_id = %proxy_id_btc,
                                    connection_id,
                                    direction = "backend->client",
                                    limit_kind,
                                    size,
                                    max_size,
                                    "WebSocket size policy rejected input before forwarding"
                                );
                                let close = publish_ws_policy_close(
                                    &policy_close_btc,
                                    &cancel_btc,
                                    Some(close),
                                );
                                send_bounded_ws_close(&mut ws_sink, close).await;
                                retry::ErrorClass::ResponseBodyTooLarge
                            } else if let Some((close, limit_kind, size, max_size)) =
                                EffectiveWsSizeLimits::global_capacity_close_for_error(&e)
                            {
                                warn!(
                                    proxy_id = %proxy_id_btc,
                                    connection_id,
                                    direction = "backend->client",
                                    limit_kind,
                                    size,
                                    max_size,
                                    "WebSocket global size limit rejected input before forwarding"
                                );
                                let close = publish_ws_policy_close(
                                    &policy_close_btc,
                                    &cancel_btc,
                                    Some(close),
                                );
                                send_bounded_ws_close(&mut ws_sink, close).await;
                                retry::ErrorClass::ResponseBodyTooLarge
                            } else {
                                error!("Error receiving from backend: {}", e);
                                retry::classify_boxed_error(&e)
                            };
                            // Read-side failure on the b2c path means the
                            // backend closed / reset the socket.
                            let _ = first_failure_btc.set((
                                crate::plugins::Direction::BackendToClient,
                                error_class,
                                Some(tcp_proxy::StreamIoSide::Read),
                            ));
                            break;
                        }
                    }
                }
            }
        }
        debug!("Backend -> client forwarding completed");
        // Mirror of c2b: once b2c exits for any reason, signal c2b to finish
        // so the outer `tokio::join!` can complete promptly.
        cancel_btc.cancel();
    };

    // Wait for BOTH directions to complete before teardown — not just the
    // first one. Using `tokio::select!` here would drop whichever half is
    // still running (e.g., client half-closes while the backend is still
    // draining queued frames), truncating `frames_*` counts, shortening
    // `duration_ms`, and losing any terminal failure attribution the second
    // half would have produced.
    //
    // But an unbounded `join!` can hang indefinitely: each relay loop calls
    // `on_ws_frame` plugin hooks that aren't wrapped in a cancel-aware
    // `select!`, so a stalled hook on the still-running half would hold the
    // upgraded sockets and `_ws_connection_permit` forever and eventually
    // starve new WebSocket sessions. Race the two halves for first-completion
    // (the exit branch each one runs calls `cancel()` on the opposite token)
    // then wait on the remaining half with a bounded drain grace. If the
    // grace expires the remaining future is dropped — in-flight plugin calls
    // are cancelled and all captured sockets are released.
    let mut c2b = Box::pin(client_to_backend);
    let mut b2c = Box::pin(backend_to_client);
    let client_done = tokio::select! {
        _ = &mut c2b => true,
        _ = &mut b2c => false,
    };
    // On grace-timeout the remaining half's future is dropped (in-flight
    // plugin calls cancelled, sockets released). Record that as a failure so
    // `on_ws_disconnect` surfaces `cause=timeout` instead of looking like a
    // clean close. The direction tags which half was still running when the
    // grace expired.
    if client_done {
        if tokio::time::timeout(WS_DRAIN_GRACE, b2c).await.is_err() {
            let _ = first_failure.set((
                crate::plugins::Direction::BackendToClient,
                retry::ErrorClass::ReadWriteTimeout,
                None,
            ));
        }
    } else if tokio::time::timeout(WS_DRAIN_GRACE, c2b).await.is_err() {
        let _ = first_failure.set((
            crate::plugins::Direction::ClientToBackend,
            retry::ErrorClass::ReadWriteTimeout,
            None,
        ));
    }

    // Fire the on_ws_disconnect hook exactly once, after both forward halves
    // have wound down. When no plugin opted in the list is empty and we skip
    // the whole block — zero overhead for deployments that don't observe
    // WebSocket sessions.
    fire_ws_framed_disconnect_hooks(
        &ws_disconnect_plugins,
        proxy_id,
        session_meta,
        frames_c2b.load(Ordering::Relaxed),
        frames_b2c.load(Ordering::Relaxed),
        bytes_c2b.load(Ordering::Relaxed),
        bytes_b2c.load(Ordering::Relaxed),
        first_failure.get().cloned(),
    )
    .await;

    debug!("WebSocket proxy connection closed for {}", proxy_id);
    Ok(())
}

/// Start the proxy HTTP listener with dual-path handling.
#[allow(dead_code)] // Used by library consumers and tests; binary startup uses the signaled variant.
pub async fn start_proxy_listener(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls(addr, state, shutdown, None).await
}

/// Start the proxy listener with optional TLS and client certificate verification.
#[allow(dead_code)] // Used by library consumers and tests; binary startup uses the signaled variant.
pub async fn start_proxy_listener_with_tls(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_config: Option<Arc<rustls::ServerConfig>>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls_and_signal(addr, state, shutdown, tls_config, None).await
}

/// Run the proxy accept loop on a pre-bound `TcpListener`.
///
/// This is the in-process entry point used by [`crate::modes::file::serve`]:
/// the caller (a test harness, typically) reserves an ephemeral TCP port,
/// passes the live listener in, and the gateway adopts it without rebinding.
///
/// Unlike [`start_proxy_listener_with_tls_and_signal`] this path is
/// deliberately single-listener: SO_REUSEPORT/multi-accept-thread expansion
/// requires the gateway to bind extra sockets itself, which the binary path
/// does and the in-process path explicitly skips. Tests don't need 50k+
/// conn/sec throughput — they need deterministic teardown.
///
/// All other policy (overload guard, connection semaphore, TLS handshake,
/// connection guard) is shared with the binary path.
pub async fn start_proxy_listener_with_bound_listener(
    listener: TcpListener,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_config: Option<Arc<rustls::ServerConfig>>,
) -> Result<(), anyhow::Error> {
    let state = Arc::new(state);
    // Optional connection limit, mirroring the bound-port path. The semaphore
    // is sized from `max_connections` and shared with the connection guard.
    let conn_semaphore: Option<Arc<tokio::sync::Semaphore>> =
        if state.env_config.max_connections > 0 {
            Some(Arc::new(tokio::sync::Semaphore::new(
                state.env_config.max_connections,
            )))
        } else {
            None
        };

    let local = listener.local_addr().ok();
    if let Some(addr) = local {
        info!("Proxy listener (in-process) started on {}", addr);
    } else {
        info!("Proxy listener (in-process) started on bound TCP socket");
    }

    run_accept_loop(
        listener,
        state,
        ListenerTlsSource::Static {
            tls_config,
            record_mesh_mtls_metric: false,
        },
        conn_semaphore,
        shutdown,
        None,
        0,
        SourceIpOverride::none(),
        None,
    )
    .await;
    Ok(())
}

/// Create a bound TCP socket with SO_REUSEADDR and optional SO_REUSEPORT.
/// Used by the multi-listener accept architecture where N sockets are bound
/// to the same address, each with its own accept loop.
/// `SO_REUSEPORT` is enabled only when `reuse_port` is true, which keeps
/// single-listener sockets from being co-bound unnecessarily.
///
/// When `tcp_fastopen_queue_len` is `Some(n)`, enables TCP Fast Open on the
/// listening socket (Linux only), allowing repeat clients with a cached TFO
/// cookie to send data in the SYN packet (saves 1 RTT).
pub(crate) fn create_proxy_socket(
    addr: SocketAddr,
    backlog: i32,
    tcp_fastopen_queue_len: Option<u16>,
    reuse_port: bool,
) -> Result<TcpListener, anyhow::Error> {
    let socket = socket2::Socket::new(
        if addr.is_ipv6() {
            socket2::Domain::IPV6
        } else {
            socket2::Domain::IPV4
        },
        socket2::Type::STREAM,
        Some(socket2::Protocol::TCP),
    )?;

    // SO_REUSEADDR: allow rapid restart without TIME_WAIT blocking the port.
    socket.set_reuse_address(true)?;

    // SO_REUSEPORT: let the kernel distribute incoming connections across
    // multiple listener tasks (Linux 3.9+, macOS, BSDs). This eliminates
    // the single-thread accept() bottleneck at high connection rates.
    #[cfg(unix)]
    if reuse_port {
        socket.set_reuse_port(true)?;
    }

    socket.set_nonblocking(true)?;
    socket.bind(&addr.into())?;

    // TCP_FASTOPEN: enable TFO on the server socket after bind, before listen.
    // This allows repeat clients to send data in the SYN packet, saving 1 RTT.
    if let Some(_queue_len) = tcp_fastopen_queue_len {
        #[cfg(unix)]
        {
            use std::os::unix::io::AsRawFd;
            if let Err(e) =
                crate::socket_opts::set_tcp_fastopen_server(socket.as_raw_fd(), _queue_len as i32)
            {
                tracing::warn!("Failed to enable TCP_FASTOPEN on {}: {}", addr, e);
            }
        }
    }

    socket.listen(backlog)?;

    Ok(TcpListener::from_std(socket.into())?)
}

/// Start the proxy listener with an optional startup signal sent after bind.
///
/// When `FERRUM_ACCEPT_THREADS > 1`, spawns N parallel accept loops each with
/// its own socket bound to the same address via SO_REUSEPORT. The kernel
/// distributes incoming connections across the N sockets, eliminating the
/// single-thread accept() bottleneck at high connection rates (50k+ conn/sec).
/// All N loops share the same connection semaphore for global limit enforcement.
pub async fn start_proxy_listener_with_tls_and_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_config: Option<Arc<rustls::ServerConfig>>,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls_source_and_signal(
        addr,
        state,
        shutdown,
        ListenerTlsSource::Static {
            tls_config,
            record_mesh_mtls_metric: false,
        },
        None,
        started_tx,
    )
    .await
}

/// Start a mesh plaintext listener (e.g., outbound capture on 15001).
///
/// Same as [`start_proxy_listener_with_tls_and_signal`] except the listener
/// stamps `mesh_direction` onto every accepted connection so mesh-aware
/// plugins can gate CLIENT vs SERVER span emission. Used by mesh outbound
/// capture, which terminates plaintext on a known port.
pub(crate) async fn start_mesh_plaintext_listener_with_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_config: Option<Arc<rustls::ServerConfig>>,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls_source_and_signal(
        addr,
        state,
        shutdown,
        ListenerTlsSource::Static {
            tls_config,
            record_mesh_mtls_metric: false,
        },
        mesh_direction,
        started_tx,
    )
    .await
}

/// Start the mesh UDP TPROXY capture listener (F3 §3.3 Stage 3).
///
/// Binds a transparent UDP socket on `addr` (the Stage-2 capture port,
/// `FERRUM_MESH_CAPTURE_UDP_PORT`), recovers each captured datagram's original
/// destination via the `IP(v6)_RECVORIGDSTADDR` cmsg, keys a session by
/// `(client, orig-dst)`, and DROPS it (egress relay is Stage 4). DoS bounds are
/// pulled from `EnvConfig` (`FERRUM_UDP_MAX_SESSIONS` /
/// `FERRUM_UDP_CLEANUP_INTERVAL_SECONDS` / `FERRUM_UDP_RECVMMSG_BATCH_SIZE` /
/// `FERRUM_POOL_SHARD_AMOUNT`), matching the plain UDP proxy. `tls_config` is
/// always `None` for this plaintext listener (the parameter is accepted only so
/// the mesh listener-spawn loop can call every kind uniformly). `mesh_direction`
/// is accepted for call-site uniformity; the capture listener is always
/// outbound and does not thread it further.
pub(crate) async fn start_mesh_udp_capture_listener_with_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_config: Option<Arc<rustls::ServerConfig>>,
    _mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    debug_assert!(
        tls_config.is_none(),
        "mesh UDP capture listener is plaintext; tls_config must be None"
    );
    let _ = tls_config;
    let env = &state.env_config;
    let max_sessions = env.udp_max_sessions;
    let cleanup_interval_seconds = env.udp_cleanup_interval_seconds;
    let recvmmsg_batch_size = env.udp_recvmmsg_batch_size;
    let session_shard_amount = env.pool_shard_amount;
    mesh_udp_capture::start_mesh_udp_capture_listener(mesh_udp_capture::MeshUdpCaptureConfig {
        addr,
        // Stage 4 needs the full proxy state for egress (route table, LB,
        // capability registry, HBONE pool, SVID).
        state: Arc::new(state),
        shutdown,
        // In mesh mode the per-listener `shutdown` is the runtime's
        // SIGINT/SIGTERM-driven channel, so a separate global receiver is
        // unnecessary here.
        global_shutdown: None,
        max_sessions,
        cleanup_interval_seconds,
        recvmmsg_batch_size,
        session_shard_amount,
        started_tx,
    })
    .await
}

/// Start the proxy HTTPS listener with a hot-swappable frontend TLS slot.
///
/// Used when `FERRUM_FRONTEND_TLS_LIVE_RELOAD_ENABLED=true`. The frontend TLS
/// watch task swaps the underlying `ArcSwap` after a validated cert/key
/// reload; subsequent accepts pick up the new config without restarting the
/// listener. Existing in-flight TLS sessions keep their original
/// `ServerConfig`. Mirrors [`start_proxy_listener_with_tls_and_signal`] in
/// every other respect.
pub async fn start_proxy_listener_with_dynamic_tls_and_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_slot: crate::tls::SharedFrontendTls,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls_source_and_signal(
        addr,
        state,
        shutdown,
        ListenerTlsSource::Dynamic {
            slot: tls_slot,
            record_mesh_mtls_metric: false,
        },
        None,
        started_tx,
    )
    .await
}

/// Start a proxy listener whose TLS config is loaded dynamically from
/// `ProxyState::mesh_inbound_tls_policy` on every accepted connection.
///
/// Mesh-mode mTLS / HBONE termination listeners use this when
/// `FERRUM_MESH_PEER_AUTH_LIVE_RELOAD_ENABLED=true`. The mesh slice apply task
/// swaps the underlying `ArcSwap` when PeerAuthentication changes; subsequent
/// accepts pick up the new config without restarting the listener. Existing
/// in-flight connections keep their original TLS state.
///
/// Each accept performs one `ArcSwap::load()` plus one inner `Arc` clone,
/// keeping the atomic read off the proxy request path. See `ListenerTlsSource`.
pub async fn start_proxy_listener_with_mesh_inbound_tls_and_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    allows_plaintext: bool,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    start_proxy_listener_with_tls_source_and_signal(
        addr,
        state,
        shutdown,
        ListenerTlsSource::MeshInbound { allows_plaintext },
        mesh_direction,
        started_tx,
    )
    .await
}

#[derive(Clone)]
enum ListenerTlsSource {
    /// Static listener TLS captured at startup; loading clones only the inner
    /// `Option<Arc<_>>` and performs no atomic read.
    Static {
        tls_config: Option<Arc<rustls::ServerConfig>>,
        record_mesh_mtls_metric: bool,
    },
    /// Dynamic mesh inbound TLS loaded from the authoritative
    /// `ProxyState::mesh_inbound_tls_policy` on every accept so
    /// PeerAuthentication changes can hot-swap future handshakes without
    /// restarting the listener.
    MeshInbound { allows_plaintext: bool },
    /// Dynamic frontend TLS loaded from a shared `ArcSwap` slot on every
    /// accept so a successful cert/key reload (opt-in via
    /// `FERRUM_FRONTEND_TLS_LIVE_RELOAD_ENABLED`) takes effect on the next
    /// handshake without restarting the listener. Existing in-flight TLS
    /// sessions keep their old `ServerConfig`.
    Dynamic {
        slot: crate::tls::SharedFrontendTls,
        record_mesh_mtls_metric: bool,
    },
}

impl ListenerTlsSource {
    /// Load the TLS config for a single accepted connection.
    ///
    /// `Static` is the ordinary startup-captured path. `MeshInbound` performs
    /// one `ArcSwap::load()` and one inner `Arc` clone per accept; this is
    /// the narrow mesh live-reload carve-out and is not on the request path.
    /// `Dynamic` performs one `ArcSwap::load()` and one inner `Arc` clone per
    /// accept; this is the narrow frontend cert/key live-reload carve-out
    /// and is not on the request path.
    fn load(&self, state: &ProxyState, orig_dst: Option<SocketAddr>) -> ListenerTlsSelection {
        match self {
            Self::Static { tls_config, .. } => ListenerTlsSelection {
                tls_config: tls_config.clone(),
                accepts_plaintext: false,
                mesh_inbound_pre_handshake_app_port: None,
            },
            Self::MeshInbound { allows_plaintext } => {
                let policy = state.mesh_inbound_tls_policy.load();
                select_mesh_inbound_tls_for_listener(&policy, orig_dst, *allows_plaintext)
            }
            Self::Dynamic { slot, .. } => ListenerTlsSelection {
                tls_config: slot.load().as_ref().clone(),
                accepts_plaintext: false,
                mesh_inbound_pre_handshake_app_port: None,
            },
        }
    }

    fn record_mesh_mtls_metric(&self) -> bool {
        match self {
            Self::Static {
                record_mesh_mtls_metric,
                ..
            } => *record_mesh_mtls_metric,
            Self::MeshInbound { .. } => true,
            Self::Dynamic {
                record_mesh_mtls_metric,
                ..
            } => *record_mesh_mtls_metric,
        }
    }

    /// Whether this source REQUIRES a TLS config to serve a connection.
    /// Generic dynamic HTTPS listeners must fail closed when their slot is
    /// empty. Mesh inbound live reload is different: `None` is the intentional
    /// representation for PeerAuthentication `DISABLE` and for permissive mode
    /// without frontend TLS materials, so it must fall through to plaintext.
    fn requires_tls(&self) -> bool {
        match self {
            Self::Static { .. } => false,
            Self::MeshInbound { allows_plaintext } => !allows_plaintext,
            Self::Dynamic { .. } => true,
        }
    }
}

struct ListenerTlsSelection {
    tls_config: Option<Arc<rustls::ServerConfig>>,
    /// When TLS is configured, inspect the first byte and send non-TLS traffic
    /// to the plaintext handler. Only mesh PeerAuthentication uses this dual
    /// posture; ordinary HTTPS listeners remain TLS-only.
    accepts_plaintext: bool,
    /// Captured app port used to select this TLS posture, after ingress alias
    /// translation. Stashed on the connection for mismatch diagnostics; the
    /// request gate always consults the current live policy snapshot.
    mesh_inbound_pre_handshake_app_port: Option<u16>,
}

fn mtls_mode_accepts_plaintext(mode: crate::modes::mesh::config::MtlsMode) -> bool {
    matches!(
        mode,
        crate::modes::mesh::config::MtlsMode::Permissive
            | crate::modes::mesh::config::MtlsMode::Disable
    )
}

fn mtls_mode_accepts_tls(mode: crate::modes::mesh::config::MtlsMode) -> bool {
    mode != crate::modes::mesh::config::MtlsMode::Disable
}

fn select_mesh_inbound_tls(
    policy: &MeshInboundTlsPolicy,
    orig_dst: Option<SocketAddr>,
) -> ListenerTlsSelection {
    if let Some(dst) = orig_dst {
        let app_port = policy
            .app_port_by_orig_dst_port
            .get(&dst.port())
            .copied()
            .unwrap_or_else(|| dst.port());
        let mode = policy
            .modes_by_port
            .get(&app_port)
            .copied()
            .unwrap_or(policy.default_mode);
        return ListenerTlsSelection {
            tls_config: select_mesh_inbound_tls_config(
                &policy.default,
                &policy.by_port,
                Some(app_port),
            )
            .clone(),
            accepts_plaintext: mtls_mode_accepts_plaintext(mode),
            mesh_inbound_pre_handshake_app_port: Some(app_port),
        };
    }

    // A direct dial has no app-port signal until HTTP/HBONE routing. Build a
    // dual-wire accept posture whenever any effective mode admits plaintext,
    // and choose the least restrictive available TLS verifier so every TLS
    // mode can complete its handshake. The post-routing gate below enforces
    // the selected app port exactly (STRICT still requires a verified cert;
    // DISABLE still rejects TLS).
    let permissive_tls = if policy.default_mode == crate::modes::mesh::config::MtlsMode::Permissive
    {
        policy.default.clone()
    } else {
        None
    }
    .or_else(|| {
        policy.modes_by_port.iter().find_map(|(port, mode)| {
            if *mode == crate::modes::mesh::config::MtlsMode::Permissive {
                policy.by_port.get(port).cloned().flatten()
            } else {
                None
            }
        })
    });
    let strict_tls = if policy.default_mode == crate::modes::mesh::config::MtlsMode::Strict {
        policy.default.clone()
    } else {
        None
    }
    .or_else(|| {
        policy.modes_by_port.iter().find_map(|(port, mode)| {
            if *mode == crate::modes::mesh::config::MtlsMode::Strict {
                policy.by_port.get(port).cloned().flatten()
            } else {
                None
            }
        })
    });
    let has_different_port_mode = policy
        .modes_by_port
        .values()
        .any(|mode| *mode != policy.default_mode);
    let any_mode_accepts_plaintext = mtls_mode_accepts_plaintext(policy.default_mode)
        || policy
            .modes_by_port
            .values()
            .copied()
            .any(mtls_mode_accepts_plaintext);
    let any_mode_accepts_tls = mtls_mode_accepts_tls(policy.default_mode)
        || policy
            .modes_by_port
            .values()
            .copied()
            .any(mtls_mode_accepts_tls);
    ListenerTlsSelection {
        tls_config: permissive_tls.or(strict_tls),
        accepts_plaintext: mtls_mode_accepts_plaintext(policy.default_mode)
            || (has_different_port_mode && any_mode_accepts_plaintext && any_mode_accepts_tls),
        mesh_inbound_pre_handshake_app_port: None,
    }
}

fn select_mesh_inbound_tls_for_listener(
    policy: &MeshInboundTlsPolicy,
    orig_dst: Option<SocketAddr>,
    allows_plaintext: bool,
) -> ListenerTlsSelection {
    let mut selection = select_mesh_inbound_tls(policy, orig_dst);
    selection.accepts_plaintext &= allows_plaintext;
    selection
}

fn first_byte_is_tls_client_hello(first_byte: u8) -> bool {
    // A TLS connection begins with a handshake record containing ClientHello.
    // This intentionally remains a one-byte discriminator only for HTTP-family
    // inbound traffic: a plaintext HTTP request cannot validly begin with 0x16,
    // and the post-route gate rejects plaintext for STRICT ports. Captured
    // stream-family routes bypass this classifier entirely so application TLS
    // and binary protocols are relayed byte-for-byte under PERMISSIVE.
    first_byte == 0x16
}

fn mesh_inbound_selection_uses_tls(
    has_tls_config: bool,
    accepts_plaintext: bool,
    stream_family_passthrough: bool,
    first_byte: u8,
) -> bool {
    has_tls_config
        && (!accepts_plaintext
            || (!stream_family_passthrough && first_byte_is_tls_client_hello(first_byte)))
}

fn select_mesh_inbound_tls_config<'a>(
    default: &'a Option<Arc<rustls::ServerConfig>>,
    by_port: &'a HashMap<u16, Option<Arc<rustls::ServerConfig>>>,
    app_port: Option<u16>,
) -> &'a Option<Arc<rustls::ServerConfig>> {
    app_port
        .and_then(|port| by_port.get(&port))
        .unwrap_or(default)
}

fn mesh_inbound_transport_satisfies_mode(
    mode: crate::modes::mesh::config::MtlsMode,
    is_tls: bool,
    has_verified_peer_certificate: bool,
) -> bool {
    match mode {
        crate::modes::mesh::config::MtlsMode::Strict => is_tls && has_verified_peer_certificate,
        crate::modes::mesh::config::MtlsMode::Permissive => true,
        crate::modes::mesh::config::MtlsMode::Disable => !is_tls,
        // DestinationRule-only client modes are invalid on PeerAuthentication.
        // Fail closed if malformed native config ever lets one reach this gate.
        crate::modes::mesh::config::MtlsMode::Simple
        | crate::modes::mesh::config::MtlsMode::Mutual
        | crate::modes::mesh::config::MtlsMode::IstioMutual => false,
    }
}

fn mesh_inbound_peer_auth_app_port(proxy: &Proxy, upstream_target: Option<&UpstreamTarget>) -> u16 {
    // Sidecar ingress authorization intentionally uses the declared listener
    // port stored on RequestContext, but PeerAuthentication.portLevelMtls is
    // keyed by the workload app/container port behind defaultEndpoint. Route
    // overrides and upstream selection can replace that initial proxy port, so
    // the concrete target port is authoritative once one has been selected.
    upstream_target
        .map(|target| target.port)
        .unwrap_or(proxy.backend_port)
}

fn mesh_inbound_requires_post_route_transport_gate(
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
) -> bool {
    // Every HTTP-family/HBONE request on a mesh inbound listener must consult
    // the current atomic policy snapshot. In particular, a captured keep-alive
    // connection may have completed its handshake under an older PERMISSIVE or
    // DISABLE posture before live reload made the same app port STRICT.
    mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Inbound)
}

#[derive(Clone, Copy)]
struct MeshInboundPeerAuthTransportMismatch {
    pre_handshake_app_port: Option<u16>,
    resolved_app_port: u16,
    required_mode: crate::modes::mesh::config::MtlsMode,
}

fn mesh_inbound_peer_auth_transport_mismatch(
    state: &ProxyState,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    pre_handshake_app_port: Option<u16>,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
    is_tls: bool,
    has_verified_peer_certificate: bool,
) -> Option<MeshInboundPeerAuthTransportMismatch> {
    let resolved_app_port = mesh_inbound_peer_auth_app_port(proxy, upstream_target);
    if !mesh_inbound_requires_post_route_transport_gate(mesh_direction) {
        return None;
    }

    let policy = state.mesh_inbound_tls_policy.load();
    let required_mode = policy
        .modes_by_port
        .get(&resolved_app_port)
        .copied()
        .unwrap_or(policy.default_mode);
    (!mesh_inbound_transport_satisfies_mode(required_mode, is_tls, has_verified_peer_certificate))
        .then_some(MeshInboundPeerAuthTransportMismatch {
            pre_handshake_app_port,
            resolved_app_port,
            required_mode,
        })
}

#[allow(clippy::too_many_arguments)]
async fn reject_mesh_inbound_peer_auth_transport_mismatch(
    state: &ProxyState,
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    proxy: &Proxy,
    mismatch: MeshInboundPeerAuthTransportMismatch,
    is_tls: bool,
    is_grpc_request: bool,
    start_time: Instant,
    plugin_execution_ns: u64,
    log_reason: &'static str,
    request_path: Option<&str>,
) -> Response<ProxyBody> {
    warn!(
        proxy_id = %proxy.id,
        pre_handshake_app_port = ?mismatch.pre_handshake_app_port,
        resolved_app_port = mismatch.resolved_app_port,
        required_mode = ?mismatch.required_mode,
        transport_tls = is_tls,
        verified_peer_certificate = ctx.tls_client_cert_der.is_some(),
        client_ip = %ctx.client_ip,
        "Rejecting mesh inbound request because its transport does not satisfy the effective target app-port PeerAuthentication mode"
    );
    let reject = finalize_reject_response_with_after_proxy_hooks(
        plugins,
        ctx,
        StatusCode::FORBIDDEN,
        br#"{"error":"Mesh inbound transport does not satisfy PeerAuthentication for the resolved application port"}"#,
        HashMap::new(),
        is_grpc_request,
    )
    .await;
    if is_grpc_request {
        apply_grpc_reject_metadata(ctx, &reject);
    }
    log_rejected_request_with_path(
        plugins,
        ctx,
        reject.http_status.as_u16(),
        start_time,
        log_reason,
        plugin_execution_ns,
        request_path,
    )
    .await;
    record_request(state, reject.http_status.as_u16());
    build_response_from_normalized_reject(reject)
}

struct TlsConnectionMetadata {
    frontend_listen_port: Option<u16>,
    record_mesh_mtls_metric: bool,
    node_waypoint_identity: Option<Arc<NodeWaypointIdentity>>,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    /// See [`RequestConnectionMetadata::orig_dst`].
    orig_dst: Option<SocketAddr>,
    /// See [`RequestConnectionMetadata::mesh_inbound_pre_handshake_app_port`].
    mesh_inbound_pre_handshake_app_port: Option<u16>,
}

struct NodeWaypointAcceptIdentity {
    identity: Arc<NodeWaypointIdentity>,
    orig_dst: Option<SocketAddr>,
    cookie_error: Option<NodeWaypointIdentityError>,
}

struct NodeWaypointAcceptIdentityDrop {
    error: NodeWaypointIdentityError,
    cookie_error: Option<NodeWaypointIdentityError>,
}

fn resolve_node_waypoint_accept_identity(
    resolver: &NodeWaypointIdentityResolver,
    stream: &tokio::net::TcpStream,
    expected_pod_uid: Option<[u8; 16]>,
) -> Result<NodeWaypointAcceptIdentity, NodeWaypointAcceptIdentityDrop> {
    let Some(expected_pod_uid) = expected_pod_uid else {
        return resolver
            .resolve_stream(stream)
            .map(|resolved| NodeWaypointAcceptIdentity {
                identity: resolved.identity,
                orig_dst: Some(resolved.orig_dst),
                cookie_error: None,
            })
            .map_err(|error| NodeWaypointAcceptIdentityDrop {
                error,
                cookie_error: None,
            });
    };

    match resolver.resolve_stream_for_expected_pod(stream, expected_pod_uid) {
        Ok(resolved) => Ok(NodeWaypointAcceptIdentity {
            identity: resolved.identity,
            orig_dst: Some(resolved.orig_dst),
            cookie_error: None,
        }),
        Err(error) if node_waypoint_listener_uid_fallback_allowed(&error) => {
            match resolver.resolve_expected_pod_identity(expected_pod_uid) {
                Ok((identity, _scope)) => Ok(NodeWaypointAcceptIdentity {
                    identity,
                    orig_dst: None,
                    cookie_error: Some(error),
                }),
                Err(fallback_error) => Err(NodeWaypointAcceptIdentityDrop {
                    error: fallback_error,
                    cookie_error: Some(error),
                }),
            }
        }
        Err(error) => Err(NodeWaypointAcceptIdentityDrop {
            error,
            cookie_error: None,
        }),
    }
}

async fn start_proxy_listener_with_tls_source_and_signal(
    addr: SocketAddr,
    state: ProxyState,
    shutdown: tokio::sync::watch::Receiver<bool>,
    tls_source: ListenerTlsSource,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    started_tx: Option<tokio::sync::oneshot::Sender<()>>,
) -> Result<(), anyhow::Error> {
    let backlog = state.env_config.tcp_listen_backlog as i32;
    let configured_accept_threads = state.env_config.accept_threads.max(1);
    #[cfg(unix)]
    let accept_threads = configured_accept_threads;
    #[cfg(not(unix))]
    let accept_threads = {
        if configured_accept_threads > 1 {
            tracing::warn!(
                configured_accept_threads,
                "FERRUM_ACCEPT_THREADS > 1 requires SO_REUSEPORT; using one accept loop on this platform"
            );
        }
        1
    };
    let reuse_port = accept_threads > 1;
    let tfo_enabled = state
        .env_config
        .tcp_fastopen_enabled
        .resolve(crate::socket_opts::is_tcp_fastopen_available);
    let tfo_queue = if tfo_enabled {
        Some(state.env_config.tcp_fastopen_queue_len)
    } else {
        None
    };

    // Create the first listener — this one validates that the port is available.
    let first_listener = create_proxy_socket(addr, backlog, tfo_queue, reuse_port)?;

    // Optional connection limit. Shared across all accept threads so the global
    // max_connections limit is enforced regardless of which thread accepted.
    let conn_semaphore: Option<Arc<tokio::sync::Semaphore>> =
        if state.env_config.max_connections > 0 {
            info!(
                "Connection limit: {} max concurrent connections",
                state.env_config.max_connections
            );
            Some(Arc::new(tokio::sync::Semaphore::new(
                state.env_config.max_connections,
            )))
        } else {
            None
        };
    let state = Arc::new(state);

    if accept_threads > 1 {
        // Multi-listener mode: spawn N-1 additional accept loops, each with its
        // own socket bound to the same address via SO_REUSEPORT. The kernel
        // distributes connections across all N sockets.
        let mut handles = Vec::with_capacity(accept_threads);

        // Spawn additional listeners (threads 1..N-1)
        for i in 1..accept_threads {
            let listener = create_proxy_socket(addr, backlog, tfo_queue, reuse_port)?;
            let state = Arc::clone(&state);
            let tls_source = tls_source.clone();
            let semaphore = conn_semaphore.clone();
            let shutdown_rx = shutdown.clone();

            handles.push(tokio::spawn(async move {
                run_accept_loop(
                    listener,
                    state,
                    tls_source,
                    semaphore,
                    shutdown_rx,
                    mesh_direction,
                    i,
                    SourceIpOverride::none(),
                    None,
                )
                .await;
            }));
        }

        info!(
            "Proxy listener started on {} (backlog={}, accept_threads={})",
            addr, backlog, accept_threads
        );
        if let Some(started_tx) = started_tx {
            let _ = started_tx.send(());
        }

        // Run thread 0 on the current task (avoids an extra spawn)
        run_accept_loop(
            first_listener,
            state,
            tls_source,
            conn_semaphore,
            shutdown,
            mesh_direction,
            0,
            SourceIpOverride::none(),
            None,
        )
        .await;

        // When the first loop exits (shutdown), wait for others to finish
        for handle in handles {
            let _ = handle.await;
        }
    } else {
        // Single-listener mode (FERRUM_ACCEPT_THREADS=1) — no extra spawns
        info!("Proxy listener started on {} (backlog={})", addr, backlog);
        if let Some(started_tx) = started_tx {
            let _ = started_tx.send(());
        }

        run_accept_loop(
            first_listener,
            state,
            tls_source,
            conn_semaphore,
            shutdown,
            mesh_direction,
            0,
            SourceIpOverride::none(),
            None,
        )
        .await;
    }

    Ok(())
}

pub(super) enum SourceIpOverride {
    Static(Option<std::net::IpAddr>),
    Dynamic(watch::Receiver<Option<std::net::IpAddr>>),
}

impl SourceIpOverride {
    fn none() -> Self {
        Self::Static(None)
    }

    fn current(&self) -> Option<std::net::IpAddr> {
        match self {
            Self::Static(ip) => *ip,
            Self::Dynamic(rx) => *rx.borrow(),
        }
    }
}

fn select_mesh_original_dst(
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    socket_original_dst: Option<SocketAddr>,
    node_waypoint_original_dst: Option<SocketAddr>,
) -> Option<SocketAddr> {
    match mesh_direction {
        Some(crate::modes::mesh::MeshTrafficDirection::Outbound) => {
            node_waypoint_original_dst.or(socket_original_dst)
        }
        Some(crate::modes::mesh::MeshTrafficDirection::Inbound) => socket_original_dst,
        None => None,
    }
}

fn should_resolve_node_waypoint_identity(
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
) -> bool {
    mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Outbound)
}

fn should_use_direct_pod_ip_http_route(
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    has_node_waypoint_identity: bool,
) -> bool {
    mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Outbound)
        && has_node_waypoint_identity
}

/// Accept loop that runs on a single listener socket. Multiple instances can
/// run concurrently on the same address when SO_REUSEPORT is enabled.
#[allow(clippy::too_many_arguments)]
async fn run_accept_loop(
    listener: TcpListener,
    state: Arc<ProxyState>,
    tls_source: ListenerTlsSource,
    conn_semaphore: Option<Arc<tokio::sync::Semaphore>>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
    mesh_direction: Option<crate::modes::mesh::MeshTrafficDirection>,
    _thread_id: usize,
    // Overrides the accepted connection's client IP. Used by the node-waypoint
    // in-netns capture path: `connect4` rewrites a captured pod's egress to
    // loopback, so the accepted peer is 127.0.0.1; this carries the real source
    // pod IP so client-IP authz conditions, logs, and IP-keyed plugins see the
    // pod instead of loopback.
    source_ip_override: SourceIpOverride,
    node_waypoint_expected_pod_uid: Option<[u8; 16]>,
) {
    let frontend_listen_port = listener.local_addr().ok().map(|addr| addr.port());
    // Count consecutive accept() failures to back off a busy-loop. Under fd
    // exhaustion (EMFILE/ENFILE) accept() fails WITHOUT consuming the pending
    // connection or clearing the socket's read-readiness, so the next accept()
    // re-fails immediately — a CPU + log busy-loop until the descriptor table
    // drains. A single transient error (e.g. ECONNABORTED, which consumes the
    // backlog entry) must NOT be penalized, so backoff engages only on repeats.
    let mut accept_backoff = crate::util::accept_backoff::AcceptBackoff::new();
    let mut accept_err_log = crate::util::accept_backoff::LogRateLimiter::new();
    loop {
        tokio::select! {
            result = listener.accept() => {
                match result {
                    Ok((stream, remote_addr)) => {
                        // Override the loopback peer with the source pod IP for
                        // in-netns capture connections (see `source_ip_override`).
                        let remote_addr = source_ip_override
                            .current()
                            .map(|ip| std::net::SocketAddr::new(ip, remote_addr.port()))
                            .unwrap_or(remote_addr);
                        accept_backoff.on_success();
                        // Overload check: reject new connections under critical
                        // pressure. Checked after accept (inside the select!) so
                        // shutdown_rx is always observed even during sustained
                        // overload. Single atomic load (~1ns).
                        if state
                            .overload
                            .reject_new_connections
                            .load(std::sync::atomic::Ordering::Relaxed)
                        {
                            drop(stream); // TCP RST
                            continue;
                        }
                        // Acquire connection permit before spawning. This avoids
                        // creating tasks that queue on the semaphore under floods —
                        // over-limit connections are dropped immediately with zero
                        // task overhead (no spawn, no state.clone, no scheduler slot).
                        let conn_permit = if let Some(ref sem) = conn_semaphore {
                            match sem.clone().try_acquire_owned() {
                                Ok(permit) => Some(permit),
                                Err(_) => {
                                    drop(stream); // TCP RST — at capacity
                                    continue;
                                }
                            }
                        } else {
                            None
                        };

                        let state = Arc::clone(&state);
                        let mut node_waypoint_orig_dst = None;
                        let node_waypoint_identity =
                            if should_resolve_node_waypoint_identity(mesh_direction)
                                && let Some(resolver) =
                                    state.node_waypoint_identity_resolver.as_ref()
                            {
                                match resolve_node_waypoint_accept_identity(
                                    resolver,
                                    &stream,
                                    node_waypoint_expected_pod_uid,
                                ) {
                                    // HTTP/HBONE re-queries the per-pod scope
                                    // per request, so the accept-time scope is
                                    // unused here; keep only the identity and
                                    // optional original destination on the
                                    // connection metadata.
                                    Ok(resolved) => {
                                        node_waypoint_orig_dst = resolved.orig_dst;
                                        if let Some(cookie_error) = resolved.cookie_error.as_ref() {
                                            let expected_pod_uid =
                                                node_waypoint_expected_pod_uid.map(|uid| {
                                                    pod_uid_label(&uid)
                                                });
                                            info!(
                                                remote_addr = %remote_addr,
                                                expected_pod_uid = expected_pod_uid.as_deref().unwrap_or("<shared>"),
                                                error = %cookie_error,
                                                "Admitting node-waypoint in-netns connection by listener pod UID after cookie lookup miss"
                                            );
                                        }
                                        Some(resolved.identity)
                                    }
                                    Err(drop_reason) => {
                                        record_node_waypoint_identity_drop(
                                            &state.overload,
                                            &drop_reason.error,
                                        );
                                        if let Some(cookie_error) =
                                            drop_reason.cookie_error.as_ref()
                                        {
                                            let expected_pod_uid =
                                                node_waypoint_expected_pod_uid.map(|uid| {
                                                    pod_uid_label(&uid)
                                                });
                                            warn!(
                                                remote_addr = %remote_addr,
                                                expected_pod_uid = expected_pod_uid.as_deref().unwrap_or("<shared>"),
                                                cookie_error = %cookie_error,
                                                error = %drop_reason.error,
                                                "Dropping node-waypoint connection without a resolved pod identity"
                                            );
                                        } else {
                                            let expected_pod_uid =
                                                node_waypoint_expected_pod_uid.map(|uid| {
                                                    pod_uid_label(&uid)
                                                });
                                            warn!(
                                                remote_addr = %remote_addr,
                                                expected_pod_uid = expected_pod_uid.as_deref().unwrap_or("<shared>"),
                                                error = %drop_reason.error,
                                                "Dropping node-waypoint connection without a resolved pod identity"
                                            );
                                        }
                                        drop(stream);
                                        continue;
                                    }
                                }
                            } else {
                                None
                            };
                        // Read the captured connection's original destination
                        // before TLS selection. Inbound REDIRECT preserves the
                        // workload app/container port, allowing PeerAuthentication
                        // `portLevelMtls` to choose the ServerConfig before the
                        // rustls handshake begins.
                        let orig_dst = if mesh_direction.is_some() {
                            select_mesh_original_dst(
                                mesh_direction,
                                crate::socket_opts::original_dst(&stream),
                                node_waypoint_orig_dst,
                            )
                        } else {
                            None
                        };
                        let tls_selection = tls_source.load(&state, orig_dst);
                        // Defense in depth: a TLS-required source (Dynamic
                        // frontend reload slot, MeshInbound peer-auth slot)
                        // that observes a `None` payload must NOT fall
                        // through to the plaintext handler — that would be a
                        // silent TLS-to-HTTP downgrade on a port bound for
                        // TLS. Drop the connection and continue. In normal
                        // operation the slot is initialized with a live
                        // config and only ever stores `Some(..)`; this guard
                        // protects against a slot transiently or buggily
                        // holding `None`.
                        if tls_selection.tls_config.is_none() && tls_source.requires_tls() {
                            debug!(
                                remote_addr = %remote_addr.ip(),
                                "Dropping TLS connection: TLS slot is empty for a TLS-required listener (live-reload race or misconfiguration)"
                            );
                            drop(stream);
                            continue;
                        }
                        let record_mesh_mtls_metric = tls_source.record_mesh_mtls_metric();
                        // Each connection gets its own subscriber so that
                        // shutdown can interrupt the per-connection serve
                        // future (sending GOAWAY on H2 / closing keepalive
                        // on H1) instead of letting it sit idle until the
                        // drain timeout fires.
                        let conn_shutdown_rx = shutdown_rx.clone();

                        tokio::spawn(async move {
                            // Hold the permit for the connection lifetime.
                            // Released automatically when _conn_permit drops on any exit path.
                            let _conn_permit = conn_permit;

                            // Track this connection for graceful drain.
                            // The guard decrements the counter on drop (all exit paths).
                            let _conn_guard = crate::overload::ConnectionGuard::new(&state.overload);

                            // PeerAuthentication PERMISSIVE, and direct dials
                            // spanning TLS plus DISABLE app-port modes, must
                            // accept both wire protocols on one transport
                            // listener. Peek without consuming the ClientHello;
                            // exact per-port enforcement still happens after
                            // routing. Bound this pre-protocol read with the TLS
                            // handshake timeout so an idle peer cannot pin a
                            // connection indefinitely before Hyper's header
                            // timeout starts.
                            let ListenerTlsSelection {
                                mut tls_config,
                                accepts_plaintext,
                                mesh_inbound_pre_handshake_app_port,
                            } = tls_selection;
                            if tls_config.is_some() && accepts_plaintext {
                                // A captured stream-family port is an L4
                                // passthrough surface. In PERMISSIVE mode every
                                // byte sequence, including an application-level
                                // TLS ClientHello beginning with 0x16, belongs to
                                // the backend protocol and must not be consumed
                                // by the mesh HTTP TLS terminator.
                                let stream_family_passthrough = mesh_direction
                                    == Some(crate::modes::mesh::MeshTrafficDirection::Inbound)
                                    && orig_dst.is_some_and(|dst| {
                                        state
                                            .request_epoch
                                            .load()
                                            .route_table
                                            .mesh_tcp_inbound_entry(dst)
                                            .is_some()
                                    });
                                if stream_family_passthrough {
                                    tls_config = None;
                                } else {
                                    let mut first_byte = [0_u8; 1];
                                    let peek = stream.peek(&mut first_byte);
                                    let peek_result = if state
                                        .env_config
                                        .frontend_tls_handshake_timeout_seconds
                                        > 0
                                    {
                                        match tokio::time::timeout(
                                            std::time::Duration::from_secs(
                                                state
                                                    .env_config
                                                    .frontend_tls_handshake_timeout_seconds,
                                            ),
                                            peek,
                                        )
                                        .await
                                        {
                                            Ok(result) => result,
                                            Err(_) => Err(std::io::Error::from(
                                                std::io::ErrorKind::TimedOut,
                                            )),
                                        }
                                    } else {
                                        peek.await
                                    };
                                    match peek_result {
                                        Ok(0) => return,
                                        Ok(_)
                                            if !mesh_inbound_selection_uses_tls(
                                                tls_config.is_some(),
                                                accepts_plaintext,
                                                false,
                                                first_byte[0],
                                            ) =>
                                        {
                                            tls_config = None;
                                        }
                                        Ok(_) => {}
                                        Err(error) => {
                                            debug!(
                                                remote_addr = %remote_addr.ip(),
                                                %error,
                                                "Unable to classify dual-posture mesh inbound connection"
                                            );
                                            return;
                                        }
                                    }
                                }
                            }

                            // Raw-TCP mesh egress: a captured plaintext
                            // outbound connection whose original destination
                            // matches a declared (service VIP, stream-family
                            // port) pair never reaches hyper — the raw client
                            // (redis, mysql, ...) does not speak HTTP. Relay
                            // it over HBONE, or close it when the pair is
                            // mesh-owned but unroutable (never guess). All
                            // other destinations fall through unchanged.
                            if tls_config.is_none()
                                && mesh_direction
                                    == Some(crate::modes::mesh::MeshTrafficDirection::Outbound)
                                && let Some(dst) = orig_dst
                            {
                                let epoch = state.request_epoch.load();
                                // Try the VIP table first (strict `(cluster_ip,
                                // service port)`), then fall back to the
                                // direct-pod-IP / headless by-workload index
                                // (strict `(workload IP, target port)`, F3 §3.4)
                                // only when no HTTP direct-pod-IP route owns the
                                // same target. HTTP direct-pod-IP egress needs the
                                // HTTP request path for Host-independent routing
                                // and AuthorizationPolicy evaluation.
                                let http_direct_pod_ip_owner = epoch
                                    .route_table
                                    .mesh_http_egress_by_workload_decision(dst)
                                    .is_some();
                                let decision = epoch
                                    .route_table
                                    .mesh_tcp_egress_decision(dst)
                                    .or_else(|| {
                                        if http_direct_pod_ip_owner {
                                            None
                                        } else {
                                            epoch
                                                .route_table
                                                .mesh_tcp_egress_by_workload_decision(dst)
                                        }
                                    })
                                    .cloned();
                                match decision {
                                    Some(crate::router_cache::MeshTcpEgressDecision::Relay(
                                        entry,
                                    )) => {
                                        mesh_tcp_egress::handle_mesh_tcp_egress(
                                            stream,
                                            remote_addr,
                                            &state,
                                            &epoch,
                                            &entry,
                                            dst,
                                            node_waypoint_identity
                                                .as_ref()
                                                .map(|identity| &identity.spiffe_id),
                                        )
                                        .await;
                                        return;
                                    }
                                    Some(
                                        crate::router_cache::MeshTcpEgressDecision::CloseNotRoutable,
                                    ) => {
                                        // The materializer warned once per
                                        // apply with the reason; per-connection
                                        // logging stays at debug.
                                        debug!(
                                            orig_dst = %dst,
                                            client_ip = %remote_addr.ip(),
                                            "Captured raw-TCP dial targets a declared but \
                                             unroutable mesh TCP port; closing"
                                        );
                                        drop(stream);
                                        return;
                                    }
                                    None => {}
                                }
                            }

                            // Raw-TCP Sidecar inbound: when mesh inbound TLS
                            // is intentionally disabled/absent and iptables
                            // REDIRECT captures plaintext TCP for a local
                            // stream-family app port, route by the captured
                            // original destination before Hyper tries to parse
                            // Redis/MySQL/etc. bytes as HTTP.
                            if tls_config.is_none()
                                && mesh_direction
                                    == Some(crate::modes::mesh::MeshTrafficDirection::Inbound)
                                && let Some(dst) = orig_dst
                            {
                                let epoch = state.request_epoch.load();
                                if let Some(entry) = epoch.route_table.mesh_tcp_inbound_entry(dst) {
                                    mesh_tcp_inbound::handle_mesh_tcp_inbound(
                                        stream,
                                        remote_addr,
                                        &state,
                                        &epoch,
                                        &entry,
                                        dst,
                                    )
                                    .await;
                                    return;
                                }
                            }

                            let result = if let Some(tls_config) = tls_config {
                                let tls_connection_metadata = TlsConnectionMetadata {
                                    frontend_listen_port,
                                    record_mesh_mtls_metric,
                                    node_waypoint_identity,
                                    mesh_direction,
                                    orig_dst,
                                    mesh_inbound_pre_handshake_app_port,
                                };
                                handle_tls_connection(
                                    stream,
                                    remote_addr,
                                    state,
                                    tls_config,
                                    conn_shutdown_rx,
                                    tls_connection_metadata,
                                )
                                .await
                            } else {
                                handle_connection(
                                    stream,
                                    remote_addr,
                                    state,
                                    conn_shutdown_rx,
                                    frontend_listen_port,
                                    node_waypoint_identity,
                                    mesh_direction,
                                    orig_dst,
                                    mesh_inbound_pre_handshake_app_port,
                                )
                                .await
                            };

                            if let Err(e) = result {
                                debug!("Connection handling error: {}", e);
                            }
                        });
                    }
                    Err(e) => {
                        // Bound the log rate independently of the backoff: an
                        // abort/reset flood makes progress and is not backed
                        // off, so without this it could emit one error per
                        // accept. Emit the first error, then at most one
                        // summary per second carrying the suppressed count.
                        if let Some(suppressed) =
                            accept_err_log.on_event(crate::socket_opts::monotonic_now_ms())
                        {
                            error!(suppressed, "Failed to accept connection: {}", e);
                        }
                        // Back off (capped at 100ms) once accept() fails
                        // repeatedly in quick succession so fd exhaustion cannot
                        // peg a core. The brief sleep also gives the descriptor
                        // table a chance to drain. Shutdown is delayed by at
                        // most one backoff interval. Connection abort/reset
                        // floods make progress and are not throttled (see
                        // AcceptBackoff).
                        if let Some(delay) = accept_backoff.on_error(e.kind()) {
                            tokio::time::sleep(delay).await;
                        }
                    }
                }
            }
            _ = shutdown_rx.changed() => {
                info!("Proxy listener shutting down");
                return;
            }
        }
    }
}

/// Handle TLS connections with HTTP/1.1 and HTTP/2 auto-negotiation via ALPN.
///
/// On shutdown, calls `graceful_shutdown()` on the hyper connection so that
/// HTTP/2 clients receive a GOAWAY frame and HTTP/1.1 keepalive connections
/// stop accepting new requests. See [`handle_connection`] for rationale.
async fn handle_tls_connection(
    stream: tokio::net::TcpStream,
    remote_addr: SocketAddr,
    state: Arc<ProxyState>,
    tls_config: Arc<rustls::ServerConfig>,
    mut shutdown_rx: tokio::sync::watch::Receiver<bool>,
    tls_connection_metadata: TlsConnectionMetadata,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    use tokio_rustls::TlsAcceptor;

    // Set TCP keepalive on inbound connection
    set_tcp_keepalive(&stream);

    let acceptor = TlsAcceptor::from(tls_config);
    let tls_stream = crate::tls::accept_with_optional_timeout(
        &acceptor,
        stream,
        state.env_config.frontend_tls_handshake_timeout_seconds,
        &remote_addr,
        tls_connection_metadata.record_mesh_mtls_metric,
    )
    .await?;
    info!("TLS connection established from {}", remote_addr.ip());

    // Extract peer certificate and chain before wrapping the stream.
    // This is the only point where the ServerConnection is accessible — once
    // wrapped in TokioIo, the TLS metadata is encapsulated and inaccessible.
    // Arc-shared so HTTP/2 multiplexed requests avoid per-request cert cloning.
    let peer_certs = tls_stream.get_ref().1.peer_certificates();
    let client_cert_der: Option<Arc<Vec<u8>>> = peer_certs
        .and_then(|certs| certs.first())
        .map(|cert| Arc::new(cert.to_vec()));
    // Capture intermediate/CA certs (index 1+) for per-proxy CA filtering in mtls_auth.
    let client_cert_chain_der: Option<Arc<Vec<Vec<u8>>>> = peer_certs
        .filter(|certs| certs.len() > 1)
        .map(|certs| Arc::new(certs[1..].iter().map(|c| c.to_vec()).collect()));
    let mtls_auth_connection_cache = client_cert_der
        .as_ref()
        .map(|_| Arc::new(crate::plugins::mtls_auth::MtlsAuthConnectionCache::new()));
    // Connection-scoped SPIFFE extraction cache: the peer cert is fixed for
    // the connection, so `spiffe_identity` derives its outcome once and every
    // multiplexed request reuses it without re-parsing the DER.
    let peer_spiffe_extraction_cache = client_cert_der.as_ref().map(|_| {
        Arc::new(crate::plugins::mesh::spiffe_identity::SpiffeIdentityConnectionCache::new())
    });
    let frontend_sni_hostname = tls_stream
        .get_ref()
        .1
        .server_name()
        .map(str::to_ascii_lowercase);

    // Convert TLS stream to TokioIo for hyper
    let io = hyper_util::rt::TokioIo::new(tls_stream);

    // Use hyper-util's auto builder which negotiates HTTP/1.1 or HTTP/2 via ALPN.
    // HTTP/2 clients get multiplexed streams; HTTP/1.1 clients get upgrade support.
    let mut builder =
        hyper_util::server::conn::auto::Builder::new(hyper_util::rt::TokioExecutor::new());
    {
        let mut http1 = builder.http1();
        http1.max_buf_size(http1_parser_max_buf_size(state.max_header_size_bytes));
        http1.writev(true);
        // Slowloris protection: close connections that take too long to send headers.
        if state.env_config.http_header_read_timeout_seconds > 0 {
            http1.timer(hyper_util::rt::TokioTimer::new());
            http1.header_read_timeout(std::time::Duration::from_secs(
                state.env_config.http_header_read_timeout_seconds,
            ));
        }
    }
    builder
        .http2()
        .max_header_list_size(h2_parser_max_header_list_size(state.max_header_size_bytes))
        .initial_stream_window_size(state.env_config.frontend_h2_initial_stream_window_size)
        .initial_connection_window_size(state.env_config.frontend_h2_initial_connection_window_size)
        .adaptive_window(false)
        .max_frame_size(state.env_config.frontend_h2_max_frame_size)
        .max_concurrent_streams(state.env_config.server_http2_max_concurrent_streams)
        .max_pending_accept_reset_streams(Some(
            state
                .env_config
                .server_http2_max_pending_accept_reset_streams,
        ))
        .max_local_error_reset_streams(Some(
            state.env_config.server_http2_max_local_error_reset_streams,
        ))
        // RFC 8441: Advertise SETTINGS_ENABLE_CONNECT_PROTOCOL so HTTP/2 clients
        // can initiate WebSocket connections via Extended CONNECT.
        .enable_connect_protocol();

    // WebSocket requests flow through handle_proxy_request so that authentication
    // and authorization plugins execute before the upgrade handshake.
    let svc = service_fn(move |req: hyper::Request<hyper::body::Incoming>| {
        let state = Arc::clone(&state);
        let addr = remote_addr;
        let cert = client_cert_der.clone();
        let chain = client_cert_chain_der.clone();
        let mtls_auth_connection_cache = mtls_auth_connection_cache.clone();
        let frontend_sni_hostname = frontend_sni_hostname.clone();
        let connection_metadata = RequestConnectionMetadata {
            frontend_listen_port: tls_connection_metadata.frontend_listen_port,
            frontend_sni_hostname,
            node_waypoint_identity: tls_connection_metadata.node_waypoint_identity.clone(),
            mesh_direction: tls_connection_metadata.mesh_direction,
            orig_dst: tls_connection_metadata.orig_dst,
            mesh_inbound_pre_handshake_app_port: tls_connection_metadata
                .mesh_inbound_pre_handshake_app_port,
            peer_spiffe_extraction_cache: peer_spiffe_extraction_cache.clone(),
        };
        async move {
            handle_proxy_request_on_frontend_port(
                req,
                state,
                addr,
                true,
                cert,
                chain,
                mtls_auth_connection_cache,
                connection_metadata,
            )
            .await
        }
    });

    let conn = builder.serve_connection_with_upgrades(io, svc);
    tokio::pin!(conn);

    let result = tokio::select! {
        biased;
        res = conn.as_mut() => res,
        _ = shutdown_rx.changed() => {
            // Send GOAWAY (H2) / signal end-of-keepalive (H1) and wait for
            // in-flight requests to complete on this connection.
            conn.as_mut().graceful_shutdown();
            conn.as_mut().await
        }
    };

    if let Err(e) = result {
        let err_string = e.to_string();
        if is_client_disconnect_error(&err_string) {
            debug!(
                remote_addr = %remote_addr.ip(),
                error_kind = "client_disconnect",
                error = %e,
                "Client disconnected before response completed (TLS)"
            );
        } else {
            error!(
                remote_addr = %remote_addr.ip(),
                error = %e,
                "HTTP connection error over TLS"
            );
        }
    }

    Ok(())
}

/// Run logging plugins for a rejected request.
///
/// When a plugin (auth, access control, rate limiting, etc.) rejects a request,
/// logging plugins (stdout_logging, http_logging, transaction_debugger) must still
/// execute so that rejected traffic is visible in log sinks like Splunk, stdout, etc.
/// Plugins outside the logging priority band (e.g., `otel_tracing` at priority 25)
/// also implement `log()` and must receive rejected transactions — so we dispatch
/// to the full plugin chain. The default `.log()` impl is a no-op, so awaiting
/// plugins that don't override it is cheap.
pub async fn log_rejected_request(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    status_code: u16,
    start_time: Instant,
    rejection_phase: &str,
    plugin_execution_ns: u64,
) {
    log_rejected_request_with_path_and_backend_state(
        plugins,
        ctx,
        status_code,
        start_time,
        rejection_phase,
        plugin_execution_ns,
        None,
        true,
    )
    .await;
}

/// Run logging plugins for a rejection that occurred before backend contact.
///
/// The summary retains matched-proxy attribution but deliberately omits
/// `backend_target`: configuration identifies where a request might have gone,
/// not a destination that Ferrum actually contacted.
pub async fn log_pre_backend_rejected_request(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    status_code: u16,
    start_time: Instant,
    rejection_phase: &str,
    plugin_execution_ns: u64,
) {
    log_rejected_request_with_path_and_backend_state(
        plugins,
        ctx,
        status_code,
        start_time,
        rejection_phase,
        plugin_execution_ns,
        None,
        false,
    )
    .await;
}

/// Like [`log_rejected_request`] but allows the caller to supply the
/// original client-requested path when `ctx.path` has already been rebased
/// to the VirtualService-rewritten backend path. When `request_path_override`
/// is `Some`, it is recorded as `TransactionSummary.request_path` instead of
/// `ctx.path`; `ctx.path` (the rewritten value) is still used for
/// `backend_target` URL construction. Pass `None` at all sites that fire
/// before the rewrite — they get the same behavior as `log_rejected_request`.
pub(crate) async fn log_rejected_request_with_path(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    status_code: u16,
    start_time: Instant,
    rejection_phase: &str,
    plugin_execution_ns: u64,
    request_path_override: Option<&str>,
) {
    log_rejected_request_with_path_and_backend_state(
        plugins,
        ctx,
        status_code,
        start_time,
        rejection_phase,
        plugin_execution_ns,
        request_path_override,
        true,
    )
    .await;
}

#[allow(clippy::too_many_arguments)]
async fn log_rejected_request_with_path_and_backend_state(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
    status_code: u16,
    start_time: Instant,
    rejection_phase: &str,
    plugin_execution_ns: u64,
    request_path_override: Option<&str>,
    include_backend_target: bool,
) {
    if plugins.is_empty() {
        return;
    }

    let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
    // Fold in the reject-path `after_proxy` + synthetic response-body hook time
    // recorded by `finalize_reject_response_with_after_proxy_hooks` (0 on the H3
    // path, which times those hooks inline) so synthetic-guardrail latency is
    // reported as plugin execution rather than gateway overhead.
    let plugin_execution_ns =
        plugin_execution_ns + ctx.reject_hook_execution_ns.load(Ordering::Relaxed);
    let plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
    let plugin_external_io_ms =
        ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
    let gateway_overhead_ms = (total_ms - plugin_execution_ms).max(0.0);
    let proxy = ctx.matched_proxy.as_ref();

    let mut metadata = clone_log_metadata(ctx);
    metadata.insert("rejection_phase".to_string(), rejection_phase.to_string());

    // Uses `..TransactionSummary::default()` for the boilerplate tail
    // (body-streaming counters, booleans, `error_class`, `mirror`). Future
    // additions to `TransactionSummary` get a sane default here without
    // touching this call site — same pattern new log sites should follow.
    // Request bytes: plugin rejects can fire before or after the body has
    // been observed. If a plugin that buffers the body (e.g. body_validator)
    // rejected, the counter is populated. For pre-body rejects (auth, rate
    // limit) the counter is 0, which the serializer correctly omits.
    let bytes_sent = ctx
        .bytes_sent_observed
        .load(std::sync::atomic::Ordering::Acquire);
    let summary = TransactionSummary {
        namespace: proxy
            .map(|p| p.namespace.clone())
            .unwrap_or_else(crate::config::types::default_namespace),
        timestamp_received: ctx.timestamp_received.to_rfc3339(),
        client_ip: ctx.client_ip.clone(),
        consumer_username: ctx.effective_identity().map(str::to_owned),
        auth_method: ctx.auth_method,
        http_method: ctx.method.clone(),
        // Use the caller-supplied original path when provided; otherwise fall
        // back to `ctx.path`, which may be the rewritten backend path if the
        // caller is after a VirtualService `rewrite.uri` application.
        request_path: request_path_override
            .map(str::to_owned)
            .unwrap_or_else(|| ctx.path.clone()),
        proxy_id: proxy.map(|p| p.id.clone()),
        proxy_name: proxy.and_then(|p| p.name.clone()),
        backend_target: if include_backend_target {
            proxy.map(|p| {
                // Host-only proxies (listen_path None) have no prefix to strip.
                // `ctx.path` is intentionally used here (not the override) because
                // `backend_target` should reflect the rewritten path that would
                // have been sent to the backend.
                let strip_len = p.listen_path.as_deref().map(str::len).unwrap_or(0);
                let url = build_backend_url(p, &ctx.path, "", strip_len);
                strip_query_params(&url).to_string()
            })
        } else {
            None
        },
        response_status_code: status_code,
        latency_total_ms: total_ms,
        latency_gateway_processing_ms: total_ms,
        latency_backend_ttfb_ms: -1.0,
        latency_backend_total_ms: -1.0,
        latency_plugin_execution_ms: plugin_execution_ms,
        latency_plugin_external_io_ms: plugin_external_io_ms,
        latency_gateway_overhead_ms: gateway_overhead_ms,
        request_user_agent: ctx.headers.get("user-agent").cloned(),
        bytes_sent,
        // Response body for rejection responses is built by
        // `reject_result_to_backend_response` / admin reject paths and is
        // not visible here. The outer caller sends the rejection JSON; it
        // is typically small and flowing through the main handler's buffered
        // arm, which populates `bytes_received` separately. Leave 0 here.
        metadata,
        ai_usage_export: ctx.ai_usage_export.clone(),
        proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
        ..TransactionSummary::default()
    };

    crate::plugins::log_with_mirror_before_buffered_response(plugins, summary, ctx).await;
}

fn replace_rejection_with_gateway_deadline(
    ctx: &mut RequestContext,
    status_code: &mut u16,
    response_body: Option<&mut Vec<u8>>,
    response_headers: &mut HashMap<String, String>,
) {
    *status_code = StatusCode::OK.as_u16();
    if let Some(body) = response_body {
        body.clear();
    }
    ctx.retain_deadline_response_gateway_headers(response_headers);
    grpc_proxy::finalize_grpc_error_response_headers(
        response_headers,
        grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
        GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
        &[],
    );
    ctx.sync_deadline_response_terminal_headers(response_headers);
}

const DETACHED_REJECTION_CLEANUP_TIMEOUT: Duration = Duration::from_secs(5);

struct OwnedRejectionHookResult {
    ctx: RequestContext,
    status_code: u16,
    response_body: Option<Vec<u8>>,
    response_headers: HashMap<String, String>,
    result: PluginResult,
}

type OwnedRejectionHookFuture =
    std::pin::Pin<Box<dyn std::future::Future<Output = OwnedRejectionHookResult> + Send + 'static>>;

fn owned_rejection_hook_future(
    plugin: Arc<dyn Plugin>,
    mut ctx: RequestContext,
    status_code: u16,
    response_body: Option<Vec<u8>>,
    mut response_headers: HashMap<String, String>,
) -> OwnedRejectionHookFuture {
    Box::pin(async move {
        let result = plugin
            .after_proxy(&mut ctx, status_code, &mut response_headers)
            .await;
        OwnedRejectionHookResult {
            ctx,
            status_code,
            response_body,
            response_headers,
            result,
        }
    })
}

async fn poll_owned_rejection_hook_once(
    future: &mut OwnedRejectionHookFuture,
) -> Option<OwnedRejectionHookResult> {
    futures_util::future::poll_fn(|cx| {
        Poll::Ready(match std::future::Future::poll(future.as_mut(), cx) {
            Poll::Ready(result) => Some(result),
            Poll::Pending => None,
        })
    })
    .await
}

fn adopt_owned_rejection_hook_result(
    outcome: OwnedRejectionHookResult,
    ctx: &mut RequestContext,
    status_code: &mut u16,
    response_body: &mut Option<&mut Vec<u8>>,
    response_headers: &mut HashMap<String, String>,
) -> PluginResult {
    *ctx = outcome.ctx;
    *status_code = outcome.status_code;
    if let (Some(body), Some(owned_body)) = (response_body.as_deref_mut(), outcome.response_body) {
        *body = owned_body;
    }
    *response_headers = outcome.response_headers;
    outcome.result
}

fn restore_rejection_response_markers(
    ctx: &mut RequestContext,
    previous_marker: Option<String>,
    previous_replaceable_marker: Option<String>,
) {
    if let Some(previous_marker) = previous_marker {
        ctx.metadata
            .insert(REJECTION_RESPONSE_METADATA_KEY.to_string(), previous_marker);
    } else {
        ctx.metadata.remove(REJECTION_RESPONSE_METADATA_KEY);
    }
    if let Some(previous_marker) = previous_replaceable_marker {
        ctx.metadata.insert(
            REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY.to_string(),
            previous_marker,
        );
    } else {
        ctx.metadata
            .remove(REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY);
    }
}

fn spawn_detached_rejection_cleanup(
    pending_hook: OwnedRejectionHookFuture,
    remaining_plugins: Vec<Arc<dyn Plugin>>,
    previous_marker: Option<String>,
    previous_replaceable_marker: Option<String>,
) {
    std::mem::drop(tokio::spawn(async move {
        let cleanup = async move {
            let OwnedRejectionHookResult {
                mut ctx,
                mut status_code,
                mut response_body,
                mut response_headers,
                result: _,
            } = pending_hook.await;
            ctx.mark_gateway_deadline_response_selected();
            replace_rejection_with_gateway_deadline(
                &mut ctx,
                &mut status_code,
                response_body.as_mut(),
                &mut response_headers,
            );
            for plugin in remaining_plugins {
                if plugin.may_replace_rejection_response() {
                    continue;
                }
                let _ = plugin
                    .after_proxy(&mut ctx, status_code, &mut response_headers)
                    .await;
            }
            restore_rejection_response_markers(
                &mut ctx,
                previous_marker,
                previous_replaceable_marker,
            );
        };
        if tokio::time::timeout(DETACHED_REJECTION_CLEANUP_TIMEOUT, cleanup)
            .await
            .is_err()
        {
            warn!(
                timeout_seconds = DETACHED_REJECTION_CLEANUP_TIMEOUT.as_secs(),
                "detached rejection cleanup exceeded its post-response bound"
            );
        }
    }));
}

async fn run_after_proxy_hooks_on_rejection(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status_code: &mut u16,
    mut response_body: Option<&mut Vec<u8>>,
    response_headers: &mut HashMap<String, String>,
) {
    ctx.begin_rejection_deadline_response_header_provenance(response_headers);
    let previous_replaceable_marker = if response_body.is_some() {
        ctx.metadata.insert(
            REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        )
    } else {
        ctx.metadata
            .remove(REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY)
    };
    let previous_marker = ctx.metadata.insert(
        REJECTION_RESPONSE_METADATA_KEY.to_string(),
        "true".to_string(),
    );
    let deadline_already_elapsed = ctx
        .grpc_deadline_at()
        .is_some_and(|deadline| deadline <= tokio::time::Instant::now());
    let initial_terminal_gateway_deadline =
        ctx.gateway_deadline_response_selected() || deadline_already_elapsed;
    if initial_terminal_gateway_deadline {
        ctx.mark_gateway_deadline_response_selected();
        replace_rejection_with_gateway_deadline(
            ctx,
            status_code,
            response_body.as_deref_mut(),
            response_headers,
        );
    }
    for (index, plugin) in plugins.iter().enumerate() {
        if !plugin.applies_after_proxy_on_reject() {
            continue;
        }
        let terminal_gateway_deadline = ctx.gateway_deadline_response_selected()
            || ctx
                .grpc_deadline_at()
                .is_some_and(|deadline| deadline <= tokio::time::Instant::now());
        if terminal_gateway_deadline {
            ctx.mark_gateway_deadline_response_selected();
            replace_rejection_with_gateway_deadline(
                ctx,
                status_code,
                response_body.as_deref_mut(),
                response_headers,
            );
        }
        // Once an earlier phase has selected the canonical client-deadline
        // response, give non-replacing decorators and cleanup hooks one
        // immediate poll. Pending work continues in order on owned state under
        // the detached cleanup bound and cannot retain the response writer.
        // Response-replacing hooks are skipped after the terminal deadline is
        // selected: an already-ready replacer must never overwrite
        // DEADLINE_EXCEEDED at the boundary.
        if terminal_gateway_deadline && plugin.may_replace_rejection_response() {
            continue;
        }
        let result = if terminal_gateway_deadline {
            let mut future = owned_rejection_hook_future(
                Arc::clone(plugin),
                ctx.clone(),
                *status_code,
                response_body.as_deref().cloned(),
                response_headers.clone(),
            );
            match poll_owned_rejection_hook_once(&mut future).await {
                Some(outcome) => adopt_owned_rejection_hook_result(
                    outcome,
                    ctx,
                    status_code,
                    &mut response_body,
                    response_headers,
                ),
                None => {
                    spawn_detached_rejection_cleanup(
                        future,
                        plugins[index + 1..]
                            .iter()
                            .filter(|plugin| plugin.applies_after_proxy_on_reject())
                            .cloned()
                            .collect(),
                        previous_marker.clone(),
                        previous_replaceable_marker.clone(),
                    );
                    restore_rejection_response_markers(
                        ctx,
                        previous_marker,
                        previous_replaceable_marker,
                    );
                    return;
                }
            }
        } else if let Some(deadline) = ctx.grpc_deadline_at() {
            let mut future = owned_rejection_hook_future(
                Arc::clone(plugin),
                ctx.clone(),
                *status_code,
                response_body.as_deref().cloned(),
                response_headers.clone(),
            );
            let deadline_sleep = tokio::time::sleep_until(deadline);
            tokio::pin!(deadline_sleep);
            tokio::select! {
                biased;
                () = &mut deadline_sleep => {
                    ctx.mark_gateway_deadline_response_selected();
                    replace_rejection_with_gateway_deadline(
                        ctx,
                        status_code,
                        response_body.as_deref_mut(),
                        response_headers,
                    );
                    spawn_detached_rejection_cleanup(
                        future,
                        plugins[index + 1..]
                            .iter()
                            .filter(|plugin| plugin.applies_after_proxy_on_reject())
                            .cloned()
                            .collect(),
                        previous_marker.clone(),
                        previous_replaceable_marker.clone(),
                    );
                    restore_rejection_response_markers(
                        ctx,
                        previous_marker,
                        previous_replaceable_marker,
                    );
                    return;
                }
                outcome = &mut future => adopt_owned_rejection_hook_result(
                    outcome,
                    ctx,
                    status_code,
                    &mut response_body,
                    response_headers,
                ),
            }
        } else {
            plugin
                .after_proxy(ctx, *status_code, response_headers)
                .await
        };
        if terminal_gateway_deadline {
            ctx.mark_gateway_deadline_response_selected();
        }
        if matches!(&result, PluginResult::Continue) || !plugin.may_replace_rejection_response() {
            ctx.record_deadline_response_header_plugin(plugin.as_ref(), response_headers);
        }
        match result {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let Some(reject) = plugin_result_into_reject_parts(reject) else {
                    warn!(
                        rejecting_plugin = plugin.name(),
                        "after_proxy rejection could not be normalized"
                    );
                    continue;
                };
                let reject_status = reject.status_code;
                if plugin.may_replace_rejection_response()
                    && let Some(body) = response_body.as_deref_mut()
                {
                    let replaced_status = *status_code;
                    *status_code = reject.status_code;
                    *body = reject.body;
                    // Keep headers already attached by earlier decorators (for
                    // example CORS and correlation IDs), but discard metadata
                    // describing the representation that is being replaced.
                    // Explicit replacement headers below then define the new
                    // body and win over any retained decorator header.
                    let preserve_origin_vary = response_headers.get("vary").is_some_and(|value| {
                        value
                            .split(',')
                            .any(|token| token.trim().eq_ignore_ascii_case("origin"))
                    });
                    for header in [
                        "content-length",
                        "content-encoding",
                        "content-range",
                        "content-md5",
                        "digest",
                        "content-digest",
                        "repr-digest",
                        "etag",
                        "last-modified",
                        "cache-control",
                        "cdn-cache-control",
                        "surrogate-control",
                        "expires",
                        "age",
                        "pragma",
                        "vary",
                        "warning",
                    ] {
                        response_headers.remove(header);
                    }
                    response_headers.extend(reject.headers);
                    if preserve_origin_vary {
                        response_headers
                            .entry("vary".to_string())
                            .and_modify(|value| {
                                if !value
                                    .split(',')
                                    .any(|token| token.trim().eq_ignore_ascii_case("origin"))
                                {
                                    value.push_str(", Origin");
                                }
                            })
                            .or_insert_with(|| "Origin".to_string());
                    }
                    ctx.record_deadline_response_header_mutations(response_headers);
                    if plugin.warn_on_rejection_response_replacement() {
                        warn!(
                            rejecting_plugin = plugin.name(),
                            replacement_status = *status_code,
                            replaced_status,
                            "after_proxy plugin replaced an uncommitted rejection response"
                        );
                    } else {
                        debug!(
                            replacing_plugin = plugin.name(),
                            replacement_status = *status_code,
                            replaced_status,
                            "after_proxy plugin normalized an uncommitted rejection response"
                        );
                    }
                    continue;
                }
                // The gateway is already committed to emitting this rejection
                // response (the status/body are fixed by the time after-proxy-on-
                // reject hooks run), so a hook cannot replace it here — it is
                // ignored and only logged. Known consequence: `ai_rate_limiter`'s
                // `on_unmetered_response: "reject"` is best-effort for synthetic
                // responses such as `ai_federation`'s final-request-body
                // short-circuit — a federated 2xx missing usage metadata is still
                // returned to the client. See docs/plugins.md (ai_rate_limiter
                // federation limitation).
                warn!(
                    rejecting_plugin = plugin.name(),
                    attempted_reject_status = reject_status,
                    committed_status = *status_code,
                    "after_proxy plugin returned Reject during rejection handling; \
                     ignoring (response already committed)"
                );
            }
        }
    }

    if ctx.gateway_deadline_response_selected()
        || ctx
            .grpc_deadline_at()
            .is_some_and(|deadline| deadline <= tokio::time::Instant::now())
    {
        ctx.mark_gateway_deadline_response_selected();
        replace_rejection_with_gateway_deadline(ctx, status_code, response_body, response_headers);
    }

    restore_rejection_response_markers(ctx, previous_marker, previous_replaceable_marker);
}

pub(crate) async fn apply_replaceable_after_proxy_hooks_to_rejection(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status_code: &mut u16,
    response_body: &mut Vec<u8>,
    response_headers: &mut HashMap<String, String>,
) {
    run_after_proxy_hooks_on_rejection(
        plugins,
        ctx,
        status_code,
        Some(response_body),
        response_headers,
    )
    .await;
}

/// Rebuild `response_status` / `response_headers` for a plugin rejection
/// **without** running the `after_proxy` reject hooks, returning the rejection
/// body. This is the header/body half of [`apply_plugin_rejection_response`],
/// split out so the synthetic-response-body-hook path can replace the response
/// for a body rejection while deferring the `after_proxy` reject hooks to a
/// single application point (see
/// [`apply_reject_after_proxy_and_synthetic_body_hooks`]).
///
/// Deferring matters because several reject-path `after_proxy` hooks consume
/// one-shot state on their first invocation — `oidc_relying_party` does
/// `ctx.metadata.remove(SESSION_SET_COOKIE_METADATA_KEY)` to stage the rotated
/// session cookie, and `response_transformer` does
/// `ctx.route_override_response_transform.take()`. If `after_proxy` ran once
/// over the synthetic 2xx and then again here (after `response_headers.clear()`),
/// that one-shot state would already be gone and could not be re-applied to the
/// rejection response, silently dropping the rotated cookie / route overrides.
fn rebuild_plugin_rejection_response_headers(
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    reject: RejectedResponseParts,
) -> Vec<u8> {
    *response_status = reject.status_code;
    response_headers.clear();
    response_headers.insert("content-type".to_string(), "application/json".to_string());
    for (key, value) in reject.headers {
        response_headers.insert(key, value);
    }
    reject.body
}

pub(crate) async fn apply_plugin_rejection_response(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    reject: RejectedResponseParts,
) -> Vec<u8> {
    let mut body =
        rebuild_plugin_rejection_response_headers(response_status, response_headers, reject);
    apply_replaceable_after_proxy_hooks_to_rejection(
        plugins,
        ctx,
        response_status,
        &mut body,
        response_headers,
    )
    .await;
    body
}

/// Decide whether response-body guardrails / transforms should run over a
/// synthetic plugin short-circuit body. This includes ordinary successful
/// synthetic responses (e.g. `ai_federation` / `ai_semantic_cache` surfaced via
/// `RejectBinary{200}`) and every final 2xx-5xx terminate-mode serverless
/// response, which is application-owned content rather than a gateway error.
///
/// General rule: these hooks (`on_response_body`,
/// `transform_response_body_with_context`, `on_final_response_body`) run over a
/// governed short-circuit body **only** when there is a body to inspect and the
/// same response-body-buffering capability gate the normal response path uses
/// is satisfied. Specifically we skip when:
/// - the request is gRPC (synthetic gRPC bodies are handled as trailers-only),
/// - the status is neither 2xx nor a marked final serverless response,
/// - the status is 204, 205, or 304 (a body-emitting transform there is
///   protocol-incorrect),
/// - the synthetic body is empty (nothing to inspect/transform), or
/// - no active plugin wants to buffer this response. We mirror the normal
///   response path's two-tier gate exactly: a plugin's per-request
///   `should_buffer_response_body(ctx)` is only consulted when that plugin
///   advertised the config-time `requires_response_body_buffering()` capability
///   upper bound (the documented precondition on
///   [`Plugin::should_buffer_response_body`], and the same ordering
///   [`should_stream_response_body`] uses). This both honors the capability
///   contract and keeps preflight/mock-heavy proxies from paying three extra
///   async plugin sweeps per request.
///
/// Empty 200 and 204/205 successes still finalize through
/// [`apply_reject_after_proxy_and_synthetic_body_hooks`], which records
/// [`FINALIZED_SYNTHETIC_RESPONSE_METADATA_KEY`] so ownership plugins can
/// release in-flight markers from `on_response_committed` without depending on
/// this body-hook gate.
///
/// [`Plugin::should_buffer_response_body`]: crate::plugins::Plugin::should_buffer_response_body
fn should_apply_synthetic_response_body_hooks(
    status_code: u16,
    is_grpc_request: bool,
    response_body: &[u8],
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
) -> bool {
    let governed_synthetic_status = (200..300).contains(&status_code)
        || (ctx.serverless_terminate_response && (200..=599).contains(&status_code));
    !is_grpc_request
        && governed_synthetic_status
        && !crate::plugins::utils::synthetic_response::status_forbids_response_body(status_code)
        && !response_body.is_empty()
        && response_body_plugins_process_body(plugins, ctx)
}

/// Whether a response-body-capable plugin phase actually processes THIS
/// response.
///
/// The two-tier gate every buffered response path uses: a plugin's per-request
/// `should_buffer_response_body(ctx)` refinement is consulted only when that
/// plugin advertised the config-time `requires_response_body_buffering()`
/// upper bound (the documented precondition on
/// [`Plugin::should_buffer_response_body`]).
///
/// Callers use this to answer "did the response-body pipeline see these
/// bytes?" — notably the buffered native-H3 path, which must drop backend
/// trailers a body-inspecting plugin could not see, while an auth/logging-only
/// chain keeps them (issue #2941).
///
/// [`Plugin::should_buffer_response_body`]: crate::plugins::Plugin::should_buffer_response_body
pub(crate) fn response_body_plugins_process_body(
    plugins: &[Arc<dyn Plugin>],
    ctx: &RequestContext,
) -> bool {
    plugins.iter().any(|plugin| {
        plugin.requires_response_body_buffering() && plugin.should_buffer_response_body(ctx)
    })
}

/// Run the governed synthetic short-circuit response-body hook pipeline
/// (`on_response_body`, `transform_response_body_with_context`,
/// `on_final_response_body`) over a plugin-generated body, replacing the
/// response when a body guardrail rejects it.
///
/// A body rejection here rebuilds the response headers via
/// [`rebuild_plugin_rejection_response_headers`] — it deliberately does **not**
/// run the `after_proxy` reject hooks. The caller
/// ([`apply_reject_after_proxy_and_synthetic_body_hooks`]) runs those hooks
/// exactly once after this function returns, over whatever the final response
/// turned out to be (the synthetic response or the body-rejection response), so
/// one-shot `after_proxy` response state (e.g. the `oidc_relying_party` rotated
/// session cookie, `response_transformer` route overrides) lands on the final
/// response exactly once instead of being consumed by an earlier pass and lost
/// when this path replaces the response.
pub(crate) async fn apply_synthetic_response_body_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
) {
    // Mark the context for the duration of this body-hook phase so that storing
    // plugins (e.g. `request_deduplication`) can tell this body is a synthetic
    // plugin short-circuit and skip caching/replaying it. Saved/restored so a
    // pre-existing value is preserved and the marker never leaks past this phase.
    let previous_synthetic_marker = ctx.metadata.insert(
        SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY.to_string(),
        "true".to_string(),
    );

    // Once a response-body phase selects a gateway-authored terminal response,
    // later final-body validators must not inspect that error payload and replace
    // the original policy decision with a second rejection. Presentation and
    // protocol transforms still run below so the selected response keeps the
    // correct client wire shape.
    let mut terminal_body_response_selected = false;
    let mut response_body_reject = None;
    for plugin in plugins.iter() {
        let deadline = ctx.grpc_deadline_at();
        let result = crate::plugins::await_request_plugin_deadline_with_provenance(
            deadline,
            plugin.on_response_body(ctx, *response_status, response_headers, response_body),
        )
        .await
        .into_plugin_result(ctx);
        match result {
            PluginResult::Continue => {
                // Inspect-phase header mutations (e.g. ai_rate_limiter
                // refreshing usage/remaining after reconcile) must enter
                // deadline provenance the same way after_proxy mutations do.
                ctx.record_deadline_response_header_plugin(plugin.as_ref(), response_headers);
            }
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let reject = plugin_result_into_reject_parts(reject)
                    .expect("reject result should convert to rejection parts");
                debug!(
                    plugin = plugin.name(),
                    status_code = reject.status_code,
                    "Plugin rejected synthetic response body"
                );
                response_body_reject = Some(reject);
                break;
            }
        }
    }
    if let Some(reject) = response_body_reject {
        // Rebuild headers/body only; the after_proxy reject hooks run once in
        // the caller so one-shot response state survives this replacement.
        *response_body =
            rebuild_plugin_rejection_response_headers(response_status, response_headers, reject);
        terminal_body_response_selected = true;
    }

    // Same shared representation gate as every backend path. The bytes here were
    // produced by the gateway (plugin short-circuit, mock, semantic-cache hit,
    // serverless terminate, dedup replay), so there is no upstream snapshot and
    // no hidden origin coding — the live headers are the only description of
    // these bytes, and `GatewayGenerated` reads them directly.
    let owned_grpc_web_response_content_type =
        crate::plugins::grpc_web::retained_response_content_type(ctx).map(str::to_owned);
    let grpc_web_response_content_type = owned_grpc_web_response_content_type.as_deref();
    // `false`: the reject `after_proxy` hooks are deliberately deferred on this
    // path and applied exactly once by
    // `apply_reject_after_proxy_and_synthetic_body_hooks` over the final
    // response, so running them here would consume one-shot response state twice.
    let admission = admit_buffered_response_body_transforms(
        plugins,
        ctx,
        crate::plugins::response_representation::RepresentationOrigin::GatewayGenerated,
        response_status,
        response_headers,
        response_body,
        grpc_web_response_content_type,
        InitialResponseHeaderPolicySource::ProtocolPlugins(plugins),
        false,
    )
    .await;
    terminal_body_response_selected |= matches!(admission, BufferedTransformAdmission::Rejected);
    // Read after the gate: a decoded body installs fresh representation headers.
    let content_type = response_headers.get("content-type").cloned();
    let ct_ref = content_type.as_deref();
    if matches!(
        admission,
        BufferedTransformAdmission::Proceed {
            rewrite_allowed: true,
            ..
        }
    ) {
        let mut mandatory_replay_transform_failed = None;
        for plugin in plugins.iter() {
            let mandatory_replay_transform = ctx.finalized_response_replay
                && plugin.requires_replay_response_body_transform(ctx);
            if ctx.finalized_response_replay && !mandatory_replay_transform {
                continue;
            }
            let deadline = ctx.grpc_deadline_at();
            let transformed = match crate::plugins::await_grpc_deadline(
                deadline,
                plugin.transform_response_body_with_context(
                    ctx,
                    response_body,
                    ct_ref,
                    response_headers,
                ),
            )
            .await
            {
                Ok(transformed) => transformed,
                Err(()) if mandatory_replay_transform => {
                    mandatory_replay_transform_failed = Some(plugin.name());
                    break;
                }
                Err(()) => break,
            };
            if let Some(transformed) = transformed {
                response_headers
                    .insert("content-length".to_string(), transformed.len().to_string());
                *response_body = transformed;
                crate::plugins::finalize_response_body_transformation(
                    plugin.as_ref(),
                    ctx,
                    response_headers,
                );
            } else if mandatory_replay_transform {
                mandatory_replay_transform_failed = Some(plugin.name());
                break;
            } else {
                if crate::plugins::compression::reconcile_aborted_gateway_response_encoding(
                    ctx,
                    response_status,
                    response_headers,
                    response_body,
                ) {
                    terminal_body_response_selected = true;
                    break;
                }
            }
        }
        if let Some(plugin_name) = mandatory_replay_transform_failed {
            warn!(
                plugin = plugin_name,
                "Mandatory replay response redaction transform failed; rejecting response"
            );
            *response_body = rebuild_plugin_rejection_response_headers(
                response_status,
                response_headers,
                RejectedResponseParts {
                    status_code: 502,
                    body: br#"{"error":"response redaction failed"}"#.to_vec(),
                    headers: HashMap::new(),
                },
            );
            terminal_body_response_selected = true;
        }
    }

    if !terminal_body_response_selected {
        let mut response_body_reject = None;
        for plugin in plugins.iter() {
            let deadline = ctx.grpc_deadline_at();
            let result = crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.on_final_response_body(
                    ctx,
                    *response_status,
                    response_headers,
                    response_body,
                ),
            )
            .await
            .into_plugin_result(ctx);
            match result {
                PluginResult::Continue => {}
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let reject = plugin_result_into_reject_parts(reject)
                        .expect("reject result should convert to rejection parts");
                    debug!(
                        plugin = plugin.name(),
                        status_code = reject.status_code,
                        "Plugin rejected finalized synthetic response body"
                    );
                    response_body_reject = Some(reject);
                    break;
                }
            }
        }
        if let Some(reject) = response_body_reject {
            // Rebuild headers/body only; the after_proxy reject hooks run once in
            // the caller so one-shot response state survives this replacement.
            *response_body = rebuild_plugin_rejection_response_headers(
                response_status,
                response_headers,
                reject,
            );
        }
    }

    // Restore the synthetic short-circuit marker to its prior state so it does
    // not leak past this body-hook phase into later logging/metrics hooks.
    if let Some(previous_synthetic_marker) = previous_synthetic_marker {
        ctx.metadata.insert(
            SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY.to_string(),
            previous_synthetic_marker,
        );
    } else {
        ctx.metadata.remove(SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY);
    }
}

/// Run the rejection-response plugin pipeline over a plugin short-circuit:
/// the synthetic response-body guardrail/transform hooks (when the gate in
/// [`should_apply_synthetic_response_body_hooks`] is satisfied) followed by the
/// `after_proxy` reject hooks (`applies_after_proxy_on_reject()`), applied
/// **exactly once** over the final response.
///
/// This is the shared core used by both the H1/H2/HBONE rejection path
/// ([`finalize_reject_response_with_after_proxy_hooks`]) and the HTTP/3
/// `before_proxy` rejection path, so AI guardrails (`ai_response_guard` /
/// `ai_semantic_firewall`) see synthetic 2xx bodies (e.g. `ai_federation` /
/// `ai_semantic_cache` hits surfaced via `RejectBinary{200}`) identically
/// across all frontends. It mutates `status`, `headers`, and `body` in place.
/// After body guardrails and reject-path `after_proxy` hooks, it applies shared
/// HEAD/204/205/304 wire preparation so H1/H2 finalize and every H3 reject
/// writer omit content bytes together (HEAD keeps representation
/// `Content-Length`). Remaining wire normalization (gRPC trailers) is still
/// the caller's responsibility.
///
/// Ordering: the synthetic body hooks run first (they may *replace* the
/// response when `ai_response_guard` / `ai_semantic_firewall` rejects the
/// synthetic body — see [`apply_synthetic_response_body_hooks`], which
/// rebuilds headers via [`rebuild_plugin_rejection_response_headers`] without
/// running `after_proxy`). The `after_proxy` reject hooks then run a single
/// time over whatever the FINAL response is (the synthetic response OR the
/// body-rejection response). Running `after_proxy` exactly once — and last —
/// preserves one-shot response state that those hooks emit: the
/// `oidc_relying_party` rotated session cookie and `response_transformer`
/// route-override headers are staged from metadata that the hook consumes on
/// first invocation, so they must be applied to the final response, not
/// consumed against a synthetic response that a later body rejection discards.
/// The reject-path `after_proxy` hooks are header-only and do not depend on the
/// body-hook output (`compression::after_proxy` deliberately no-ops on the
/// rejection path), so deferring them past the body hooks is safe.
pub(crate) async fn apply_reject_after_proxy_and_synthetic_body_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status: &mut u16,
    headers: &mut HashMap<String, String>,
    body: &mut Vec<u8>,
    is_grpc_request: bool,
    invoke_response_committed: bool,
) {
    let original_method = ctx
        .metadata
        .remove(SYNTHETIC_RESPONSE_METHOD_OVERRIDE_METADATA_KEY)
        .map(|method_override| std::mem::replace(&mut ctx.method, method_override));
    let applied_synthetic_body_hooks = !plugins.is_empty()
        && should_apply_synthetic_response_body_hooks(*status, is_grpc_request, body, plugins, ctx);
    if applied_synthetic_body_hooks {
        // KNOWN ORDERING DIVERGENCE (accepted, documented trade-off):
        //
        // On the synthetic short-circuit path the response-BODY hooks
        // (`on_response_body` / `transform_response_body_with_context` /
        // `on_final_response_body`) run HERE, BEFORE the `after_proxy` reject
        // hooks below. On the NORMAL backend path the order is reversed —
        // `after_proxy` runs before the body transforms. So a body transform that
        // depends on a header/metadata mutation made by an `after_proxy` hook
        // (e.g. `response_transformer`'s `after_proxy` rewriting `Content-Type`
        // to `application/json` before its JSON body rules, or `compression`
        // choosing an encoding) can see a different input on a synthetic 2xx than
        // it would on an equivalent backend 2xx.
        //
        // This is INTENTIONAL and must NOT be "fixed" by moving `after_proxy`
        // ahead of the body hooks: doing so would re-break the one-shot
        // `after_proxy` response-state contract that the caller relies on. The
        // body hooks may REPLACE the response when a guardrail rejects the
        // synthetic body (`apply_synthetic_response_body_hooks` rebuilds
        // headers via `rebuild_plugin_rejection_response_headers`). The
        // `after_proxy` reject hooks therefore have to run exactly once and LAST,
        // over the FINAL response, so one-shot state emitted from consumed
        // metadata — the `oidc_relying_party` rotated session cookie, the
        // `response_transformer` route override — lands on whatever the client
        // actually receives instead of being consumed against a synthetic
        // response that a later body rejection discards (see commit 36de1bf0
        // and the function-level doc on
        // `apply_reject_after_proxy_and_synthetic_body_hooks`).
        // The two requirements directly conflict; we keep the one-shot guarantee
        // and accept the minor body-transform divergence on the synthetic path.
        apply_synthetic_response_body_hooks(plugins, ctx, status, headers, body).await;
    }
    if let Some(original_method) = original_method {
        ctx.method = original_method;
    }
    // Apply the after_proxy reject hooks exactly once, over the final response
    // (the synthetic response or the body-rejection response produced above), so
    // one-shot response state (rotated session cookie, route overrides) is
    // emitted onto whatever the client actually receives. Runs LAST by design —
    // see the divergence note above.
    apply_replaceable_after_proxy_hooks_to_rejection(plugins, ctx, status, body, headers).await;

    // A failed WebSocket handshake is still an ordinary HTTP response, but its
    // transport-owned fields must come only from a successful H1 Upgrade or
    // Extended CONNECT builder. Run this boundary after every ordered reject
    // hook (including security_headers) so an early auth/authz/before_proxy
    // rejection cannot expose configured Upgrade/Connection/Sec-WebSocket-*
    // values. The request-flavor bit is stamped once by both frontends, avoiding
    // a second hot-path classification or plugin scan here.
    if ctx.has_websocket_response_boundary() {
        strip_websocket_transport_managed_response_header_map(headers);
    }

    // Body-independent finalized-synthetic signal. Empty 200 and 204/205
    // short-circuits skip the synthetic body-hook pipeline (and therefore never
    // see `SYNTHETIC_SHORT_CIRCUIT_METADATA_KEY`), but ownership plugins still
    // need a durable success signal through `on_response_committed`. Gate on the
    // *final* status after body-hook replacement and reject-path `after_proxy`
    // so a downstream non-2xx rejection replacement remains TTL-backed instead
    // of clearing in-flight ownership. H1/H2 and H3 share this finalizer, so
    // local and Redis request-dedup modes observe the same lifecycle.
    if (200..300).contains(status) {
        ctx.metadata.insert(
            FINALIZED_SYNTHETIC_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        );
    }

    // Observe every client-visible rejection that flows through this finalizer —
    // synthetic short-circuits, gRPC rejects, non-2xx rejects, empty-body rejects
    // — only after final-body validators, rejection replacement, and the
    // synthetic path's deliberately-late response-header hooks have run. The
    // committed-hook capability scan runs unconditionally (no longer gated on
    // whether body hooks applied) so exporters see the final response on all
    // rejection shapes, not just synthetic paths that ran body hooks.
    if invoke_response_committed
        && plugins
            .iter()
            .any(|plugin| plugin.requires_response_committed_hook())
    {
        let status_code = StatusCode::from_u16(*status).unwrap_or(StatusCode::BAD_GATEWAY);
        let normalized = normalize_reject_response(status_code, body, headers, is_grpc_request);
        for (index, plugin) in plugins.iter().enumerate() {
            if !plugin.requires_response_committed_hook() {
                continue;
            }
            let terminal_gateway_deadline = ctx.gateway_deadline_response_selected();
            let Some(pending_hook) = run_response_committed_hook_until_deadline(
                Arc::clone(plugin),
                ctx,
                normalized.http_status.as_u16(),
                &normalized.headers,
                &normalized.body,
                terminal_gateway_deadline,
            )
            .await
            else {
                continue;
            };
            if !terminal_gateway_deadline {
                ctx.mark_gateway_deadline_response_selected();
                replace_rejection_with_gateway_deadline(ctx, status, Some(body), headers);
            }
            spawn_detached_response_committed_hooks(
                pending_hook,
                plugins[index + 1..].to_vec(),
                *status,
                Arc::new(headers.clone()),
                Arc::new(body.clone()),
            );
            break;
        }
    }

    // This is internal ownership bookkeeping, not transaction metadata. Keep
    // it visible for the complete committed-hook lifecycle (including an owned
    // context transferred to detached deadline cleanup), then remove it from
    // the request context before later logging/summary hooks can copy it. H3
    // calls this finalizer with `invoke_response_committed = false` and runs its
    // committed hooks immediately afterward, so leave the marker intact for
    // that caller; the H3 committed-hook runner consumes it after its lifecycle.
    if invoke_response_committed {
        ctx.metadata
            .remove(FINALIZED_SYNTHETIC_RESPONSE_METADATA_KEY);
    }

    // Final wire shape for synthetic/reject responses: HEAD keeps representation
    // metadata (Content-Length) but omits content bytes; 204/205/304 omit both
    // content and Content-Length. Applied here so H1/H2 finalize and every H3
    // path that runs this shared hook cannot diverge.
    if crate::plugins::utils::synthetic_response::prepare_synthetic_response_wire(
        &ctx.method,
        *status,
        headers,
        body.len(),
    ) {
        *body = Vec::new();
    }
}

pub(crate) struct AfterProxyReject {
    pub status_code: u16,
    pub body: Vec<u8>,
    pub headers: HashMap<String, String>,
}

pub(crate) async fn run_after_proxy_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    response_status: u16,
    response_headers: &mut HashMap<String, String>,
) -> Option<AfterProxyReject> {
    // Establish backend provenance before the first trusted response hook can
    // mutate the map. A later deadline or representation-error replacement
    // retains only mutations from hooks that completed, never backend fields
    // selected by header name. Body-policy provenance is also required without
    // an RPC deadline: the eventual rejection must preserve gateway decorators
    // while shedding the rejected backend representation.
    if plugins
        .iter()
        .any(|plugin| plugin.may_enforce_response_body_policy(ctx))
    {
        ctx.begin_buffered_replacement_response_header_provenance(response_headers);
    } else {
        ctx.begin_buffered_deadline_response_header_provenance(response_headers);
    }
    // Capture the genuine backend status BEFORE any after_proxy hook can reject
    // and replace the response. If a hook at a lower priority rejects a 2xx
    // backend response (e.g. `response_size_limiting` at 3490 rejecting an
    // oversized 200), a higher-priority hook's genuine pass is skipped and only
    // re-runs inside `apply_after_proxy_hooks_to_rejection`; without this it
    // could not tell a rejected-but-served backend response apart from a real
    // gateway rejection. `ai_rate_limiter` reads this key to keep its token
    // reservation charged in that case.
    //
    // Gated on the presence of an `ai_rate_limiter` token reservation
    // (`RESERVED_TOKENS_METADATA_KEY`, set in its `before_proxy`) so this does
    // not add a metadata entry — and thus a transaction-log field — to every
    // request on non-AI proxies. When no reservation exists the keep/release
    // decision is moot anyway (`should_release_gateway_rejection` requires a
    // non-zero reservation), so the status is only useful when the marker is set.
    if ctx.metadata.contains_key(RESERVED_TOKENS_METADATA_KEY) {
        ctx.metadata.insert(
            BACKEND_STATUS_METADATA_KEY.to_string(),
            response_status.to_string(),
        );
    }

    for (index, plugin) in plugins.iter().enumerate() {
        if plugin.needs_later_response_cache_control_no_transform()
            || plugin.needs_later_response_strong_etag()
        {
            let later_headers =
                simulate_later_after_proxy_headers(&plugins[index + 1..], ctx, response_headers);
            if plugin.needs_later_response_cache_control_no_transform()
                && later_headers.cache_control_no_transform
            {
                ctx.metadata.insert(
                    LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY.to_string(),
                    "true".to_string(),
                );
            } else {
                ctx.metadata
                    .remove(LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY);
            }
            if plugin.needs_later_response_strong_etag() && later_headers.strong_etag {
                ctx.metadata.insert(
                    LATER_STRONG_ETAG_RESPONSE_METADATA_KEY.to_string(),
                    "true".to_string(),
                );
            } else {
                ctx.metadata.remove(LATER_STRONG_ETAG_RESPONSE_METADATA_KEY);
            }
        } else {
            ctx.metadata
                .remove(LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY);
            ctx.metadata.remove(LATER_STRONG_ETAG_RESPONSE_METADATA_KEY);
        }

        let deadline = ctx.grpc_deadline_at();
        let result = match crate::plugins::await_grpc_deadline(
            deadline,
            plugin.after_proxy(ctx, response_status, response_headers),
        )
        .await
        {
            Ok(result) => result,
            Err(()) => {
                ctx.mark_gateway_deadline_response_selected();
                crate::plugins::grpc_deadline_exceeded_plugin_result()
            }
        };
        match result {
            PluginResult::Continue => {
                ctx.record_buffered_initial_response_header_plugin(
                    plugin.as_ref(),
                    response_headers,
                );
                ctx.record_deadline_response_header_plugin(plugin.as_ref(), response_headers);
            }
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let RejectedResponseParts {
                    mut status_code,
                    mut body,
                    mut headers,
                } = plugin_result_into_reject_parts(reject)
                    .expect("reject result should convert to rejection parts");
                warn!(
                    "after_proxy plugin '{}' rejected response before downstream commit (status {})",
                    plugin.name(),
                    status_code,
                );
                ctx.metadata
                    .remove(LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY);
                ctx.metadata.remove(LATER_STRONG_ETAG_RESPONSE_METADATA_KEY);
                apply_replaceable_after_proxy_hooks_to_rejection(
                    plugins,
                    ctx,
                    &mut status_code,
                    &mut body,
                    &mut headers,
                )
                .await;
                return Some(AfterProxyReject {
                    status_code,
                    body,
                    headers,
                });
            }
        }
    }

    ctx.metadata
        .remove(LATER_NO_TRANSFORM_RESPONSE_METADATA_KEY);
    ctx.metadata.remove(LATER_STRONG_ETAG_RESPONSE_METADATA_KEY);
    None
}

pub(crate) struct NormalizedRejectResponse {
    pub(crate) http_status: StatusCode,
    pub(crate) headers: HashMap<String, String>,
    pub(crate) body: Vec<u8>,
    pub(crate) grpc_status: Option<u32>,
    pub(crate) grpc_message: Option<String>,
}

/// Apply route policy to a gateway-generated plain HTTP response and then
/// discard fields whose framing is owned by the frontend transport.
pub(crate) fn finalize_plain_gateway_error_response_headers(
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
    response_headers: &mut HashMap<String, String>,
) {
    crate::plugins::apply_initial_response_header_policies(
        initial_response_header_policy_plugins,
        response_headers,
    );
    response_headers.retain(|name, _| {
        !name.eq_ignore_ascii_case("content-length")
            && ![
                "connection",
                "keep-alive",
                "proxy-authenticate",
                "proxy-connection",
                "te",
                "trailer",
                "transfer-encoding",
                "upgrade",
            ]
            .iter()
            .any(|managed| name.eq_ignore_ascii_case(managed))
    });
}

/// Restore the gateway-owned method retry contract after generic response
/// policy has run. Policy may decorate a 405 response, but it must not remove,
/// replace, or duplicate the authoritative `Allow` value derived from the
/// matched route.
pub(crate) fn restore_authoritative_allow_header(
    response_headers: &mut HashMap<String, String>,
    allow_value: &str,
) {
    response_headers.retain(|name, _| !name.eq_ignore_ascii_case("allow"));
    response_headers.insert("allow".to_string(), allow_value.to_string());
}

fn finalize_synthesized_reject_headers(
    reject: &mut NormalizedRejectResponse,
    request_protocol: ProxyProtocol,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) {
    if let Some(grpc_status) = reject.grpc_status {
        grpc_proxy::finalize_grpc_error_response_headers(
            &mut reject.headers,
            grpc_status,
            reject.grpc_message.as_deref().unwrap_or(""),
            initial_response_header_policy_plugins,
        );
    } else if request_protocol == ProxyProtocol::WebSocket {
        finalize_websocket_response_headers(
            initial_response_header_policy_plugins,
            &mut reject.headers,
        );
    } else {
        finalize_plain_gateway_error_response_headers(
            initial_response_header_policy_plugins,
            &mut reject.headers,
        );
    }
}

fn grpc_status_reason(status: u32) -> &'static str {
    match status {
        grpc_proxy::grpc_status::INVALID_ARGUMENT => "Invalid argument",
        grpc_proxy::grpc_status::DEADLINE_EXCEEDED => "Deadline exceeded",
        grpc_proxy::grpc_status::NOT_FOUND => "Not found",
        grpc_proxy::grpc_status::PERMISSION_DENIED => "Permission denied",
        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED => "Resource exhausted",
        grpc_proxy::grpc_status::FAILED_PRECONDITION => "Failed precondition",
        grpc_proxy::grpc_status::ABORTED => "Aborted",
        grpc_proxy::grpc_status::UNIMPLEMENTED => "Unimplemented",
        grpc_proxy::grpc_status::INTERNAL => "Internal error",
        grpc_proxy::grpc_status::UNAVAILABLE => "Service unavailable",
        grpc_proxy::grpc_status::UNAUTHENTICATED => "Unauthenticated",
        _ => "Gateway rejected request",
    }
}

fn sanitize_grpc_message(message: &str) -> String {
    message
        .chars()
        .map(|c| if matches!(c, '\r' | '\n') { ' ' } else { c })
        .collect::<String>()
        .trim()
        .to_string()
}

pub(crate) fn extract_grpc_reject_message(body: &[u8]) -> Option<String> {
    let body = std::str::from_utf8(body).ok()?;
    let trimmed = body.trim();
    if trimmed.is_empty() {
        return None;
    }

    if let Ok(parsed) = serde_json::from_str::<serde_json::Value>(trimmed) {
        for key in ["grpc_message", "message", "error", "details"] {
            if let Some(msg) = parsed.get(key).and_then(|v| v.as_str()) {
                let sanitized = sanitize_grpc_message(msg);
                if !sanitized.is_empty() {
                    return Some(sanitized);
                }
            }
        }
    }

    let sanitized = sanitize_grpc_message(trimmed);
    (!sanitized.is_empty()).then_some(sanitized)
}

pub(crate) fn map_http_reject_status_to_grpc_status(status: StatusCode) -> u32 {
    grpc_proxy::http_reject_status_to_grpc_status(status)
}

pub(crate) fn normalize_reject_response(
    status: StatusCode,
    body: &[u8],
    headers: &HashMap<String, String>,
    is_grpc_request: bool,
) -> NormalizedRejectResponse {
    let grpc_web_accept_rejected =
        crate::plugins::grpc_web::reject_headers_mark_accept_not_acceptable(headers);
    if !is_grpc_request || grpc_web_accept_rejected {
        let mut normalized_headers = headers
            .iter()
            .filter(|(name, _)| !crate::plugins::grpc_web::is_internal_grpc_web_bridge_header(name))
            .map(|(name, value)| (name.clone(), value.clone()))
            .collect::<HashMap<_, _>>();
        normalized_headers
            .entry("content-type".to_string())
            .or_insert_with(|| "application/json".to_string());
        return NormalizedRejectResponse {
            http_status: status,
            headers: normalized_headers,
            body: body.to_vec(),
            grpc_status: None,
            grpc_message: None,
        };
    }

    let grpc_status = headers
        .get("grpc-status")
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or_else(|| map_http_reject_status_to_grpc_status(status));
    let grpc_message = headers
        .get("grpc-message")
        .cloned()
        .or_else(|| extract_grpc_reject_message(body))
        .unwrap_or_else(|| grpc_status_reason(grpc_status).to_string());
    let grpc_message = sanitize_grpc_message(&grpc_message);

    let mut normalized_headers = HashMap::with_capacity(headers.len() + 3);
    for (key, value) in headers {
        if key.eq_ignore_ascii_case("content-type")
            || key.eq_ignore_ascii_case("grpc-status")
            || key.eq_ignore_ascii_case("grpc-message")
        {
            continue;
        }
        normalized_headers.insert(key.clone(), value.clone());
    }
    normalized_headers.insert("content-type".to_string(), "application/grpc".to_string());
    normalized_headers.insert("grpc-status".to_string(), grpc_status.to_string());
    if !grpc_message.is_empty() {
        normalized_headers.insert("grpc-message".to_string(), grpc_message.clone());
    }

    NormalizedRejectResponse {
        http_status: StatusCode::OK,
        headers: normalized_headers,
        body: Vec::new(),
        grpc_status: Some(grpc_status),
        grpc_message: Some(grpc_message),
    }
}

fn normalized_grpc_deadline_exceeded() -> NormalizedRejectResponse {
    normalize_reject_response(
        StatusCode::OK,
        &[],
        &HashMap::from([
            ("content-type".to_string(), "application/grpc".to_string()),
            (
                "grpc-status".to_string(),
                GATEWAY_DEADLINE_EXCEEDED_STATUS_HEADER.to_string(),
            ),
            (
                "grpc-message".to_string(),
                GATEWAY_DEADLINE_EXCEEDED_MESSAGE.to_string(),
            ),
        ]),
        true,
    )
}

pub(crate) fn insert_grpc_error_metadata(
    metadata: &mut HashMap<String, String>,
    grpc_status: u32,
    grpc_message: &str,
) {
    metadata.insert("grpc_status".to_string(), grpc_status.to_string());
    let grpc_message = sanitize_grpc_message(grpc_message);
    if grpc_message.is_empty() {
        metadata.remove("grpc_message");
    } else {
        metadata.insert("grpc_message".to_string(), grpc_message);
    }
}

fn apply_grpc_reject_metadata(ctx: &mut RequestContext, reject: &NormalizedRejectResponse) {
    if let Some(grpc_status) = reject.grpc_status {
        insert_grpc_error_metadata(
            &mut ctx.metadata,
            grpc_status,
            reject.grpc_message.as_deref().unwrap_or(""),
        );
    }
}

pub(crate) async fn normalize_grpc_plugin_rejection_with_after_proxy_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    reject: RejectedResponseParts,
    invoke_response_committed: bool,
) -> NormalizedRejectResponse {
    let status = StatusCode::from_u16(reject.status_code).unwrap_or(StatusCode::BAD_GATEWAY);
    let normalized = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
        plugins,
        ctx,
        status,
        &reject.body,
        reject.headers,
        true,
        invoke_response_committed,
    )
    .await;
    apply_grpc_reject_metadata(ctx, &normalized);
    normalized
}

fn build_response_from_normalized_reject(reject: NormalizedRejectResponse) -> Response<ProxyBody> {
    let is_grpc_error = reject.grpc_status.is_some();
    let builder = headers_mod::apply_response_headers(
        Response::builder().status(reject.http_status),
        &reject.headers,
    );

    let body = if reject.body.is_empty() {
        // Status-aware empty body: 205 must not advertise Content-Length on H1
        // (Hyper would otherwise synthesize `Content-Length: 0` for ordinary
        // empty Full bodies; 204/304 are already special-cased upstream).
        ProxyBody::empty_for_response_status(reject.http_status.as_u16())
    } else {
        ProxyBody::full(Bytes::from(reject.body))
    };

    builder.body(body).unwrap_or_else(|_| {
        if is_grpc_error {
            grpc_proxy::build_grpc_error_response(
                grpc_proxy::grpc_status::INTERNAL,
                "Internal gateway error",
            )
        } else {
            build_response(
                StatusCode::INTERNAL_SERVER_ERROR,
                r#"{"error":"Internal server error"}"#,
            )
        }
    })
}

/// Build a gateway-generated error for a request the grpc_web plugin already
/// translated, enforcing the precomputed initial-header policy chain because
/// no backend response exists and the ordinary after_proxy lifecycle cannot
/// run. Policy is applied after the gRPC-Web representation headers are built
/// so content framing remains authoritative.
fn build_translated_grpc_web_error_response(
    ctx: &RequestContext,
    status: u32,
    message: &str,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> Option<Response<ProxyBody>> {
    let mut translated = crate::plugins::grpc_web::translated_error_response(ctx, status, message)?;
    finalize_grpc_web_error_response_headers(
        &mut translated,
        initial_response_header_policy_plugins,
        None,
    );
    Some(build_grpc_web_error_response_from_parts(
        translated, status, message,
    ))
}

/// Build a gateway-generated gRPC-Web error at the client-visible boundary.
/// These early/backend-exchange failure paths bypass normal response hooks, so
/// enforce the precomputed initial-header policy chain directly without a
/// plugin scan or moving terminal gRPC metadata out of the body trailer frame.
fn build_grpc_web_error_response(
    response_content_type: &str,
    status: u32,
    message: &str,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> Response<ProxyBody> {
    let mut response = crate::plugins::grpc_web::error_response_for_content_type(
        response_content_type,
        status,
        message,
    );
    finalize_grpc_web_error_response_headers(
        &mut response,
        initial_response_header_policy_plugins,
        None,
    );
    build_grpc_web_error_response_from_parts(response, status, message)
}

fn merge_grpc_web_expose_headers(
    required: Option<&str>,
    headers: &HashMap<String, String>,
) -> Option<String> {
    let mut merged = String::new();
    let configured = headers.iter().filter_map(|(name, value)| {
        name.eq_ignore_ascii_case("access-control-expose-headers")
            .then_some(value.as_str())
    });
    for value in required.into_iter().chain(configured) {
        for token in value
            .split(',')
            .map(str::trim)
            .filter(|token| !token.is_empty())
        {
            if merged
                .split(',')
                .any(|existing| existing.trim().eq_ignore_ascii_case(token))
            {
                continue;
            }
            if !merged.is_empty() {
                merged.push_str(", ");
            }
            merged.push_str(token);
        }
    }
    (!merged.is_empty()).then_some(merged)
}

/// Finalize the initial HEADERS for a gateway-generated gRPC-Web error.
///
/// Terminal gRPC metadata remains body-only at the wire boundary. A finalized
/// reject-hook chain may temporarily contribute terminal fields so the body
/// trailer frame can be rebuilt, but those fields are removed from the initial
/// headers before sending. The generated representation fields are also
/// authoritative: neither a security policy nor reject headers may replace
/// them or supply a stale content length.
///
/// The base gRPC-Web expose list is one of those authoritative generated
/// fields, so it is seeded from the canonical constant rather than read back
/// out of `response.headers`. Callers populate this map by EXTENDING the
/// generated error with other header sources — retained deadline-provenance
/// gateway output, or a finalized reject chain — and `extend` overwrites on key
/// collision. Reading the field back therefore did not observe the generated
/// base list at all once any of those sources carried its own
/// `access-control-expose-headers`: a partial value (a CORS policy's configured
/// list, or a provenance-partitioned suffix) replaced it wholesale, and the
/// browser-facing DEADLINE_EXCEEDED response could omit `grpc-status` /
/// `grpc-message` — the terminal metadata gRPC-Web carries in the body trailer
/// frame and JavaScript cannot read without them being exposed. Everything else
/// present still merges in on top; the merge dedups case-insensitively.
pub(crate) fn finalize_grpc_web_error_response_headers(
    response: &mut crate::plugins::grpc_web::GrpcWebErrorResponse,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
    finalized_reject_headers: Option<&HashMap<String, String>>,
) {
    finalize_grpc_web_error_response_headers_with_policy_source(
        response,
        InitialResponseHeaderPolicySource::Prefiltered(initial_response_header_policy_plugins),
        finalized_reject_headers,
    );
}

fn finalize_grpc_web_error_response_headers_with_policy_source(
    response: &mut crate::plugins::grpc_web::GrpcWebErrorResponse,
    initial_response_header_policy_source: InitialResponseHeaderPolicySource<'_>,
    finalized_reject_headers: Option<&HashMap<String, String>>,
) {
    let content_type = response.headers.get("content-type").cloned();
    let grpc_web = response.headers.get("x-grpc-web").cloned();

    if let Some(finalized_headers) = finalized_reject_headers {
        response.headers.extend(
            finalized_headers
                .iter()
                .map(|(name, value)| (name.clone(), value.clone())),
        );
        if let Some(content_type) = content_type.as_ref() {
            // Rejection normalization uses native application/grpc. Restore
            // the client representation before choosing binary versus text
            // trailer framing.
            response
                .headers
                .insert("content-type".to_string(), content_type.clone());
        }
        // Rejection hooks may supply rich terminal metadata such as
        // grpc-status-details-bin. Fold it into the body trailer frame before
        // terminal gRPC fields are removed from the initial header block.
        crate::plugins::grpc_web::rebuild_error_body_from_headers(response);
    } else {
        initial_response_header_policy_source.apply(&mut response.headers);
    }

    let expose_headers = merge_grpc_web_expose_headers(
        Some(crate::plugins::grpc_web::BASE_EXPOSE_HEADERS_VALUE),
        &response.headers,
    );

    response.headers.retain(|name, _| {
        ![
            "content-type",
            "content-length",
            "content-encoding",
            "x-grpc-web",
            "access-control-expose-headers",
            "grpc-status",
            "grpc-message",
            "grpc-status-details-bin",
            "connection",
            "keep-alive",
            "proxy-authenticate",
            "proxy-connection",
            "te",
            "trailer",
            "transfer-encoding",
            "upgrade",
        ]
        .iter()
        .any(|managed| name.eq_ignore_ascii_case(managed))
    });
    if let Some(content_type) = content_type {
        response
            .headers
            .insert("content-type".to_string(), content_type);
    }
    if let Some(grpc_web) = grpc_web {
        response.headers.insert("x-grpc-web".to_string(), grpc_web);
    }
    if let Some(expose_headers) = expose_headers {
        response
            .headers
            .insert("access-control-expose-headers".to_string(), expose_headers);
    }
    response.headers.insert(
        "content-length".to_string(),
        response.body.len().to_string(),
    );
}

/// Replace an uncommitted buffered native gRPC or gRPC-Web response with the
/// canonical gateway deadline result. All buffered frontends use this helper
/// so the terminal status, browser framing, CORS exposure, and initial-header
/// policies cannot drift by protocol or lifecycle phase.
pub(crate) fn replace_buffered_grpc_response_with_deadline(
    ctx: &mut RequestContext,
    grpc_web_response_content_type: Option<&str>,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> StatusCode {
    ctx.mark_gateway_deadline_response_selected();
    ctx.retain_deadline_response_gateway_headers(response_headers);
    if let Some(content_type) = grpc_web_response_content_type {
        let mut response = crate::plugins::grpc_web::error_response_for_content_type(
            content_type,
            grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
            GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
        );
        response.headers.extend(response_headers.drain());
        finalize_grpc_web_error_response_headers(
            &mut response,
            initial_response_header_policy_plugins,
            None,
        );
        *response_headers = response.headers;
        *response_body = response.body;
    } else {
        grpc_proxy::finalize_grpc_error_response_headers(
            response_headers,
            grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
            GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
            initial_response_header_policy_plugins,
        );
        response_body.clear();
    }
    ctx.sync_deadline_response_terminal_headers(response_headers);
    insert_grpc_error_metadata(
        &mut ctx.metadata,
        grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
        GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
    );
    StatusCode::OK
}

/// Client-visible message when a configured response body policy could not be
/// applied to the representation the backend produced.
///
/// Deliberately describes only that inspection failed. The rejection reason is
/// recorded in transaction metadata for operators; it is not echoed to the
/// client, so a caller cannot probe which codings or documents evade inspection.
const REPRESENTATION_UNINSPECTABLE_MESSAGE: &str = "response representation could not be inspected";

/// Transaction-metadata key carrying the low-cardinality reason a protected
/// buffered response was rejected by the shared representation gate.
pub(crate) const REPRESENTATION_REJECTED_METADATA_KEY: &str = "ferrum:representation_rejected";

/// Whether the buffered body transform phase may run, after the shared
/// representation gate has had its say.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum BufferedTransformAdmission {
    /// Run the transform phase. `rewrite_allowed` carries the pre-existing
    /// status gate, which still applies to responses no configured body policy
    /// claims: an unprotected `206`/`226` body is a fragment, and a
    /// presentation transform (compression, gRPC-Web framing) must not rewrite
    /// it into something the unchanged status no longer describes.
    Proceed {
        rewrite_allowed: bool,
        /// The gate itself replaced encoded bytes with identity bytes. This is
        /// a client-visible representation rewrite even when no later body rule
        /// returns replacement bytes, so trailer disposition must treat it the
        /// same as an ordinary transform.
        representation_rewritten: bool,
    },
    /// The response was replaced with a fail-closed representation error and the
    /// transform phase must be skipped.
    Rejected,
}

/// Where a representation-error path obtains deterministic initial-response
/// header policy.
///
/// Backend publication paths already carry the plugin cache's prefiltered list.
/// The synthetic short-circuit body phase instead owns the live,
/// protocol-filtered plugin chain; it filters that chain only after the gate has
/// selected a terminal representation error, avoiding allocation and leaving
/// the successful request path untouched.
#[derive(Clone, Copy)]
pub(crate) enum InitialResponseHeaderPolicySource<'a> {
    Prefiltered(&'a [Arc<dyn Plugin>]),
    ProtocolPlugins(&'a [Arc<dyn Plugin>]),
}

impl InitialResponseHeaderPolicySource<'_> {
    fn apply(self, response_headers: &mut HashMap<String, String>) {
        match self {
            Self::Prefiltered(policy_plugins) => {
                crate::plugins::apply_initial_response_header_policies(
                    policy_plugins,
                    response_headers,
                );
            }
            Self::ProtocolPlugins(plugins) => {
                for plugin in plugins {
                    if plugin.is_initial_response_header_policy() {
                        plugin.apply_initial_response_header_policy(response_headers);
                    }
                }
            }
        }
    }
}

/// Provenance of the buffered bytes entering the body transform phase.
///
/// One shared answer so no publication path can drift: the bytes are the
/// backend's until an `on_response_body` hook replaces them, after which they are
/// the gateway's own rejection and must be judged on their own live headers
/// rather than against the replaced backend response's snapshot.
pub(crate) fn buffered_response_representation_origin(
    response_body_rejected: bool,
) -> crate::plugins::response_representation::RepresentationOrigin {
    use crate::plugins::response_representation::RepresentationOrigin;
    if response_body_rejected {
        RepresentationOrigin::GatewayGenerated
    } else {
        RepresentationOrigin::Backend
    }
}

/// Replace a buffered response whose protected representation could not be
/// inspected, in the flavor the client is speaking.
///
/// gRPC and gRPC-Web get a trailers-only `INTERNAL` error (a plugin rejection on
/// `application/grpc` must never be a bare HTTP status); everything else gets a
/// `502` JSON body through the same rebuild path plugin rejections use.
///
/// Header discipline is the same on all three branches: no header describing the
/// rejected backend representation may survive onto the gateway-authored error,
/// and the gateway's own opt-in decorators (CORS, correlation IDs, security
/// headers) must survive, exactly as they do for an ordinary body reject.
///
/// `apply_reject_after_proxy_hooks` controls only *when* those decorators run for
/// the non-gRPC branch. The synthetic short-circuit path passes `false` because
/// its caller ([`apply_reject_after_proxy_and_synthetic_body_hooks`]) applies the
/// `after_proxy` reject hooks exactly once over whatever the final response turns
/// out to be — running them here too would consume one-shot response state (the
/// `oidc_relying_party` rotated session cookie, `response_transformer` route
/// overrides) a second time and silently drop it. Every backend path passes
/// `true`, matching [`apply_plugin_rejection_response`].
// Same nine request/response context parameters as the single caller
// (`admit_buffered_response_body_transforms`); bundling them into a struct
// here would only move the same borrows across one call boundary.
#[allow(clippy::too_many_arguments)]
async fn replace_buffered_response_with_representation_error(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    grpc_web_response_content_type: Option<&str>,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
    rejection: crate::plugins::response_representation::RepresentationRejection,
    initial_response_header_policy_source: InitialResponseHeaderPolicySource<'_>,
    apply_reject_after_proxy_hooks: bool,
) {
    warn!(
        reason = rejection.reason(),
        "Buffered response rejected: configured response body policy could not be enforced"
    );
    ctx.metadata.insert(
        REPRESENTATION_REJECTED_METADATA_KEY.to_string(),
        rejection.reason().to_string(),
    );

    // Response hooks are allowed to remove or relabel Content-Type. Keep the
    // error wire shape tied to the immutable inbound classification instead of
    // reclassifying the post-policy response header map.
    let native_grpc_request = ctx.is_native_grpc_request();

    // Both gRPC branches below rebuild from provenance-known gateway output.
    // The backend lifecycle seeded replacement provenance before response
    // hooks whenever a body policy could reject; this idempotent ensure also
    // covers deadline-only and direct helper paths. With no state recorded,
    // `retain_deadline_response_gateway_headers` still clears the map wholesale
    // rather than trusting backend fields by name.
    if grpc_web_response_content_type.is_some() || native_grpc_request {
        ctx.ensure_buffered_deadline_response_header_provenance(response_headers);
    }

    if let Some(content_type) = grpc_web_response_content_type {
        // Same header discipline as every other buffered terminal response:
        // rebuild from provenance-known gateway output so no entity header
        // describing the rejected representation survives onto the error.
        ctx.retain_deadline_response_gateway_headers(response_headers);
        let mut response = crate::plugins::grpc_web::error_response_for_content_type(
            content_type,
            grpc_proxy::grpc_status::INTERNAL,
            REPRESENTATION_UNINSPECTABLE_MESSAGE,
        );
        response.headers.extend(response_headers.drain());
        finalize_grpc_web_error_response_headers_with_policy_source(
            &mut response,
            initial_response_header_policy_source,
            None,
        );
        *response_headers = response.headers;
        *response_body = response.body;
        *response_status = StatusCode::OK.as_u16();
        ctx.sync_deadline_response_terminal_headers(response_headers);
        insert_grpc_error_metadata(
            &mut ctx.metadata,
            grpc_proxy::grpc_status::INTERNAL,
            REPRESENTATION_UNINSPECTABLE_MESSAGE,
        );
    } else if native_grpc_request {
        // Same discipline as the gRPC-Web branch above and as the deadline
        // replacement: shed everything that is not provenance-known gateway
        // output BEFORE synthesizing the trailers-only error. Otherwise backend
        // `set-cookie`, `etag`, `cache-control`, and other representation
        // metadata would survive onto a gateway-authored error describing bytes
        // that were rejected precisely because they could not be inspected.
        ctx.retain_deadline_response_gateway_headers(response_headers);
        initial_response_header_policy_source.apply(response_headers);
        grpc_proxy::finalize_grpc_error_response_headers(
            response_headers,
            grpc_proxy::grpc_status::INTERNAL,
            REPRESENTATION_UNINSPECTABLE_MESSAGE,
            &[],
        );
        response_body.clear();
        *response_status = StatusCode::OK.as_u16();
        ctx.sync_deadline_response_terminal_headers(response_headers);
        insert_grpc_error_metadata(
            &mut ctx.metadata,
            grpc_proxy::grpc_status::INTERNAL,
            REPRESENTATION_UNINSPECTABLE_MESSAGE,
        );
    } else {
        // `rebuild_plugin_rejection_response_headers` clears the map, so no
        // backend representation header can leak onto the error. The opt-in
        // `applies_after_proxy_on_reject` decorators then re-apply gateway-owned
        // headers, which is what makes this rejection indistinguishable from an
        // ordinary body reject to a CORS/correlation/security-header plugin.
        *response_body = rebuild_plugin_rejection_response_headers(
            response_status,
            response_headers,
            RejectedResponseParts {
                status_code: 502,
                body: format!(r#"{{"error":"{REPRESENTATION_UNINSPECTABLE_MESSAGE}"}}"#)
                    .into_bytes(),
                headers: HashMap::new(),
            },
        );
        if apply_reject_after_proxy_hooks {
            apply_replaceable_after_proxy_hooks_to_rejection(
                plugins,
                ctx,
                response_status,
                response_body,
                response_headers,
            )
            .await;
        }
    }
}

/// Apply the shared representation gate to one buffered response, immediately
/// before its body transform phase.
///
/// This is the single decision point every buffered publication path funnels
/// through — H1/H2, buffered gRPC, native H3, both H3 cross-protocol bridges,
/// and the synthetic/replay short-circuit — so the same bytes under the same
/// configuration cannot be treated differently by frontend protocol. On
/// `Enforce` with decoded bytes it installs the identity-coded body first, so
/// every transform in the phase sees exactly the representation the gate proved
/// inspectable.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn admit_buffered_response_body_transforms(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    origin: crate::plugins::response_representation::RepresentationOrigin,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
    grpc_web_response_content_type: Option<&str>,
    initial_response_header_policy_source: InitialResponseHeaderPolicySource<'_>,
    apply_reject_after_proxy_hooks: bool,
) -> BufferedTransformAdmission {
    use crate::plugins::response_representation::{
        RepresentationOrigin, ResponseBodyPolicyPosture, evaluate_response_body_policy_posture,
        install_decoded_response_body,
    };

    // Gateway-generated bytes have replaced whatever the backend sent, so the
    // pre-`after_proxy` snapshot describes a response that is no longer being
    // published. Drop it BEFORE the gate runs: the gate switches its own reads on
    // `origin`, but the per-plugin claim predicates it consults take only
    // `&RequestContext` and cannot, so a surviving stamp would let a stale
    // backend media type decide whether these bytes are claimed at all. Clearing
    // once here covers every gateway-generated publication path — the synthetic
    // short-circuit and the post-`on_response_body` replacement alike — so a new
    // one cannot be added that forgets to.
    if origin == RepresentationOrigin::GatewayGenerated {
        clear_replaced_backend_response_snapshot(ctx);
    }

    match evaluate_response_body_policy_posture(
        plugins,
        ctx,
        origin,
        *response_status,
        response_headers,
        response_body,
    ) {
        ResponseBodyPolicyPosture::Unprotected => BufferedTransformAdmission::Proceed {
            rewrite_allowed: crate::plugins::response_body_rewrite_allowed(*response_status),
            representation_rewritten: false,
        },
        ResponseBodyPolicyPosture::Enforce { decoded } => {
            let representation_rewritten = decoded.is_some();
            if let Some(decoded) = decoded {
                install_decoded_response_body(ctx, response_headers, response_body, decoded);
            }
            // A claimed response is never a fragment here: the gate rejects
            // partial and delta representations rather than admitting them, so
            // there is no status to relabel and no truncated resource to cache.
            BufferedTransformAdmission::Proceed {
                rewrite_allowed: true,
                representation_rewritten,
            }
        }
        ResponseBodyPolicyPosture::Reject(rejection) => {
            replace_buffered_response_with_representation_error(
                plugins,
                ctx,
                grpc_web_response_content_type,
                response_status,
                response_headers,
                response_body,
                rejection,
                initial_response_header_policy_source,
                apply_reject_after_proxy_hooks,
            )
            .await;
            BufferedTransformAdmission::Rejected
        }
    }
}

/// Run buffered response transforms under the request's absolute gRPC
/// deadline. A transform that exhausts the deadline selects the same
/// flavor-aware terminal response as every other buffered response phase.
///
/// The shared representation gate runs first
/// ([`admit_buffered_response_body_transforms`]).
///
/// `origin` is what the buffered bytes actually are by the time this phase runs,
/// and callers must pass it honestly. It is [`RepresentationOrigin::Backend`] for
/// a real backend response, whose pre-`after_proxy` snapshot is authoritative for
/// its encoding and range/delta state. It is
/// [`RepresentationOrigin::GatewayGenerated`] once an earlier `on_response_body`
/// hook has already **replaced** that backend response with a plugin rejection:
/// those bytes are the gateway's own JSON error, and judging them against the
/// original backend's snapshot would decode a body that was never encoded, or
/// reject a legitimate gateway `403` as a `206` fragment and overwrite it with a
/// generic `502` — destroying the rejection the operator's policy asked for.
///
/// [`RepresentationOrigin::Backend`]: crate::plugins::response_representation::RepresentationOrigin::Backend
/// [`RepresentationOrigin::GatewayGenerated`]: crate::plugins::response_representation::RepresentationOrigin::GatewayGenerated
///
/// Returns `(response_replaced, representation_rewritten)`.
/// `response_replaced` is true when this phase substituted a terminal response
/// — a deadline replacement or a representation rejection — so callers drop
/// backend trailers and treat the gateway-authored terminal metadata as
/// authoritative in both cases. `representation_rewritten` includes both a
/// plugin body transform and a gate-owned content decode, because either makes
/// trailers describing the original bytes stale.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn transform_buffered_response_body_with_deadline(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    origin: crate::plugins::response_representation::RepresentationOrigin,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
    grpc_web_response_content_type: Option<&str>,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> (bool, bool) {
    // Provenance is established before the gate, exactly as it is before the
    // deadline replacement path: a representation rejection is a gateway-authored
    // terminal response, so it must keep the gateway's own decorators (CORS,
    // tracing, request-id) and shed backend entity headers. Header changes the
    // gate itself makes are safe under this baseline — dropping a backend-authored
    // `Content-Encoding` after a decode cannot be resurrected by a later rebuild,
    // which replays gateway output only.
    ctx.ensure_buffered_deadline_response_header_provenance(response_headers);
    let (rewrite_allowed, representation_rewritten) = match admit_buffered_response_body_transforms(
        plugins,
        ctx,
        origin,
        response_status,
        response_headers,
        response_body,
        grpc_web_response_content_type,
        InitialResponseHeaderPolicySource::Prefiltered(initial_response_header_policy_plugins),
        true,
    )
    .await
    {
        BufferedTransformAdmission::Proceed {
            rewrite_allowed,
            representation_rewritten,
        } => (rewrite_allowed, representation_rewritten),
        BufferedTransformAdmission::Rejected => return (true, false),
    };
    if !rewrite_allowed {
        return (false, false);
    }
    // Read after the gate: a decoded body installs fresh representation headers.
    let content_type = response_headers.get("content-type").cloned();
    let content_type = content_type.as_deref();
    let mut body_transformed = representation_rewritten;
    for plugin in plugins {
        let transformed = match crate::plugins::await_grpc_deadline(
            ctx.grpc_deadline_at(),
            plugin.transform_response_body_with_context(
                ctx,
                response_body,
                content_type,
                response_headers,
            ),
        )
        .await
        {
            Ok(transformed) => transformed,
            Err(()) => {
                *response_status = replace_buffered_grpc_response_with_deadline(
                    ctx,
                    grpc_web_response_content_type,
                    response_headers,
                    response_body,
                    initial_response_header_policy_plugins,
                )
                .as_u16();
                return (true, body_transformed);
            }
        };
        if let Some(transformed) = transformed {
            response_headers.insert("content-length".to_string(), transformed.len().to_string());
            *response_body = transformed;
            crate::plugins::finalize_response_body_transformation(
                plugin.as_ref(),
                ctx,
                response_headers,
            );
            body_transformed = true;
        } else {
            if crate::plugins::compression::reconcile_aborted_gateway_response_encoding(
                ctx,
                response_status,
                response_headers,
                response_body,
            ) {
                return (true, true);
            }
        }
        ctx.record_deadline_response_header_plugin(plugin.as_ref(), response_headers);
    }
    (false, body_transformed)
}

/// A streaming deadline may replace the backend body with native trailers or
/// a gRPC-Web trailer DATA frame before any backend DATA is forwarded. The
/// backend's declared length therefore cannot remain authoritative.
pub(crate) fn strip_content_length_for_streaming_grpc_deadline(
    response_headers: &mut HashMap<String, String>,
    grpc_deadline_at: Option<tokio::time::Instant>,
) {
    if grpc_deadline_at.is_some() {
        response_headers.remove("content-length");
    }
}

pub(crate) type OwnedResponseCommittedHookFuture =
    std::pin::Pin<Box<dyn std::future::Future<Output = RequestContext> + Send + 'static>>;

fn owned_response_committed_hook_future(
    plugin: Arc<dyn Plugin>,
    mut ctx: RequestContext,
    response_status: u16,
    response_headers: Arc<HashMap<String, String>>,
    response_body: Arc<Vec<u8>>,
) -> OwnedResponseCommittedHookFuture {
    Box::pin(async move {
        plugin
            .on_response_committed(
                &mut ctx,
                response_status,
                response_headers.as_ref(),
                response_body.as_ref(),
            )
            .await;
        ctx
    })
}

/// Await a committed observer only while it can still affect the synchronous
/// terminal lifecycle. Once the client deadline is selected, give an
/// immediately-ready observer one poll; a pending observer is returned with
/// owned state so cleanup can continue without borrowing the response writer.
pub(crate) async fn run_response_committed_hook_until_deadline(
    plugin: Arc<dyn Plugin>,
    ctx: &mut RequestContext,
    response_status: u16,
    response_headers: &HashMap<String, String>,
    response_body: &[u8],
    terminal_gateway_deadline: bool,
) -> Option<OwnedResponseCommittedHookFuture> {
    let deadline = ctx.grpc_deadline_at();
    if !terminal_gateway_deadline && deadline.is_none() {
        plugin
            .on_response_committed(ctx, response_status, response_headers, response_body)
            .await;
        return None;
    }
    let mut hook = owned_response_committed_hook_future(
        plugin,
        ctx.clone(),
        response_status,
        Arc::new(response_headers.clone()),
        Arc::new(response_body.to_vec()),
    );
    if terminal_gateway_deadline {
        let completed = futures_util::future::poll_fn(|cx| {
            Poll::Ready(match std::future::Future::poll(hook.as_mut(), cx) {
                Poll::Ready(ctx) => Some(ctx),
                Poll::Pending => None,
            })
        })
        .await;
        if let Some(completed) = completed {
            *ctx = completed;
            return None;
        }
        return Some(hook);
    }
    let Some(deadline) = deadline else {
        return Some(hook);
    };
    let deadline_sleep = tokio::time::sleep_until(deadline);
    tokio::pin!(deadline_sleep);
    tokio::select! {
        biased;
        () = &mut deadline_sleep => Some(hook),
        completed = &mut hook => {
            *ctx = completed;
            None
        },
    }
}

pub(crate) fn spawn_detached_response_committed_hooks(
    pending_hook: OwnedResponseCommittedHookFuture,
    remaining_plugins: Vec<Arc<dyn Plugin>>,
    response_status: u16,
    response_headers: Arc<HashMap<String, String>>,
    response_body: Arc<Vec<u8>>,
) {
    std::mem::drop(tokio::spawn(async move {
        let cleanup = async move {
            let mut ctx = pending_hook.await;
            for plugin in remaining_plugins {
                if !plugin.requires_response_committed_hook() {
                    continue;
                }
                plugin
                    .on_response_committed(
                        &mut ctx,
                        response_status,
                        response_headers.as_ref(),
                        response_body.as_ref(),
                    )
                    .await;
            }
        };
        if tokio::time::timeout(DETACHED_REJECTION_CLEANUP_TIMEOUT, cleanup)
            .await
            .is_err()
        {
            warn!(
                timeout_seconds = DETACHED_REJECTION_CLEANUP_TIMEOUT.as_secs(),
                "detached committed-response cleanup exceeded its post-response bound"
            );
        }
    }));
}

/// Invoke each opted-in committed-response observer at most once. If the RPC
/// deadline expires inside one observer, select the canonical deadline
/// response and transfer that exact pending invocation plus the remaining
/// observers to bounded, owned post-response cleanup. Earlier observers are
/// never replayed and no observer can retain the client response writer.
pub(crate) async fn run_deadline_bounded_response_committed_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    response_status: &mut u16,
    response_headers: &mut HashMap<String, String>,
    response_body: &mut Vec<u8>,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> bool {
    let terminal_at_entry = ctx.gateway_deadline_response_selected();
    for (index, plugin) in plugins.iter().enumerate() {
        if !plugin.requires_response_committed_hook() {
            continue;
        }
        let terminal_gateway_deadline = ctx.gateway_deadline_response_selected();
        let Some(pending_hook) = run_response_committed_hook_until_deadline(
            Arc::clone(plugin),
            ctx,
            *response_status,
            response_headers,
            response_body,
            terminal_gateway_deadline,
        )
        .await
        else {
            continue;
        };

        let owned_grpc_web_response_content_type =
            crate::plugins::grpc_web::retained_response_content_type(ctx)
                .map(str::to_owned)
                .or_else(|| {
                    response_headers
                        .get("content-type")
                        .filter(|content_type| {
                            crate::plugins::grpc_web::is_grpc_web_content_type(content_type)
                        })
                        .map(|content_type| {
                            crate::plugins::grpc_web::response_content_type(content_type)
                        })
                });
        let grpc_web_response_content_type = owned_grpc_web_response_content_type.as_deref();
        *response_status = replace_buffered_grpc_response_with_deadline(
            ctx,
            grpc_web_response_content_type,
            response_headers,
            response_body,
            initial_response_header_policy_plugins,
        )
        .as_u16();
        spawn_detached_response_committed_hooks(
            pending_hook,
            plugins[index + 1..].to_vec(),
            *response_status,
            Arc::new(response_headers.clone()),
            Arc::new(response_body.clone()),
        );
        return true;
    }
    terminal_at_entry
}

fn build_grpc_web_error_response_from_parts(
    response: crate::plugins::grpc_web::GrpcWebErrorResponse,
    status: u32,
    message: &str,
) -> Response<ProxyBody> {
    let builder =
        headers_mod::apply_response_headers(Response::builder().status(200), &response.headers);

    builder
        .body(ProxyBody::full(Bytes::from(response.body)))
        .unwrap_or_else(|_| grpc_proxy::build_grpc_error_response(status, message))
}

fn build_pre_plugin_reject_response(
    status: StatusCode,
    body: &[u8],
    headers: &HashMap<String, String>,
    request_uses_grpc_content_type: bool,
    grpc_web_response_content_type: Option<&str>,
) -> Response<ProxyBody> {
    let reject = normalize_reject_response(
        status,
        body,
        headers,
        request_uses_grpc_content_type || grpc_web_response_content_type.is_some(),
    );
    if let (Some(content_type), Some(grpc_status)) =
        (grpc_web_response_content_type, reject.grpc_status)
    {
        let message = reject
            .grpc_message
            .as_deref()
            .unwrap_or_else(|| grpc_status_reason(grpc_status));
        return build_grpc_web_error_response(content_type, grpc_status, message, &[]);
    }
    build_response_from_normalized_reject(reject)
}

async fn build_grpc_web_reject_response(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    response_content_type: Option<&str>,
    reject: &NormalizedRejectResponse,
) -> Option<Response<ProxyBody>> {
    let (Some(content_type), Some(mut grpc_status)) = (response_content_type, reject.grpc_status)
    else {
        return None;
    };
    let mut message = reject
        .grpc_message
        .as_deref()
        .unwrap_or_else(|| grpc_status_reason(grpc_status))
        .to_string();
    let mut translated = crate::plugins::grpc_web::error_response_for_content_type(
        content_type,
        grpc_status,
        &message,
    );
    finalize_grpc_web_error_response_headers(&mut translated, &[], Some(&reject.headers));
    if plugins
        .iter()
        .any(|plugin| plugin.requires_response_committed_hook())
    {
        for (index, plugin) in plugins.iter().enumerate() {
            if !plugin.requires_response_committed_hook() {
                continue;
            }
            let terminal_gateway_deadline = ctx.gateway_deadline_response_selected();
            let Some(pending_hook) = run_response_committed_hook_until_deadline(
                Arc::clone(plugin),
                ctx,
                StatusCode::OK.as_u16(),
                &translated.headers,
                &translated.body,
                terminal_gateway_deadline,
            )
            .await
            else {
                continue;
            };
            if !terminal_gateway_deadline {
                ctx.mark_gateway_deadline_response_selected();
                grpc_status = grpc_proxy::grpc_status::DEADLINE_EXCEEDED;
                message = GATEWAY_DEADLINE_EXCEEDED_MESSAGE.to_string();
                translated = crate::plugins::grpc_web::error_response_for_content_type(
                    content_type,
                    grpc_status,
                    &message,
                );
                let mut deadline_headers = reject.headers.clone();
                deadline_headers.retain(|name, _| {
                    !["grpc-status", "grpc-message", "grpc-status-details-bin"]
                        .iter()
                        .any(|terminal| name.eq_ignore_ascii_case(terminal))
                });
                finalize_grpc_web_error_response_headers(
                    &mut translated,
                    &[],
                    Some(&deadline_headers),
                );
                insert_grpc_error_metadata(&mut ctx.metadata, grpc_status, &message);
            }
            spawn_detached_response_committed_hooks(
                pending_hook,
                plugins[index + 1..].to_vec(),
                StatusCode::OK.as_u16(),
                Arc::new(translated.headers.clone()),
                Arc::new(translated.body.clone()),
            );
            break;
        }
    }
    Some(build_grpc_web_error_response_from_parts(
        translated,
        grpc_status,
        &message,
    ))
}

#[allow(clippy::too_many_arguments)]
async fn run_backend_path_plugins_or_build_reject(
    backend_path_plugins: &[Arc<dyn Plugin>],
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    backend_path: &str,
    state: &ProxyState,
    start_time: Instant,
    plugin_execution_ns: &mut u64,
    original_request_path: &str,
    is_grpc_request: bool,
    grpc_web_response_content_type: Option<&str>,
) -> Option<Response<ProxyBody>> {
    let phase_start = Instant::now();
    for plugin in backend_path_plugins {
        let deadline = ctx.grpc_deadline_at();
        match crate::plugins::await_request_plugin_deadline_with_provenance(
            deadline,
            plugin.on_backend_path_resolved(ctx, backend_path),
        )
        .await
        .into_plugin_result(ctx)
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                *plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                    error!(
                        plugin = plugin.name(),
                        "Backend-path plugin rejection could not be normalized"
                    );
                    record_request(state, 500);
                    return Some(build_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        r#"{"error":"Internal error"}"#,
                    ));
                };
                let status = StatusCode::from_u16(plugin_reject.status_code)
                    .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
                let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                    plugins,
                    ctx,
                    status,
                    &plugin_reject.body,
                    plugin_reject.headers,
                    is_grpc_request,
                    grpc_web_response_content_type.is_none(),
                )
                .await;
                apply_grpc_reject_metadata(ctx, &reject);
                let grpc_web_response = build_grpc_web_reject_response(
                    plugins,
                    ctx,
                    grpc_web_response_content_type,
                    &reject,
                )
                .await;
                log_rejected_request_with_path(
                    plugins,
                    ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "on_backend_path_resolved",
                    *plugin_execution_ns,
                    Some(original_request_path),
                )
                .await;
                record_request(state, reject.http_status.as_u16());
                if let Some(response) = grpc_web_response {
                    return Some(response);
                }
                return Some(build_response_from_normalized_reject(reject));
            }
        }
    }
    *plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    None
}

async fn finalize_reject_response_with_after_proxy_hooks(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status: StatusCode,
    body: &[u8],
    headers: HashMap<String, String>,
    is_grpc_request: bool,
) -> NormalizedRejectResponse {
    finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
        plugins,
        ctx,
        status,
        body,
        headers,
        is_grpc_request,
        true,
    )
    .await
}

async fn finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status: StatusCode,
    body: &[u8],
    mut headers: HashMap<String, String>,
    is_grpc_request: bool,
    invoke_response_committed: bool,
) -> NormalizedRejectResponse {
    let mut response_status = status.as_u16();
    let mut response_body = body.to_vec();
    let hook_start = Instant::now();
    apply_reject_after_proxy_and_synthetic_body_hooks(
        plugins,
        ctx,
        &mut response_status,
        &mut headers,
        &mut response_body,
        is_grpc_request,
        invoke_response_committed,
    )
    .await;
    // Attribute the reject-path `after_proxy` + synthetic response-body hook time
    // to plugin execution rather than gateway overhead. The H1/H2/HBONE callers
    // add their phase `plugin_execution_ns` *before* invoking this finalizer, so
    // these hooks — which can run `ai_response_guard`/`ai_semantic_firewall` over
    // a synthetic AI body, including external HTTP calls — would otherwise be
    // uncounted in `latency_plugin_execution_ms`; `log_rejected_request_with_path`
    // folds this in. The H3 reject path times these hooks inline and never calls
    // this finalizer, so its `reject_hook_execution_ns` stays 0 (no double count).
    ctx.reject_hook_execution_ns.fetch_add(
        hook_start.elapsed().as_nanos() as u64,
        std::sync::atomic::Ordering::Relaxed,
    );
    let status = StatusCode::from_u16(response_status).unwrap_or(status);
    normalize_reject_response(status, &response_body, &headers, is_grpc_request)
}

/// Finalize a terminal request-body read failure before any external operation
/// or backend dispatch could start. The committed-response hook owns cleanup of
/// exact local/distributed in-flight tokens, so every failure shape must pass
/// through the same rejection pipeline exactly once.
#[allow(clippy::too_many_arguments)]
async fn finalize_terminal_request_body_read_rejection(
    state: &ProxyState,
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    status: StatusCode,
    body: &[u8],
    is_grpc_request: bool,
    start_time: Instant,
    plugin_execution_ns: u64,
    request_path: &str,
) -> Response<ProxyBody> {
    ctx.metadata.insert(
        RELEASE_INFLIGHT_ON_COMMIT_METADATA_KEY.to_string(),
        "true".to_string(),
    );
    let normalized = finalize_reject_response_with_after_proxy_hooks(
        plugins,
        ctx,
        status,
        body,
        HashMap::new(),
        is_grpc_request,
    )
    .await;
    apply_grpc_reject_metadata(ctx, &normalized);
    log_rejected_request_with_path(
        plugins,
        ctx,
        normalized.http_status.as_u16(),
        start_time,
        "on_final_request_body",
        plugin_execution_ns,
        Some(request_path),
    )
    .await;
    record_request(state, normalized.http_status.as_u16());
    build_response_from_normalized_reject(normalized)
}

#[allow(clippy::too_many_arguments)]
async fn handle_backend_admission_rejection(
    rejection: backend_dispatch::BackendAdmissionRejection,
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    state: &ProxyState,
    start_time: Instant,
    plugin_execution_ns: u64,
    original_request_path: Option<&str>,
    is_grpc_request: bool,
    grpc_web_error_content_type: Option<&str>,
) -> Response<ProxyBody> {
    let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
        plugins,
        ctx,
        StatusCode::from_u16(rejection.status_code).unwrap_or(StatusCode::SERVICE_UNAVAILABLE),
        &rejection.body,
        rejection.headers,
        is_grpc_request,
        grpc_web_error_content_type.is_none(),
    )
    .await;
    apply_grpc_reject_metadata(ctx, &reject);
    let grpc_web_response =
        build_grpc_web_reject_response(plugins, ctx, grpc_web_error_content_type, &reject).await;
    log_rejected_request_with_path(
        plugins,
        ctx,
        reject.http_status.as_u16(),
        start_time,
        &rejection.plugin_name,
        plugin_execution_ns,
        original_request_path,
    )
    .await;
    record_request(state, reject.http_status.as_u16());
    if let Some(response) = grpc_web_response {
        return response;
    }
    build_response_from_normalized_reject(reject)
}

/// Finalize a client RPC deadline discovered while buffering the upload.
///
/// These exits occur before a backend response exists, but they are still
/// ordinary client-visible rejections: reject-path `after_proxy` decorators,
/// committed observers, and rejection logging must all see the canonical
/// status-4 result. In particular, gRPC-Web needs the finalized header map so
/// CORS decorators survive translation into its body-trailer representation.
pub(crate) async fn build_finalized_upload_deadline_response(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    grpc_web_response_content_type: Option<&str>,
) -> (Response<ProxyBody>, u16) {
    let deadline = normalized_grpc_deadline_exceeded();
    let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
        plugins,
        ctx,
        deadline.http_status,
        &deadline.body,
        deadline.headers,
        true,
        grpc_web_response_content_type.is_none(),
    )
    .await;
    apply_grpc_reject_metadata(ctx, &reject);
    let grpc_web_response =
        build_grpc_web_reject_response(plugins, ctx, grpc_web_response_content_type, &reject).await;
    let log_status = reject.http_status.as_u16();
    let response =
        grpc_web_response.unwrap_or_else(|| build_response_from_normalized_reject(reject));
    (response, log_status)
}

#[allow(clippy::too_many_arguments)]
async fn finalize_upload_deadline_rejection(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    state: &ProxyState,
    start_time: Instant,
    rejection_phase: &str,
    plugin_execution_ns: u64,
    original_request_path: Option<&str>,
    grpc_web_response_content_type: Option<&str>,
) -> Response<ProxyBody> {
    let (response, log_status) =
        build_finalized_upload_deadline_response(plugins, ctx, grpc_web_response_content_type)
            .await;
    log_rejected_request_with_path(
        plugins,
        ctx,
        log_status,
        start_time,
        rejection_phase,
        plugin_execution_ns,
        original_request_path,
    )
    .await;
    record_request(state, log_status);
    response
}

fn release_circuit_breaker_probe_on_admission_reject(
    state: &ProxyState,
    proxy: &Proxy,
    target_key: Option<&str>,
    is_half_open_probe: bool,
) {
    if !is_half_open_probe {
        return;
    }
    if let Some(cb_config) = &proxy.circuit_breaker {
        let cb = state
            .circuit_breaker_cache
            .get_or_create(&proxy.id, target_key, cb_config);
        cb.record_neutral(true);
    }
}

pub fn request_is_authenticated(ctx: &RequestContext) -> bool {
    ctx.effective_identity().is_some()
}

const MISSING_AUTHENTICATION_BODY: &[u8] = br#"{"error":"Authentication required"}"#;

fn missing_authentication_reject(
    auth_plugins: &[Arc<dyn Plugin>],
) -> (u16, Vec<u8>, HashMap<String, String>) {
    let mut headers = HashMap::new();
    // Challenge selection follows configured priority order: mechanisms that
    // do not advertise a challenge are skipped, and the first available
    // challenge wins.
    let challenge = auth_plugins
        .iter()
        .find_map(|plugin| plugin.authentication_challenge())
        .unwrap_or("ferrum-edge");
    headers.insert("WWW-Authenticate".to_string(), challenge.to_string());
    (401, MISSING_AUTHENTICATION_BODY.to_vec(), headers)
}

#[derive(Clone, Copy)]
pub(crate) enum BackendPathBeforeProxyPass {
    Initial,
    RoutingHeaderDeferred,
    RemainingDeferred,
}

pub(crate) async fn run_before_proxy_hooks_for_backend_path_policy(
    plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    headers: &mut HashMap<String, String>,
    backend_path_is_policy_bound: bool,
    pass: BackendPathBeforeProxyPass,
) -> PluginResult {
    for plugin in plugins {
        let deferred =
            backend_path_is_policy_bound && plugin.defer_before_proxy_until_backend_path_resolved();
        let should_run = match pass {
            BackendPathBeforeProxyPass::Initial => !deferred,
            BackendPathBeforeProxyPass::RoutingHeaderDeferred => {
                deferred && plugin.deferred_before_proxy_may_change_routing_headers()
            }
            BackendPathBeforeProxyPass::RemainingDeferred => {
                deferred && !plugin.deferred_before_proxy_may_change_routing_headers()
            }
        };
        if !should_run {
            continue;
        }
        let deadline = ctx.grpc_deadline_at();
        match crate::plugins::await_request_plugin_deadline_with_provenance(
            deadline,
            plugin.before_proxy(ctx, headers),
        )
        .await
        .into_plugin_result(ctx)
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                return reject;
            }
        }
    }
    PluginResult::Continue
}

const MAX_SET_COOKIE_NAME_VALUE_BYTES: usize = 4096;

/// Return the RFC 10025 cookie-name from a browser-comparable leading
/// cookie-pair. Keep the existing strict producer grammar for names, but use
/// the user-agent value boundary: browsers accept non-control value syntax
/// that producers are discouraged from emitting, including spaces, commas,
/// quotes, and backslashes.
fn set_cookie_name(set_cookie: &str) -> Option<&str> {
    let cookie_pair = set_cookie
        .split_once(';')
        .map_or(set_cookie, |(pair, _)| pair);
    let (name, value) = cookie_pair.split_once('=')?;
    // RFC 6265 strips leading and trailing SP/HTAB from both sides of the
    // cookie-pair before validating its name and value.
    let name = name.trim_matches([' ', '\t']);
    let value = value.trim_matches([' ', '\t']);
    // RFC 10025 rejects a cookie when its trimmed name and value total more
    // than 4096 octets. Such a line cannot own and suppress a valid staged
    // cleanup cookie that the browser can actually store.
    if name.len().saturating_add(value.len()) > MAX_SET_COOKIE_NAME_VALUE_BYTES
        || name.is_empty()
        || !name.bytes().all(|byte| {
            matches!(
                byte,
                b'!' | b'#'
                    | b'$'
                    | b'%'
                    | b'&'
                    | b'\''
                    | b'*'
                    | b'+'
                    | b'-'
                    | b'.'
                    | b'0'..=b'9'
                    | b'A'..=b'Z'
                    | b'^'
                    | b'_'
                    | b'`'
                    | b'a'..=b'z'
                    | b'|'
                    | b'~'
            )
        })
    {
        return None;
    }

    // The first semicolon already terminated `cookie_pair`. Reject C0/DEL so
    // malformed or header-injection-bearing values remain non-comparable,
    // while retaining ownership for values a user agent can actually store.
    if value.bytes().any(|byte| byte <= 0x1f || byte == 0x7f) {
        return None;
    }

    Some(name)
}

/// RFC 6265 ignores one leading dot on Domain attributes and compares the
/// resulting canonicalized domain case-insensitively. Ferrum accepts the full
/// RFC 3986 reg-name and bracketed IP-literal forms at request admission, so
/// apply the same validation here instead of narrowing comparable cookie
/// scopes to LDH names. Normalize IPv6 text so equivalent compressed and
/// expanded forms cannot evade storage-key ownership.
enum CanonicalSetCookieDomain<'a> {
    Text(&'a str),
    Ipv6(std::net::Ipv6Addr),
}

fn canonical_set_cookie_domain(domain: &str) -> Option<CanonicalSetCookieDomain<'_>> {
    let domain = domain.strip_prefix('.').unwrap_or(domain);
    if let Some(content) = domain
        .strip_prefix('[')
        .and_then(|content| content.strip_suffix(']'))
    {
        if let Ok(ipv6) = content.parse::<std::net::Ipv6Addr>() {
            return Some(CanonicalSetCookieDomain::Ipv6(ipv6));
        }
        return is_valid_ip_literal_contents(content)
            .then_some(CanonicalSetCookieDomain::Text(domain));
    }
    if domain.ends_with('.') || !is_valid_reg_name(domain) {
        return None;
    }
    Some(CanonicalSetCookieDomain::Text(domain))
}

fn canonical_set_cookie_domain_ip(domain: &CanonicalSetCookieDomain<'_>) -> Option<IpAddr> {
    match domain {
        CanonicalSetCookieDomain::Text(domain) => domain.parse().ok(),
        CanonicalSetCookieDomain::Ipv6(domain) => Some(IpAddr::V6(*domain)),
    }
}

fn set_cookie_request_host(authority: Option<&str>) -> Option<&str> {
    split_request_authority(authority?).map(|(host, _)| host)
}

fn set_cookie_request_host_ip(request_host: Option<&str>) -> Option<IpAddr> {
    let host = request_host?;
    host.strip_prefix('[')
        .and_then(|content| content.strip_suffix(']'))
        .unwrap_or(host)
        .parse()
        .ok()
}

fn set_cookie_domain_is_public_suffix(domain: &str) -> bool {
    let lowercase_domain = domain.to_ascii_lowercase();
    psl::suffix_str(&lowercase_domain).is_some_and(|suffix| suffix == lowercase_domain.as_str())
}

fn valid_set_cookie_path(path: &str) -> bool {
    path.starts_with('/') && !path.bytes().any(|byte| byte <= 0x1f || byte == 0x7f)
}

fn default_set_cookie_path(request_path: &str) -> &str {
    if !request_path.starts_with('/') {
        return "/";
    }
    match request_path.rfind('/') {
        Some(0) | None => "/",
        Some(last_slash) => &request_path[..last_slash],
    }
}

/// Browsers treat HTTP loopback and `localhost` origins as potentially
/// trustworthy, so they may store `Secure` cookies even without TLS. Match the
/// default trust boundary from Secure Contexts; user-configured browser
/// allowlists are intentionally unknowable at the proxy.
fn request_authority_is_potentially_trustworthy(authority: &str) -> bool {
    let Some((host, _)) = split_request_authority(authority) else {
        return false;
    };
    let host = host.strip_suffix('.').unwrap_or(host);
    let localhost_suffix = ".localhost";
    if host.eq_ignore_ascii_case("localhost")
        || (host.len() > localhost_suffix.len()
            && host
                .get(host.len() - localhost_suffix.len()..)
                .is_some_and(|suffix| suffix.eq_ignore_ascii_case(localhost_suffix)))
    {
        return true;
    }

    let ip_literal = host
        .strip_prefix('[')
        .and_then(|content| content.strip_suffix(']'))
        .unwrap_or(host);
    match ip_literal.parse::<std::net::IpAddr>() {
        Ok(std::net::IpAddr::V4(address)) => address.octets()[0] == 127,
        Ok(std::net::IpAddr::V6(address)) => address.is_loopback(),
        Err(_) => false,
    }
}

fn request_can_store_secure_cookie(ctx: &RequestContext) -> bool {
    ctx.request_is_secure
        || ctx
            .request_authority
            .as_deref()
            .is_some_and(request_authority_is_potentially_trustworthy)
}

struct SetCookieStorageKey<'a> {
    name: &'a str,
    domain: Option<CanonicalSetCookieDomain<'a>>,
    path: &'a str,
    host_only: bool,
    partitioned: bool,
}

/// Return the effective RFC 10025 cookie storage key. Omitted Domain resolves
/// to the exact validated request host used for browser cookie comparison while
/// retaining its host-only state. Omitted, empty, or non-absolute Path
/// attributes use the request path's default directory. Host-only and
/// Partitioned cookies remain independent from otherwise equivalent domain and
/// unpartitioned cookies.
fn set_cookie_storage_key<'a>(
    set_cookie: &'a str,
    default_path: &'a str,
    request_is_secure: bool,
    request_host: Option<&'a str>,
    request_host_ip: Option<IpAddr>,
) -> Option<SetCookieStorageKey<'a>> {
    let name = set_cookie_name(set_cookie)?;
    let mut domain_attribute = None;
    let mut path_attribute = None;
    let mut partitioned = false;
    let mut secure = false;
    let mut http_only = false;
    let mut same_site_none = false;

    for attribute in set_cookie.split(';').skip(1) {
        let attribute = attribute.trim_matches([' ', '\t']);
        // User agents reject control-bearing cookie attributes. Do not treat a
        // hostile Path control as ordinary invalid syntax and resolve it to the
        // default path, which could suppress a valid staged cleanup cookie.
        if attribute.bytes().any(|byte| byte <= 0x1f || byte == 0x7f) {
            return None;
        }
        let (attribute_name, attribute_value) = match attribute.split_once('=') {
            Some((name, value)) => (
                name.trim_matches([' ', '\t']),
                Some(value.trim_matches([' ', '\t'])),
            ),
            None => (attribute, None),
        };
        if attribute_name.eq_ignore_ascii_case("partitioned") {
            partitioned = true;
        } else if attribute_name.eq_ignore_ascii_case("secure") {
            secure = true;
        } else if attribute_name.eq_ignore_ascii_case("httponly") {
            http_only = true;
        } else if attribute_name.eq_ignore_ascii_case("samesite") {
            // The last SameSite attribute wins; invalid and bare values map to
            // the default enforcement rather than preserving an earlier None.
            same_site_none =
                attribute_value.is_some_and(|value| value.eq_ignore_ascii_case("none"));
        } else if attribute_name.eq_ignore_ascii_case("domain") {
            // User agents ignore empty and bare Domain cookie-avs. A later
            // empty value therefore does not erase an earlier valid Domain.
            if let Some(value) = attribute_value.filter(|value| !value.is_empty()) {
                domain_attribute = Some(value);
            }
        } else if attribute_name.eq_ignore_ascii_case("path") {
            // A bare Path is the last Path attribute with an empty value, so
            // it supersedes an earlier value and resolves to default_path.
            path_attribute = Some(attribute_value.unwrap_or(""));
        }
    }

    // RFC 6265 uses the last effective Domain/Path attribute. Empty Domain
    // values were ignored above, while a trailing-dot or otherwise malformed
    // non-empty Domain rejects the cookie. Mainstream user agents treat an
    // exact-IP Domain as a host cookie and reject a nonmatching IP Domain.
    // An invalid Path value falls back to the request's default path.
    let (domain, host_only) = match domain_attribute {
        None => (request_host.and_then(canonical_set_cookie_domain), true),
        Some(domain) => {
            let domain = canonical_set_cookie_domain(domain)?;
            if let Some(domain_ip) = canonical_set_cookie_domain_ip(&domain) {
                if request_host_ip != Some(domain_ip) {
                    return None;
                }
                (Some(domain), true)
            } else {
                // RFC 6265bis public-suffix handling is storage-key-visible:
                // a Domain equal to the request host is converted to a
                // host-only cookie, while any other public-suffix Domain is
                // rejected. Use the current Mozilla PSL (including private
                // suffixes such as github.io) so Ferrum compares the same key
                // a browser will actually store.
                let CanonicalSetCookieDomain::Text(domain_text) = &domain else {
                    return None;
                };
                if set_cookie_domain_is_public_suffix(domain_text) {
                    if !request_host.is_some_and(|host| host.eq_ignore_ascii_case(domain_text)) {
                        return None;
                    }
                    (Some(domain), true)
                } else {
                    (Some(domain), false)
                }
            }
        }
    };
    let path = match path_attribute {
        Some(path) if valid_set_cookie_path(path) => path,
        Some(_) | None => default_path,
    };

    // RFC 10025 §5.4 requires user agents to match cookie-name prefix strings
    // case-insensitively; §5.7 applies that rule in the __Secure-/__Host-
    // storage checks. Keep every browser-prefix check here case-insensitive.
    let secure_prefix = name
        .get(.."__Secure-".len())
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("__Secure-"));
    let host_prefix = name
        .get(.."__Host-".len())
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("__Host-"));
    let http_prefix = name
        .get(.."__Http-".len())
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("__Http-"));
    let host_http_prefix = name
        .get(.."__Host-Http-".len())
        .is_some_and(|prefix| prefix.eq_ignore_ascii_case("__Host-Http-"));
    // Cookies that a browser will reject cannot own a staged cookie's storage
    // key. Keep the selected line in the response, but make it non-comparable
    // so a valid earlier cleanup is appended after it. `__Host-` additionally
    // requires an explicit Path=/ attribute, not merely a default path of `/`;
    // `__Http-` and `__Host-Http-` additionally require HttpOnly.
    if (secure && !request_is_secure)
        || (partitioned && !secure)
        || (same_site_none && !secure)
        || (secure_prefix && !secure)
        || (host_prefix && (!secure || !host_only || path_attribute != Some("/")))
        || (http_prefix && (!secure || !http_only))
        || (host_http_prefix && !http_only)
    {
        return None;
    }

    Some(SetCookieStorageKey {
        name,
        domain,
        path,
        host_only,
        partitioned,
    })
}

fn set_cookie_same_storage_key(
    existing: &str,
    candidate: &str,
    default_path: &str,
    request_is_secure: bool,
    request_host: Option<&str>,
    request_host_ip: Option<IpAddr>,
) -> bool {
    let Some(existing_key) = set_cookie_storage_key(
        existing,
        default_path,
        request_is_secure,
        request_host,
        request_host_ip,
    ) else {
        return false;
    };
    let Some(candidate_key) = set_cookie_storage_key(
        candidate,
        default_path,
        request_is_secure,
        request_host,
        request_host_ip,
    ) else {
        return false;
    };

    existing_key.name == candidate_key.name
        && existing_key.path == candidate_key.path
        && existing_key.host_only == candidate_key.host_only
        && existing_key.partitioned == candidate_key.partitioned
        && match (existing_key.domain, candidate_key.domain) {
            (
                Some(CanonicalSetCookieDomain::Text(existing_domain)),
                Some(CanonicalSetCookieDomain::Text(candidate_domain)),
            ) => existing_domain.eq_ignore_ascii_case(candidate_domain),
            (
                Some(CanonicalSetCookieDomain::Ipv6(existing_domain)),
                Some(CanonicalSetCookieDomain::Ipv6(candidate_domain)),
            ) => existing_domain == candidate_domain,
            (None, None) => true,
            _ => false,
        }
}

/// Add newline-joined `Set-Cookie` lines in encounter order, replacing an
/// earlier line only when a later line owns the same RFC 10025 storage key.
/// Invalid cookie-pairs can only replace byte-identical lines.
fn collect_later_set_cookies(
    cookies: &mut Vec<String>,
    joined: &str,
    default_path: &str,
    request_is_secure: bool,
    request_host: Option<&str>,
    request_host_ip: Option<IpAddr>,
) {
    for candidate in joined.split('\n').filter(|candidate| !candidate.is_empty()) {
        if let Some(index) = cookies.iter().position(|existing| {
            existing == candidate
                || set_cookie_same_storage_key(
                    existing,
                    candidate,
                    default_path,
                    request_is_secure,
                    request_host,
                    request_host_ip,
                )
        }) {
            cookies.remove(index);
        }
        cookies.push(candidate.to_string());
    }
}

fn set_cookie_conflicts(
    cookies: &[String],
    candidate: &str,
    default_path: &str,
    request_is_secure: bool,
    request_host: Option<&str>,
    request_host_ip: Option<IpAddr>,
) -> bool {
    cookies.iter().any(|existing| {
        existing == candidate
            || set_cookie_same_storage_key(
                existing,
                candidate,
                default_path,
                request_is_secure,
                request_host,
                request_host_ip,
            )
    })
}

/// Stage requester-owned cookies from rejecting auth attempts. This remains on
/// the rejection path: successful authentication only removes the metadata.
pub(crate) fn stage_auth_rejection_set_cookie(ctx: &mut RequestContext, cookie: String) {
    let default_path = default_set_cookie_path(&ctx.path);
    let can_store_secure_cookie = request_can_store_secure_cookie(ctx);
    let request_host = set_cookie_request_host(ctx.request_authority.as_deref());
    let request_host_ip = set_cookie_request_host_ip(request_host);
    let mut staged = Vec::new();
    if let Some(existing) = ctx.metadata.get(AUTH_REJECTION_SET_COOKIE_METADATA_KEY) {
        collect_later_set_cookies(
            &mut staged,
            existing,
            default_path,
            can_store_secure_cookie,
            request_host,
            request_host_ip,
        );
    }
    collect_later_set_cookies(
        &mut staged,
        &cookie,
        default_path,
        can_store_secure_cookie,
        request_host,
        request_host_ip,
    );

    if staged.is_empty() {
        ctx.metadata.remove(AUTH_REJECTION_SET_COOKIE_METADATA_KEY);
    } else {
        ctx.metadata.insert(
            AUTH_REJECTION_SET_COOKIE_METADATA_KEY.to_string(),
            staged.join("\n"),
        );
    }
}

fn attach_auth_rejection_set_cookie(
    ctx: &mut RequestContext,
    headers: &mut HashMap<String, String>,
) {
    let Some(staged) = ctx.metadata.remove(AUTH_REJECTION_SET_COOKIE_METADATA_KEY) else {
        return;
    };
    let default_path = default_set_cookie_path(&ctx.path);
    let can_store_secure_cookie = request_can_store_secure_cookie(ctx);
    let request_host = set_cookie_request_host(ctx.request_authority.as_deref());
    let request_host_ip = set_cookie_request_host_ip(request_host);

    // A custom plugin can return multiple case variants because rejection
    // headers use a String-keyed HashMap. Sort the variants by their exact key
    // before merging so randomized HashMap iteration cannot select ownership.
    // The canonical lowercase key sorts after uppercase variants and therefore
    // wins same-name conflicts deterministically.
    let mut selected_variants = headers
        .iter()
        .filter(|(name, _)| name.eq_ignore_ascii_case("set-cookie"))
        .map(|(name, value)| (name.clone(), value.clone()))
        .collect::<Vec<_>>();
    selected_variants.sort_unstable_by(|left, right| left.0.cmp(&right.0));
    headers.retain(|name, _| !name.eq_ignore_ascii_case("set-cookie"));

    let mut merged = Vec::new();
    for (_, value) in selected_variants {
        collect_later_set_cookies(
            &mut merged,
            &value,
            default_path,
            can_store_secure_cookie,
            request_host,
            request_host_ip,
        );
    }

    let mut staged_cookies = Vec::new();
    collect_later_set_cookies(
        &mut staged_cookies,
        &staged,
        default_path,
        can_store_secure_cookie,
        request_host,
        request_host_ip,
    );
    for candidate in staged_cookies {
        // The selected final rejection owns conflicts. Preserve each selected
        // line's full attributes and deterministic order, appending only
        // independently scoped requester-owned cookies from earlier rejects.
        if !set_cookie_conflicts(
            &merged,
            &candidate,
            default_path,
            can_store_secure_cookie,
            request_host,
            request_host_ip,
        ) {
            merged.push(candidate);
        }
    }
    if !merged.is_empty() {
        headers.insert("set-cookie".to_string(), merged.join("\n"));
    }
}

pub async fn run_authentication_phase(
    auth_mode: AuthMode,
    auth_plugins: &[Arc<dyn Plugin>],
    ctx: &mut RequestContext,
    consumer_index: &ConsumerIndex,
) -> Option<(u16, Vec<u8>, HashMap<String, String>)> {
    // Mark every configured query credential location before multi-auth can
    // stop at the first successful mechanism. Presence is enough to redact:
    // an invalid token may coexist with a different successful credential and
    // must not cross the OPA policy-service boundary.
    for auth_plugin in auth_plugins {
        auth_plugin.mark_query_credentials_for_redaction(ctx);
    }

    match auth_mode {
        AuthMode::Multi => {
            // Execute auth plugins; first success stops iteration.
            // Multi-auth success includes external identity auth (e.g. jwks_auth)
            // even when no gateway Consumer record exists.
            let mut last_reject: Option<(u16, Vec<u8>, HashMap<String, String>)> = None;
            let mut server_reject: Option<(u16, Vec<u8>, HashMap<String, String>)> = None;
            for auth_plugin in auth_plugins {
                let deadline = ctx.grpc_deadline_at();
                let auth_result = match crate::plugins::await_grpc_deadline(
                    deadline,
                    auth_plugin.authenticate(ctx, consumer_index),
                )
                .await
                {
                    Ok(result) => result,
                    Err(()) => {
                        ctx.mark_gateway_deadline_response_selected();
                        let reject = crate::plugins::grpc_deadline_exceeded_plugin_result();
                        let Some(reject) = plugin_result_into_reject_parts(reject) else {
                            return Some((
                                500,
                                br#"{"error":"Internal error"}"#.to_vec(),
                                HashMap::new(),
                            ));
                        };
                        return Some((reject.status_code, reject.body, reject.headers));
                    }
                };
                match auth_result {
                    reject @ PluginResult::Reject { .. }
                    | reject @ PluginResult::RejectBinary { .. } => {
                        if let Some(reject) = plugin_result_into_reject_parts(reject) {
                            let reject = (reject.status_code, reject.body, reject.headers);
                            if reject.0 >= 500 {
                                if server_reject.is_none() {
                                    server_reject = Some(reject);
                                }
                            } else {
                                last_reject = Some(reject);
                            }
                        }
                    }
                    PluginResult::Continue => {
                        if request_is_authenticated(ctx) {
                            last_reject = None;
                            break;
                        }
                    }
                }
            }
            let mesh_permissive_only_auth_plugin = auth_plugins.len() == 1
                && ctx
                    .metadata
                    .get("mesh_request_auth.permissive_missing_token")
                    .is_some_and(|v| v == "true");
            if request_is_authenticated(ctx)
                || auth_plugins.is_empty()
                || (last_reject.is_none() && mesh_permissive_only_auth_plugin)
            {
                ctx.metadata.remove(AUTH_REJECTION_SET_COOKIE_METADATA_KEY);
                None
            } else {
                let mut reject = server_reject
                    .or(last_reject)
                    .unwrap_or_else(|| missing_authentication_reject(auth_plugins));
                attach_auth_rejection_set_cookie(ctx, &mut reject.2);
                Some(reject)
            }
        }
        AuthMode::Single => {
            for auth_plugin in auth_plugins {
                if request_is_authenticated(ctx) {
                    return None;
                }
                let deadline = ctx.grpc_deadline_at();
                match crate::plugins::await_request_plugin_deadline_with_provenance(
                    deadline,
                    auth_plugin.authenticate(ctx, consumer_index),
                )
                .await
                .into_plugin_result(ctx)
                {
                    reject @ PluginResult::Reject { .. }
                    | reject @ PluginResult::RejectBinary { .. } => {
                        if let Some(reject) = plugin_result_into_reject_parts(reject) {
                            let mut reject = (reject.status_code, reject.body, reject.headers);
                            attach_auth_rejection_set_cookie(ctx, &mut reject.2);
                            return Some(reject);
                        }
                    }
                    PluginResult::Continue => {
                        if request_is_authenticated(ctx) {
                            return None;
                        }
                    }
                }
            }
            let mesh_permissive_only_auth_plugin = auth_plugins.len() == 1
                && ctx
                    .metadata
                    .get("mesh_request_auth.permissive_missing_token")
                    .is_some_and(|v| v == "true");
            ctx.metadata.remove(AUTH_REJECTION_SET_COOKIE_METADATA_KEY);
            if request_is_authenticated(ctx)
                || auth_plugins.is_empty()
                || mesh_permissive_only_auth_plugin
            {
                None
            } else {
                Some(missing_authentication_reject(auth_plugins))
            }
        }
    }
}

/// Apply the original HTTP-family scheme reported by a directly connected
/// trusted proxy through either a singleton overwrite or an XFF-correlated
/// appended chain. The same accepted fact drives browser cookie storage checks,
/// authority normalization, and canonical frontend URL metadata consumed by
/// authentication plugins.
pub fn apply_trusted_forwarded_request_scheme(
    ctx: &mut RequestContext,
    socket_addr: &IpAddr,
    trusted_proxies: &client_ip::TrustedProxies,
) -> Option<&'static str> {
    let forwarded_scheme = client_ip::trusted_forwarded_request_scheme(
        socket_addr,
        ctx.raw_header_value_bytes("x-forwarded-for"),
        ctx.raw_header_value_bytes("x-forwarded-proto"),
        trusted_proxies,
    );
    if let Some(scheme) = forwarded_scheme {
        ctx.request_is_secure = scheme == "https";
        ctx.metadata
            .insert("ferrum.frontend_scheme".to_string(), scheme.to_string());
    }
    forwarded_scheme
}

/// Handle a single proxy request.
#[allow(dead_code)] // Public test/library entry point; listeners use the port-aware wrapper below.
pub async fn handle_proxy_request(
    req: Request<Incoming>,
    state: ProxyState,
    remote_addr: SocketAddr,
    is_tls: bool,
    tls_client_cert_der: Option<Arc<Vec<u8>>>,
    tls_client_cert_chain_der: Option<Arc<Vec<Vec<u8>>>>,
) -> Result<Response<ProxyBody>, hyper::Error> {
    let mtls_auth_connection_cache = tls_client_cert_der
        .as_ref()
        .map(|_| Arc::new(crate::plugins::mtls_auth::MtlsAuthConnectionCache::new()));
    let peer_spiffe_extraction_cache = tls_client_cert_der.as_ref().map(|_| {
        Arc::new(crate::plugins::mesh::spiffe_identity::SpiffeIdentityConnectionCache::new())
    });
    handle_proxy_request_on_frontend_port(
        req,
        Arc::new(state),
        remote_addr,
        is_tls,
        tls_client_cert_der,
        tls_client_cert_chain_der,
        mtls_auth_connection_cache,
        RequestConnectionMetadata {
            peer_spiffe_extraction_cache,
            ..RequestConnectionMetadata::default()
        },
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn handle_proxy_request_on_frontend_port(
    req: Request<Incoming>,
    state: Arc<ProxyState>,
    remote_addr: SocketAddr,
    is_tls: bool,
    tls_client_cert_der: Option<Arc<Vec<u8>>>,
    tls_client_cert_chain_der: Option<Arc<Vec<Vec<u8>>>>,
    mtls_auth_connection_cache: Option<Arc<crate::plugins::mtls_auth::MtlsAuthConnectionCache>>,
    connection_metadata: RequestConnectionMetadata,
) -> Result<Response<ProxyBody>, hyper::Error> {
    // ACME HTTP-01 is answered ahead of overload admission on purpose: losing a
    // domain validation to load shedding costs a certificate. The lookup
    // resolves the *canonical* policy path (advisory GHSA-69xf-42xm-4w4f), so an
    // escaped-but-legal spelling of a live challenge cannot slip past the ACME
    // handler here and then fall through to routing under a different reading.
    // A refused or ambiguous target resolves to `None` and reaches the single
    // canonicalization boundary in `handle_proxy_request_inner`, which is the
    // only place a path is rejected.
    if req.method() == hyper::Method::GET
        && let Some(key_authorization) =
            crate::tls::acme::http01_key_authorization_for_path(req.uri().path())
    {
        record_request(&state, 200);
        return Ok(build_plain_text_response(
            StatusCode::OK,
            &key_authorization,
        ));
    }

    // Global request admission control. Single atomic load (~1ns) on the fast
    // path. Rejects with 503 when request pressure exceeds the critical
    // threshold (FERRUM_MAX_REQUESTS + FERRUM_OVERLOAD_REQ_CRITICAL_THRESHOLD)
    // OR when shutdown drain has begun (set by `overload::begin_drain` via
    // Release; loaded here with Acquire to synchronize-with that store and
    // also reject new H2/H3 streams on existing connections during drain).
    if state
        .overload
        .reject_new_requests
        .load(std::sync::atomic::Ordering::Acquire)
    {
        let is_grpc = grpc_proxy::is_grpc_request(&req);
        record_request(&state, 503);
        if is_grpc {
            return Ok(grpc_proxy::build_grpc_error_response(
                grpc_proxy::grpc_status::UNAVAILABLE,
                "Service overloaded",
            ));
        }
        return Ok(build_response(
            StatusCode::SERVICE_UNAVAILABLE,
            r#"{"error":"Service overloaded"}"#,
        ));
    }

    // Track this request for overload monitoring and graceful drain.
    // The guard is attached to the response body so it lives as long as hyper
    // is sending the response — critical for H2/gRPC streaming where the body
    // outlives this function scope.
    let request_guard = crate::overload::RequestGuard::new(&state.overload);

    let response = handle_proxy_request_inner(
        req,
        state,
        remote_addr,
        is_tls,
        tls_client_cert_der,
        tls_client_cert_chain_der,
        mtls_auth_connection_cache,
        connection_metadata,
    )
    .await;

    // Attach the guard to the response body so active_requests stays incremented
    // for the full response lifetime (including streaming bodies).
    response.map(|mut resp| {
        let body = std::mem::replace(resp.body_mut(), ProxyBody::empty());
        *resp.body_mut() = body.with_request_guard(request_guard);
        resp
    })
}

/// Inner implementation of [`handle_proxy_request`] — separated so the outer
/// function can attach the [`RequestGuard`] to the response body.
#[allow(clippy::too_many_arguments)]
async fn handle_proxy_request_inner(
    req: Request<Incoming>,
    state: Arc<ProxyState>,
    remote_addr: SocketAddr,
    is_tls: bool,
    tls_client_cert_der: Option<Arc<Vec<u8>>>,
    tls_client_cert_chain_der: Option<Arc<Vec<Vec<u8>>>>,
    mtls_auth_connection_cache: Option<Arc<crate::plugins::mtls_auth::MtlsAuthConnectionCache>>,
    connection_metadata: RequestConnectionMetadata,
) -> Result<Response<ProxyBody>, hyper::Error> {
    let start_time = Instant::now();

    let method = req.method().as_str().to_owned();
    let inbound_version = req.version();
    let is_hbone_connect = is_hbone_connect_request(&req, &state.env_config);
    // Datagram-over-HBONE CONNECT (F3 §3.3 Stage 4) — disjoint from the
    // byte-stream `is_hbone_connect` (different wire marker). EITHER shape is a
    // CONNECT-relay for the shared dispatch machinery (path normalization,
    // body-buffering avoidance, route-miss relay synthesis, CONNECT-405 bypass),
    // so the combined `is_hbone_connect_any` drives those; the `udp` flavor is
    // routed to the unframing UDP handler at the final dispatch branch.
    let is_udp_hbone_connect = is_udp_hbone_connect_request(&req, &state.env_config);
    let is_hbone_connect_any = is_hbone_connect || is_udp_hbone_connect;
    let raw_path = req.uri().path();
    let path = if is_hbone_connect_any && raw_path.is_empty() {
        "/".to_string()
    } else {
        raw_path.to_string()
    };
    let query_string = req.uri().query().unwrap_or("").to_string();

    let socket_ip = canonicalize_client_ip(remote_addr.ip()).to_string();

    // Build request context — pass cloned socket_ip to ctx (client_ip may be
    // overwritten by trusted-proxy resolution below). method and path keep
    // separate ownership for use in backend URL building and logging.
    let mut ctx = RequestContext::new(socket_ip.clone(), method.clone(), path.clone());
    // Carry the operator's response-body ceiling so the buffered representation
    // gate bounds its decompression by the same limit the wire path enforces.
    ctx.max_response_body_size_bytes = state.max_response_body_size_bytes;
    let mut request_scheme = if is_tls { "https" } else { "http" };
    ctx.request_is_secure = is_tls;
    ctx.metadata.insert(
        "ferrum.frontend_scheme".to_string(),
        request_scheme.to_string(),
    );
    ctx.frontend_listen_port = Some(connection_metadata.frontend_listen_port.unwrap_or(
        if is_tls {
            state.env_config.proxy_https_port
        } else {
            state.env_config.proxy_http_port
        },
    ));
    ctx.frontend_sni_hostname = connection_metadata.frontend_sni_hostname;
    ctx.mesh_direction = connection_metadata.mesh_direction;
    ctx.orig_dst = connection_metadata.orig_dst;
    let mesh_inbound_pre_handshake_app_port =
        connection_metadata.mesh_inbound_pre_handshake_app_port;
    ctx.tls_client_cert_der = tls_client_cert_der;
    ctx.tls_client_cert_chain_der = tls_client_cert_chain_der;
    ctx.mtls_auth_connection_cache = mtls_auth_connection_cache;
    ctx.peer_spiffe_extraction_cache = connection_metadata.peer_spiffe_extraction_cache;
    if let Some(identity) = connection_metadata.node_waypoint_identity {
        // In node-waypoint topology, the node-agent/eBPF cookie-derived pod
        // identity is the authenticated source workload for policy. It
        // intentionally pre-populates `peer_spiffe_id` so mesh authz and the
        // SPIFFE identity plugin consume the pod identity instead of baggage or
        // future TLS-peer derivation on this listener.
        ctx.peer_spiffe_id = Some(identity.spiffe_id.clone());
        ctx.node_waypoint_pod_uid = Some(identity.pod_uid);
        // GAP-2M.4: also resolve the per-pod PolicyScopeCache so mesh_authz
        // can filter slice-level policies by the source pod's identity
        // (namespace + labels) rather than relying on the proxy listener's
        // shared identity, which is meaningless on a multi-pod listener.
        //
        // Cost: one `ArcSwap::load` + two `HashMap::get`s on the
        // node-waypoint admit path. Cheap, paid once per request. The scope is
        // derived from the same slice generation that vouches the pod's
        // identity, so a `None` here means the pod's workload has left the live
        // slice (removed/re-keyed), not an enrollment race: `mesh_authz` stamps
        // `mesh_authz.scope_missing` and fails closed (403) when scoped policies
        // exist, else evaluates mesh-wide-only. Re-queried per request so a
        // workload removed mid-connection stops being served under scoped authz.
        // When mesh_authz is not configured the stamped field is unused and
        // propagates harmlessly.
        if let Some(resolver) = state.node_waypoint_identity_resolver.as_ref() {
            ctx.node_waypoint_policy_scope = resolver.policy_scope_for_pod(&identity.pod_uid);
        }
    }
    // Store raw query string on ctx for lazy parsing. The local `query_string`
    // is kept for validation + URL building; the ctx copy is consumed by
    // materialize_query_params() when plugins need the parsed HashMap.
    ctx.set_raw_query_string(query_string.clone());
    // Validate header sizes without materializing headers into owned Strings.
    // The raw HeaderMap is stored on ctx for deferred materialization — the full
    // HashMap<String, String> is only built when a plugin phase or backend
    // dispatch actually needs it (saving ~20-60 String allocations per request
    // on early-reject paths and deferring them past routing on the happy path).
    let mut total_header_size: usize = 0;
    for (name, value) in req.headers() {
        let header_size = name.as_str().len() + value.len();
        if header_size > state.max_single_header_size_bytes {
            record_request(&state, 431);
            // Escape header name to prevent JSON injection from client-controlled data.
            // Use serde_json to produce a correctly escaped JSON string value,
            // which handles backslash, quotes, and all control characters.
            let escaped_name = serde_json::to_string(name.as_str())
                .unwrap_or_else(|_| "\"<invalid>\"".to_string());
            // escaped_name is a quoted JSON string like "\"foo\"", strip outer quotes for embedding
            let inner = &escaped_name[1..escaped_name.len() - 1];
            return Ok(build_response(
                StatusCode::REQUEST_HEADER_FIELDS_TOO_LARGE,
                &format!(
                    r#"{{"error":"Request header '{}' exceeds maximum size of {} bytes"}}"#,
                    inner, state.max_single_header_size_bytes
                ),
            ));
        }
        total_header_size += header_size;
    }
    if total_header_size > state.max_header_size_bytes {
        record_request(&state, 431);
        return Ok(build_response(
            StatusCode::REQUEST_HEADER_FIELDS_TOO_LARGE,
            r#"{"error":"Total request headers exceed maximum size"}"#,
        ));
    }
    if state.max_header_count > 0 && req.headers().len() > state.max_header_count {
        record_request(&state, 431);
        return Ok(build_response(
            StatusCode::REQUEST_HEADER_FIELDS_TOO_LARGE,
            &format!(
                r#"{{"error":"Request header count ({}) exceeds maximum of {}"}}"#,
                req.headers().len(),
                state.max_header_count
            ),
        ));
    }

    // Store raw headers for deferred materialization. The clone is a single
    // contiguous allocation (HeaderMap's internal Vec) — much cheaper than
    // N individual String allocations from the previous eager conversion.
    ctx.set_raw_headers(req.headers().clone());
    stamp_original_request_metadata(&mut ctx);

    // Validate URL length (path + query string)
    if state.max_url_length_bytes > 0 {
        let url_len = path.len()
            + if query_string.is_empty() {
                0
            } else {
                1 + query_string.len()
            };
        if url_len > state.max_url_length_bytes {
            record_request(&state, 414);
            return Ok(build_response(
                StatusCode::URI_TOO_LONG,
                &format!(
                    r#"{{"error":"Request URL length ({} bytes) exceeds maximum of {} bytes"}}"#,
                    url_len, state.max_url_length_bytes
                ),
            ));
        }
    }

    // Validate query parameter count (skip empty segments from consecutive '&').
    if state.max_query_params > 0 && !query_string.is_empty() {
        let param_count = count_query_params(&query_string);
        if param_count > state.max_query_params {
            record_request(&state, 400);
            return Ok(build_response(
                StatusCode::BAD_REQUEST,
                &format!(
                    r#"{{"error":"Query parameter count ({}) exceeds maximum of {}"}}"#,
                    param_count, state.max_query_params
                ),
            ));
        }
    }

    // Protocol-level header validation to prevent request smuggling and desync attacks.
    // Must run before routing because these are transport-level violations that apply
    // regardless of which backend the request would be forwarded to.
    if let Some(error_body) = check_protocol_headers(req.headers(), req.version()) {
        warn!("Rejected request: {}", error_body);
        record_request(&state, 400);
        return Ok(build_response(StatusCode::BAD_REQUEST, error_body));
    }

    if let Some(error_body) =
        check_host_authority_consistency(req.headers(), req.uri(), req.version())
    {
        warn!("Rejected request: {}", error_body);
        record_request(&state, 400);
        return Ok(build_response(StatusCode::BAD_REQUEST, error_body));
    }

    // Classify before the canonical-path boundary so a refusal uses the
    // client's wire representation. WebSocket Upgrade / Extended CONNECT wins
    // over any hostile Content-Type, matching backend dispatch and the H3
    // frontend.
    let flavor = crate::proxy::backend_dispatch::detect_http_flavor(&req);
    let request_uses_grpc_content_type = flavor == HttpFlavor::Grpc;
    let grpc_web_response_content_type_owned = if flavor == HttpFlavor::WebSocket {
        None
    } else {
        req.headers()
            .get(hyper::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok())
            .and_then(|content_type| {
                if !crate::plugins::grpc_web::is_grpc_web_content_type(content_type) {
                    return None;
                }
                let negotiated =
                    crate::plugins::grpc_web::negotiate_response_media_type_from_headers(
                        content_type,
                        req.headers(),
                        state.max_header_size_bytes,
                    );
                Some(negotiated.unwrap_or_else(|_| {
                    crate::plugins::grpc_web::response_content_type(content_type)
                }))
            })
    };
    let grpc_web_request = grpc_web_response_content_type_owned.is_some();
    let grpc_web_response_content_type = grpc_web_response_content_type_owned.as_deref();
    // Retain the representation just classified, exactly as the H3 frontend
    // does right after it builds its context. Without this the marker existed
    // only when the `grpc_web` plugin was configured, so an H1/H2 PASS-THROUGH
    // deployment — the backend speaks gRPC-Web itself and the translator is
    // deliberately absent — left `client_grpc_framing_representation` with
    // nothing to read. A backend that omits `Content-Type` (or a response hook
    // that strips it) then reached the buffered representation gate as untyped
    // JSON, and valid gRPC-Web frames were replaced with a `502` whenever a
    // response body rule was configured. The classification is taken from the
    // immutable inbound content-type before any hook runs, so it records the
    // client's own representation and never a rewritten one.
    if let Some(content_type) = grpc_web_response_content_type {
        crate::plugins::grpc_web::retain_negotiated_response_content_type(&mut ctx, content_type);
    }

    // Canonical policy path (advisory GHSA-69xf-42xm-4w4f). Runs after the
    // transport-level checks above — which bound the work by the operator's
    // URL-length limit and settle smuggling/authority questions first — and
    // before routing, every plugin phase, and backend dispatch, so no
    // protected surface ever observes a non-canonical target. An ambiguous
    // target is refused here rather than resolved to one of its readings.
    //
    // `path` and `ctx.path` are the only path coordinates the rest of this
    // handler uses (backend URL building reads the local `path`; plugins read
    // `ctx.path`), so rebinding both here is what makes policy and the wire
    // agree. Nothing between `RequestContext::new` and this point inspects the
    // path.
    // `None` means the target was already canonical, so nothing is rebound and
    // nothing is allocated — the case for the overwhelming majority of traffic.
    let canonicalized_path = match crate::policy_path::canonicalize_policy_path(&path) {
        Ok(std::borrow::Cow::Borrowed(_)) => None,
        Ok(std::borrow::Cow::Owned(canonical)) => Some(canonical),
        Err(rejection) => {
            // The raw target is attacker-controlled: log only the fixed reason
            // token, never the bytes.
            warn!(
                reason = rejection.reason(),
                "Rejected request: ambiguous percent-encoded request path"
            );
            record_request(&state, 400);
            if let Some(content_type) = grpc_web_response_content_type {
                return Ok(build_grpc_web_error_response(
                    content_type,
                    grpc_proxy::grpc_status::INVALID_ARGUMENT,
                    rejection.grpc_message(),
                    &[],
                ));
            }
            if request_uses_grpc_content_type {
                return Ok(grpc_proxy::build_grpc_error_response(
                    grpc_proxy::grpc_status::INVALID_ARGUMENT,
                    rejection.grpc_message(),
                ));
            }
            return Ok(build_response(
                StatusCode::BAD_REQUEST,
                rejection.client_error_body(),
            ));
        }
    };
    let path = match canonicalized_path {
        Some(canonical) => {
            // Move the original target into the context for `hmac_auth`; the
            // canonical form replaces it everywhere else.
            let raw_path = std::mem::replace(&mut ctx.path, canonical.clone());
            ctx.set_raw_path_for_hmac(raw_path);
            canonical
        }
        None => path,
    };

    // Block TRACE method to prevent Cross-Site Tracing (XST) attacks.
    // TRACE echoes request headers (including cookies and auth tokens) in the
    // response body, which can be exploited to steal credentials.
    if method == "TRACE" {
        warn!("Rejected TRACE request");
        record_request(&state, 405);
        return Ok(build_response(
            StatusCode::METHOD_NOT_ALLOWED,
            r#"{"error":"TRACE method is not allowed"}"#,
        ));
    }

    // Block CONNECT method to prevent protocol confusion and tunneling attacks.
    // HTTP/1.1 CONNECT creates TCP tunnels (bypassing proxy controls).
    // HTTP/2 Extended CONNECT (RFC 8441) is only valid for WebSocket upgrades,
    // which are handled separately via is_h2_websocket_connect(). Non-WebSocket
    // CONNECT requests (e.g., :protocol = "h2c", "connect-udp") must be rejected
    // to prevent clients from using Extended CONNECT to bypass proxy routing.
    // Note: we enable_connect_protocol() on the h2 server to support WebSocket,
    // which means h2 will deliver Extended CONNECT requests to us — we must
    // filter non-WebSocket ones here before routing.
    if method == "CONNECT" && !is_h2_websocket_connect(&req) && !is_hbone_connect_any {
        warn!("Rejected non-WebSocket CONNECT request");
        record_request(&state, 405);
        return Ok(build_response(
            StatusCode::METHOD_NOT_ALLOWED,
            r#"{"error":"CONNECT method is not allowed"}"#,
        ));
    }
    if is_hbone_connect {
        hbone_proxy::tag_request_metadata(&mut ctx);
    } else if is_udp_hbone_connect {
        hbone_proxy::tag_udp_request_metadata(&mut ctx);
    }

    // TLS 1.3 0-RTT early data enforcement (RFC 8470).
    // On the HTTPS path, we detect early data via the `Early-Data: 1` header
    // that upstream proxies/CDNs add per RFC 8470. Direct-client 0-RTT detection
    // is not possible with the current rustls+tokio-rustls API (the early data
    // state is consumed during the handshake and not exposed afterwards).
    // HTTP/3 0-RTT is detected natively via quinn's into_0rtt() in the H3 path.
    if !state.early_data_methods.is_empty() {
        // Raw byte comparison avoids UTF-8 validation on the hot path.
        let is_early_data = req
            .headers()
            .get("early-data")
            .is_some_and(|v| v.as_bytes() == b"1");
        if is_early_data {
            ctx.is_early_data = true;
            if !state.early_data_methods.contains(&method) {
                let is_grpc = grpc_proxy::is_grpc_request(&req);
                warn!(
                    "Rejected 0-RTT request: method {} not in allowed early data methods",
                    method
                );
                record_request(&state, 425);
                if is_grpc {
                    return Ok(grpc_proxy::build_grpc_error_response(
                        grpc_proxy::grpc_status::UNAVAILABLE,
                        "Method not allowed in 0-RTT early data",
                    ));
                }
                return Ok(build_response(
                    StatusCode::TOO_EARLY,
                    r#"{"error":"Method not allowed in 0-RTT early data"}"#,
                ));
            }
        }
    }

    // Resolve real client IP using trusted proxy configuration.
    // Parse the socket IP once and reuse the parsed value to avoid redundant
    // parsing across the real-IP-header check and the XFF walk.
    // When no resolution changes the IP, we skip the allocation entirely —
    // ctx.client_ip was already set to socket_ip by RequestContext::new().
    // Uses the raw header accessors to read specific headers without
    // materializing the full HashMap — only 2-3 targeted lookups on the raw
    // HeaderMap. The configured real-IP header is read as ALL of its field
    // lines, never a single `get()`, so duplicate lines cannot hide a competing
    // attacker-supplied value (advisory GHSA-fx4w-68hx-mj7r).
    if !state.trusted_proxies.is_empty() {
        let socket_addr: Option<std::net::IpAddr> = socket_ip.parse().ok();
        if let Some(ref addr) = socket_addr {
            if let Some(forwarded_scheme) =
                apply_trusted_forwarded_request_scheme(&mut ctx, addr, &state.trusted_proxies)
            {
                request_scheme = forwarded_scheme;
            }
            let xff_chain = {
                let mut values = ctx.raw_header_values("x-forwarded-for");
                values.next().map(|first| {
                    let mut combined = String::from(first);
                    for value in values {
                        combined.push(',');
                        combined.push_str(value);
                    }
                    combined
                })
            };
            // Bound the immutable borrow of `ctx` (held by the field-line
            // iterator) to this statement so the assignment below can take a
            // mutable borrow.
            let resolved = client_ip::resolve_forwarded_client_ip(
                &socket_ip,
                addr,
                state
                    .env_config
                    .real_ip_header
                    .as_deref()
                    // real_ip_header is pre-lowercased at config load time — no allocation needed
                    .map(|name| ctx.header_field_lines(name))
                    .into_iter()
                    .flatten(),
                xff_chain.as_deref(),
                &state.trusted_proxies,
            );
            if let Some(resolved) = resolved {
                ctx.client_ip = resolved;
            }
        }
        // else: unparseable socket_ip, keep socket_ip (already set in ctx)
    }

    // Per-IP concurrent request limiting. The guard auto-decrements on drop,
    // covering all 30+ return paths without manual tracking.
    let per_ip_guard = if let Some(ref counts) = state.per_ip_request_counts {
        let current = {
            let count = counts
                .entry(ctx.client_ip.clone())
                .or_insert_with(|| AtomicU64::new(0));
            count.value().fetch_add(1, Ordering::Relaxed) + 1
        };
        let guard = Some(PerIpRequestGuard {
            ip: ctx.client_ip.clone(),
            counts: counts.clone(),
        });
        if current > state.max_concurrent_requests_per_ip {
            // Guard will be dropped immediately, decrementing the counter
            drop(guard);
            warn!(
                client_ip = %ctx.client_ip,
                concurrent = current,
                limit = state.max_concurrent_requests_per_ip,
                "Per-IP concurrent request limit exceeded"
            );
            record_request(&state, 429);
            return Ok(build_response(
                StatusCode::TOO_MANY_REQUESTS,
                r#"{"error":"Too many concurrent requests from this IP"}"#,
            ));
        }
        guard
    } else {
        None
    };

    // Extract request host for host-based routing.
    // HTTP/1.1 uses the Host header; HTTP/2 uses the :authority pseudo-header
    // (exposed via req.uri().authority()). Strip port if present and lowercase.
    // Uses raw_header_get() to avoid materializing the full HashMap.
    let raw_host = ctx
        .raw_header_get("host")
        .or_else(|| req.uri().authority().map(|a| a.as_str()));
    // One `split_request_authority` pass yields both the routing host (port
    // stripped, as before) and the request's EXPLICIT authority port —
    // consumed only by mesh inbound multi-port sibling selection below, where
    // a peer sidecar's egress rewrites the authority to carry the service
    // port. `is_valid_port` already bounded it to u16, so the parse is
    // infallible for any authority that got this far.
    let mut authority_port: Option<u16> = None;
    let request_host: Option<String> = match raw_host {
        Some(h) => match split_request_authority(h) {
            Some((host, port)) => {
                let normalized = normalize_authority_host(host);
                if normalized.is_empty() {
                    warn!("Rejected request: malformed Host/authority value");
                    record_request(&state, 400);
                    return Ok(build_response(
                        StatusCode::BAD_REQUEST,
                        r#"{"error":"Request contains malformed Host or authority"}"#,
                    ));
                }
                authority_port = port.and_then(|p| p.parse().ok());
                Some(normalized)
            }
            None => {
                warn!("Rejected request: malformed Host/authority value");
                record_request(&state, 400);
                return Ok(build_response(
                    StatusCode::BAD_REQUEST,
                    r#"{"error":"Request contains malformed Host or authority"}"#,
                ));
            }
        },
        None => None,
    };
    let request_authority = raw_host.and_then(|authority| {
        normalize_request_authority_for_signing(authority, Some(request_scheme))
    });
    ctx.request_authority = request_authority;

    let epoch = state.request_epoch.load();
    ctx.lb_generation = epoch.lb_generation;

    // Direct Pod-IP HTTP mesh egress is selected by captured original
    // destination before Host routing. The client-controlled Host header cannot
    // safely identify the destination service for a direct pod-IP dial.
    let direct_pod_ip_http_route = if should_use_direct_pod_ip_http_route(
        ctx.mesh_direction,
        ctx.node_waypoint_pod_uid.is_some(),
    ) {
        ctx.orig_dst.and_then(|orig_dst| {
            epoch
                .route_table
                .mesh_http_egress_by_workload_decision(orig_dst)
                .cloned()
        })
    } else {
        None
    };

    // Route: host + longest prefix match via router cache (O(1) cache hit, pre-sorted fallback)
    let route_match = match direct_pod_ip_http_route {
        Some(crate::router_cache::MeshHttpEgressByWorkloadDecision::Route {
            proxy,
            service_port,
        }) => {
            ctx.mesh_outbound_destination_authz_port = Some(service_port);
            Some(crate::router_cache::RouteMatch {
                proxy,
                path_params: Vec::new(),
                matched_prefix_len: 0,
            })
        }
        Some(crate::router_cache::MeshHttpEgressByWorkloadDecision::CloseNotRoutable) => {
            debug!(
                orig_dst = ?ctx.orig_dst,
                client_ip = %ctx.client_ip,
                "Direct Pod-IP HTTP mesh egress destination is declared but not routable; rejecting captured request"
            );
            state.request_count.fetch_add(1, Ordering::Relaxed);
            let response = build_pre_plugin_reject_response(
                StatusCode::BAD_GATEWAY,
                br#"{"error":"Original destination is not a mesh-routable direct workload HTTP destination"}"#,
                &EMPTY_HEADERS,
                request_uses_grpc_content_type,
                grpc_web_response_content_type,
            );
            record_status(&state, response.status().as_u16());
            return Ok(response);
        }
        None => state.router_cache.find_proxy_in_snapshot(
            &epoch.route_table,
            epoch.route_generation,
            request_host.as_deref(),
            &path,
        ),
    };

    // Materialized mesh routes (`__mesh-inbound-*` / `__mesh-outbound-*`) are
    // direction-scoped: the inbound and outbound capture listeners share one
    // route table, so each may serve only its own direction's routes. If the
    // cached winner is a mesh route whose direction does not match this request's
    // listener direction, re-resolve keeping only matching-direction routes — so
    // a peer's inbound request is not re-tunnelled out an outbound HBONE route,
    // and an app's outbound request is not shortcut to the local inbound loopback
    // (and neither 404s past a valid lower-priority route).
    let route_match = match route_match {
        Some(rm)
            if crate::modes::mesh::mesh_route_direction(&rm.proxy.id)
                .is_some_and(|route_dir| Some(route_dir) != ctx.mesh_direction) =>
        {
            state.router_cache.resolve_route_excluding_wrong_direction(
                &epoch.route_table,
                request_host.as_deref(),
                &path,
                ctx.mesh_direction,
            )
        }
        other => other,
    };

    // Mesh outbound multi-port disambiguation: host routing picked the
    // service (the route tiers hold one representative per outbound service);
    // the captured original-destination port now picks the per-port sibling.
    // Fails closed (502, like `hbone_required`) when the dialed port cannot
    // be determined for a multi-port service or is not a materialized
    // HTTP-family port — captured traffic is never forwarded to a port the
    // client did not dial. Single-port services keep their orig-dst-free
    // behavior, so direct dials (functional tests, non-Linux dev) are
    // unaffected.
    let route_match = match route_match {
        Some(rm)
            if ctx.mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Outbound)
                && crate::modes::mesh::is_mesh_outbound_route_id(&rm.proxy.id)
                && !crate::modes::mesh::is_mesh_outbound_http_bywl_route_id(&rm.proxy.id) =>
        {
            let representative_id = Arc::clone(&rm.proxy);
            match epoch
                .route_table
                .select_mesh_outbound_port_route_with_authz_port(
                    rm,
                    ctx.orig_dst.map(|addr| addr.port()),
                ) {
                Ok((rm, authz_port)) => {
                    ctx.mesh_outbound_destination_authz_port = authz_port;
                    Some(rm)
                }
                Err(reason) => {
                    debug!(
                        proxy_id = %representative_id.id,
                        orig_dst = ?ctx.orig_dst,
                        reason = ?reason,
                        client_ip = %ctx.client_ip,
                        "Mesh outbound port selection failed; rejecting captured request"
                    );
                    state.request_count.fetch_add(1, Ordering::Relaxed);
                    let body: &[u8] = match reason {
                        crate::router_cache::MeshOutboundPortSelectError::OrigDstUnavailable => {
                            br#"{"error":"Mesh outbound destination port is ambiguous without a captured original destination"}"#
                        }
                        crate::router_cache::MeshOutboundPortSelectError::PortNotMaterialized => {
                            br#"{"error":"Original destination port is not a mesh-routable port of this service"}"#
                        }
                    };
                    let response = build_pre_plugin_reject_response(
                        StatusCode::BAD_GATEWAY,
                        body,
                        &EMPTY_HEADERS,
                        request_uses_grpc_content_type,
                        grpc_web_response_content_type,
                    );
                    record_status(&state, response.status().as_u16());
                    return Ok(response);
                }
            }
        }
        other => other,
    };

    // Mesh inbound multi-port disambiguation — the inbound mirror of the
    // outbound arm above: host routing picked the local service (one
    // representative per service in the tiers); the captured original
    // destination (REDIRECT-captured plain inbound, container port) or the
    // request's explicit authority port (peer-sidecar dials, service port)
    // now picks the per-port loopback sibling. Multi-port requests carrying
    // neither signal — or a signal matching no materialized sibling — fail
    // closed with 502; single-port services are untouched. The synthesized
    // HBONE relay proxy shares the id prefix but is created post-route-miss
    // and never matches here.
    let route_match = match route_match {
        Some(rm)
            if ctx.mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Inbound)
                && crate::modes::mesh::is_mesh_inbound_route_id(&rm.proxy.id) =>
        {
            let representative_id = Arc::clone(&rm.proxy);
            match epoch.route_table.select_mesh_inbound_port_route(
                rm,
                ctx.orig_dst.map(|addr| addr.port()),
                authority_port,
            ) {
                Ok((rm, ingress_authz_port)) => {
                    // F6 §6.2 (security): for a Sidecar `ingress[]` route, stamp
                    // the DECLARED listener port so `mesh_authz` authorizes on it
                    // (not the `defaultEndpoint` backend port the route forwards
                    // to). `None` for service-port default inbound routes — they
                    // authorize on the backend/container port (Istio inbound
                    // authz). Stamped before the plugin chain runs.
                    ctx.mesh_inbound_listener_authz_port = ingress_authz_port;
                    Some(rm)
                }
                Err(reason) => {
                    debug!(
                        proxy_id = %representative_id.id,
                        orig_dst = ?ctx.orig_dst,
                        authority_port = ?authority_port,
                        reason = ?reason,
                        client_ip = %ctx.client_ip,
                        "Mesh inbound port selection failed; rejecting inbound request"
                    );
                    state.request_count.fetch_add(1, Ordering::Relaxed);
                    let body: &[u8] = match reason {
                        crate::router_cache::MeshInboundPortSelectError::PortSignalUnavailable => {
                            br#"{"error":"Mesh inbound destination port is ambiguous: the local service exposes multiple ports and the request carries no original destination or explicit authority port"}"#
                        }
                        crate::router_cache::MeshInboundPortSelectError::PortNotMaterialized => {
                            br#"{"error":"Request port is not a mesh-routable port of the local service"}"#
                        }
                    };
                    let response = build_pre_plugin_reject_response(
                        StatusCode::BAD_GATEWAY,
                        body,
                        &EMPTY_HEADERS,
                        request_uses_grpc_content_type,
                        grpc_web_response_content_type,
                    );
                    record_status(&state, response.status().as_u16());
                    return Ok(response);
                }
            }
        }
        other => other,
    };

    // Datagram-over-HBONE CONNECTs MUST always traverse the guarded inbound
    // relay-synthesis path, never an LB-backed HTTP/TCP route. The UDP handler
    // dials a local `UdpSocket` straight at the route's backend addr+port, so a
    // `udp`-marked CONNECT whose `:authority` happens to match a materialized
    // HTTP/TCP route would open a socket to that route's destination WITHOUT the
    // open-relay destination guard (`inbound_hbone_relay_destination_allowed`)
    // that `build_inbound_hbone_relay_proxy` applies. Forcing a route miss here
    // funnels every UDP CONNECT through that guard (which bounds the authority to
    // a loopback / slice-known workload addr+port) or a fail-closed 404 — the
    // same destination check the byte-stream relay's synthesis path enforces
    // (codex r5 P2). The byte-stream HBONE relay deliberately keeps matched-route
    // dispatch (VirtualService `mesh_route_dispatch` overrides ride it), so this
    // is scoped to the UDP variant only.
    let route_match = if is_udp_hbone_connect {
        None
    } else {
        route_match
    };

    let (proxy, strip_len) = match route_match {
        Some(rm) => {
            // Materialize headers now — path param injection writes to ctx.headers,
            // and all subsequent code (plugins, backend dispatch) needs the HashMap.
            // Requests that fail routing (404) skip this entirely, saving ~20-60
            // String allocations.
            ctx.materialize_headers();

            // Synthesize a `Host` entry from the HTTP/2 `:authority`
            // pseudo-header when the client sent only `:authority`. RFC 9113
            // §8.3.1 treats `:authority` as the Host equivalent for
            // forwarding, but hyper-server places it on `req.uri()` and
            // does not insert it into `req.headers()`. Without this
            // backfill, every downstream codepath that reads
            // `headers.get("host")` (backend Host emission with
            // `preserve_host_header=true`, X-Forwarded-Host, RFC 7239
            // `Forwarded`, plugins keyed on inbound host) sees `None`.
            // HTTP/1.1 mandates an explicit Host so this is effectively
            // an HTTP/2-only no-op for compliant H1 clients; we apply the
            // backfill unconditionally because the cost is one
            // `contains_key` + one optional insert and the rule is the
            // same across versions.
            //
            // When `preserve_host_header == false`, the per-route Host
            // override fires later in the dispatch path
            // (`proxy_to_backend` for plain HTTP, `proxy_to_backend_http2`
            // for the direct H2 pool, `proxy_grpc_request_core` /
            // `proxy_grpc_request_streaming` for gRPC,
            // `build_http3_backend_headers` for the H1/H2 → H3-native
            // backend dispatch) and replaces this synthetic value with the
            // upstream target's host — the existing semantics for
            // non-preserve mode are preserved.
            if !ctx.headers.contains_key("host")
                && let Some(authority) = req.uri().authority()
            {
                ctx.headers
                    .insert("host".to_string(), authority.as_str().to_string());
            }

            // Inject regex path parameters into context metadata and headers
            for (name, value) in &rm.path_params {
                ctx.metadata
                    .insert(format!("path_param.{}", name), value.clone());
                ctx.headers
                    .insert(format!("x-path-param-{}", name), value.clone());
            }
            (rm.proxy, rm.matched_prefix_len)
        }
        None => {
            // Ambient / Waypoint inbound HBONE terminators materialize NO
            // inbound routes — the relay is transparent: it dials the CONNECT
            // `:authority`, the original destination the mesh peer asked for.
            // An authenticated CONNECT to a safe local target therefore relays
            // through a synthesized proxy instead of 404ing. The synthesized
            // proxy is built only on the inbound listener (`mesh_direction ==
            // Inbound`) and only for a loopback / slice-known workload
            // destination, with loopback ports constrained to the slice's
            // declared workload application ports; `handle_hbone_request` /
            // `handle_hbone_udp_request` re-checks the authenticated-peer gate
            // before dialing. A datagram-over-HBONE CONNECT (`is_udp_hbone_connect`)
            // takes the SAME transparent-relay synthesis — the open-relay guard
            // (`inbound_hbone_relay_destination_allowed`) bounds the authority to
            // a loopback / slice-known workload addr+port the same way — and is
            // then routed to the UDP unframing handler at the dispatch branch.
            let hbone_relay = if is_hbone_connect_any
                && ctx.mesh_direction == Some(crate::modes::mesh::MeshTrafficDirection::Inbound)
            {
                build_inbound_hbone_relay_proxy(req.uri().authority(), epoch.config.mesh.as_deref())
            } else {
                None
            };
            match hbone_relay {
                Some(relay_proxy) => {
                    // Plugins (incl. the mesh global chain / `mesh_authz`) read
                    // `ctx.headers`, so materialize them before the chain runs.
                    ctx.materialize_headers();
                    (relay_proxy, 0)
                }
                None => {
                    // Outbound-capture route misses under effective
                    // REGISTRY_ONLY must take the same configured deny /
                    // metric path as the auto-injected
                    // `mesh_outbound_registry` plugin. Routing completes
                    // before the plugin chain, so without this gate an
                    // unknown destination would return a generic 404 and
                    // skip `FERRUM_MESH_OUTBOUND_REGISTRY_REJECT_STATUS`
                    // plus the fixed-cardinality deny counter. Inbound
                    // listeners and HBONE relay synthesis above are
                    // unchanged (capture-port Skip / inbound-only relay).
                    if let Some(listen_port) = ctx.frontend_listen_port
                        && let Some(enforcement) =
                            state.mesh_outbound_enforcement.load_full().as_ref()
                        && let Some(reject_status) = enforcement.http_route_miss_reject_status(
                            listen_port,
                            request_host.as_deref(),
                            authority_port,
                        )
                    {
                        debug!(
                            path = %path,
                            host = %request_host.as_deref().unwrap_or("<missing>"),
                            client_ip = %ctx.client_ip,
                            reject_status,
                            "Mesh REGISTRY_ONLY: rejecting outbound route miss for unadmitted destination"
                        );
                        state.request_count.fetch_add(1, Ordering::Relaxed);
                        let status =
                            StatusCode::from_u16(reject_status).unwrap_or(StatusCode::BAD_GATEWAY);
                        let body: &[u8] = if request_host.as_deref().is_none_or(|h| h.is_empty()) {
                            br#"{"error":"host header required"}"#
                        } else {
                            br#"{"error":"destination not in mesh registry (REGISTRY_ONLY policy)"}"#
                        };
                        let response = build_pre_plugin_reject_response(
                            status,
                            body,
                            &EMPTY_HEADERS,
                            request_uses_grpc_content_type,
                            grpc_web_response_content_type,
                        );
                        record_status(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    debug!(path = %path, client_ip = %ctx.client_ip, "No route matched for request path");
                    state.request_count.fetch_add(1, Ordering::Relaxed);
                    let response = build_pre_plugin_reject_response(
                        StatusCode::NOT_FOUND,
                        br#"{"error":"Not Found"}"#,
                        &EMPTY_HEADERS,
                        request_uses_grpc_content_type,
                        grpc_web_response_content_type,
                    );
                    record_status(&state, response.status().as_u16());
                    return Ok(response);
                }
            }
        }
    };

    ctx.matched_proxy = Some(Arc::clone(&proxy));
    ctx.proxy_lifecycle_generation = epoch
        .plugin_cache
        .proxy_lifecycle_generation(proxy.id.as_str());
    debug!(proxy_id = %proxy.id, method = %method, path = %path, client_ip = %ctx.client_ip, "Request routed to proxy");

    // Preserve the path the client actually requested before any plugin can
    // select a rewritten backend path. Upload-deadline rejection logging runs
    // before route overrides are applied, while normal transaction logging
    // below shares this same authoritative client-path snapshot.
    let original_request_path = path.clone();

    // Reuse the client-visible flavor and strict gRPC-Web classification made
    // before routing. In particular, WebSocket precedence must continue to
    // suppress gRPC-Web shaping for route-level rejects carrying a hostile
    // Content-Type.
    let is_h2_ws = is_h2_websocket_connect(&req);
    ctx.set_request_http_flavor(flavor);

    // Resolve the client-visible protocol before route-level rejects so every
    // post-routing synthesized initial HEADERS block uses the same precomputed
    // policy slice as normal responses. gRPC-Web dispatch remains plain HTTP
    // while selecting the gRPC policy set.
    let request_protocol = match flavor {
        HttpFlavor::WebSocket => ProxyProtocol::WebSocket,
        HttpFlavor::Grpc => ProxyProtocol::Grpc,
        HttpFlavor::Plain if grpc_web_request => ProxyProtocol::Grpc,
        HttpFlavor::Plain => ProxyProtocol::Http,
    };
    let plugin_cache_view = if grpc_web_request {
        epoch.plugin_cache.grpc_web_request_view(&proxy.id)
    } else {
        epoch.plugin_cache.request_view(&proxy.id, request_protocol)
    };
    let initial_response_header_policy_plugins =
        plugin_cache_view.initial_response_header_policy_plugins();
    let is_grpc_request = request_protocol == ProxyProtocol::Grpc;

    // Per-proxy HTTP method filtering (checked before plugins to save work).
    // Ordinary request hooks stay skipped, but terminal transaction logging
    // still runs from the protocol-filtered plugin-cache view so sinks can
    // attribute the matched-proxy 405.
    if let Some(ref allowed) = proxy.allowed_methods
        && !allowed.iter().any(|m| m.eq_ignore_ascii_case(&method))
    {
        state.request_count.fetch_add(1, Ordering::Relaxed);
        let allow_header = allowed.join(", ");
        let mut reject_headers = HashMap::new();
        reject_headers.insert("allow".to_string(), allow_header.clone());
        let mut reject = normalize_reject_response(
            StatusCode::METHOD_NOT_ALLOWED,
            br#"{"error":"Method Not Allowed"}"#,
            &reject_headers,
            is_grpc_request,
        );
        finalize_synthesized_reject_headers(
            &mut reject,
            request_protocol,
            initial_response_header_policy_plugins.as_ref(),
        );
        restore_authoritative_allow_header(&mut reject.headers, &allow_header);
        // Empty plugin list: do not run after_proxy / request hooks merely to
        // shape the response. Logging uses a separate immutable cache view.
        let grpc_web_response =
            build_grpc_web_reject_response(&[], &mut ctx, grpc_web_response_content_type, &reject)
                .await;
        // Metrics and transaction logs keep the admission status (405) even when
        // native gRPC reshapes the client-visible HTTP status to trailers-only
        // 200 + grpc-status.
        record_status(&state, StatusCode::METHOD_NOT_ALLOWED.as_u16());
        let logging_plugins = plugin_cache_view.plugins();
        log_pre_backend_rejected_request(
            &logging_plugins,
            &ctx,
            StatusCode::METHOD_NOT_ALLOWED.as_u16(),
            start_time,
            "allowed_methods",
            0,
        )
        .await;
        if let Some(response) = grpc_web_response {
            return Ok(response);
        }
        return Ok(build_response_from_normalized_reject(reject));
    }

    let allows_request_body_buffering = http_flavor_allows_request_body_buffering(flavor);
    if is_grpc_request {
        ctx.metadata
            .entry("request_protocol".to_string())
            .or_insert_with(|| "grpc".to_string());
    }

    // gRPC spec mandates POST method. Reject non-POST gRPC requests with a proper
    // gRPC trailers-only error rather than forwarding an invalid request to the backend.
    if is_grpc_request && method != "POST" {
        state.request_count.fetch_add(1, Ordering::Relaxed);
        warn!(method = %method, path = %path, "Rejected gRPC request: method must be POST");
        let mut reject = normalize_reject_response(
            StatusCode::BAD_REQUEST,
            br#"{"error":"gRPC requires POST method"}"#,
            &EMPTY_HEADERS,
            true,
        );
        finalize_synthesized_reject_headers(
            &mut reject,
            request_protocol,
            initial_response_header_policy_plugins.as_ref(),
        );
        let grpc_web_response =
            build_grpc_web_reject_response(&[], &mut ctx, grpc_web_response_content_type, &reject)
                .await;
        record_status(&state, reject.http_status.as_u16());
        if let Some(response) = grpc_web_response {
            return Ok(response);
        }
        return Ok(build_response_from_normalized_reject(reject));
    }

    // A mixed direct-listener posture may intentionally accept cert-less TLS
    // far enough to resolve the application port. Once the initial route has
    // supplied a concrete app port, enforce its PeerAuthentication mode before
    // any request plugin runs. Route overrides and load-balancer selection can
    // still change the destination later, so the authoritative post-plugin and
    // per-retry checks below remain required. An upstream template with port 0
    // has no concrete initial app port and is deferred to those later checks.
    if proxy.backend_port != 0
        && let Some(mismatch) = mesh_inbound_peer_auth_transport_mismatch(
            &state,
            ctx.mesh_direction,
            mesh_inbound_pre_handshake_app_port,
            &proxy,
            None,
            is_tls,
            ctx.tls_client_cert_der.is_some(),
        )
    {
        // Deliberately pass an empty plugin list: this is the pre-plugin trust
        // boundary, so neither after_proxy nor transaction-log plugin hooks may
        // run for a transport that the initial app-port policy has rejected.
        return Ok(reject_mesh_inbound_peer_auth_transport_mismatch(
            &state,
            &[],
            &mut ctx,
            &proxy,
            mismatch,
            is_tls,
            is_grpc_request,
            start_time,
            0,
            "mesh_inbound_peer_auth_initial_route_mismatch",
            None,
        )
        .await);
    }

    // Use the same request-scoped cache view selected above for normal request
    // handling. gRPC-Web is framed HTTP, so it uses the composed gRPC-Web view
    // that keeps HTTP guardrail plugins while retaining native gRPC policies
    // that explicitly opt in.

    // Get pre-resolved plugins filtered by protocol (O(1) lookup, no per-request filtering)
    let plugins = plugin_cache_view.plugins();
    ctx.set_request_headers_to_redact(plugin_cache_view.request_headers_to_redact());
    // Bind this request to the same cache generation's static response-side
    // presentation policy that the plugin list above will execute, so a plugin
    // persisting a finalized representation can prove which rules produced it.
    ctx.set_response_presentation_policy_digest(
        plugin_cache_view.response_presentation_policy_digest(),
    );
    // Establish the effective RPC budget before any request-plugin or body
    // await. The absolute instant is anchored to `timestamp_received` and is
    // carried independently of the relative header forwarded upstream.
    if is_grpc_request {
        let prepared = crate::plugins::grpc_deadline::prepare_request_deadline(
            plugin_cache_view.grpc_deadline_plugins(),
            &mut ctx,
        );
        if let reject @ (PluginResult::Reject { .. } | PluginResult::RejectBinary { .. }) = prepared
        {
            let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                record_request(&state, 500);
                return Ok(build_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    r#"{"error":"Internal error"}"#,
                ));
            };
            let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                &plugins,
                &mut ctx,
                StatusCode::from_u16(plugin_reject.status_code).unwrap_or(StatusCode::BAD_REQUEST),
                &plugin_reject.body,
                plugin_reject.headers,
                true,
                grpc_web_response_content_type.is_none(),
            )
            .await;
            apply_grpc_reject_metadata(&mut ctx, &reject);
            let grpc_web_response = build_grpc_web_reject_response(
                &plugins,
                &mut ctx,
                grpc_web_response_content_type,
                &reject,
            )
            .await;
            log_rejected_request(
                &plugins,
                &ctx,
                reject.http_status.as_u16(),
                start_time,
                "grpc_deadline_preflight",
                0,
            )
            .await;
            record_request(&state, reject.http_status.as_u16());
            if let Some(response) = grpc_web_response {
                return Ok(response);
            }
            return Ok(build_response_from_normalized_reject(reject));
        }
    }
    // Pre-computed capability bitset and phase-specific plugin lists — avoids
    // per-request `iter().filter().collect()` and `iter().any()` scans.
    let capabilities = plugin_cache_view.capabilities();
    let backend_path_plugins = plugin_cache_view.backend_path_plugins();
    let backend_path_is_policy_bound = !backend_path_plugins.is_empty();
    let mut client_request_body = ClientRequestBody::Streaming(Box::new(req));

    // Accumulator for total wall-clock time spent inside plugin phase callbacks.
    // Stored as nanoseconds in u64 to avoid floating-point precision loss across
    // many additions; converted to f64 milliseconds once when building the summary.
    let mut plugin_execution_ns: u64 = 0;

    // Execute on_request_received hooks (skip iteration when no plugins configured)
    if !plugins.is_empty() {
        let phase_start = Instant::now();
        for plugin in plugins.iter() {
            let deadline = ctx.grpc_deadline_at();
            match crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.on_request_received(&mut ctx),
            )
            .await
            .into_plugin_result(&mut ctx)
            {
                PluginResult::Continue => {}
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let plugin_reject = plugin_result_into_reject_parts(reject)
                        .expect("reject result should convert to rejection parts");
                    let status_code = plugin_reject.status_code;
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                    let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                        &plugins,
                        &mut ctx,
                        StatusCode::from_u16(status_code)
                            .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR),
                        &plugin_reject.body,
                        plugin_reject.headers,
                        is_grpc_request,
                        grpc_web_response_content_type.is_none(),
                    )
                    .await;
                    apply_grpc_reject_metadata(&mut ctx, &reject);
                    let grpc_web_response = build_grpc_web_reject_response(
                        &plugins,
                        &mut ctx,
                        grpc_web_response_content_type,
                        &reject,
                    )
                    .await;
                    log_rejected_request(
                        &plugins,
                        &ctx,
                        reject.http_status.as_u16(),
                        start_time,
                        "on_request_received",
                        plugin_execution_ns,
                    )
                    .await;
                    record_request(&state, reject.http_status.as_u16());
                    if let Some(response) = grpc_web_response {
                        return Ok(response);
                    }
                    return Ok(build_response_from_normalized_reject(reject));
                }
            }
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    // Materialize query params before authentication — key_auth and jwt_auth
    // may read query params for API key / token lookup. Deferred past routing
    // and on_request_received so plugin-less early rejects skip the work.
    ctx.materialize_query_params();

    // Some auth plugins (for example `hmac_auth`) verify request body integrity
    // at authenticate time. Buffer the body before the auth phase runs so those
    // plugins can read `ctx.request_body_bytes`.
    // HBONE CONNECT must keep hyper's upgrade handle in the streaming request
    // body. Pre-auth body buffering would consume it and make the relay fail.
    // WebSocket Extended CONNECT is also excluded: DATA frames after the 200
    // response are WebSocket bytes, not an HTTP request body to drain before
    // authentication.
    let consumer_index = ConsumerIndex::from_inner(Arc::clone(&epoch.consumer_index));
    let authenticate_body_requirements = if !is_hbone_connect_any
        && allows_request_body_buffering
        && capabilities.has(PluginCapabilities::HAS_BODY_BEFORE_AUTHENTICATE)
    {
        request_body_requirements_before_authenticate(&plugins, &ctx, &consumer_index)
    } else {
        RequestBodyPhaseRequirements::default()
    };

    if authenticate_body_requirements.required {
        client_request_body = match client_request_body {
            ClientRequestBody::Streaming(request) => {
                match buffer_request_body_for_before_proxy(
                    *request,
                    &method,
                    &ctx.headers,
                    effective_request_body_limit_for_protocol(
                        is_grpc_request,
                        state.max_request_body_size_bytes,
                        state.max_grpc_recv_size_bytes,
                        authenticate_body_requirements.plugin_limit,
                    ),
                    proxy.backend_read_timeout_ms,
                    ctx.grpc_deadline_at(),
                )
                .await
                {
                    Ok(buffered) => {
                        match &buffered {
                            ClientRequestBody::Buffered(buffered) => {
                                store_request_body_metadata(
                                    &mut ctx,
                                    &buffered.body,
                                    authenticate_body_requirements.needs_text,
                                    authenticate_body_requirements.needs_bytes,
                                    authenticate_body_requirements.needs_digests,
                                );
                                ctx.bytes_sent_observed.fetch_max(
                                    buffered.body.len() as u64,
                                    std::sync::atomic::Ordering::Release,
                                );
                            }
                            ClientRequestBody::Streaming(_) => {
                                // The buffering helper returns Streaming only
                                // when Incoming already reports END_STREAM, so
                                // seeding empty-body digests cannot race later
                                // H2 DATA. Retain the original empty stream for
                                // zero-copy backend forwarding.
                                store_request_body_metadata(
                                    &mut ctx,
                                    &[],
                                    false,
                                    false,
                                    authenticate_body_requirements.needs_digests,
                                );
                            }
                        }
                        buffered
                    }
                    Err(RequestBodyBufferError::TooLarge) => {
                        let response = build_request_body_too_large_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            effective_request_body_limit_for_protocol(
                                is_grpc_request,
                                state.max_request_body_size_bytes,
                                state.max_grpc_recv_size_bytes,
                                authenticate_body_requirements.plugin_limit,
                            ),
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::ClientDisconnected(error_message)) => {
                        error!(
                            proxy_id = %proxy.id,
                            path = %ctx.path,
                            error_kind = "client_disconnect",
                            error = %error_message,
                            "Client disconnected while buffering request body before authenticate"
                        );
                        record_request(&state, 499);
                        return Ok(build_response(
                            StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
                            r#"{"error":"Client disconnected"}"#,
                        ));
                    }
                    Err(RequestBodyBufferError::TimedOut) => {
                        let response = build_request_body_timeout_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::DeadlineExceeded) => {
                        let response = finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_upload_before_authenticate",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await;
                        return Ok(response);
                    }
                }
            }
            already_buffered => already_buffered,
        };
    }

    // Authentication phase (pre-computed auth plugin list — zero allocation)
    let auth_plugins = plugin_cache_view.auth_plugins();

    {
        let auth_phase_start = Instant::now();
        if let Some((status_code, body, headers)) = run_authentication_phase(
            proxy.auth_mode.clone(),
            &auth_plugins,
            &mut ctx,
            &consumer_index,
        )
        .await
        {
            plugin_execution_ns += auth_phase_start.elapsed().as_nanos() as u64;
            let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                &plugins,
                &mut ctx,
                StatusCode::from_u16(status_code).unwrap_or(StatusCode::UNAUTHORIZED),
                &body,
                headers,
                is_grpc_request,
                grpc_web_response_content_type.is_none(),
            )
            .await;
            apply_grpc_reject_metadata(&mut ctx, &reject);
            let grpc_web_response = build_grpc_web_reject_response(
                &plugins,
                &mut ctx,
                grpc_web_response_content_type,
                &reject,
            )
            .await;
            log_rejected_request(
                &plugins,
                &ctx,
                reject.http_status.as_u16(),
                start_time,
                "authenticate",
                plugin_execution_ns,
            )
            .await;
            record_request(&state, reject.http_status.as_u16());
            if let Some(response) = grpc_web_response {
                return Ok(response);
            }
            return Ok(build_response_from_normalized_reject(reject));
        }
        plugin_execution_ns += auth_phase_start.elapsed().as_nanos() as u64;
    }

    // Authorization plugins that need a body buffer only after identity has
    // been established. This keeps unauthenticated requests on the early
    // rejection path without collecting their bodies.
    let authorize_plugins = plugin_cache_view.authorize_plugins();
    let authorize_body_requirements =
        if capabilities.has(PluginCapabilities::HAS_BODY_BEFORE_AUTHORIZE) {
            request_body_requirements_before_authorize(&authorize_plugins, &ctx)
        } else {
            RequestBodyPhaseRequirements::default()
        };
    if authorize_body_requirements.required
        && !is_hbone_connect_any
        && allows_request_body_buffering
    {
        let body_limit = effective_request_body_limit_for_protocol(
            is_grpc_request,
            state.max_request_body_size_bytes,
            state.max_grpc_recv_size_bytes,
            authorize_body_requirements.plugin_limit,
        );
        client_request_body = match client_request_body {
            ClientRequestBody::Streaming(request) => {
                match buffer_request_body_for_before_proxy(
                    *request,
                    &method,
                    &ctx.headers,
                    body_limit,
                    proxy.backend_read_timeout_ms,
                    ctx.grpc_deadline_at(),
                )
                .await
                {
                    Ok(buffered) => {
                        if let ClientRequestBody::Buffered(buffered) = &buffered {
                            store_request_body_metadata(
                                &mut ctx,
                                &buffered.body,
                                authorize_body_requirements.needs_text,
                                authorize_body_requirements.needs_bytes,
                                authorize_body_requirements.needs_digests,
                            );
                            ctx.bytes_sent_observed.fetch_max(
                                buffered.body.len() as u64,
                                std::sync::atomic::Ordering::Release,
                            );
                        }
                        buffered
                    }
                    Err(RequestBodyBufferError::TooLarge) => {
                        let response = build_request_body_too_large_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            body_limit,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::ClientDisconnected(error_message)) => {
                        error!(
                            proxy_id = %proxy.id,
                            path = %ctx.path,
                            error_kind = "client_disconnect",
                            error = %error_message,
                            "Client disconnected while buffering request body before authorize"
                        );
                        record_request(&state, 499);
                        return Ok(build_response(
                            StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
                            r#"{"error":"Client disconnected"}"#,
                        ));
                    }
                    Err(RequestBodyBufferError::TimedOut) => {
                        let response = build_request_body_timeout_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::DeadlineExceeded) => {
                        let response = finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_upload_before_authorize",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await;
                        return Ok(response);
                    }
                }
            }
            ClientRequestBody::Buffered(buffered) => {
                if body_limit > 0 && buffered.body.len() > body_limit {
                    let response = build_request_body_too_large_response(
                        is_grpc_request,
                        grpc_web_response_content_type,
                        body_limit,
                        plugin_cache_view
                            .initial_response_header_policy_plugins()
                            .as_ref(),
                    );
                    record_request(&state, response.status().as_u16());
                    return Ok(response);
                }
                store_request_body_metadata(
                    &mut ctx,
                    &buffered.body,
                    authorize_body_requirements.needs_text,
                    authorize_body_requirements.needs_bytes,
                    authorize_body_requirements.needs_digests,
                );
                ClientRequestBody::Buffered(buffered)
            }
        };
    }

    // Authorization phase (pre-computed authorize plugin list — zero allocation)
    if !authorize_plugins.is_empty() {
        let phase_start = Instant::now();
        for plugin in authorize_plugins.iter() {
            let deadline = ctx.grpc_deadline_at();
            match crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.authorize(&mut ctx),
            )
            .await
            .into_plugin_result(&mut ctx)
            {
                PluginResult::Continue => {}
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let plugin_reject = plugin_result_into_reject_parts(reject)
                        .expect("reject result should convert to rejection parts");
                    let status_code = plugin_reject.status_code;
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                    let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                        &plugins,
                        &mut ctx,
                        StatusCode::from_u16(status_code).unwrap_or(StatusCode::FORBIDDEN),
                        &plugin_reject.body,
                        plugin_reject.headers,
                        is_grpc_request,
                        grpc_web_response_content_type.is_none(),
                    )
                    .await;
                    apply_grpc_reject_metadata(&mut ctx, &reject);
                    let grpc_web_response = build_grpc_web_reject_response(
                        &plugins,
                        &mut ctx,
                        grpc_web_response_content_type,
                        &reject,
                    )
                    .await;
                    log_rejected_request(
                        &plugins,
                        &ctx,
                        reject.http_status.as_u16(),
                        start_time,
                        "authorize",
                        plugin_execution_ns,
                    )
                    .await;
                    record_request(&state, reject.http_status.as_u16());
                    if let Some(response) = grpc_web_response {
                        return Ok(response);
                    }
                    return Ok(build_response_from_normalized_reject(reject));
                }
            }
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    let maybe_requires_request_body_buffering = plugin_cache_view.requires_request_body_buffering();
    // should_buffer_request_body is request-time (takes &RequestContext), so it
    // must still iterate. But the config-time capability checks use the bitset.
    // HBONE CONNECT requests must keep hyper's upgrade handle in the streaming
    // body (see `handle_hbone_request`), so pre-`before_proxy` buffering is
    // skipped — same reason as the pre-authenticate buffering guard above.
    let request_may_need_buffering = !is_hbone_connect_any
        && allows_request_body_buffering
        && maybe_requires_request_body_buffering;
    let has_terminal_body_dispatch = capabilities
        .has(crate::plugin_cache::PluginCapabilities::FINAL_BODY_BEFORE_BACKEND_DISPATCH);
    let has_contextual_final_body_hook =
        capabilities.has(crate::plugin_cache::PluginCapabilities::NEEDS_FINAL_REQUEST_BODY_CONTEXT);
    let (
        initial_requires_request_body_buffering,
        initial_final_body_before_backend_dispatch,
        initial_needs_final_request_body_context,
    ) = final_request_body_requirements(
        &plugins,
        &ctx,
        request_may_need_buffering,
        has_terminal_body_dispatch,
        has_contextual_final_body_hook,
    );
    let before_proxy_body_requirements = if initial_requires_request_body_buffering
        && capabilities.has(PluginCapabilities::HAS_BODY_BEFORE_BEFORE_PROXY)
    {
        request_body_requirements_before_before_proxy(&plugins, &ctx)
    } else {
        RequestBodyPhaseRequirements::default()
    };

    if before_proxy_body_requirements.required {
        let body_limit = effective_request_body_limit_for_protocol(
            is_grpc_request,
            state.max_request_body_size_bytes,
            state.max_grpc_recv_size_bytes,
            before_proxy_body_requirements.plugin_limit,
        );
        client_request_body = match client_request_body {
            ClientRequestBody::Streaming(request) => {
                match buffer_request_body_for_before_proxy(
                    *request,
                    &method,
                    &ctx.headers,
                    body_limit,
                    proxy.backend_read_timeout_ms,
                    ctx.grpc_deadline_at(),
                )
                .await
                {
                    Ok(buffered) => {
                        if let ClientRequestBody::Buffered(buffered) = &buffered {
                            store_request_body_metadata(
                                &mut ctx,
                                &buffered.body,
                                before_proxy_body_requirements.needs_text,
                                before_proxy_body_requirements.needs_bytes,
                                before_proxy_body_requirements.needs_digests,
                            );
                            // Seed bytes_sent_observed from the prebuffered
                            // body so before_proxy rejects (logged via
                            // `log_rejected_request`) surface the real on-wire
                            // size instead of 0. `fetch_max` is safe against
                            // later proxy_to_backend updates — the largest
                            // observed value always wins.
                            ctx.bytes_sent_observed.fetch_max(
                                buffered.body.len() as u64,
                                std::sync::atomic::Ordering::Release,
                            );
                        }
                        buffered
                    }
                    Err(RequestBodyBufferError::TooLarge) => {
                        let response = build_request_body_too_large_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            body_limit,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::ClientDisconnected(error_message)) => {
                        error!(
                            proxy_id = %proxy.id,
                            path = %ctx.path,
                            error_kind = "client_disconnect",
                            error = %error_message,
                            "Client disconnected while buffering request body before before_proxy"
                        );
                        record_request(&state, 499);
                        return Ok(build_response(
                            StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
                            r#"{"error":"Client disconnected"}"#,
                        ));
                    }
                    Err(RequestBodyBufferError::TimedOut) => {
                        let response = build_request_body_timeout_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::DeadlineExceeded) => {
                        let response = finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_upload_before_before_proxy",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await;
                        return Ok(response);
                    }
                }
            }
            ClientRequestBody::Buffered(buffered) => {
                if body_limit > 0 && buffered.body.len() > body_limit {
                    let response = build_request_body_too_large_response(
                        is_grpc_request,
                        grpc_web_response_content_type,
                        body_limit,
                        plugin_cache_view
                            .initial_response_header_policy_plugins()
                            .as_ref(),
                    );
                    record_request(&state, response.status().as_u16());
                    return Ok(response);
                }
                store_request_body_metadata(
                    &mut ctx,
                    &buffered.body,
                    before_proxy_body_requirements.needs_text,
                    before_proxy_body_requirements.needs_bytes,
                    before_proxy_body_requirements.needs_digests,
                );
                ClientRequestBody::Buffered(buffered)
            }
        };
    }

    // Opt-in buffered-body normalization (configured request decompression)
    // runs after the pre-`before_proxy` buffer is stored and before any
    // `before_proxy` hook, so earlier body consumers see validated plaintext.
    if capabilities.has(PluginCapabilities::NORMALIZES_BUFFERED_REQUEST_BODY_BEFORE_BEFORE_PROXY)
        && let ClientRequestBody::Buffered(buffered) = &mut client_request_body
    {
        let phase_start = Instant::now();
        let mut tmp_headers = std::mem::take(&mut ctx.headers);
        let normalize_result = apply_buffered_request_body_normalization_before_before_proxy(
            &plugins,
            &mut ctx,
            &mut tmp_headers,
            &mut buffered.body,
            before_proxy_body_requirements.needs_text,
            before_proxy_body_requirements.needs_bytes,
        )
        .await;
        ctx.headers = tmp_headers;
        match normalize_result {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                    error!("request-body normalization rejection could not be normalized");
                    record_request(&state, 500);
                    return Ok(build_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        r#"{"error":"Internal error"}"#,
                    ));
                };
                let status_code = plugin_reject.status_code;
                plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                    &plugins,
                    &mut ctx,
                    StatusCode::from_u16(status_code).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR),
                    &plugin_reject.body,
                    plugin_reject.headers,
                    is_grpc_request,
                    grpc_web_response_content_type.is_none(),
                )
                .await;
                apply_grpc_reject_metadata(&mut ctx, &reject);
                let grpc_web_response = build_grpc_web_reject_response(
                    &plugins,
                    &mut ctx,
                    grpc_web_response_content_type,
                    &reject,
                )
                .await;
                log_rejected_request(
                    &plugins,
                    &ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "normalize_buffered_request_body",
                    plugin_execution_ns,
                )
                .await;
                record_request(&state, reject.http_status.as_u16());
                if let Some(response) = grpc_web_response {
                    return Ok(response);
                }
                return Ok(build_response_from_normalized_reject(reject));
            }
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    // before_proxy hooks — only clone headers if at least one plugin modifies them.
    // When no plugin modifies headers, pass &mut ctx.headers directly to avoid
    // an expensive per-request HashMap clone on the hot path.
    let needs_header_clone = capabilities.has(PluginCapabilities::MODIFIES_REQUEST_HEADERS);
    let mut owned_proxy_headers: Option<HashMap<String, String>> = None;
    if needs_header_clone {
        let phase_start = Instant::now();
        let mut cloned = ctx.headers.clone();
        match run_before_proxy_hooks_for_backend_path_policy(
            &plugins,
            &mut ctx,
            &mut cloned,
            backend_path_is_policy_bound,
            BackendPathBeforeProxyPass::Initial,
        )
        .await
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                    error!("before_proxy rejection could not be normalized");
                    record_request(&state, 500);
                    return Ok(build_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        r#"{"error":"Internal error"}"#,
                    ));
                };
                let status_code = plugin_reject.status_code;
                plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                    &plugins,
                    &mut ctx,
                    StatusCode::from_u16(status_code).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR),
                    &plugin_reject.body,
                    plugin_reject.headers,
                    is_grpc_request,
                    grpc_web_response_content_type.is_none(),
                )
                .await;
                apply_grpc_reject_metadata(&mut ctx, &reject);
                let grpc_web_response = build_grpc_web_reject_response(
                    &plugins,
                    &mut ctx,
                    grpc_web_response_content_type,
                    &reject,
                )
                .await;
                log_rejected_request(
                    &plugins,
                    &ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "before_proxy",
                    plugin_execution_ns,
                )
                .await;
                record_request(&state, reject.http_status.as_u16());
                if let Some(response) = grpc_web_response {
                    return Ok(response);
                }
                return Ok(build_response_from_normalized_reject(reject));
            }
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
        owned_proxy_headers = Some(cloned);
    } else if !plugins.is_empty() {
        // Run before_proxy hooks that don't modify headers (e.g., body_validator).
        // No plugin modifies headers, so swap headers out of ctx temporarily to
        // satisfy the borrow checker without cloning — zero allocation hot path.
        let phase_start = Instant::now();
        let mut tmp_headers = std::mem::take(&mut ctx.headers);
        match run_before_proxy_hooks_for_backend_path_policy(
            &plugins,
            &mut ctx,
            &mut tmp_headers,
            backend_path_is_policy_bound,
            BackendPathBeforeProxyPass::Initial,
        )
        .await
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                    error!("before_proxy rejection could not be normalized");
                    ctx.headers = tmp_headers;
                    record_request(&state, 500);
                    return Ok(build_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        r#"{"error":"Internal error"}"#,
                    ));
                };
                let status_code = plugin_reject.status_code;
                plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                ctx.headers = tmp_headers;
                let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                    &plugins,
                    &mut ctx,
                    StatusCode::from_u16(status_code).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR),
                    &plugin_reject.body,
                    plugin_reject.headers,
                    is_grpc_request,
                    grpc_web_response_content_type.is_none(),
                )
                .await;
                apply_grpc_reject_metadata(&mut ctx, &reject);
                let grpc_web_response = build_grpc_web_reject_response(
                    &plugins,
                    &mut ctx,
                    grpc_web_response_content_type,
                    &reject,
                )
                .await;
                log_rejected_request(
                    &plugins,
                    &ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "before_proxy",
                    plugin_execution_ns,
                )
                .await;
                record_request(&state, reject.http_status.as_u16());
                if let Some(response) = grpc_web_response {
                    return Ok(response);
                }
                return Ok(build_response_from_normalized_reject(reject));
            }
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
        ctx.headers = tmp_headers;
    }

    // A header-transforming before_proxy hook can change the applicability of
    // body plugins (for example, text/plain -> application/json). Re-evaluate
    // against the effective outbound headers before choosing terminal versus
    // backend dispatch. Swap maps temporarily to avoid another full clone.
    let (
        requires_request_body_buffering,
        final_body_before_backend_dispatch,
        needs_final_request_body_context,
    ) = if let Some(transformed_headers) = owned_proxy_headers.as_mut() {
        std::mem::swap(&mut ctx.headers, transformed_headers);
        let requirements = final_request_body_requirements(
            &plugins,
            &ctx,
            request_may_need_buffering,
            has_terminal_body_dispatch,
            has_contextual_final_body_hook,
        );
        std::mem::swap(&mut ctx.headers, transformed_headers);
        requirements
    } else {
        (
            initial_requires_request_body_buffering,
            initial_final_body_before_backend_dispatch,
            initial_needs_final_request_body_context,
        )
    };

    // HBONE CONNECT short-circuits the rest of the dispatch ladder: the relay
    // is a transparent TCP tunnel, so identity-header injection, egress
    // baggage strip on `owned_proxy_headers`, the WS/gRPC branches, and the
    // HTTP backend pool selection below are all unreachable for it. We branch
    // here — after `before_proxy` — so plugins like `mesh_route_dispatch` get
    // to run and set `route_override_*` on the outer CONNECT request; the
    // HBONE handler then consumes those via `apply_route_overrides_with_upstreams`
    // before backend connect, mirroring the H1/H2/H3 dispatch contract.
    if is_hbone_connect {
        return Ok(hbone_proxy::handle_hbone_request(
            &state,
            &proxy,
            &epoch,
            &mut ctx,
            is_tls,
            mesh_inbound_pre_handshake_app_port,
            client_request_body,
            &plugins,
            start_time,
            &method,
            plugin_execution_ns,
        )
        .await);
    }
    // Datagram-over-HBONE CONNECT (F3 §3.3 Stage 4): same short-circuit as the
    // byte-stream HBONE relay, but the destination side UNFRAMES the tunnel into
    // a local `UdpSocket` toward the CONNECT authority instead of byte-relaying
    // to a TCP backend.
    if is_udp_hbone_connect {
        return Ok(hbone_proxy::handle_hbone_udp_request(
            &state,
            &proxy,
            &epoch,
            &mut ctx,
            is_tls,
            mesh_inbound_pre_handshake_app_port,
            client_request_body,
            &plugins,
            start_time,
            &method,
            plugin_execution_ns,
        )
        .await);
    }

    // Strip plugin-controlled gateway assertions and inject only the
    // authenticated principal and private GeoIP result. The common
    // no-assertion path avoids materializing an owned header map.
    let effective_headers = owned_proxy_headers.as_ref().unwrap_or(&ctx.headers);
    let source_has_reserved_assertion = effective_headers.keys().any(|name| {
        name.eq_ignore_ascii_case("x-consumer-username")
            || name.eq_ignore_ascii_case("x-consumer-custom-id")
            || name.eq_ignore_ascii_case("x-geo-country")
    });
    if ctx.backend_consumer_username().is_some()
        || ctx.backend_geo_country().is_some()
        || source_has_reserved_assertion
    {
        let headers = owned_proxy_headers.get_or_insert_with(|| ctx.headers.clone());
        refresh_backend_gateway_assertion_headers(&ctx, headers);
    }
    // Egress baggage strip — operator-configured key prefixes are removed
    // from the outbound `baggage` header. Default empty list is a no-op.
    // Controlled by `FERRUM_MESH_EGRESS_STRIP_BAGGAGE_KEYS`. This handles the
    // reqwest / direct-H2 / cross-protocol-H3 / gRPC dispatch paths that
    // consume `proxy_headers`. The native HTTP/3 frontend
    // (`src/http3/server.rs`) and WebSocket handshake (`src/proxy/mod.rs`
    // `handle_websocket_request_authenticated`) build their backend headers
    // from independent sources and call the same helper at their own egress
    // boundaries — keep all three call sites in sync.
    hbone_proxy::strip_egress_baggage_in_proxy_headers(
        &mut owned_proxy_headers,
        &ctx.headers,
        &state.mesh_egress_strip_baggage_keys,
    );
    let stream_hooks_enabled = plugin_cache_view.requires_response_stream_hooks();
    let maybe_requires_response_body_buffering =
        plugin_cache_view.requires_response_body_buffering();

    // Request-body transforms can change the per-request response policy (most
    // notably `stream: true`). When either response buffering or streaming
    // inspection is configured, finalize the already-required buffered request
    // body before selecting a backend transport. The two PluginCache flags keep
    // the ordinary no-body-policy path unchanged: no extra scan, clone, collect,
    // or hook pass.
    let reevaluate_response_policy_after_request_body = !is_grpc_request
        && requires_request_body_buffering
        && (maybe_requires_response_body_buffering || stream_hooks_enabled);
    let mut request_body_prepared = false;
    // The config-time capability above avoids a full scan when no contextual
    // final-body hook is configured. The request-time value also requires that
    // same plugin's body-applicability predicate to match, avoiding an unrelated
    // body plugin triggering a context clone.
    // Provider-dispatch plugins synthesize the complete response from the
    // finalized request body. The config-time bit above avoids extra work when
    // none are configured; the request-time value is true only when that same
    // terminal plugin's `should_buffer_request_body` matched this request.
    let effective_query_string = query_string_after_plugin_strips(&ctx, &query_string);

    // Apply plugin-set route overrides (e.g., `mesh_route_dispatch` from an
    // Istio VirtualService header/method match). When no overrides are set,
    // this is an `Arc::clone` — no per-request allocation. When overrides
    // are set, the override values are baked into a fresh `Arc<Proxy>` so
    // downstream pool keys, capability-registry lookups, URL construction,
    // and circuit-breaker target keys all derive from the effective
    // destination (pool-poisoning invariant).
    let proxy = ctx.apply_route_overrides_with_upstreams(proxy, epoch.load_balancer.upstreams());
    ctx.matched_proxy = Some(Arc::clone(&proxy));
    ctx.proxy_lifecycle_generation = epoch
        .plugin_cache
        .proxy_lifecycle_generation(proxy.id.as_str());

    // Istio `VirtualService.http[].rewrite.uri`: `mesh_route_dispatch` set
    // `ctx.route_override_path` for the matched route. Rebase the request path
    // used for backend URL building (reqwest / direct-H2 / gRPC paths read the
    // local `path`; the WS / HBONE branches read `ctx.path`, so mirror the
    // override onto `ctx.path` too). The original path was already used for
    // route selection; VS-derived proxies never set `strip_listen_path`, so
    // the rewritten value is the literal forwarded path. No allocation when no
    // rewrite is set.
    let path = match ctx.route_override_path.take() {
        Some(rewritten) => {
            ctx.path = rewritten.clone();
            rewritten
        }
        None => path,
    };

    // Resolve upstream target and hash key from the request epoch.
    // `ctx.orig_dst` (the captured SO_ORIGINAL_DST on mesh capture listeners)
    // enables true PASSTHROUGH load balancing when the upstream's algorithm is
    // Passthrough; it is ignored for every other algorithm.
    let selection = backend_dispatch::select_upstream_target(
        &proxy,
        &state,
        &epoch,
        &ctx.client_ip,
        owned_proxy_headers.as_ref().unwrap_or(&ctx.headers),
        ctx.orig_dst,
    );
    let lb_hash_key = selection.lb_hash_key;
    let upstream_target = backend_dispatch::concretize_wildcard_target_for_request(
        selection.target,
        request_host.as_deref(),
    );

    let has_deferred_routing_header_hooks = backend_path_is_policy_bound
        && capabilities.has(PluginCapabilities::HAS_DEFERRED_ROUTING_HEADER_HOOKS);
    let mut deferred_result = PluginResult::Continue;
    // The selected target is pinned before deferred routing-header hooks run,
    // so enforce its backend-effective path before those hooks can perform
    // external work. This also ensures an exhausted method rate limit rejects
    // before a pre-proxy serverless function is invoked.
    if backend_path_is_policy_bound {
        let backend_path = build_backend_effective_path(
            &proxy,
            &path,
            strip_len,
            upstream_target
                .as_ref()
                .and_then(|target| target.path.as_deref()),
        );
        if let Some(response) = run_backend_path_plugins_or_build_reject(
            backend_path_plugins,
            &plugins,
            &mut ctx,
            &backend_path,
            &state,
            start_time,
            &mut plugin_execution_ns,
            &original_request_path,
            is_grpc_request,
            grpc_web_response_content_type,
        )
        .await
        {
            return Ok(response);
        }
        ctx.bind_authorized_backend_path(backend_path);
    }

    if has_deferred_routing_header_hooks {
        // These hooks moved later for authorization ordering, but their
        // documented request view remains the original client path.
        let backend_ctx_path = std::mem::replace(&mut ctx.path, original_request_path.clone());
        let phase_start = Instant::now();
        deferred_result = match owned_proxy_headers.as_mut() {
            Some(headers) => {
                run_before_proxy_hooks_for_backend_path_policy(
                    &plugins,
                    &mut ctx,
                    headers,
                    true,
                    BackendPathBeforeProxyPass::RoutingHeaderDeferred,
                )
                .await
            }
            None => {
                let mut headers = std::mem::take(&mut ctx.headers);
                let result = run_before_proxy_hooks_for_backend_path_policy(
                    &plugins,
                    &mut ctx,
                    &mut headers,
                    true,
                    BackendPathBeforeProxyPass::RoutingHeaderDeferred,
                )
                .await;
                ctx.headers = headers;
                result
            }
        };
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
        ctx.path = backend_ctx_path;
        if matches!(deferred_result, PluginResult::Continue) {
            // A deferred routing function can return arbitrary headers.
            // Restore gateway-owned assertions and reapply the egress baggage
            // policy before those headers can reach any backend transport.
            refresh_effective_backend_gateway_assertion_headers(&mut ctx, &mut owned_proxy_headers);
            hbone_proxy::strip_egress_baggage_in_proxy_headers(
                &mut owned_proxy_headers,
                &ctx.headers,
                &state.mesh_egress_strip_baggage_keys,
            );
        }
    }

    // Hooks that can dispatch external work or synthesize a terminal response
    // must not run until route-sensitive policy has authorized the exact first
    // backend path. The ordinary pipeline never enters this second pass.
    if backend_path_is_policy_bound {
        if matches!(deferred_result, PluginResult::Continue) {
            // Preserve the pre-existing client-path view for deferred hooks.
            // request_mirror separately consumes the private path that passed
            // final backend-effective authorization.
            let backend_ctx_path = std::mem::replace(&mut ctx.path, original_request_path.clone());
            let phase_start = Instant::now();
            deferred_result = match owned_proxy_headers.as_mut() {
                Some(headers) => {
                    run_before_proxy_hooks_for_backend_path_policy(
                        &plugins,
                        &mut ctx,
                        headers,
                        true,
                        BackendPathBeforeProxyPass::RemainingDeferred,
                    )
                    .await
                }
                None => {
                    let mut headers = std::mem::take(&mut ctx.headers);
                    let result = run_before_proxy_hooks_for_backend_path_policy(
                        &plugins,
                        &mut ctx,
                        &mut headers,
                        true,
                        BackendPathBeforeProxyPass::RemainingDeferred,
                    )
                    .await;
                    ctx.headers = headers;
                    result
                }
            };
            plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
            ctx.path = backend_ctx_path;
        }
        if matches!(deferred_result, PluginResult::Continue) {
            refresh_effective_backend_gateway_assertion_headers(&mut ctx, &mut owned_proxy_headers);
            hbone_proxy::strip_egress_baggage_in_proxy_headers(
                &mut owned_proxy_headers,
                &ctx.headers,
                &state.mesh_egress_strip_baggage_keys,
            );
        }
        match deferred_result {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                let Some(plugin_reject) = plugin_result_into_reject_parts(reject) else {
                    record_request(&state, 500);
                    return Ok(build_response(
                        StatusCode::INTERNAL_SERVER_ERROR,
                        r#"{"error":"Internal error"}"#,
                    ));
                };
                let status = StatusCode::from_u16(plugin_reject.status_code)
                    .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
                let reject = finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                    &plugins,
                    &mut ctx,
                    status,
                    &plugin_reject.body,
                    plugin_reject.headers,
                    is_grpc_request,
                    grpc_web_response_content_type.is_none(),
                )
                .await;
                apply_grpc_reject_metadata(&mut ctx, &reject);
                let grpc_web_response = build_grpc_web_reject_response(
                    &plugins,
                    &mut ctx,
                    grpc_web_response_content_type,
                    &reject,
                )
                .await;
                log_rejected_request_with_path(
                    &plugins,
                    &ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "before_proxy",
                    plugin_execution_ns,
                    Some(&original_request_path),
                )
                .await;
                record_request(&state, reject.http_status.as_u16());
                if let Some(response) = grpc_web_response {
                    return Ok(response);
                }
                return Ok(build_response_from_normalized_reject(reject));
            }
        }
    }

    // The effective PeerAuthentication app port is not authoritative until
    // routing plugins have applied their overrides and load balancing has
    // selected a concrete upstream target. Re-check every inbound request
    // against the current atomic policy snapshot so a keep-alive connection
    // accepted before live reload cannot retain a weaker transport posture.
    if let Some(mismatch) = mesh_inbound_peer_auth_transport_mismatch(
        &state,
        ctx.mesh_direction,
        mesh_inbound_pre_handshake_app_port,
        &proxy,
        upstream_target.as_deref(),
        is_tls,
        ctx.tls_client_cert_der.is_some(),
    ) {
        return Ok(reject_mesh_inbound_peer_auth_transport_mismatch(
            &state,
            &plugins,
            &mut ctx,
            &proxy,
            mismatch,
            is_tls,
            is_grpc_request,
            start_time,
            plugin_execution_ns,
            "mesh_inbound_peer_auth_transport_mismatch",
            Some(&original_request_path),
        )
        .await);
    }

    // A terminal final-body plugin (currently `ai_federation`) owns its own
    // external dispatch and returns the complete response. Finalize and invoke
    // it after inbound transport policy, but before the placeholder route's
    // backend circuit breaker and every backend-only preflight. Besides
    // preventing an unrelated backend policy from suppressing provider calls,
    // returning here keeps synthetic provider outcomes out of backend health,
    // breaker, and latency accounting.
    if final_body_before_backend_dispatch {
        let hook_headers = owned_proxy_headers.as_ref().unwrap_or(&ctx.headers).clone();
        client_request_body = match client_request_body {
            ClientRequestBody::Streaming(request) => {
                match buffer_request_body_for_before_proxy(
                    *request,
                    &method,
                    &hook_headers,
                    state.max_request_body_size_bytes,
                    proxy.backend_read_timeout_ms,
                    ctx.grpc_deadline_at(),
                )
                .await
                {
                    Ok(body) => body,
                    Err(RequestBodyBufferError::TooLarge) => {
                        return Ok(finalize_terminal_request_body_read_rejection(
                            &state,
                            &plugins,
                            &mut ctx,
                            StatusCode::PAYLOAD_TOO_LARGE,
                            br#"{"error":"Request body exceeds maximum size"}"#,
                            is_grpc_request,
                            start_time,
                            plugin_execution_ns,
                            &original_request_path,
                        )
                        .await);
                    }
                    Err(RequestBodyBufferError::ClientDisconnected(error_message)) => {
                        error!(
                            proxy_id = %proxy.id,
                            path = %ctx.path,
                            error_kind = "client_disconnect",
                            error = %error_message,
                            "Client disconnected while finalizing terminal request body before backend dispatch"
                        );
                        return Ok(finalize_terminal_request_body_read_rejection(
                            &state,
                            &plugins,
                            &mut ctx,
                            StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
                            br#"{"error":"Client disconnected"}"#,
                            is_grpc_request,
                            start_time,
                            plugin_execution_ns,
                            &original_request_path,
                        )
                        .await);
                    }
                    Err(RequestBodyBufferError::TimedOut) => {
                        return Ok(finalize_terminal_request_body_read_rejection(
                            &state,
                            &plugins,
                            &mut ctx,
                            StatusCode::REQUEST_TIMEOUT,
                            br#"{"error":"Request body read timed out"}"#,
                            is_grpc_request,
                            start_time,
                            plugin_execution_ns,
                            &original_request_path,
                        )
                        .await);
                    }
                    Err(RequestBodyBufferError::DeadlineExceeded) => {
                        ctx.metadata.insert(
                            RELEASE_INFLIGHT_ON_COMMIT_METADATA_KEY.to_string(),
                            "true".to_string(),
                        );
                        return Ok(finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_terminal_request_body",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await);
                    }
                }
            }
            buffered => buffered,
        };

        client_request_body = match client_request_body {
            ClientRequestBody::Buffered(mut buffered) => {
                ctx.bytes_sent_observed.fetch_max(
                    buffered.body.len() as u64,
                    std::sync::atomic::Ordering::Release,
                );
                let mut body_hook_ctx = needs_final_request_body_context
                    .then(|| ctx.clone_for_final_request_body_hooks());
                let terminal_hook_start = Instant::now();
                let grpc_deadline_at = ctx.grpc_deadline_at();
                let transformed = apply_request_body_plugins_with_context(
                    &plugins,
                    body_hook_ctx.as_mut(),
                    grpc_deadline_at,
                    &hook_headers,
                    buffered.body,
                )
                .await;
                let final_body_result = run_final_request_body_hooks(
                    &plugins,
                    body_hook_ctx.as_mut(),
                    grpc_deadline_at,
                    &hook_headers,
                    &transformed,
                )
                .await;
                plugin_execution_ns += terminal_hook_start.elapsed().as_nanos() as u64;
                if let Some(body_hook_ctx) = body_hook_ctx {
                    let request_body = ctx.metadata.remove("request_body");
                    ctx.metadata = body_hook_ctx.metadata;
                    if let Some(body) = request_body {
                        ctx.metadata.insert("request_body".to_string(), body);
                    }
                    ctx.waf_metadata_initialized = body_hook_ctx.waf_metadata_initialized;
                    ctx.waf_owned_metadata = body_hook_ctx.waf_owned_metadata;
                    ctx.waf_instance_scores = body_hook_ctx.waf_instance_scores;
                }
                match final_body_result {
                    PluginResult::Continue => {
                        request_body_prepared = true;
                        buffered.body = transformed;
                        ClientRequestBody::Buffered(buffered)
                    }
                    reject @ PluginResult::Reject { .. }
                    | reject @ PluginResult::RejectBinary { .. } => {
                        let Some(reject) = plugin_result_into_reject_parts(reject) else {
                            record_request(&state, 500);
                            return Ok(build_response(
                                StatusCode::INTERNAL_SERVER_ERROR,
                                r#"{"error":"Internal error"}"#,
                            ));
                        };
                        let status = StatusCode::from_u16(reject.status_code)
                            .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
                        let normalized =
                            finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                                &plugins,
                                &mut ctx,
                                status,
                                &reject.body,
                                reject.headers,
                                is_grpc_request,
                                grpc_web_response_content_type.is_none(),
                            )
                            .await;
                        apply_grpc_reject_metadata(&mut ctx, &normalized);
                        let grpc_web_response = build_grpc_web_reject_response(
                            &plugins,
                            &mut ctx,
                            grpc_web_response_content_type,
                            &normalized,
                        )
                        .await;
                        log_rejected_request_with_path(
                            &plugins,
                            &ctx,
                            normalized.http_status.as_u16(),
                            start_time,
                            "on_final_request_body",
                            plugin_execution_ns,
                            Some(&original_request_path),
                        )
                        .await;
                        record_request(&state, normalized.http_status.as_u16());
                        if let Some(response) = grpc_web_response {
                            return Ok(response);
                        }
                        return Ok(build_response_from_normalized_reject(normalized));
                    }
                }
            }
            bodyless => bodyless,
        };
    }

    let upstream_balancer = selection.balancer;
    let upstream_is_fallback = selection.is_fallback;
    let sticky_cookie_needed = selection.sticky_cookie_needed;

    // Apply the DestinationRule `connectionPool.http.maxRetries` per-request
    // retry-count CAP now that the dispatch target's port is known, before any
    // retry loop (HTTP / gRPC / WebSocket) reads `proxy.retry`. The cap comes
    // from the SELECTED target's port override; retries stay in that port's lane
    // (see `cap_proxy_retry_for_target`), so the selected-port cap governs the
    // whole sequence. This caps an existing retry policy to `min(existing,
    // dr_max)`; it never enables retries when the proxy has none. No-op (no Arc
    // clone) in the common case.
    let proxy = cap_proxy_retry_for_target(proxy, upstream_target.as_deref());
    ctx.matched_proxy = Some(Arc::clone(&proxy));
    ctx.proxy_lifecycle_generation = epoch
        .plugin_cache
        .proxy_lifecycle_generation(proxy.id.as_str());

    let backend_admission_plugins = plugin_cache_view.backend_admission_plugins();
    let mut backend_admission_permits: Option<BackendAdmissionPermitSet> = None;
    let mut preacquired_backend_admission = PreacquiredBackendAdmission::default();

    // Circuit breaker check — per-target when upstream is configured, per-proxy otherwise
    // `cb_admission_open_epoch` is re-captured on retry-target rotation (the gRPC
    // and direct-H2 retry loops below) so a deferred streaming outcome is
    // stale-checked against the FINAL admitted target's generation, not the initial
    // target's (#1649 R6 findings 1 & 2).
    let (cb_target_key, cb_is_half_open_probe, mut cb_admission_open_epoch) =
        match backend_dispatch::check_circuit_breaker(&proxy, &state, upstream_target.as_deref()) {
            Ok(result) => result,
            Err(()) => {
                let reject = finalize_reject_response_with_after_proxy_hooks(
                    &plugins,
                    &mut ctx,
                    StatusCode::SERVICE_UNAVAILABLE,
                    br#"{"error":"Service temporarily unavailable (circuit breaker open)"}"#,
                    HashMap::new(),
                    is_grpc_request,
                )
                .await;
                apply_grpc_reject_metadata(&mut ctx, &reject);
                // Use `original_request_path` so the log records the path the
                // client actually requested, not the VirtualService-rewritten
                // backend path stored in `ctx.path` after the rewrite above.
                log_rejected_request_with_path(
                    &plugins,
                    &ctx,
                    reject.http_status.as_u16(),
                    start_time,
                    "circuit_breaker_open",
                    plugin_execution_ns,
                    Some(&original_request_path),
                )
                .await;
                record_request(&state, reject.http_status.as_u16());
                return Ok(build_response_from_normalized_reject(reject));
            }
        };

    // For ordinary response-policy reevaluation, finalize the body only after
    // fail-fast routing and breaker gates have admitted the request. This
    // preserves the open-breaker behavior (no slow upload drain or body-plugin
    // I/O before the immediate 503). Terminal dispatch plugins were finalized
    // above and skip this second pass via `request_body_prepared`.
    let preparation_backend_host = upstream_target
        .as_deref()
        .map(|target| target.host.as_str())
        .unwrap_or(proxy.backend_host.as_str());
    let preparation_requires_direct_h2_for_sni = !request_body_prepared
        && reevaluate_response_policy_after_request_body
        && resolve_backend_connection_proxy_for_target(&proxy, upstream_target.as_deref())
            .resolved_tls
            .sni
            .is_some();
    let preparation_blocked_by_dispatch_policy = preparation_requires_direct_h2_for_sni
        || denied_literal_backend_or_dns_override(
            preparation_backend_host,
            &proxy,
            &state.env_config.backend_allow_ips,
        )
        .is_some()
        || backend_dispatch::direct_http_mesh_transport_refusal(upstream_target.as_deref())
            .is_some();
    if reevaluate_response_policy_after_request_body
        && !request_body_prepared
        && !preparation_blocked_by_dispatch_policy
    {
        if !backend_admission_plugins.is_empty() {
            let admission_proxy =
                resolve_effective_proxy_for_target(&proxy, upstream_target.as_deref());
            let permits = match backend_dispatch::run_backend_admission_plugins(
                backend_admission_plugins.as_ref(),
                &ctx,
                admission_proxy.as_ref(),
                upstream_target.as_deref(),
                ProxyProtocol::Http,
            ) {
                Ok(permits) => permits,
                Err(rejection) => {
                    release_circuit_breaker_probe_on_admission_reject(
                        &state,
                        &proxy,
                        cb_target_key.as_deref(),
                        cb_is_half_open_probe,
                    );
                    return Ok(handle_backend_admission_rejection(
                        rejection,
                        &plugins,
                        &mut ctx,
                        &state,
                        start_time,
                        plugin_execution_ns,
                        Some(&original_request_path),
                        is_grpc_request,
                        grpc_web_response_content_type,
                    )
                    .await);
                }
            };
            preacquired_backend_admission = PreacquiredBackendAdmission::acquired(permits);
        }
        let hook_headers = owned_proxy_headers.as_ref().unwrap_or(&ctx.headers).clone();
        client_request_body = match client_request_body {
            ClientRequestBody::Streaming(request) => {
                match buffer_request_body_for_before_proxy(
                    *request,
                    &method,
                    &hook_headers,
                    state.max_request_body_size_bytes,
                    proxy.backend_read_timeout_ms,
                    ctx.grpc_deadline_at(),
                )
                .await
                {
                    Ok(body) => body,
                    Err(RequestBodyBufferError::TooLarge) => {
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            cb_is_half_open_probe,
                        );
                        record_request(&state, 413);
                        return Ok(build_response(
                            StatusCode::PAYLOAD_TOO_LARGE,
                            r#"{"error":"Request body exceeds maximum size"}"#,
                        ));
                    }
                    Err(RequestBodyBufferError::ClientDisconnected(error_message)) => {
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            cb_is_half_open_probe,
                        );
                        error!(
                            proxy_id = %proxy.id,
                            path = %ctx.path,
                            error_kind = "client_disconnect",
                            error = %error_message,
                            "Client disconnected while finalizing request body before dispatch"
                        );
                        record_request(&state, 499);
                        return Ok(build_response(
                            StatusCode::from_u16(499).unwrap_or(StatusCode::BAD_REQUEST),
                            r#"{"error":"Client disconnected"}"#,
                        ));
                    }
                    Err(RequestBodyBufferError::TimedOut) => {
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            cb_is_half_open_probe,
                        );
                        drop(preacquired_backend_admission.take_if_acquired());
                        let response = build_request_body_timeout_response(
                            is_grpc_request,
                            grpc_web_response_content_type,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        );
                        record_request(&state, response.status().as_u16());
                        return Ok(response);
                    }
                    Err(RequestBodyBufferError::DeadlineExceeded) => {
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            cb_is_half_open_probe,
                        );
                        drop(preacquired_backend_admission.take_if_acquired());
                        let response = finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_upload_before_dispatch",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await;
                        return Ok(response);
                    }
                }
            }
            buffered => buffered,
        };

        client_request_body = match client_request_body {
            ClientRequestBody::Buffered(mut buffered) => {
                ctx.bytes_sent_observed.fetch_max(
                    buffered.body.len() as u64,
                    std::sync::atomic::Ordering::Release,
                );
                let grpc_deadline_at = ctx.grpc_deadline_at();
                let mut body_hook_ctx = needs_final_request_body_context
                    .then(|| ctx.clone_for_final_request_body_hooks());
                let transformed = apply_request_body_plugins_with_context(
                    &plugins,
                    body_hook_ctx.as_mut(),
                    grpc_deadline_at,
                    &hook_headers,
                    buffered.body,
                )
                .await;
                let final_body_result = run_final_request_body_hooks(
                    &plugins,
                    body_hook_ctx.as_mut(),
                    grpc_deadline_at,
                    &hook_headers,
                    &transformed,
                )
                .await;
                if let Some(body_hook_ctx) = body_hook_ctx {
                    if body_hook_ctx.gateway_deadline_response_selected() {
                        ctx.mark_gateway_deadline_response_selected();
                    }
                    let request_body = ctx.metadata.remove("request_body");
                    ctx.metadata = body_hook_ctx.metadata;
                    ctx.ai_usage_export = body_hook_ctx.ai_usage_export;
                    if let Some(body) = request_body {
                        ctx.metadata.insert("request_body".to_string(), body);
                    }
                    ctx.waf_metadata_initialized = body_hook_ctx.waf_metadata_initialized;
                    ctx.waf_owned_metadata = body_hook_ctx.waf_owned_metadata;
                    ctx.waf_instance_scores = body_hook_ctx.waf_instance_scores;
                }
                match final_body_result {
                    PluginResult::Continue => {
                        request_body_prepared = true;
                        buffered.body = transformed;
                        ClientRequestBody::Buffered(buffered)
                    }
                    reject @ PluginResult::Reject { .. }
                    | reject @ PluginResult::RejectBinary { .. } => {
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            cb_is_half_open_probe,
                        );
                        let Some(reject) = plugin_result_into_reject_parts(reject) else {
                            record_request(&state, 500);
                            return Ok(build_response(
                                StatusCode::INTERNAL_SERVER_ERROR,
                                r#"{"error":"Internal error"}"#,
                            ));
                        };
                        let status = StatusCode::from_u16(reject.status_code)
                            .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
                        let normalized =
                            finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                                &plugins,
                                &mut ctx,
                                status,
                                &reject.body,
                                reject.headers,
                                is_grpc_request,
                                grpc_web_response_content_type.is_none(),
                            )
                            .await;
                        apply_grpc_reject_metadata(&mut ctx, &normalized);
                        let grpc_web_response = build_grpc_web_reject_response(
                            &plugins,
                            &mut ctx,
                            grpc_web_response_content_type,
                            &normalized,
                        )
                        .await;
                        log_rejected_request_with_path(
                            &plugins,
                            &ctx,
                            normalized.http_status.as_u16(),
                            start_time,
                            "on_final_request_body",
                            plugin_execution_ns,
                            Some(&original_request_path),
                        )
                        .await;
                        record_request(&state, normalized.http_status.as_u16());
                        if let Some(response) = grpc_web_response {
                            return Ok(response);
                        }
                        return Ok(build_response_from_normalized_reject(normalized));
                    }
                }
            }
            bodyless => bodyless,
        };
    }
    // Build one lightweight mutable hook context for the selected dispatch
    // branch so request transforms and final hooks observe the same state.
    // Early-prepared bodies already ran both hook phases above.
    let mut deferred_body_hook_ctx = (!request_body_prepared && needs_final_request_body_context)
        .then(|| ctx.clone_for_final_request_body_hooks());
    // Check if this is a WebSocket upgrade request. WebSocket is a runtime
    // flavor in the new scheme-decoupled model — any HTTP-family proxy
    // (plaintext `http` or TLS `https`) can serve WebSocket upgrades; the
    // backend wire protocol is `ws://` or `wss://` depending on scheme.
    // Stream proxies never reach here (the handler only runs for HTTP).
    if request_protocol == ProxyProtocol::WebSocket && proxy.dispatch_kind.is_http_family() {
        let initial_response_header_policy_plugins =
            plugin_cache_view.initial_response_header_policy_plugins();
        // Cross-Site WebSocket Hijacking (CSWSH) protection per RFC 6455 §10.2.
        // When allowed_ws_origins is non-empty, reject upgrades from unlisted origins.
        if !proxy.allowed_ws_origins.is_empty() {
            let origin = ctx.headers.get("origin").map(|s| s.as_str()).unwrap_or("");
            if !websocket_origin_allowed(&proxy.allowed_ws_origins, origin) {
                warn!(
                    "WebSocket upgrade rejected: Origin '{}' not in allowed_ws_origins for proxy {}",
                    origin, proxy.id
                );
                // The circuit-breaker check above may have admitted this request
                // as a HALF_OPEN probe. This origin reject happens before any
                // backend dispatch, so release the claimed probe slot — otherwise
                // repeated rejected origin probes leak `half_open_in_flight` slots
                // and wedge the breaker. Mirrors the H3 origin reject in
                // `src/http3/server.rs` and the other H1/H2 WebSocket gateway-side
                // rejects (missing OnUpgrade, connection limits, backend admission).
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    cb_target_key.as_deref(),
                    cb_is_half_open_probe,
                );
                record_request(&state, 403);
                return Ok(build_websocket_error_response(
                    StatusCode::FORBIDDEN,
                    r#"{"error":"WebSocket Origin not allowed"}"#,
                    &initial_response_header_policy_plugins,
                ));
            }
        }
        let request = match client_request_body {
            ClientRequestBody::Streaming(request) => *request,
            ClientRequestBody::Buffered(_) => {
                debug_assert!(
                    false,
                    "websocket requests should never be pre-buffered for before_proxy"
                );
                record_request(&state, 500);
                return Ok(build_websocket_error_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    r#"{"error":"WebSocket request buffering invariant violated"}"#,
                    &initial_response_header_policy_plugins,
                ));
            }
        };
        let requires_websocket_framing = plugin_cache_view.requires_ws_frame_hooks();
        let mut websocket_proxy_headers =
            owned_proxy_headers.as_ref().unwrap_or(&ctx.headers).clone();
        apply_effective_backend_scheme_headers(
            &mut websocket_proxy_headers,
            &ctx.client_ip,
            ctx.request_is_secure,
            state.add_forwarded_header,
        );
        return handle_websocket_request_authenticated(
            request,
            state,
            remote_addr,
            proxy,
            ctx,
            websocket_proxy_headers,
            plugins,
            initial_response_header_policy_plugins,
            backend_admission_plugins,
            plugin_execution_ns,
            Arc::clone(&epoch),
            upstream_target,
            upstream_balancer,
            lb_hash_key,
            sticky_cookie_needed,
            start_time,
            is_h2_ws,
            is_tls,
            mesh_inbound_pre_handshake_app_port,
            cb_target_key,
            cb_is_half_open_probe,
            requires_websocket_framing,
            effective_query_string.to_string(),
            strip_len,
            backend_path_is_policy_bound,
            original_request_path.clone(),
        )
        .await;
    }

    // Check if this is a gRPC request. Like WebSocket, gRPC is a runtime
    // flavor — any HTTP-family proxy can serve gRPC when the client sends
    // the right content-type. The gRPC pool uses h2c (plaintext HTTP/2) for
    // `BackendScheme::Http` and TLS+ALPN=h2 for `BackendScheme::Https`.
    //
    // MESH TRANSPORTS (issue #2003): the gRPC branch runs BEFORE the HBONE /
    // mesh-mTLS dispatch gates below, and its pool dials the LB-selected
    // `target.host:target.port` directly — which would silently bypass the
    // secured mesh transport for a mesh-tagged target (unauthenticated under
    // PERMISSIVE PeerAuthentication, confusing capture-listener failures under
    // STRICT). Classify the selected target first:
    //   * Same-cluster Sidecar `mesh.mtls` targets SKIP this branch and flow
    //     down the generic HTTP dispatch path, whose mesh-mTLS gate + pool
    //     (`proxy_to_backend_mesh_mtls`) carry gRPC natively: the pool is
    //     hyper h2 end-to-end with pinned peer SVID, the request body streams
    //     (`SizeLimitedIncoming`), and the `StreamingH2` response arm relays
    //     backend trailers through `StripHopByHopTrailers` — the same trailer
    //     semantics as `GrpcConnectionPool`. When that path cannot dispatch
    //     (retry configured, body buffering required, no gateway SVID) the
    //     mesh-mTLS gate below fails closed with a gRPC UNAVAILABLE.
    //   * NATIVE-gRPC requests (and gRPC-Web the `grpc_web` plugin
    //     TRANSLATED — wire-native gRPC by dispatch time) to Ambient
    //     `mesh.hbone` and cross-cluster targets FAIL CLOSED inside this
    //     branch (see `grpc_mesh_dispatch_falls_through`), never direct-dial.
    //   * PASS-THROUGH gRPC-Web (protocol-classified gRPC for plugin routing,
    //     but NOT the native `application/grpc` content-type, and NOT
    //     translated by the `grpc_web` plugin) frames its trailers inside
    //     the response BODY, so it needs no HTTP/2 trailer relay: it falls
    //     through for EVERY mesh-tagged target and rides the topology's
    //     HTTP-family transport like plain HTTP (including HBONE and the
    //     cross-cluster east-west paths). Non-mesh gRPC-Web keeps its
    //     existing direct gRPC-pool dispatch unchanged.
    //   * TRANSLATED gRPC-Web (codex r2-2 finding 1): the `grpc_web` plugin
    //     rewrote the outbound request to wire-native gRPC in `before_proxy`,
    //     so the ORIGINAL content-type check alone would let it ride the
    //     HBONE HTTP/1.1 inner tunnel (or the cross-cluster paths) as native
    //     gRPC — the exact no-trailer corruption the refusal prevents. It is
    //     detected via the plugin's spoof-proof context marker and FAILS
    //     CLOSED inside this branch like native gRPC (the Trailers-Only
    //     refusal is encoded in the gRPC-Web wire format here because this
    //     early fail-closed branch returns before the normal `grpc_web`
    //     `after_proxy`/body hooks can translate a native gRPC error response).
    //     `MeshMtls` still falls through for native gRPC and binary translated
    //     gRPC-Web, but text-mode translated gRPC-Web remains fail-closed here
    //     because it requires request-body buffering and the generic mesh-mTLS
    //     path does not accept pre-buffered request bodies.
    let grpc_request_is_web_translated =
        crate::plugins::grpc_web::request_is_grpc_web_translated(&ctx);
    let grpc_mesh_fall_through = is_grpc_request
        && proxy.dispatch_kind.is_http_family()
        && upstream_target.as_deref().is_some_and(|target| {
            grpc_proxy::grpc_mesh_dispatch_falls_through(
                grpc_proxy::classify_grpc_mesh_dispatch(target),
                request_uses_grpc_content_type,
                grpc_request_is_web_translated,
                !requires_request_body_buffering,
            )
        });
    if is_grpc_request && proxy.dispatch_kind.is_http_family() && !grpc_mesh_fall_through {
        {
            let grpc_proxy_headers = owned_proxy_headers.as_mut().unwrap_or(&mut ctx.headers);
            apply_effective_backend_scheme_headers(
                grpc_proxy_headers,
                &ctx.client_ip,
                ctx.request_is_secure,
                state.add_forwarded_header,
            );
        }
        let owned_proxy_headers_ref = owned_proxy_headers.as_ref();

        // FAIL CLOSED on a gRPC request routed to a mesh-tagged target this
        // branch cannot dispatch over its secured transport (issue #2003):
        //   * CROSS-CLUSTER east-west targets (Ambient `mesh.hbone` or Sidecar
        //     `mesh.mtls`): the dial host is a remote-pod / scoped synthetic
        //     identity that is NOT directly routable, and the dial has no
        //     east-west gateway dial-host override, no destination-FQDN SNI
        //     override, and no trust-domain-scoped verification. gRPC over
        //     cross-cluster HBONE / mesh-mTLS is a documented follow-up
        //     (HTTP-first), mirroring the WebSocket cross-cluster guards.
        //   * Same-cluster Ambient `mesh.hbone` targets: the HBONE inner
        //     protocol is HTTP/1.1 over a byte tunnel, which cannot carry the
        //     HTTP/2 trailers gRPC requires — an explicit non-goal (see the
        //     out-of-scope list in docs/mesh_supported_matrix.md), fail
        //     closed rather than silently corrupt.
        //   * `MeshMtls` is normally unreachable here (the fall-through above
        //     routes it down the generic mesh path) — refuse defensively.
        // Refuse cleanly with a gRPC UNAVAILABLE (14, the gRPC analog of a 502
        // connection-level failure) before any backend dial / circuit-breaker
        // charge — NEVER a direct plaintext dial that would bypass the mesh
        // transport, identity pinning, and mesh authz identity.
        if let Some(target) = upstream_target.as_deref() {
            let refusal = match grpc_proxy::classify_grpc_mesh_dispatch(target) {
                grpc_proxy::GrpcMeshDispatch::Direct => None,
                grpc_proxy::GrpcMeshDispatch::RefuseCrossCluster => Some(
                    "gRPC over cross-cluster Ambient HBONE east-west routing is not supported \
                     (HBONE inner protocol cannot carry gRPC trailers)",
                ),
                grpc_proxy::GrpcMeshDispatch::RefuseCrossClusterMalformed => Some(
                    "gRPC over cross-cluster east-west routing requires a destination SNI \
                     override and a remote trust domain",
                ),
                grpc_proxy::GrpcMeshDispatch::RefuseCrossClusterNoTransport => {
                    Some("gRPC over cross-cluster east-west routing requires a mesh transport tag")
                }
                grpc_proxy::GrpcMeshDispatch::RefuseHbone => Some(
                    "gRPC over the Ambient HBONE mesh transport is not supported \
                     (HBONE inner protocol cannot carry gRPC trailers)",
                ),
                // `MeshMtlsCrossCluster` normally falls through to the generic
                // mesh-mTLS path (its east-west branch) like `MeshMtls`; both are
                // refused defensively here in case they reach this branch.
                grpc_proxy::GrpcMeshDispatch::MeshMtls
                | grpc_proxy::GrpcMeshDispatch::MeshMtlsCrossCluster => {
                    Some("gRPC to a sidecar mesh mTLS target cannot be dialed directly")
                }
            };
            if let Some(message) = refusal {
                warn!(
                    proxy_id = %proxy.id,
                    target_host = %target.host,
                    message,
                    "Refusing direct gRPC dispatch to a mesh-transport-tagged target: \
                     failing closed with gRPC UNAVAILABLE instead of bypassing the \
                     secured mesh transport"
                );
                // Release a HALF_OPEN circuit-breaker probe slot that
                // `check_circuit_breaker` may have admitted for this request — this
                // reject precedes any backend dispatch, so a leaked probe slot would
                // wedge the breaker (mirrors the WebSocket gateway-side rejects).
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    cb_target_key.as_deref(),
                    cb_is_half_open_probe,
                );
                record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
                if let Some(content_type) = grpc_web_response_content_type {
                    return Ok(build_grpc_web_error_response(
                        content_type,
                        14,
                        message,
                        plugin_cache_view
                            .initial_response_header_policy_plugins()
                            .as_ref(),
                    ));
                }
                return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                    14, // UNAVAILABLE
                    message,
                    initial_response_header_policy_plugins.as_ref(),
                ));
            }
        }

        // Honor DestinationRule per-port `connect_timeout_ms` overrides on
        // the gRPC path — the gRPC transport reads
        // `proxy.backend_{host,port,connect_timeout_ms}` directly
        // (grpc_proxy.rs), so we must pass the resolved Cow<Proxy> through
        // dispatch. Borrowed when no override applies; cloned only when the
        // selected target or per-port timeout differs.

        // Account for a HALF_OPEN circuit-breaker probe slot that
        // check_circuit_breaker may have admitted for this request. The gRPC
        // block returns from many early paths; this guard records a NEUTRAL
        // outcome on drop (releasing the probe slot) unless an explicit
        // success/failure is recorded after dispatch. `grpc_cb_probe_slot`
        // tracks whether that probe is still unconsumed so the retry loop and
        // the final record below cannot double-decrement it.
        let mut grpc_cb_probe_slot = cb_is_half_open_probe;
        // The post-dispatch breaker record must be charged to the target that
        // actually produced grpc_result. The retry loop can rotate targets, so
        // track the final target here (init to the initial target) and update it
        // on each rotation, mirroring the HTTP path's final_cb_target_key. The
        // probe-slot release still lands correctly: grpc_cb_probe_slot is only
        // still true when no rotation occurred, in which case this equals
        // cb_target_key.
        let mut grpc_final_cb_key = cb_target_key.clone();
        // Set when a load-balanced retry rotates to a target whose breaker
        // rejects the attempt (see the can_execute gate in the retry loop): the
        // current outcome was already recorded for the prior target, so the
        // post-dispatch record below must be skipped. Mirrors the HTTP path's
        // `skip_final_cb_record`.
        let mut grpc_skip_final_cb_record = false;
        let mut grpc_probe_guard = GrpcProbeReleaseGuard {
            cb: if cb_is_half_open_probe {
                proxy.circuit_breaker.as_ref().map(|cfg| {
                    state.circuit_breaker_cache.get_or_create(
                        &proxy.id,
                        cb_target_key.as_deref(),
                        cfg,
                    )
                })
            } else {
                None
            },
            armed: true,
        };

        let grpc_connection_proxy =
            resolve_backend_connection_proxy_for_target(&proxy, upstream_target.as_deref());
        let grpc_dispatch_proxy: &Proxy = grpc_connection_proxy.as_ref();
        let grpc_effective_host = grpc_dispatch_proxy.backend_host.as_str();
        // Enforce the backend egress policy for a literal-IP gRPC backend before
        // dialing. The gRPC pool self-resolves via `DnsCache::resolve` (canonical
        // `IpAddr` fast path; non-canonical spellings go to real DNS and are
        // screened on the resolved address), never reqwest's URL parser, so use
        // the canonical screen — the URL-canonicalizing one would wrongly reject a
        // legitimate all-numeric gRPC backend hostname (e.g. `2852039166`).
        if let Some(reason) = denied_literal_backend_or_dns_override_canonical(
            grpc_effective_host,
            grpc_dispatch_proxy,
            &state.env_config.backend_allow_ips,
        ) {
            warn!(
                proxy_id = %proxy.id,
                backend = %grpc_effective_host,
                reason,
                "Backend egress policy denied literal-IP gRPC backend; not dialing"
            );
            // Release a HALF_OPEN probe slot `check_circuit_breaker` may have
            // admitted (else it wedges the breaker) and count the request so
            // policy-denied gRPC calls still appear in request/status metrics.
            // Unlike the cross-cluster reject above (which runs BEFORE
            // `grpc_probe_guard` exists), this reject is AFTER the guard, so
            // disarm it first — otherwise its still-armed `Drop` fires a SECOND
            // neutral release that would decrement another in-flight probe slot.
            grpc_probe_guard.disarm();
            release_circuit_breaker_probe_on_admission_reject(
                &state,
                &proxy,
                cb_target_key.as_deref(),
                cb_is_half_open_probe,
            );
            record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
            return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                14,
                "backend address blocked by egress policy",
                initial_response_header_policy_plugins.as_ref(),
            ));
        }
        let grpc_effective_port = grpc_dispatch_proxy.backend_port;
        let mut grpc_backend_url = build_backend_url_with_target(
            grpc_dispatch_proxy,
            &path,
            effective_query_string.as_ref(),
            grpc_effective_host,
            grpc_effective_port,
            strip_len,
            upstream_target.as_ref().and_then(|t| t.path.as_deref()),
        );
        let backend_start = Instant::now();
        // Adaptive-concurrency admission latency must be measured from the
        // backend dispatch point, not from here: `backend_start` precedes
        // request-body collection and final-body hooks, so reusing it would
        // bill slow client uploads / body-plugin time as backend latency and
        // wrongly shrink a healthy upstream's limit. Reset this to the dispatch
        // instant before each attempt, mirroring the HTTP path's
        // `backend_admission_started_at`. `backend_start` itself stays the
        // origin for full backend-latency metrics (`backend_total_ms`).
        let mut grpc_backend_admission_started_at = backend_start;
        let mut grpc_final_upstream_target = upstream_target.clone();
        let mut grpc_lb_connection_guard: Option<LoadBalancerConnectionGuard> = None;

        // Streaming-response safety:
        //   * Retries are triggered by CONNECTION errors (BackendUnavailable,
        //     BackendTimeout::Connect) that fire BEFORE response headers
        //     arrive. Once headers arrive we have already committed to a
        //     single attempt — response-body streaming does not prevent
        //     retry, so retry alone is NOT a reason to buffer.
        //   * The REQUEST body still has to be collected up-front when
        //     retry is configured (caller side), so the retry loop can
        //     replay the collected request bytes regardless of the
        //     `stream_response` flag.
        //   * Streaming IS unsafe when a plugin (or explicit
        //     `response_body_mode = Buffer`) requires the full response
        //     body in memory to make an admission decision.
        //
        // Fixing the old `!grpc_has_retry &&` gate eliminates the
        // trailer-stall on server-streaming RPCs where retry was
        // configured: previously the gateway collected every data frame
        // into a Vec before surfacing `grpc-status`, which turned a
        // stream-of-small-frames RPC into a "wait for the whole body"
        // pattern (500 KB p99 = 732 ms under 100 concurrency).
        let grpc_has_retry = crate::retry::can_retry_connection_failures(proxy.retry.as_ref());
        let grpc_should_stream = should_stream_response_body(
            &proxy,
            &plugins,
            &ctx,
            plugin_cache_view.requires_response_body_buffering(),
        );

        // When plugins need request body access (e.g., protobuf validation),
        // collect the body first, run hooks, then dispatch to backend.
        // Otherwise, use the fast combined collect+dispatch path.
        // An earlier terminal preparation already ran transforms and final
        // hooks. Reusing that buffer must not invoke either phase a second
        // time merely because the selected transport is native gRPC.
        let grpc_needs_request_body_hooks =
            requires_request_body_buffering && !request_body_prepared;
        // `proxy_grpc_request_streaming` streams BOTH the request AND the
        // response, which means the request body is consumed on the wire
        // and cannot be replayed — incompatible with retry. Gate it on
        // `!grpc_has_retry` so retry-enabled streaming proxies still use the
        // buffered-request path (collects request body up-front, streams
        // response frame-by-frame).
        let grpc_can_use_streaming_fast_path = grpc_should_stream && !grpc_has_retry;
        // Deferred circuit-breaker probe recorder for the fully-streaming fast
        // path. Set only when that path is taken AND the request was admitted as
        // a HALF_OPEN probe; it defers classification + probe-slot release to
        // request-upload termination so a late client-upload overflow records
        // NEUTRAL instead of falsely healing the probe. `None` (no breaker,
        // CLOSED state, or the buffered-request streaming path) records the
        // outcome at response-header time as before.
        let mut grpc_streaming_probe_recorder: Option<Arc<GrpcStreamingProbeRecorder>> = None;
        // Unread frontend upload retained across a synthesized Trailers-Only
        // error on the fully-streaming H2 path. The pinned h2 transport already
        // orders response HEADERS before its permitted NO_ERROR cancellation;
        // coupling ownership to the response lifecycle is defense-in-depth,
        // while the raw client still handles the legal residual reset (#2057).
        let mut held_frontend_grpc_upload: Option<grpc_proxy::GrpcBody> = None;
        let (mut grpc_result, grpc_body_bytes) = if grpc_needs_request_body_hooks {
            // Split path: collect body → run plugin hooks → dispatch
            let (grpc_method, grpc_headers, grpc_req_body) = match client_request_body {
                ClientRequestBody::Streaming(request) => {
                    match grpc_proxy::collect_grpc_request_body(
                        *request,
                        state.max_grpc_recv_size_bytes,
                        proxy.backend_read_timeout_ms,
                        ctx.grpc_deadline_at(),
                    )
                    .await
                    {
                        Ok(parts) => parts,
                        Err(grpc_proxy::GrpcRequestBodyCollectError::TimedOut) => {
                            // `grpc_probe_guard` remains armed: returning drops it and
                            // releases the admitted HALF_OPEN slot exactly once,
                            // neutrally, before the response is written by hyper.
                            record_request(&state, StatusCode::OK.as_u16());
                            return Ok(build_request_body_timeout_response(
                                true,
                                grpc_web_response_content_type,
                                plugin_cache_view
                                    .initial_response_header_policy_plugins()
                                    .as_ref(),
                            ));
                        }
                        Err(grpc_proxy::GrpcRequestBodyCollectError::DeadlineExceeded) => {
                            // Rejection decorators/logging may await external sinks.
                            // Release the admitted HALF_OPEN probe and any body-phase
                            // preacquisition before entering that cleanup pipeline.
                            grpc_probe_guard.disarm();
                            release_circuit_breaker_probe_on_admission_reject(
                                &state,
                                &proxy,
                                cb_target_key.as_deref(),
                                grpc_cb_probe_slot,
                            );
                            drop(preacquired_backend_admission.take_if_acquired());
                            return Ok(finalize_upload_deadline_rejection(
                                &plugins,
                                &mut ctx,
                                &state,
                                start_time,
                                "grpc_deadline_buffered_grpc_upload",
                                plugin_execution_ns,
                                Some(&original_request_path),
                                grpc_web_response_content_type,
                            )
                            .await);
                        }
                        Err(grpc_proxy::GrpcRequestBodyCollectError::Proxy(e)) => {
                            let (grpc_status, message) = match e {
                                GrpcProxyError::ResourceExhausted(message) => {
                                    (grpc_proxy::grpc_status::RESOURCE_EXHAUSTED, message)
                                }
                                other => (
                                    grpc_proxy::grpc_status::INTERNAL,
                                    format!("Failed to read gRPC request body: {other:?}"),
                                ),
                            };
                            record_request(&state, StatusCode::OK.as_u16());
                            return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                                grpc_status,
                                &message,
                                initial_response_header_policy_plugins.as_ref(),
                            ));
                        }
                    }
                }
                ClientRequestBody::Buffered(buffered) => {
                    if state.max_grpc_recv_size_bytes > 0
                        && buffered.body.len() > state.max_grpc_recv_size_bytes
                    {
                        record_request(&state, StatusCode::OK.as_u16());
                        return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                            grpc_proxy::grpc_status::RESOURCE_EXHAUSTED,
                            &format!(
                                "gRPC request payload size exceeds maximum of {} bytes",
                                state.max_grpc_recv_size_bytes
                            ),
                            initial_response_header_policy_plugins.as_ref(),
                        ));
                    }
                    (
                        buffered.method,
                        buffered.headers,
                        Bytes::from(buffered.body),
                    )
                }
            };

            // Store body metadata for plugins that read via ctx.metadata
            let request_body_size_bytes = grpc_req_body.len().to_string();
            ctx.metadata.insert(
                "request_body_size_bytes".to_string(),
                request_body_size_bytes.clone(),
            );
            if let Some(body_hook_ctx) = deferred_body_hook_ctx.as_mut() {
                body_hook_ctx.metadata.insert(
                    "request_body_size_bytes".to_string(),
                    request_body_size_bytes,
                );
            }

            // Mirror pre-transform bytes into the shared request-bytes counter
            // so `TransactionSummary.bytes_sent` is populated on the gRPC
            // path too. `fetch_max` preserves the first-attempt count across
            // plugin-driven body rewrites.
            ctx.bytes_sent_observed.fetch_max(
                grpc_req_body.len() as u64,
                std::sync::atomic::Ordering::Release,
            );

            // Transform request body via plugins (e.g., gRPC-Web base64 decoding)
            let mut hook_headers = owned_proxy_headers_ref.unwrap_or(&ctx.headers).clone();
            hook_headers
                .entry(":path".to_string())
                .or_insert_with(|| path.clone());
            let grpc_deadline_at = ctx.grpc_deadline_at();
            let grpc_req_body = bytes::Bytes::from(
                apply_request_body_plugins_with_context(
                    &plugins,
                    deferred_body_hook_ctx.as_mut(),
                    grpc_deadline_at,
                    &hook_headers,
                    grpc_req_body.to_vec(),
                )
                .await,
            );

            // Run on_final_request_body hooks (e.g., protobuf validation)
            let mut body_hook_ctx = deferred_body_hook_ctx.take();
            let final_body_result = run_final_request_body_hooks(
                &plugins,
                body_hook_ctx.as_mut(),
                grpc_deadline_at,
                &hook_headers,
                &grpc_req_body,
            )
            .await;
            if let Some(body_hook_ctx) = body_hook_ctx {
                if body_hook_ctx.gateway_deadline_response_selected() {
                    ctx.mark_gateway_deadline_response_selected();
                }
                // `clone_for_final_request_body_hooks` omits `request_body`; carry
                // the original across the metadata swap (no on_final hook touches
                // it). Disjoint field assignments avoid a whole-`ctx` borrow.
                let request_body = ctx.metadata.remove("request_body");
                ctx.metadata = body_hook_ctx.metadata;
                ctx.ai_usage_export = body_hook_ctx.ai_usage_export;
                if let Some(body) = request_body {
                    ctx.metadata.insert("request_body".to_string(), body);
                }
                ctx.waf_metadata_initialized = body_hook_ctx.waf_metadata_initialized;
                ctx.waf_owned_metadata = body_hook_ctx.waf_owned_metadata;
                ctx.waf_instance_scores = body_hook_ctx.waf_instance_scores;
            }
            match final_body_result {
                PluginResult::Continue => {}
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let Some(reject) = plugin_result_into_reject_parts(reject) else {
                        warn!("reject plugin result could not be converted to response parts");
                        record_request(&state, StatusCode::INTERNAL_SERVER_ERROR.as_u16());
                        return Ok(build_response(
                            StatusCode::INTERNAL_SERVER_ERROR,
                            "Internal Server Error",
                        ));
                    };
                    let status = StatusCode::from_u16(reject.status_code)
                        .unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
                    let normalized =
                        finalize_reject_response_with_after_proxy_hooks_and_commit_policy(
                            &plugins,
                            &mut ctx,
                            status,
                            &reject.body,
                            reject.headers,
                            true,
                            grpc_web_response_content_type.is_none(),
                        )
                        .await;
                    apply_grpc_reject_metadata(&mut ctx, &normalized);
                    let grpc_web_response = build_grpc_web_reject_response(
                        &plugins,
                        &mut ctx,
                        grpc_web_response_content_type,
                        &normalized,
                    )
                    .await;
                    record_request(&state, normalized.http_status.as_u16());
                    if let Some(response) = grpc_web_response {
                        return Ok(response);
                    }
                    return Ok(build_response_from_normalized_reject(normalized));
                }
            }

            // Dispatch to backend with pre-collected body bytes.
            //
            // The collected request body must be returned to the caller
            // regardless of `grpc_should_stream` — retries fire on
            // CONNECTION errors that occur BEFORE response headers, so the
            // streaming-or-not choice for the response has no bearing on
            // whether the request body needs to be replayable. Returning
            // `Bytes::new()` here on the streaming branch silently fed the
            // retry loop an empty body whenever a body-hook proxy also had
            // `retry_on_connect_failure` enabled. Mirrors the same
            // single-return contract used by the buffered-request gRPC path.
            backend_admission_permits = match backend_dispatch::run_backend_admission_plugins(
                backend_admission_plugins.as_ref(),
                &ctx,
                &proxy,
                upstream_target.as_deref(),
                ProxyProtocol::Grpc,
            ) {
                Ok(permits) => permits,
                Err(rejection) => {
                    // The initial CB check may have admitted this request as a
                    // HALF_OPEN probe; an adaptive-concurrency reject here must
                    // release that probe slot so the breaker can admit the next
                    // probe (the retry path and HTTP/WS/H3 paths do the same).
                    // Disarm the RAII guard FIRST — its Drop would otherwise
                    // fire a second `record_neutral(true)` on the same breaker,
                    // and the spurious extra decrement can free a DIFFERENT
                    // in-flight probe's slot, over-admitting probes.
                    grpc_probe_guard.disarm();
                    release_circuit_breaker_probe_on_admission_reject(
                        &state,
                        &proxy,
                        cb_target_key.as_deref(),
                        grpc_cb_probe_slot,
                    );
                    return Ok(handle_backend_admission_rejection(
                        rejection,
                        &plugins,
                        &mut ctx,
                        &state,
                        start_time,
                        plugin_execution_ns,
                        Some(&original_request_path),
                        true,
                        grpc_web_response_content_type,
                    )
                    .await);
                }
            };
            grpc_lb_connection_guard = Some(LoadBalancerConnectionGuard::new(
                upstream_target.clone(),
                upstream_balancer.clone(),
            ));
            grpc_backend_admission_started_at = Instant::now();
            let result = grpc_proxy::proxy_grpc_request_core(
                grpc_method,
                grpc_headers,
                grpc_req_body.clone(),
                grpc_dispatch_proxy,
                &grpc_backend_url,
                &state.grpc_pool,
                &state.dns_cache,
                owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                grpc_should_stream,
                state.max_response_body_size_bytes,
                ctx.grpc_deadline_at(),
            )
            .await;
            (result, grpc_req_body)
        } else {
            // Fast path: no plugin body hooks needed
            let grpc_request_was_buffered =
                matches!(&client_request_body, ClientRequestBody::Buffered(_));
            if grpc_can_use_streaming_fast_path && !grpc_request_was_buffered {
                let request = match client_request_body {
                    ClientRequestBody::Streaming(request) => *request,
                    ClientRequestBody::Buffered(_) => {
                        debug_assert!(false, "buffered gRPC body entered streaming fast path");
                        record_request(&state, 500);
                        return Ok(build_response(
                            StatusCode::INTERNAL_SERVER_ERROR,
                            r#"{"error":"Internal error"}"#,
                        ));
                    }
                };
                // Reject an oversized declared Content-Length BEFORE admission, so
                // a capacity rejection cannot mask the size violation as a
                // concurrency reject instead of the deterministic RESOURCE_EXHAUSTED
                // the streaming size limiter produces. The split/mixed gRPC paths
                // enforce the limit during body collection (before admission); this
                // fully-streaming path never collects, so the check is hoisted here
                // (mirrors the reqwest/direct-H2/H3/HBONE ordering). gRPC errors ride
                // on HTTP 200, matching the streaming overflow's logged status.
                if state.max_grpc_recv_size_bytes > 0
                    && let Some(content_length) = request.headers().get("content-length")
                    && let Some(len) = content_length
                        .to_str()
                        .ok()
                        .and_then(|s| s.parse::<usize>().ok())
                    && len > state.max_grpc_recv_size_bytes
                {
                    record_request(&state, 200);
                    return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED,
                        &format!(
                            "gRPC request payload size exceeds maximum of {} bytes",
                            state.max_grpc_recv_size_bytes
                        ),
                        initial_response_header_policy_plugins.as_ref(),
                    ));
                }
                // Fully streaming fast path: forward request body frame-by-
                // frame without collecting. No retries possible (request
                // body consumed on wire) and no body plugins.
                //
                // The backend-health outcome (CB / passive / least-latency) for
                // every streaming response is recorded at response-**body**
                // completion via the deferred dispatch outcome (#1649 items 2/3),
                // so a `2xx`-then-stall is recorded as a failure rather than a
                // phantom header-time success. All this fast path settles eagerly
                // is the HALF_OPEN **probe slot**: for a probe, build a recorder
                // fired from the request body's `Drop` so the single slot is
                // released (NEUTRAL) at upload termination — never pinned for the
                // life of a long server/bidi response stream. No retry on this
                // path means `grpc_final_cb_key == cb_target_key` and
                // `grpc_cb_probe_slot` is unconsumed, so the recorder owns the
                // single slot release. A CLOSED-state (non-probe) request has no
                // slot to settle.
                let body_size_exceeded = Arc::new(std::sync::atomic::AtomicBool::new(false));
                // Build the recorder whenever a breaker is configured (not just for
                // HALF_OPEN probes): on the fully-streaming path it owns the gRPC
                // circuit-breaker outcome, settling it at the join of request-upload
                // termination and response-body completion so a clean SUCCESS waits
                // for the overflow flag to be final while a body FAILURE trips
                // promptly (#1649 item 3 / #1640). `is_half_open_probe` controls
                // only the probe-slot release; CLOSED-state requests still defer the
                // health outcome to the join.
                let upload_observer: Option<Arc<dyn grpc_proxy::GrpcUploadTerminationObserver>> =
                    match proxy.circuit_breaker.as_ref() {
                        Some(cb_config) => {
                            let cb = state.circuit_breaker_cache.get_or_create(
                                &proxy.id,
                                grpc_final_cb_key.as_deref(),
                                cb_config,
                            );
                            // Pass the guard window as a duration; the recorder
                            // anchors it to response-header arrival rather than
                            // dispatch start (see `start_post_header_upload_timeout`).
                            let post_header_upload_timeout_ms =
                                grpc_proxy::streaming_post_header_upload_timeout_ms_after_proxy_headers(
                                    request.headers(),
                                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                                    proxy.as_ref(),
                                );
                            let recorder = Arc::new(GrpcStreamingProbeRecorder::new(
                                cb,
                                grpc_cb_probe_slot,
                                Arc::clone(&body_size_exceeded),
                                post_header_upload_timeout_ms,
                                cb_admission_open_epoch,
                            ));
                            grpc_streaming_probe_recorder = Some(Arc::clone(&recorder));
                            // `let`-binding the trait object drives the
                            // `Arc<Concrete>` -> `Arc<dyn Trait>` unsizing
                            // coercion (`as` cannot do this).
                            let observer: Arc<dyn grpc_proxy::GrpcUploadTerminationObserver> =
                                recorder;
                            Some(observer)
                        }
                        // No breaker: nothing to record. The deferred dispatch
                        // outcome still records passive-health + least-latency.
                        None => None,
                    };
                backend_admission_permits = match backend_dispatch::run_backend_admission_plugins(
                    backend_admission_plugins.as_ref(),
                    &ctx,
                    &proxy,
                    upstream_target.as_deref(),
                    ProxyProtocol::Grpc,
                ) {
                    Ok(permits) => permits,
                    Err(rejection) => {
                        // Release the CB HALF_OPEN probe slot before rejecting, as on
                        // the other admission paths (see the split-path branch above).
                        // Disarm the RAII guard first so its Drop doesn't double-release.
                        grpc_probe_guard.disarm();
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            grpc_cb_probe_slot,
                        );
                        return Ok(handle_backend_admission_rejection(
                            rejection,
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            plugin_execution_ns,
                            Some(&original_request_path),
                            true,
                            grpc_web_response_content_type,
                        )
                        .await);
                    }
                };
                grpc_lb_connection_guard = Some(LoadBalancerConnectionGuard::new(
                    upstream_target.clone(),
                    upstream_balancer.clone(),
                ));
                grpc_backend_admission_started_at = Instant::now();
                let result = grpc_proxy::proxy_grpc_request_streaming(
                    request,
                    grpc_dispatch_proxy,
                    &grpc_backend_url,
                    &state.grpc_pool,
                    &state.dns_cache,
                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                    state.max_grpc_recv_size_bytes,
                    body_size_exceeded,
                    upload_observer,
                    ctx.grpc_deadline_at(),
                    &mut held_frontend_grpc_upload,
                )
                .await;
                (result, Bytes::new())
            } else {
                // Mixed path: collect request body up-front (required for
                // retry replay), or reuse an earlier bounded prebuffer, but
                // propagate the streaming decision to the response so
                // trailers reach the client immediately when safe.
                let collected = match client_request_body {
                    ClientRequestBody::Streaming(request) => {
                        grpc_proxy::collect_grpc_request_body(
                            *request,
                            state.max_grpc_recv_size_bytes,
                            proxy.backend_read_timeout_ms,
                            ctx.grpc_deadline_at(),
                        )
                        .await
                    }
                    ClientRequestBody::Buffered(buffered) => {
                        if state.max_grpc_recv_size_bytes > 0
                            && buffered.body.len() > state.max_grpc_recv_size_bytes
                        {
                            Err(grpc_proxy::GrpcRequestBodyCollectError::Proxy(
                                GrpcProxyError::ResourceExhausted(format!(
                                    "gRPC request payload size exceeds maximum of {} bytes",
                                    state.max_grpc_recv_size_bytes
                                )),
                            ))
                        } else {
                            Ok((
                                buffered.method,
                                buffered.headers,
                                Bytes::from(buffered.body),
                            ))
                        }
                    }
                };
                match collected {
                    Ok((grpc_method, grpc_headers, grpc_req_body)) => {
                        ctx.bytes_sent_observed.fetch_max(
                            grpc_req_body.len() as u64,
                            std::sync::atomic::Ordering::Release,
                        );
                        backend_admission_permits =
                            match backend_dispatch::run_backend_admission_plugins(
                                backend_admission_plugins.as_ref(),
                                &ctx,
                                &proxy,
                                upstream_target.as_deref(),
                                ProxyProtocol::Grpc,
                            ) {
                                Ok(permits) => permits,
                                Err(rejection) => {
                                    // Release the CB HALF_OPEN probe slot before
                                    // rejecting, as on the other admission paths.
                                    // Disarm the RAII guard first so its Drop
                                    // doesn't double-release.
                                    grpc_probe_guard.disarm();
                                    release_circuit_breaker_probe_on_admission_reject(
                                        &state,
                                        &proxy,
                                        cb_target_key.as_deref(),
                                        grpc_cb_probe_slot,
                                    );
                                    return Ok(handle_backend_admission_rejection(
                                        rejection,
                                        &plugins,
                                        &mut ctx,
                                        &state,
                                        start_time,
                                        plugin_execution_ns,
                                        Some(&original_request_path),
                                        true,
                                        grpc_web_response_content_type,
                                    )
                                    .await);
                                }
                            };
                        grpc_lb_connection_guard = Some(LoadBalancerConnectionGuard::new(
                            upstream_target.clone(),
                            upstream_balancer.clone(),
                        ));
                        grpc_backend_admission_started_at = Instant::now();
                        let result = grpc_proxy::proxy_grpc_request_core(
                            grpc_method,
                            grpc_headers,
                            grpc_req_body.clone(),
                            grpc_dispatch_proxy,
                            &grpc_backend_url,
                            &state.grpc_pool,
                            &state.dns_cache,
                            owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                            grpc_should_stream,
                            state.max_response_body_size_bytes,
                            ctx.grpc_deadline_at(),
                        )
                        .await;
                        (result, grpc_req_body)
                    }
                    Err(grpc_proxy::GrpcRequestBodyCollectError::TimedOut) => {
                        // As in the split path, the armed RAII guard performs the
                        // sole neutral probe release on this early return.
                        record_request(&state, StatusCode::OK.as_u16());
                        return Ok(build_request_body_timeout_response(
                            true,
                            grpc_web_response_content_type,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        ));
                    }
                    Err(grpc_proxy::GrpcRequestBodyCollectError::DeadlineExceeded) => {
                        grpc_probe_guard.disarm();
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            cb_target_key.as_deref(),
                            grpc_cb_probe_slot,
                        );
                        drop(preacquired_backend_admission.take_if_acquired());
                        return Ok(finalize_upload_deadline_rejection(
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            "grpc_deadline_buffered_grpc_upload",
                            plugin_execution_ns,
                            Some(&original_request_path),
                            grpc_web_response_content_type,
                        )
                        .await);
                    }
                    Err(grpc_proxy::GrpcRequestBodyCollectError::Proxy(error)) => {
                        (Err(error), Bytes::new())
                    }
                }
            }
        };

        // Only build retry parts when retries are configured
        let grpc_method = hyper::Method::POST; // gRPC always uses POST
        let grpc_req_headers: hyper::HeaderMap = if grpc_has_retry {
            let mut hm = hyper::HeaderMap::new();
            for (k, v) in owned_proxy_headers_ref.unwrap_or(&ctx.headers) {
                if let (Ok(name), Ok(val)) = (
                    hyper::header::HeaderName::from_bytes(k.as_bytes()),
                    hyper::header::HeaderValue::from_str(v),
                ) {
                    hm.insert(name, val);
                }
            }
            hm
        } else {
            hyper::HeaderMap::new()
        };

        // gRPC retry loop — retries on connection failures
        if grpc_has_retry && let Some(retry_config) = &proxy.retry {
            let mut grpc_attempt = 0u32;
            let mut grpc_current_target = upstream_target.clone();
            let mut grpc_current_cb_key = cb_target_key.clone();

            loop {
                // Classify the error and determine if retryable. Narrow to
                // the connect-class kinds via `is_connect_class()` so
                // `retry_on_connect_failure` cannot replay non-idempotent
                // gRPC POSTs after a `BackendRequest` failure (post-wire,
                // emitted from `send_request().await` after the H2 stream
                // has been opened — request bytes may already be on the
                // wire). The wildcard `BackendUnavailable { .. }` matcher
                // previously here let post-wire errors bypass
                // `retry_on_methods`.
                let is_connection_error = match &grpc_result {
                    // A gateway-side egress denial (DnsResolution kind whose message
                    // carries "egress policy") dialed no backend → not connect-class.
                    Err(GrpcProxyError::BackendUnavailable { kind, message, .. }) => {
                        kind.is_connect_class() && !message.contains("egress policy")
                    }
                    Err(GrpcProxyError::BackendTimeout {
                        kind: grpc_proxy::GrpcTimeoutKind::Connect,
                        ..
                    }) => true,
                    _ => false,
                };
                if grpc_attempt >= retry_config.max_retries
                    || !is_connection_error
                    || !retry_config.retry_on_connect_failure
                {
                    break;
                }

                // Resolve and validate the next gRPC retry target before
                // charging this failure as an intermediate attempt or
                // entering backoff. A path-changing candidate will never be
                // dispatched, so the ordinary final-outcome path must record
                // the failed attempt exactly once without adding retry delay.
                let next_retry_target = if let (Some(_upstream_id), Some(prev_target)) =
                    (&proxy.upstream_id, &grpc_current_target)
                    && let Some(ref hash_key) = lb_hash_key
                    && let Some(next) = backend_dispatch::select_next_retry_target(
                        &state,
                        &epoch,
                        &proxy,
                        prev_target,
                        hash_key,
                        &ctx.client_ip,
                        owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                    ) {
                    if !retry_target_preserves_backend_path(
                        backend_path_is_policy_bound,
                        &proxy,
                        &path,
                        strip_len,
                        prev_target,
                        &next,
                    ) {
                        warn!(
                            proxy_id = %proxy.id,
                            "Aborting gRPC retry because the candidate would change the authorized backend method path"
                        );
                        break;
                    }
                    Some(next)
                } else {
                    None
                };

                if let Some(permits) = backend_admission_permits.take() {
                    let error_class = match &grpc_result {
                        Err(error) => Some(retry::classify_grpc_proxy_error(error)),
                        Ok(_) => None,
                    };
                    permits.record_backend_outcome(BackendAdmissionOutcome {
                        response_status: 502,
                        connection_error: true,
                        error_class,
                        backend_elapsed: grpc_backend_admission_started_at.elapsed(),
                    });
                }
                let grpc_retry_error_class = match &grpc_result {
                    Err(error) => Some(retry::classify_grpc_proxy_error(error)),
                    Ok(_) => None,
                };
                record_grpc_backend_dispatch_outcome(
                    &state,
                    &proxy,
                    &epoch.load_balancer,
                    upstream_balancer.as_ref(),
                    grpc_current_target.as_ref(),
                    grpc_current_cb_key.as_deref(),
                    502,
                    true,
                    grpc_retry_error_class,
                    grpc_backend_admission_started_at.elapsed(),
                );
                drop(grpc_lb_connection_guard.take());

                // Record circuit breaker failure for current target
                if let Some(cb_config) = &proxy.circuit_breaker {
                    let cb = state.circuit_breaker_cache.get_or_create(
                        &proxy.id,
                        grpc_current_cb_key.as_deref(),
                        cb_config,
                    );
                    cb.record_failure(502, true, grpc_cb_probe_slot);
                    // This intermediate failure consumes the probe slot (if any);
                    // the post-dispatch record must not decrement it again.
                    grpc_cb_probe_slot = false;
                    // The probe slot this guard would release on drop has now
                    // been released by record_failure above, so disarm it.
                    // Otherwise a future dropped during the retry backoff/next
                    // attempt would call record_neutral on the same breaker and
                    // release a second slot (over-admitting probes when
                    // half_open_max_requests > 1).
                    grpc_probe_guard.disarm();
                }

                let delay = retry::retry_delay(retry_config, grpc_attempt);
                if let Some(deadline) = ctx.grpc_deadline_at() {
                    if tokio::time::timeout_at(deadline, tokio::time::sleep(delay))
                        .await
                        .is_err()
                    {
                        grpc_result = Err(GrpcProxyError::ClientDeadlineExceeded(
                            "gRPC deadline exceeded during retry backoff".to_string(),
                        ));
                        break;
                    }
                } else {
                    tokio::time::sleep(delay).await;
                }
                grpc_attempt += 1;

                // Save the pre-rotation CB key so that if the rotated target's
                // breaker rejects below, the already-recorded current outcome
                // stays attributed to the target that produced it. Mirrors the
                // HTTP retry path.
                let grpc_pre_rotation_cb_key = grpc_current_cb_key.clone();
                let grpc_pre_rotation_target = grpc_current_target.clone();

                // Try a different target on retry if load balancing is configured
                if let Some(next) = next_retry_target {
                    grpc_backend_url = build_backend_url_with_target(
                        &proxy,
                        &path,
                        effective_query_string.as_ref(),
                        &next.host,
                        next.port,
                        strip_len,
                        next.path.as_deref(),
                    );
                    grpc_current_cb_key =
                        Some(crate::circuit_breaker::target_key(&next.host, next.port));
                    grpc_final_cb_key = grpc_current_cb_key.clone();
                    grpc_current_target = Some(next);
                }

                // Retry backoff and target rotation cross a fresh policy
                // boundary: the selected app port may differ from the first
                // attempt, and live reload may have tightened even the same
                // port. Re-check before any retry-target breaker/admission
                // state is acquired and before the gRPC pool can dispatch.
                if let Some(mismatch) = mesh_inbound_peer_auth_transport_mismatch(
                    &state,
                    ctx.mesh_direction,
                    mesh_inbound_pre_handshake_app_port,
                    &proxy,
                    grpc_current_target.as_deref(),
                    is_tls,
                    ctx.tls_client_cert_der.is_some(),
                ) {
                    return Ok(reject_mesh_inbound_peer_auth_transport_mismatch(
                        &state,
                        &plugins,
                        &mut ctx,
                        &proxy,
                        mismatch,
                        is_tls,
                        true,
                        start_time,
                        plugin_execution_ns,
                        "mesh_inbound_peer_auth_retry_target_mismatch",
                        Some(&original_request_path),
                    )
                    .await);
                }

                // Re-screen the (possibly LB-rotated) retry target for mesh
                // transport tags (issue #2003): the initial-attempt guard /
                // fall-through above only classified the FIRST selected target,
                // and this loop dials `GrpcConnectionPool` directly — a rotation
                // onto a mesh-tagged target (mixed mesh/non-mesh upstream) must
                // fail closed, never direct-dial past the secured transport.
                // `MeshMtls` / `MeshMtlsCrossCluster` also refuse here (any
                // non-`Direct` classification does): the generic mesh-mTLS path
                // cannot dispatch retries (`!has_retry` gate), so there is no
                // transport to switch to mid-loop. No circuit-breaker probe
                // slot is held for the new target yet (the breaker is checked
                // just below), so only the request is counted — mirrors the
                // egress-policy re-screen below.
                if let Some(ref rotated_target) = grpc_current_target
                    && grpc_proxy::classify_grpc_mesh_dispatch(rotated_target)
                        != grpc_proxy::GrpcMeshDispatch::Direct
                {
                    warn!(
                        proxy_id = %proxy.id,
                        target_host = %rotated_target.host,
                        "gRPC retry rotated onto a mesh-transport-tagged target; \
                         refusing the direct dial and failing closed with gRPC UNAVAILABLE"
                    );
                    record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
                    if let Some(content_type) = grpc_web_response_content_type {
                        return Ok(build_grpc_web_error_response(
                            content_type,
                            14,
                            "gRPC retry target requires a mesh transport that does not support retries",
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        ));
                    }
                    if grpc_request_is_web_translated
                        && let Some(response) = build_translated_grpc_web_error_response(
                            &ctx,
                            14,
                            "gRPC retry target requires a mesh transport that does not support retries",
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        )
                    {
                        return Ok(response);
                    }
                    return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                        14, // UNAVAILABLE
                        "gRPC retry target requires a mesh transport that does not support retries",
                        initial_response_header_policy_plugins.as_ref(),
                    ));
                }

                // Re-screen the (possibly LB-rotated) retry target before
                // dispatch: the gRPC pool self-resolves via `DnsCache::resolve`
                // (canonical `IpAddr` fast path; non-canonical → real DNS +
                // resolved-address screen), so use the canonical screen here too
                // (mirrors the first-attempt gRPC screen) — the URL-canonicalizing
                // one would wrongly reject a legitimate all-numeric hostname. No
                // circuit-breaker probe slot is held for the new target yet (the
                // breaker is checked just below), so only the request is counted.
                if let Some(ref rotated_target) = grpc_current_target
                    && denied_literal_backend_ip_canonical(
                        &rotated_target.host,
                        &state.env_config.backend_allow_ips,
                    )
                    .is_some()
                {
                    warn!(
                        proxy_id = %proxy.id,
                        backend = %rotated_target.host,
                        "Backend egress policy denied literal-IP gRPC retry target; not dialing"
                    );
                    record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
                    return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                        14,
                        "backend address blocked by egress policy",
                        initial_response_header_policy_plugins.as_ref(),
                    ));
                }

                // Enforce the (possibly rotated) target's circuit breaker before
                // dispatching this retry, mirroring the HTTP retry path. Without
                // this gate a retry can dispatch to — and then record an outcome
                // against — a target whose breaker is OPEN or has no free
                // HALF_OPEN probe slot, letting an unadmitted retry advance or
                // close a breaker that should have rejected the attempt.
                if let Some(cb_config) = &proxy.circuit_breaker {
                    match state
                        .circuit_breaker_cache
                        .can_execute_with_admission_epoch(
                            &proxy.id,
                            grpc_current_cb_key.as_deref(),
                            cb_config,
                        ) {
                        Ok((cb, is_half_open_probe, admission_open_epoch)) => {
                            grpc_cb_probe_slot = is_half_open_probe;
                            // #1649 R6 finding 1: re-capture the admission epoch for
                            // the rotated target so the deferred body-completion
                            // outcome is stale-checked against THIS target's
                            // generation, not the initial target's.
                            cb_admission_open_epoch = admission_open_epoch;
                            // #1649 R6 finding 4: re-point the probe-release guard at
                            // the rotated target. On rotation the guard was disarmed
                            // (after recording the prior target's intermediate
                            // failure), so without this a HALF_OPEN slot acquired on
                            // the rotated target would never be released on the
                            // buffered streaming path (the deferred outcome records
                            // the health as a non-probe). The buffered/retry request
                            // has finished uploading, so header-flush release (guard
                            // Drop) is the correct timing; the eager-record arms below
                            // disarm the guard and release via `grpc_cb_probe_slot`.
                            grpc_probe_guard.cb = is_half_open_probe.then(|| Arc::clone(&cb));
                            grpc_probe_guard.armed = is_half_open_probe;
                        }
                        Err(_) => {
                            // Rotated/retried target's breaker rejected: don't
                            // dispatch to it. The current grpc_result (the
                            // connection error recorded at the top of this
                            // iteration) stays as the outcome. Restore the final
                            // key to the target that produced it and skip the
                            // post-dispatch record so we neither double-record
                            // nor attribute to the never-dispatched target.
                            grpc_final_cb_key = grpc_pre_rotation_cb_key;
                            grpc_final_upstream_target = grpc_pre_rotation_target;
                            grpc_skip_final_cb_record = true;
                            break;
                        }
                    }
                }

                backend_admission_permits = match backend_dispatch::run_backend_admission_plugins(
                    backend_admission_plugins.as_ref(),
                    &ctx,
                    &proxy,
                    grpc_current_target.as_deref(),
                    ProxyProtocol::Grpc,
                ) {
                    Ok(permits) => permits,
                    Err(rejection) => {
                        // Disarm the RAII guard first so its Drop doesn't
                        // double-release: after a rotation the guard was re-armed to
                        // this target (#1649 R6 finding 4), so the explicit release
                        // below would otherwise be duplicated by the guard's Drop.
                        grpc_probe_guard.disarm();
                        release_circuit_breaker_probe_on_admission_reject(
                            &state,
                            &proxy,
                            grpc_current_cb_key.as_deref(),
                            grpc_cb_probe_slot,
                        );
                        return Ok(handle_backend_admission_rejection(
                            rejection,
                            &plugins,
                            &mut ctx,
                            &state,
                            start_time,
                            plugin_execution_ns,
                            Some(&original_request_path),
                            true,
                            grpc_web_response_content_type,
                        )
                        .await);
                    }
                };

                warn!(
                    proxy_id = %proxy.id,
                    attempt = grpc_attempt,
                    max_retries = retry_config.max_retries,
                    "Retrying gRPC backend request"
                );

                // Stream the retry response under the same conditions as
                // the initial attempt. The retry loop only fires on
                // CONNECTION errors that surface BEFORE response headers
                // (`BackendUnavailable` / `BackendTimeout::Connect`) — once
                // a response begins, this loop breaks out and never touches
                // the body, so passing `grpc_should_stream=true` here is
                // safe and necessary to keep the trailer-stall fix that
                // motivates this PR working when the very first connect
                // hiccups (otherwise a transient TCP RST silently downgrades
                // a streaming RPC to fully buffered).
                //
                // Re-resolve the effective proxy for the (possibly rotated)
                // current target so per-port `connect_timeout_ms` overrides
                // apply to the retried backend. Same per-target-rotation
                // contract as `proxy_to_backend_inner`.
                let grpc_retry_effective_proxy = resolve_backend_connection_proxy_for_target(
                    &proxy,
                    grpc_current_target.as_deref(),
                );
                grpc_final_upstream_target = grpc_current_target.clone();
                grpc_lb_connection_guard = Some(LoadBalancerConnectionGuard::new(
                    grpc_current_target.clone(),
                    upstream_balancer.clone(),
                ));
                grpc_backend_admission_started_at = Instant::now();
                grpc_result = grpc_proxy::proxy_grpc_request_from_bytes(
                    grpc_method.clone(),
                    grpc_req_headers.clone(),
                    grpc_body_bytes.clone(),
                    grpc_retry_effective_proxy.as_ref(),
                    &grpc_backend_url,
                    &state.grpc_pool,
                    &state.dns_cache,
                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                    grpc_should_stream,
                    state.max_response_body_size_bytes,
                    ctx.grpc_deadline_at(),
                )
                .await;
            }
        }

        // Record non-streaming final backend outcomes to the circuit breaker
        // once, here, and disarm the neutral-release guard. Buffered gRPC
        // results and dispatch errors have no late streaming request-body flag,
        // so they can mirror the HTTP path and record before response handling.
        // Streaming responses defer to the streaming arm so it can sample the
        // request-body flag at response-header time and arm the post-header
        // probe guard before response hooks run.
        //
        // Previously the gRPC path recorded nothing here, so the breaker never
        // saw gRPC successes (could not recover from HALF_OPEN) or non-connect
        // failures (could not trip). check_circuit_breaker admitted any probe
        // against cb_target_key; the retry loop already recorded per-attempt
        // failures (and disarmed the guard) for rotated targets, and
        // grpc_skip_final_cb_record marks the case where a rotated retry's
        // breaker rejected (already recorded for the prior target).
        if !grpc_skip_final_cb_record && let Some(cb_config) = &proxy.circuit_breaker {
            let cb = state.circuit_breaker_cache.get_or_create(
                &proxy.id,
                grpc_final_cb_key.as_deref(),
                cb_config,
            );
            match &grpc_result {
                // Classify buffered responses by the backend's HTTP status,
                // like the HTTP path. An oversized client request detected
                // BEFORE backend headers is GrpcProxyError::ResourceExhausted
                // (neutral arm below); streaming responses defer to the
                // streaming arm, where HALF_OPEN fast-path probes can
                // neutralize late upload overflows via the deferred recorder.
                Ok(GrpcResponseKind::Buffered(r)) => {
                    grpc_probe_guard.disarm();
                    record_grpc_backend_status_outcome(&cb, r.status, grpc_cb_probe_slot);
                }
                Ok(GrpcResponseKind::Streaming(_)) => {
                    // Defer: the streaming arm finalizes via
                    // finalize_grpc_streaming_probe_outcome. For a HALF_OPEN probe
                    // on the fully-streaming fast path that hands off to
                    // GrpcStreamingProbeRecorder, which classifies the probe at
                    // request-upload termination — so a client-upload overflow that
                    // only trips during response-body streaming records NEUTRAL and
                    // releases the HALF_OPEN probe slot instead of falsely healing
                    // the backend. CLOSED-state (non-probe) requests and the
                    // buffered-request streaming path record immediately by backend
                    // status (a backend failure trips the breaker without waiting
                    // for a long/slow upload to finish).
                }
                // Oversized CLIENT request payloads (ResourceExhausted, detected
                // before backend headers) and client-body-read / gateway-config
                // errors (Internal) are client/gateway-side, not backend
                // failures. Record NEUTRAL so client behavior cannot trip or
                // reopen the backend breaker — mirroring the HTTP path's
                // ClientDisconnect -> record_neutral. An oversized BACKEND
                // response is GrpcProxyError::ResponseTooLarge (NOT
                // ResourceExhausted) and falls to the failure arm below, matching
                // the HTTP path's ResponseBodyTooLarge -> 502.
                Err(
                    GrpcProxyError::ClientDeadlineExceeded(_)
                    | GrpcProxyError::ResourceExhausted(_)
                    | GrpcProxyError::Internal(_),
                ) => {
                    grpc_probe_guard.disarm();
                    cb.record_neutral(grpc_cb_probe_slot);
                }
                Err(e) => {
                    grpc_probe_guard.disarm();
                    let connection_error = matches!(
                        e,
                        GrpcProxyError::BackendUnavailable { kind, message, .. }
                        // A gateway-side egress denial (DnsResolution kind whose
                        // message carries "egress policy") dialed no backend, so it
                        // is NOT a connect-class failure even though the kind is.
                        if kind.is_connect_class() && !message.contains("egress policy")
                    ) || matches!(
                        e,
                        GrpcProxyError::BackendTimeout {
                            kind: grpc_proxy::GrpcTimeoutKind::Connect,
                            ..
                        }
                    );
                    cb.record_failure(502, connection_error, grpc_cb_probe_slot);
                }
            }
        }

        let backend_total_ms = backend_start.elapsed().as_secs_f64() * 1000.0;

        match grpc_result {
            Ok(GrpcResponseKind::Streaming(grpc_streaming)) => {
                let grpc_backend_admission_elapsed = grpc_backend_admission_started_at.elapsed();
                // Frame-by-frame streaming path: headers arrived, body not buffered.
                // Settle the HALF_OPEN probe slot before after_proxy hooks so the
                // post-header upload guard is measured from header arrival, even
                // if a response hook blocks.
                if !grpc_skip_final_cb_record {
                    finalize_grpc_streaming_probe_outcome(
                        grpc_streaming_probe_recorder.as_ref(),
                        &mut grpc_probe_guard,
                    );
                }

                // after_proxy plugins run on headers only (body is not yet in memory).
                let mut response_headers: HashMap<String, String> = grpc_streaming.headers;
                let grpc_header_status =
                    grpc_proxy::grpc_status_from_maps(&EMPTY_HEADERS, &response_headers);
                if let Some(grpc_status) = grpc_header_status {
                    ctx.metadata
                        .insert("grpc_status".to_string(), grpc_status.to_string());
                }
                let grpc_backend_dispatch_status = grpc_proxy::grpc_admission_status_from_maps(
                    &EMPTY_HEADERS,
                    &response_headers,
                    grpc_streaming.status,
                );
                // #1649 item 3: a streamable non-failure streaming header defers the circuit
                // breaker — for the fully-streaming path the recorder settles it at
                // the upload-termination + response-completion join (overflow-aware,
                // #1640), and for the buffered-request path the deferred dispatch
                // records it at response completion. A KNOWN failure status at
                // header time (a trailers-only error mapped to 5xx, or a sandwiched
                // LB 5xx) — and an already-end-of-stream body (gRPC Trailers-Only)
                // whose outcome is final now — is recorded EAGERLY here so the
                // breaker trips/heals promptly instead of waiting out a possibly
                // long-lived/stalled upload (matches
                // `grpc_streaming_closed_state_backend_failure_trips_breaker_at_header_time`
                // and #1649 round-2 finding C). The eager record is a non-probe (the
                // recorder owns the slot release); the recorder is then marked so it
                // does not double-record.
                let grpc_body_ended = http_body::Body::is_end_stream(&grpc_streaming.body);
                // Set when an already-ended CLEAN response is handed to the recorder
                // (#1649 R8 finding 1): the body-terminal observer must then be
                // suppressed so the ended body's `Drop` can't deliver a second
                // (ClientDisconnect) terminal that neutralizes the deferred success.
                let pristine_streaming_trailers_only_terminal_metadata =
                    grpc_body_ended.then(|| {
                        grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(&response_headers)
                    });
                let pristine_streaming_grpc_web_terminal_names =
                    (grpc_web_response_content_type.is_some() && grpc_body_ended).then(|| {
                        response_headers
                            .keys()
                            .cloned()
                            .collect::<HashSet<String>>()
                    });
                let mut grpc_recorder_owns_ended_response = false;
                let grpc_cb_recorded_eagerly = if grpc_skip_final_cb_record {
                    // A rotated retry already recorded (and released) the prior
                    // target's breaker — never record again here.
                    true
                } else if grpc_streaming_dispatch_should_defer(
                    &proxy,
                    grpc_backend_dispatch_status,
                    grpc_body_ended,
                ) {
                    false
                } else if grpc_body_ended
                    && let Some(recorder) = &grpc_streaming_probe_recorder
                    && !proxy.circuit_breaker.as_ref().is_some_and(|cb| {
                        cb.failure_status_codes
                            .contains(&grpc_backend_dispatch_status)
                    })
                {
                    // #1649 R8 finding 1 (re-raised R6-5): an already-ended CLEAN gRPC
                    // success (Trailers-Only / empty 2xx) with a recorder must NOT be
                    // banked eagerly. A client upload still in flight could overflow
                    // `max_grpc_recv_size_bytes` AFTER the response ends, and only the
                    // recorder's upload-termination join re-checks the overflow flag.
                    // Hand the clean outcome to the recorder (it defers the success to
                    // upload termination, overflow-aware) and suppress the
                    // body-terminal observer below. A KNOWN failure status still falls
                    // through to the eager arm so it trips promptly.
                    crate::proxy::body::GrpcResponseTerminalObserver::on_response_terminal(
                        recorder.as_ref(),
                        grpc_backend_dispatch_status,
                        false,
                        None,
                    );
                    grpc_recorder_owns_ended_response = true;
                    false
                } else if let Some(cb_config) = &proxy.circuit_breaker {
                    let cb = state.circuit_breaker_cache.get_or_create(
                        &proxy.id,
                        grpc_final_cb_key.as_deref(),
                        cb_config,
                    );
                    record_grpc_backend_status_outcome(&cb, grpc_backend_dispatch_status, false);
                    if let Some(recorder) = &grpc_streaming_probe_recorder {
                        recorder.mark_health_recorded();
                    }
                    true
                } else {
                    // No breaker configured — nothing to record or defer.
                    true
                };
                {
                    let phase_start = Instant::now();
                    if let Some(reject) = run_after_proxy_hooks(
                        &plugins,
                        &mut ctx,
                        grpc_streaming.status,
                        &mut response_headers,
                    )
                    .await
                    {
                        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                        let normalized = normalize_reject_response(
                            StatusCode::from_u16(reject.status_code)
                                .unwrap_or(StatusCode::BAD_GATEWAY),
                            &reject.body,
                            &reject.headers,
                            true,
                        );
                        apply_grpc_reject_metadata(&mut ctx, &normalized);
                        if let Some(permits) = backend_admission_permits.take() {
                            permits.record_backend_outcome(BackendAdmissionOutcome {
                                response_status: grpc_streaming.status,
                                connection_error: false,
                                error_class: None,
                                backend_elapsed: grpc_backend_admission_elapsed,
                            });
                        }
                        // #1649 item 3: record passive-health + least-latency for
                        // the rejected streaming response. The circuit breaker is
                        // owned by the recorder on the fully-streaming path
                        // (settled at the upload-termination join, overflow-aware) —
                        // signal it the header outcome here since the rejected
                        // response body is never wrapped, so a healthy 2xx still
                        // heals once the upload terminates without overflow, while a
                        // client that rejects + overflows cannot falsely heal
                        // (round-2 finding A / round-3 findings). The buffered-request
                        // path (no recorder, upload already complete) records the CB
                        // directly here unless it was recorded eagerly (round-3 B).
                        let reject_skip_cb =
                            grpc_streaming_probe_recorder.is_some() || grpc_cb_recorded_eagerly;
                        // #1649 R5 finding 1 (parity): the buffered-request path
                        // records the CB here directly; skip it if the breaker opened
                        // a new cycle since admission (the recorder path is already
                        // epoch-checked inside `on_response_terminal`). Passive-health
                        // + least-latency still record below.
                        let reject_cb_stale = !reject_skip_cb
                            && backend_dispatch::deferred_circuit_breaker_is_stale(
                                &state,
                                &proxy,
                                grpc_final_cb_key.as_deref(),
                                cb_admission_open_epoch,
                            );
                        backend_dispatch::record_backend_outcome_no_conn_end(
                            &state,
                            &proxy,
                            &epoch.load_balancer,
                            upstream_balancer.as_ref(),
                            grpc_final_upstream_target.as_deref(),
                            grpc_final_cb_key.as_deref(),
                            grpc_backend_dispatch_status,
                            false,
                            None,
                            false,
                            reject_skip_cb || reject_cb_stale,
                            grpc_backend_admission_elapsed,
                        );
                        if let Some(recorder) = &grpc_streaming_probe_recorder {
                            crate::proxy::body::GrpcResponseTerminalObserver::on_response_terminal(
                                recorder.as_ref(),
                                grpc_backend_dispatch_status,
                                false,
                                None,
                            );
                        }
                        drop(grpc_lb_connection_guard.take());
                        // Use `original_request_path` so the log records the
                        // path the client actually requested, not the
                        // VirtualService-rewritten backend path in `ctx.path`.
                        log_rejected_request_with_path(
                            &plugins,
                            &ctx,
                            normalized.http_status.as_u16(),
                            start_time,
                            "after_proxy",
                            plugin_execution_ns,
                            Some(&original_request_path),
                        )
                        .await;
                        record_request(&state, normalized.http_status.as_u16());
                        return Ok(build_response_from_normalized_reject(normalized));
                    }
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                }
                if let Some(pristine_terminal_metadata) =
                    pristine_streaming_trailers_only_terminal_metadata.as_ref()
                {
                    // An already-ended Incoming is a true Trailers-Only response.
                    // Discard policy attempts to rewrite its terminal fields and
                    // restore the backend's pristine status before emission.
                    grpc_proxy::apply_buffered_grpc_initial_response_policy(
                        None,
                        &mut response_headers,
                        Some(pristine_terminal_metadata),
                    );
                }
                // Seed deferred metadata from the final client-visible headers.
                // The snapshot restore above protects a true Trailers-Only status;
                // a later real trailer on an open stream remains authoritative.
                grpc_proxy::refresh_grpc_status_metadata(
                    &mut ctx.metadata,
                    &EMPTY_HEADERS,
                    &response_headers,
                );

                // Check if the streaming request body exceeded the size limit
                // BEFORE logging — otherwise the transaction summary captures a
                // success status while we're about to return RESOURCE_EXHAUSTED.
                let body_exceeded =
                    grpc_request_body_limit_exceeded(&grpc_streaming.request_body_exceeded);

                // Determine the final status for logging and metrics.
                let final_status = if body_exceeded {
                    200_u16
                } else {
                    grpc_streaming.status
                };
                let final_error_class: Option<retry::ErrorClass> = if body_exceeded {
                    Some(retry::ErrorClass::RequestBodyTooLarge)
                } else {
                    None
                };
                if body_exceeded {
                    ctx.metadata.insert(
                        "grpc_status".to_string(),
                        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED.to_string(),
                    );
                }

                let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
                let plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
                let plugin_external_io_ms =
                    ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
                // `backend_total_ms` for the gRPC streaming path is actually the time
                // through response headers (TTFB) — the body is forwarded frame-by-frame
                // by hyper after this point. When body_exceeded aborts streaming, backend
                // work is complete at the abort so total == TTFB. Otherwise the body is
                // still flowing at log time, so backend total is unknown
                // (`LATENCY_UNKNOWN_MS` per schema).
                let streamed = !body_exceeded;
                let grpc_backend_total_ms = if streamed {
                    crate::plugins::LATENCY_UNKNOWN_MS
                } else {
                    backend_total_ms
                };
                let (gateway_processing_ms, gateway_overhead_ms) =
                    TransactionSummary::derive_gateway_latencies(
                        total_ms,
                        grpc_backend_total_ms,
                        plugin_execution_ms,
                        streamed,
                    );

                // Build the summary up front so we can either log synchronously
                // (body_exceeded early-return path) or defer via the streaming
                // body wrapper (non-exceeded streaming path).
                let deferred_grpc_logger: Option<
                    Arc<crate::proxy::deferred_log::DeferredTransactionLogger>,
                > = if !plugins.is_empty() || streamed || final_error_class.is_some() {
                    let grpc_resolved_ip = if !plugins.is_empty() {
                        state
                            .dns_cache
                            .resolve(
                                &proxy.backend_host,
                                proxy.dns_override.as_deref(),
                                proxy.dns_cache_ttl_seconds,
                            )
                            .await
                            .ok()
                            .map(|ip| ip.to_string())
                    } else {
                        None
                    };

                    // Read counters populated earlier in the gRPC body
                    // handling (request bytes) and by the streaming deferred
                    // logger (response bytes, patched at fire time). For
                    // trailers-only error paths the response body is built
                    // synchronously below and its length is not plumbed here
                    // — those paths log with `bytes_received: 0` currently.
                    let bytes_sent = ctx
                        .bytes_sent_observed
                        .load(std::sync::atomic::Ordering::Acquire);
                    let mut metadata = clone_log_metadata(&ctx);
                    metadata
                        .entry("request_protocol".to_string())
                        .or_insert_with(|| "grpc".to_string());
                    let summary = TransactionSummary {
                        namespace: proxy.namespace.clone(),
                        timestamp_received: ctx.timestamp_received.to_rfc3339(),
                        client_ip: ctx.client_ip.clone(),
                        consumer_username: ctx.effective_identity().map(str::to_owned),
                        auth_method: ctx.auth_method,
                        http_method: method,
                        request_path: original_request_path.clone(),
                        proxy_id: Some(proxy.id.clone()),
                        proxy_name: proxy.name.clone(),
                        backend_target: Some(strip_query_params(&grpc_backend_url).to_string()),
                        backend_resolved_ip: grpc_resolved_ip,
                        response_status_code: final_status,
                        latency_total_ms: total_ms,
                        latency_gateway_processing_ms: gateway_processing_ms,
                        latency_backend_ttfb_ms: backend_total_ms,
                        latency_backend_total_ms: grpc_backend_total_ms,
                        latency_plugin_execution_ms: plugin_execution_ms,
                        latency_plugin_external_io_ms: plugin_external_io_ms,
                        latency_gateway_overhead_ms: gateway_overhead_ms,
                        request_user_agent: ctx.headers.get("user-agent").cloned(),
                        response_streamed: streamed,
                        error_class: final_error_class,
                        bytes_sent,
                        metadata,
                        ai_usage_export: ctx.ai_usage_export.clone(),
                        proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
                        ..TransactionSummary::default()
                    };
                    if body_exceeded {
                        // Request body exceeded the size limit; we're about to
                        // return a trailers-only RESOURCE_EXHAUSTED error. The
                        // response body never streams, so start terminal logging
                        // here. An active RPC deadline moves that cleanup to
                        // owned, bounded detached state.
                        crate::plugins::log_with_mirror_before_buffered_response(
                            &plugins, summary, &ctx,
                        )
                        .await;
                        None
                    } else {
                        // Streaming gRPC response: defer so the summary reflects
                        // mid-body RST, client cancellation, and partial bytes.
                        // Thread `start_time` so the deferred logger can
                        // re-derive wall-clock latencies at body-completion
                        // time instead of logging the header-flush snapshot.
                        Some(crate::proxy::deferred_log::DeferredTransactionLogger::new_with_start_time(
                            summary,
                            Arc::clone(&plugins),
                            ctx.clone(),
                            start_time,
                        ))
                    }
                } else {
                    None
                };

                if body_exceeded {
                    drop(backend_admission_permits.take());
                    drop(grpc_lb_connection_guard.take());
                    record_request(&state, 200);
                    return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED,
                        "gRPC request payload size exceeds maximum",
                        initial_response_header_policy_plugins.as_ref(),
                    ));
                }

                record_request(&state, grpc_streaming.status);

                // A client gRPC deadline is an absolute total-body bound. It
                // may replace an unpolled backend body with terminal trailers,
                // so the backend Content-Length cannot remain authoritative.
                let (grpc_read_timeout_ms, grpc_total_deadline) =
                    grpc_proxy::grpc_streaming_response_deadline(
                        grpc_streaming.grpc_deadline_at,
                        grpc_streaming.response_read_timeout_ms,
                    );
                strip_content_length_for_streaming_grpc_deadline(
                    &mut response_headers,
                    grpc_total_deadline,
                );
                let grpc_web_streaming_content_type = grpc_web_response_content_type.filter(|_| {
                    crate::plugins::response_body_rewrite_allowed(grpc_streaming.status)
                });
                let grpc_web_streaming_initial_metadata =
                    grpc_web_streaming_content_type.map(|_| {
                        crate::plugins::grpc_web::take_streaming_initial_terminal_metadata(
                            &mut response_headers,
                            grpc_body_ended,
                            pristine_streaming_grpc_web_terminal_names.as_ref(),
                        )
                    });
                if grpc_web_streaming_content_type.is_some() {
                    // Incremental translation changes the representation size
                    // and carries terminal metadata in a final DATA frame.
                    response_headers.remove("content-length");
                }
                let cl = response_headers
                    .get("content-length")
                    .and_then(|v| v.parse::<u64>().ok());

                // Build the response with the live Incoming body — hyper will forward
                // DATA frames and TRAILERS to the downstream client as they arrive.
                // Split any newline-joined Set-Cookie into separate header lines.
                let resp_builder = headers_mod::apply_response_headers(
                    Response::builder().status(
                        StatusCode::from_u16(grpc_streaming.status).unwrap_or(StatusCode::OK),
                    ),
                    &response_headers,
                );
                // For bidi/client-streaming RPCs where the request body is still
                // sending: GrpcBody::Streaming returns an error when exceeded,
                // which causes hyper to RST_STREAM the request. The backend then
                // resets the response stream, and the Incoming response body
                // naturally propagates the h2 error to the client.

                // Stream H2 DATA frames on the gRPC streaming path.
                //
                // Wrap the backend body in `StripHopByHopTrailers` (via the
                // `*_strip_hop_by_hop_trailers` helper) so RFC 9110 §7.6.1
                // response-direction hop-by-hop names (`connection`,
                // `keep-alive`, `proxy-authenticate`, `proxy-connection`,
                // `te`, `trailer`, `transfer-encoding`, `upgrade`) cannot
                // leak to the downstream client through TRAILERS frames.
                // Without this filter, a misbehaving backend can punch a
                // hole in the proxy boundary by emitting `proxy-authenticate`
                // / `keep-alive` / `connection: close` in the trailer map —
                // hyper's H2 trailer encoder rejects some hop-by-hop names
                // at the frame layer but `proxy-authenticate`,
                // `proxy-connection`, and `keep-alive` are not blocked.
                // Mirrors the buffered-path strip in `grpc_proxy.rs` so the
                // two response paths cannot drift.
                // gRPC streaming body deadline (issue #1649): a client
                // `grpc-timeout` is an end-to-end RPC deadline, honored as an
                // ABSOLUTE deadline (`grpc_total_deadline`) anchored at request
                // receipt (`start_time`); without one, `response_read_timeout_ms`
                // applies per frame. See `grpc_streaming_response_deadline` —
                // shared with the mesh-mTLS `StreamingH2` relay so the two
                // regimes cannot drift.
                let body = if state.response_buffer_cutoff_bytes == 0
                    && state.max_response_body_size_bytes == 0
                {
                    crate::proxy::body::direct_streaming_h2_body_strip_hop_by_hop_trailers(
                        grpc_streaming.body,
                        cl,
                        grpc_read_timeout_ms,
                        grpc_total_deadline,
                    )
                } else if state.max_response_body_size_bytes > 0 {
                    crate::proxy::body::size_limited_coalescing_h2_body_strip_hop_by_hop_trailers(
                        grpc_streaming.body,
                        state.max_response_body_size_bytes,
                        cl,
                        state.h2_coalesce_target_bytes,
                        grpc_read_timeout_ms,
                        grpc_total_deadline,
                    )
                } else {
                    crate::proxy::body::coalescing_h2_body_strip_hop_by_hop_trailers(
                        grpc_streaming.body,
                        cl,
                        state.h2_coalesce_target_bytes,
                        grpc_read_timeout_ms,
                        grpc_total_deadline,
                    )
                };
                let mut body = body;

                // Keep the per-IP concurrent-request guard alive for the full
                // streaming-body lifetime, matching the HTTP streaming path
                // (body.with_per_ip_request_guard). per_ip_guard is a
                // function-scope local that would otherwise drop when this
                // handler returns at header flush — releasing the per-IP slot
                // while the gRPC body and trailers are still streaming, which
                // lets a client evade the per-IP concurrency limit on
                // long-lived streaming RPCs.
                if let Some(guard) = per_ip_guard {
                    body = body.with_per_ip_request_guard(guard);
                }
                if let Some(guard) = grpc_lb_connection_guard.take() {
                    body = body.with_lb_connection_guard(guard);
                }
                // #1649 item 3: the deferred dispatch outcome records passive-health
                // + least-latency at response-body completion. The circuit breaker
                // is owned by the recorder on the fully-streaming path (it settles
                // it at the upload-termination join, overflow-aware) — so skip the CB
                // here and hand the terminal outcome to the recorder via the
                // response-terminal observer. On the buffered-request path (no
                // recorder, upload already complete) the CB is recorded here at
                // response completion unless it was already recorded eagerly.
                let grpc_dispatch_skip_cb =
                    grpc_streaming_probe_recorder.is_some() || grpc_cb_recorded_eagerly;
                body = body
                    .with_deferred_backend_dispatch_outcome(
                        Arc::clone(&state),
                        Arc::clone(&proxy),
                        Arc::clone(&epoch.load_balancer),
                        upstream_balancer.clone(),
                        grpc_final_upstream_target.clone(),
                        grpc_final_cb_key.clone(),
                        grpc_backend_dispatch_status,
                        false, // connection_error: post-wire, derived at body completion
                        None,  // error_class: derived from the terminal body error
                        false, // is_half_open_probe: slot released separately by the recorder
                        grpc_dispatch_skip_cb,
                        grpc_backend_admission_elapsed,
                    )
                    .with_grpc_trailer_backend_dispatch_classification()
                    .with_deferred_dispatch_request_body_exceeded_flag(
                        grpc_streaming.request_body_exceeded.clone(),
                    );
                // #1649 R5 finding 1: on the buffered-request streaming path there
                // is no recorder, so the deferred dispatch records the CB itself at
                // body completion — carry the admission epoch so a stream admitted
                // before the breaker opened a new cycle can't heal/reopen a later
                // HALF_OPEN cycle it never probed (parity with the direct-H2 path and
                // the recorder's own epoch check). With a recorder present the
                // recorder owns the epoch check; when recorded eagerly the CB is
                // skipped here entirely, so the epoch is irrelevant in both cases.
                if grpc_streaming_probe_recorder.is_none() && !grpc_cb_recorded_eagerly {
                    body =
                        body.with_deferred_dispatch_admission_open_epoch(cb_admission_open_epoch);
                }
                // Suppress the body-terminal observer when an already-ended clean
                // response was already handed to the recorder at header time (#1649
                // R8 finding 1) — otherwise the ended body's `Drop` would deliver a
                // second, ClientDisconnect-classified terminal that neutralizes the
                // deferred clean success the recorder is waiting to settle at upload
                // termination.
                if !grpc_recorder_owns_ended_response
                    && let Some(recorder) = &grpc_streaming_probe_recorder
                {
                    let recorder = Arc::clone(recorder);
                    // `let`-binding drives the `Arc<Concrete>` -> `Arc<dyn Trait>`
                    // unsizing coercion.
                    let observer: Arc<dyn crate::proxy::body::GrpcResponseTerminalObserver> =
                        recorder;
                    body = body.with_grpc_response_terminal_observer(observer);
                }
                if let Some(permits) = backend_admission_permits.take() {
                    body = body
                        .with_deferred_backend_admission_outcome(
                            permits,
                            grpc_streaming.status,
                            grpc_backend_admission_elapsed,
                        )
                        // The response finishes HTTP 200 with the gRPC outcome in a
                        // grpc-status trailer; classify it at EOF so a backend gRPC
                        // failure (e.g. 14 -> 503) shrinks the limit.
                        .with_grpc_trailer_admission_classification()
                        // A late client-upload overflow (> max_grpc_recv_size_bytes)
                        // RSTs the response stream; tag the outcome so the limiter
                        // treats it as a client-side RequestBodyTooLarge (ignored)
                        // instead of a backend fault, matching the circuit breaker's
                        // NEUTRAL handling of the same flag on this path.
                        .with_deferred_admission_request_body_exceeded_flag(
                            grpc_streaming.request_body_exceeded.clone(),
                        );
                }
                if let Some(content_type) = grpc_web_streaming_content_type {
                    body = body.into_grpc_web_streaming(
                        content_type,
                        grpc_streaming.status,
                        grpc_web_streaming_initial_metadata,
                    );
                }
                if let Some(logger) = deferred_grpc_logger {
                    body = body.with_logger(logger);
                }

                // Detach the deferred logger before handing the body to
                // `resp_builder.body(...)`. If the build fails (e.g. plugin/
                // header mutations left the builder in an error state), the
                // body is dropped before we can react — which would fire the
                // logger's Drop safety net as `client_disconnect`, incorrectly
                // billing a server-side build failure as a client abort and
                // inflating disconnect/body-error metrics. By taking the
                // logger first we can fire a specific server-side outcome on
                // failure and reattach on success. Mirrors the HTTP path's
                // `take_logger` → reattach-or-fire pattern.
                let logger = body.take_logger();
                match resp_builder.body(body) {
                    Ok(mut resp) => {
                        if let Some(logger) = logger {
                            resp.body_mut().set_logger(logger);
                        }
                        return Ok(resp);
                    }
                    Err(_) => {
                        if let Some(logger) = logger {
                            // Classify as `ProtocolError` (not `RequestError`)
                            // because gRPC errors ride on HTTP/2 and this is
                            // a framing/build failure on the response stream,
                            // not a client-initiated request failure.
                            logger.fire(
                                crate::proxy::deferred_log::BodyOutcome::error(
                                    crate::retry::ErrorClass::ProtocolError,
                                    0,
                                    false,
                                )
                                .with_grpc_status(Some(grpc_proxy::grpc_status::UNAVAILABLE)),
                            );
                        }
                        return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                            grpc_proxy::grpc_status::UNAVAILABLE,
                            "Internal gateway error",
                            initial_response_header_policy_plugins.as_ref(),
                        ));
                    }
                }
            }
            Ok(GrpcResponseKind::Buffered(grpc_resp)) => {
                let mut response_status = grpc_resp.status;
                let mut response_headers: HashMap<String, String> = grpc_resp.headers;
                let mut response_trailers: HashMap<String, String> = grpc_resp.trailers;
                let mut response_body = grpc_resp.body;
                if let Some(grpc_status) =
                    grpc_proxy::grpc_status_from_maps(&response_trailers, &response_headers)
                {
                    ctx.metadata
                        .insert("grpc_status".to_string(), grpc_status.to_string());
                }
                // `response_trailers` is the backend's untouched trailer map at
                // this point (moved out of `grpc_resp` above, reconciled with
                // plugin mutations only later), so the grpc-status mapping is
                // correct for both the non-empty-body (status in trailers) and
                // Trailers-Only (status in headers) encodings.
                let grpc_backend_dispatch_status = grpc_proxy::grpc_admission_status_from_maps(
                    &response_trailers,
                    &response_headers,
                    response_status,
                );
                if let Some(permits) = backend_admission_permits.take() {
                    // gRPC application failures ride in the `grpc-status` trailer
                    // (or header, for trailers-only) under HTTP 200, so the HTTP
                    // status alone mislabels an UNAVAILABLE/INTERNAL backend as a
                    // healthy success. Map the effective non-OK gRPC status to HTTP
                    // so a server-side failure surfaces as 5xx and shrinks the limit,
                    // while client-side statuses stay <500 (healthy). The backend's
                    // trailers are still intact here — plugin-view merge and wire
                    // writeback happen below.
                    permits.record_backend_outcome(BackendAdmissionOutcome {
                        response_status: grpc_backend_dispatch_status,
                        connection_error: false,
                        error_class: None,
                        backend_elapsed: grpc_backend_admission_started_at.elapsed(),
                    });
                }
                if !grpc_skip_final_cb_record {
                    record_grpc_backend_dispatch_outcome(
                        &state,
                        &proxy,
                        &epoch.load_balancer,
                        upstream_balancer.as_ref(),
                        grpc_final_upstream_target.as_ref(),
                        grpc_final_cb_key.as_deref(),
                        grpc_backend_dispatch_status,
                        false,
                        None,
                        grpc_backend_admission_started_at.elapsed(),
                    );
                }
                drop(grpc_lb_connection_guard.take());

                // Plugins historically saw a merged header+trailer map on the
                // buffered gRPC path because trailers were inserted into
                // response headers before hooks ran. Keep that compatibility
                // view (same convention as the H3 bridge in
                // `http3::cross_protocol`: a trailer never overrides a real
                // header in the view), but split the wire response back into
                // HEADERS + DATA + TRAILERS when the final body is non-empty.
                // Trailer keys the backend ALSO sent as real initial headers
                // are tracked (`header_shadowed_trailer_keys`) so post-hook
                // writeback can distinguish the backend's split wire shape from
                // keys that originated only as trailers. The merged view carries
                // the *header* value for a shadowed key, so writeback below
                // copies a hook-updated value into the hidden wire trailer too
                // (a sanitizer rewriting the visible key must not leave the
                // trailer at the backend's original value), while an untouched
                // shadowed trailer keeps the backend's true trailing value.
                //
                // Exception: the reserved gRPC terminal-status keys
                // (grpc-status / grpc-message / grpc-status-details-bin) are
                // trailer-authoritative and never shadowed — a malformed
                // backend that duplicates them into the initial headers must
                // not feed plugins (or the wire) the bogus header copy, so
                // the trailing value wins in the view and the header copy is
                // stripped on the non-empty wire path below.
                let (mut plugin_response_headers, header_shadowed_trailer_keys) =
                    grpc_proxy::build_grpc_plugin_header_view(
                        &response_headers,
                        &response_trailers,
                    );
                // Provenance for the gRPC-Web body trailer frame: only names
                // that arrived as backend trailers (plus reserved terminal
                // metadata) may be embedded. Collision provenance also keeps a
                // true trailing value distinct from a same-name initial header
                // without bypassing hook rewrites/removals. Record even when
                // the trailer map is empty so initial-header-only fields in the
                // merged view cannot leak into the frame.
                if crate::plugins::grpc_web::request_is_grpc_web_translated(&ctx) {
                    crate::plugins::grpc_web::record_backend_trailer_provenance_for_frame(
                        &mut ctx.metadata,
                        &response_headers,
                        &response_trailers,
                    );
                }
                // Set when a gateway-authored terminal response encodes its
                // gRPC status in the gRPC-Web BODY trailer frame instead of in
                // the header/trailer maps, so the metadata refresh below does
                // not read those (deliberately emptied) maps as a hook-removed
                // status and overwrite the recorded status with UNKNOWN.
                let mut terminal_metadata_is_body_framed = false;
                let initial_response_header_policy_names =
                    plugin_cache_view.initial_response_header_policy_names();
                // Set once an earlier body phase selects a gateway-authored
                // terminal response. The transform phase still runs so protocol
                // transforms such as gRPC-Web can emit the correct wire shape,
                // but final-body validators must not replace the selected error.
                // While this is first set by `on_response_body`, it also records a
                // representation-gate or deadline replacement below.
                let mut response_body_rejected = false;
                let mut authoritative_trailers_only_terminal_metadata = (response_body.is_empty()
                    && response_trailers.is_empty())
                .then(|| grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(&response_headers));
                // Capture original response invariants before `after_proxy`
                // rewrites the header view, matching the H1/H2, native H3, and
                // H3 bridge paths. `response_headers` is still the backend's
                // untouched initial header map here, so the shared
                // representation gate can prove this response's original content
                // coding and range/delta state rather than reading a map a hook
                // has already rewritten.
                stamp_original_response_metadata(&mut ctx, response_status, &response_headers);
                ctx.begin_buffered_initial_response_header_policy(
                    initial_response_header_policy_names,
                    &response_headers,
                    &plugin_response_headers,
                );

                // after_proxy hooks. Policy state stays on `ctx` through body
                // transforms so gRPC-Web trailer framing can honor the same
                // BufferedInitialResponseHeaderPolicyState outcomes as native
                // trailer reconciliation; it is taken after transform below.
                let mut after_proxy_rejected = false;
                {
                    let phase_start = Instant::now();
                    let after_proxy_reject = run_after_proxy_hooks(
                        &plugins,
                        &mut ctx,
                        response_status,
                        &mut plugin_response_headers,
                    )
                    .await;
                    if let Some(reject) = after_proxy_reject {
                        let _ = ctx.take_buffered_initial_response_header_policy();
                        let normalized = normalize_reject_response(
                            StatusCode::from_u16(reject.status_code)
                                .unwrap_or(StatusCode::BAD_GATEWAY),
                            &reject.body,
                            &reject.headers,
                            true,
                        );
                        apply_grpc_reject_metadata(&mut ctx, &normalized);
                        authoritative_trailers_only_terminal_metadata =
                            Some(grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(
                                &normalized.headers,
                            ));
                        response_status = normalized.http_status.as_u16();
                        response_headers = normalized.headers;
                        plugin_response_headers = response_headers.clone();
                        response_trailers.clear();
                        response_body = normalized.body;
                        after_proxy_rejected = true;
                    }
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                }

                if !after_proxy_rejected {
                    let phase_start = Instant::now();
                    crate::plugins::normalize_response_body_for_inspection(
                        &plugins,
                        &mut ctx,
                        response_status,
                        &mut plugin_response_headers,
                        &mut response_body,
                        initial_response_header_policy_plugins.as_ref(),
                    )
                    .await;
                    for plugin in plugins.iter() {
                        let deadline = ctx.grpc_deadline_at();
                        let result = crate::plugins::await_request_plugin_deadline_with_provenance(
                            deadline,
                            plugin.on_response_body(
                                &mut ctx,
                                response_status,
                                &mut plugin_response_headers,
                                &response_body,
                            ),
                        )
                        .await
                        .into_plugin_result(&mut ctx);
                        match result {
                            PluginResult::Continue => {
                                ctx.record_deadline_response_header_plugin(
                                    plugin.as_ref(),
                                    &plugin_response_headers,
                                );
                            }
                            reject @ PluginResult::Reject { .. }
                            | reject @ PluginResult::RejectBinary { .. } => {
                                let reject = plugin_result_into_reject_parts(reject)
                                    .expect("reject result should convert to rejection parts");
                                debug!(
                                    plugin = plugin.name(),
                                    status_code = reject.status_code,
                                    "Plugin rejected gRPC response body"
                                );
                                let normalized =
                                    normalize_grpc_plugin_rejection_with_after_proxy_hooks(
                                        &plugins, &mut ctx, reject, false,
                                    )
                                    .await;
                                authoritative_trailers_only_terminal_metadata =
                                    Some(grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(
                                        &normalized.headers,
                                    ));
                                response_status = normalized.http_status.as_u16();
                                response_headers = normalized.headers;
                                plugin_response_headers = response_headers.clone();
                                response_trailers.clear();
                                response_body = normalized.body;
                                let _ = ctx.take_buffered_initial_response_header_policy();
                                response_body_rejected = true;
                                break;
                            }
                        }
                    }
                    // Capture normalize / inspect header mutations before the
                    // gRPC-Web transform frames trailers from the live view.
                    ctx.record_buffered_initial_response_header_later_mutations(
                        &mut plugin_response_headers,
                    );
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                }

                // Take policy state for wire reconciliation after transforms.
                // Retiring compatibility-view application trailers is deferred
                // until after reconcile + gRPC-Web body-frame sync: discarding
                // first leaves only reserved terminal keys, and sync would
                // rebuild a sparse trailer frame that drops ASCII/binary custom
                // metadata (the H3 framed-body failure mode).
                let (
                    mut buffered_initial_response_header_policy_state,
                    defer_application_trailer_discard,
                ) = if !after_proxy_rejected {
                    let phase_start = Instant::now();
                    // Keep buffered gRPC-Web conversion keyed to the original
                    // request when the hook-visible response headers are still
                    // native gRPC. The grpc_web body transform relies on this
                    // relabel before it embeds terminal trailers in the body.
                    if let Some(grpc_web_ct) = grpc_web_response_content_type
                        && plugins.iter().any(|plugin| plugin.name() == "grpc_web")
                        && plugin_response_headers
                            .get("content-type")
                            .is_some_and(|ct| {
                                crate::proxy::backend_dispatch::is_native_grpc_content_type(
                                    ct.as_bytes(),
                                )
                            })
                    {
                        plugin_response_headers
                            .insert("content-type".to_string(), grpc_web_ct.to_string());
                    }
                    let (response_replaced, representation_rewritten) =
                        transform_buffered_response_body_with_deadline(
                            &plugins,
                            &mut ctx,
                            buffered_response_representation_origin(response_body_rejected),
                            &mut response_status,
                            &mut plugin_response_headers,
                            &mut response_body,
                            grpc_web_response_content_type,
                            initial_response_header_policy_plugins.as_ref(),
                        )
                        .await;
                    if response_replaced {
                        grpc_proxy::select_buffered_grpc_terminal_response(
                            &plugin_response_headers,
                            &mut response_trailers,
                            &mut authoritative_trailers_only_terminal_metadata,
                        );
                        let _ = ctx.take_buffered_initial_response_header_policy();
                        // A gRPC-Web replacement (representation rejection or
                        // deadline) puts its status in the body trailer frame
                        // and keeps it out of both maps. The native gRPC
                        // replacement leaves `grpc-status` in the headers, so
                        // this flag stays false and the ordinary refresh reads
                        // it back.
                        terminal_metadata_is_body_framed |=
                            grpc_web_response_content_type.is_some();
                    }
                    response_body_rejected |= response_replaced;
                    // Record genuine transform-phase edits BEFORE later
                    // trailer retirement. The discard removes trailer-only
                    // names from the merged view; if it ran before this
                    // recording, a policy-owned initial header whose name the
                    // backend also sent as a trailer would look like a later
                    // intentional removal.
                    let mut policy_state = ctx.take_buffered_initial_response_header_policy();
                    if let Some(policy_state) = policy_state.as_mut() {
                        Arc::make_mut(policy_state)
                            .record_later_response_header_mutations(&mut plugin_response_headers);
                    }
                    let defer_application_trailer_discard =
                        !response_replaced && representation_rewritten;
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                    (policy_state, defer_application_trailer_discard)
                } else {
                    (None, false)
                };

                if !after_proxy_rejected && !response_body_rejected {
                    let phase_start = Instant::now();
                    for plugin in plugins.iter() {
                        let deadline = ctx.grpc_deadline_at();
                        let result = crate::plugins::await_request_plugin_deadline_with_provenance(
                            deadline,
                            plugin.on_final_response_body(
                                &mut ctx,
                                response_status,
                                &plugin_response_headers,
                                &response_body,
                            ),
                        )
                        .await
                        .into_plugin_result(&mut ctx);
                        match result {
                            PluginResult::Continue => {}
                            reject @ PluginResult::Reject { .. }
                            | reject @ PluginResult::RejectBinary { .. } => {
                                let reject = plugin_result_into_reject_parts(reject)
                                    .expect("reject result should convert to rejection parts");
                                debug!(
                                    plugin = plugin.name(),
                                    status_code = reject.status_code,
                                    "Plugin rejected finalized gRPC response body"
                                );
                                let normalized =
                                    normalize_grpc_plugin_rejection_with_after_proxy_hooks(
                                        &plugins, &mut ctx, reject, false,
                                    )
                                    .await;
                                authoritative_trailers_only_terminal_metadata =
                                    Some(grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(
                                        &normalized.headers,
                                    ));
                                if let (Some(grpc_web_ct), Some(grpc_status)) =
                                    (grpc_web_response_content_type, normalized.grpc_status)
                                {
                                    let message = normalized
                                        .grpc_message
                                        .as_deref()
                                        .unwrap_or_else(|| grpc_status_reason(grpc_status));
                                    let mut translated =
                                        crate::plugins::grpc_web::error_response_for_content_type(
                                            grpc_web_ct,
                                            grpc_status,
                                            message,
                                        );
                                    finalize_grpc_web_error_response_headers(
                                        &mut translated,
                                        &[],
                                        Some(&normalized.headers),
                                    );
                                    response_status = 200;
                                    response_headers = translated.headers;
                                    response_body = translated.body;
                                    // Same body-framed shape as the gate's
                                    // replacement above: the finalized status
                                    // lives in the trailer frame only.
                                    terminal_metadata_is_body_framed = true;
                                } else {
                                    response_status = normalized.http_status.as_u16();
                                    response_headers = normalized.headers;
                                    response_body = normalized.body;
                                }
                                plugin_response_headers = response_headers.clone();
                                response_trailers.clear();
                                buffered_initial_response_header_policy_state = None;
                                let _ = ctx.take_buffered_initial_response_header_policy();
                                break;
                            }
                        }
                    }
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                }

                // Capture the backend's original trailer `set-cookie` (issue
                // #1638) before reconciliation overwrites it, so the re-homing
                // step below can distinguish a hook-contributed value from the
                // backend's untouched trailer.
                let original_trailer_set_cookie = response_trailers.get("set-cookie").cloned();
                if !after_proxy_rejected {
                    // Reconcile hook mutations from the merged view back into
                    // the wire trailers: a trailer-originated key now absent
                    // from the view was removed by a hook (honor the removal,
                    // matching the pre-split behavior where trailers lived in
                    // the headers map plugins mutated); a changed value is a
                    // hook edit.
                    //
                    // A key shadowed by a real backend header was merged into
                    // the view at the *header* value (a trailer never overrides
                    // a real header), so the view value is NOT comparable to the
                    // trailer's own value — a blind copy would clobber a distinct
                    // backend trailer value even when no hook touched it. Detect
                    // a genuine hook edit by comparing the post-hook view value
                    // against the original initial-header value (`response_headers`
                    // still holds the backend headers here; it is reassigned
                    // below): if a hook rewrote the visible key, propagate the
                    // sanitized value into the hidden wire trailer too (a
                    // sanitizer must scrub every client-visible copy); if the
                    // hook left it untouched, keep the backend's true trailer
                    // value (faithful split wire shape). Removal of a shadowed
                    // key still suppresses the hidden trailer.
                    grpc_proxy::reconcile_grpc_trailers_from_view(
                        &mut response_trailers,
                        &plugin_response_headers,
                        &response_headers,
                        &header_shadowed_trailer_keys,
                        buffered_initial_response_header_policy_state.as_deref(),
                    );
                    // Body-framed gRPC-Web trailers must match the reconciled
                    // wire trailers (policy set/override preserves application
                    // trailers; removals and later rewrites stay authoritative).
                    if !terminal_metadata_is_body_framed
                        && crate::plugins::grpc_web::request_is_grpc_web_translated(&ctx)
                    {
                        let http_status = ctx
                            .metadata
                            .get(crate::plugins::grpc_web::META_GRPC_WEB_HTTP_STATUS)
                            .and_then(|value| value.parse::<u16>().ok());
                        let content_type = plugin_response_headers
                            .get("content-type")
                            .map(String::as_str);
                        if crate::plugins::grpc_web::sync_translated_body_trailer_frame_from_trailers(
                            &mut response_body,
                            content_type,
                            &response_trailers,
                            http_status,
                        ) {
                            plugin_response_headers.insert(
                                "content-length".to_string(),
                                response_body.len().to_string(),
                            );
                        }
                    }
                    // Retire compatibility-view application trailers only after
                    // the body frame has been synced from the reconciled map.
                    if defer_application_trailer_discard {
                        grpc_proxy::discard_grpc_application_trailers_after_body_rewrite(
                            &mut plugin_response_headers,
                            &mut response_trailers,
                            &header_shadowed_trailer_keys,
                        );
                    }
                    response_headers = plugin_response_headers;
                }
                // Health/circuit-breaker accounting intentionally retains the
                // pristine backend status above. Metrics and logs instead track
                // the final status after response hooks reconciled their edits
                // back onto the client-visible header/trailer maps.
                grpc_proxy::refresh_grpc_status_metadata_with_body_framed_terminal(
                    &mut ctx.metadata,
                    &response_trailers,
                    &response_headers,
                    terminal_metadata_is_body_framed,
                );
                if response_body.is_empty() {
                    // True Trailers-Only encoding: no DATA frame, grpc-status
                    // and friends ride in the initial HEADERS with END_STREAM.
                    // Trailer values are authoritative on collapse (pre-split
                    // merge order), including over duplicate initial headers.
                    grpc_proxy::collapse_grpc_trailers_only_with_initial_response_policies(
                        &mut response_headers,
                        &mut response_trailers,
                        &header_shadowed_trailer_keys,
                        buffered_initial_response_header_policy_state.as_deref(),
                        authoritative_trailers_only_terminal_metadata.as_ref(),
                    );
                } else {
                    // Non-empty gRPC responses must carry grpc-status in a
                    // terminal TRAILERS frame. Strip the view-merged trailer
                    // copies from the initial headers; keys the backend also
                    // sent as real initial headers stay headers — the wire
                    // trailer carries the backend's true trailer value (same
                    // wire shape as the H3 bridge). Reserved terminal-status
                    // keys are never shadowed, so a malformed duplicate
                    // grpc-status initial header is always stripped here:
                    // status must only appear in the trailers.
                    grpc_proxy::finalize_buffered_grpc_split_response(
                        &mut response_headers,
                        &mut response_trailers,
                        &header_shadowed_trailer_keys,
                        buffered_initial_response_header_policy_state.as_deref(),
                        None,
                        original_trailer_set_cookie.as_deref(),
                    );
                }

                // A response transform that re-encodes the gRPC terminal
                // status into the body (e.g. `grpc_web` appends a gRPC-Web
                // trailer frame and relabels the content-type) leaves the
                // response no longer native gRPC. Emitting the reconciled
                // native TRAILERS frame as well would double-signal terminal
                // status and confuse gRPC-Web clients/intermediaries, so
                // suppress the wire trailers whenever the final content-type
                // positively indicates a conversion away from native
                // `application/grpc` — keyed on the content-type, not on any
                // specific plugin, so future transforms behave the same. An
                // absent content-type keeps native gRPC semantics (we are on
                // the gRPC dispatch path).
                if !response_trailers.is_empty() {
                    let converted_away_from_grpc =
                        response_headers.get("content-type").is_some_and(|ct| {
                            !crate::proxy::backend_dispatch::is_native_grpc_content_type(
                                ct.as_bytes(),
                            )
                        });
                    if converted_away_from_grpc {
                        response_trailers.clear();
                    }
                }

                // Inject sticky session cookie for gRPC responses
                if sticky_cookie_needed
                    && let (Some(upstream_id), Some(target)) =
                        (&proxy.upstream_id, &upstream_target)
                {
                    let strategy = backend_dispatch::hash_on_strategy_for_selected_target(
                        &proxy,
                        &epoch.load_balancer,
                        upstream_id,
                        target,
                    );
                    if let HashOnStrategy::Cookie(ref cookie_name) = strategy {
                        let upstream =
                            LoadBalancerCache::get_upstream_from(&epoch.load_balancer, upstream_id);
                        let default_cc = crate::config::types::HashOnCookieConfig::default();
                        let cookie_config = upstream
                            .as_ref()
                            .and_then(|u| u.hash_on_cookie_config.as_ref())
                            .unwrap_or(&default_cc);
                        let cookie_val =
                            build_sticky_cookie_header(cookie_name, target, cookie_config);
                        response_headers
                            .entry("set-cookie".to_string())
                            .and_modify(|v| {
                                v.push('\n');
                                v.push_str(&cookie_val);
                            })
                            .or_insert(cookie_val);
                        // Record the gateway-authored affinity cookie in deadline
                        // provenance: it is injected here (not by a plugin
                        // mutation), so a later response-committed hook that
                        // exhausts the RPC deadline would otherwise rebuild the
                        // DEADLINE_EXCEEDED response without it and the client
                        // would not stay pinned. Line-granular recording keeps
                        // any co-present backend cookie out of gateway output.
                        //
                        // This is an APPEND, so it deliberately does not declare
                        // ownership: ownership means whole-value replacement and
                        // retires the backend cookie baseline, which here would
                        // credit a co-present backend cookie as gateway output.
                        // The injection always changes the field (`or_insert`
                        // into an absent slot, or `and_modify` adding a line), so
                        // mutation tracking sees it unconditionally, and the
                        // occurrence partition credits the affinity line even
                        // when it is byte-identical to a backend cookie.
                        ctx.record_deadline_response_header_mutations(&response_headers);
                    }
                }

                if capabilities.has(PluginCapabilities::HAS_RESPONSE_COMMITTED_HOOK) {
                    let phase_start = Instant::now();
                    if run_deadline_bounded_response_committed_hooks(
                        plugin_cache_view.response_committed_plugins(),
                        &mut ctx,
                        &mut response_status,
                        &mut response_headers,
                        &mut response_body,
                        initial_response_header_policy_plugins.as_ref(),
                    )
                    .await
                    {
                        response_trailers.clear();
                    }
                    plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
                }

                let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
                let plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
                let plugin_external_io_ms =
                    ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
                let gateway_processing_ms = total_ms - backend_total_ms;
                let gateway_overhead_ms =
                    (total_ms - backend_total_ms - plugin_execution_ms).max(0.0);

                // Log only after committed exporters write their final metadata.
                if !plugins.is_empty() {
                    let resolve = state.dns_cache.resolve(
                        &proxy.backend_host,
                        proxy.dns_override.as_deref(),
                        proxy.dns_cache_ttl_seconds,
                    );
                    let grpc_resolved_ip =
                        match crate::plugins::await_grpc_deadline(ctx.grpc_deadline_at(), resolve)
                            .await
                        {
                            Ok(result) => result.ok().map(|ip| ip.to_string()),
                            Err(()) => None,
                        };
                    let bytes_sent = ctx
                        .bytes_sent_observed
                        .load(std::sync::atomic::Ordering::Acquire);
                    let bytes_received = response_body.len() as u64;
                    let summary = TransactionSummary {
                        namespace: proxy.namespace.clone(),
                        timestamp_received: ctx.timestamp_received.to_rfc3339(),
                        client_ip: ctx.client_ip.clone(),
                        consumer_username: ctx.effective_identity().map(str::to_owned),
                        auth_method: ctx.auth_method,
                        http_method: method,
                        request_path: original_request_path.clone(),
                        proxy_id: Some(proxy.id.clone()),
                        proxy_name: proxy.name.clone(),
                        backend_target: Some(strip_query_params(&grpc_backend_url).to_string()),
                        backend_resolved_ip: grpc_resolved_ip,
                        response_status_code: response_status,
                        latency_total_ms: total_ms,
                        latency_gateway_processing_ms: gateway_processing_ms,
                        latency_backend_ttfb_ms: backend_total_ms,
                        latency_backend_total_ms: backend_total_ms,
                        latency_plugin_execution_ms: plugin_execution_ms,
                        latency_plugin_external_io_ms: plugin_external_io_ms,
                        latency_gateway_overhead_ms: gateway_overhead_ms,
                        request_user_agent: ctx.headers.get("user-agent").cloned(),
                        bytes_sent,
                        bytes_received,
                        metadata: clone_log_metadata(&ctx),
                        ai_usage_export: ctx.ai_usage_export.clone(),
                        proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
                        ..TransactionSummary::default()
                    };
                    crate::plugins::log_with_mirror_before_buffered_response(
                        &plugins, summary, &ctx,
                    )
                    .await;
                }

                record_request(&state, response_status);

                // Build gRPC response with headers and trailers (splitting any
                // newline-joined Set-Cookie into separate header lines).
                let resp_builder = headers_mod::apply_response_headers(
                    Response::builder()
                        .status(StatusCode::from_u16(response_status).unwrap_or(StatusCode::OK)),
                    &response_headers,
                );

                let response_body = Bytes::from(response_body);
                let body = if !response_body.is_empty() && !response_trailers.is_empty() {
                    // Split LF-joined duplicate metadata before HeaderValue
                    // construction — from_str rejects embedded LF and would
                    // otherwise drop the entire multi-value trailer.
                    let trailers =
                        grpc_proxy::buffered_grpc_trailers_to_header_map(&response_trailers);
                    ProxyBody::buffered_grpc_with_trailers(response_body, trailers)
                } else {
                    ProxyBody::full(response_body)
                };

                return Ok(resp_builder.body(body).unwrap_or_else(|_| {
                    grpc_proxy::build_grpc_error_response_with_policy(
                        grpc_proxy::grpc_status::UNAVAILABLE,
                        "Internal gateway error",
                        initial_response_header_policy_plugins.as_ref(),
                    )
                }));
            }
            Err(e) => {
                let grpc_error_class = retry::classify_grpc_proxy_error(&e);
                let grpc_backend_connection_error = matches!(
                    &e,
                    GrpcProxyError::BackendUnavailable { kind, message, .. }
                        // A gateway-side egress denial (DnsResolution kind whose
                        // message carries "egress policy") dialed no backend, so it
                        // is NOT a connect-class failure even though the kind is.
                        if kind.is_connect_class() && !message.contains("egress policy")
                ) || matches!(
                    &e,
                    GrpcProxyError::BackendTimeout {
                        kind: grpc_proxy::GrpcTimeoutKind::Connect,
                        ..
                    }
                );
                if !matches!(
                    &e,
                    GrpcProxyError::ClientDeadlineExceeded(_)
                        | GrpcProxyError::ResourceExhausted(_)
                        | GrpcProxyError::Internal(_)
                ) && let Some(permits) = backend_admission_permits.take()
                {
                    permits.record_backend_outcome(BackendAdmissionOutcome {
                        response_status: 502,
                        connection_error: grpc_backend_connection_error,
                        error_class: Some(grpc_error_class),
                        backend_elapsed: grpc_backend_admission_started_at.elapsed(),
                    });
                }
                if !grpc_skip_final_cb_record
                    && !matches!(
                        &e,
                        GrpcProxyError::ClientDeadlineExceeded(_)
                            | GrpcProxyError::ResourceExhausted(_)
                            | GrpcProxyError::Internal(_)
                    )
                {
                    record_grpc_backend_dispatch_outcome(
                        &state,
                        &proxy,
                        &epoch.load_balancer,
                        upstream_balancer.as_ref(),
                        grpc_final_upstream_target.as_ref(),
                        grpc_final_cb_key.as_deref(),
                        502,
                        grpc_backend_connection_error,
                        Some(grpc_error_class),
                        grpc_backend_admission_started_at.elapsed(),
                    );
                }
                drop(grpc_lb_connection_guard.take());
                if grpc_error_class == retry::ErrorClass::PortExhaustion {
                    state.overload.record_port_exhaustion();
                }
                let grpc_code = match &e {
                    GrpcProxyError::ClientDeadlineExceeded(_) => {
                        grpc_proxy::grpc_status::DEADLINE_EXCEEDED
                    }
                    GrpcProxyError::BackendUnavailable { .. } => {
                        grpc_proxy::grpc_status::UNAVAILABLE
                    }
                    GrpcProxyError::BackendTimeout { .. } => {
                        grpc_proxy::grpc_status::DEADLINE_EXCEEDED
                    }
                    GrpcProxyError::ResourceExhausted(_) | GrpcProxyError::ResponseTooLarge(_) => {
                        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED
                    }
                    GrpcProxyError::Internal(_) => grpc_proxy::grpc_status::UNAVAILABLE,
                };
                // Use a generic client-facing message to avoid leaking
                // internal backend details (hostnames, DNS errors, etc.).
                let msg = match &e {
                    GrpcProxyError::ClientDeadlineExceeded(_) => GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
                    _ if grpc_code == grpc_proxy::grpc_status::DEADLINE_EXCEEDED => {
                        "Backend deadline exceeded"
                    }
                    _ if grpc_code == grpc_proxy::grpc_status::RESOURCE_EXHAUSTED => {
                        "Resource exhausted"
                    }
                    _ => "Backend unavailable",
                };

                // Log with error_class for gRPC backend failures
                let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
                let grpc_plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
                let grpc_plugin_external_io_ms =
                    ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
                let grpc_gateway_overhead_ms =
                    (total_ms - backend_total_ms - grpc_plugin_execution_ms).max(0.0);
                // Dispatch to the full plugin chain — plugins outside the
                // logging priority band (e.g., `otel_tracing` at priority 25)
                // still need the hook so rejected/error transactions reach
                // tracing sinks. The default `.log()` impl is a no-op.
                if !plugins.is_empty() {
                    {
                        let proxy_ref = ctx.matched_proxy.as_ref();
                        let mut metadata = clone_log_metadata(&ctx);
                        metadata.insert(
                            "rejection_phase".to_string(),
                            "grpc_backend_error".to_string(),
                        );
                        insert_grpc_error_metadata(&mut metadata, grpc_code, msg);
                        // gRPC backend-error path. Request bytes were captured
                        // at the gRPC body collection site above; response is
                        // a synthetic trailers-only frame (built by
                        // `build_grpc_error_response` on return), so we don't
                        // have its size here — leave bytes_received at 0.
                        let bytes_sent = ctx
                            .bytes_sent_observed
                            .load(std::sync::atomic::Ordering::Acquire);
                        let summary = TransactionSummary {
                            namespace: proxy_ref
                                .map(|p| p.namespace.clone())
                                .unwrap_or_else(crate::config::types::default_namespace),
                            timestamp_received: ctx.timestamp_received.to_rfc3339(),
                            client_ip: ctx.client_ip.clone(),
                            consumer_username: ctx.effective_identity().map(str::to_owned),
                            auth_method: ctx.auth_method,
                            http_method: ctx.method.clone(),
                            request_path: original_request_path.clone(),
                            proxy_id: proxy_ref.map(|p| p.id.clone()),
                            proxy_name: proxy_ref.and_then(|p| p.name.clone()),
                            backend_target: proxy_ref.map(|p| {
                                let strip_len = p.listen_path.as_deref().map(str::len).unwrap_or(0);
                                let url = build_backend_url(p, &ctx.path, "", strip_len);
                                strip_query_params(&url).to_string()
                            }),
                            response_status_code: 200, // gRPC errors use HTTP 200
                            latency_total_ms: total_ms,
                            latency_gateway_processing_ms: total_ms - backend_total_ms,
                            latency_backend_ttfb_ms: backend_total_ms,
                            latency_backend_total_ms: backend_total_ms,
                            latency_plugin_execution_ms: grpc_plugin_execution_ms,
                            latency_plugin_external_io_ms: grpc_plugin_external_io_ms,
                            latency_gateway_overhead_ms: grpc_gateway_overhead_ms,
                            request_user_agent: ctx.headers.get("user-agent").cloned(),
                            error_class: Some(grpc_error_class),
                            bytes_sent,
                            metadata,
                            ai_usage_export: ctx.ai_usage_export.clone(),
                            proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
                            ..TransactionSummary::default()
                        };
                        crate::plugins::log_with_mirror_before_buffered_response(
                            &plugins, summary, &ctx,
                        )
                        .await;
                    }
                } else {
                    crate::runtime_metrics::global_ref().record_grpc_error(
                        ctx.matched_proxy.as_ref().map(|p| p.id.as_str()),
                        grpc_error_class,
                    );
                }

                record_request(&state, 200); // gRPC errors use HTTP 200
                // A gRPC-Web request must receive a gRPC-Web-shaped response even
                // for a gateway-generated backend error: the terminal status has
                // to ride in a gRPC-Web trailer frame under the gRPC-Web
                // content-type, never a raw `application/grpc` trailers-only
                // response the browser client cannot read. The mesh-retry-refusal
                // (above) and backend-admission-rejection paths are already
                // gRPC-Web aware; this backend-exchange-error arm was the last one
                // that fell through to raw `application/grpc`, which is exactly the
                // intermittent `200 + application/grpc` a gRPC-Web caller saw when
                // a backend read/connect blipped under load (issue #2041).
                if let Some(content_type) = grpc_web_response_content_type {
                    return Ok(grpc_proxy::attach_held_frontend_grpc_upload(
                        build_grpc_web_error_response(
                            content_type,
                            grpc_code,
                            msg,
                            plugin_cache_view
                                .initial_response_header_policy_plugins()
                                .as_ref(),
                        ),
                        held_frontend_grpc_upload.take(),
                    ));
                }
                if grpc_request_is_web_translated
                    && let Some(response) = build_translated_grpc_web_error_response(
                        &ctx,
                        grpc_code,
                        msg,
                        plugin_cache_view
                            .initial_response_header_policy_plugins()
                            .as_ref(),
                    )
                {
                    return Ok(grpc_proxy::attach_held_frontend_grpc_upload(
                        response,
                        held_frontend_grpc_upload.take(),
                    ));
                }
                return Ok(grpc_proxy::attach_held_frontend_grpc_upload(
                    grpc_proxy::build_grpc_error_response_with_policy(
                        grpc_code,
                        msg,
                        initial_response_header_policy_plugins.as_ref(),
                    ),
                    held_frontend_grpc_upload.take(),
                ));
            }
        }
    }

    // Keep only the independently owned header map borrowed across the
    // selected generic dispatch. When no owned map exists, borrow
    // `ctx.headers` at each use so final-body deadline provenance can still
    // update the rest of `ctx` without cloning the hot-path request headers.
    let owned_proxy_headers_ref = owned_proxy_headers.as_ref();

    // Build backend URL (using upstream target if available)
    let (effective_host, effective_port) = if let Some(ref target) = upstream_target {
        (target.host.as_str(), target.port)
    } else {
        (proxy.backend_host.as_str(), proxy.backend_port)
    };

    let backend_url = build_backend_url_with_target(
        &proxy,
        &path,
        effective_query_string.as_ref(),
        effective_host,
        effective_port,
        strip_len,
        upstream_target.as_ref().and_then(|t| t.path.as_deref()),
    );
    let backend_start = Instant::now();

    // Track connection for least-connections load balancing. The guard calls
    // record_connection_start now and record_connection_end on drop. For
    // streaming responses the guard is attached to ProxyBody so it lives as
    // long as hyper streams the response; for buffered responses it drops
    // immediately after body construction.
    let lb_connection_guard =
        LoadBalancerConnectionGuard::new(upstream_target.clone(), upstream_balancer.clone());

    let should_stream = should_stream_response_body(
        &proxy,
        &plugins,
        &ctx,
        maybe_requires_response_body_buffering,
    );

    // Determine if we can stream the request body to the backend without
    // collecting it into memory. When effective retries are enabled, we force
    // buffered mode so the collected body bytes can be replayed on connection
    // failures.
    let has_retry = crate::retry::has_effective_http_retries(proxy.retry.as_ref(), &method);
    let stream_request_body = !has_retry && !requires_request_body_buffering;
    // The reqwest pin is now an optimization rather than the correctness
    // boundary: every streaming response arm can drive inspectors. Evaluate it
    // from the finalized context so a body transform that adds/removes
    // `stream: true` is reflected before the native-H3 decision commits.
    let requires_response_stream_inspection = stream_hooks_enabled
        && plugins
            .iter()
            .any(|plugin| plugin.forces_reqwest_dispatch(&ctx));
    let request_client_ip = ctx.client_ip.clone();
    let request_xff_append_ip = socket_ip.clone();
    let retry_config = if has_retry {
        proxy.retry.as_ref()
    } else {
        None
    };

    // Perform the backend request with retry logic.
    // Returns the response and the final CB target key (may differ from the
    // initial target when retries switch to a different upstream target).
    //
    // Dispatch decision is per-target, captured atomically per attempt:
    //
    // * Same target across attempts → keep the snapshot. Cross-protocol
    //   replay against the same backend would bypass
    //   `proxy.retry.retry_on_methods` (the failed transport attempt may
    //   have flushed headers/body before the error surfaced) and risk
    //   duplicating non-idempotent requests on the same backend instance.
    //
    // * Load-balancer rotated to a different target → recompute the
    //   snapshot for the new target. Different target → different backend
    //   → no same-target partial-write replay risk, so the new target's
    //   actual capability classification (the registry already knows each
    //   target's protocol) wins. Mixed-capability upstreams (target A
    //   speaks H3, target B speaks H1) MUST switch transports here, else
    //   retries would force `proxy_to_backend_http3_retry` against an H1
    //   backend and 502 forever.
    //
    // The snapshot is captured by the OUTER code and threaded into
    // `proxy_to_backend` as `dispatch_h3`; re-reading inside that function
    // would race the async DNS resolve against a concurrent
    // `mark_h3_unsupported` / refresh and let the dispatch decision split
    // mid-attempt.
    //
    // Note: `proxy_to_backend_retry` always uses reqwest (not the direct H2
    // pool), and reqwest's client pool is keyed per-target, so a
    // `dispatch_h3=false` rotation already picks up the new target's warmed
    // reqwest client without extra plumbing here.
    let hbone_required = upstream_target
        .as_deref()
        .is_some_and(hbone_pool::target_hbone_enabled);
    let current_dispatch_hbone = !has_retry
        && can_use_hbone_pool(
            has_retry,
            requires_request_body_buffering,
            stream_request_body,
        )
        && can_attempt_hbone_backend(
            state.backend_capabilities.as_ref(),
            &proxy,
            upstream_target.as_deref(),
            state.gateway_svid_bundle.load().is_some(),
        );
    if hbone_required && !current_dispatch_hbone {
        let block_reason = if has_retry {
            "effective retry config disables HBONE dispatch"
        } else if requires_request_body_buffering {
            "request body buffering disables HBONE dispatch"
        } else if !stream_request_body {
            "non-streaming request body disables HBONE dispatch"
        } else {
            "HBONE backend capability is not available"
        };
        warn!(
            proxy_id = %proxy.id,
            upstream_target = ?upstream_target,
            has_retry,
            requires_request_body_buffering,
            stream_request_body,
            block_reason,
            "mesh.hbone=true target requires HBONE dispatch; refusing direct-backend fallback"
        );
        // codex r1-2: `check_circuit_breaker` may have admitted this request
        // as a HALF_OPEN probe. This refusal precedes any backend dispatch,
        // so release the claimed probe slot before returning — repeated
        // fail-closed refusals would otherwise leak `half_open_in_flight`
        // slots and wedge the breaker (mirrors the WebSocket origin reject
        // and the gRPC-branch mesh refusals).
        release_circuit_breaker_probe_on_admission_reject(
            &state,
            &proxy,
            cb_target_key.as_deref(),
            cb_is_half_open_probe,
        );
        // A gRPC-flavored request gets a protocol-appropriate Trailers-Only
        // refusal (gRPC errors ride HTTP 200 + grpc-status) instead of a JSON
        // 502 the client cannot parse. Same fail-closed contract either way.
        if is_grpc_request {
            record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
            let message =
                format!("HBONE dispatch required for this backend target: {block_reason}");
            if let Some(content_type) = grpc_web_response_content_type {
                return Ok(build_grpc_web_error_response(
                    content_type,
                    14,
                    &message,
                    plugin_cache_view
                        .initial_response_header_policy_plugins()
                        .as_ref(),
                ));
            }
            return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                14, // UNAVAILABLE
                &message,
                initial_response_header_policy_plugins.as_ref(),
            ));
        }
        record_request(&state, 502);
        return Ok(build_response(
            StatusCode::BAD_GATEWAY,
            r#"{"error":"Bad Gateway","message":"HBONE dispatch required for this backend target"}"#,
        ));
    }
    // Sidecar egress mirrors the HBONE fail-closed contract: a `mesh.mtls=true`
    // target that cannot dispatch over the SVID-mTLS pool must never fall back
    // to a plaintext direct-backend dial.
    let mesh_mtls_required = upstream_target
        .as_deref()
        .is_some_and(mesh_mtls_pool::target_mesh_mtls_enabled);
    let current_dispatch_mesh_mtls = !has_retry
        && can_use_hbone_pool(
            has_retry,
            requires_request_body_buffering,
            stream_request_body,
        )
        && supports_mesh_mtls_backend(&state, &proxy, upstream_target.as_deref());
    if mesh_mtls_required && !current_dispatch_mesh_mtls {
        let block_reason = if has_retry {
            "effective retry config disables sidecar SVID-mTLS dispatch"
        } else if requires_request_body_buffering {
            "request body buffering disables sidecar SVID-mTLS dispatch"
        } else if !stream_request_body {
            "non-streaming request body disables sidecar SVID-mTLS dispatch"
        } else {
            "sidecar SVID-mTLS backend transport is not available"
        };
        warn!(
            proxy_id = %proxy.id,
            upstream_target = ?upstream_target,
            has_retry,
            requires_request_body_buffering,
            stream_request_body,
            block_reason,
            "mesh.mtls=true target requires sidecar SVID-mTLS dispatch; refusing direct-backend fallback"
        );
        // codex r1-2: release a HALF_OPEN probe slot `check_circuit_breaker`
        // may have claimed for this request — this refusal precedes any
        // backend dispatch, and without the release repeated fail-closed
        // refusals leak `half_open_in_flight` slots and wedge the breaker
        // (mirrors the WebSocket origin reject and the gRPC-branch mesh
        // refusals).
        release_circuit_breaker_probe_on_admission_reject(
            &state,
            &proxy,
            cb_target_key.as_deref(),
            cb_is_half_open_probe,
        );
        // This gate is the fail-closed surface for gRPC-over-mesh-mTLS (issue
        // #2003): gRPC requests to same-cluster `mesh.mtls` targets skip the
        // direct-dial gRPC branch and dispatch through the mesh-mTLS pool, so
        // when that transport is unavailable (retry configured, request-body
        // buffering, missing gateway SVID) the request must die HERE with a
        // protocol-appropriate Trailers-Only refusal — never fall back to a
        // plaintext direct dial.
        if is_grpc_request {
            record_request(&state, 200); // gRPC errors ride HTTP 200 + trailers
            let message = format!(
                "sidecar mesh mTLS dispatch required for this backend target: {block_reason}"
            );
            if let Some(content_type) = grpc_web_response_content_type {
                return Ok(build_grpc_web_error_response(
                    content_type,
                    14,
                    &message,
                    plugin_cache_view
                        .initial_response_header_policy_plugins()
                        .as_ref(),
                ));
            }
            if grpc_request_is_web_translated
                && let Some(response) = build_translated_grpc_web_error_response(
                    &ctx,
                    14,
                    &message,
                    plugin_cache_view
                        .initial_response_header_policy_plugins()
                        .as_ref(),
                )
            {
                return Ok(response);
            }
            return Ok(grpc_proxy::build_grpc_error_response_with_policy(
                14,
                &message,
                initial_response_header_policy_plugins.as_ref(),
            ));
        }
        record_request(&state, 502);
        return Ok(build_response(
            StatusCode::BAD_GATEWAY,
            r#"{"error":"Bad Gateway","message":"Sidecar mTLS dispatch required for this backend target"}"#,
        ));
    }
    // The native H3 backend path does not yet bound DNS/connect, response
    // headers, retry dispatch, and body drains by the client RPC deadline.
    // Keep deadline-bound untranslated gRPC-Web on the reqwest path, whose
    // entire exchange is guarded and can still synthesize the browser-visible
    // status-4 trailer frame before any response bytes are committed.
    let deadline_bound_grpc_web_pass_through =
        grpc_web_request && !grpc_request_is_web_translated && ctx.grpc_deadline_at().is_some();
    let mut current_dispatch_h3 = !deadline_bound_grpc_web_pass_through
        && !requires_response_stream_inspection
        && supports_native_http3_backend(&state, &proxy, upstream_target.as_deref());
    // Client end-to-end gRPC deadline for any gRPC-flavored request riding the
    // generic path (native gRPC or gRPC-Web). The typed instant was anchored at
    // receipt by policy preflight and survives representation/transport
    // translation independently of the relative upstream header.
    let grpc_request_deadline = ctx.grpc_deadline_at();
    let bytes_sent_observed = Arc::clone(&ctx.bytes_sent_observed);
    let mut cb_retry_probe_slot_available = cb_is_half_open_probe;
    let mut skip_final_cb_record = false;
    let mut backend_admission_started_at = backend_start;
    // Mesh-transport (HBONE and mesh-mTLS) client-upload overflow flag,
    // returned by `proxy_to_backend` for streaming dispatches and threaded
    // into the deferred admission/dispatch outcomes below so a late upload
    // overflow records neutral `RequestBodyTooLarge` instead of a backend
    // failure (codex r2-2 finding 5 extended it beyond HBONE).
    let mut mesh_request_body_exceeded = None;
    // Mesh H2 dispatch resolves per-target proxy overrides inside
    // `proxy_to_backend`; carry the effective read timeout back to the
    // `StreamingH2` relay so native gRPC without a client deadline does not
    // fall back to the outer proxy default.
    let mut streaming_h2_read_timeout_ms = None;
    let (backend_resp, final_cb_target_key, final_upstream_target) = if let Some(retry_config) =
        retry_config
    {
        let mut attempt = 0u32;
        let mut current_target = upstream_target.clone();
        let mut final_upstream_target = upstream_target.clone();
        let mut current_cb_target_key = cb_target_key.clone();
        let mut current_url = backend_url.clone();
        let mut body_hook_ctx = deferred_body_hook_ctx.take();
        let initial_dispatch = proxy_to_backend(
            &state,
            &proxy,
            &current_url,
            &method,
            owned_proxy_headers_ref.unwrap_or(&ctx.headers),
            client_request_body,
            upstream_target.as_deref(),
            &plugins,
            backend_admission_plugins.as_ref(),
            std::mem::take(&mut preacquired_backend_admission),
            body_hook_ctx.as_mut(),
            &ctx,
            should_stream,
            requires_request_body_buffering,
            stream_request_body,
            has_retry,
            request_body_prepared,
            &request_client_ip,
            &request_xff_append_ip,
            ctx.request_is_secure,
            false,
            false,
            current_dispatch_h3,
            &bytes_sent_observed,
            inbound_version,
            &mut backend_admission_started_at,
        )
        .await;
        if let Some(body_hook_ctx) = body_hook_ctx.take() {
            if body_hook_ctx.gateway_deadline_response_selected() {
                ctx.mark_gateway_deadline_response_selected();
            }
            // `clone_for_final_request_body_hooks` omits `request_body`; carry the
            // original across the metadata swap (no on_final hook touches it).
            // Disjoint field assignments avoid a whole-`ctx` borrow.
            let request_body = ctx.metadata.remove("request_body");
            ctx.metadata = body_hook_ctx.metadata;
            ctx.ai_usage_export = body_hook_ctx.ai_usage_export;
            if let Some(body) = request_body {
                ctx.metadata.insert("request_body".to_string(), body);
            }
            ctx.waf_metadata_initialized = body_hook_ctx.waf_metadata_initialized;
            ctx.waf_owned_metadata = body_hook_ctx.waf_owned_metadata;
            ctx.waf_instance_scores = body_hook_ctx.waf_instance_scores;
        }
        let (mut result, retained_body) = match initial_dispatch {
            BackendDispatchResult::Response {
                response,
                retained_body,
                backend_admission_permits: permits,
                ..
            } => {
                backend_admission_permits = permits;
                (*response, retained_body)
            }
            BackendDispatchResult::AdmissionRejected(rejection) => {
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    cb_target_key.as_deref(),
                    cb_is_half_open_probe,
                );
                // Codex r2-2 finding 3: gRPC-flavored requests on the generic
                // path (mesh fall-through) keep the gRPC rejection shape — the
                // direct gRPC branch passes `true` unconditionally to
                // `normalize_reject_response`, which renders a Trailers-Only
                // gRPC reject instead of HTTP/JSON.
                return Ok(handle_backend_admission_rejection(
                    rejection,
                    &plugins,
                    &mut ctx,
                    &state,
                    start_time,
                    plugin_execution_ns,
                    Some(&original_request_path),
                    is_grpc_request,
                    grpc_web_response_content_type,
                )
                .await);
            }
        };

        while retry::should_retry(retry_config, &method, &result, attempt) {
            // Resolve and validate the next retry target before charging this
            // failure as an intermediate attempt or entering backoff. A
            // path-changing candidate will not be dispatched, so leave final
            // accounting to the ordinary post-loop path without delaying the
            // client first.
            let next_retry_target = if let (Some(_upstream_id), Some(prev_target)) =
                (&proxy.upstream_id, &current_target)
                && let Some(ref hash_key) = lb_hash_key
                && let Some(next) = backend_dispatch::select_next_retry_target(
                    &state,
                    &epoch,
                    &proxy,
                    prev_target,
                    hash_key,
                    &ctx.client_ip,
                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                ) {
                if !retry_target_preserves_backend_path(
                    backend_path_is_policy_bound,
                    &proxy,
                    &path,
                    strip_len,
                    prev_target,
                    &next,
                ) {
                    warn!(
                        proxy_id = %proxy.id,
                        "Aborting retry because the candidate would change the authorized backend method path"
                    );
                    break;
                }
                Some(next)
            } else {
                None
            };

            if let Some(permits) = backend_admission_permits.take() {
                permits.record_backend_outcome(BackendAdmissionOutcome {
                    response_status: result.status_code,
                    connection_error: result.connection_error,
                    error_class: result.error_class,
                    backend_elapsed: backend_admission_started_at.elapsed(),
                });
            }
            // Record the failed attempt against the current target's circuit breaker
            // before potentially switching to a different target for the next retry.
            if let Some(cb_config) = &proxy.circuit_breaker {
                let cb = state.circuit_breaker_cache.get_or_create(
                    &proxy.id,
                    current_cb_target_key.as_deref(),
                    cb_config,
                );
                cb.record_failure(
                    result.status_code,
                    result.connection_error,
                    cb_retry_probe_slot_available,
                );
                cb_retry_probe_slot_available = false;
            }

            let delay = retry::retry_delay(retry_config, attempt);
            if let Some(deadline) = ctx.grpc_deadline_at() {
                if tokio::time::timeout_at(deadline, tokio::time::sleep(delay))
                    .await
                    .is_err()
                {
                    result = client_grpc_deadline_exceeded_response_for_request(
                        &ctx,
                        owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                        result.backend_resolved_ip.clone(),
                    );
                    break;
                }
            } else {
                tokio::time::sleep(delay).await;
            }
            attempt += 1;

            // Try a different target on retry if load balancing is configured.
            // When the LB hands us a NEW target (host:port), recompute the
            // dispatch decision for that target — different target may have
            // different protocol classification in the registry. When the
            // LB returns the same host:port (single-backend, sticky LB), the
            // snapshot stays unchanged so same-target retries keep the
            // same protocol.
            //
            // Save the pre-rotation CB key so the post-loop
            // `record_backend_outcome` attributes the last *dispatched*
            // result correctly if we break before dispatching to the new
            // target (e.g. its circuit breaker is open).
            let pre_rotation_cb_key = current_cb_target_key.clone();
            if let Some(next) = next_retry_target {
                let target_changed = current_target.as_ref().is_some_and(|prev_target| {
                    next.host != prev_target.host || next.port != prev_target.port
                });
                current_url = build_backend_url_with_target(
                    &proxy,
                    &path,
                    effective_query_string.as_ref(),
                    &next.host,
                    next.port,
                    strip_len,
                    next.path.as_deref(),
                );
                current_cb_target_key =
                    Some(crate::circuit_breaker::target_key(&next.host, next.port));
                current_target = Some(next);
                if target_changed {
                    // Per-target capability lookup is O(1) (DashMap +
                    // thread-local key buffer). Unknown / Unsupported both
                    // gracefully fall through to reqwest, so an
                    // un-pre-warmed target degrades to the safe path until
                    // the periodic refresh classifies it.
                    current_dispatch_h3 = !deadline_bound_grpc_web_pass_through
                        && !requires_response_stream_inspection
                        && supports_native_http3_backend(&state, &proxy, current_target.as_deref());
                }
            }

            // Re-evaluate the live PeerAuthentication snapshot for every
            // retry attempt. The load balancer may have rotated to a target
            // on another app-port lane, while even a same-target retry may
            // follow a policy reload that tightened the current lane.
            if let Some(mismatch) = mesh_inbound_peer_auth_transport_mismatch(
                &state,
                ctx.mesh_direction,
                mesh_inbound_pre_handshake_app_port,
                &proxy,
                current_target.as_deref(),
                is_tls,
                ctx.tls_client_cert_der.is_some(),
            ) {
                return Ok(reject_mesh_inbound_peer_auth_transport_mismatch(
                    &state,
                    &plugins,
                    &mut ctx,
                    &proxy,
                    mismatch,
                    is_tls,
                    is_grpc_request,
                    start_time,
                    plugin_execution_ns,
                    "mesh_inbound_peer_auth_retry_target_mismatch",
                    Some(&original_request_path),
                )
                .await);
            }

            if let Some(reason) =
                backend_dispatch::direct_http_mesh_transport_refusal(current_target.as_deref())
            {
                warn!(
                    proxy_id = %proxy.id,
                    target_host = current_target.as_deref().map(|target| target.host.as_str()).unwrap_or(""),
                    target_port = current_target.as_deref().map(|target| target.port).unwrap_or(0),
                    reason,
                    "HTTP retry rotated onto a mesh-transport-tagged target; refusing direct retry dispatch"
                );
                result = retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        br#"{"error":"Bad Gateway","message":"Mesh transport dispatch required for this backend target"}"#
                            .to_vec(),
                    ),
                    headers: HashMap::from([(
                        "gateway-error-reason".to_string(),
                        reason.to_string(),
                    )]),
                    connection_error: false,
                    backend_resolved_ip: None,
                    error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
                };
                final_upstream_target = current_target.clone();
                backend_admission_started_at = Instant::now();
                // No backend attempt was made for the rotated target. Keep the
                // synthetic policy refusal neutral for CB/passive-health.
                skip_final_cb_record = true;
                break;
            }

            // Enforce per-target circuit breaker before each retry attempt.
            // Retries may switch to a different upstream target, so the
            // breaker gate must be re-evaluated for the currently selected
            // target rather than relying on the initial attempt's check.
            // On break, restore the pre-rotation key so the post-loop
            // `record_backend_outcome` attributes against the target that
            // actually produced `result`, not the never-called new target.
            if let Some(cb_config) = &proxy.circuit_breaker {
                match state
                    .circuit_breaker_cache
                    .can_execute_with_admission_epoch(
                        &proxy.id,
                        current_cb_target_key.as_deref(),
                        cb_config,
                    ) {
                    Ok((_cb, is_half_open_probe, admission_open_epoch)) => {
                        cb_retry_probe_slot_available = is_half_open_probe;
                        // #1649 R6 finding 2: re-capture the admission epoch for the
                        // rotated target so the deferred StreamingH2 body-completion
                        // outcome is stale-checked against THIS target's generation,
                        // not the initial target's (the header-time neutral release
                        // and the deferred record both use `final_cb_target_key`).
                        cb_admission_open_epoch = admission_open_epoch;
                    }
                    Err(_err) => {
                        current_cb_target_key = pre_rotation_cb_key;
                        // The current `result` was already recorded at the top of this
                        // retry iteration; don't double-record it below.
                        skip_final_cb_record = true;
                        break;
                    }
                }
            }

            backend_admission_permits = match backend_dispatch::run_backend_admission_plugins(
                backend_admission_plugins.as_ref(),
                &ctx,
                &proxy,
                current_target.as_deref(),
                ProxyProtocol::Http,
            ) {
                Ok(permits) => permits,
                Err(rejection) => {
                    release_circuit_breaker_probe_on_admission_reject(
                        &state,
                        &proxy,
                        current_cb_target_key.as_deref(),
                        cb_retry_probe_slot_available,
                    );
                    // Codex r2-2 finding 3: keep the gRPC rejection shape for
                    // gRPC-flavored requests (see the initial-dispatch arm).
                    return Ok(handle_backend_admission_rejection(
                        rejection,
                        &plugins,
                        &mut ctx,
                        &state,
                        start_time,
                        plugin_execution_ns,
                        Some(&original_request_path),
                        is_grpc_request,
                        grpc_web_response_content_type,
                    )
                    .await);
                }
            };
            // Start the final-attempt health/LB/adaptive-concurrency sample
            // after admission succeeds. This mirrors `proxy_to_backend`, which
            // resets the same timer immediately before dispatch. A rotated
            // retry's successful target must not inherit the previous target's
            // failed-attempt latency or retry backoff in least-latency EWMA.
            backend_admission_started_at = Instant::now();

            warn!(
                proxy_id = %proxy.id,
                attempt = attempt,
                max_retries = retry_config.max_retries,
                connection_error = result.connection_error,
                "Retrying backend request"
            );

            // Replay the original request body on retry. On connection failures
            // the body was never sent, so replaying is correct and safe.
            //
            // The caller's response-streaming decision (`should_stream`) is
            // preserved on EVERY attempt, not only the last one (issue #2949).
            // `retry::should_retry` consults status/`error_class`/method only —
            // all known once the response headers arrive and before any body
            // byte is read — so an attempt that turns out retryable simply drops
            // its `reqwest::Response` / `H3StreamingResponse` undrained, exactly
            // as the initial attempt (dispatched with `should_stream`) already
            // does. Making streaming attempt-positional instead forced a healthy
            // `text/event-stream` that succeeded before the last attempt through
            // full-body collection: unbounded when
            // `max_response_body_size_bytes` is `0`, and otherwise a stalled
            // stream that 502s at the cap or the read timeout.
            // `current_dispatch_h3` was either kept from the prior attempt
            // (same target → same protocol) or recomputed above for the
            // new target (rotation → match the new target's capability).
            result = if current_dispatch_h3 {
                proxy_to_backend_http3_retry(
                    &state,
                    &proxy,
                    &current_url,
                    &method,
                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                    current_target.as_deref(),
                    retained_body.as_deref(),
                    should_stream,
                    &plugins,
                    &ctx,
                    &ctx.client_ip,
                    &request_xff_append_ip,
                    ctx.request_is_secure,
                    inbound_version,
                )
                .await
            } else {
                proxy_to_backend_retry(
                    &state,
                    &proxy,
                    &current_url,
                    &method,
                    owned_proxy_headers_ref.unwrap_or(&ctx.headers),
                    current_target.as_deref(),
                    retained_body.as_deref(),
                    should_stream,
                    &plugins,
                    &ctx,
                    &ctx.client_ip,
                    &request_xff_append_ip,
                    ctx.request_is_secure,
                    inbound_version,
                )
                .await
            };
            // If H3 was attempted and produced a transport-level failure,
            // downgrade the cached capability so subsequent requests (and
            // any future retry that rotates BACK to this target) skip the
            // H3 pool. This downgrade does NOT change the current
            // iteration's `current_dispatch_h3` — that decision was locked
            // before the attempt — but it does affect the next iteration
            // IF the LB rotates to a target that gets recomputed here.
            if current_dispatch_h3 && is_h3_transport_failure(&result) {
                mark_h3_unsupported_for_backend_target(
                    state.backend_capabilities.as_ref(),
                    &proxy,
                    current_target.as_deref(),
                );
            }
            final_upstream_target = current_target.clone();
        }
        (result, current_cb_target_key, final_upstream_target)
    } else {
        let mut body_hook_ctx = deferred_body_hook_ctx.take();
        let dispatch = proxy_to_backend(
            &state,
            &proxy,
            &backend_url,
            &method,
            owned_proxy_headers_ref.unwrap_or(&ctx.headers),
            client_request_body,
            upstream_target.as_deref(),
            &plugins,
            backend_admission_plugins.as_ref(),
            std::mem::take(&mut preacquired_backend_admission),
            body_hook_ctx.as_mut(),
            &ctx,
            should_stream,
            requires_request_body_buffering,
            stream_request_body,
            false, // no retry — don't retain body
            request_body_prepared,
            &request_client_ip,
            &request_xff_append_ip,
            ctx.request_is_secure,
            current_dispatch_hbone,
            current_dispatch_mesh_mtls,
            current_dispatch_h3,
            &bytes_sent_observed,
            inbound_version,
            &mut backend_admission_started_at,
        )
        .await;
        if let Some(body_hook_ctx) = body_hook_ctx {
            if body_hook_ctx.gateway_deadline_response_selected() {
                ctx.mark_gateway_deadline_response_selected();
            }
            // `clone_for_final_request_body_hooks` omits `request_body`; carry the
            // original across the metadata swap (no on_final hook touches it).
            // Disjoint field assignments avoid a whole-`ctx` borrow.
            let request_body = ctx.metadata.remove("request_body");
            ctx.metadata = body_hook_ctx.metadata;
            ctx.ai_usage_export = body_hook_ctx.ai_usage_export;
            if let Some(body) = request_body {
                ctx.metadata.insert("request_body".to_string(), body);
            }
            ctx.waf_metadata_initialized = body_hook_ctx.waf_metadata_initialized;
            ctx.waf_owned_metadata = body_hook_ctx.waf_owned_metadata;
            ctx.waf_instance_scores = body_hook_ctx.waf_instance_scores;
        }
        let resp = match dispatch {
            BackendDispatchResult::Response {
                response,
                backend_admission_permits: permits,
                request_body_exceeded,
                streaming_h2_read_timeout_ms: effective_streaming_h2_read_timeout_ms,
                ..
            } => {
                backend_admission_permits = permits;
                mesh_request_body_exceeded = request_body_exceeded;
                streaming_h2_read_timeout_ms = effective_streaming_h2_read_timeout_ms;
                *response
            }
            BackendDispatchResult::AdmissionRejected(rejection) => {
                release_circuit_breaker_probe_on_admission_reject(
                    &state,
                    &proxy,
                    cb_target_key.as_deref(),
                    cb_is_half_open_probe,
                );
                // Codex r2-2 finding 3: keep the gRPC rejection shape for
                // gRPC-flavored requests (see the initial-dispatch arm).
                return Ok(handle_backend_admission_rejection(
                    rejection,
                    &plugins,
                    &mut ctx,
                    &state,
                    start_time,
                    plugin_execution_ns,
                    Some(&original_request_path),
                    is_grpc_request,
                    grpc_web_response_content_type,
                )
                .await);
            }
        };
        (resp, cb_target_key.clone(), upstream_target.clone())
    };
    let mut response_status = backend_resp.status_code;
    let mut response_body = backend_resp.body;
    let mut response_headers = backend_resp.headers;
    // Record original backend response invariants before any `after_proxy` hook
    // can rewrite headers. Compression preserves these markers even if an earlier
    // hook strips/renames `Content-Range` or `Cache-Control`.
    stamp_original_response_metadata(&mut ctx, response_status, &response_headers);
    let backend_resolved_ip = backend_resp.backend_resolved_ip;
    let backend_error_class = backend_resp.error_class;
    annotate_gateway_mesh_metadata(
        &mut ctx,
        upstream_target.as_deref(),
        if current_dispatch_hbone {
            Some("hbone")
        } else if current_dispatch_mesh_mtls {
            Some("mtls")
        } else {
            None
        },
        backend_error_class,
    );

    debug!(
        proxy_id = %proxy.id,
        status = response_status,
        connection_error = backend_resp.connection_error,
        "Backend response received"
    );

    // Record outcome across CB, passive health, and latency. Connection-end is
    // owned by the LoadBalancerConnectionGuard (`with_lb_connection_guard` /
    // drop), which correctly defers the decrement until a streaming response
    // body completes. Use the no-conn-end variant so the least-connections
    // gauge is not decremented twice per request (guard + this call).
    //
    // #1649 item 2 / #1901: direct-H2 `StreamingH2` and native-H3 `StreamingH3`
    // responses can fail *after* headers — a streamable non-failure status
    // followed by a stalled body raises a post-wire read-timeout / reset once
    // the streaming read-timeout window (#1626 / #1940) fires.
    // Recording the dispatch outcome here, at header time, would bank a phantom
    // success and even feed the broken backend's fast TTFB into least-latency, and a mid-stream failure could never
    // correct it. Only that genuinely-unknown case is deferred to body completion
    // via `with_deferred_backend_dispatch_outcome` (mirroring the gRPC streaming
    // path); `streaming_dispatch_should_defer` keeps known-failure-status and
    // no-body responses on the eager header-time record. The HALF_OPEN probe slot
    // is still RELEASED here (same timing as the eager record), only the health
    // *outcome* is deferred — so a long-lived stream never pins the slot, and the
    // deferred record runs as a non-probe (`is_half_open_probe = false`).
    //
    // HBONE (`current_dispatch_hbone`) and mesh-mTLS
    // (`current_dispatch_mesh_mtls`) flow through the same `StreamingH2` arm.
    // Both carry a request-body size limit, so thread the mesh upload
    // overflow flag into the deferred dispatch outcome. That lets genuine
    // streamable-status-then-stall/reset response-body failures trip backend
    // health while a late client-upload overflow remains neutral instead of being
    // misclassified as a backend fault.
    // Whether the H2 response body is already end-of-stream at header time
    // (empty 200 / `content-length: 0` / END_STREAM-in-headers). Such a body is
    // dropped without being polled, so deferring it would be misread as a client
    // disconnect — record it eagerly instead (#1649 round-2 finding C).
    //
    let streaming_h2_body_ended = match &response_body {
        ResponseBody::StreamingH2(resp) => http_body::Body::is_end_stream(resp.body()),
        _ => false,
    };
    let pristine_streaming_grpc_web_trailers_only_terminal_metadata =
        (grpc_request_is_web_translated && streaming_h2_body_ended)
            .then(|| grpc_proxy::GrpcTerminalMetadataSnapshot::from_headers(&response_headers));
    let streaming_h3_header_content_length = match &response_body {
        ResponseBody::StreamingH3(_) => response_headers
            .get("content-length")
            .and_then(|v| v.parse::<u64>().ok()),
        _ => None,
    };
    // H3 does not expose an `is_end_stream()` signal at response-header time.
    // Treat declared zero-length responses as already ended for the defer gate;
    // HEAD/204/304 are still covered by `streaming_dispatch_should_defer`.
    let streaming_h3_body_ended = matches!(&response_body, ResponseBody::StreamingH3(_))
        && streaming_h3_header_content_length == Some(0);
    let pristine_streaming_grpc_web_terminal_names = (grpc_request_is_web_translated
        && (streaming_h2_body_ended || streaming_h3_body_ended))
        .then(|| {
            response_headers
                .keys()
                .cloned()
                .collect::<HashSet<String>>()
        });
    let defer_streaming_h2_dispatch = matches!(&response_body, ResponseBody::StreamingH2(_))
        && streaming_dispatch_should_defer(
            &proxy,
            response_status,
            streaming_h2_body_ended,
            // HEAD responses suppress the body, so a deferred outcome would be
            // misread as a client disconnect (#1649 R7 finding 1).
            method.eq_ignore_ascii_case("HEAD"),
            streaming_response_status_is_passively_unhealthy(
                &epoch.load_balancer,
                &proxy,
                final_upstream_target.as_deref(),
                response_status,
            ),
        );
    let defer_streaming_h3_dispatch = matches!(&response_body, ResponseBody::StreamingH3(_))
        && streaming_dispatch_should_defer(
            &proxy,
            response_status,
            streaming_h3_body_ended,
            method.eq_ignore_ascii_case("HEAD"),
            streaming_response_status_is_passively_unhealthy(
                &epoch.load_balancer,
                &proxy,
                final_upstream_target.as_deref(),
                response_status,
            ),
        );
    let defer_streaming_dispatch = defer_streaming_h2_dispatch || defer_streaming_h3_dispatch;
    // Issue #2003 codex r1-1: native gRPC over the generic path (the
    // mesh-mTLS `StreamingH2` relay — the only way a native-gRPC request
    // reaches this point) rides HTTP 200 with the RPC outcome in
    // `grpc-status`. Seed backend-health accounting (CB / passive health /
    // least-latency / adaptive concurrency) with the header-mapped status so
    // a Trailers-Only error — grpc-status in the response HEADERS with
    // END_STREAM set, which lands on the eager-record path via
    // `streaming_h2_body_ended` — is not banked as a healthy 200. A
    // trailer-borne grpc-status on a streaming response is classified at body
    // EOF by the gRPC trailer classifiers attached in the `StreamingH2` body
    // arm below. Together these mirror the direct gRPC path exactly:
    // `grpc_admission_status_from_maps` at header time +
    // `with_grpc_trailer_{admission,backend_dispatch}_classification` at EOF,
    // sharing the same `grpc_status_to_http_status` mapping. The client-visible
    // response status is deliberately NOT rewritten.
    let streaming_h2_native_grpc =
        request_uses_grpc_content_type && matches!(&response_body, ResponseBody::StreamingH2(_));
    // Codex r2-2 finding 2: the BUFFERED arm needs the same seeding. A
    // gRPC-flavored buffered response on this path is the mesh-mTLS
    // translated-gRPC-Web arm, whose backend H2 trailers were already folded
    // into `response_headers` (`collect_buffered_grpc_trailers` +
    // `build_grpc_plugin_header_view` in `proxy_to_backend_mesh_mtls`) — so a
    // 200 + trailer `grpc-status: 14` must map to the 503 the direct pool's
    // buffered arm records (`grpc_admission_status_from_maps` over
    // headers+trailers feeding `record_grpc_backend_dispatch_outcome` and the
    // admission permits), not bank a healthy success. Pass-through gRPC-Web
    // keeps its trailers inside the BODY, so the map lookup is a no-op and
    // the HTTP status stands — same as the direct pool, which cannot see
    // body-framed trailers either. Trailers-Only refusals synthesized by the
    // mesh path (e.g. RESOURCE_EXHAUSTED / DEADLINE_EXCEEDED) carry
    // `grpc-status` in the headers and an `error_class` that keeps
    // client-side outcomes neutral downstream.
    let buffered_grpc_flavored = (request_uses_grpc_content_type || grpc_request_is_web_translated)
        && matches!(&response_body, ResponseBody::Buffered(_));
    let recorded_backend_status = if streaming_h2_native_grpc || buffered_grpc_flavored {
        grpc_proxy::grpc_admission_status_from_maps(
            &HashMap::new(),
            &response_headers,
            response_status,
        )
    } else {
        response_status
    };
    // Final-attempt dispatch elapsed for CB/passive-health/least-latency and
    // adaptive-concurrency samples. `backend_start` intentionally spans every
    // retry attempt and backoff for transaction logs below; using it here would
    // penalize a rotated retry target with another target's failure/backoff.
    let final_backend_dispatch_elapsed = backend_admission_started_at.elapsed();
    if defer_streaming_dispatch {
        // Release the half-open probe slot promptly without recording a health
        // outcome; the deferred dispatch records the real outcome at body
        // completion as a non-probe. Gated by `!skip_final_cb_record` because a
        // rotated-retry break already recorded (and released) the breaker for
        // the prior target.
        if cb_retry_probe_slot_available
            && !skip_final_cb_record
            && let Some(cb_config) = &proxy.circuit_breaker
        {
            state
                .circuit_breaker_cache
                .get_or_create(&proxy.id, final_cb_target_key.as_deref(), cb_config)
                .record_neutral(true);
        }
    } else {
        backend_dispatch::record_backend_outcome_no_conn_end(
            &state,
            &proxy,
            &epoch.load_balancer,
            upstream_balancer.as_ref(),
            final_upstream_target.as_deref(),
            final_cb_target_key.as_deref(),
            recorded_backend_status,
            backend_resp.connection_error,
            backend_error_class,
            cb_retry_probe_slot_available,
            skip_final_cb_record,
            final_backend_dispatch_elapsed,
        );
    }
    let backend_admission_response_status = recorded_backend_status;
    let backend_admission_connection_error = backend_resp.connection_error;
    let backend_admission_error_class = backend_error_class;
    let backend_admission_elapsed = final_backend_dispatch_elapsed;
    let is_streaming_response = matches!(
        &response_body,
        ResponseBody::Streaming { .. }
            | ResponseBody::StreamingH2(_)
            | ResponseBody::StreamingH3(_)
    );
    if !is_streaming_response && let Some(permits) = backend_admission_permits.take() {
        permits.record_backend_outcome(BackendAdmissionOutcome {
            response_status: backend_admission_response_status,
            connection_error: backend_admission_connection_error,
            error_class: backend_admission_error_class,
            backend_elapsed: backend_admission_elapsed,
        });
    }

    // Transaction backend latency must measure the FULL backend interaction
    // from `backend_start`, spanning every retry attempt and backoff, so it
    // stays consistent with `latency_total_ms`. It is deliberately NOT derived
    // from `backend_admission_elapsed`: that timer is reset per attempt for the
    // adaptive-concurrency sample, which would make retried requests report
    // only the final attempt and understate backend time.
    let backend_elapsed = backend_start.elapsed().as_secs_f64() * 1000.0;
    let backend_ttfb_ms = backend_elapsed;
    // For buffered responses, backend_elapsed includes full body download (accurate total).
    // For streaming responses, concurrent backend-body and client-delivery lifetime
    // cannot be separated at header flush (or at deferred fire without optional
    // tracking), so mark total as unknown (`LATENCY_UNKNOWN_MS`) rather than
    // silently reporting TTFB as total or inflating gateway fields from it.
    let backend_total_ms = if is_streaming_response {
        crate::plugins::LATENCY_UNKNOWN_MS
    } else {
        backend_elapsed
    };

    // Mesh-mTLS translated gRPC-Web folds backend trailers into the header map
    // before this path runs. Capture the bridged split and begin policy-state
    // tracking so body-framed trailers honor the same
    // BufferedInitialResponseHeaderPolicyState outcomes as the direct gRPC pool.
    let mut mesh_grpc_web_trailer_reconcile = None;
    if grpc_request_is_web_translated
        && let Some(split) =
            crate::plugins::grpc_web::capture_bridged_trailer_split_for_policy(&response_headers)
    {
        let mut merged_for_policy = response_headers.clone();
        merged_for_policy.remove(crate::plugins::grpc_web::HEADER_GRPC_WEB_TRAILER_NAMES);
        merged_for_policy.remove(crate::plugins::grpc_web::HEADER_GRPC_WEB_SHADOWED_TRAILERS);
        ctx.begin_buffered_initial_response_header_policy(
            plugin_cache_view.initial_response_header_policy_names(),
            &split.initial_headers,
            &merged_for_policy,
        );
        mesh_grpc_web_trailer_reconcile = Some(split);
    }
    // The shadowed-trailer bridge can contain application metadata values.
    // Promote and strip it before any response hook (including transaction
    // debugging) can inspect or log the backend response-header map.
    crate::plugins::grpc_web::promote_bridged_trailer_provenance(
        &mut ctx.metadata,
        &mut response_headers,
    );

    // after_proxy hooks run before anything is sent downstream, so a plugin may
    // still replace the backend response here (for example, content-length fast-path
    // enforcement in response_size_limiting).
    let mut after_proxy_rejected = false;
    if !plugins.is_empty() {
        let phase_start = Instant::now();
        if let Some(reject) =
            run_after_proxy_hooks(&plugins, &mut ctx, response_status, &mut response_headers).await
        {
            let _ = ctx.take_buffered_initial_response_header_policy();
            mesh_grpc_web_trailer_reconcile = None;
            response_status = reject.status_code;
            response_headers = reject.headers;
            response_headers
                .entry("content-type".to_string())
                .or_insert_with(|| "application/json".to_string());
            response_body = ResponseBody::Buffered(reject.body);
            after_proxy_rejected = true;
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    if !matches!(
        &response_body,
        ResponseBody::Streaming { .. }
            | ResponseBody::StreamingH2(_)
            | ResponseBody::StreamingH3(_)
    ) && let Some(permits) = backend_admission_permits.take()
    {
        permits.record_backend_outcome(BackendAdmissionOutcome {
            response_status: backend_admission_response_status,
            connection_error: backend_admission_connection_error,
            error_class: backend_admission_error_class,
            backend_elapsed: backend_admission_elapsed,
        });
    }

    // #1649 item 2 / #1901: an after_proxy reject can replace the `StreamingH2`
    // or `StreamingH3` body with a buffered response, so the body will no longer
    // carry the deferred dispatch outcome. Record it synchronously now, using the
    // BACKEND's captured
    // status/error (NOT the plugin reject's, which says nothing about backend
    // health) and as a non-probe (the slot was released at header time).
    let deferred_streaming_body_still_streaming = (defer_streaming_h2_dispatch
        && matches!(&response_body, ResponseBody::StreamingH2(_)))
        || (defer_streaming_h3_dispatch && matches!(&response_body, ResponseBody::StreamingH3(_)));
    if defer_streaming_dispatch && !deferred_streaming_body_still_streaming {
        // #1649 R5 finding 3: the after_proxy hook may have run long enough for the
        // breaker to open a new cycle. Skip the CB record if this header-time
        // outcome is stale for the current generation (parity with the
        // body-deferred path's `cb_stale` check), while still recording
        // passive-health + least-latency below.
        let cb_stale = backend_dispatch::deferred_circuit_breaker_is_stale(
            &state,
            &proxy,
            final_cb_target_key.as_deref(),
            cb_admission_open_epoch,
        );
        backend_dispatch::record_backend_outcome_no_conn_end(
            &state,
            &proxy,
            &epoch.load_balancer,
            upstream_balancer.as_ref(),
            final_upstream_target.as_deref(),
            final_cb_target_key.as_deref(),
            backend_admission_response_status,
            backend_admission_connection_error,
            backend_admission_error_class,
            false,
            skip_final_cb_record || cb_stale,
            final_backend_dispatch_elapsed,
        );
    }

    // Provider/protocol normalizers run before response-body guardrails. This is
    // a distinct lifecycle phase from ordinary presentation transforms, which
    // intentionally remain after on_response_body.
    // The fragment gate lives inside `normalize_response_body_for_inspection`
    // itself, so every protocol path reaches it identically; duplicating it here
    // would let one path drift from the others.
    if !after_proxy_rejected
        && !plugins.is_empty()
        && let ResponseBody::Buffered(ref mut data) = response_body
    {
        let phase_start = Instant::now();
        crate::plugins::normalize_response_body_for_inspection(
            &plugins,
            &mut ctx,
            response_status,
            &mut response_headers,
            data,
            initial_response_header_policy_plugins.as_ref(),
        )
        .await;
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    // Set once an earlier body phase selects a gateway-authored terminal
    // response. The transform phase still runs so presentation/protocol
    // transforms can emit the correct wire shape, but final-body validators must
    // not replace the selected error. While this is first set by
    // `on_response_body`, it also records a representation-gate or deadline
    // replacement below.
    let mut response_body_rejected = false;

    // on_response_body hooks — only for buffered responses, only when plugins exist.
    // This phase sees the normalized backend body before ordinary response
    // transformations, so guardrails inspect the client-visible protocol shape.
    // A Reject result replaces the response before it reaches the client.
    if !after_proxy_rejected
        && !plugins.is_empty()
        && let ResponseBody::Buffered(ref data) = response_body
    {
        let phase_start = Instant::now();
        let mut response_body_reject = None;
        for plugin in plugins.iter() {
            let deadline = ctx.grpc_deadline_at();
            let result = crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.on_response_body(&mut ctx, response_status, &mut response_headers, data),
            )
            .await
            .into_plugin_result(&mut ctx);
            match result {
                PluginResult::Continue => {
                    ctx.record_deadline_response_header_plugin(plugin.as_ref(), &response_headers);
                }
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let reject = plugin_result_into_reject_parts(reject)
                        .expect("reject result should convert to rejection parts");
                    debug!(
                        plugin = plugin.name(),
                        status_code = reject.status_code,
                        "Plugin rejected response body"
                    );
                    response_body_reject = Some(reject);
                    break;
                }
            }
        }
        if let Some(reject) = response_body_reject {
            let body = apply_plugin_rejection_response(
                &plugins,
                &mut ctx,
                &mut response_status,
                &mut response_headers,
                reject,
            )
            .await;
            response_body = ResponseBody::Buffered(body);
            let _ = ctx.take_buffered_initial_response_header_policy();
            mesh_grpc_web_trailer_reconcile = None;
            response_body_rejected = true;
        }
        // Capture normalize / inspect mutations before gRPC-Web frames trailers.
        ctx.record_buffered_initial_response_header_later_mutations(&mut response_headers);
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    // transform_response_body hooks — only for buffered responses.
    // Allows plugins (e.g., response_transformer with body rules) to rewrite
    // JSON fields in the response body before it is sent to the client.
    if !after_proxy_rejected
        && !plugins.is_empty()
        && let ResponseBody::Buffered(ref mut data) = response_body
    {
        let phase_start = Instant::now();
        let (response_replaced, _) = transform_buffered_response_body_with_deadline(
            &plugins,
            &mut ctx,
            buffered_response_representation_origin(response_body_rejected),
            &mut response_status,
            &mut response_headers,
            data,
            grpc_web_response_content_type,
            initial_response_header_policy_plugins.as_ref(),
        )
        .await;
        if response_replaced {
            let _ = ctx.take_buffered_initial_response_header_policy();
            mesh_grpc_web_trailer_reconcile = None;
        }
        response_body_rejected |= response_replaced;
        // Mesh translated gRPC-Web: reconcile bridged trailers with policy state
        // and rewrite the body trailer frame so it matches native H2/H3 semantics.
        if let Some(crate::plugins::grpc_web::BridgedTrailerSplit {
            mut trailers,
            initial_headers,
            shadowed_keys,
        }) = mesh_grpc_web_trailer_reconcile.take()
        {
            ctx.record_buffered_initial_response_header_later_mutations(&mut response_headers);
            let policy_state = ctx.take_buffered_initial_response_header_policy();
            grpc_proxy::reconcile_grpc_trailers_from_view(
                &mut trailers,
                &response_headers,
                &initial_headers,
                &shadowed_keys,
                policy_state.as_deref(),
            );
            let http_status = ctx
                .metadata
                .get(crate::plugins::grpc_web::META_GRPC_WEB_HTTP_STATUS)
                .and_then(|value| value.parse::<u16>().ok());
            let content_type = response_headers.get("content-type").map(String::as_str);
            if crate::plugins::grpc_web::sync_translated_body_trailer_frame_from_trailers(
                data,
                content_type,
                &trailers,
                http_status,
            ) {
                response_headers.insert("content-length".to_string(), data.len().to_string());
                // Mirror H1/H2/H3: after body-framing trailers, retire
                // trailer-only application metadata from initial headers while
                // preserving shadowed collisions and reserved terminal keys.
                grpc_proxy::discard_grpc_application_trailers_after_body_rewrite(
                    &mut response_headers,
                    &mut trailers,
                    &shadowed_keys,
                );
            }
        } else {
            let _ = ctx.take_buffered_initial_response_header_policy();
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    } else {
        let _ = ctx.take_buffered_initial_response_header_policy();
    }

    // on_final_response_body hooks — buffered responses after all body transforms.
    // This lets plugins validate or persist the final client-visible payload.
    if !after_proxy_rejected
        && !response_body_rejected
        && !plugins.is_empty()
        && let ResponseBody::Buffered(ref data) = response_body
    {
        let phase_start = Instant::now();
        let mut response_body_reject = None;
        for plugin in plugins.iter() {
            let deadline = ctx.grpc_deadline_at();
            let result = crate::plugins::await_request_plugin_deadline_with_provenance(
                deadline,
                plugin.on_final_response_body(&mut ctx, response_status, &response_headers, data),
            )
            .await
            .into_plugin_result(&mut ctx);
            match result {
                PluginResult::Continue => {}
                reject @ PluginResult::Reject { .. }
                | reject @ PluginResult::RejectBinary { .. } => {
                    let reject = plugin_result_into_reject_parts(reject)
                        .expect("reject result should convert to rejection parts");
                    debug!(
                        plugin = plugin.name(),
                        status_code = reject.status_code,
                        "Plugin rejected finalized response body"
                    );
                    response_body_reject = Some(reject);
                    break;
                }
            }
        }
        if let Some(reject) = response_body_reject {
            let body = apply_plugin_rejection_response(
                &plugins,
                &mut ctx,
                &mut response_status,
                &mut response_headers,
                reject,
            )
            .await;
            response_body = ResponseBody::Buffered(body);
        }
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    // Inject the sticky-session cookie before committed exporters observe the
    // final header view. This remains after every rejection/body replacement so
    // the cookie lands on the same response that will be sent downstream.
    if sticky_cookie_needed
        && let (Some(upstream_id), Some(target)) = (&proxy.upstream_id, &upstream_target)
    {
        let strategy = backend_dispatch::hash_on_strategy_for_selected_target(
            &proxy,
            &epoch.load_balancer,
            upstream_id,
            target,
        );
        if let HashOnStrategy::Cookie(ref cookie_name) = strategy {
            let upstream = LoadBalancerCache::get_upstream_from(&epoch.load_balancer, upstream_id);
            let default_cc = crate::config::types::HashOnCookieConfig::default();
            let cookie_config = upstream
                .as_ref()
                .and_then(|u| u.hash_on_cookie_config.as_ref())
                .unwrap_or(&default_cc);
            let cookie_val = build_sticky_cookie_header(cookie_name, target, cookie_config);
            response_headers
                .entry("set-cookie".to_string())
                .and_modify(|v| {
                    v.push('\n');
                    v.push_str(&cookie_val);
                })
                .or_insert(cookie_val);
            // Record the gateway-authored affinity cookie in deadline provenance
            // before the committed-hook phase can exhaust the RPC deadline and
            // rebuild the response from gateway-owned output only. Line-granular
            // recording keeps any co-present backend cookie out of gateway output.
            // An APPEND, so it records mutations rather than declaring ownership
            // (which means whole-value replacement) — see the sibling site above.
            ctx.record_deadline_response_header_mutations(&response_headers);
        }
    }

    // Observe the response only after final-body rejection replacement. The
    // precomputed capability bit keeps this phase to one predictable branch
    // when no exporter is configured.
    if capabilities.has(PluginCapabilities::HAS_RESPONSE_COMMITTED_HOOK)
        && let ResponseBody::Buffered(ref mut data) = response_body
    {
        let phase_start = Instant::now();
        run_deadline_bounded_response_committed_hooks(
            plugin_cache_view.response_committed_plugins(),
            &mut ctx,
            &mut response_status,
            &mut response_headers,
            data,
            initial_response_header_policy_plugins.as_ref(),
        )
        .await;
        plugin_execution_ns += phase_start.elapsed().as_nanos() as u64;
    }

    let total_ms = start_time.elapsed().as_secs_f64() * 1000.0;
    let plugin_execution_ms = plugin_execution_ns as f64 / 1_000_000.0;
    let plugin_external_io_ms =
        ctx.plugin_http_call_ns.load(Ordering::Relaxed) as f64 / 1_000_000.0;
    let (gateway_processing_ms, gateway_overhead_ms) = TransactionSummary::derive_gateway_latencies(
        total_ms,
        backend_total_ms,
        plugin_execution_ms,
        is_streaming_response,
    );

    // Log/runtime-metrics phase. Keep the no-plugin, non-streaming success
    // path lightweight, but still construct a summary when runtime metrics need
    // error/client-disconnect classification without logging plugins.
    //
    // For streaming responses (Streaming / StreamingH2 / StreamingH3), defer
    // the log until the response body reaches a terminal state. At this point
    // only response headers have been flushed to hyper; the body is still being
    // polled out. Firing the log synchronously would record
    // `client_disconnected=false, body_completed=false` even if hyper then
    // cancels the connection mid-stream. The DeferredTransactionLogger attaches
    // to the ProxyBody wrapper and fires on success (Ready(None)), streaming
    // error (Ready(Some(Err))), or the Drop safety net (client disconnected
    // before completion). See `src/proxy/deferred_log.rs`.
    //
    // Note: a plugin reject during after_proxy/on_response_body/on_final_response_body
    // can replace the originally-streaming body with a Buffered one. We branch on
    // the *current* `response_body` rather than the captured `is_streaming_response`
    // (which tracks the original backend behavior for observability).
    let body_will_stream = matches!(
        &response_body,
        ResponseBody::Streaming { .. }
            | ResponseBody::StreamingH2(_)
            | ResponseBody::StreamingH3(_)
    );
    // Native H3 needs the backend's declared length to distinguish a complete
    // body followed by a graceful QUIC close from truncation. Preserve it
    // before an attached inspector strips the client-visible Content-Length.
    let streaming_h3_backend_content_length =
        matches!(&response_body, ResponseBody::StreamingH3(_))
            .then(|| {
                response_headers
                    .get("content-length")
                    .and_then(|value| value.parse::<u64>().ok())
            })
            .flatten();
    // Resolve the inspector before cloning the context into the deferred
    // logger. The resolver stamps a private stream id only when an inspector
    // actually attaches; the terminal hook uses that id to drain plugin-owned
    // aggregate state into transaction metadata.
    let response_inspector = if body_will_stream && stream_hooks_enabled {
        let content_type = response_headers.get("content-type").map(String::as_str);
        crate::plugins::create_response_stream_inspector_for_enabled_plugins(
            &plugins,
            &mut ctx,
            response_status,
            content_type,
        )
    } else {
        if body_will_stream {
            let content_type = response_headers.get("content-type").map(String::as_str);
            crate::plugins::notify_response_stream_selected(
                &plugins,
                &ctx,
                response_status,
                content_type,
            );
        }
        None
    };
    if response_inspector.is_some() {
        response_headers.remove("content-length");
    }
    let needs_transaction_summary =
        !plugins.is_empty() || body_will_stream || backend_error_class.is_some();
    let deferred_logger: Option<Arc<crate::proxy::deferred_log::DeferredTransactionLogger>> =
        if needs_transaction_summary {
            // Request bytes: read the shared counter populated by the body
            // handlers in `proxy_to_backend` / `proxy_to_backend_http2` /
            // `proxy_to_backend_http3`. By this point the request has
            // completed so the counter reflects the total (Acquire pairs with
            // the Release stores in the body adapters).
            let bytes_sent = ctx
                .bytes_sent_observed
                .load(std::sync::atomic::Ordering::Acquire);
            // Response bytes for buffered responses: the ProxyBody::Buffered
            // arm is built from `Bytes::from(data)`; use the known data length
            // directly. For streaming responses, `bytes_received` is patched
            // at deferred-log fire time from `bytes_streamed`.
            let bytes_received_buffered = match &response_body {
                ResponseBody::Buffered(v) => v.len() as u64,
                _ => 0,
            };
            let summary = TransactionSummary {
                namespace: proxy.namespace.clone(),
                timestamp_received: ctx.timestamp_received.to_rfc3339(),
                client_ip: ctx.client_ip.clone(),
                consumer_username: ctx.effective_identity().map(str::to_owned),
                auth_method: ctx.auth_method,
                http_method: method,
                request_path: original_request_path.clone(),
                proxy_id: Some(proxy.id.clone()),
                proxy_name: proxy.name.clone(),
                backend_target: Some(strip_query_params(&backend_url).to_string()),
                backend_resolved_ip,
                response_status_code: response_status,
                latency_total_ms: total_ms,
                latency_gateway_processing_ms: gateway_processing_ms,
                latency_backend_ttfb_ms: backend_ttfb_ms,
                latency_backend_total_ms: backend_total_ms,
                latency_plugin_execution_ms: plugin_execution_ms,
                latency_plugin_external_io_ms: plugin_external_io_ms,
                latency_gateway_overhead_ms: gateway_overhead_ms,
                request_user_agent: ctx.headers.get("user-agent").cloned(),
                response_streamed: is_streaming_response,
                error_class: backend_error_class,
                bytes_sent,
                bytes_received: bytes_received_buffered,
                metadata: clone_log_metadata(&ctx),
                ai_usage_export: ctx.ai_usage_export.clone(),
                proxy_lifecycle_generation: ctx.proxy_lifecycle_generation,
                ..TransactionSummary::default()
            };

            if body_will_stream {
                // Thread `start_time` so `latency_total_ms` / derived gateway
                // fields are re-derived at body-completion time — closes the
                // header-flush snapshot gap for streaming responses.
                Some(
                    crate::proxy::deferred_log::DeferredTransactionLogger::new_with_start_time(
                        summary,
                        Arc::clone(&plugins),
                        ctx.clone(),
                        start_time,
                    ),
                )
            } else {
                crate::plugins::log_with_mirror_before_buffered_response(&plugins, summary, &ctx)
                    .await;
                None
            }
        } else {
            None
        };

    record_request(&state, response_status);

    // A streaming deadline can replace an as-yet-unpolled backend body with a
    // differently sized gRPC-Web frame or native trailers. Strip the backend
    // length before response headers are committed. H1/H2 builders below then
    // receive `cl = None`; native-H3 keeps the backend length only for internal
    // FIN/truncation validation, while the outer deadline wrapper suppresses
    // that exact size hint so hyper cannot recreate a client Content-Length.
    let streaming_grpc_deadline = match &response_body {
        ResponseBody::Streaming { .. }
        | ResponseBody::StreamingH2(_)
        | ResponseBody::StreamingH3(_) => ctx.grpc_deadline_at(),
        ResponseBody::Buffered(_) => None,
    };
    strip_content_length_for_streaming_grpc_deadline(
        &mut response_headers,
        streaming_grpc_deadline,
    );
    let grpc_web_streaming_adapter = if body_will_stream
        && grpc_request_is_web_translated
        && crate::plugins::response_body_rewrite_allowed(response_status)
        && let Some(content_type) = grpc_web_response_content_type
    {
        // Terminal fields belong to a real trailer block unless the pristine
        // backend response was genuinely Trailers-Only. Discard response-policy
        // attempts to add/rewrite them and restore only that authoritative
        // initial-END_STREAM snapshot.
        grpc_proxy::apply_buffered_grpc_initial_response_policy(
            None,
            &mut response_headers,
            pristine_streaming_grpc_web_trailers_only_terminal_metadata.as_ref(),
        );
        let already_ended = streaming_h2_body_ended || streaming_h3_body_ended;
        let terminal = crate::plugins::grpc_web::take_streaming_initial_terminal_metadata(
            &mut response_headers,
            already_ended,
            pristine_streaming_grpc_web_terminal_names.as_ref(),
        );
        response_headers.remove("content-length");
        Some((content_type.to_string(), terminal))
    } else {
        None
    };

    // Build final response
    let mut resp_builder = Response::builder()
        .status(StatusCode::from_u16(response_status).unwrap_or(StatusCode::BAD_GATEWAY));

    // Apply backend/plugin response headers, splitting newline-joined Set-Cookie
    // into separate header lines (RFC 6265).
    resp_builder = headers_mod::apply_response_headers(resp_builder, &response_headers);

    // Add gateway error categorization headers so clients and ops teams
    // can distinguish different failure modes:
    //   X-Gateway-Error: connection_failure | backend_timeout | backend_error
    //   X-Gateway-Upstream-Status: degraded (when routing via all-unhealthy fallback)
    if backend_resp.connection_error {
        resp_builder = resp_builder.header("X-Gateway-Error", "connection_failure");
    } else if response_status == 504 {
        resp_builder = resp_builder.header("X-Gateway-Error", "backend_timeout");
    } else if response_status >= 500 {
        resp_builder = resp_builder.header("X-Gateway-Error", "backend_error");
    }

    if upstream_is_fallback {
        resp_builder = resp_builder.header("X-Gateway-Upstream-Status", "degraded");
    }

    // Advertise HTTP/3 availability via pre-computed Alt-Svc header
    if let Some(ref alt_svc) = state.alt_svc_header {
        resp_builder = resp_builder.header("alt-svc", alt_svc.as_str());
    }

    // During shutdown drain or overload pressure, tell HTTP/1.1 clients to
    // close after this response instead of reusing the connection. This
    // naturally frees connection slots for new clients (overload) or allows
    // the process to exit cleanly (drain).
    // RED adaptive shedding: between pressure and critical thresholds,
    // Connection: close is applied probabilistically (linear ramp from 0%
    // to 100%) rather than all-or-nothing. This smooths tail latency by
    // gradually shedding keepalive connections as load increases.
    // `draining` uses Acquire to synchronize-with the Release-ordered store
    // in `overload::begin_drain` so the close hint is observed promptly on
    // weakly-ordered architectures (mirrors the PR #569 startup_ready pattern).
    //
    // We OR `disable_keepalive` (the binary pressure-mode flag) with
    // `should_disable_keepalive_red()` (RED probabilistic shedding). Both
    // signals must be honored: the binary flag is the authoritative
    // "pressure-mode active" signal, while RED probability is a separate
    // adaptive smoothing mechanism. They are independent `Relaxed` writes
    // in the monitor loop, so a reader can transiently observe
    // `disable_keepalive = true` while `red_drop_probability` still holds
    // the prior cycle's value of 0 — and at the exact pressure threshold
    // the linear ramp produces probability 0 even though `disable_keepalive`
    // is set. Without the OR, those windows would skip Connection: close
    // and defeat the purpose of the binary pressure-mode signal.
    // Cost: draining check is one AtomicBool::load(Acquire) ~1ns (no-op on x86);
    // disable_keepalive check is one AtomicBool::load(Relaxed) ~1ns;
    // RED check is one AtomicU32::load + one AtomicU64::load + one multiply ~3ns.
    if state
        .overload
        .draining
        .load(std::sync::atomic::Ordering::Acquire)
        || state
            .overload
            .disable_keepalive
            .load(std::sync::atomic::Ordering::Relaxed)
        || state.overload.should_disable_keepalive_red()
    {
        resp_builder = resp_builder.header("connection", "close");
    }

    // Via header on response path (RFC 9110 §7.6.3): describe the protocol
    // used by the upstream sender of this message, not the client-facing
    // inbound protocol.
    let resp_via = via_header_for_backend_response_body(&state, &response_body);
    if let Some(via) = resp_via {
        resp_builder = resp_builder.header("via", via.as_str());
    }

    // Build response body: either stream from backend or return buffered data.
    // When FERRUM_ENABLE_STREAMING_LATENCY_TRACKING=true, streaming responses are
    // wrapped with a TrackedBody that records the final transfer time via a shared
    // atomic. A deferred task reads it after read_timeout + 5s to emit a
    // supplementary log with accurate backend_total_ms.
    // Default (false): streaming responses pass through with zero tracking overhead.
    let body = match response_body {
        ResponseBody::Streaming {
            response,
            reqwest_backend_guard,
        } => {
            // `response_inspector` was resolved above (before headers were applied,
            // so Content-Length is already stripped on the inspect path). On a hit,
            // run the async inspection in a detached task feeding a passthrough
            // channel body — the poll/async bridge for the poll-based H1/H2 body.
            // The backend guards move into the task so connection accounting tracks
            // the real streaming lifetime; a policy cut ends the body cleanly (EOF,
            // not an error).
            if let Some(inspector) = response_inspector {
                let (tx, rx) = tokio::sync::mpsc::channel(16);
                tokio::spawn(crate::proxy::body::run_response_inspection(
                    response,
                    inspector,
                    tx,
                    state.max_response_body_size_bytes,
                    reqwest_backend_guard,
                    lb_connection_guard,
                ));
                // Carry the adaptive-concurrency permits on the inspected body, just
                // like the non-inspect streaming path below: the in-flight slot then
                // stays counted for the full inspected stream and the backend outcome
                // is recorded when the body completes (EOF / policy cut / error /
                // client disconnect) via the same deferred machinery, rather than
                // being released early at header time.
                let mut inspected = crate::proxy::body::inspected_streaming_body(rx);
                if let Some(permits) = backend_admission_permits.take() {
                    inspected = inspected.with_deferred_backend_admission_outcome(
                        permits,
                        backend_admission_response_status,
                        backend_admission_elapsed,
                    );
                }
                if let Some(deadline) = ctx.grpc_deadline_at() {
                    inspected = inspected
                        .with_client_grpc_deadline(deadline, grpc_web_response_content_type);
                }
                inspected
            } else {
                let cl = response_headers
                    .get("content-length")
                    .and_then(|v| v.parse::<u64>().ok());
                // Build the base body from the shared protocol-agnostic builders
                // first, THEN optionally wrap it in latency tracking via
                // `into_tracked`. This guarantees the tracked path inherits the
                // same coalescing / size-limit / fast-path behaviour as the
                // default streaming path — we have one source of truth for body
                // construction across the H1/H2-via-reqwest hot paths.
                //
                // Fast path: skip coalescing when no plugins need body buffering,
                // no size limits apply, and response buffer cutoff is disabled.
                // This eliminates per-frame BytesMut buffering and branch overhead.
                let base = if state.response_buffer_cutoff_bytes == 0
                    && state.max_response_body_size_bytes == 0
                {
                    crate::proxy::body::direct_streaming_body(response, cl)
                } else if state.max_response_body_size_bytes > 0 && cl.is_none() {
                    // No Content-Length — enforce size limit while streaming instead
                    // of buffering the entire body into memory.
                    crate::proxy::body::size_limited_streaming_body(
                        response,
                        state.max_response_body_size_bytes,
                        cl,
                    )
                } else {
                    crate::proxy::body::coalescing_body(response, cl)
                };
                let base = if let Some(guard) = reqwest_backend_guard {
                    base.with_reqwest_backend_guard(guard)
                } else {
                    base
                };
                let mut base = base.with_lb_connection_guard(lb_connection_guard);
                // Deferred backend-admission outcome (adaptive_concurrency): thread the
                // permits into the streaming body so the limiter's latency/health
                // signal fires and the in-flight slot is released at body completion.
                // The inspect branch above attaches the same permits to its inspected
                // body, so both streaming paths count the slot for the full stream.
                if let Some(permits) = backend_admission_permits.take() {
                    base = base.with_deferred_backend_admission_outcome(
                        permits,
                        backend_admission_response_status,
                        backend_admission_elapsed,
                    );
                }

                let base = if state.env_config.enable_streaming_latency_tracking {
                    let (tracked_body, metrics) = base.into_tracked(backend_start);

                    // Spawn a lightweight deferred task to log the final streaming latency.
                    // Wakes once after read_timeout + 5s buffer, reads one atomic, emits one log line.
                    // Skipped when read timeout is disabled (0) — no meaningful deadline to check.
                    if proxy.backend_read_timeout_ms > 0 {
                        let deferred_proxy_id = proxy.id.clone();
                        let deferred_backend_url = strip_query_params(&backend_url).to_string();
                        let read_timeout_ms = proxy.backend_read_timeout_ms;
                        tokio::spawn(async move {
                            tokio::time::sleep(std::time::Duration::from_millis(
                                read_timeout_ms + 5_000,
                            ))
                            .await;
                            let completed = metrics.completed();
                            let total_ms = metrics.last_frame_elapsed_ms().unwrap_or(-1.0);
                            if completed {
                                debug!(
                                    proxy_id = %deferred_proxy_id,
                                    backend_url = %deferred_backend_url,
                                    backend_total_ms = total_ms,
                                    "Streaming response completed"
                                );
                            } else {
                                warn!(
                                    proxy_id = %deferred_proxy_id,
                                    backend_url = %deferred_backend_url,
                                    backend_last_frame_ms = total_ms,
                                    "Streaming response incomplete (client disconnect or timeout)"
                                );
                            }
                        });
                    }

                    tracked_body
                } else {
                    base
                };
                if let Some(deadline) = ctx.grpc_deadline_at() {
                    base.with_client_grpc_deadline(deadline, grpc_web_response_content_type)
                } else {
                    base
                }
            }
        }
        ResponseBody::StreamingH2(resp) => {
            let cl = response_headers
                .get("content-length")
                .and_then(|v| v.parse::<u64>().ok());
            // Plain-HTTPS direct-H2 large-response fast path.
            //
            // The backend's H2 writer already emits `http2_max_frame_size`
            // chunks (default 1 MiB). For small/medium responses the
            // coalescer usefully amortises the per-frame write cost on
            // the downstream client side; but for large responses
            // (>= 512 KiB) the backend frames are already big enough that
            // coalescing them into 128 KiB target chunks just adds a
            // `BytesMut::extend_from_slice` copy before the pre-existing
            // large-frame bypass at `body.rs:~1184` would skip it anyway.
            // That copy was the remaining gap for 5 MB HTTP/2 throughput
            // (81 RPS vs direct 232 RPS).
            //
            // Decision made ONCE per response using `content-length` — we
            // only bypass when the size is known AND large. Unknown CL
            // keeps the coalescer (we cannot be sure frames are already
            // 1 MiB when the backend is chunked).
            //
            // gRPC still uses the coalescing path (see gRPC streaming
            // response at ~line 5905) because gRPC's +35 % large-payload
            // win is documented in CLAUDE.md and depends on coalescing.
            let use_passthrough = should_bypass_h2_coalesce_for_large_response(
                cl,
                state.max_response_body_size_bytes,
            );

            // Timeout regime for this streaming H2 body (codex r2-2 finding
            // 6). Plain HTTP/2 (and HBONE) streaming uses only the per-frame
            // idle (`backend_read_timeout_ms`) regime — no client end-to-end
            // gRPC deadline applies (issue #1649). A NATIVE-gRPC response
            // (the mesh-mTLS relay — the only native-gRPC route into this
            // arm) instead honors the request's typed ABSOLUTE deadline,
            // anchored at receipt before plugin work, with per-frame idle
            // disabled — `grpc_streaming_response_deadline` is the same
            // helper the direct gRPC pool's streaming arm uses, falling back
            // to the effective per-target `backend_read_timeout_ms` when the
            // client set no deadline.
            let effective_h2_read_timeout_ms =
                streaming_h2_read_timeout_ms.unwrap_or(proxy.backend_read_timeout_ms);
            let (h2_read_timeout_ms, h2_total_deadline) =
                grpc_proxy::grpc_streaming_response_deadline(
                    grpc_request_deadline,
                    effective_h2_read_timeout_ms,
                );
            let body = if state.response_buffer_cutoff_bytes == 0
                && state.max_response_body_size_bytes == 0
            {
                crate::proxy::body::direct_streaming_h2_body_strip_hop_by_hop_trailers(
                    resp.into_body(),
                    cl,
                    h2_read_timeout_ms,
                    None,
                )
            } else if state.max_response_body_size_bytes > 0 && cl.is_none() {
                // No Content-Length — enforce response-size limits while
                // streaming H2 bodies, including HBONE tunnel responses,
                // without buffering the whole backend response into memory.
                crate::proxy::body::size_limited_coalescing_h2_body_strip_hop_by_hop_trailers(
                    resp.into_body(),
                    state.max_response_body_size_bytes,
                    cl,
                    state.h2_coalesce_target_bytes,
                    h2_read_timeout_ms,
                    None,
                )
            } else if use_passthrough {
                // Response too large to benefit from coalescing — stream
                // direct, let hyper forward 1 MiB frames as-is. Saves the
                // `BytesMut::extend_from_slice` copy that CoalescingH2Body
                // would do on every data frame before the large-frame
                // bypass kicks in at body.rs:~1184.
                crate::proxy::body::direct_streaming_h2_body_strip_hop_by_hop_trailers(
                    resp.into_body(),
                    cl,
                    h2_read_timeout_ms,
                    None,
                )
            } else {
                crate::proxy::body::coalescing_h2_body_strip_hop_by_hop_trailers(
                    resp.into_body(),
                    cl,
                    state.h2_coalesce_target_bytes,
                    h2_read_timeout_ms,
                    None,
                )
            };
            let mut body = if let Some(inspector) = response_inspector {
                let (tx, rx) = tokio::sync::mpsc::channel(16);
                tokio::spawn(crate::proxy::body::run_proxy_body_response_inspection(
                    body,
                    inspector,
                    tx,
                    state.max_response_body_size_bytes,
                    lb_connection_guard,
                ));
                crate::proxy::body::inspected_streaming_body(rx)
            } else {
                body.with_lb_connection_guard(lb_connection_guard)
            };
            // The absolute wrapper must observe the inspector's OUTPUT, not
            // the backend frames it consumed. An inspector may hold a chunk by
            // returning empty Forward; only bytes yielded by this outer body
            // are client-visible for the clean-status-4 versus reset decision.
            if let Some(deadline) = h2_total_deadline {
                body = body.with_client_grpc_deadline(deadline, grpc_web_response_content_type);
            }
            // Deferred admission/dispatch outcomes stay on the client-visible
            // body. The least-connections guard moves into the inspection task
            // on a hit so a client cancel cannot under-count a provider-blocked
            // inspector that still owns the backend stream.
            if let Some(permits) = backend_admission_permits.take() {
                body = body.with_deferred_backend_admission_outcome(
                    permits,
                    backend_admission_response_status,
                    backend_admission_elapsed,
                );
                // Issue #2003 codex r1-1: native gRPC over mesh-mTLS finishes
                // HTTP 200 with the RPC outcome in a grpc-status trailer —
                // classify it at EOF so a backend gRPC failure (e.g. 14 -> 503)
                // shrinks the adaptive-concurrency limit instead of recording a
                // healthy success. A late client-upload overflow (which RSTs the
                // response stream) is tagged so the limiter ignores it as
                // client-side RequestBodyTooLarge (the flag is populated by
                // both mesh transports — codex r2-2 finding 5). Both mirror
                // the direct gRPC streaming path's admission wiring exactly.
                if streaming_h2_native_grpc {
                    body = body
                        .with_grpc_trailer_admission_classification()
                        .with_deferred_admission_request_body_exceeded_flag(
                            mesh_request_body_exceeded.clone(),
                        );
                }
            }
            // #1649 item 2: defer the dispatch outcome (CB / passive health /
            // least-latency) to body completion so a 2xx-then-stall H2/HBONE body
            // trips the breaker and reports a passive-health failure instead of
            // banking a phantom header-time success. The probe slot was already
            // released at header time, so this records as a non-probe.
            // `record_deferred_backend_dispatch` derives the post-wire
            // `connection_error` from the terminal body error class, so pass
            // `connection_error = false` / `error_class = None` here.
            if defer_streaming_h2_dispatch {
                body = body
                    .with_deferred_backend_dispatch_outcome(
                        Arc::clone(&state),
                        Arc::clone(&proxy),
                        Arc::clone(&epoch.load_balancer),
                        upstream_balancer.clone(),
                        final_upstream_target.clone(),
                        final_cb_target_key.clone(),
                        backend_admission_response_status,
                        false,
                        None,
                        false,
                        skip_final_cb_record,
                        final_backend_dispatch_elapsed,
                    )
                    // #1649 round-4 B: skip the deferred CB record if the breaker
                    // opened a new cycle since admission (stale stream must not
                    // heal/reopen a later HALF_OPEN cycle).
                    .with_deferred_dispatch_admission_open_epoch(cb_admission_open_epoch)
                    .with_deferred_dispatch_request_body_exceeded_flag(
                        mesh_request_body_exceeded.clone(),
                    );
                // Issue #2003 codex r1-1: map a native-gRPC grpc-status trailer
                // into the deferred dispatch outcome (circuit breaker / passive
                // health / least-latency) at body EOF — same semantics as the
                // direct gRPC streaming path
                // (`with_grpc_trailer_backend_dispatch_classification`): the
                // trailer status maps through `grpc_status_to_http_status` and
                // counts as a failure exactly when the mapped HTTP status does.
                if streaming_h2_native_grpc {
                    body = body.with_grpc_trailer_backend_dispatch_classification();
                }
            }
            body
        }
        ResponseBody::StreamingH3(h3_resp) => {
            let client_content_length = response_headers
                .get("content-length")
                .and_then(|v| v.parse::<u64>().ok());
            let success_on_drop_after_bytes =
                h3_success_on_drop_after_response_bytes(inbound_version, client_content_length);
            let backend_content_length = streaming_h3_backend_content_length;
            // Match the H2/native-H3 regime switch: a client RPC deadline is
            // the sole response-phase timer. The outer wrapper below enforces
            // it after inspection, so the inner per-frame idle timer is off.
            let h3_read_timeout_ms = if grpc_request_deadline.is_some() {
                0
            } else {
                proxy.backend_read_timeout_ms
            };
            // Method + status thread into `H3FrameSource` so its graceful-close
            // recovery gate uses the same `is_response_body_complete` predicate
            // as the buffered path (HEAD/204/304 no-body responses included).
            // `method` was moved into the transaction summary above, so read it
            // back from `ctx`; one `Arc<str>` alloc per streaming-H3 response.
            let h3_method: Arc<str> = Arc::from(ctx.method.as_str());
            let body = if state.response_buffer_cutoff_bytes == 0
                && state.max_response_body_size_bytes == 0
            {
                crate::proxy::body::direct_streaming_h3_body(
                    h3_resp.recv_stream,
                    h3_method,
                    response_status,
                    backend_content_length,
                    h3_read_timeout_ms,
                )
            } else if state.max_response_body_size_bytes > 0 {
                crate::proxy::body::size_limited_streaming_h3_body(
                    h3_resp.recv_stream,
                    state.max_response_body_size_bytes,
                    h3_method,
                    response_status,
                    backend_content_length,
                    state.env_config.http3_coalesce_min_bytes,
                    state.env_config.http3_coalesce_max_bytes,
                    std::time::Duration::from_micros(state.env_config.http3_flush_interval_micros),
                    h3_read_timeout_ms,
                )
            } else {
                crate::proxy::body::coalescing_h3_body(
                    h3_resp.recv_stream,
                    h3_method,
                    response_status,
                    backend_content_length,
                    state.env_config.http3_coalesce_min_bytes,
                    state.env_config.http3_coalesce_max_bytes,
                    std::time::Duration::from_micros(state.env_config.http3_flush_interval_micros),
                    h3_read_timeout_ms,
                )
            };
            let mut body = if let Some(inspector) = response_inspector {
                let (tx, rx) = tokio::sync::mpsc::channel(16);
                tokio::spawn(crate::proxy::body::run_proxy_body_response_inspection(
                    body,
                    inspector,
                    tx,
                    state.max_response_body_size_bytes,
                    lb_connection_guard,
                ));
                crate::proxy::body::inspected_streaming_body(rx)
            } else {
                body.with_lb_connection_guard(lb_connection_guard)
            };
            if let Some(deadline) = grpc_request_deadline {
                body = body.with_client_grpc_deadline(deadline, grpc_web_response_content_type);
            }
            body = body.with_success_on_drop_after_response_bytes(success_on_drop_after_bytes);
            if let Some(permits) = backend_admission_permits.take() {
                body = body.with_deferred_backend_admission_outcome(
                    permits,
                    backend_admission_response_status,
                    backend_admission_elapsed,
                );
            }
            if defer_streaming_h3_dispatch {
                body = body
                    .with_deferred_backend_dispatch_outcome(
                        Arc::clone(&state),
                        Arc::clone(&proxy),
                        Arc::clone(&epoch.load_balancer),
                        upstream_balancer.clone(),
                        final_upstream_target.clone(),
                        final_cb_target_key.clone(),
                        backend_admission_response_status,
                        false,
                        None,
                        false,
                        skip_final_cb_record,
                        final_backend_dispatch_elapsed,
                    )
                    .with_deferred_dispatch_admission_open_epoch(cb_admission_open_epoch);
            }
            body
        }
        ResponseBody::Buffered(data) => {
            // Buffered response: body is fully consumed, drop the guard
            // immediately so record_connection_end fires now.
            drop(lb_connection_guard);
            ProxyBody::full(Bytes::from(data))
        }
    };
    let body = if let Some((content_type, initial_terminal_metadata)) = grpc_web_streaming_adapter {
        body.into_grpc_web_streaming(
            &content_type,
            response_status,
            Some(initial_terminal_metadata),
        )
    } else {
        body
    };

    // Attach deferred logger to the body so `log_with_mirror` fires when the
    // body reaches a terminal state (completion, streaming error, or client
    // disconnect via the Drop safety net) rather than at header-flush time.
    // `deferred_logger` is `Some` only for streaming responses with plugins.
    let body = if let Some(guard) = per_ip_guard {
        body.with_per_ip_request_guard(guard)
    } else {
        body
    };

    let mut body = if let Some(logger) = deferred_logger {
        body.with_logger(logger)
    } else {
        body
    };

    // Detach the logger before handing the body to the builder. `http::Error`
    // doesn't expose the consumed body, so we can't recover the logger after
    // a builder failure. Re-attach on success; fire an explicit error outcome
    // on failure so the dropped body isn't miscounted as a client disconnect.
    let logger = body.take_logger();
    match resp_builder.body(body) {
        Ok(mut resp) => {
            if let Some(logger) = logger {
                resp.body_mut().set_logger(logger);
            }
            Ok(resp)
        }
        Err(_) => {
            if let Some(logger) = logger {
                logger.fire(crate::proxy::deferred_log::BodyOutcome::error(
                    crate::retry::ErrorClass::RequestError,
                    0,
                    false,
                ));
            }
            Ok(Response::new(ProxyBody::from_string(
                "Internal Server Error",
            )))
        }
    }
}

/// Build the backend URL based on proxy config and path forwarding logic.
pub fn build_backend_url(
    proxy: &Proxy,
    incoming_path: &str,
    query_string: &str,
    strip_len: usize,
) -> String {
    build_backend_url_with_target(
        proxy,
        incoming_path,
        query_string,
        &proxy.backend_host,
        proxy.backend_port,
        strip_len,
        None,
    )
}

/// Build backend URL using a specific host and port (for load-balanced targets).
///
/// `strip_len` is the number of bytes to strip from the start of `incoming_path`
/// when `proxy.strip_listen_path` is true. For prefix routes this equals
/// `proxy.listen_path.len()`; for regex routes it is the regex match length
/// (from `RouteMatch::matched_prefix_len`).
///
/// Uses a single `String` buffer to avoid intermediate allocations from
/// multiple `format!` calls.
pub fn build_backend_url_with_target(
    proxy: &Proxy,
    incoming_path: &str,
    query_string: &str,
    host: &str,
    port: u16,
    strip_len: usize,
    target_path: Option<&str>,
) -> String {
    use std::fmt::Write;

    // URL scheme is a function of TLS-vs-plaintext only. gRPC and WebSocket
    // use the same `http`/`https` wire scheme — the flavor only changes the
    // request's content-type / Upgrade header, not the URL scheme. Stream
    // kinds never reach this builder but we fall through safely for them.
    let scheme = match proxy.dispatch_kind {
        DispatchKind::HttpPool => "http",
        DispatchKind::HttpsPool => "https",
        DispatchKind::TcpRaw | DispatchKind::UdpRaw => "http",
        DispatchKind::TcpTls | DispatchKind::UdpDtls => "https",
    };

    with_backend_path_parts(
        proxy,
        incoming_path,
        strip_len,
        target_path,
        |backend_path, remaining_path| {
            let path_layout = backend_path_layout(backend_path, remaining_path);
            let rendered_host = url_render_host(host);

            // Build URL in a single buffer, writing the path segments directly
            // to avoid an intermediate `full_path` allocation.
            let capacity = scheme.len()
                + 3
                + rendered_host.len()
                + 6
                + path_layout.len
                + if query_string.is_empty() {
                    0
                } else {
                    1 + query_string.len()
                };
            let mut url = String::with_capacity(capacity);
            let _ = write!(url, "{}://{}:{}", scheme, rendered_host, port);
            push_backend_path(&mut url, backend_path, remaining_path);

            if !query_string.is_empty() {
                url.push('?');
                url.push_str(query_string);
            }
            url
        },
    )
}

/// Resolve the effective `Proxy` for one backend dispatch, honoring an
/// upstream's per-destination-port `connect_timeout_ms` override (Istio
/// `DestinationRule.trafficPolicy.portLevelSettings[].connectionPool.tcp.connectTimeout`).
///
/// Hot-path discipline: single field read on `Proxy.dispatch_port_overrides`
/// (precomputed at config-resolve time by
/// `GatewayConfig::resolve_dispatch_port_overrides()`). No `ArcSwap` load,
/// no `DashMap` lookup — the common no-override case is a borrowed `Proxy`.
/// The owned-clone branch only fires for the rare case where (a) the proxy
/// has at least one port override AND (b) the resolved destination port
/// matches a configured override key AND (c) the override's
/// `connect_timeout_ms` differs from `proxy.backend_connect_timeout_ms`.
/// Use this helper when the transport receives the LB-selected
/// `UpstreamTarget` separately (reqwest/H3 dispatch, TCP/HBONE timeout
/// derivation) and only needs the per-port timeout rebased onto the proxy.
/// Do not use it for pools that key or dial from `proxy.backend_host` /
/// `proxy.backend_port`; those paths need
/// `resolve_backend_connection_proxy_for_target`.
///
/// `upstream_target` is the LB-selected target whose port we'll connect to;
/// when `None` the call is a direct-backend proxy with no upstream, so no
/// per-port lookup is possible.
pub(crate) fn resolve_effective_proxy_for_target<'a>(
    proxy: &'a Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> std::borrow::Cow<'a, Proxy> {
    let Some(target) = upstream_target else {
        return std::borrow::Cow::Borrowed(proxy);
    };
    // Per-port override for the LB-selected target's policy port and the service-discovery
    // top-level `connectionPool.http` overlay (`Proxy.dispatch_port_override_fallback`)
    // are FIELD-MERGED, not wholesale-replaced: a per-port `connectionPool.http`
    // field wins when set, otherwise the top-level overlay's value is inherited —
    // so an unrelated per-port field (`connectTimeout`/`tls`) no longer wipes the
    // inherited top-level `idleTimeout`/`http2MaxRequests`/`maxRetries`. This
    // matches the NON-SD apply-time layering exactly (top-level fan-out, then a
    // partial per-port overlay; see `apply_connection_pool_http_to_port_override`
    // in `src/modes/mesh/mod.rs`). Either side may be absent; the owned merge only
    // fires when BOTH are present (the rare SD-with-explicit-port case).
    let per_port = proxy
        .dispatch_port_overrides
        .as_ref()
        .and_then(|overrides| overrides.get(&target.dispatch_policy_port()));
    let fallback = proxy.dispatch_port_override_fallback.as_ref();
    let merged: Option<std::borrow::Cow<'_, crate::config::types::ResolvedPortOverride>> =
        match (per_port, fallback) {
            (Some(per_port), Some(fallback)) => {
                let mut owned = per_port.clone();
                owned.seed_connection_pool_http_from_fallback(fallback);
                Some(std::borrow::Cow::Owned(owned))
            }
            (Some(per_port), None) => Some(std::borrow::Cow::Borrowed(per_port)),
            (None, Some(fallback)) => Some(std::borrow::Cow::Borrowed(fallback)),
            (None, None) => None,
        };
    let Some(override_config) = merged else {
        return std::borrow::Cow::Borrowed(proxy);
    };
    let override_config = override_config.as_ref();

    // Compare each candidate override against the proxy's current value and
    // build an owned clone only when at least one field actually differs.
    // The HTTP-family additions (T1-C) reuse the existing
    // `connect_timeout_ms` fast path so the common "no override" and "override
    // matches current value" branches still return a borrowed proxy without
    // allocating.

    let connect_override = override_config
        .connect_timeout_ms
        .filter(|&v| v != proxy.backend_connect_timeout_ms);

    // `pool_http2_max_concurrent_streams` lives on the proxy as
    // `Option<u32>`; project the per-port value when it differs from what
    // the proxy already carries (treating `None` as "no proxy default").
    let h2_streams_override = override_config
        .h2_max_concurrent_streams
        .filter(|new| Some(*new) != proxy.pool_http2_max_concurrent_streams);

    // Per-port HTTP idle timeout is exposed as milliseconds on the override
    // and as whole seconds on the proxy (`pool_idle_timeout_seconds`). The
    // translator already rejects sub-second durations, so the conversion is
    // lossless here.
    let idle_seconds_override = override_config.http_idle_timeout_ms.and_then(|ms| {
        let secs = ms / 1000;
        (Some(secs) != proxy.pool_idle_timeout_seconds).then_some(secs)
    });

    // `maxRequestsPerConnection` is intentionally not projected from
    // DestinationRule-derived port overrides. It has no backend close-after-N
    // runtime behavior, so translation/status report it as deferred instead of
    // letting a legacy carried value appear effective here.

    // Per-port backend TLS (DestinationRule `portLevelSettings[].tls`), resolved
    // at apply time. Overrides the proxy's upstream-/subset-level `resolved_tls`
    // for dials to this port. `resolved_tls` identity fields are part of the
    // backend pool key (built from this effective proxy), so a distinct per-port
    // TLS posture fragments its own pool instead of sharing a connection.
    let tls_override = override_config
        .tls
        .as_ref()
        .filter(|t| **t != proxy.resolved_tls);

    // Per-port `h2UpgradePolicy` (DestinationRule `connectionPool.http`). Drives
    // the plain-HTTPS H2-vs-H1 dispatch fork in `proxy_to_backend` via the
    // effective proxy's `h2_upgrade_policy`. Project it when the per-port value
    // differs from what the proxy already carries.
    let h2_upgrade_override = override_config
        .h2_upgrade_policy
        .filter(|new| Some(*new) != proxy.h2_upgrade_policy);

    // Per-port `http1MaxPendingRequests` (DestinationRule `connectionPool.http`).
    // Drives the reqwest/H1 dispatch path's pending-request gate in
    // `proxy_to_backend` via the effective proxy's
    // `pool_http1_max_pending_requests`. Project it when the per-port value
    // differs from what the proxy already carries.
    let http1_pending_override = override_config
        .http1_max_pending_requests
        .filter(|new| Some(*new) != proxy.pool_http1_max_pending_requests);

    if connect_override.is_none()
        && h2_streams_override.is_none()
        && idle_seconds_override.is_none()
        && tls_override.is_none()
        && h2_upgrade_override.is_none()
        && http1_pending_override.is_none()
    {
        return std::borrow::Cow::Borrowed(proxy);
    }

    let mut owned = proxy.clone();
    if let Some(ms) = connect_override {
        owned.backend_connect_timeout_ms = ms;
    }
    if let Some(streams) = h2_streams_override {
        owned.pool_http2_max_concurrent_streams = Some(streams);
    }
    if let Some(secs) = idle_seconds_override {
        owned.pool_idle_timeout_seconds = Some(secs);
    }
    if let Some(tls) = tls_override {
        owned.resolved_tls = tls.clone();
    }
    if let Some(policy) = h2_upgrade_override {
        owned.h2_upgrade_policy = Some(policy);
    }
    if let Some(pending) = http1_pending_override {
        owned.pool_http1_max_pending_requests = Some(pending);
    }
    std::borrow::Cow::Owned(owned)
}

/// Cap a proxy's per-request retry count from the DestinationRule
/// `connectionPool.http.maxRetries` override for the dispatch target's port.
///
/// **Honest semantics (read this):** Envoy's `connectionPool.http.maxRetries`
/// is a *cluster-wide outstanding-retry concurrency budget*. Ferrum's retry
/// model (`Proxy.retry`) is *per-request*, so we interpret DR `maxRetries` as
/// an upper bound on the per-request retry count, NOT Envoy's gauge. See
/// `docs/mesh.md` "DestinationRule maxRetries semantics".
///
/// **Why the SELECTED target's port, not a min across every port:** the cap
/// must come from the port the request actually dials. Retries stay in the
/// selected target's PORT LANE — `select_next_retry_target` resolves the next
/// target with `select_next_target_for_port_*_from` whenever the failed
/// target's port has a live per-port override (see
/// `retry_port_override_dispatch_port` + `LoadBalancerCache::has_port_override_state_from`),
/// so a per-port `maxRetries` does NOT rotate across ports between attempts.
/// The selected-port cap therefore governs the whole retry sequence. Taking the
/// MINIMUM across every override would instead let a higher-cap port inherit an
/// unrelated sibling port's lower cap (port 8080 cap 5 wrongly limited to 1
/// because port 9090 has cap 1) — that is what we must NOT do.
///
/// In practice, for MESH upstreams — the only place `maxRetries` applies, since
/// it is DestinationRule-derived — the per-port caps fan out UNIFORMLY: the
/// translator (`apply_destination_rules`) fans one owning-service-port entry to
/// every target dial port, so all of one upstream's port-override caps are
/// equal anyway. Keying on the selected port is correct for the uniform mesh
/// case and avoids the cross-port leakage in the mixed-cap non-mesh case.
///
/// Precedence / no-double-retry:
/// * If the proxy already has a retry policy, the effective `max_retries`
///   becomes `min(existing, dr_max_retries)` — never *increases* retries.
/// * If the proxy has NO retry policy, DR `maxRetries` alone does NOT enable
///   retries (an Istio `maxRetries` is a budget, not a retry-policy enabler),
///   so we leave `retry == None`.
///
/// Applied once, in `handle_proxy_request_inner`, right after the dispatch
/// target (hence its port) is resolved and BEFORE `proxy.retry` is consumed
/// by the HTTP / gRPC / WebSocket retry loops. Returns the same `Arc` (no
/// clone) in the common case: no port override, no `maxRetries`, no retry
/// policy, or the cap is already >= the configured count.
///
/// Hot-path discipline: a single map lookup on the already-present, precomputed
/// `Proxy.dispatch_port_overrides` (no `ArcSwap` load, no allocation unless a
/// clone is actually needed to reduce the count).
///
/// The standalone H3 frontend mirrors this after target selection in
/// `src/http3/server.rs`, before native-H3 and cross-protocol dispatch read the
/// proxy.
pub(crate) fn cap_proxy_retry_for_target(
    proxy: Arc<Proxy>,
    upstream_target: Option<&UpstreamTarget>,
) -> Arc<Proxy> {
    // No retry policy → DR maxRetries does not synthesize one.
    let Some(existing) = proxy.retry.as_ref() else {
        return proxy;
    };
    let Some(target) = upstream_target else {
        return proxy;
    };
    // Cap from the SELECTED dispatch target's policy-port override. Retries stay in
    // this port's lane (see docstring), so this cap governs the whole sequence.
    // FIELD-level fallback: the per-port `maxRetries` wins when set, otherwise
    // the service-discovery top-level `connectionPool.http.maxRetries` overlay
    // (`Proxy.dispatch_port_override_fallback`) is inherited — so a per-port
    // entry that sets only an unrelated field (e.g. `connectTimeout`) does not
    // wipe the inherited top-level cap. Mirrors the field-merge in
    // `resolve_effective_proxy_for_target` and the non-SD apply-time layering.
    let cap = proxy
        .dispatch_port_overrides
        .as_ref()
        .and_then(|overrides| overrides.get(&target.dispatch_policy_port()))
        .and_then(|o| o.max_retries)
        .or_else(|| {
            proxy
                .dispatch_port_override_fallback
                .as_ref()
                .and_then(|o| o.max_retries)
        });
    let Some(cap) = cap else {
        return proxy;
    };
    if existing.max_retries <= cap {
        // Cap does not reduce the configured count — nothing to do.
        return proxy;
    }
    let mut owned = (*proxy).clone();
    if let Some(retry) = owned.retry.as_mut() {
        retry.max_retries = cap;
    }
    Arc::new(owned)
}

/// Resolve the DestinationRule `connectionPool.tcp.maxConnections` cap for the
/// destination port a backend dial will target.
///
/// Returns `None` (no cap) in the common case: the proxy has no
/// `dispatch_port_overrides`, the resolved port has no override, or the
/// override carries no `max_connections`. Hot-path discipline matches
/// [`resolve_effective_proxy_for_target`]: a single field read on the
/// precomputed `Proxy.dispatch_port_overrides` map, no `ArcSwap` load.
///
/// `dispatch_port` is the port the dial will actually use: the LB-selected
/// `UpstreamTarget.port` for upstream proxies, or `proxy.backend_port` for a
/// direct-backend proxy with no upstream. This mirrors how the raw-TCP path
/// reads the same field via `ResolvedPortOverride.max_connections`.
pub(crate) fn resolve_backend_max_connections(proxy: &Proxy, dispatch_port: u16) -> Option<u32> {
    proxy
        .dispatch_port_overrides
        .as_ref()
        .and_then(|overrides| overrides.get(&dispatch_port))
        .and_then(|override_config| override_config.max_connections)
}

/// Resolve the DestinationRule `connectionPool.http.http1MaxPendingRequests`
/// cap for the destination port a backend dial will target.
///
/// Returns `None` (no cap) in the common case: the proxy has no
/// `dispatch_port_overrides`, the resolved port has no override, or the
/// override carries no `http1_max_pending_requests`. Hot-path discipline
/// matches [`resolve_backend_max_connections`]: a single field read on the
/// precomputed `Proxy.dispatch_port_overrides` map, no `ArcSwap` load.
///
/// `dispatch_port` is the port the dial will actually use: the LB-selected
/// `UpstreamTarget.port` for upstream proxies, or `proxy.backend_port` for a
/// direct-backend proxy with no upstream.
///
/// FIELD-level fallback (#1806 codex r1): when the per-port entry carries no
/// `http1_max_pending_requests`, inherit the service-discovery top-level
/// `connectionPool.http.http1MaxPendingRequests` overlay
/// (`Proxy.dispatch_port_override_fallback`) — so an SD upstream that sets ONLY a
/// top-level cap (no per-port entry) is still capped, and a per-port entry that
/// sets an unrelated field does not wipe the inherited cap. Mirrors how
/// `resolve_effective_proxy_for_target` consumes the fallback.
pub(crate) fn resolve_backend_http1_max_pending_requests(
    proxy: &Proxy,
    dispatch_port: u16,
) -> Option<u32> {
    proxy
        .dispatch_port_overrides
        .as_ref()
        .and_then(|overrides| overrides.get(&dispatch_port))
        .and_then(|override_config| override_config.http1_max_pending_requests)
        .or_else(|| {
            proxy
                .dispatch_port_override_fallback
                .as_ref()
                .and_then(|fallback| fallback.http1_max_pending_requests)
        })
}

/// Whether the reqwest-backed backend client for this (effective) proxy is
/// **known to dispatch over HTTP/1.1 at acquire time** — the only transport the
/// `connectionPool.http.http1MaxPendingRequests` pending-request gate applies
/// to. The gate is consulted ONLY when this returns `true`, so a backend that
/// MIGHT negotiate h2 is left uncapped (an `http1*` knob must not 503 an h2
/// backend — that is `http2MaxRequests`'s job).
///
/// HTTP/1.1 is *known* in these cases:
///
/// * `proxy.forces_backend_http1_only()` — DestinationRule
///   `h2UpgradePolicy: DO_NOT_UPGRADE` restricts the reqwest client's ALPN to
///   `http/1.1` (see `BackendTlsConfigBuilder::build_reqwest`), so even an
///   h2-capable backend is pinned to HTTP/1.1; or
/// * the backend scheme is **plaintext `http`** (`DispatchKind::HttpPool`,
///   i.e. `!is_tls_backend()` on the HTTP-family reqwest path) — reqwest never
///   speaks h2c / HTTP/2-prior-knowledge over cleartext, so every cleartext
///   dial is HTTP/1.1; or
/// * backend HTTP/2 is disabled for this proxy (`pool_enable_http2: false`) —
///   the request has already been routed away from the direct-H2 pool and onto
///   reqwest, and Ferrum's preconfigured-rustls reqwest path does not install
///   h2 ALPN in this mode, so the operator's H1 cap must remain in force; or
/// * the backend is **HTTPS but the capability registry has already classified
///   this target H2/TLS-unsupported (H1-only)** — the direct-H2 pool fork
///   (`direct_h2_known_unsupported` in `proxy_to_backend`) then bypasses the H2
///   pool and falls to this reqwest path, where the backend re-negotiates
///   HTTP/1.1 every time (the verdict was learned from a prior
///   `Http2PoolError::BackendSelectedHttp1` fallback or a startup probe), so the
///   dispatch is known HTTP/1.1 at acquire time and must be capped.
///
/// A **HTTPS** backend with backend HTTP/2 enabled and no H1-only registry
/// verdict MAY still negotiate h2 via ALPN — unknown until the TLS handshake
/// completes — so it is deliberately NOT capped (an `http1*` knob must not 503 a
/// reqwest dispatch that becomes h2). The buffered/retained-body bypass
/// (`enable_http2 && (retain_request_body || requires_request_body_buffering)`)
/// likewise stays uncapped absent a registry verdict.
///
/// Only ever called after a non-`None` `http1MaxPendingRequests` cap has been
/// resolved (the rare case a DestinationRule sets the knob), so the
/// `for_proxy` pool-config resolve and registry lookup never run on the no-cap
/// hot path.
pub(crate) fn reqwest_dispatch_is_http1_only(
    state: &ProxyState,
    proxy: &Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> bool {
    if proxy.forces_backend_http1_only() {
        return true;
    }
    // Plaintext `http` backend: reqwest dispatches HTTP/1.1 (no h2c / prior
    // knowledge over cleartext), so the H1 cap applies regardless of the h2
    // preference. Only an HTTPS backend can ALPN-negotiate h2.
    if !proxy.dispatch_kind.is_tls_backend() {
        return true;
    }
    let pool_config = state.connection_pool.global_pool_config().for_proxy(proxy);
    if !pool_config.enable_http2 {
        return true;
    }
    // HTTPS backend: HTTP/1.1 is *known* only when the capability registry has
    // already classified this target H2/TLS-unsupported — then, even though the
    // reqwest client still advertises h2 ALPN, the backend negotiates h1, and
    // `proxy_to_backend`'s direct-H2 fork keys this exact verdict
    // (`record.plain_http.h2_tls == Unsupported`) to bypass the H2 pool and fall
    // to reqwest-H1.
    // Lookup uses the same target-effective capability key as the H2 fork.
    get_backend_capability_for_target(state.backend_capabilities.as_ref(), proxy, upstream_target)
        .is_some_and(|record| {
            matches!(
                record.plain_http.h2_tls,
                crate::proxy::backend_capabilities::ProtocolSupport::Unsupported
            )
        })
}

/// Resolve the per-port retry lane after a concrete target has failed.
///
/// Initial selection may use the full upstream for mixed-port target sets when
/// no request destination port is known yet. Retry is different: we have a
/// failed `prev_target`, so staying in that target's configured port lane
/// avoids switching destination ports and bypassing port-scoped LB/passive
/// policy on the retry attempt.
pub(crate) fn retry_port_override_dispatch_port(
    proxy: &Proxy,
    prev_target: &UpstreamTarget,
) -> Option<u16> {
    let dispatch_port = prev_target.dispatch_policy_port();
    proxy
        .dispatch_port_overrides
        .as_ref()
        .is_some_and(|overrides| overrides.contains_key(&dispatch_port))
        .then_some(dispatch_port)
}

/// Resolve the effective `Proxy` for backend pools that build their key and
/// dial target from `proxy.backend_host` / `proxy.backend_port`.
///
/// Generic reqwest and H3 dispatch pass the selected upstream target as an
/// explicit argument to their transport. The gRPC and direct-H2 pools do not:
/// their pool keys and connection establishment read the `Proxy` fields
/// directly. After an upstream override or normal load-balanced selection,
/// those pool-backed paths must bake the concrete target host/port into the
/// proxy clone or they can reuse/dial a connection for the route template's
/// original backend.
pub(crate) fn resolve_backend_connection_proxy_for_target<'a>(
    proxy: &'a Proxy,
    upstream_target: Option<&UpstreamTarget>,
) -> std::borrow::Cow<'a, Proxy> {
    let mut effective = resolve_effective_proxy_for_target(proxy, upstream_target);
    if let Some(target) = upstream_target {
        let policy_port = target.dispatch_policy_port();
        if policy_port != target.port
            && let Some(policy_override) = effective
                .dispatch_port_overrides
                .as_ref()
                .and_then(|overrides| overrides.get(&policy_port))
                .cloned()
        {
            // Direct H2 and gRPC pools receive only this effective proxy, then
            // look up socket keepalive by `proxy.backend_port`. Mirror the selected
            // service-port policy onto that dial port in the per-dispatch clone so
            // targetPort remaps keep the dial address and policy identity distinct
            // without changing the serialized proxy or global projected map.
            effective
                .to_mut()
                .dispatch_port_overrides
                .get_or_insert_with(HashMap::new)
                .insert(target.port, policy_override);
        }
        if effective.backend_host != target.host || effective.backend_port != target.port {
            let owned = effective.to_mut();
            owned.backend_host = target.host.clone();
            owned.backend_port = target.port;
        }
    }
    effective
}

/// Retry a backend request, replaying the original request body if available.
/// The body bytes were collected and retained on the first attempt so they
/// can be replayed on connection-failure retries without data loss.
#[allow(clippy::too_many_arguments)]
pub(crate) async fn proxy_to_backend_retry(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    upstream_target: Option<&UpstreamTarget>,
    request_body: Option<&[u8]>,
    stream_response: bool,
    plugins: &[Arc<dyn Plugin>],
    request_ctx: &RequestContext,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    inbound_version: hyper::Version,
) -> retry::BackendResponse {
    // Honor DestinationRule per-port `connect_timeout_ms` overrides for this
    // specific destination port. Borrowed when no override applies (zero-alloc
    // hot path); cloned only when an override actually differs from
    // `proxy.backend_connect_timeout_ms`.
    let effective_proxy = resolve_effective_proxy_for_target(proxy, upstream_target);
    let proxy: &Proxy = effective_proxy.as_ref();

    // All reqwest clients use our DnsCacheResolver, so DNS resolution is
    // always served from the warmed cache — never hitting DNS on the hot path.
    // For both single-backend and load-balanced proxies, the client transparently
    // resolves hostnames through the DNS cache.
    let effective_host = upstream_target
        .map(|t| t.host.as_str())
        .unwrap_or(&proxy.backend_host);

    // Re-screen the (possibly LB-rotated) retry target: reqwest skips the
    // DnsCacheResolver for IP literals, so a denied literal reached via retry
    // rotation must be rejected here too, mirroring the first-attempt screen in
    // proxy_to_backend. (Hostname targets are screened by the resolver at
    // dispatch and classified via classify_reqwest_error.)
    if denied_literal_backend_ip(effective_host, &state.env_config.backend_allow_ips).is_some() {
        return backend_egress_denied_response(effective_host);
    }

    if proxy.resolved_tls.sni.is_some() {
        warn!(
            proxy_id = %proxy.id,
            backend_tls_sni = ?proxy.resolved_tls.sni,
            "Backend TLS SNI override cannot be replayed through reqwest retry path; returning 502"
        );
        return backend_tls_sni_requires_direct_h2_response(None);
    }

    // Resolve backend IP from DNS cache (O(1) cached lookup).
    let resolve_backend_ip = state.dns_cache.resolve(
        effective_host,
        proxy.dns_override.as_deref(),
        proxy.dns_cache_ttl_seconds,
    );
    let resolved_ip_result = if let Some(deadline) = request_ctx.grpc_deadline_at() {
        match tokio::time::timeout_at(deadline, resolve_backend_ip).await {
            Ok(result) => result,
            Err(_) => {
                return client_grpc_deadline_exceeded_response_for_request(
                    request_ctx,
                    headers,
                    None,
                );
            }
        }
    } else {
        resolve_backend_ip.await
    };
    let resolved_ip = resolved_ip_result.ok().map(|ip| ip.to_string());

    let client_result = crate::plugins::await_grpc_deadline(
        request_ctx.grpc_deadline_at(),
        state.connection_pool.get_client(proxy),
    )
    .await;
    let client = match client_result {
        Err(()) => {
            return client_grpc_deadline_exceeded_response_for_request(
                request_ctx,
                headers,
                resolved_ip,
            );
        }
        Ok(Ok(client)) => client,
        Ok(Err(e)) => {
            error!("Failed to get client from pool for retry: {}", e);
            return retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    format!(r#"{{"error":"Backend unavailable: {}"}}"#, e).into_bytes(),
                ),
                headers: HashMap::new(),
                connection_error: true,
                backend_resolved_ip: resolved_ip.clone(),
                error_class: Some(retry::ErrorClass::ConnectionPoolError),
            };
        }
    };

    let req_method = match parse_reqwest_method(method) {
        Ok(m) => m,
        Err(()) => {
            warn!("Invalid HTTP method on retry: {}", method);
            return retry::BackendResponse {
                status_code: 405,
                body: ResponseBody::Buffered(
                    r#"{"error":"Method Not Allowed"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip.clone(),
                error_class: None,
            };
        }
    };

    let mut req_builder = client.request(req_method, backend_url);

    // Per-request timeout overrides. The shared `reqwest::Client` intentionally
    // has no client-level connect or read timeout (see
    // `connection_pool::create_client`) so two proxies with different timeouts
    // sharing the same pool entry do not leak policy across routes. `0` means
    // "disabled" for both — skip the override so reqwest's default (no timeout)
    // applies. The per-request `connect_timeout` API is provided by a vendored
    // copy of reqwest patched with seanmonstar/reqwest#3017.
    // Keep the timeout source typed: the outer `await_grpc_deadline` owns the
    // client RPC deadline, while reqwest owns only operator timeouts that
    // expire strictly earlier. Installing the same budget in both
    // places creates a race where reqwest can misclassify client expiry as a
    // backend failure and train health/adaptive accounting.
    let client_deadline_remaining = if let Some(deadline) = request_ctx.grpc_deadline_at() {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        if remaining.is_zero() {
            return client_grpc_deadline_exceeded_response_for_request(
                request_ctx,
                headers,
                resolved_ip,
            );
        }
        Some(remaining)
    } else {
        None
    };
    if proxy.backend_connect_timeout_ms > 0 {
        let operator_timeout = Duration::from_millis(proxy.backend_connect_timeout_ms);
        if client_deadline_remaining.is_none_or(|remaining| operator_timeout < remaining) {
            req_builder = req_builder.connect_timeout(operator_timeout);
        }
    }
    if proxy.backend_read_timeout_ms > 0 {
        let operator_timeout = Duration::from_millis(proxy.backend_read_timeout_ms);
        if client_deadline_remaining.is_none_or(|remaining| operator_timeout < remaining) {
            req_builder = req_builder.timeout(operator_timeout);
        }
    }

    // Forward headers, stripping hop-by-hop headers per RFC 9110 §7.6.1
    // (canonical predicate in `proxy::headers`). Also strip every header
    // NAMED in the request's `Connection` field — see
    // `parse_connection_listed_from_str_map` for the spec rationale and
    // smuggling defence.
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (k, v) in headers {
        match k.as_str() {
            "host" => {
                if proxy.preserve_host_header {
                    req_builder = req_builder.header("Host", v.as_str());
                } else {
                    // Use upstream target host when load balancing, so SNI-based
                    // ingress routers see the correct Host header for the target.
                    req_builder = req_builder.header("Host", effective_host);
                }
            }
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            _ => {
                req_builder = req_builder.header(k.as_str(), v.as_str());
            }
        }
    }

    // Add proxy-managed forwarding metadata.
    let xff_val = build_xff_value(
        headers.get("x-forwarded-for").map(|s| s.as_str()),
        client_ip,
        xff_append_ip,
        &state.trusted_proxies,
    );
    let proto_str = if request_is_secure { "https" } else { "http" };
    req_builder = req_builder.header("X-Forwarded-For", xff_val);
    req_builder = req_builder.header("X-Forwarded-Proto", proto_str);
    if let Some(host) = headers.get("host") {
        req_builder = req_builder.header("X-Forwarded-Host", host.as_str());
    }
    let via = via_header_for_inbound_version(state, inbound_version);
    if let Some(via) = via {
        req_builder = req_builder.header("Via", via.as_str());
    }
    if state.add_forwarded_header {
        req_builder = req_builder.header(
            "Forwarded",
            build_forwarded_value(
                client_ip,
                proto_str,
                headers.get("host").map(|s| s.as_str()),
            ),
        );
    }

    // Replay the original request body on retry if available.
    // On connection failures the body was never sent, so replaying is safe.
    if let Some(body) = request_body
        && !body.is_empty()
    {
        req_builder = req_builder.body(body.to_vec());
    }

    // DestinationRule `connectionPool.http.http1MaxPendingRequests`: re-enter the
    // same per-`(host, policy-port)` pending gate as the initial attempt
    // (`proxy_to_backend`). The initial attempt's slot was already released
    // before the retry loop ran (it drops the moment that attempt's `send()`
    // returns), so a retry no longer overlaps it — without acquiring here, a
    // `retry_on_connect_failure`-driven retry storm would dial this destination
    // unboundedly, bypassing the cap. Acquire under the SAME H1 predicate
    // (`reqwest_dispatch_is_http1_only`). Under the in-flight reinterpretation
    // (see `proxy_to_backend` / `docs/mesh.md`) every H1-determined attempt
    // counts, so there is no body-shape exclusion. The slot is released the
    // instant this attempt's `send()` returns (the `drop` below), so it spans
    // only this attempt's in-flight window and an attempt never double-counts.
    let retry_dial_port = upstream_target
        .map(|t| t.port)
        .unwrap_or(proxy.backend_port);
    let retry_policy_port = upstream_target
        .map(UpstreamTarget::dispatch_policy_port)
        .unwrap_or(proxy.backend_port);
    let retry_pending_cap = resolve_backend_http1_max_pending_requests(proxy, retry_policy_port)
        .filter(|_| reqwest_dispatch_is_http1_only(state, proxy, upstream_target));
    let retry_pending_slot = match state.backend_pending_limit.try_acquire(
        effective_host,
        retry_policy_port,
        retry_pending_cap,
    ) {
        Ok(slot) => slot,
        Err(limit) => {
            warn!(
                proxy_id = %proxy.id,
                backend_host = %effective_host,
                backend_port = retry_dial_port,
                pending_requests = limit.current,
                max_pending_requests = limit.cap,
                "Shedding HTTP/1.1 retry: DestinationRule http1MaxPendingRequests reached for backend (upstream overflow)"
            );
            // Gateway-side capacity shed before the retry dial: classify
            // `DispatchPolicyRejected` (NOT a connection_error) so the retry
            // loop does not treat the shed as another connect failure and
            // amplify the overflow. That class is a no-backend-signal
            // (`client_side_no_backend_signal`), so this overflow 503 stays
            // NEUTRAL to backend health/CB/AC, mirroring the initial-attempt
            // shed.
            return retry::BackendResponse {
                status_code: 503,
                body: ResponseBody::Buffered(
                    r#"{"error":"Upstream pending request queue full"}"#
                        .as_bytes()
                        .to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip.clone(),
                error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
            };
        }
    };

    let mut reqwest_backend_guard =
        Some(crate::runtime_metrics::global_ref().reqwest_backend_request_guard());
    let send_result = match crate::plugins::await_grpc_deadline(
        request_ctx.grpc_deadline_at(),
        req_builder.send(),
    )
    .await
    {
        Ok(result) => result,
        Err(()) => {
            return client_grpc_deadline_exceeded_response_for_request(
                request_ctx,
                headers,
                resolved_ip,
            );
        }
    };
    // Release this retry attempt's in-flight slot the instant `send()` resolves
    // (response headers / dial failure) — BEFORE any response-body collection —
    // so it spans this attempt's dispatch → response-headers window only, never
    // the response lifetime. A no-cap / non-HTTP-1.1 retry holds `None` here, so
    // the drop is a no-op.
    drop(retry_pending_slot);
    match send_result {
        Ok(response) => {
            let status = response.status().as_u16();
            let mut resp_headers = HashMap::with_capacity(response.headers().keys_len());
            collect_response_headers(response.headers(), &mut resp_headers);
            let retry_ctx = (!stream_response
                && plugins_may_release_response_body_under_retries(plugins, request_ctx))
            .then(|| retry_response_decision_context(request_ctx));
            let stream_response = if stream_response {
                true
            } else {
                refine_stream_response_for_content_type(
                    false,
                    proxy,
                    plugins,
                    retry_ctx.as_ref(),
                    status,
                    &resp_headers,
                )
            };

            // Enforce response body size limit — mirrors the logic in
            // `proxy_to_backend`. Without this the retry path would accept
            // arbitrarily large response bodies, bypassing the operator-
            // configured `max_response_body_size_bytes`.
            let content_length = response
                .headers()
                .get("content-length")
                .and_then(|v| v.to_str().ok())
                .and_then(|v| v.parse::<usize>().ok());

            // Fast path: reject immediately when Content-Length exceeds limit.
            if state.max_response_body_size_bytes > 0
                && let Some(len) = content_length
                && len > state.max_response_body_size_bytes
            {
                warn!(
                    "Backend response body ({} bytes) exceeds limit ({} bytes)",
                    len, state.max_response_body_size_bytes
                );
                return retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Backend response body exceeds maximum size"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip.clone(),
                    error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                };
            }

            if stream_response {
                // Buffer small responses eagerly: a single `bytes().await`
                // allocation is cheaper than the async coalescing adapter for
                // typical JSON API payloads. Skip buffering for SSE (unbounded
                // streams) and responses without Content-Length (unknown size).
                let cutoff = state.response_buffer_cutoff_bytes;
                if cutoff > 0
                    && content_length.is_some_and(|cl| cl <= cutoff)
                    && !is_streaming_content_type(&resp_headers)
                {
                    // Content-Length is within cutoff (and within max_response
                    // _body_size_bytes if set, checked above), so eager
                    // collection is bounded.
                    let body_read = match crate::plugins::await_grpc_deadline(
                        request_ctx.grpc_deadline_at(),
                        response.bytes(),
                    )
                    .await
                    {
                        Ok(result) => result,
                        Err(()) => {
                            return client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip,
                            );
                        }
                    };
                    buffered_backend_response_from_body_read(
                        body_read,
                        status,
                        resp_headers,
                        resolved_ip.clone(),
                    )
                } else {
                    // Streaming path — the downstream body builder applies
                    // `SizeLimitedStreamingResponse` when CL is absent and a
                    // size limit is configured, so no enforcement needed here.
                    retry::BackendResponse {
                        status_code: status,
                        body: ResponseBody::Streaming {
                            response,
                            reqwest_backend_guard: reqwest_backend_guard.take(),
                        },
                        headers: resp_headers,
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: None,
                    }
                }
            } else {
                // Buffered mode: use size-limited collection when a limit is
                // configured so an oversized chunked response cannot exhaust
                // memory.
                if state.max_response_body_size_bytes > 0 {
                    let max_size = state.max_response_body_size_bytes;
                    let collected = match crate::plugins::await_grpc_deadline(
                        request_ctx.grpc_deadline_at(),
                        collect_response_with_limit(response, max_size),
                    )
                    .await
                    {
                        Ok(result) => result,
                        Err(()) => {
                            return client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip,
                            );
                        }
                    };
                    match collected {
                        Ok((resp_body, _)) => retry::BackendResponse {
                            status_code: status,
                            body: ResponseBody::Buffered(resp_body),
                            headers: resp_headers,
                            connection_error: false,
                            backend_resolved_ip: resolved_ip.clone(),
                            error_class: None,
                        },
                        Err(err_body) => retry::BackendResponse {
                            status_code: 502,
                            body: ResponseBody::Buffered(err_body),
                            headers: HashMap::new(),
                            connection_error: false,
                            backend_resolved_ip: resolved_ip.clone(),
                            error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                        },
                    }
                } else {
                    let body_read = match crate::plugins::await_grpc_deadline(
                        request_ctx.grpc_deadline_at(),
                        response.bytes(),
                    )
                    .await
                    {
                        Ok(result) => result,
                        Err(()) => {
                            return client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip,
                            );
                        }
                    };
                    buffered_backend_response_from_body_read(
                        body_read,
                        status,
                        resp_headers,
                        resolved_ip.clone(),
                    )
                }
            }
        }
        Err(e) => {
            let error_class = retry::classify_reqwest_error(&e);
            if error_class == retry::ErrorClass::PortExhaustion {
                state.overload.record_port_exhaustion();
            }
            // Drive `error_kind` and `connection_error` from `ErrorClass`
            // (see comment on the corresponding initial-attempt branch in
            // `proxy_to_backend`). Critically: a connect-class failure on
            // the retry path must still report `connection_error=true` so
            // the retry loop sees it and gives `retry_on_connect_failure`
            // another chance against the next upstream target.
            let error_kind = retry::error_class_log_kind(error_class);
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                error_kind = error_kind,
                error = %e,
                "Backend retry request failed"
            );
            let error_body = r#"{"error":"Backend unavailable"}"#;
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(error_body.as_bytes().to_vec()),
                headers: HashMap::new(),
                connection_error: !retry::request_reached_wire(error_class),
                backend_resolved_ip: resolved_ip.clone(),
                error_class: Some(error_class),
            }
        }
    }
}

/// Proxy the request to the backend.
///
/// `dispatch_h3` is captured by the caller and forced through here so the
/// dispatch decision is made exactly once per attempt — see the
/// `current_dispatch_h3` capture in `proxy_to_backend_inner` for the
/// rationale. Without it, a concurrent capability refresh /
/// `mark_h3_unsupported` between the outer capture and the async DNS resolve
/// below could flip the inner re-check and split a single attempt's
/// dispatch decision in half on the same target — the exact
/// cross-protocol-mid-attempt behavior this contract forbids.
///
/// Per-target rotation across retries IS allowed to switch protocols (see the
/// retry loop's recompute-on-target-change branch). The prohibition is on
/// switching transports mid-attempt or across same-target retries; cross-
/// target rotation runs against a different backend, so the new target's
/// own capability classification is the right answer.
enum BackendDispatchResult {
    Response {
        response: Box<retry::BackendResponse>,
        retained_body: Option<Bytes>,
        backend_admission_permits: Option<BackendAdmissionPermitSet>,
        request_body_exceeded: Option<Arc<std::sync::atomic::AtomicBool>>,
        streaming_h2_read_timeout_ms: Option<u64>,
    },
    AdmissionRejected(backend_dispatch::BackendAdmissionRejection),
}

/// Backend-admission result acquired before request-body finalization.
///
/// The explicit `was_run` bit distinguishes "admission ran and no plugin
/// returned a permit" from "admission has not run yet". This lets the narrow
/// post-transform response-policy path preserve fail-fast admission without
/// invoking admission plugins twice on accepted requests.
#[derive(Default)]
pub(crate) struct PreacquiredBackendAdmission {
    was_run: bool,
    permits: Option<BackendAdmissionPermitSet>,
}

impl PreacquiredBackendAdmission {
    pub(crate) fn acquired(permits: Option<BackendAdmissionPermitSet>) -> Self {
        Self {
            was_run: true,
            permits,
        }
    }

    pub(crate) fn take_if_acquired(&mut self) -> Option<Option<BackendAdmissionPermitSet>> {
        self.was_run.then(|| {
            self.was_run = false;
            self.permits.take()
        })
    }

    fn take_or_run(
        &mut self,
        plugins: &[Arc<dyn crate::plugins::Plugin>],
        ctx: &RequestContext,
        proxy: &Proxy,
        upstream_target: Option<&UpstreamTarget>,
        protocol: ProxyProtocol,
    ) -> Result<Option<BackendAdmissionPermitSet>, backend_dispatch::BackendAdmissionRejection>
    {
        if let Some(permits) = self.take_if_acquired() {
            Ok(permits)
        } else {
            backend_dispatch::run_backend_admission_plugins(
                plugins,
                ctx,
                proxy,
                upstream_target,
                protocol,
            )
        }
    }
}

fn backend_dispatch_response(
    response: retry::BackendResponse,
    retained_body: Option<Bytes>,
    backend_admission_permits: Option<BackendAdmissionPermitSet>,
) -> BackendDispatchResult {
    BackendDispatchResult::Response {
        response: Box::new(response),
        retained_body,
        backend_admission_permits,
        request_body_exceeded: None,
        streaming_h2_read_timeout_ms: None,
    }
}

/// Record a direct-H2 pool/connect failure against the admission permit acquired
/// before `get_sender()`. Used when `get_sender()` fails on a path that does not
/// fall back to reqwest (a real pool/connect failure, or an SNI-pinned backend
/// that cannot downgrade), so the adaptive limiter learns the connect failure
/// instead of seeing the slot silently released. Takes the permit, so its
/// in-flight slot is released when the returned permit set drops.
fn record_h2_pool_admission_failure(
    permits: &mut Option<BackendAdmissionPermitSet>,
    started_at: &Instant,
    err: &http2_pool::Http2PoolError,
) {
    if let Some(permits) = permits.take() {
        // Record the REAL classified class (not a hard-coded ConnectionPoolError):
        // a gateway-side egress denial (DispatchPolicyRejected — a hostname /
        // dns_override that resolves or rebinds to a blocked IP) dialed no
        // backend, so it must be neutral. `client_side_no_backend_signal` skips
        // the adaptive-concurrency shrink for that class, and the connect flag is
        // derived from `request_reached_wire` so it isn't charged as a connect
        // failure either.
        let class = http2_pool::classify_http2_pool_error(err);
        permits.record_backend_outcome(BackendAdmissionOutcome {
            response_status: 502,
            connection_error: !retry::request_reached_wire(class),
            error_class: Some(class),
            backend_elapsed: started_at.elapsed(),
        });
    }
}

/// Build a buffered `BackendResponse` from a reqwest body-read result. A read
/// failure AFTER the response headers arrived (backend reset/closed/timed out
/// mid-body) is a backend fault, so it must surface as a 502 with
/// an error class — NOT the backend's original status with a silently-emptied
/// body. It is not a connection error because response headers already arrived,
/// so retry policy must treat it as a post-wire/status failure and preserve
/// method/idempotency checks. Otherwise the non-streaming adaptive-concurrency
/// admission (and passive health) record a mid-body backend failure as a healthy
/// success and can grow the limit. Mirrors the size-limited buffered read paths
/// that already classify this.
fn buffered_backend_response_from_body_read(
    result: Result<bytes::Bytes, reqwest::Error>,
    status: u16,
    resp_headers: HashMap<String, String>,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    match result {
        Ok(b) => retry::BackendResponse {
            status_code: status,
            body: ResponseBody::Buffered(b.to_vec()),
            headers: resp_headers,
            connection_error: false,
            backend_resolved_ip: resolved_ip,
            error_class: None,
        },
        Err(e) => {
            warn!("Failed to read backend response body: {}", e);
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"Backend response body read failed"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ConnectionReset),
            }
        }
    }
}

/// Content-Length 413 fast path, hoisted BEFORE backend admission on the HBONE
/// and native-H3 dispatch branches. Those branches always dispatch (no reqwest
/// fall-through), and their request-size check lives inside the backend dispatch
/// function — i.e. after admission. With the adaptive limiter at capacity, an
/// oversized upload would then be rejected as a concurrency 503 instead of the
/// The egress-policy enforcement point for **literal-IP** backends.
///
/// reqwest and the H2/gRPC/H3 pools skip the `DnsCacheResolver` for a host that
/// is already an IP literal (there is nothing to resolve), so the resolver-side
/// screen never runs for them — only *hostname* backends are screened at dial
/// time. A denied literal `backend_host`/target (for example a row that DB load
/// only warned about, or any path that treats an IP as already resolved) would
/// otherwise be dialed. Returns the denial reason when `host` is a literal IP
/// blocked by the policy; `None` for hostnames (screened by the resolver) and
/// allowed IPs.
pub(crate) fn denied_literal_backend_ip(
    host: &str,
    policy: &crate::config::BackendEgressPolicy,
) -> Option<&'static str> {
    crate::config::types::egress_literal_ip(host).and_then(|ip| policy.deny_reason(&ip))
}

/// Like [`denied_literal_backend_ip`] but also screens the proxy's `dns_override`
/// literal IP: a `dns_override` pins resolution to a fixed address, so a denied
/// literal there must be rejected at dispatch too. Without this, a DB/CP-loaded
/// proxy (load only warns) with `dns_override` = a denied literal reaches the
/// connection-pool builder, which `bail!`s a generic `ConnectionPoolError`
/// (`connection_error=true`) that the retry loop replays and charges to passive
/// health / the breaker even though no backend was dialed.
pub(crate) fn denied_literal_backend_or_dns_override(
    host: &str,
    proxy: &Proxy,
    policy: &crate::config::BackendEgressPolicy,
) -> Option<&'static str> {
    denied_literal_backend_ip(host, policy).or_else(|| {
        proxy
            .dns_override
            .as_deref()
            .and_then(|ovr| denied_literal_backend_ip(ovr, policy))
    })
}

/// Canonical-literal-only counterpart of [`denied_literal_backend_ip`] for the
/// **self-resolving** dispatch pools — gRPC (`GrpcConnectionPool`) and native H3
/// (`Http3ConnectionPool`). Those pools do NOT hand the host to reqwest's URL
/// parser; they resolve it themselves through `DnsCache::resolve` /
/// `resolve_backend_addr_cached`, whose literal fast path is `IpAddr::parse`
/// (canonical only) and which otherwise performs real DNS and policy-screens the
/// *resolved* address. So a non-canonical numeric spelling like `2852039166` or
/// `111` is a DNS NAME on those paths (resolved, then screened), NOT the
/// URL-canonicalized literal `169.254.169.254` / `0.0.0.111` — screening it with
/// the URL-canonicalizing [`egress_literal_ip`] would wrongly reject a legitimate
/// all-numeric backend hostname. Canonical denied literals are still caught here
/// (and again by the resolver's own screen). reqwest-dialed paths (HTTP/1.1,
/// H2-via-reqwest, the H3 cross-protocol bridge) and config admission — none of
/// which know the runtime dispatch pool — MUST keep using [`egress_literal_ip`],
/// since a cold capability registry routes plain-HTTPS traffic through reqwest
/// where the URL-canonicalized bypass is real.
pub(crate) fn denied_literal_backend_ip_canonical(
    host: &str,
    policy: &crate::config::BackendEgressPolicy,
) -> Option<&'static str> {
    crate::config::types::stream_literal_ip(host).and_then(|ip| policy.deny_reason(&ip))
}

/// Like [`denied_literal_backend_ip_canonical`] but also screens the proxy's
/// `dns_override` literal. `dns_override` is always consumed as a canonical
/// `IpAddr` (`DnsCache::resolve` parses it with `IpAddr::parse`), so the
/// canonical screen matches its dial semantics exactly.
pub(crate) fn denied_literal_backend_or_dns_override_canonical(
    host: &str,
    proxy: &Proxy,
    policy: &crate::config::BackendEgressPolicy,
) -> Option<&'static str> {
    denied_literal_backend_ip_canonical(host, policy).or_else(|| {
        proxy
            .dns_override
            .as_deref()
            .and_then(|ovr| denied_literal_backend_ip_canonical(ovr, policy))
    })
}

/// Build the fail-closed `BackendResponse` for a literal-IP backend blocked by
/// the egress policy: a 502 that is NOT retried and is neutral to backend health
/// (the backend was never dialed), via `ErrorClass::DispatchPolicyRejected`.
fn backend_egress_denied_response(host: &str) -> retry::BackendResponse {
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(
            br#"{"error":"backend address blocked by egress policy"}"#.to_vec(),
        ),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: Some(host.to_string()),
        error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
    }
}

/// Dispatch-result wrapper around [`backend_egress_denied_response`] for the
/// first-attempt `proxy_to_backend` path.
fn backend_egress_denied_dispatch_result(host: &str) -> BackendDispatchResult {
    backend_dispatch_response(backend_egress_denied_response(host), None, None)
}

/// deterministic gateway 413, masking a client/gateway policy violation as
/// upstream pressure. The reqwest/direct-H2 paths already run their size checks
/// before admitting; this restores the same ordering. Returns the 413 dispatch
/// result when the declared Content-Length exceeds the limit, else `None`.
fn oversized_request_body_dispatch_reject(
    state: &ProxyState,
    method: &str,
    headers: &HashMap<String, String>,
    resolved_ip: Option<String>,
) -> Option<BackendDispatchResult> {
    if state.max_request_body_size_bytes > 0
        && request_may_have_body(method, headers)
        && let Some(content_length) = headers.get("content-length")
        && let Ok(len) = content_length.parse::<usize>()
        && len > state.max_request_body_size_bytes
    {
        return Some(backend_dispatch_response(
            retry::BackendResponse {
                status_code: 413,
                body: ResponseBody::Buffered(
                    r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
            },
            None,
            None,
        ));
    }
    None
}

#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    client_request_body: ClientRequestBody,
    upstream_target: Option<&UpstreamTarget>,
    plugins: &[Arc<dyn crate::plugins::Plugin>],
    backend_admission_plugins: &[Arc<dyn crate::plugins::Plugin>],
    mut preacquired_backend_admission: PreacquiredBackendAdmission,
    mut ctx: Option<&mut RequestContext>,
    // Real, read-only request context for the response-side buffering decision.
    // Distinct from `ctx` above, which is the request-body-hook clone and is
    // `None` unless request-body buffering is active.
    request_ctx: &RequestContext,
    stream_response: bool,
    requires_request_body_buffering: bool,
    stream_request_body: bool,
    retain_request_body: bool,
    request_body_prepared: bool,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    dispatch_hbone: bool,
    dispatch_mesh_mtls: bool,
    dispatch_h3: bool,
    // Shared counter for request body bytes observed on the wire. Populated
    // by the body handling block below via either `fetch_max` (buffered paths)
    // or frame-by-frame `fetch_add` (streaming paths via SizeLimitedIncoming /
    // CountingIncoming). Summary builders read the final value via
    // `ctx.bytes_sent_observed.load(Ordering::Acquire)` once the request
    // has completed.
    ctx_bytes_sent_observed: &Arc<std::sync::atomic::AtomicU64>,
    inbound_version: hyper::Version,
    // Out-parameter: reset immediately before the backend dial / send, after
    // admission permits are available. A narrow response-policy reevaluation
    // path may preacquire admission before body finalization to preserve
    // fail-fast rejection; its client-upload/body-hook time must still stay out
    // of the backend latency sample.
    // Left at its incoming value (the caller's `backend_start`) on paths that
    // never reach admission, so the fallback is the pre-fix behavior.
    backend_admission_started_at: &mut Instant,
) -> BackendDispatchResult {
    // Honor DestinationRule per-port `connect_timeout_ms` overrides for this
    // dispatch. Borrowed when no override applies (zero-alloc hot path);
    // cloned only when a port override differs from the proxy default.
    // Threading through `&Proxy` for the rest of this function means every
    // downstream call (reqwest, H2 pool, H3 pool, gRPC pool, HBONE) inherits
    // the effective timeout automatically.
    let effective_proxy = resolve_effective_proxy_for_target(proxy, upstream_target);
    let proxy: &Proxy = effective_proxy.as_ref();
    let backend_admission_permits: Option<BackendAdmissionPermitSet>;

    // Context for the response-side buffer->stream downgrade. Use the real
    // request context (not the request-body-hook clone). Retry-enabled requests
    // use a private marked clone so ordinary responses remain buffered while an
    // inherently streaming representation can be released only when every
    // active buffering plugin explicitly opts in.
    let retry_response_ctx = (retain_request_body
        && plugins_may_release_response_body_under_retries(plugins, request_ctx))
    .then(|| retry_response_decision_context(request_ctx));
    let response_decision_ctx = if retain_request_body {
        retry_response_ctx.as_ref()
    } else {
        Some(request_ctx)
    };

    // When retain_request_body is true (retries configured), the collected
    // body bytes are retained alongside the response so the caller can replay
    // them on connection-failure retries. `Bytes` is shared via Arc so the
    // retain-clone is a refcount bump, not a deep copy of the request body —
    // the previous `Option<Vec<u8>>` deep-copied the body on every request
    // with retry enabled, even when no retry actually fired. `Option<Bytes>`
    // still derefs to `Option<&[u8]>` via `as_deref`, so the retry
    // call sites in `proxy_to_backend_inner` are unchanged.
    let mut retained_body: Option<Bytes> = None;

    // All reqwest clients use our DnsCacheResolver, so DNS resolution is
    // always served from the warmed cache — never hitting DNS on the hot path.
    // For both single-backend and load-balanced proxies, the client transparently
    // resolves hostnames through the DNS cache.
    let effective_host = upstream_target
        .map(|t| t.host.as_str())
        .unwrap_or(&proxy.backend_host);

    // Enforce the backend egress policy for a literal-IP backend before dialing
    // (reqwest/pools skip the DnsCacheResolver for IP literals).
    if let Some(reason) = denied_literal_backend_or_dns_override(
        effective_host,
        proxy,
        &state.env_config.backend_allow_ips,
    ) {
        warn!(
            proxy_id = %proxy.id,
            backend = %effective_host,
            reason,
            "Backend egress policy denied literal-IP backend; not dialing"
        );
        return backend_egress_denied_dispatch_result(effective_host);
    }

    // Resolve backend IP from DNS cache (O(1) cached lookup, <1μs).
    // This is the same cache reqwest will use internally via DnsCacheResolver,
    // so the IP will match the actual connection target.
    let resolve_backend_ip = state.dns_cache.resolve(
        effective_host,
        proxy.dns_override.as_deref(),
        proxy.dns_cache_ttl_seconds,
    );
    let resolved_ip_result = if let Some(deadline) = request_ctx.grpc_deadline_at() {
        match tokio::time::timeout_at(deadline, resolve_backend_ip).await {
            Ok(result) => result,
            Err(_) => {
                return backend_dispatch_response(
                    client_grpc_deadline_exceeded_response_for_request(request_ctx, headers, None),
                    None,
                    None,
                );
            }
        }
    } else {
        resolve_backend_ip.await
    };
    let resolved_ip = resolved_ip_result.ok().map(|ip| ip.to_string());

    if dispatch_hbone {
        // 413 on an oversized declared Content-Length BEFORE admission, so a
        // capacity rejection cannot mask the size violation as a 503.
        if let Some(reject) =
            oversized_request_body_dispatch_reject(state, method, headers, resolved_ip.clone())
        {
            return reject;
        }
        backend_admission_permits = match preacquired_backend_admission.take_or_run(
            backend_admission_plugins,
            request_ctx,
            proxy,
            upstream_target,
            ProxyProtocol::Http,
        ) {
            Ok(permits) => permits,
            Err(rejection) => return BackendDispatchResult::AdmissionRejected(rejection),
        };
        *backend_admission_started_at = Instant::now();
        let (backend_resp, body_bytes, request_body_exceeded) = proxy_to_backend_hbone(
            state,
            proxy,
            backend_url,
            method,
            headers,
            client_request_body,
            upstream_target,
            plugins,
            Some(request_ctx),
            response_decision_ctx,
            stream_response,
            client_ip,
            xff_append_ip,
            request_is_secure,
            resolved_ip.clone(),
            ctx_bytes_sent_observed,
        )
        .await;
        return BackendDispatchResult::Response {
            response: Box::new(backend_resp),
            retained_body: body_bytes,
            backend_admission_permits,
            request_body_exceeded,
            streaming_h2_read_timeout_ms: Some(proxy.backend_read_timeout_ms),
        };
    }

    // Sidecar egress: plain HTTP/2 over SVID-mTLS to the peer sidecar's
    // inbound listener. Same admission ordering as the HBONE path.
    if dispatch_mesh_mtls {
        // Flavor-aware declared-Content-Length check BEFORE admission (same
        // ordering rationale as the HBONE branch above), codex r2-2 finding
        // 4: a gRPC-flavored request — native `application/grpc` or
        // `grpc_web`-translated; both are wire-native gRPC in the OUTBOUND
        // headers by dispatch time — is bounded ONLY by the gRPC receive
        // limit (`max_grpc_recv_size_bytes`), exactly like the direct gRPC
        // pool, which never applies `max_request_body_size_bytes`. Running
        // the generic HTTP check first would, when the HTTP limit is the
        // smaller of the two, reject an in-budget gRPC body early as an
        // HTTP/JSON 413 instead of admitting it (and an over-budget one with
        // the wrong shape). The gRPC reject shape is the direct pool's
        // Trailers-Only RESOURCE_EXHAUSTED with neutral
        // `ErrorClass::RequestBodyTooLarge`.
        let mesh_grpc_flavored = headers
            .get("content-type")
            .is_some_and(|ct| backend_dispatch::is_native_grpc_content_type(ct.as_bytes()));
        if mesh_grpc_flavored {
            let grpc_limit = grpc_proxy::mesh_request_body_limit(
                true,
                state.max_request_body_size_bytes,
                state.max_grpc_recv_size_bytes,
            );
            if grpc_limit > 0
                && request_may_have_body(method, headers)
                && let Some(content_length) = headers.get("content-length")
                && let Ok(len) = content_length.parse::<usize>()
                && len > grpc_limit
            {
                return backend_dispatch_response(
                    grpc_proxy::grpc_request_body_too_large_backend_response(
                        &proxy.id,
                        resolved_ip.clone(),
                        Some(len),
                        grpc_limit,
                    ),
                    None,
                    None,
                );
            }
        } else if let Some(reject) =
            oversized_request_body_dispatch_reject(state, method, headers, resolved_ip.clone())
        {
            return reject;
        }
        backend_admission_permits = match preacquired_backend_admission.take_or_run(
            backend_admission_plugins,
            request_ctx,
            proxy,
            upstream_target,
            ProxyProtocol::Http,
        ) {
            Ok(permits) => permits,
            Err(rejection) => return BackendDispatchResult::AdmissionRejected(rejection),
        };
        *backend_admission_started_at = Instant::now();
        let (backend_resp, body_bytes, request_body_exceeded) = proxy_to_backend_mesh_mtls(
            state,
            proxy,
            backend_url,
            method,
            headers,
            client_request_body,
            upstream_target,
            plugins,
            request_ctx,
            response_decision_ctx,
            stream_response,
            client_ip,
            xff_append_ip,
            request_is_secure,
            resolved_ip.clone(),
            ctx_bytes_sent_observed,
        )
        .await;
        return BackendDispatchResult::Response {
            response: Box::new(backend_resp),
            retained_body: body_bytes,
            backend_admission_permits,
            request_body_exceeded,
            streaming_h2_read_timeout_ms: Some(proxy.backend_read_timeout_ms),
        };
    }

    // Plain HTTPS requests attempt the native H3 pool only when startup
    // classification has already proved that this concrete backend target
    // supports H3. gRPC and WebSocket dispatch earlier in the handler and
    // never reach this block, so only Plain-flavor requests can enter.
    //
    // `dispatch_h3` is the caller-captured snapshot of
    // `supports_native_http3_backend` taken once at the start of the request.
    // Re-reading the registry here would race a concurrent
    // `mark_h3_unsupported` / refresh between the outer capture and the
    // async DNS resolve above, letting the first attempt and the retry loop
    // pick different transports.
    //
    // On H3 transport failure we downgrade the cached capability so
    // subsequent requests skip the native pool immediately — but we do NOT
    // cross protocols on the same request. The failed H3 attempt may
    // already have flushed headers / body to the backend before the reset,
    // timeout, or protocol error surfaced, so cross-protocol replay would
    // bypass the operator's `retry_on_methods` policy and could duplicate
    // non-idempotent requests. Same-protocol H3 retries do replay the
    // retained body — the outer retry loop's job — but only against the
    // H3 pool. Without retry, the 502 propagates to the client and the
    // NEXT request uses reqwest.
    if dispatch_h3 {
        // 413 on an oversized declared Content-Length BEFORE admission (same
        // ordering as the reqwest/direct-H2 paths), so a capacity rejection
        // cannot mask the size violation as a 503.
        if let Some(reject) =
            oversized_request_body_dispatch_reject(state, method, headers, resolved_ip.clone())
        {
            return reject;
        }
        backend_admission_permits = match preacquired_backend_admission.take_or_run(
            backend_admission_plugins,
            request_ctx,
            proxy,
            upstream_target,
            ProxyProtocol::Http,
        ) {
            Ok(permits) => permits,
            Err(rejection) => return BackendDispatchResult::AdmissionRejected(rejection),
        };
        *backend_admission_started_at = Instant::now();
        let (mut backend_resp, body_bytes) = proxy_to_backend_http3(
            state,
            proxy,
            backend_url,
            method,
            headers,
            client_request_body,
            plugins,
            ctx,
            request_ctx.grpc_deadline_at(),
            response_decision_ctx,
            upstream_target,
            client_ip,
            xff_append_ip,
            request_is_secure,
            inbound_version,
            stream_request_body,
            retain_request_body,
            request_body_prepared,
            stream_response,
            ctx_bytes_sent_observed,
        )
        .await;
        // For streaming H3 responses, move headers from the H3StreamingResponse
        // into the BackendResponse headers map (avoids cloning all key/value strings).
        if let ResponseBody::StreamingH3(ref mut h3_resp) = backend_resp.body {
            backend_resp.headers = std::mem::take(&mut h3_resp.headers);
        }
        // Merge resolved_ip into the response (h3 function resolves its own IP
        // but the outer resolved_ip is already computed from DNS cache above)
        let resp = retry::BackendResponse {
            backend_resolved_ip: resolved_ip.clone().or(backend_resp.backend_resolved_ip),
            ..backend_resp
        };

        if is_h3_transport_failure(&resp) {
            debug!(
                proxy_id = %proxy.id,
                error_class = ?resp.error_class,
                "H3 backend transport failed; downgrading cached capability so subsequent requests route via reqwest"
            );
            mark_h3_unsupported_for_backend_target(
                state.backend_capabilities.as_ref(),
                proxy,
                upstream_target,
            );
        }
        return backend_dispatch_response(resp, body_bytes, backend_admission_permits);
    }

    // Use the direct HTTP/2 pool only when the capability registry has already
    // classified this concrete backend target as H2-capable and the request
    // body path is compatible with the hyper sender.
    if proxy.dispatch_kind == DispatchKind::HttpsPool {
        let pool_config = state.connection_pool.global_pool_config().for_proxy(proxy);
        // Mirror the warmup path: the direct H2 pool must key and dial on the
        // load-balanced target, not the proxy's template backend_host/port.
        let direct_h2_effective_proxy =
            resolve_backend_connection_proxy_for_target(proxy, upstream_target);
        let direct_h2_proxy = direct_h2_effective_proxy.as_ref();
        let requires_direct_h2_for_sni = direct_h2_proxy.resolved_tls.sni.is_some();
        let direct_h2_capability = get_backend_capability_for_target(
            state.backend_capabilities.as_ref(),
            direct_h2_proxy,
            upstream_target,
        );
        let direct_h2_known_unsupported = direct_h2_capability
            .as_ref()
            .is_some_and(|record| matches!(record.plain_http.h2_tls, ProtocolSupport::Unsupported));
        let direct_h2_supports = direct_h2_capability
            .as_ref()
            .is_some_and(|record| record.plain_http.h2_tls.is_supported());
        let direct_h2_compatible = can_use_direct_http2_pool(
            pool_config.enable_http2,
            retain_request_body,
            requires_request_body_buffering,
        );
        // Backend TLS SNI cannot fall back to reqwest. Body-size limits are
        // enforced in-path on the direct-H2 sender / response collectors
        // (413 / 502), so nonzero FERRUM_MAX_*_BODY_SIZE_BYTES must not
        // disqualify SNI routes the way they do for ordinary H2 preference.
        let direct_h2_can_dispatch = if requires_direct_h2_for_sni {
            direct_h2_compatible
        } else {
            can_dispatch_direct_http2_pool(
                pool_config.enable_http2,
                retain_request_body,
                requires_request_body_buffering,
                state.max_request_body_size_bytes,
                state.max_response_body_size_bytes,
            )
        };
        // Fold the DestinationRule `connectionPool.http.h2UpgradePolicy` override
        // (projected onto the effective proxy) into the registry verdict. Scope
        // is strictly this plain-HTTPS h1-vs-h2 fork — gRPC (always H2) and
        // HBONE/mesh-mTLS transports never reach here. See
        // `should_dispatch_direct_h2` for the exact policy interaction.
        let direct_h2_dispatch = should_dispatch_direct_h2(
            direct_h2_can_dispatch,
            direct_h2_supports,
            direct_h2_known_unsupported,
            requires_direct_h2_for_sni,
            direct_h2_proxy.h2_upgrade_policy,
        );
        if requires_direct_h2_for_sni && direct_h2_known_unsupported {
            debug!(
                proxy_id = %proxy.id,
                backend_tls_sni = ?direct_h2_proxy.resolved_tls.sni,
                "H2 pool required for backend TLS SNI override but capability registry already marks this backend target H2/TLS unsupported"
            );
            return backend_dispatch_response(
                backend_tls_sni_requires_direct_h2_response(resolved_ip.clone()),
                None,
                None,
            );
        }
        if direct_h2_dispatch {
            // 413 on an oversized declared Content-Length BEFORE dial/admission,
            // matching HBONE/mesh-mTLS ordering so a capacity 503 cannot mask a
            // size violation — especially important for SNI routes that must
            // stay on direct-H2 under nonzero body limits.
            if let Some(reject) =
                oversized_request_body_dispatch_reject(state, method, headers, resolved_ip.clone())
            {
                return reject;
            }
            // Gate adaptive-concurrency admission BEFORE opening the H2 sender.
            // `get_sender()` can dial the backend, so admitting afterward would
            // let a capacity-rejected request still create a connection and
            // would hide get_sender connect failures from the limiter.
            let mut h2_admission_permits = match preacquired_backend_admission.take_or_run(
                backend_admission_plugins,
                request_ctx,
                proxy,
                upstream_target,
                ProxyProtocol::Http,
            ) {
                Ok(permits) => permits,
                Err(rejection) => return BackendDispatchResult::AdmissionRejected(rejection),
            };
            *backend_admission_started_at = Instant::now();
            let sender_result = crate::plugins::await_grpc_deadline(
                request_ctx.grpc_deadline_at(),
                state.http2_pool.get_sender(direct_h2_proxy),
            )
            .await;
            let direct_h2_sender = match sender_result {
                Err(()) => {
                    drop(h2_admission_permits.take());
                    return backend_dispatch_response(
                        client_grpc_deadline_exceeded_response_for_request(
                            request_ctx,
                            headers,
                            resolved_ip,
                        ),
                        None,
                        None,
                    );
                }
                Ok(Ok(sender)) => Some(sender),
                Ok(Err(e)) => {
                    if should_fallback_to_reqwest_after_http2_pool_error(&e) {
                        // The per-pool-key ALPN learning cache was removed
                        // when the capability registry took over classification,
                        // so without this the next request would repeat the
                        // direct-H2 handshake + ALPN-fallback cost until the
                        // 24 h refresh re-probes. Downgrade here so subsequent
                        // requests go straight to reqwest.
                        let downgraded = mark_h2_tls_unsupported_for_backend_target(
                            state.backend_capabilities.as_ref(),
                            direct_h2_proxy,
                            upstream_target,
                        );
                        if requires_direct_h2_for_sni {
                            if downgraded {
                                warn!(
                                    proxy_id = %proxy.id,
                                    error = %e,
                                    backend_tls_sni = ?direct_h2_proxy.resolved_tls.sni,
                                    "HTTP/2 pool negotiated HTTP/1.1 backend but backend TLS SNI override cannot fall back to reqwest; marking backend H2/TLS unsupported and returning 502"
                                );
                            } else {
                                debug!(
                                    proxy_id = %proxy.id,
                                    error = %e,
                                    backend_tls_sni = ?direct_h2_proxy.resolved_tls.sni,
                                    "HTTP/2 pool negotiated HTTP/1.1 backend but backend TLS SNI override cannot fall back to reqwest"
                                );
                            }
                            // SNI override cannot fall back to reqwest, so this
                            // request terminates at the H2 pool: record the pool
                            // failure so the adaptive limiter learns it.
                            record_h2_pool_admission_failure(
                                &mut h2_admission_permits,
                                backend_admission_started_at,
                                &e,
                            );
                            return backend_dispatch_response(
                                backend_tls_sni_requires_direct_h2_response(resolved_ip.clone()),
                                None,
                                None,
                            );
                        } else {
                            debug!(
                                proxy_id = %proxy.id,
                                error = %e,
                                "HTTP/2 pool negotiated HTTP/1.1 backend — downgrading cached capability and falling back to reqwest"
                            );
                            // ALPN negotiated H1 — a capability mismatch, not a
                            // backend failure. Leave `h2_admission_permits` to
                            // drop on fall-through so the reqwest path re-admits
                            // and records the real backend outcome there.
                            None
                        }
                    } else {
                        // A real pool/connect failure: train the adaptive limiter
                        // with the connect failure before returning the 502.
                        record_h2_pool_admission_failure(
                            &mut h2_admission_permits,
                            backend_admission_started_at,
                            &e,
                        );
                        return backend_dispatch_response(
                            http2_pool_sender_error_response(state, proxy, &e, resolved_ip.clone()),
                            None,
                            None,
                        );
                    }
                }
            };
            if let Some(sender) = direct_h2_sender {
                let request = match client_request_body {
                    ClientRequestBody::Streaming(request) => *request,
                    ClientRequestBody::Buffered(_) => {
                        debug_assert!(
                            false,
                            "direct HTTP/2 pool should not be used when request body is pre-buffered"
                        );
                        return backend_dispatch_response(
                            retry::BackendResponse {
                                status_code: 500,
                                body: ResponseBody::Buffered(
                                    r#"{"error":"Request buffering invariant violated"}"#
                                        .as_bytes()
                                        .to_vec(),
                                ),
                                headers: HashMap::new(),
                                connection_error: false,
                                backend_resolved_ip: resolved_ip,
                                error_class: None,
                            },
                            None,
                            None,
                        );
                    }
                };
                let (backend_resp, request_body_exceeded) = proxy_to_backend_http2(
                    state,
                    direct_h2_proxy,
                    sender,
                    backend_url,
                    method,
                    headers,
                    request,
                    plugins,
                    response_decision_ctx,
                    request_ctx.grpc_deadline_at(),
                    stream_response,
                    client_ip,
                    xff_append_ip,
                    request_is_secure,
                    resolved_ip,
                    ctx_bytes_sent_observed,
                )
                .await;
                return BackendDispatchResult::Response {
                    response: Box::new(backend_resp),
                    retained_body: None,
                    backend_admission_permits: h2_admission_permits.take(),
                    request_body_exceeded,
                    streaming_h2_read_timeout_ms: Some(proxy.backend_read_timeout_ms),
                };
            }
            // Fall through to the reqwest path: `h2_admission_permits` drops here,
            // releasing the in-flight slot so the reqwest path below re-admits
            // after its own request-body collection / final-body hooks.
        } else if direct_h2_compatible
            && !direct_h2_can_dispatch
            && (direct_h2_supports || requires_direct_h2_for_sni)
        {
            debug!(
                proxy_id = %proxy.id,
                max_request_body_size_bytes = state.max_request_body_size_bytes,
                max_response_body_size_bytes = state.max_response_body_size_bytes,
                "H2 pool bypassed because body-size limits are enabled"
            );
        }
        if requires_direct_h2_for_sni {
            warn!(
                proxy_id = %proxy.id,
                backend_tls_sni = ?direct_h2_proxy.resolved_tls.sni,
                retain_request_body = retain_request_body,
                requires_request_body_buffering = requires_request_body_buffering,
                enable_http2 = pool_config.enable_http2,
                "H2 pool required for backend TLS SNI override but request is not compatible with direct H2 dispatch"
            );
            return backend_dispatch_response(
                backend_tls_sni_requires_direct_h2_response(resolved_ip.clone()),
                None,
                None,
            );
        }
        if pool_config.enable_http2 && (retain_request_body || requires_request_body_buffering) {
            debug!(
                proxy_id = %proxy.id,
                retain_request_body = retain_request_body,
                requires_request_body_buffering = requires_request_body_buffering,
                "H2 pool bypassed for request buffering support — using reqwest (ALPN HTTP/2)"
            );
        }
    }

    // Get client from connection pool for HTTP/1.1 and HTTP/2.
    // The client uses our DnsCacheResolver for transparent DNS cache lookups.
    // All upstream targets share one reqwest::Client since it handles
    // per-host pooling and SNI internally.
    //
    // Force-H1 (`h2UpgradePolicy: DO_NOT_UPGRADE`) reaches this reqwest fallback
    // too: `proxy` here is the EFFECTIVE proxy (rebound at function entry via
    // `resolve_effective_proxy_for_target`, which projects per-port
    // `h2_upgrade_policy`), so when DO_NOT_UPGRADE applies — top-level or
    // port-level — `proxy.forces_backend_http1_only()` is true and `get_client`
    // builds the `h1`-discriminated, ALPN-`http/1.1`-restricted client (see
    // `ConnectionPool` pool-key + `BackendTlsConfigBuilder::build_reqwest`).
    // The direct-H2 block above uses `direct_h2_proxy` only to skip the H2 pool;
    // the force-H1 ALPN/pool-key guarantee on this path rides this rebind, so a
    // first/non-retry request cannot ALPN-negotiate h2 despite DO_NOT_UPGRADE.
    // `proxy_to_backend_retry` rebinds identically for the retry path.
    let client_result = crate::plugins::await_grpc_deadline(
        request_ctx.grpc_deadline_at(),
        state.connection_pool.get_client(proxy),
    )
    .await;
    let client = match client_result {
        Err(()) => {
            return backend_dispatch_response(
                client_grpc_deadline_exceeded_response_for_request(
                    request_ctx,
                    headers,
                    resolved_ip,
                ),
                None,
                None,
            );
        }
        Ok(Ok(client)) => client,
        Ok(Err(e)) => {
            error!(
                proxy_id = %proxy.id,
                listen_path = ?proxy.listen_path,
                "Connection pool client creation failed — refusing to proxy without proper TLS configuration: {}",
                e
            );
            return backend_dispatch_response(
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(r#"{"error":"Bad Gateway"}"#.as_bytes().to_vec()),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip.clone(),
                    error_class: Some(retry::ErrorClass::ConnectionPoolError),
                },
                None,
                None,
            );
        }
    };

    let req_method = match parse_reqwest_method(method) {
        Ok(m) => m,
        Err(()) => {
            warn!("Invalid HTTP method: {}", method);
            return backend_dispatch_response(
                retry::BackendResponse {
                    status_code: 405,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Method Not Allowed"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip.clone(),
                    error_class: None,
                },
                None,
                None,
            );
        }
    };

    let mut req_builder = client.request(req_method, backend_url);

    // Per-request timeout overrides. The shared `reqwest::Client` intentionally
    // has no client-level connect or read timeout (see
    // `connection_pool::create_client`) so two proxies with different timeouts
    // sharing the same pool entry do not leak policy across routes. `0` means
    // "disabled" for both — skip the override so reqwest's default (no timeout)
    // applies. The per-request `connect_timeout` API is provided by a vendored
    // copy of reqwest patched with seanmonstar/reqwest#3017.
    // Keep the timeout source typed; see the retry-path companion above.
    let client_deadline_remaining = if let Some(deadline) = request_ctx.grpc_deadline_at() {
        let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
        if remaining.is_zero() {
            return backend_dispatch_response(
                client_grpc_deadline_exceeded_response_for_request(
                    request_ctx,
                    headers,
                    resolved_ip,
                ),
                retained_body,
                None,
            );
        }
        Some(remaining)
    } else {
        None
    };
    if proxy.backend_connect_timeout_ms > 0 {
        let operator_timeout = Duration::from_millis(proxy.backend_connect_timeout_ms);
        if client_deadline_remaining.is_none_or(|remaining| operator_timeout < remaining) {
            req_builder = req_builder.connect_timeout(operator_timeout);
        }
    }
    if proxy.backend_read_timeout_ms > 0 {
        let operator_timeout = Duration::from_millis(proxy.backend_read_timeout_ms);
        if client_deadline_remaining.is_none_or(|remaining| operator_timeout < remaining) {
            req_builder = req_builder.timeout(operator_timeout);
        }
    }

    // Forward headers, stripping hop-by-hop headers per RFC 9110 §7.6.1
    // (canonical predicate in `proxy::headers`). Also strip every header
    // NAMED in the request's `Connection` field.
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (k, v) in headers {
        match k.as_str() {
            "host" => {
                if proxy.preserve_host_header {
                    req_builder = req_builder.header("Host", v.as_str());
                } else {
                    // Use upstream target host when load balancing, so SNI-based
                    // ingress routers see the correct Host header for the target.
                    req_builder = req_builder.header("Host", effective_host);
                }
            }
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            _ => {
                req_builder = req_builder.header(k.as_str(), v.as_str());
            }
        }
    }

    // Add proxy-managed forwarding metadata.
    let xff_val = build_xff_value(
        headers.get("x-forwarded-for").map(|s| s.as_str()),
        client_ip,
        xff_append_ip,
        &state.trusted_proxies,
    );
    let proto_str = if request_is_secure { "https" } else { "http" };
    req_builder = req_builder.header("X-Forwarded-For", xff_val);
    req_builder = req_builder.header("X-Forwarded-Proto", proto_str);
    if let Some(host) = headers.get("host") {
        req_builder = req_builder.header("X-Forwarded-Host", host.as_str());
    }
    let via = via_header_for_inbound_version(state, inbound_version);
    if let Some(via) = via {
        req_builder = req_builder.header("Via", via.as_str());
    }
    if state.add_forwarded_header {
        req_builder = req_builder.header(
            "Forwarded",
            build_forwarded_value(
                client_ip,
                proto_str,
                headers.get("host").map(|s| s.as_str()),
            ),
        );
    }

    let has_body = request_may_have_body(method, headers);

    // Shared flag for detecting size-limit exceeded during streaming.
    // Only allocated when we actually stream a request body.
    let body_size_exceeded = Arc::new(std::sync::atomic::AtomicBool::new(false));

    if has_body {
        // Enforce request body size limit via Content-Length fast path
        if state.max_request_body_size_bytes > 0
            && let Some(content_length) = headers.get("content-length")
            && let Ok(len) = content_length.parse::<usize>()
            && len > state.max_request_body_size_bytes
        {
            return backend_dispatch_response(
                retry::BackendResponse {
                    status_code: 413,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip.clone(),
                    error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                },
                None,
                None,
            );
        }

        match client_request_body {
            ClientRequestBody::Buffered(buffered) => {
                // Record pre-transform body length (bytes as received from the
                // client — already buffered by an earlier phase such as
                // request_mirror prebuffering) BEFORE running plugin transforms
                // or final-body hooks. Recording here rather than after the
                // hooks ensures:
                //   1. Consistency with the Streaming-then-buffered, gRPC, and
                //      HTTP/3 paths, which all record pre-transform bytes.
                //   2. Rejections from `run_final_request_body_hooks` still
                //      surface the original on-wire size in the log summary.
                // `fetch_max` preserves the largest observed value across
                // retries where plugin transforms may shrink the body. The
                // pre-dispatch finalization path already recorded the raw
                // client length before replacing this buffer with transformed
                // bytes, so do not let an expanding transform overwrite that
                // on-wire count here.
                if !request_body_prepared {
                    ctx_bytes_sent_observed.fetch_max(
                        buffered.body.len() as u64,
                        std::sync::atomic::Ordering::Release,
                    );
                }
                let body_bytes = if request_body_prepared {
                    buffered.body
                } else {
                    let body_bytes = apply_request_body_plugins_with_context(
                        plugins,
                        ctx.as_deref_mut(),
                        request_ctx.grpc_deadline_at(),
                        headers,
                        buffered.body,
                    )
                    .await;
                    match run_final_request_body_hooks(
                        plugins,
                        ctx,
                        request_ctx.grpc_deadline_at(),
                        headers,
                        &body_bytes,
                    )
                    .await
                    {
                        PluginResult::Continue => {}
                        reject @ PluginResult::Reject { .. }
                        | reject @ PluginResult::RejectBinary { .. } => {
                            return backend_dispatch_response(
                                reject_result_to_backend_response(reject, resolved_ip.clone()),
                                None,
                                None,
                            );
                        }
                    }
                    body_bytes
                };
                if !body_bytes.is_empty() {
                    // `Bytes::from(Vec<u8>)` is zero-cost (transfers ownership of
                    // the Vec without copying). The optional clone below is then
                    // a refcount bump, not a deep copy.
                    let body_bytes = Bytes::from(body_bytes);
                    if retain_request_body {
                        retained_body = Some(body_bytes.clone());
                    }
                    req_builder = req_builder.body(body_bytes);
                }
            }
            ClientRequestBody::Streaming(original_req) if stream_request_body => {
                // Stream the request body directly to the backend without collecting
                // into memory. Size limit is enforced during streaming via
                // SizeLimitedIncoming which sets body_size_exceeded on overflow.
                // Pass `ctx_bytes_sent_observed` as the shared counter so the
                // body adapter writes byte counts directly into the context that
                // summary builders read — no separate handle-capture needed.
                let incoming = (*original_req).into_body();
                if state.max_request_body_size_bytes > 0 {
                    let limited = body::SizeLimitedIncoming::new_with_counter(
                        incoming,
                        state.max_request_body_size_bytes,
                        Arc::clone(&body_size_exceeded),
                        Arc::clone(ctx_bytes_sent_observed),
                    );
                    req_builder = req_builder.body(limited.into_reqwest_body());
                } else {
                    // No size limit — stream body directly. Wrap in
                    // `CountingIncoming` so we still count bytes forwarded to
                    // the backend while preserving the size_hint behavior for
                    // Content-Length forwarding (avoids chunked encoding when
                    // the client sent a known length).
                    let counting = body::CountingIncoming::new_with_counter(
                        incoming,
                        Arc::clone(ctx_bytes_sent_observed),
                    );
                    req_builder = req_builder.body(counting.into_reqwest_body());
                }
            }
            ClientRequestBody::Streaming(original_req) => {
                // Buffered path: collect body into memory for plugin transformation.
                // Pre-transform length is recorded below after collect completes.
                let body_bytes = if state.max_request_body_size_bytes > 0 {
                    let limited = http_body_util::Limited::new(
                        (*original_req).into_body(),
                        state.max_request_body_size_bytes,
                    );
                    match collect_request_body_with_deadline(
                        limited.collect(),
                        request_ctx.grpc_deadline_at(),
                        proxy.backend_read_timeout_ms,
                    )
                    .await
                    {
                        Ok(Ok(collected)) => collected.to_bytes().to_vec(),
                        Ok(Err(_)) => {
                            return backend_dispatch_response(
                                retry::BackendResponse {
                                    status_code: 413,
                                    body:
                                        ResponseBody::Buffered(
                                            r#"{"error":"Request body exceeds maximum size"}"#
                                                .as_bytes()
                                                .to_vec(),
                                        ),
                                    headers: HashMap::new(),
                                    connection_error: false,
                                    backend_resolved_ip: resolved_ip.clone(),
                                    error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                                },
                                None,
                                None,
                            );
                        }
                        Err(RequestBodyWaitError::DeadlineExceeded) => {
                            let response = client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip.clone(),
                            );
                            return backend_dispatch_response(response, None, None);
                        }
                        Err(RequestBodyWaitError::TimedOut) => {
                            let response =
                                request_body_timeout_backend_response(resolved_ip.clone());
                            return backend_dispatch_response(response, None, None);
                        }
                    }
                } else {
                    match collect_request_body_with_deadline(
                        (*original_req).into_body().collect(),
                        request_ctx.grpc_deadline_at(),
                        proxy.backend_read_timeout_ms,
                    )
                    .await
                    {
                        Ok(Ok(collected)) => collected.to_bytes().to_vec(),
                        Ok(Err(e)) => {
                            error!(
                                proxy_id = %proxy.id,
                                backend_url = %strip_query_params(backend_url),
                                error_kind = "client_disconnect",
                                error = %e,
                                "Client disconnected while sending request body"
                            );
                            return backend_dispatch_response(
                                retry::BackendResponse {
                                    status_code: 499,
                                    body: ResponseBody::Buffered(
                                        r#"{"error":"Client disconnected"}"#.as_bytes().to_vec(),
                                    ),
                                    headers: HashMap::new(),
                                    connection_error: false,
                                    backend_resolved_ip: resolved_ip.clone(),
                                    error_class: Some(retry::ErrorClass::ClientDisconnect),
                                },
                                None,
                                None,
                            );
                        }
                        Err(RequestBodyWaitError::DeadlineExceeded) => {
                            let response = client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip.clone(),
                            );
                            return backend_dispatch_response(response, None, None);
                        }
                        Err(RequestBodyWaitError::TimedOut) => {
                            let response =
                                request_body_timeout_backend_response(resolved_ip.clone());
                            return backend_dispatch_response(response, None, None);
                        }
                    }
                };

                // Record pre-transform body length (bytes actually received
                // from the client) for summary. Use fetch_max so retries that
                // shrink the body via plugin transforms don't lower the count.
                ctx_bytes_sent_observed.fetch_max(
                    body_bytes.len() as u64,
                    std::sync::atomic::Ordering::Release,
                );

                // Transform request body via plugins (JSON field rename, add, remove, etc.)
                let body_bytes = apply_request_body_plugins_with_context(
                    plugins,
                    ctx.as_deref_mut(),
                    request_ctx.grpc_deadline_at(),
                    headers,
                    body_bytes,
                )
                .await;
                match run_final_request_body_hooks(
                    plugins,
                    ctx,
                    request_ctx.grpc_deadline_at(),
                    headers,
                    &body_bytes,
                )
                .await
                {
                    PluginResult::Continue => {}
                    reject @ PluginResult::Reject { .. }
                    | reject @ PluginResult::RejectBinary { .. } => {
                        return backend_dispatch_response(
                            reject_result_to_backend_response(reject, resolved_ip.clone()),
                            None,
                            None,
                        );
                    }
                }

                if !body_bytes.is_empty() {
                    let body_bytes = Bytes::from(body_bytes);
                    if retain_request_body {
                        retained_body = Some(body_bytes.clone());
                    }
                    req_builder = req_builder.body(body_bytes);
                }
            }
        }
    }

    // DestinationRule `connectionPool.http.http1MaxPendingRequests`: bound the
    // number of concurrent in-flight HTTP/1.1 requests to this backend
    // destination on the reqwest/HTTP-1.1 dispatch path (in-flight
    // reinterpretation — see the detailed note below and `docs/mesh.md`). The
    // slot is acquired here, AFTER local 413 / plugin rejections and
    // request-body collection / final-body hooks, immediately before backend
    // admission and the dispatch onto the shared reqwest client.
    //
    // Released the moment `send().await` returns (see the explicit `drop` below)
    // — BEFORE any response-body collection — so the slot spans dispatch →
    // response-headers (the in-flight window reqwest exposes), NOT the
    // response-stream / response-buffering lifetime. When the destination is at
    // its in-flight cap the request is shed with a 503 ("upstream overflow"),
    // NOT queued unboundedly.
    //
    // HTTP/1.1-scoped: the direct-H2 / gRPC / H3 / HBONE / mesh-mTLS branches
    // above already returned before reaching here, so the multiplexed transports
    // never consult this gate. The reqwest fallback ALSO negotiates ALPN HTTP/2
    // when the direct-H2 pool is bypassed for a buffered/retained body
    // (`enable_http2 && (retain_request_body || requires_request_body_buffering)`);
    // an H2 backend must not be capped by an `http1*` knob, so the slot is taken
    // only when the reqwest client is forced/known HTTP/1.1
    // (`reqwest_dispatch_is_http1_only`). Their concurrency is instead governed
    // by `http2MaxRequests` → `h2_max_concurrent_streams`.
    //
    // In-flight reinterpretation (codex r3, finding 3): reqwest's `send()`
    // resolves when RESPONSE HEADERS arrive, not when a connection slot is
    // assigned, and reqwest exposes no connection-acquisition hook — so a slot
    // held acquire-before-send / release-after-send inevitably spans
    // connection-wait + upload + backend-TTFB. We therefore CANNOT implement
    // Envoy's true pending-queue depth over reqwest. Mirroring how this repo
    // honestly reinterprets DR `maxRetries` as a per-request cap, the knob is
    // reframed as a **max concurrent in-flight HTTP/1.1 requests per
    // `(host, policy-port)`** cap (measured dispatch → response-headers), shedding
    // excess with a 503 ("upstream overflow"). Under that framing a streamed
    // upload IS legitimately in-flight, so there is NO body-shape exclusion —
    // bodyless GET/HEAD/OPTIONS (where `stream_request_body` is true) are capped
    // too, which is the most common H1 traffic. The connection-failure retry
    // path (`proxy_to_backend_retry`) re-enters this same gate per attempt (see
    // its own acquire); the initial slot is already released before the retry
    // loop runs, so an attempt and its retry never double-count.
    let pending_dial_port = upstream_target
        .map(|t| t.port)
        .unwrap_or(proxy.backend_port);
    let pending_policy_port = upstream_target
        .map(UpstreamTarget::dispatch_policy_port)
        .unwrap_or(proxy.backend_port);
    let pending_cap = resolve_backend_http1_max_pending_requests(proxy, pending_policy_port)
        // Only an HTTP/1.1-determined reqwest dispatch consults the gate; a
        // reqwest fallback that may ALPN-negotiate h2 ignores the `http1*` cap.
        .filter(|_| reqwest_dispatch_is_http1_only(state, proxy, upstream_target));
    let pending_slot = match state.backend_pending_limit.try_acquire(
        effective_host,
        pending_policy_port,
        pending_cap,
    ) {
        Ok(slot) => slot,
        Err(limit) => {
            warn!(
                proxy_id = %proxy.id,
                backend_host = %effective_host,
                backend_port = pending_dial_port,
                pending_requests = limit.current,
                max_pending_requests = limit.cap,
                "Shedding HTTP/1.1 request: DestinationRule http1MaxPendingRequests reached for backend (upstream overflow)"
            );
            return backend_dispatch_response(
                retry::BackendResponse {
                    status_code: 503,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Upstream pending request queue full"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    // Gateway-side capacity shed before any backend dial: the
                    // request never reached the backend application layer, so it
                    // is classified `DispatchPolicyRejected` (NOT a transport
                    // connection_error). That class is now a no-backend-signal
                    // (`client_side_no_backend_signal`), so this overflow 503 is
                    // NEUTRAL to backend health: it is not retried, does not trip
                    // the backend circuit breaker / passive health, and does not
                    // shrink the adaptive-concurrency permit for a backend that
                    // was never dialed — mirrors the backend-TLS-SNI gateway
                    // reject above.
                    connection_error: false,
                    backend_resolved_ip: resolved_ip.clone(),
                    error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
                },
                None,
                None,
            );
        }
    };

    backend_admission_permits = match preacquired_backend_admission.take_or_run(
        backend_admission_plugins,
        request_ctx,
        proxy,
        upstream_target,
        ProxyProtocol::Http,
    ) {
        Ok(permits) => permits,
        Err(rejection) => return BackendDispatchResult::AdmissionRejected(rejection),
    };
    // Ordinary requests acquire admission here after request-body collection
    // and final-body hooks. The narrow post-transform policy path consumes its
    // preacquired result here instead; either way, reset the timer now so the
    // adaptive sample measures only the backend interaction.
    *backend_admission_started_at = Instant::now();

    // Send
    let mut reqwest_backend_guard =
        Some(crate::runtime_metrics::global_ref().reqwest_backend_request_guard());
    let send_result = match crate::plugins::await_grpc_deadline(
        request_ctx.grpc_deadline_at(),
        req_builder.send(),
    )
    .await
    {
        Ok(result) => result,
        Err(()) => {
            return backend_dispatch_response(
                client_grpc_deadline_exceeded_response_for_request(
                    request_ctx,
                    headers,
                    resolved_ip,
                ),
                retained_body,
                backend_admission_permits,
            );
        }
    };
    // Release the in-flight slot the instant `send()` resolves — i.e. when
    // RESPONSE HEADERS arrive (or the dial failed). This is the only join point
    // reqwest exposes, so under the in-flight reinterpretation it IS the correct
    // release point by definition (codex r3, finding 3): the slot spans dispatch
    // → response-headers. Dropping here — before response-body collection /
    // eager buffering / response-inspection — keeps the slot off the
    // response-streaming lifetime. RAII covers all the early returns ABOVE this
    // point (admission reject); this explicit drop covers the response-handling
    // tail BELOW it. A no-cap / non-HTTP-1.1 dispatch holds `None`, so it no-ops.
    drop(pending_slot);
    let response = match send_result {
        Ok(response) => {
            // A streaming request body that overran `max_request_body_size_bytes`
            // is authoritative regardless of how the send/receive race resolved.
            // `SizeLimitedIncoming` forwards bytes up to the limit before it
            // errors, so a truncated request can reach the backend; under HTTP/1
            // full-duplex (and especially under CPU contention on loaded CI
            // runners) the backend can answer that truncated request — or the
            // poisoned connection can surface a malformed/oversized response —
            // before the body error propagates, making `send()` return `Ok`
            // instead of `Err`. Without this guard the `Ok` arm would process
            // that backend-derived response and could return the backend's
            // status (or a 502 from the response-size path) instead of the
            // contractual 413. Mirror the `Err`-branch check so the outcome is
            // deterministic across both arms of the race.
            if body_size_exceeded.load(Ordering::Acquire) {
                warn!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    max_body_size = state.max_request_body_size_bytes,
                    backend_status = response.status().as_u16(),
                    "Streaming request body exceeded maximum size (backend responded before body error surfaced)"
                );
                return backend_dispatch_response(
                    retry::BackendResponse {
                        status_code: 413,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                    },
                    retained_body,
                    backend_admission_permits,
                );
            }

            let status = response.status().as_u16();
            let mut resp_headers = HashMap::with_capacity(response.headers().keys_len());
            collect_response_headers(response.headers(), &mut resp_headers);

            // The pre-flight buffering decision could not see the response
            // content-type. Now that headers are known, downgrade buffer ->
            // stream for a response no plugin will inspect at this content-type
            // (e.g. binary downloads under `waf` response inspection), so we do
            // not collect a body that would be discarded unscanned.
            let stream_response = refine_stream_response_for_content_type(
                stream_response,
                proxy,
                plugins,
                response_decision_ctx,
                status,
                &resp_headers,
            );

            // Enforce response body size limit
            if state.max_response_body_size_bytes > 0 {
                // Fast path: check Content-Length header from backend
                let content_length = response
                    .headers()
                    .get("content-length")
                    .and_then(|v| v.to_str().ok())
                    .and_then(|v| v.parse::<usize>().ok());

                if let Some(len) = content_length
                    && len > state.max_response_body_size_bytes
                {
                    warn!(
                        "Backend response body ({} bytes) exceeds limit ({} bytes)",
                        len, state.max_response_body_size_bytes
                    );
                    return backend_dispatch_response(
                        retry::BackendResponse {
                            status_code: 502,
                            body: ResponseBody::Buffered(
                                r#"{"error":"Backend response body exceeds maximum size"}"#
                                    .as_bytes()
                                    .to_vec(),
                            ),
                            headers: HashMap::new(),
                            connection_error: false,
                            backend_resolved_ip: resolved_ip.clone(),
                            error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                        },
                        retained_body,
                        backend_admission_permits,
                    );
                }

                // When streaming is requested and Content-Length is present and within
                // limits, we can stream. Buffer small bodies eagerly (cheaper than
                // async coalescing). Skip buffering for SSE (unbounded streams).
                if stream_response && content_length.is_some() {
                    let cutoff = state.response_buffer_cutoff_bytes;
                    if cutoff > 0
                        && content_length.is_some_and(|cl| cl <= cutoff)
                        && !is_streaming_content_type(&resp_headers)
                    {
                        let body_read = match crate::plugins::await_grpc_deadline(
                            request_ctx.grpc_deadline_at(),
                            response.bytes(),
                        )
                        .await
                        {
                            Ok(result) => result,
                            Err(()) => {
                                return backend_dispatch_response(
                                    client_grpc_deadline_exceeded_response_for_request(
                                        request_ctx,
                                        headers,
                                        resolved_ip.clone(),
                                    ),
                                    retained_body,
                                    backend_admission_permits,
                                );
                            }
                        };
                        return backend_dispatch_response(
                            buffered_backend_response_from_body_read(
                                body_read,
                                status,
                                resp_headers,
                                resolved_ip.clone(),
                            ),
                            retained_body,
                            backend_admission_permits,
                        );
                    }
                    return backend_dispatch_response(
                        retry::BackendResponse {
                            status_code: status,
                            body: ResponseBody::Streaming {
                                response,
                                reqwest_backend_guard: reqwest_backend_guard.take(),
                            },
                            headers: resp_headers,
                            connection_error: false,
                            backend_resolved_ip: resolved_ip.clone(),
                            error_class: None,
                        },
                        retained_body,
                        backend_admission_permits,
                    );
                }

                // No Content-Length — stream with coalescing. The response size
                // limit is still enforced via the `SizeLimitedStreamingResponse`
                // adapter applied at the response body builder stage.
                if stream_response {
                    return backend_dispatch_response(
                        retry::BackendResponse {
                            status_code: status,
                            body: ResponseBody::Streaming {
                                response,
                                reqwest_backend_guard: reqwest_backend_guard.take(),
                            },
                            headers: resp_headers,
                            connection_error: false,
                            backend_resolved_ip: resolved_ip.clone(),
                            error_class: None,
                        },
                        retained_body,
                        backend_admission_permits,
                    );
                }

                // Buffered mode: stream-collect with size limit
                let max_size = state.max_response_body_size_bytes;
                let collected = match crate::plugins::await_grpc_deadline(
                    request_ctx.grpc_deadline_at(),
                    collect_response_with_limit(response, max_size),
                )
                .await
                {
                    Ok(result) => result,
                    Err(()) => {
                        return backend_dispatch_response(
                            client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip.clone(),
                            ),
                            retained_body,
                            backend_admission_permits,
                        );
                    }
                };
                match collected {
                    Ok((resp_body, _)) => retry::BackendResponse {
                        status_code: status,
                        body: ResponseBody::Buffered(resp_body),
                        headers: resp_headers,
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: None,
                    },
                    Err(err_body) => retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(err_body),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                    },
                }
            } else if stream_response {
                // No size limit — stream directly. Buffer small bodies eagerly
                // when Content-Length is known and below the cutoff (cheaper than
                // async coalescing). Skip buffering for SSE (unbounded streams).
                let content_length = response
                    .headers()
                    .get("content-length")
                    .and_then(|v| v.to_str().ok())
                    .and_then(|v| v.parse::<usize>().ok());
                let cutoff = state.response_buffer_cutoff_bytes;
                if cutoff > 0
                    && content_length.is_some_and(|cl| cl <= cutoff)
                    && !is_streaming_content_type(&resp_headers)
                {
                    let body_read = match crate::plugins::await_grpc_deadline(
                        request_ctx.grpc_deadline_at(),
                        response.bytes(),
                    )
                    .await
                    {
                        Ok(result) => result,
                        Err(()) => {
                            return backend_dispatch_response(
                                client_grpc_deadline_exceeded_response_for_request(
                                    request_ctx,
                                    headers,
                                    resolved_ip.clone(),
                                ),
                                retained_body,
                                backend_admission_permits,
                            );
                        }
                    };
                    buffered_backend_response_from_body_read(
                        body_read,
                        status,
                        resp_headers,
                        resolved_ip.clone(),
                    )
                } else {
                    retry::BackendResponse {
                        status_code: status,
                        body: ResponseBody::Streaming {
                            response,
                            reqwest_backend_guard: reqwest_backend_guard.take(),
                        },
                        headers: resp_headers,
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: None,
                    }
                }
            } else {
                let body_read = match crate::plugins::await_grpc_deadline(
                    request_ctx.grpc_deadline_at(),
                    response.bytes(),
                )
                .await
                {
                    Ok(result) => result,
                    Err(()) => {
                        return backend_dispatch_response(
                            client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip.clone(),
                            ),
                            retained_body,
                            backend_admission_permits,
                        );
                    }
                };
                buffered_backend_response_from_body_read(
                    body_read,
                    status,
                    resp_headers,
                    resolved_ip.clone(),
                )
            }
        }
        Err(e) => {
            // Check if the error was caused by the streaming body exceeding
            // the size limit. If so, return 413 instead of generic 502.
            if body_size_exceeded.load(Ordering::Acquire) {
                warn!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    max_body_size = state.max_request_body_size_bytes,
                    "Streaming request body exceeded maximum size"
                );
                return backend_dispatch_response(
                    retry::BackendResponse {
                        status_code: 413,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip.clone(),
                        error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                    },
                    retained_body,
                    backend_admission_permits,
                );
            }

            let error_class = retry::classify_reqwest_error(&e);
            if error_class == retry::ErrorClass::PortExhaustion {
                state.overload.record_port_exhaustion();
            }
            // Drive `error_kind` and `connection_error` from the same
            // `ErrorClass` rather than re-deriving them from
            // `e.is_connect()` / `e.is_timeout()`. The reqwest predicates
            // miss TLS-handshake failures, DNS lookup errors that don't
            // surface as `is_connect()` (e.g. cached failures), and port
            // exhaustion — every transport-class failure must funnel
            // through `retry::request_reached_wire` so
            // `retry_on_connect_failure` fires consistently across reqwest,
            // direct H2, gRPC, and H3 paths.
            let error_kind = retry::error_class_log_kind(error_class);
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                error_kind = error_kind,
                error = %e,
                "Backend request failed"
            );
            let error_body = r#"{"error":"Backend unavailable"}"#;
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(error_body.as_bytes().to_vec()),
                headers: HashMap::new(),
                connection_error: !retry::request_reached_wire(error_class),
                backend_resolved_ip: resolved_ip.clone(),
                error_class: Some(error_class),
            }
        }
    };

    backend_dispatch_response(response, retained_body, backend_admission_permits)
}

/// Returns `true` for response content types that represent inherently unbounded
/// or latency-sensitive streams and should never be eagerly buffered regardless
/// of Content-Length. Currently covers SSE (`text/event-stream`).
#[inline]
fn is_streaming_content_type(resp_headers: &HashMap<String, String>) -> bool {
    resp_headers.get("content-type").is_some_and(|ct| {
        ct.len() >= 17 && ct.as_bytes()[..17].eq_ignore_ascii_case(b"text/event-stream")
    })
}

/// Collect a response body with a size limit, returning Err with error body if exceeded.
async fn collect_response_with_limit(
    response: reqwest::Response,
    max_size: usize,
) -> Result<(Vec<u8>, usize), Vec<u8>> {
    use futures_util::StreamExt as _;
    let mut body = Vec::new();
    let mut stream = response.bytes_stream();
    while let Some(chunk_result) = stream.next().await {
        match chunk_result {
            Ok(chunk) => {
                if body.len() + chunk.len() > max_size {
                    warn!(
                        "Backend response truncated: exceeded {} byte limit",
                        max_size
                    );
                    return Err(r#"{"error":"Backend response body exceeds maximum size"}"#
                        .as_bytes()
                        .to_vec());
                }
                body.extend_from_slice(&chunk);
            }
            Err(e) => {
                error!("Error reading backend response: {}", e);
                return Err(r#"{"error":"Backend response read error"}"#.as_bytes().to_vec());
            }
        }
    }
    let len = body.len();
    Ok((body, len))
}

/// Build a `Set-Cookie` header value for sticky session cookie injection.
///
/// The cookie value is a SHA-256 hash of the backend `host:port`, not the
/// raw address itself. This prevents leaking internal backend topology to
/// clients while remaining deterministic across gateway instances and
/// restarts (no keyed HMAC, no per-process state).
pub(crate) fn build_sticky_cookie_header(
    cookie_name: &str,
    target: &UpstreamTarget,
    config: &crate::config::types::HashOnCookieConfig,
) -> String {
    use crate::load_balancer::target_host_port_key;
    use sha2::{Digest, Sha256};

    let raw = target_host_port_key(target);
    let value = hex::encode(Sha256::digest(raw.as_bytes()));
    let mut cookie = format!(
        "{}={}; Path={}; Max-Age={}",
        cookie_name, value, config.path, config.ttl_seconds
    );
    if config.http_only {
        cookie.push_str("; HttpOnly");
    }
    if config.secure {
        cookie.push_str("; Secure");
    }
    if let Some(ref domain) = config.domain {
        cookie.push_str("; Domain=");
        cookie.push_str(domain);
    }
    if let Some(ref same_site) = config.same_site {
        cookie.push_str("; SameSite=");
        cookie.push_str(same_site);
    }
    cookie
}

pub(crate) fn strip_query_params(url: &str) -> &str {
    url.split('?').next().unwrap_or(url)
}

/// Count query parameters for global request validation.
///
/// Empty segments produced by duplicate or leading/trailing ampersands are not
/// parameters and must not make otherwise equivalent H1/H2/H3 requests diverge.
pub(crate) fn count_query_params(query_string: &str) -> usize {
    query_string.split('&').filter(|s| !s.is_empty()).count()
}

pub(crate) fn query_string_after_plugin_strips<'a>(
    ctx: &RequestContext,
    query_string: &'a str,
) -> Cow<'a, str> {
    if query_string.is_empty() {
        return Cow::Borrowed(query_string);
    }

    let strip_names: HashSet<&str> = ctx
        .metadata
        .keys()
        .filter_map(|key| {
            key.strip_prefix(
                crate::plugins::utils::token_extract::STRIP_QUERY_PARAM_METADATA_PREFIX,
            )
        })
        .collect();
    if strip_names.is_empty() {
        return Cow::Borrowed(query_string);
    }

    let mut stripped = String::with_capacity(query_string.len());
    let mut removed_any = false;
    for pair in query_string.split('&') {
        if pair.is_empty() {
            continue;
        }
        let raw_name = pair.split_once('=').map_or(pair, |(name, _)| name);
        let decoded_name = percent_decode_str(raw_name).decode_utf8_lossy();
        if strip_names.contains(raw_name) || strip_names.contains(decoded_name.as_ref()) {
            removed_any = true;
            continue;
        }
        if !stripped.is_empty() {
            stripped.push('&');
        }
        stripped.push_str(pair);
    }

    if removed_any {
        Cow::Owned(stripped)
    } else {
        Cow::Borrowed(query_string)
    }
}

pub(crate) fn record_status(state: &ProxyState, status: u16) {
    // Fast path: get() uses a read lock (shared), which is much cheaper than
    // entry() which always takes a write lock. Since status codes are a small
    // fixed set, the entry almost always exists after the first request.
    if let Some(counter) = state.status_counts.get(&status) {
        counter.fetch_add(1, Ordering::Relaxed);
    } else if state.status_counts.len() < state.env_config.status_counts_max_entries {
        // Only insert new status codes if under the cap. Prevents unbounded
        // growth from adversarial backends returning many distinct codes.
        state
            .status_counts
            .entry(status)
            .or_insert_with(|| AtomicU64::new(0))
            .fetch_add(1, Ordering::Relaxed);
    }
    // else: silently drop — rare status code and map is at capacity
    crate::runtime_metrics::global_ref().record_http_status(status);
}

pub(crate) fn record_request(state: &ProxyState, status: u16) {
    state.request_count.fetch_add(1, Ordering::Relaxed);
    record_status(state, status);
}

/// Collect backend response headers into a HashMap.
///
/// RFC 7230 Section 3.2.2 allows folding multi-valued headers with commas,
/// **except** `Set-Cookie` (RFC 6265) which must be emitted as separate header
/// lines. We store multiple Set-Cookie values separated by `\n` so they can be
/// split back into individual headers when building the downstream response.
///
/// `connection_listed_strip` carries the lowercase names that the response's
/// `Connection` header named as additional hop-by-hop headers (RFC 9110
/// §7.6.1). These are removed in the same pass as the canonical
/// response-direction strip predicate.
fn collect_response_headers_generic<'a, I>(
    source_keys_len: usize,
    source: I,
    target: &mut HashMap<String, String>,
    connection_listed_strip: &[http::header::HeaderName],
) where
    I: IntoIterator<Item = (&'a http::header::HeaderName, &'a http::header::HeaderValue)>,
{
    target.reserve(source_keys_len);
    for (k, v) in source {
        // Strip hop-by-hop headers from backend responses per RFC 9110 §7.6.1
        // (canonical predicate in `proxy::headers`; response-direction set
        // differs from the request-direction set).
        if headers_mod::is_backend_response_strip_header(k.as_str()) {
            continue;
        }
        // RFC 9110 §7.6.1: also strip every header NAMED in the response's
        // `Connection` field. Linear scan is fine — the list is typically
        // empty and bounded by realistic header counts.
        if connection_listed_strip.iter().any(|n| n == k) {
            continue;
        }
        if let Ok(vs) = v.to_str() {
            // Determine multi-value separator before allocating the key String.
            // HeaderName comparison is zero-cost (pointer/length check on
            // pre-interned names), saving a String allocation when the header
            // already exists in the target map.
            let sep = if k == "set-cookie" { "\n" } else { ", " };
            match target.get_mut(k.as_str()) {
                Some(existing) => {
                    existing.push_str(sep);
                    existing.push_str(vs);
                }
                None => {
                    target.insert(k.as_str().to_owned(), vs.to_owned());
                }
            }
        }
    }
}

fn collect_response_headers(
    source: &reqwest::header::HeaderMap,
    target: &mut HashMap<String, String>,
) {
    let listed = headers_mod::parse_connection_listed_headers(source);
    collect_response_headers_generic(source.keys_len(), source.iter(), target, &listed);
}

/// Collect hyper response headers into a HashMap.
///
/// Same semantics as `collect_response_headers` (Set-Cookie newline separation,
/// comma folding for other headers) but for `hyper::HeaderMap` instead of
/// `reqwest::header::HeaderMap`. Used by the HTTP/2 multiplexing pool path.
fn collect_hyper_response_headers(source: &hyper::HeaderMap, target: &mut HashMap<String, String>) {
    let listed = headers_mod::parse_connection_listed_headers(source);
    collect_response_headers_generic(source.keys_len(), source.iter(), target, &listed);
}

/// Trim optional whitespace (OWS: SP / HTAB) from both ends of a byte slice.
/// Used for parsing comma-separated header field values per RFC 9110 §5.6.1.
fn trim_ows(bytes: &[u8]) -> &[u8] {
    let start = bytes
        .iter()
        .position(|&b| b != b' ' && b != b'\t')
        .unwrap_or(bytes.len());
    let end = bytes
        .iter()
        .rposition(|&b| b != b' ' && b != b'\t')
        .map_or(start, |i| i + 1);
    &bytes[start..end]
}

fn is_valid_reg_name(host: &str) -> bool {
    // RFC 3986 reg-name minus comma. Comma is technically a sub-delim, but it
    // is also the HTTP list separator (Content-Length, TE, etc.), so accepting
    // it inside a hostname invites parser-differential mistakes between routing
    // and any code that splits authority-derived strings on commas later.
    !host.is_empty()
        && host
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"-._%~!$&'()*+;=".contains(&b))
}

/// RFC 3986 IP-literal contents validator: accept IPv6address or IPvFuture
/// inside `[...]`. Without this, `Host: []` and `Host: [not-an-ip]` would
/// normalize to opaque strings and fall through to the catch-all routing
/// tier — bypassing host-scoped routes for a malformed authority.
fn is_valid_ip_literal_contents(content: &str) -> bool {
    if content.is_empty() {
        return false;
    }
    if content.parse::<std::net::Ipv6Addr>().is_ok() {
        return true;
    }
    // IPvFuture = "v" 1*HEXDIG "." 1*( unreserved / sub-delims / ":" )
    //
    // Note: this validator accepts comma in the `addr` segment because RFC 3986
    // lists comma as a sub-delim. `is_valid_reg_name` rejects comma instead, to
    // avoid the HTTP list-separator parser-differential. The asymmetry is
    // intentional and safe here because IPvFuture content is always wrapped in
    // `[...]` — downstream code that splits an authority string on commas will
    // treat the bracketed segment as opaque, so a comma inside cannot be
    // smuggled out as a second list element the way it could in a bare host.
    let rest = match content.as_bytes().first() {
        Some(b'v') | Some(b'V') => &content[1..],
        _ => return false,
    };
    let Some((hex, addr)) = rest.split_once('.') else {
        return false;
    };
    !hex.is_empty()
        && hex.bytes().all(|b| b.is_ascii_hexdigit())
        && !addr.is_empty()
        && addr
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"-._~!$&'()*+,;=:".contains(&b))
}

/// Validate an authority port suffix: ASCII digits only and within `u16` range.
///
/// Without the range check, values like `host:9999999999` parse as a valid
/// authority because the only previous gate was `is_ascii_digit()`. The TCP
/// port space is `0..=65535`; anything larger is broken-client territory and
/// should be rejected at admission so it never reaches routing or backend
/// dispatch where the same string would be re-parsed and fail with a
/// less-specific error.
fn is_valid_port(port: &str) -> bool {
    !port.is_empty() && port.parse::<u16>().is_ok()
}

fn split_request_authority(value: &str) -> Option<(&str, Option<&str>)> {
    let value = value.trim();
    if value.is_empty() || value.contains('@') {
        return None;
    }

    if value.starts_with('[') {
        let end = value.find(']')?;
        // Reject brackets that don't enclose a valid IPv6address/IPvFuture.
        // RFC 3986 §3.2.2: bracketed authorities exist solely to disambiguate
        // IP-literal hosts from port colons; opaque content like `[]` or
        // `[not-an-ip]` is malformed authority syntax.
        if !is_valid_ip_literal_contents(&value[1..end]) {
            return None;
        }
        let host = &value[..=end];
        let suffix = &value[end + 1..];
        if suffix.is_empty() {
            return Some((host, None));
        }
        if let Some(port) = suffix.strip_prefix(':')
            && is_valid_port(port)
        {
            return Some((host, Some(port)));
        }
        return None;
    }

    match value.rsplit_once(':') {
        Some((host, port)) if !host.contains(':') => {
            if is_valid_reg_name(host) && is_valid_port(port) {
                Some((host, Some(port)))
            } else {
                None
            }
        }
        Some(_) => None,
        None => {
            if is_valid_reg_name(value) {
                Some((value, None))
            } else {
                None
            }
        }
    }
}

fn normalize_authority_host(host: &str) -> String {
    let normalized = host.strip_suffix('.').unwrap_or(host);
    normalized.to_ascii_lowercase()
}

/// The `:authority` a multi-port Sidecar egress request sends to the peer's
/// inbound listener: the preserved client host with any client-supplied port
/// replaced by the OWNING SERVICE port of the per-port route the captured
/// original destination selected (the orig-dst is the dialed truth; a
/// client's explicit Host port should agree, but the route's owning port
/// wins when they differ). Bracketed IPv6 hosts keep their brackets. A host
/// that fails authority parsing (it already passed routing normalization, so
/// this is defensive) is used as-is with the port appended.
fn mesh_mtls_request_authority(preserved_host: &str, service_port: u16) -> String {
    let host = split_request_authority(preserved_host)
        .map(|(host, _)| host)
        .unwrap_or(preserved_host);
    format!("{host}:{service_port}")
}

/// Normalize a Host/authority value for host-based routing.
///
/// This removes a valid port suffix, preserves bracketed IPv6 literals, strips
/// DNS trailing dots, and lowercases ASCII hostnames. Invalid authority syntax
/// returns `None` so callers can avoid routing on ambiguous host data.
pub fn normalize_request_host_for_routing(value: &str) -> Option<String> {
    split_request_authority(value)
        .map(|(host, _)| normalize_authority_host(host))
        .filter(|h| !h.is_empty())
}

fn default_port_for_scheme(scheme: Option<&str>) -> Option<&'static str> {
    match scheme {
        Some("http" | "ws") => Some("80"),
        Some("https" | "wss") => Some("443"),
        _ => None,
    }
}

fn normalize_authority_for_consistency(value: &str, scheme: Option<&str>) -> Option<String> {
    split_request_authority(value).map(|(host, port)| {
        if let Some(port) = port
            && Some(port) != default_port_for_scheme(scheme)
        {
            let mut normalized = normalize_authority_host(host);
            normalized.push(':');
            normalized.push_str(port);
            return normalized;
        }
        normalize_authority_host(host)
    })
}

/// Canonicalize a validated Host/`:authority` value for request signatures.
/// Default ports are omitted so equivalent HTTP authorities have one signing
/// representation; non-default ports and bracketed IPv6 literals are retained.
pub fn normalize_request_authority_for_signing(
    value: &str,
    scheme: Option<&str>,
) -> Option<String> {
    normalize_authority_for_consistency(value, scheme).filter(|authority| !authority.is_empty())
}

/// Validate HTTP/2 and HTTP/3 `Host`/`:authority` consistency before routing.
///
/// RFC 9113 states that `Host` and `:authority` are not permitted to disagree;
/// RFC 9114 says that if both are present, they must contain the same value.
/// Rejecting disagreement here prevents routing/plugin decisions from keying on
/// one authority while a backend sees another during H2/H3-to-H1 translation.
pub fn check_host_authority_consistency(
    headers: &hyper::HeaderMap,
    uri: &hyper::Uri,
    version: hyper::Version,
) -> Option<&'static str> {
    if version != hyper::Version::HTTP_2 && version != hyper::Version::HTTP_3 {
        return None;
    }

    let mut host_values = headers.get_all("host").iter();
    let host = host_values.next();
    if host_values.next().is_some() {
        return Some(r#"{"error":"Request contains multiple Host headers"}"#);
    }

    let host = host?;
    let Ok(host) = host.to_str() else {
        return Some(r#"{"error":"Host header contains invalid characters"}"#);
    };
    let scheme = uri.scheme_str();
    let Some(host) = normalize_authority_for_consistency(host, scheme) else {
        return Some(r#"{"error":"Host header contains invalid authority"}"#);
    };

    if let Some(authority) = uri.authority() {
        let Some(authority) = normalize_authority_for_consistency(authority.as_str(), scheme)
        else {
            return Some(r#"{"error":"Request authority contains invalid authority"}"#);
        };
        if host != authority {
            return Some(r#"{"error":"Host header and request authority disagree"}"#);
        }
    }

    None
}

/// Validate protocol-level header constraints to block smuggling and desync attacks.
///
/// Returns an error message string if the request violates protocol rules, `None` if valid.
///
/// Checks performed (all run before routing — these are transport-level violations):
///
/// 1. **Content-Length + Transfer-Encoding conflict** (HTTP/1.x only): RFC 9112 §6.1
///    mandates that a proxy MUST reject or fix messages with both headers. Attackers
///    exploit CL/TE or TE/CL parsing disagreements between proxies and backends to
///    smuggle requests across connection boundaries.
///
/// 2. **Multiple Content-Length with mismatched values** (all HTTP versions): RFC 9110 §8.6
///    — different CL values in the same message indicate tampering or a broken intermediary.
///
/// 3. **Multiple Host headers** (HTTP/1.1 only): RFC 9112 §3.2 — a request with
///    duplicate Host headers MUST be rejected with 400 to prevent host-header routing
///    confusion between the proxy and backend.
///
/// 4. **Transfer-Encoding rejection** (HTTP/2 and HTTP/3): RFC 9113 §8.2.2 and
///    RFC 9114 §4.2 forbid this HTTP/1.x framing header on multiplexed protocols.
///
/// 5. **TE header validation** (HTTP/2 and HTTP/3): RFC 9113 §8.2.2 and RFC 9114 §4.2 —
///    the only permitted value is "trailers"; any other value (or an empty list element
///    such as `,trailers` / `trailers,`) is a protocol violation that could be used to
///    confuse intermediaries that translate H2/H3 to HTTP/1.x.
pub fn check_protocol_headers(
    headers: &hyper::HeaderMap,
    version: hyper::Version,
) -> Option<&'static str> {
    let is_http1 = version == hyper::Version::HTTP_10 || version == hyper::Version::HTTP_11;

    // 1a. HTTP/1.0 must not use Transfer-Encoding (RFC 9112 §6.2 — HTTP/1.0 has no chunked encoding)
    if version == hyper::Version::HTTP_10 && headers.contains_key("transfer-encoding") {
        return Some(r#"{"error":"HTTP/1.0 does not support Transfer-Encoding"}"#);
    }

    // 1b. Content-Length + Transfer-Encoding conflict (HTTP/1.x request smuggling)
    // HTTP/2 and HTTP/3 don't use Transfer-Encoding (framing is at the protocol layer).
    if is_http1
        && headers.contains_key("transfer-encoding")
        && headers.contains_key("content-length")
    {
        return Some(
            r#"{"error":"Request contains both Content-Length and Transfer-Encoding headers"}"#,
        );
    }

    // 2. Content-Length validation (all HTTP versions)
    // a) Each token must be ASCII digits only (RFC 9110 §8.6 — non-negative integer).
    //    Rejecting signs, decimals, hex prefixes, and garbage prevents parsing
    //    disagreements between the proxy and backend about message boundaries.
    // b) An intermediary may coalesce duplicate CL headers into a single comma-separated
    //    field line (e.g. "Content-Length: 42, 0"). We must split on commas, trim OWS,
    //    and reject if any parsed value differs — otherwise a smuggling variant that
    //    relies on coalesced CL values can bypass the guard.
    {
        let mut canonical: Option<&[u8]> = None;
        for val in headers.get_all("content-length") {
            for token in val.as_bytes().split(|&b| b == b',') {
                let trimmed = trim_ows(token);
                if trimmed.is_empty() {
                    return Some(
                        r#"{"error":"Content-Length header contains invalid empty value"}"#,
                    );
                }
                // 2a. Must be ASCII digits only (no signs, decimals, hex, or garbage)
                if !trimmed.iter().all(|&b| b.is_ascii_digit()) {
                    return Some(
                        r#"{"error":"Content-Length header contains invalid non-numeric value"}"#,
                    );
                }
                if trimmed
                    .iter()
                    .try_fold(0usize, |acc, &digit| {
                        acc.checked_mul(10)
                            .and_then(|acc| acc.checked_add((digit - b'0') as usize))
                    })
                    .is_none()
                {
                    return Some(
                        r#"{"error":"Content-Length header exceeds supported integer range"}"#,
                    );
                }
                // 2b. All tokens must agree on the same value
                match canonical {
                    None => canonical = Some(trimmed),
                    Some(prev) if prev != trimmed => {
                        return Some(
                            r#"{"error":"Multiple Content-Length headers with conflicting values"}"#,
                        );
                    }
                    _ => {}
                }
            }
        }
    }

    // 3. Multiple Host headers (HTTP/1.1 only)
    // HTTP/2 and HTTP/3 use the :authority pseudo-header (exposed via URI), not Host.
    if is_http1 {
        let mut host_iter = headers.get_all("host").iter();
        if host_iter.next().is_some() && host_iter.next().is_some() {
            return Some(r#"{"error":"Request contains multiple Host headers"}"#);
        }
    }

    // 4. HTTP/2 and HTTP/3 must not carry HTTP/1.x Transfer-Encoding.
    if (version == hyper::Version::HTTP_2 || version == hyper::Version::HTTP_3)
        && headers.contains_key("transfer-encoding")
    {
        return Some(r#"{"error":"HTTP/2 and HTTP/3 do not support Transfer-Encoding"}"#);
    }

    // 5. TE header in HTTP/2 and HTTP/3 must be "trailers" only
    // (RFC 9113 §8.2.2 for HTTP/2, RFC 9114 §4.2 for HTTP/3).
    // Iterate all TE header entries and comma-separated tokens within each entry.
    // A request with `te: trailers` plus a second `te: gzip` entry (or a single
    // `te: trailers, gzip` field) must be rejected.
    if version == hyper::Version::HTTP_2 || version == hyper::Version::HTTP_3 {
        for te_val in headers.get_all("te") {
            if let Ok(te_str) = te_val.to_str() {
                for token in te_str.split(',') {
                    let trimmed = token.trim();
                    if trimmed.is_empty() {
                        return Some(r#"{"error":"TE header contains invalid empty value"}"#);
                    }
                    if !trimmed.eq_ignore_ascii_case("trailers") {
                        return Some(r#"{"error":"TE header must be 'trailers' or absent"}"#);
                    }
                }
            } else {
                return Some(r#"{"error":"TE header contains invalid characters"}"#);
            }
        }
    }

    None
}

fn build_response(status: StatusCode, body: &str) -> Response<ProxyBody> {
    // Response::builder with a valid status and static header name cannot fail
    Response::builder()
        .status(status)
        .header("Content-Type", "application/json")
        .body(ProxyBody::from_string(body))
        .unwrap_or_else(|_| {
            Response::new(ProxyBody::from_string(
                r#"{"error":"Internal server error"}"#,
            ))
        })
}

fn build_request_body_timeout_response(
    is_grpc_request: bool,
    grpc_web_response_content_type: Option<&str>,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> Response<ProxyBody> {
    const MESSAGE: &str = "Request body read timed out";
    if let Some(content_type) = grpc_web_response_content_type {
        return build_grpc_web_error_response(
            content_type,
            grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
            MESSAGE,
            initial_response_header_policy_plugins,
        );
    }
    if is_grpc_request {
        return grpc_proxy::build_grpc_error_response_with_policy(
            grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
            MESSAGE,
            initial_response_header_policy_plugins,
        );
    }
    build_response(
        StatusCode::REQUEST_TIMEOUT,
        r#"{"error":"Request body read timed out"}"#,
    )
}

fn build_request_body_too_large_response(
    is_grpc_request: bool,
    grpc_web_response_content_type: Option<&str>,
    limit: usize,
    initial_response_header_policy_plugins: &[Arc<dyn Plugin>],
) -> Response<ProxyBody> {
    let message = format!("Request body exceeds maximum size of {limit} bytes");
    if let Some(content_type) = grpc_web_response_content_type {
        return build_grpc_web_error_response(
            content_type,
            grpc_proxy::grpc_status::RESOURCE_EXHAUSTED,
            &message,
            initial_response_header_policy_plugins,
        );
    }
    if is_grpc_request {
        return grpc_proxy::build_grpc_error_response_with_policy(
            grpc_proxy::grpc_status::RESOURCE_EXHAUSTED,
            &message,
            initial_response_header_policy_plugins,
        );
    }
    build_response(
        StatusCode::PAYLOAD_TOO_LARGE,
        r#"{"error":"Request body exceeds maximum size"}"#,
    )
}

fn request_body_timeout_backend_response(resolved_ip: Option<String>) -> retry::BackendResponse {
    retry::BackendResponse {
        status_code: StatusCode::REQUEST_TIMEOUT.as_u16(),
        body: ResponseBody::Buffered(
            r#"{"error":"Request body read timed out"}"#.as_bytes().to_vec(),
        ),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        // Buffered client-upload timeouts carry no backend health signal.
        // ClientDisconnect is the existing centrally neutral client-side class.
        error_class: Some(retry::ErrorClass::ClientDisconnect),
    }
}

fn build_plain_text_response(status: StatusCode, body: &str) -> Response<ProxyBody> {
    Response::builder()
        .status(status)
        .header("Content-Type", "text/plain")
        .header("Cache-Control", "no-store")
        .body(ProxyBody::from_string(body))
        .unwrap_or_else(|_| Response::new(ProxyBody::from_string("Internal server error")))
}

/// Proxy the request to an HTTPS backend using the HTTP/2 multiplexing pool.
///
/// Uses hyper's HTTP/2 client directly to multiplex concurrent requests over
/// a single persistent TLS connection, avoiding reqwest's connection-per-burst behavior.
fn hbone_pool_error_response(
    state: &ProxyState,
    proxy: &Proxy,
    err: &HbonePoolError,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let error_class = err.error_class();
    if error_class == retry::ErrorClass::PortExhaustion {
        state.overload.record_port_exhaustion();
    }
    let error_body = if error_class == retry::ErrorClass::DnsLookupError {
        r#"{"error":"DNS resolution for HBONE backend failed"}"#.to_string()
    } else {
        format!(r#"{{"error":"HBONE backend unavailable: {}"}}"#, err)
    };
    error!(
        proxy_id = %proxy.id,
        error_kind = retry::error_class_log_kind(error_class),
        error = %err,
        "HBONE backend request failed"
    );
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(error_body.into_bytes()),
        headers: HashMap::new(),
        connection_error: !retry::request_reached_wire(error_class),
        backend_resolved_ip: resolved_ip,
        error_class: Some(error_class),
    }
}

fn hbone_hyper_error_response(
    proxy: &Proxy,
    err: hyper::Error,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    error!(proxy_id = %proxy.id, error = %err, "HBONE tunneled HTTP request failed");
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(r#"{"error":"HBONE backend unavailable"}"#.into()),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ProtocolError),
    }
}

enum HyperBodyCollectError {
    TooLarge,
    Read(hyper::Error),
    ReadTimeout { timeout_ms: u64 },
}

async fn collect_hyper_body_with_limit(
    body: Incoming,
    max_size: usize,
    backend_read_timeout_ms: u64,
) -> Result<Vec<u8>, HyperBodyCollectError> {
    collect_hyper_body_and_trailers_with_limit(body, max_size, backend_read_timeout_ms)
        .await
        .map(|(body_bytes, _trailers)| body_bytes)
}

/// Collect a hyper H2 response body up to `max_size`, also capturing the
/// terminal TRAILERS frame when present. Data-frame limits and read-timeout
/// behavior are identical to [`collect_hyper_body_with_limit`] (which
/// delegates here). The mesh-mTLS buffered arm needs the trailers to preserve
/// gRPC terminal metadata for gRPC-Web translation (codex r1-4); callers that
/// don't can use the body-only wrapper.
async fn collect_hyper_body_and_trailers_with_limit(
    mut body: Incoming,
    max_size: usize,
    backend_read_timeout_ms: u64,
) -> Result<(Vec<u8>, Option<hyper::HeaderMap>), HyperBodyCollectError> {
    let mut body_bytes = Vec::new();
    let mut trailers: Option<hyper::HeaderMap> = None;
    loop {
        let next_frame = if backend_read_timeout_ms > 0 {
            match tokio::time::timeout(Duration::from_millis(backend_read_timeout_ms), body.frame())
                .await
            {
                Ok(frame) => frame,
                Err(_) => {
                    return Err(HyperBodyCollectError::ReadTimeout {
                        timeout_ms: backend_read_timeout_ms,
                    });
                }
            }
        } else {
            body.frame().await
        };
        let Some(frame) = next_frame else {
            break;
        };
        let frame = frame.map_err(HyperBodyCollectError::Read)?;
        if let Some(data) = frame.data_ref() {
            if max_size > 0 && body_bytes.len().saturating_add(data.len()) > max_size {
                return Err(HyperBodyCollectError::TooLarge);
            }
            body_bytes.extend_from_slice(data);
        } else if let Ok(trailer_map) = frame.into_trailers() {
            // A second TRAILERS frame is not legal HTTP/2, but merge whatever
            // hyper surfaces rather than silently dropping trailing metadata.
            match trailers.as_mut() {
                Some(existing) => existing.extend(trailer_map),
                None => trailers = Some(trailer_map),
            }
        }
    }
    Ok((body_bytes, trailers))
}

fn hbone_response_body_too_large_response(
    proxy: &Proxy,
    resolved_ip: Option<String>,
    observed_size: Option<usize>,
    max_size: usize,
) -> retry::BackendResponse {
    match observed_size {
        Some(size) => warn!(
            proxy_id = %proxy.id,
            response_body_bytes = size,
            max_response_body_size_bytes = max_size,
            "HBONE backend response body exceeds configured size limit"
        ),
        None => warn!(
            proxy_id = %proxy.id,
            max_response_body_size_bytes = max_size,
            "HBONE backend response body exceeded configured size limit while buffering"
        ),
    }
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(
            r#"{"error":"Backend response body exceeds maximum size"}"#
                .as_bytes()
                .to_vec(),
        ),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
    }
}

fn hbone_request_body_too_large_response(
    proxy: &Proxy,
    resolved_ip: Option<String>,
    observed_size: Option<usize>,
    max_size: usize,
) -> retry::BackendResponse {
    match observed_size {
        Some(size) => warn!(
            proxy_id = %proxy.id,
            request_body_bytes = size,
            max_request_body_size_bytes = max_size,
            "HBONE request body exceeds configured size limit"
        ),
        None => warn!(
            proxy_id = %proxy.id,
            max_request_body_size_bytes = max_size,
            "HBONE streaming request body exceeded configured size limit"
        ),
    }
    retry::BackendResponse {
        status_code: 413,
        body: ResponseBody::Buffered(
            r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
        ),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
    }
}

/// Mid-upload overflow refusal for the sidecar mesh-mTLS path (codex r1-3):
/// gRPC-flavored requests — which are capped at the gRPC receive limit — get
/// the direct gRPC pool's Trailers-Only RESOURCE_EXHAUSTED shape; plain HTTP
/// keeps the JSON 413. Both are `ErrorClass::RequestBodyTooLarge`, so
/// backend-health accounting stays NEUTRAL either way.
fn mesh_mtls_request_body_too_large_response(
    proxy: &Proxy,
    resolved_ip: Option<String>,
    grpc_flavored: bool,
    max_size: usize,
) -> retry::BackendResponse {
    if grpc_flavored {
        grpc_proxy::grpc_request_body_too_large_backend_response(
            &proxy.id,
            resolved_ip,
            None,
            max_size,
        )
    } else {
        hbone_request_body_too_large_response(proxy, resolved_ip, None, max_size)
    }
}

fn mesh_grpc_unavailable_response(
    resolved_ip: Option<String>,
    message: &str,
    error_class: retry::ErrorClass,
) -> retry::BackendResponse {
    let mut headers = HashMap::with_capacity(3);
    headers.insert("content-type".to_string(), "application/grpc".to_string());
    headers.insert(
        "grpc-status".to_string(),
        grpc_proxy::grpc_status::UNAVAILABLE.to_string(),
    );
    headers.insert("grpc-message".to_string(), message.to_string());
    retry::BackendResponse {
        status_code: 200, // gRPC errors ride HTTP 200 + grpc-status
        body: ResponseBody::Buffered(Vec::new()),
        headers,
        connection_error: !retry::request_reached_wire(error_class),
        backend_resolved_ip: resolved_ip,
        error_class: Some(error_class),
    }
}

/// Post-dispatch timeout for a gRPC-flavored request on the sidecar mesh-mTLS
/// path (codex r2-2 finding 6): the direct gRPC pool maps a dispatch timeout
/// (`GrpcProxyError::BackendTimeout`) to a Trailers-Only DEADLINE_EXCEEDED
/// with the generic "Backend deadline exceeded" message — mirror that shape
/// instead of the plain-HTTP JSON 504. Rides HTTP 200 (gRPC errors carry the
/// outcome in `grpc-status`); backend-health accounting still sees the
/// failure through the gRPC status seeding (`grpc_admission_status_from_maps`
/// maps 4 -> 504) plus `ErrorClass::ReadWriteTimeout` — the same class the
/// direct pool derives via `classify_grpc_proxy_error` for a Read timeout.
fn mesh_grpc_deadline_exceeded_response(resolved_ip: Option<String>) -> retry::BackendResponse {
    let mut headers = HashMap::with_capacity(3);
    headers.insert("content-type".to_string(), "application/grpc".to_string());
    headers.insert(
        "grpc-status".to_string(),
        grpc_proxy::grpc_status::DEADLINE_EXCEEDED.to_string(),
    );
    headers.insert(
        "grpc-message".to_string(),
        "Backend deadline exceeded".to_string(),
    );
    retry::BackendResponse {
        status_code: 200, // gRPC errors ride HTTP 200 + grpc-status
        body: ResponseBody::Buffered(Vec::new()),
        headers,
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
    }
}

/// Client RPC deadline expiry while gateway work is still pending. It has the
/// same client-visible Trailers-Only status as a backend read timeout, but
/// remains neutral to backend health, circuit breaking, and adaptive
/// concurrency because the client-chosen deadline is not a backend signal.
fn client_grpc_deadline_exceeded_response(resolved_ip: Option<String>) -> retry::BackendResponse {
    let mut response = mesh_grpc_deadline_exceeded_response(resolved_ip);
    response.headers.insert(
        "grpc-message".to_string(),
        GATEWAY_DEADLINE_EXCEEDED_MESSAGE.to_string(),
    );
    response.error_class = Some(retry::ErrorClass::ClientDisconnect);
    response.connection_error = false;
    response
}

pub(crate) fn client_grpc_deadline_exceeded_response_for_request(
    request_ctx: &RequestContext,
    request_headers: &HashMap<String, String>,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    // A translated request still runs the normal response plugin chain. Keep
    // its internal response native so `grpc_web` performs exactly one body
    // encoding pass. A pass-through gRPC-Web request has no translation marker,
    // so synthesize its client wire shape here instead.
    if crate::plugins::grpc_web::request_is_grpc_web_translated(request_ctx) {
        return client_grpc_deadline_exceeded_response(resolved_ip);
    }
    let Some(content_type) = request_headers
        .get("content-type")
        .filter(|content_type| crate::plugins::grpc_web::is_grpc_web_content_type(content_type))
    else {
        return client_grpc_deadline_exceeded_response(resolved_ip);
    };
    let response_content_type =
        crate::plugins::grpc_web::retained_response_content_type(request_ctx)
            .map(str::to_owned)
            .unwrap_or_else(|| crate::plugins::grpc_web::response_content_type(content_type));
    let translated = crate::plugins::grpc_web::error_response_for_content_type(
        &response_content_type,
        grpc_proxy::grpc_status::DEADLINE_EXCEEDED,
        GATEWAY_DEADLINE_EXCEEDED_MESSAGE,
    );
    retry::BackendResponse {
        status_code: StatusCode::OK.as_u16(),
        body: ResponseBody::Buffered(translated.body),
        headers: translated.headers,
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ClientDisconnect),
    }
}

fn client_grpc_deadline_exceeded_response_for_optional_request(
    request_ctx: Option<&RequestContext>,
    request_headers: &HashMap<String, String>,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    match request_ctx {
        Some(request_ctx) => client_grpc_deadline_exceeded_response_for_request(
            request_ctx,
            request_headers,
            resolved_ip,
        ),
        None => client_grpc_deadline_exceeded_response(resolved_ip),
    }
}

fn mesh_grpc_response_body_too_large_response(
    proxy: &Proxy,
    resolved_ip: Option<String>,
    observed_size: Option<usize>,
    max_size: usize,
) -> retry::BackendResponse {
    match observed_size {
        Some(size) => warn!(
            proxy_id = %proxy.id,
            response_body_bytes = size,
            max_response_body_size_bytes = max_size,
            "sidecar mTLS gRPC backend response body exceeds configured size limit"
        ),
        None => warn!(
            proxy_id = %proxy.id,
            max_response_body_size_bytes = max_size,
            "sidecar mTLS gRPC backend response body exceeded configured size limit while buffering"
        ),
    }
    let mut headers = HashMap::with_capacity(3);
    headers.insert("content-type".to_string(), "application/grpc".to_string());
    headers.insert(
        "grpc-status".to_string(),
        grpc_proxy::grpc_status::RESOURCE_EXHAUSTED.to_string(),
    );
    headers.insert(
        "grpc-message".to_string(),
        format!("gRPC response payload size exceeds maximum of {max_size} bytes"),
    );
    retry::BackendResponse {
        status_code: 200, // gRPC errors ride HTTP 200 + grpc-status
        body: ResponseBody::Buffered(Vec::new()),
        headers,
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
    }
}

/// Gateway-side refusal when native gRPC over sidecar mesh-mTLS would require
/// response buffering. Healthy backend statuses stay neutral because the
/// refusal is a gateway-side policy conflict; an already-observed backend 5xx
/// remains visible to backend-health accounting.
fn mesh_grpc_response_buffering_refusal_response(
    observed_status: u16,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let mut headers = HashMap::with_capacity(3);
    headers.insert("content-type".to_string(), "application/grpc".to_string());
    headers.insert(
        "grpc-status".to_string(),
        grpc_proxy::grpc_status::UNAVAILABLE.to_string(),
    );
    headers.insert(
        "grpc-message".to_string(),
        "gRPC over sidecar mesh mTLS cannot buffer responses (trailers would be dropped)"
            .to_string(),
    );
    let observed_backend_failure = (500..=599).contains(&observed_status);
    retry::BackendResponse {
        status_code: if observed_backend_failure {
            observed_status
        } else {
            200 // gRPC errors ride HTTP 200 + grpc-status
        },
        body: ResponseBody::Buffered(Vec::new()),
        headers,
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: if observed_backend_failure {
            None
        } else {
            Some(retry::ErrorClass::DispatchPolicyRejected)
        },
    }
}

fn native_grpc_mesh_mtls_buffering_conflict_known(
    stream_response: bool,
    proxy: &Proxy,
    plugins: &[Arc<dyn Plugin>],
    ctx: Option<&RequestContext>,
) -> bool {
    if stream_response {
        return false;
    }
    let grpc_response_headers =
        HashMap::from([("content-type".to_string(), "application/grpc".to_string())]);
    !refine_stream_response_for_content_type(
        stream_response,
        proxy,
        plugins,
        ctx,
        200,
        &grpc_response_headers,
    )
}

#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend_hbone(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    client_request_body: ClientRequestBody,
    upstream_target: Option<&UpstreamTarget>,
    plugins: &[Arc<dyn crate::plugins::Plugin>],
    source_identity_ctx: Option<&RequestContext>,
    ctx: Option<&RequestContext>,
    stream_response: bool,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    resolved_ip: Option<String>,
    ctx_bytes_sent_observed: &Arc<std::sync::atomic::AtomicU64>,
) -> (
    retry::BackendResponse,
    Option<Bytes>,
    Option<Arc<std::sync::atomic::AtomicBool>>,
) {
    let Some(target) = upstream_target else {
        return (
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"HBONE target missing"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: true,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ConnectionPoolError),
            },
            None,
            None,
        );
    };

    // The dispatch debug (with the cross-cluster dial host / SNI / trust-domain
    // detail) is emitted below once those are resolved.

    let original_req = match client_request_body {
        ClientRequestBody::Streaming(request) => *request,
        ClientRequestBody::Buffered(_) => {
            debug_assert!(
                false,
                "HBONE pool should not be used when request body is pre-buffered"
            );
            return (
                retry::BackendResponse {
                    status_code: 500,
                    body: ResponseBody::Buffered(
                        r#"{"error":"HBONE request buffering invariant violated"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };

    if request_may_have_body(method, headers)
        && state.max_request_body_size_bytes > 0
        && let Some(content_length) = headers.get("content-length")
        && let Ok(len) = content_length.parse::<usize>()
        && len > state.max_request_body_size_bytes
    {
        return (
            hbone_request_body_too_large_response(
                proxy,
                resolved_ip,
                Some(len),
                state.max_request_body_size_bytes,
            ),
            None,
            None,
        );
    }

    let hbone_port = hbone_pool::target_hbone_port(target);
    let dial_host = match hbone_pool::target_hbone_dial_host(target) {
        Ok(host) => host,
        Err(err) => {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                error = %err,
                "Refusing HBONE dispatch: invalid dial host tag"
            );
            return (
                hbone_pool_error_response(state, proxy, &err, resolved_ip),
                None,
                None,
            );
        }
    };
    // The inner HBONE CONNECT `:authority` HOST = the REAL destination pod addr
    // the dest relay dials under the open-relay guard. For a CROSS-CLUSTER target
    // `target.host` is a SCOPED SYNTHETIC identity (so LB / health / circuit
    // breaker / retry keys never collapse two remote pods that share an IP across
    // overlapping CIDRs but are reached through DIFFERENT gateways), so the real
    // authority rides the `mesh.hbone_authority_host` tag; in-cluster targets have
    // no such tag and `target.host` IS the authority (byte-identical to before).
    // A present-but-empty tag fails CLOSED (502) — never dial the synthetic
    // identity as the CONNECT authority.
    let app_host = match hbone_pool::target_hbone_authority_host(target) {
        Ok(host) => host,
        Err(err) => {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                error = %err,
                "Refusing HBONE dispatch: invalid CONNECT authority host tag"
            );
            return (
                hbone_pool_error_response(state, proxy, &err, resolved_ip),
                None,
                None,
            );
        }
    };
    // Peer-verification mode + SNI + trust-domain scope depend on whether this is
    // a CROSS-CLUSTER east-west HBONE target (mirroring the Sidecar mesh-mTLS
    // cross-cluster branch in `proxy_to_backend_mesh_mtls`):
    // - Cross-cluster (`mesh.cross_cluster`): the dial host is the REMOTE
    //   east-west gateway (carried in `mesh.hbone_dial_host`, already resolved
    //   above), which SNI-passes the opaque outer TLS to a destination terminator
    //   that relays the inner HBONE CONNECT to the pinned pod IP. So verification
    //   is TRUST-DOMAIN-ONLY (`expected_peer = None`; the destination SVID must
    //   still chain to the remote trust domain via the federated bundle — never
    //   unverified) and the ClientHello SNI is OVERRIDDEN to the destination
    //   service FQDN (`mesh.eastwest_sni`). A cross-cluster target carries NO
    //   `mesh.spiffe_id` and MUST carry both a usable SNI and a usable trust
    //   domain tag — either missing/empty/unparseable FAILS CLOSED (502; never
    //   dial the gateway IP as SNI, never any-federated verification).
    // - In-cluster (default): the pinned destination identity is pinned (a
    //   present-but-corrupt tag fails closed) and there is no SNI / TD override.
    let cross_cluster = hbone_pool::target_hbone_cross_cluster(target);
    let (expected_peer, expected_trust_domain, sni_override) = if cross_cluster {
        let Some(sni) = hbone_pool::target_hbone_eastwest_sni(target) else {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                "Refusing cross-cluster HBONE dispatch: missing or empty mesh.eastwest_sni tag \
                 (fail closed, never dial the gateway IP as SNI)"
            );
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Cross-cluster HBONE target missing SNI"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ConnectionPoolError),
                },
                None,
                None,
            );
        };
        let Some(td) = hbone_pool::target_hbone_cross_cluster_trust_domain(target) else {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                "Refusing cross-cluster HBONE dispatch: missing, empty, or unparseable \
                 mesh.trust_domain tag (fail closed, never any-federated verification)"
            );
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Cross-cluster HBONE target missing trust domain"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ConnectionPoolError),
                },
                None,
                None,
            );
        };
        (None, Some(td), Some(sni))
    } else {
        // Pin the peer identity declared on the target. A present but corrupt
        // `mesh.hbone_peer_spiffe_id` / `mesh.spiffe_id` tag fails CLOSED here —
        // never silently downgrade a pinned dial to trust-domain-only.
        let expected_peer = match hbone_pool::target_expected_peer_spiffe(target) {
            Ok(peer) => peer,
            Err(err) => {
                error!(
                    proxy_id = %proxy.id,
                    target_host = %target.host,
                    error = %err,
                    "Refusing HBONE dispatch: invalid pinned peer identity tag"
                );
                return (
                    hbone_pool_error_response(state, proxy, &err, resolved_ip),
                    None,
                    None,
                );
            }
        };
        (expected_peer, None, None)
    };
    debug!(
        proxy_id = %proxy.id,
        target_host = %target.host,
        target_port = target.port,
        dial_host = %dial_host,
        app_host = %app_host,
        hbone_port,
        cross_cluster,
        expected_peer = expected_peer
            .as_ref()
            .map(|p| p.as_str())
            .unwrap_or("td-only"),
        expected_trust_domain = expected_trust_domain
            .as_ref()
            .map(|td| td.as_str())
            .unwrap_or(""),
        sni_override = sni_override.unwrap_or(""),
        "Proxying request via gateway HBONE tunnel"
    );
    let tunnel = match state
        .hbone_pool
        .get_tunnel_via(
            proxy,
            dial_host,
            // The inner CONNECT `:authority` host = the REAL pod addr (= the
            // synthetic-host cross-cluster target's `mesh.hbone_authority_host`,
            // else `target.host`); the network dial uses `dial_host` (gateway).
            app_host,
            target.port,
            target.dispatch_policy_port(),
            hbone_port,
            expected_peer.as_ref(),
            expected_trust_domain.as_ref(),
            sni_override,
            source_identity_ctx.and_then(|ctx| ctx.peer_spiffe_id.as_ref()),
        )
        .await
    {
        Ok(tunnel) => tunnel,
        Err(err) => {
            if err.is_capability_failure() {
                debug!(
                    proxy_id = %proxy.id,
                    error = %err,
                    "HBONE capability establishment failed; downgrading cached capability so subsequent requests skip the tunnel"
                );
                // `proxy` here is already the effective proxy resolved by
                // `proxy_to_backend`; the helper's re-resolution is idempotent
                // and keeps this downgrade on the same target-effective key the
                // probes and `can_attempt_hbone_backend` use.
                mark_hbone_unsupported_for_backend_target(
                    state.backend_capabilities.as_ref(),
                    proxy,
                    Some(target),
                );
            }
            return (
                hbone_pool_error_response(state, proxy, &err, resolved_ip),
                None,
                None,
            );
        }
    };

    let io = TokioIo::new(tunnel);
    let (mut sender, connection) = match hyper::client::conn::http1::Builder::new()
        .handshake(io)
        .await
    {
        Ok(parts) => parts,
        Err(err) => {
            return (
                hbone_hyper_error_response(proxy, err, resolved_ip),
                None,
                None,
            );
        }
    };
    tokio::spawn(async move {
        if let Err(e) = connection.await {
            debug!("hbone_pool: tunneled HTTP/1 connection closed: {}", e);
        }
    });

    // `backend_url` was built by the caller with `target.host` as the authority.
    // For a CROSS-CLUSTER target that host is a SCOPED SYNTHETIC identity (with
    // `|` separators) that is NOT a valid URI authority, so the parse below would
    // fail. Only `path_and_query` is read out of this URI (the host part is
    // dropped — the inner CONNECT already targets `app_host:port`), so rebuild a
    // PARSEABLE equivalent by swapping the synthetic authority for the real
    // `app_host` (the CONNECT authority). In-cluster targets keep `backend_url`
    // verbatim (no synthetic host), so this is byte-identical for them.
    let backend_url_for_parse: std::borrow::Cow<'_, str> = if cross_cluster {
        std::borrow::Cow::Owned(rewrite_backend_url_authority_host(
            backend_url,
            &target.host,
            app_host,
        ))
    } else {
        std::borrow::Cow::Borrowed(backend_url)
    };
    let uri: hyper::Uri = match backend_url_for_parse.parse() {
        Ok(uri) => uri,
        Err(e) => {
            error!(proxy_id = %proxy.id, error = %e, "Invalid HBONE backend URL");
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Invalid backend URL"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };
    let path_and_query = uri
        .path_and_query()
        .cloned()
        .unwrap_or_else(|| http::uri::PathAndQuery::from_static("/"));
    let tunneled_uri = hyper::Uri::builder()
        .path_and_query(path_and_query)
        .build()
        .unwrap_or_else(|_| hyper::Uri::from_static("/"));

    let (mut parts, body) = original_req.into_parts();
    let body_size_exceeded = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let max_request_body_size = if state.max_request_body_size_bytes > 0 {
        state.max_request_body_size_bytes
    } else {
        usize::MAX
    };
    let body = body::SizeLimitedIncoming::new_with_counter(
        body,
        max_request_body_size,
        Arc::clone(&body_size_exceeded),
        Arc::clone(ctx_bytes_sent_observed),
    );
    parts.uri = tunneled_uri;
    parts.version = hyper::Version::HTTP_11;
    parts.method = match parse_hyper_method(method) {
        Ok(method) => method,
        Err(()) => {
            warn_invalid_backend_method(&proxy.id, "hbone", method);
            return (
                retry::BackendResponse {
                    status_code: 405,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Method Not Allowed"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };
    parts.headers.clear();
    let backend_host_header = hbone_pool::authority_for_host_port(app_host, target.port);
    let owned_hbone_headers =
        hbone_inner_headers_with_stripped_baggage(headers, &state.mesh_egress_strip_baggage_keys);
    let headers = owned_hbone_headers.as_ref().unwrap_or(headers);
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (k, v) in headers {
        match k.as_str() {
            "host" => {
                if proxy.preserve_host_header {
                    insert_outbound_header_or_warn(
                        &mut parts.headers,
                        &proxy.id,
                        "hbone",
                        "client_host",
                        "host",
                        v,
                    );
                }
            }
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            _ => {
                insert_outbound_header_or_warn(
                    &mut parts.headers,
                    &proxy.id,
                    "hbone",
                    "client",
                    k,
                    v,
                );
            }
        }
    }
    if !proxy.preserve_host_header || !parts.headers.contains_key(hyper::header::HOST) {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "hbone",
            "backend_host",
            "host",
            &backend_host_header,
        );
    }

    let xff_val = build_xff_value(
        headers.get("x-forwarded-for").map(|s| s.as_str()),
        client_ip,
        xff_append_ip,
        &state.trusted_proxies,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "hbone",
        "generated_x_forwarded_for",
        "x-forwarded-for",
        &xff_val,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "hbone",
        "generated_x_forwarded_proto",
        "x-forwarded-proto",
        if request_is_secure { "https" } else { "http" },
    );
    if let Some(host) = headers.get("host") {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "hbone",
            "client_host_forwarded",
            "x-forwarded-host",
            host,
        );
    }
    if let Some(ref via) = state.via_header_http2 {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "hbone",
            "configured_via",
            "via",
            via,
        );
    }
    if state.add_forwarded_header {
        let proto_str = if request_is_secure { "https" } else { "http" };
        let fwd = build_forwarded_value(
            client_ip,
            proto_str,
            headers.get("host").map(|s| s.as_str()),
        );
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "hbone",
            "generated_forwarded",
            "forwarded",
            &fwd,
        );
    }

    let backend_req = Request::from_parts(parts, body);
    let send_fut = sender.send_request(backend_req);
    let response = if proxy.backend_read_timeout_ms > 0 {
        let timeout = Duration::from_millis(proxy.backend_read_timeout_ms);
        match tokio::time::timeout(timeout, send_fut).await {
            Ok(Ok(response)) => response,
            Ok(Err(err)) => {
                if body_size_exceeded.load(Ordering::Acquire) {
                    return (
                        hbone_request_body_too_large_response(
                            proxy,
                            resolved_ip,
                            None,
                            state.max_request_body_size_bytes,
                        ),
                        None,
                        None,
                    );
                }
                return (
                    hbone_hyper_error_response(proxy, err, resolved_ip),
                    None,
                    None,
                );
            }
            Err(_) => {
                if body_size_exceeded.load(Ordering::Acquire) {
                    return (
                        hbone_request_body_too_large_response(
                            proxy,
                            resolved_ip,
                            None,
                            state.max_request_body_size_bytes,
                        ),
                        None,
                        None,
                    );
                }
                warn!(
                    proxy_id = %proxy.id,
                    "HBONE tunneled HTTP read timeout ({}ms) waiting for backend response",
                    proxy.backend_read_timeout_ms
                );
                return (
                    retry::BackendResponse {
                        status_code: 504,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                    },
                    None,
                    None,
                );
            }
        }
    } else {
        match send_fut.await {
            Ok(response) => response,
            Err(err) => {
                if body_size_exceeded.load(Ordering::Acquire) {
                    return (
                        hbone_request_body_too_large_response(
                            proxy,
                            resolved_ip,
                            None,
                            state.max_request_body_size_bytes,
                        ),
                        None,
                        None,
                    );
                }
                return (
                    hbone_hyper_error_response(proxy, err, resolved_ip),
                    None,
                    None,
                );
            }
        }
    };

    let status = response.status().as_u16();
    let content_length = response
        .headers()
        .get("content-length")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<usize>().ok());
    if state.max_response_body_size_bytes > 0
        && let Some(len) = content_length
        && len > state.max_response_body_size_bytes
    {
        return (
            hbone_response_body_too_large_response(
                proxy,
                resolved_ip,
                Some(len),
                state.max_response_body_size_bytes,
            ),
            None,
            None,
        );
    }
    let mut resp_headers = HashMap::with_capacity(response.headers().keys_len());
    collect_hyper_response_headers(response.headers(), &mut resp_headers);

    // Content-type-aware buffer -> stream downgrade (see `proxy_to_backend`).
    let stream_response = refine_stream_response_for_content_type(
        stream_response,
        proxy,
        plugins,
        ctx,
        status,
        &resp_headers,
    );

    if stream_response {
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::StreamingH2(response),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            None,
            Some(body_size_exceeded),
        )
    } else {
        let body_bytes = match collect_hyper_body_with_limit(
            response.into_body(),
            state.max_response_body_size_bytes,
            proxy.backend_read_timeout_ms,
        )
        .await
        {
            Ok(body_bytes) => body_bytes,
            Err(HyperBodyCollectError::TooLarge) => {
                return (
                    hbone_response_body_too_large_response(
                        proxy,
                        resolved_ip,
                        None,
                        state.max_response_body_size_bytes,
                    ),
                    None,
                    None,
                );
            }
            Err(HyperBodyCollectError::Read(err)) => {
                return (
                    hbone_hyper_error_response(proxy, err, resolved_ip),
                    None,
                    None,
                );
            }
            Err(HyperBodyCollectError::ReadTimeout { timeout_ms }) => {
                warn!(
                    proxy_id = %proxy.id,
                    timeout_ms = timeout_ms,
                    "HBONE backend response body read timed out"
                );
                return (
                    retry::BackendResponse {
                        status_code: 504,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                    },
                    None,
                    None,
                );
            }
        };
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::Buffered(body_bytes),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            None,
            None,
        )
    }
}

/// Sidecar egress dispatch: send the request as HTTP/2 over a pooled SVID-mTLS
/// session to the destination sidecar's inbound listener (`mesh.mtls` targets).
///
/// Mirrors [`proxy_to_backend_hbone`]'s contract — streaming-only request body
/// wrapped in `SizeLimitedIncoming`, baggage-stripped inner headers, the same
/// size-limit and timeout handling, fail-closed on a missing/corrupt pinned
/// peer identity — but speaks h2 directly to the peer (no CONNECT tunnel):
/// the request `:authority` carries the service host the peer's inbound route
/// matches on, and the Host header is left to hyper's `:authority` mapping.
///
/// The third return element is the client-upload overflow flag
/// (`SizeLimitedIncoming`'s `body_size_exceeded`), returned — like the HBONE
/// path — only alongside a `StreamingH2` response so the caller's deferred
/// admission/dispatch outcomes can reclassify a post-header upload overflow as
/// neutral `RequestBodyTooLarge` instead of a backend failure (codex r2-2
/// finding 5).
#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend_mesh_mtls(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    client_request_body: ClientRequestBody,
    upstream_target: Option<&UpstreamTarget>,
    plugins: &[Arc<dyn crate::plugins::Plugin>],
    request_ctx: &RequestContext,
    response_decision_ctx: Option<&RequestContext>,
    stream_response: bool,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    resolved_ip: Option<String>,
    ctx_bytes_sent_observed: &Arc<std::sync::atomic::AtomicU64>,
) -> (
    retry::BackendResponse,
    Option<Bytes>,
    Option<Arc<std::sync::atomic::AtomicBool>>,
) {
    let Some(target) = upstream_target else {
        return (
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"Sidecar mTLS target missing"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: true,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ConnectionPoolError),
            },
            None,
            None,
        );
    };

    // Peer-verification mode + SNI depend on whether this is a CROSS-CLUSTER
    // east-west target:
    // - Cross-cluster (`mesh.cross_cluster`): the dial host is the REMOTE
    //   east-west gateway, which SNI-passes the opaque TLS to an LB-picked
    //   destination workload the client cannot name. So verification is
    //   TRUST-DOMAIN-ONLY (`expected_peer = None`; the destination SVID must
    //   still chain to a TRUSTED/federated trust domain — never unverified) and
    //   the ClientHello SNI is OVERRIDDEN to the destination service FQDN
    //   (`mesh.eastwest_sni`). A cross-cluster target carries NO `mesh.spiffe_id`
    //   and MUST carry a usable SNI tag — a missing/empty SNI FAILS CLOSED
    //   (never fall back to the gateway address as SNI, which would silently
    //   break passthrough routing and tunnel to whatever the gateway IP's own
    //   SNI resolves to).
    // - In-cluster (default): the pinned destination identity is mandatory —
    //   missing or corrupt fails closed before any dial — and no SNI override.
    // Resolve the peer-verification + SNI plan ONCE, shared with the WebSocket
    // egress path via `MeshMtlsDialPlan` so the in-cluster-pinned vs
    // cross-cluster (east-west) split cannot drift between the two transports:
    //   * IN-CLUSTER: the pinned destination identity is mandatory — missing or
    //     corrupt fails closed before any dial — and no SNI override.
    //   * CROSS-CLUSTER (`mesh.cross_cluster`): the dial host is the REMOTE
    //     east-west gateway, which SNI-passes the opaque TLS to an LB-picked
    //     destination workload the client cannot name. Verification is
    //     TRUST-DOMAIN-ONLY (`expected_peer = None`; the destination SVID must
    //     still chain to the remote/federated trust domain — never unverified)
    //     scoped to `mesh.trust_domain`, and the ClientHello SNI is OVERRIDDEN to
    //     the destination service FQDN (`mesh.eastwest_sni`). A missing SNI or
    //     trust domain FAILS CLOSED (502) — never a fallback to the gateway
    //     address as SNI or any-federated verification.
    let mesh_mtls_pool::MeshMtlsDialPlan {
        cross_cluster,
        expected_peer,
        expected_trust_domain,
        sni_override,
    } = match mesh_mtls_pool::MeshMtlsDialPlan::resolve(target) {
        Ok(plan) => plan,
        Err(mesh_mtls_pool::MeshMtlsDialError::PinnedPeer(err)) => {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                error = %err,
                "Refusing sidecar mTLS dispatch: unusable pinned peer identity"
            );
            return (
                hbone_pool_error_response(state, proxy, &err, resolved_ip),
                None,
                None,
            );
        }
        Err(mesh_mtls_pool::MeshMtlsDialError::MissingCrossClusterSni) => {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                "Refusing cross-cluster sidecar mTLS dispatch: missing or empty \
                 mesh.eastwest_sni tag (fail closed, never dial the gateway IP as SNI)"
            );
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Cross-cluster mTLS target missing SNI"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ConnectionPoolError),
                },
                None,
                None,
            );
        }
        Err(mesh_mtls_pool::MeshMtlsDialError::MissingCrossClusterTrustDomain) => {
            error!(
                proxy_id = %proxy.id,
                target_host = %target.host,
                "Refusing cross-cluster sidecar mTLS dispatch: missing, empty, or unparseable \
                 mesh.trust_domain tag (fail closed, never any-federated verification)"
            );
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Cross-cluster mTLS target missing trust domain"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ConnectionPoolError),
                },
                None,
                None,
            );
        }
    };

    debug!(
        proxy_id = %proxy.id,
        target_host = %target.host,
        target_port = target.port,
        cross_cluster,
        expected_peer = expected_peer
            .as_ref()
            .map(|p| p.as_str())
            .unwrap_or("td-only"),
        expected_trust_domain = expected_trust_domain
            .as_ref()
            .map(|td| td.as_str())
            .unwrap_or(""),
        sni_override = sni_override.unwrap_or(""),
        "Proxying request via sidecar SVID-mTLS HTTP/2"
    );

    let original_req = match client_request_body {
        ClientRequestBody::Streaming(request) => *request,
        ClientRequestBody::Buffered(_) => {
            debug_assert!(
                false,
                "mesh mTLS pool should not be used when request body is pre-buffered"
            );
            return (
                retry::BackendResponse {
                    status_code: 500,
                    body: ResponseBody::Buffered(
                        r#"{"error":"mesh mTLS request buffering invariant violated"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };

    // gRPC flavor (issue #2003): same-cluster `mesh.mtls` gRPC skips the
    // direct-dial gRPC pool and dispatches here — the mesh-mTLS pool is hyper
    // h2 end-to-end, so gRPC trailers ride it natively. gRPC-only adjustments
    // below: the request-body cap is the gRPC receive limit
    // (`max_grpc_recv_size_bytes`, mirroring the direct gRPC pool — codex
    // r1-3), the outbound request re-adds `te: trailers` (the hop-by-hop
    // strip removes it, but the gRPC HTTP/2 mapping mandates it — the direct
    // gRPC pool synthesizes it the same way), and a NATIVE gRPC response is
    // never buffered (a buffered `BackendResponse` has no trailer channel, so
    // buffering would silently drop `grpc-status`).
    //
    // gRPC-Web translated by the `grpc_web` plugin (codex r1-4) is
    // distinguished via the plugin's request-context marker — stamped only
    // after the plugin verified the ORIGINAL `application/grpc-web*`
    // content-type; the spoofable inbound header is stripped there. By
    // dispatch time its outbound content-type and body are wire-native gRPC,
    // so it shares the gRPC receive limit and `te: trailers`. Its response
    // normally stays streaming: the shared client-visible adapter converts the
    // backend's terminal trailers into one gRPC-Web DATA frame. If another
    // response policy explicitly requires buffering, the buffered arm below
    // retains the compatible whole-body transform.
    let is_grpc_flavored = headers
        .get("content-type")
        .is_some_and(|ct| backend_dispatch::is_native_grpc_content_type(ct.as_bytes()));
    let is_grpc_web_translated =
        is_grpc_flavored && crate::plugins::grpc_web::request_is_grpc_web_translated(request_ctx);
    let is_native_grpc = is_grpc_flavored && !is_grpc_web_translated;

    // Client end-to-end RPC deadline. Prefer the receipt-anchored monotonic
    // instant prepared by `grpc_deadline`; parsing the post-plugin header is
    // only a compatibility fallback for direct internal callers that did not
    // run the request preflight. Timeout regimes mirror the direct pool:
    //  * NATIVE gRPC (streams) — `streaming_effective_timeout_ms` semantics
    //    for `send_request` (upload + response-header wait): the client
    //    deadline UNCAPPED (it is the end-to-end budget, explicitly covering
    //    large uploads), falling back to `backend_read_timeout_ms` when the
    //    client set none. The response-BODY absolute deadline is applied by
    //    the caller's `StreamingH2` arm via `grpc_streaming_response_deadline`.
    //  * TRANSLATED gRPC-Web selected for buffering by another response policy
    //    — the buffered-path regime (F11): the client deadline is CAPPED by
    //    `backend_read_timeout_ms`, as ONE absolute deadline shared by
    //    `send_request` and body collection below (the deadline is end-to-end,
    //    so the phases share a single budget).
    //  * Plain HTTP — the per-phase `backend_read_timeout_ms`, unchanged.
    // Timing out a gRPC-flavored request returns the direct pool's
    // Trailers-Only DEADLINE_EXCEEDED instead of a JSON 504.
    let receipt_deadline_anchor = tokio::time::Instant::now();
    let client_grpc_deadline_at = if is_grpc_flavored {
        request_ctx.grpc_deadline_at().or_else(|| {
            headers
                .get("grpc-timeout")
                .and_then(|value| grpc_proxy::parse_grpc_timeout_value(value))
                .and_then(|ms| receipt_deadline_anchor.checked_add(Duration::from_millis(ms)))
        })
    } else {
        None
    };
    let request_body_limit = grpc_proxy::mesh_request_body_limit(
        is_grpc_flavored,
        state.max_request_body_size_bytes,
        state.max_grpc_recv_size_bytes,
    );
    if request_may_have_body(method, headers)
        && request_body_limit > 0
        && let Some(content_length) = headers.get("content-length")
        && let Ok(len) = content_length.parse::<usize>()
        && len > request_body_limit
    {
        // Mirror the direct gRPC path's oversize rejection shape (Trailers-Only
        // RESOURCE_EXHAUSTED) for gRPC-flavored requests; plain HTTP keeps the
        // 413. Both carry `ErrorClass::RequestBodyTooLarge` so backend-health
        // accounting stays NEUTRAL (the backend was never dialed).
        if is_grpc_flavored {
            return (
                grpc_proxy::grpc_request_body_too_large_backend_response(
                    &proxy.id,
                    resolved_ip,
                    Some(len),
                    request_body_limit,
                ),
                None,
                None,
            );
        }
        return (
            hbone_request_body_too_large_response(
                proxy,
                resolved_ip,
                Some(len),
                request_body_limit,
            ),
            None,
            None,
        );
    }

    // Native gRPC over sidecar mesh-mTLS can only be forwarded safely as a
    // streaming H2 response because `BackendResponse::Buffered` has no trailer
    // channel. If buffering is already known to be required for an
    // `application/grpc` response (explicit buffer mode or an active response
    // body plugin that would still need the body for that content-type), fail
    // before sending the RPC so an UNAVAILABLE response cannot duplicate
    // side effects through client retries. The post-header check below remains
    // as a defensive fallback for response-specific decisions.
    if is_native_grpc
        && native_grpc_mesh_mtls_buffering_conflict_known(
            stream_response,
            proxy,
            plugins,
            response_decision_ctx,
        )
    {
        warn!(
            proxy_id = %proxy.id,
            target_host = %target.host,
            "Refusing native gRPC over sidecar mesh mTLS before dispatch: response buffering \
             is required and would drop gRPC trailers"
        );
        return (
            mesh_grpc_response_buffering_refusal_response(200, resolved_ip),
            None,
            None,
        );
    }

    let mtls_port = mesh_mtls_pool::target_mesh_mtls_port(target);
    let get_sender = state.mesh_mtls_pool.get_sender(
        proxy,
        &target.host,
        target.port,
        target.dispatch_policy_port(),
        mtls_port,
        expected_peer.as_ref(),
        expected_trust_domain.as_ref(),
        sni_override,
    );
    let sender_result = if let Some(deadline) = client_grpc_deadline_at {
        match tokio::time::timeout_at(deadline, get_sender).await {
            Ok(result) => result,
            Err(_) => {
                return (
                    client_grpc_deadline_exceeded_response_for_request(
                        request_ctx,
                        headers,
                        resolved_ip,
                    ),
                    None,
                    None,
                );
            }
        }
    } else {
        get_sender.await
    };
    let mut sender = match sender_result {
        Ok(sender) => sender,
        Err(err) => {
            if is_grpc_flavored {
                let error_class = err.error_class();
                if error_class == retry::ErrorClass::PortExhaustion {
                    state.overload.record_port_exhaustion();
                }
                error!(
                    proxy_id = %proxy.id,
                    error_kind = retry::error_class_log_kind(error_class),
                    error = %err,
                    "sidecar mTLS gRPC pool request failed before dispatch"
                );
                return (
                    mesh_grpc_unavailable_response(
                        resolved_ip,
                        "sidecar mTLS backend unavailable",
                        error_class,
                    ),
                    None,
                    None,
                );
            }
            return (
                hbone_pool_error_response(state, proxy, &err, resolved_ip),
                None,
                None,
            );
        }
    };
    // Bound readiness by the connect budget: a pooled-but-saturated connection
    // (stream-cap reached) must not stall the request indefinitely.
    let connect_deadline = tokio::time::Instant::now()
        .checked_add(Duration::from_millis(proxy.backend_connect_timeout_ms));
    let ready_deadline = match (client_grpc_deadline_at, connect_deadline) {
        (Some(client), Some(connect)) => Some(client.min(connect)),
        (Some(client), None) => Some(client),
        (None, connect) => connect,
    };
    let ready_result = if let Some(deadline) = ready_deadline {
        tokio::time::timeout_at(deadline, sender.ready()).await
    } else {
        Ok(sender.ready().await)
    };
    match ready_result {
        Ok(Ok(())) => {}
        Ok(Err(err)) => {
            if is_grpc_flavored {
                error!(
                    proxy_id = %proxy.id,
                    error = %err,
                    "sidecar mTLS gRPC sender readiness failed before dispatch"
                );
                return (
                    mesh_grpc_unavailable_response(
                        resolved_ip,
                        "sidecar mTLS backend unavailable",
                        retry::ErrorClass::ConnectionPoolError,
                    ),
                    None,
                    None,
                );
            }
            return (
                hbone_hyper_error_response(proxy, err, resolved_ip),
                None,
                None,
            );
        }
        Err(_) => {
            warn!(
                proxy_id = %proxy.id,
                "sidecar mTLS HTTP/2 sender readiness timed out ({}ms)",
                proxy.backend_connect_timeout_ms
            );
            if is_grpc_flavored {
                if client_grpc_deadline_at
                    .is_some_and(|deadline| deadline <= tokio::time::Instant::now())
                {
                    return (
                        client_grpc_deadline_exceeded_response_for_request(
                            request_ctx,
                            headers,
                            resolved_ip,
                        ),
                        None,
                        None,
                    );
                }
                return (
                    mesh_grpc_unavailable_response(
                        resolved_ip,
                        "sidecar mTLS backend unavailable",
                        retry::ErrorClass::ConnectionTimeout,
                    ),
                    None,
                    None,
                );
            }
            return (
                retry::BackendResponse {
                    status_code: 504,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ConnectionTimeout),
                },
                None,
                None,
            );
        }
    }

    // Pool acquisition and sender readiness are connect work. Arm the
    // operator response-read window only after both complete; the client RPC
    // deadline remains receipt-anchored and therefore still caps the entire
    // operation. This matches the core/reqwest read-timeout contract.
    let read_started_at = tokio::time::Instant::now();
    let backend_read_deadline = if proxy.backend_read_timeout_ms > 0 {
        read_started_at.checked_add(Duration::from_millis(proxy.backend_read_timeout_ms))
    } else {
        None
    };
    let translated_grpc_web_may_buffer = is_grpc_web_translated && !stream_response;
    let grpc_send_deadline = match (client_grpc_deadline_at, backend_read_deadline) {
        (Some(client), Some(read)) if translated_grpc_web_may_buffer => Some(client.min(read)),
        (Some(client), _) => Some(client),
        (None, read) => read,
    };
    let grpc_send_deadline_is_client = client_grpc_deadline_at
        .is_some_and(|client| grpc_send_deadline.is_some_and(|effective| client <= effective));
    // A translated gRPC-Web response that another policy selected for
    // buffering shares one post-read-start operator window across request
    // dispatch and body collection. The normal streaming path carries the
    // receipt-anchored client deadline into the caller's H2 body wrapper.
    let buffered_grpc_shared_deadline = if translated_grpc_web_may_buffer {
        client_grpc_deadline_at
            .map(|client| backend_read_deadline.map_or(client, |read| client.min(read)))
    } else {
        None
    };
    let buffered_grpc_shared_deadline_is_client = client_grpc_deadline_at.is_some_and(|client| {
        buffered_grpc_shared_deadline.is_some_and(|effective| client <= effective)
    });

    let uri: hyper::Uri = match backend_url.parse() {
        Ok(uri) => uri,
        Err(e) => {
            error!(proxy_id = %proxy.id, error = %e, "Invalid sidecar mTLS backend URL");
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Invalid backend URL"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };
    let path_and_query = uri
        .path_and_query()
        .cloned()
        .unwrap_or_else(|| http::uri::PathAndQuery::from_static("/"));
    // `:authority` is the routing key on the peer: its materialized inbound
    // route matches the SERVICE host. A `sidecar`-topology mesh-SD target
    // (gateway-to-mesh bridge) carries that service host as a tag
    // (`mesh.mtls_authority_host`) and it takes precedence over BOTH branches
    // below — a north-south gateway's client Host is a public hostname the
    // peer would 404, and the no-preserve fallback is the pod dial address
    // (same 404). Otherwise a preserved client Host wins; without
    // preservation fall back to the dial authority (peer pod + app port),
    // matching the HBONE inner request's Host fallback. For a MULTI-PORT
    // destination the materializer stamped the owning service port on the
    // target, and the authority is rewritten to `<host>:<service_port>` —
    // the peer's inbound `:15006` dials are direct (never NATed, no
    // orig-dst), so the authority port is the only channel that tells its
    // per-port inbound siblings apart. The original client Host still rides
    // `x-forwarded-host` below. Single-port destinations carry no port tag
    // and keep the host-only / client authority byte-for-byte.
    let authority_owned;
    let authority =
        if let Some(service_host) = mesh_mtls_pool::target_mesh_mtls_authority_host(target) {
            match mesh_mtls_pool::target_mesh_mtls_authority_port(target) {
                Some(service_port) => {
                    authority_owned = format!("{service_host}:{service_port}");
                    authority_owned.as_str()
                }
                None => service_host,
            }
        } else if proxy.preserve_host_header
            && let Some(host) = headers.get("host")
            && !host.is_empty()
        {
            if let Some(service_port) = mesh_mtls_pool::target_mesh_mtls_authority_port(target) {
                authority_owned = mesh_mtls_request_authority(host, service_port);
                authority_owned.as_str()
            } else {
                host.as_str()
            }
        } else {
            authority_owned = hbone_pool::authority_for_host_port(&target.host, target.port);
            authority_owned.as_str()
        };
    let tunneled_uri = match hyper::Uri::builder()
        .scheme("https")
        .authority(authority)
        .path_and_query(path_and_query)
        .build()
    {
        Ok(uri) => uri,
        Err(e) => {
            error!(
                proxy_id = %proxy.id,
                authority,
                error = %e,
                "Invalid sidecar mTLS request authority"
            );
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Invalid backend authority"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };

    let (mut parts, body) = original_req.into_parts();
    let body_size_exceeded = Arc::new(std::sync::atomic::AtomicBool::new(false));
    // `request_body_limit` is flavor-aware (codex r1-3): the gRPC receive
    // limit for gRPC-flavored requests, the general request-body limit
    // otherwise — so a streamed gRPC upload trips at the same byte count as
    // the direct gRPC pool's size limiter.
    let max_request_body_size = if request_body_limit > 0 {
        request_body_limit
    } else {
        usize::MAX
    };
    let body = body::SizeLimitedIncoming::new_with_counter(
        body,
        max_request_body_size,
        Arc::clone(&body_size_exceeded),
        Arc::clone(ctx_bytes_sent_observed),
    );
    parts.uri = tunneled_uri;
    parts.version = hyper::Version::HTTP_2;
    parts.method = match parse_hyper_method(method) {
        Ok(method) => method,
        Err(()) => {
            warn_invalid_backend_method(&proxy.id, "mesh_mtls", method);
            return (
                retry::BackendResponse {
                    status_code: 405,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Method Not Allowed"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
                None,
            );
        }
    };
    parts.headers.clear();
    // Same inner-header hygiene as HBONE: client-supplied identity baggage is
    // stripped so a captured app cannot assert a forged source principal.
    let owned_mesh_headers =
        hbone_inner_headers_with_stripped_baggage(headers, &state.mesh_egress_strip_baggage_keys);
    let headers = owned_mesh_headers.as_ref().unwrap_or(headers);
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (k, v) in headers {
        match k.as_str() {
            // H2 carries the request host in `:authority` (set above); a
            // duplicate `host` header would trip the peer's host/authority
            // consistency check.
            "host" => continue,
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            _ => {
                insert_outbound_header_or_warn(
                    &mut parts.headers,
                    &proxy.id,
                    "mesh_mtls",
                    "client",
                    k,
                    v,
                );
            }
        }
    }

    // gRPC HTTP/2 mapping: requests MUST carry `te: trailers` (the only `te`
    // value HTTP/2 permits). The hop-by-hop strip above removes the client's
    // copy, so re-synthesize it for gRPC-flavored requests (native AND
    // gRPC-Web-translated — both are wire-native gRPC to the peer) —
    // mirroring `strip_backend_request_headers_for_grpc` on the direct gRPC
    // pool path, which serves both flavors the same way.
    if is_grpc_flavored {
        parts
            .headers
            .insert(http::header::TE, http::HeaderValue::from_static("trailers"));
    }

    let xff_val = build_xff_value(
        headers.get("x-forwarded-for").map(|s| s.as_str()),
        client_ip,
        xff_append_ip,
        &state.trusted_proxies,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "mesh_mtls",
        "generated_x_forwarded_for",
        "x-forwarded-for",
        &xff_val,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "mesh_mtls",
        "generated_x_forwarded_proto",
        "x-forwarded-proto",
        if request_is_secure { "https" } else { "http" },
    );
    if let Some(host) = headers.get("host") {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "mesh_mtls",
            "client_host_forwarded",
            "x-forwarded-host",
            host,
        );
    }
    if let Some(ref via) = state.via_header_http2 {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "mesh_mtls",
            "configured_via",
            "via",
            via,
        );
    }
    if state.add_forwarded_header {
        let proto_str = if request_is_secure { "https" } else { "http" };
        let fwd = build_forwarded_value(
            client_ip,
            proto_str,
            headers.get("host").map(|s| s.as_str()),
        );
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "mesh_mtls",
            "generated_forwarded",
            "forwarded",
            &fwd,
        );
    }

    let backend_req = Request::from_parts(parts, body);
    let send_fut = sender.send_request(backend_req);
    // `send_request` covers upload plus the response-header wait. The same
    // absolute RPC instant is reused; retries and earlier gateway work cannot
    // re-arm it by rewriting a relative header.
    let send_deadline = if is_grpc_flavored {
        grpc_send_deadline
    } else {
        backend_read_deadline
    };
    let send_result = if let Some(deadline) = send_deadline {
        match tokio::time::timeout_at(deadline, send_fut).await {
            Ok(result) => result,
            Err(_) => {
                if body_size_exceeded.load(Ordering::Acquire) {
                    return (
                        mesh_mtls_request_body_too_large_response(
                            proxy,
                            resolved_ip,
                            is_grpc_flavored,
                            request_body_limit,
                        ),
                        None,
                        None,
                    );
                }
                warn!(
                    proxy_id = %proxy.id,
                    timeout_ms = send_deadline
                        .map(|deadline| {
                            deadline
                                .saturating_duration_since(read_started_at)
                                .as_millis()
                        })
                        .unwrap_or(0),
                    is_grpc_flavored,
                    "sidecar mTLS timeout waiting for backend response"
                );
                // gRPC-flavored requests get the direct gRPC pool's timeout
                // shape (`GrpcProxyError::BackendTimeout` -> Trailers-Only
                // DEADLINE_EXCEEDED); plain HTTP keeps the JSON 504.
                if is_grpc_flavored {
                    return (
                        if grpc_send_deadline_is_client {
                            client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip,
                            )
                        } else {
                            mesh_grpc_deadline_exceeded_response(resolved_ip)
                        },
                        None,
                        None,
                    );
                }
                return (
                    retry::BackendResponse {
                        status_code: 504,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                    },
                    None,
                    None,
                );
            }
        }
    } else {
        send_fut.await
    };
    let response = match send_result {
        Ok(response) => response,
        Err(err) => {
            if body_size_exceeded.load(Ordering::Acquire) {
                return (
                    mesh_mtls_request_body_too_large_response(
                        proxy,
                        resolved_ip,
                        is_grpc_flavored,
                        request_body_limit,
                    ),
                    None,
                    None,
                );
            }
            return (
                if is_grpc_flavored {
                    mesh_grpc_unavailable_response(
                        resolved_ip,
                        "sidecar mTLS backend unavailable",
                        retry::ErrorClass::ProtocolError,
                    )
                } else {
                    hbone_hyper_error_response(proxy, err, resolved_ip)
                },
                None,
                None,
            );
        }
    };

    let status = response.status().as_u16();
    let content_length = response
        .headers()
        .get("content-length")
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.parse::<usize>().ok());
    if state.max_response_body_size_bytes > 0
        && let Some(len) = content_length
        && len > state.max_response_body_size_bytes
    {
        return (
            if is_grpc_flavored {
                mesh_grpc_response_body_too_large_response(
                    proxy,
                    resolved_ip,
                    Some(len),
                    state.max_response_body_size_bytes,
                )
            } else {
                hbone_response_body_too_large_response(
                    proxy,
                    resolved_ip,
                    Some(len),
                    state.max_response_body_size_bytes,
                )
            },
            None,
            None,
        );
    }
    let mut resp_headers = HashMap::with_capacity(response.headers().keys_len());
    collect_hyper_response_headers(response.headers(), &mut resp_headers);

    // Content-type-aware buffer -> stream downgrade (see `proxy_to_backend`).
    let stream_response = refine_stream_response_for_content_type(
        stream_response,
        proxy,
        plugins,
        response_decision_ctx,
        status,
        &resp_headers,
    );

    // NATIVE gRPC responses on this path MUST stream: a buffered
    // `BackendResponse` cannot re-emit wire trailers to the client, so
    // buffering a native gRPC response would silently drop `grpc-status`
    // and corrupt the RPC. If buffering is still demanded after the
    // content-type refinement (explicit `response_body_mode = Buffer`, or a
    // plugin that needs the body for this content-type), FAIL CLOSED with a
    // clear Trailers-Only refusal instead of forwarding a trailerless body
    // (fail-closed beats silently-wrong) or streaming past a plugin that
    // required the body (a silent policy bypass). This diverges from the
    // direct gRPC pool, whose buffered path collects AND re-emits trailers;
    // operators hitting this refusal should exempt the mesh gRPC route from
    // response-body buffering. Status 200 keeps circuit-breaker / passive
    // health accurate: the BACKEND responded fine — this is a gateway-side
    // policy conflict, not a backend fault.
    //
    // gRPC-Web translated by the `grpc_web` plugin is deliberately EXEMPT:
    // when another response policy requires buffering, its trailers can be
    // captured and body-framed by the compatible buffered transform below.
    // In the ordinary case `grpc_web` no longer requests buffering, so this
    // branch returns `StreamingH2` and the shared adapter body-frames trailers
    // incrementally at the client-visible boundary.
    if is_native_grpc && !stream_response {
        warn!(
            proxy_id = %proxy.id,
            target_host = %target.host,
            response_status = status,
            "Refusing to buffer a gRPC response over sidecar mesh mTLS: buffering would \
             drop gRPC trailers (grpc-status). Failing closed with gRPC UNAVAILABLE; \
             exempt this route from response-body buffering to restore gRPC dispatch"
        );
        return (
            mesh_grpc_response_buffering_refusal_response(status, resolved_ip),
            None,
            None,
        );
    }

    if stream_response {
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::StreamingH2(response),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            None,
            // Post-header client-upload overflow flag for the caller's
            // deferred admission/dispatch outcomes (codex r2-2 finding 5) —
            // mirrors `proxy_to_backend_hbone`'s streaming return.
            Some(body_size_exceeded),
        )
    } else {
        // Body-collection timeout regime: with the translated-gRPC-Web
        // shared deadline armed, the SAME absolute deadline that bounded
        // `send_request` bounds the collection (the client `grpc-timeout` is
        // end-to-end — one budget across both phases, per-read guard off),
        // mirroring the direct buffered gRPC path's `timeout_at` reuse.
        // Otherwise the per-read `backend_read_timeout_ms` stall guard
        // applies as before.
        let collect_fut = collect_hyper_body_and_trailers_with_limit(
            response.into_body(),
            state.max_response_body_size_bytes,
            if buffered_grpc_shared_deadline.is_some() {
                0
            } else {
                proxy.backend_read_timeout_ms
            },
        );
        let collect_result = if let Some(deadline) = buffered_grpc_shared_deadline {
            match tokio::time::timeout_at(deadline, collect_fut).await {
                Ok(result) => result,
                Err(_) => {
                    warn!(
                        proxy_id = %proxy.id,
                        deadline_source = if buffered_grpc_shared_deadline_is_client {
                            "client"
                        } else {
                            "backend_read_policy"
                        },
                        "sidecar mTLS gRPC-Web response body collection exceeded its shared deadline"
                    );
                    return (
                        if buffered_grpc_shared_deadline_is_client {
                            client_grpc_deadline_exceeded_response_for_request(
                                request_ctx,
                                headers,
                                resolved_ip,
                            )
                        } else {
                            mesh_grpc_deadline_exceeded_response(resolved_ip)
                        },
                        None,
                        None,
                    );
                }
            }
        } else {
            collect_fut.await
        };
        let (body_bytes, backend_trailers) = match collect_result {
            Ok(collected) => collected,
            Err(HyperBodyCollectError::TooLarge) => {
                return (
                    if is_grpc_flavored {
                        mesh_grpc_response_body_too_large_response(
                            proxy,
                            resolved_ip,
                            None,
                            state.max_response_body_size_bytes,
                        )
                    } else {
                        hbone_response_body_too_large_response(
                            proxy,
                            resolved_ip,
                            None,
                            state.max_response_body_size_bytes,
                        )
                    },
                    None,
                    None,
                );
            }
            Err(HyperBodyCollectError::Read(err)) => {
                if body_size_exceeded.load(Ordering::Acquire) {
                    return (
                        mesh_mtls_request_body_too_large_response(
                            proxy,
                            resolved_ip,
                            is_grpc_flavored,
                            request_body_limit,
                        ),
                        None,
                        None,
                    );
                }
                return (
                    if is_grpc_flavored {
                        mesh_grpc_unavailable_response(
                            resolved_ip,
                            "sidecar mTLS backend unavailable",
                            retry::ErrorClass::ProtocolError,
                        )
                    } else {
                        hbone_hyper_error_response(proxy, err, resolved_ip)
                    },
                    None,
                    None,
                );
            }
            Err(HyperBodyCollectError::ReadTimeout { timeout_ms }) => {
                warn!(
                    proxy_id = %proxy.id,
                    timeout_ms = timeout_ms,
                    "sidecar mTLS backend response body read timed out"
                );
                if is_grpc_flavored {
                    return (
                        mesh_grpc_deadline_exceeded_response(resolved_ip),
                        None,
                        None,
                    );
                }
                return (
                    retry::BackendResponse {
                        status_code: 504,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                    },
                    None,
                    None,
                );
            }
        };
        // A gRPC-Web-translated response reaches this arm only when another
        // response policy selected buffering. The compatible whole-body
        // transform re-encodes the backend's terminal trailers (`grpc-status` /
        // `grpc-message` / custom trailing metadata) into the gRPC-Web response
        // body, reading them from the response-header map. Fold the captured H2
        // trailers into the same merged
        // header+trailer view the direct gRPC pool's buffered path presents
        // to response hooks (hop-by-hop trailer names filtered; reserved gRPC
        // terminal keys trailer-authoritative, header-wins otherwise).
        // Without this merge the plugin would synthesize `grpc-status: 2`
        // (UNKNOWN) for every RPC, since a trailer-borne grpc-status would
        // never reach it. Scoped to the translated flavor: plain-HTTP
        // buffered responses keep their headers untouched.
        //
        // Also record trailer-name provenance so the body trailer frame embeds
        // only backend trailers (plus reserved terminal metadata), not
        // initial-header-only fields that happen to survive in the merged view.
        // This path only holds `&RequestContext`, so provenance rides an
        // internal response-header bridge that `grpc_web::after_proxy` promotes
        // into metadata and strips before the client sees the response.
        if is_grpc_web_translated {
            let mut backend_trailer_headers = HashMap::new();
            if let Some(trailer_map) = backend_trailers {
                grpc_proxy::collect_buffered_grpc_trailers(
                    &trailer_map,
                    &mut backend_trailer_headers,
                );
            }
            crate::plugins::grpc_web::bridge_backend_trailer_provenance_for_frame(
                &mut resp_headers,
                &backend_trailer_headers,
            );
            if !backend_trailer_headers.is_empty() {
                let (merged_view, _header_shadowed_trailer_keys) =
                    grpc_proxy::build_grpc_plugin_header_view(
                        &resp_headers,
                        &backend_trailer_headers,
                    );
                resp_headers = merged_view;
            }
        }
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::Buffered(body_bytes),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            None,
            None,
        )
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ResponseHeaderDeadlineSource {
    Client,
    Operator,
}

pub(crate) fn response_header_deadline(
    client_deadline: Option<tokio::time::Instant>,
    backend_read_timeout_ms: u64,
    read_started_at: tokio::time::Instant,
) -> Option<(tokio::time::Instant, ResponseHeaderDeadlineSource)> {
    let operator_deadline = if backend_read_timeout_ms > 0 {
        read_started_at.checked_add(Duration::from_millis(backend_read_timeout_ms))
    } else {
        None
    };
    match (client_deadline, operator_deadline) {
        (Some(client), Some(operator)) if client <= operator => {
            Some((client, ResponseHeaderDeadlineSource::Client))
        }
        (Some(_), Some(operator)) => Some((operator, ResponseHeaderDeadlineSource::Operator)),
        (Some(client), None) => Some((client, ResponseHeaderDeadlineSource::Client)),
        (None, Some(operator)) => Some((operator, ResponseHeaderDeadlineSource::Operator)),
        (None, None) => None,
    }
}

#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend_http2(
    state: &ProxyState,
    proxy: &Proxy,
    mut sender: crate::proxy::http2_pool::Http2Sender,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    original_req: Request<Incoming>,
    plugins: &[Arc<dyn crate::plugins::Plugin>],
    ctx: Option<&RequestContext>,
    grpc_deadline_at: Option<tokio::time::Instant>,
    stream_response: bool,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    resolved_ip: Option<String>,
    // Shared counter for request body bytes. SizeLimitedIncoming increments
    // this as frames are polled so summary builders observe streamed uploads
    // (not just Content-Length) once the response completes.
    ctx_bytes_sent_observed: &Arc<std::sync::atomic::AtomicU64>,
) -> (
    retry::BackendResponse,
    Option<Arc<std::sync::atomic::AtomicBool>>,
) {
    debug!(proxy_id = %proxy.id, backend_url = %strip_query_params(backend_url), "Proxying request via HTTP/2 pool");

    // Parse the backend URL
    let uri: hyper::Uri = match backend_url.parse() {
        Ok(u) => u,
        Err(e) => {
            error!(proxy_id = %proxy.id, error = %e, "Invalid backend URL");
            return (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Invalid backend URL"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
            );
        }
    };

    // Build hyper request
    let (mut parts, body) = original_req.into_parts();
    let body_size_exceeded = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let max_request_body_size = if state.max_request_body_size_bytes > 0 {
        state.max_request_body_size_bytes
    } else {
        usize::MAX
    };
    // Arm the cancellation channel unconditionally. `send_request` hands the
    // request body to hyper's detached HTTP/2 pipe task, so *any* early return
    // below leaves that task draining the client upload toward a response
    // nobody will read — whether or not a size limit is configured. Only the
    // completion channel (and therefore the response gate) is limit-gated.
    let (cancel_tx, cancel_rx) = tokio::sync::oneshot::channel();
    let mut body_cancel_tx = Some(cancel_tx);
    let (body, body_completion_rx) = if state.max_request_body_size_bytes > 0 {
        let (completion_tx, completion_rx) = tokio::sync::oneshot::channel();
        (
            body::SizeLimitedIncoming::new_with_counter_and_completion(
                body,
                max_request_body_size,
                Arc::clone(&body_size_exceeded),
                Arc::clone(ctx_bytes_sent_observed),
                completion_tx,
                cancel_rx,
            ),
            Some(completion_rx),
        )
    } else {
        (
            body::SizeLimitedIncoming::new_with_counter(
                body,
                max_request_body_size,
                Arc::clone(&body_size_exceeded),
                Arc::clone(ctx_bytes_sent_observed),
            )
            .with_cancel(cancel_rx),
            None,
        )
    };

    // Set the URI
    parts.uri = uri;

    // Set the method
    parts.method = match parse_hyper_method(method) {
        Ok(m) => m,
        Err(()) => {
            warn_invalid_backend_method(&proxy.id, "direct_h2", method);
            return (
                retry::BackendResponse {
                    status_code: 405,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Method Not Allowed"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: None,
                },
                None,
            );
        }
    };

    // Clear and rebuild headers from the plugin-processed headers map
    parts.headers.clear();
    let effective_host = &proxy.backend_host;
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (k, v) in headers {
        match k.as_str() {
            "host" => {
                if proxy.preserve_host_header {
                    insert_outbound_header_or_warn(
                        &mut parts.headers,
                        &proxy.id,
                        "direct_h2",
                        "client_host",
                        "host",
                        v,
                    );
                } else {
                    insert_outbound_header_or_warn(
                        &mut parts.headers,
                        &proxy.id,
                        "direct_h2",
                        "backend_host",
                        "host",
                        effective_host,
                    );
                }
            }
            // Hop-by-hop headers per RFC 9110 §7.6.1 (canonical predicate
            // in `proxy::headers`). The H2 direct pool now also strips
            // content-length: hyper frames the body via DATA frames so the
            // header is informational, and forwarding a stale upstream
            // value risked an authoritative-size mismatch with the framed
            // body when a request_transformer plugin mutated the body.
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            // Strip gateway-owned forwarding identity before regenerating it
            // below. `HeaderMap::insert` would replace, but keep the same
            // fail-closed ownership predicate as reqwest/H3 so a capability
            // flip cannot change which Forwarded element backends observe.
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            // RFC 9110 §7.6.1: also strip every header NAMED in the
            // request's `Connection` field — see `parse_connection_listed_from_str_map`.
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            _ => {
                insert_outbound_header_or_warn(
                    &mut parts.headers,
                    &proxy.id,
                    "direct_h2",
                    "client",
                    k,
                    v,
                );
            }
        }
    }

    // Add proxy-managed forwarding metadata.
    let xff_val = build_xff_value(
        headers.get("x-forwarded-for").map(|s| s.as_str()),
        client_ip,
        xff_append_ip,
        &state.trusted_proxies,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "direct_h2",
        "generated_x_forwarded_for",
        "x-forwarded-for",
        &xff_val,
    );
    insert_outbound_header_or_warn(
        &mut parts.headers,
        &proxy.id,
        "direct_h2",
        "generated_x_forwarded_proto",
        "x-forwarded-proto",
        if request_is_secure { "https" } else { "http" },
    );
    if let Some(host) = headers.get("host") {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "direct_h2",
            "client_host_forwarded",
            "x-forwarded-host",
            host,
        );
    }
    if let Some(ref via) = state.via_header_http2 {
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "direct_h2",
            "configured_via",
            "via",
            via,
        );
    }
    if state.add_forwarded_header {
        let proto_str = if request_is_secure { "https" } else { "http" };
        let fwd = build_forwarded_value(
            client_ip,
            proto_str,
            headers.get("host").map(|s| s.as_str()),
        );
        insert_outbound_header_or_warn(
            &mut parts.headers,
            &proxy.id,
            "direct_h2",
            "generated_forwarded",
            "forwarded",
            &fwd,
        );
    }

    let backend_req = Request::from_parts(parts, body);

    // Send to backend with read timeout (0 = no timeout)
    let h2_send_fut = sender.send_request(backend_req);
    let request_body_too_large = || {
        (
            retry::BackendResponse {
                status_code: 413,
                body: ResponseBody::Buffered(
                    r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip.clone(),
                error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
            },
            None,
        )
    };
    let map_h2_err = {
        let resolved_ip = resolved_ip.clone();
        let body_size_exceeded = Arc::clone(&body_size_exceeded);
        move |e: hyper::Error| {
            if body_size_exceeded.load(std::sync::atomic::Ordering::Acquire) {
                return (
                    retry::BackendResponse {
                        status_code: 413,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Request body exceeds maximum size"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                    },
                    None,
                );
            }
            error!(proxy_id = %proxy.id, error = %e, "HTTP/2 backend request failed");
            (
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Backend unavailable"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: true,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ProtocolError),
                },
                None,
            )
        }
    };
    let read_started_at = tokio::time::Instant::now();
    let header_deadline = response_header_deadline(
        grpc_deadline_at,
        proxy.backend_read_timeout_ms,
        read_started_at,
    );
    let response = if let Some((deadline, deadline_source)) = header_deadline {
        match tokio::time::timeout_at(deadline, h2_send_fut).await {
            Ok(Ok(resp)) => resp,
            Ok(Err(e)) => return map_h2_err(e),
            Err(_) => {
                // The request body already moved into hyper's detached HTTP/2
                // pipe task when `send_request` was called, so returning here
                // does not stop the upload. Wake the adapter so it yields an
                // error, resetting the backend stream and releasing the inbound
                // client body instead of streaming it into a request whose
                // response we have already abandoned. Best-effort: the signal
                // only lands the next time hyper polls the body, so a pipe
                // parked on backend send capacity tears down later (see the
                // `cancel` field docs on `SizeLimitedIncoming`).
                if let Some(cancel_tx) = body_cancel_tx.take() {
                    let _ = cancel_tx.send(());
                }
                if body_size_exceeded.load(std::sync::atomic::Ordering::Acquire) {
                    return request_body_too_large();
                }
                match deadline_source {
                    ResponseHeaderDeadlineSource::Client => {
                        return (
                            client_grpc_deadline_exceeded_response_for_optional_request(
                                ctx,
                                headers,
                                resolved_ip,
                            ),
                            None,
                        );
                    }
                    ResponseHeaderDeadlineSource::Operator => {
                        warn!(
                            proxy_id = %proxy.id,
                            "HTTP/2: read timeout ({}ms) waiting for backend response",
                            proxy.backend_read_timeout_ms
                        );
                        return (
                            retry::BackendResponse {
                                status_code: 504,
                                body: ResponseBody::Buffered(
                                    r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                                ),
                                headers: HashMap::new(),
                                // The request reached the H2 sender; this is a
                                // response-read failure, not a connect failure.
                                connection_error: false,
                                backend_resolved_ip: resolved_ip,
                                error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                            },
                            None,
                        );
                    }
                }
            }
        }
    } else {
        match h2_send_fut.await {
            Ok(resp) => resp,
            Err(e) => return map_h2_err(e),
        }
    };

    // HTTP/2 is full duplex: a backend may return response headers before it
    // has consumed the upload. Do not expose that response until the request
    // body adapter has made the configured size-limit decision authoritative.
    //
    // The channel is installed only when `max_request_body_size_bytes > 0`, and
    // limits-on requests reach direct-H2 only through a backend TLS SNI override
    // (`can_dispatch_direct_http2_pool` requires a zero limit otherwise). So the
    // gate — and the interleaving it gives up, a genuinely full-duplex non-gRPC
    // H2 app now sees response headers withheld until its upload terminates —
    // is scoped to SNI-override routes that have a request-size limit set.
    if let Some(body_completion_rx) = body_completion_rx {
        // The header phase has already spent its own deadline, so the upload
        // phase reuses the operator whole-upload stall guard composed with any
        // client RPC deadline. Without it a backend that answers early and then
        // stops reading the upload — or a client that stalls mid-body — would
        // pin this request open indefinitely.
        let upload_bound =
            compose_early_upload_bound(grpc_deadline_at, proxy.backend_read_timeout_ms);
        let outcome = match upload_bound {
            Some((upload_deadline, bound_kind)) => {
                match tokio::time::timeout_at(upload_deadline, body_completion_rx).await {
                    Ok(received) => received.ok(),
                    Err(_) => {
                        // `send_request` has already yielded response headers,
                        // so hyper moved the request body into a detached H2
                        // pipe task. Dropping this handler or the response does
                        // not cancel that upload: the pipe task holds its own
                        // `h2` stream reference, so the stream is not reset
                        // while it lives. Wake the adapter explicitly; its
                        // terminal error resets the backend stream and releases
                        // the inbound client body. Best-effort — a pipe parked
                        // on backend send capacity is not polling the body and
                        // tears down only once credit, a reset, or connection
                        // close arrives (see `SizeLimitedIncoming::cancel`).
                        if let Some(cancel_tx) = body_cancel_tx.take() {
                            let _ = cancel_tx.send(());
                        }
                        if body_size_exceeded.load(std::sync::atomic::Ordering::Acquire) {
                            return request_body_too_large();
                        }
                        return match bound_kind {
                            EarlyUploadBoundKind::RpcDeadline => (
                                client_grpc_deadline_exceeded_response_for_optional_request(
                                    ctx,
                                    headers,
                                    resolved_ip,
                                ),
                                None,
                            ),
                            EarlyUploadBoundKind::OperatorTimeout => {
                                warn!(
                                    proxy_id = %proxy.id,
                                    "HTTP/2: client upload did not finish within the whole-upload bound ({}ms) after backend response headers",
                                    proxy.backend_read_timeout_ms
                                );
                                (request_body_timeout_backend_response(resolved_ip), None)
                            }
                        };
                    }
                }
            }
            // Both bounds are disabled by configuration; preserve the existing
            // "0 = no timeout" contract shared with the buffered upload paths
            // and with the response-header wait just above. An operator who
            // sets `backend_read_timeout_ms = 0` and sends no RPC deadline
            // accepts that a backend which answers early and then stops reading
            // the upload holds this request until the client body terminates or
            // the connection drops. Do not add a hidden floor here — that would
            // silently break the documented contract.
            None => body_completion_rx.await.ok(),
        };
        // Normal completion: dropping the sender makes the adapter stop
        // polling the cancellation channel without changing its outcome.
        drop(body_cancel_tx.take());
        match classify_direct_h2_upload_outcome(outcome) {
            DirectH2UploadGate::Forward => {}
            DirectH2UploadGate::RequestBodyTooLarge => return request_body_too_large(),
            DirectH2UploadGate::FailClosed => {
                error!(
                    proxy_id = %proxy.id,
                    outcome = ?outcome,
                    "HTTP/2 request upload reported no terminal size decision; refusing to forward early backend response"
                );
                return (
                    retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend unavailable"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ProtocolError),
                    },
                    None,
                );
            }
        }
    }
    if body_size_exceeded.load(std::sync::atomic::Ordering::Acquire) {
        return request_body_too_large();
    }

    // Extract response status and headers
    let status = response.status().as_u16();
    let mut resp_headers = HashMap::with_capacity(response.headers().keys_len());
    collect_hyper_response_headers(response.headers(), &mut resp_headers);

    if let Some(len) =
        declared_response_length_exceeds_limit(&resp_headers, state.max_response_body_size_bytes)
    {
        warn!(
            proxy_id = %proxy.id,
            response_body_bytes = len,
            max_response_body_size_bytes = state.max_response_body_size_bytes,
            "HTTP/2 backend response body exceeds configured size limit"
        );
        return (
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"Backend response body exceeds maximum size"}"#
                        .as_bytes()
                        .to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
            },
            None,
        );
    }

    // Content-type-aware buffer -> stream downgrade (see `proxy_to_backend`).
    let stream_response = refine_stream_response_for_content_type(
        stream_response,
        proxy,
        plugins,
        ctx,
        status,
        &resp_headers,
    );

    if stream_response {
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::StreamingH2(response),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            Some(body_size_exceeded),
        )
    } else {
        // Buffer the full response body, enforcing the operator size cap.
        let collect = collect_hyper_body_with_limit(
            response.into_body(),
            state.max_response_body_size_bytes,
            proxy.backend_read_timeout_ms,
        );
        let collect_result =
            match crate::plugins::await_grpc_deadline(grpc_deadline_at, collect).await {
                Ok(result) => result,
                Err(()) => {
                    return (
                        client_grpc_deadline_exceeded_response_for_optional_request(
                            ctx,
                            headers,
                            resolved_ip,
                        ),
                        None,
                    );
                }
            };
        let body_bytes = match collect_result {
            Ok(collected) => collected,
            Err(HyperBodyCollectError::TooLarge) => {
                warn!(
                    proxy_id = %proxy.id,
                    max_response_body_size_bytes = state.max_response_body_size_bytes,
                    "HTTP/2 buffered body collection exceeded configured size limit"
                );
                return (
                    retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend response body exceeds maximum size"}"#
                                .as_bytes()
                                .to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                    },
                    None,
                );
            }
            Err(HyperBodyCollectError::Read(e)) => {
                error!(proxy_id = %proxy.id, error = %e, "Failed to read HTTP/2 response body");
                return (
                    retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Failed to read backend response"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ProtocolError),
                    },
                    None,
                );
            }
            Err(HyperBodyCollectError::ReadTimeout { timeout_ms }) => {
                warn!(
                    proxy_id = %proxy.id,
                    timeout_ms = timeout_ms,
                    "HTTP/2 backend response body read timed out"
                );
                return (
                    retry::BackendResponse {
                        status_code: 504,
                        body: ResponseBody::Buffered(
                            r#"{"error":"Backend timeout"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
                    },
                    None,
                );
            }
        };
        (
            retry::BackendResponse {
                status_code: status,
                body: ResponseBody::Buffered(body_bytes),
                headers: resp_headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            },
            None,
        )
    }
}

struct Http3BackendHeaderContext<'a> {
    client_ip: &'a str,
    xff_append_ip: &'a str,
    effective_host: &'a str,
    request_is_secure: bool,
    inbound_version: hyper::Version,
    content_length: Option<&'a str>,
}

fn build_http3_backend_headers(
    state: &ProxyState,
    proxy: &Proxy,
    headers: &HashMap<String, String>,
    ctx: Http3BackendHeaderContext<'_>,
) -> Vec<(hyper::header::HeaderName, hyper::header::HeaderValue)> {
    let mut http3_headers = Vec::with_capacity(headers.len() + 5);
    let connection_listed_strip = headers_mod::parse_connection_listed_from_str_map(headers);
    for (name, value) in headers {
        match name.as_str() {
            n if headers_mod::is_backend_request_strip_header(n) => continue,
            // RFC 9110 §7.6.1: also strip every header NAMED in the
            // request's `Connection` field. Hyper rejects `Connection` on
            // H2/H3 frames, but the materialised request map can carry it
            // when the client used H1 — strip on the way out so the H3
            // backend never sees the listed names.
            n if connection_listed_strip.iter().any(|s| s == n) => continue,
            // The gateway re-emits proxy-managed forwarding metadata below.
            // Do not let client-supplied values appear first on native H3
            // backend requests, where duplicate header ordering can make a
            // backend consume the spoofed value instead of Ferrum's canonical
            // value. Same fail-closed ownership as reqwest / direct-H2.
            n if headers_mod::is_proxy_owned_forwarding_header(n, state.add_forwarded_header) => {
                continue;
            }
            "host" => {
                // Apply per-route `preserve_host_header` override on the
                // first-attempt H3-native backend path. Mirrors
                // `proxy_to_backend_http3_retry`, the plain HTTP / direct
                // H2 / gRPC dispatch paths, and `build_h3_backend_headers`
                // (H3 frontend → H3 backend). Without this, an H2 frontend
                // that synthesized `host` from `:authority` (see the
                // `handle_proxy_request_inner` synthesis above) would
                // forward the client's external authority to an H3-native
                // backend even when `preserve_host_header == false`.
                let host_value = if proxy.preserve_host_header {
                    value.as_str()
                } else {
                    ctx.effective_host
                };
                if let Ok(hv) = host_value.parse::<hyper::header::HeaderValue>() {
                    http3_headers.push((hyper::header::HOST, hv));
                }
            }
            _ => {
                if let (Ok(header_name), Ok(header_value)) = (name.parse(), value.parse()) {
                    http3_headers.push((header_name, header_value));
                } else {
                    debug!("Skipping invalid HTTP/3 header: {}={}", name, value);
                }
            }
        }
    }

    if let Some(content_length) = ctx.content_length
        && let Ok(content_length) = content_length.parse()
    {
        http3_headers.push((hyper::header::CONTENT_LENGTH, content_length));
    }

    let xff = build_xff_value(
        headers.get("x-forwarded-for").map(String::as_str),
        ctx.client_ip,
        ctx.xff_append_ip,
        &state.trusted_proxies,
    );
    if let Ok(v) = xff.parse() {
        http3_headers.push((hyper::header::HeaderName::from_static("x-forwarded-for"), v));
    }
    let proto = if ctx.request_is_secure {
        "https"
    } else {
        "http"
    };
    if let Ok(v) = proto.parse() {
        http3_headers.push((
            hyper::header::HeaderName::from_static("x-forwarded-proto"),
            v,
        ));
    }
    if let Some(host) = headers.get("host")
        && let Ok(v) = host.parse()
    {
        http3_headers.push((
            hyper::header::HeaderName::from_static("x-forwarded-host"),
            v,
        ));
    }
    if let Some(via) = via_header_for_inbound_version(state, ctx.inbound_version)
        && let Ok(v) = via.parse()
    {
        http3_headers.push((hyper::header::HeaderName::from_static("via"), v));
    }
    if state.add_forwarded_header {
        let fwd = build_forwarded_value(
            ctx.client_ip,
            proto,
            headers.get("host").map(|s| s.as_str()),
        );
        if let Ok(v) = fwd.parse() {
            http3_headers.push((hyper::header::HeaderName::from_static("forwarded"), v));
        }
    }

    http3_headers
}

/// Proxy the request to an HTTP/3 backend.
#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend_http3(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    client_request_body: ClientRequestBody,
    plugins: &[Arc<dyn crate::plugins::Plugin>],
    mut ctx: Option<&mut RequestContext>,
    grpc_deadline_at: Option<tokio::time::Instant>,
    // Real, read-only request context for the response-side buffer->stream
    // downgrade (`refine_stream_response_for_content_type`). Distinct from
    // `ctx` above, which is the request-body-hook clone and is `None` for
    // response-only buffering plugins such as `compression` — so the refine
    // MUST read this, mirroring the reqwest / direct-H2 / HBONE paths. `None`
    // when retries are configured (a retry may replay the response body, so
    // every attempt stays buffered).
    response_decision_ctx: Option<&RequestContext>,
    upstream_target: Option<&UpstreamTarget>,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    inbound_version: hyper::Version,
    stream_request_body: bool,
    retain_request_body: bool,
    request_body_prepared: bool,
    stream_response: bool,
    ctx_bytes_sent_observed: &Arc<std::sync::atomic::AtomicU64>,
) -> (retry::BackendResponse, Option<Bytes>) {
    debug!(proxy_id = %proxy.id, backend_url = %strip_query_params(backend_url), "Proxying request to HTTP/3 backend");

    // Resolve backend IP from DNS cache for the effective host
    let effective_host = upstream_target
        .map(|t| t.host.as_str())
        .unwrap_or(&proxy.backend_host);
    // Enforce the backend egress policy for a literal-IP backend before dialing.
    // The native H3 pool self-resolves via `resolve_backend_addr_cached` — whose
    // literal fast path is canonical `IpAddr::parse` (non-canonical spellings go
    // to real DNS and are screened on the resolved address) — never reqwest's URL
    // parser, so use the canonical screen. The URL-canonicalizing one would
    // wrongly reject a legitimate all-numeric H3 backend hostname (`2852039166`).
    // (A denied literal reached via a reqwest fallback is re-screened on that
    // path's own `egress_literal_ip` guard.)
    if let Some(reason) = denied_literal_backend_or_dns_override_canonical(
        effective_host,
        proxy,
        &state.env_config.backend_allow_ips,
    ) {
        warn!(
            proxy_id = %proxy.id,
            backend = %effective_host,
            reason,
            "Backend egress policy denied literal-IP H3 backend; not dialing"
        );
        return (
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    br#"{"error":"backend address blocked by egress policy"}"#.to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: Some(effective_host.to_string()),
                error_class: Some(retry::ErrorClass::DispatchPolicyRejected),
            },
            None,
        );
    }
    let resolved_ip = state
        .dns_cache
        .resolve(
            effective_host,
            proxy.dns_override.as_deref(),
            proxy.dns_cache_ttl_seconds,
        )
        .await
        .ok()
        .map(|ip| ip.to_string());

    let client_request_body = if stream_request_body {
        match client_request_body {
            ClientRequestBody::Streaming(original_req) => {
                debug_assert!(
                    !retain_request_body,
                    "streaming HTTP/3 request body should not retain bytes for retries"
                );

                if state.max_request_body_size_bytes > 0
                    && let Some(content_length) = headers.get("content-length")
                    && let Ok(len) = content_length.parse::<usize>()
                    && len > state.max_request_body_size_bytes
                {
                    return (
                        retry::BackendResponse {
                            status_code: 413,
                            body: ResponseBody::Buffered(
                                r#"{"error":"Request body exceeds maximum size"}"#
                                    .as_bytes()
                                    .to_vec(),
                            ),
                            headers: HashMap::new(),
                            connection_error: false,
                            backend_resolved_ip: resolved_ip,
                            error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                        },
                        None,
                    );
                }

                let (_parts, body) = (*original_req).into_parts();
                let http3_headers = build_http3_backend_headers(
                    state,
                    proxy,
                    headers,
                    Http3BackendHeaderContext {
                        client_ip,
                        xff_append_ip,
                        effective_host,
                        request_is_secure,
                        inbound_version,
                        content_length: headers.get("content-length").map(String::as_str),
                    },
                );

                let h3_result = if let Some(target) = upstream_target {
                    let target_host = target.host.clone();
                    let target_port = target.port;
                    let connection_pool = state.connection_pool.clone();
                    let proxy_clone = proxy.clone();
                    state
                        .h3_pool
                        .request_with_target_streaming_incoming_body(
                            proxy,
                            &target_host,
                            target_port,
                            method,
                            backend_url,
                            &http3_headers,
                            body,
                            state.max_request_body_size_bytes,
                            Arc::clone(ctx_bytes_sent_observed),
                            move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                        )
                        .await
                } else {
                    let connection_pool = state.connection_pool.clone();
                    let proxy_clone = proxy.clone();
                    state
                        .h3_pool
                        .request_streaming_incoming_body(
                            proxy,
                            method,
                            backend_url,
                            &http3_headers,
                            body,
                            state.max_request_body_size_bytes,
                            Arc::clone(ctx_bytes_sent_observed),
                            move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                        )
                        .await
                };

                return match h3_result {
                    Ok(response) => {
                        // Now that the response headers are observable, run the
                        // same content-type buffer→stream downgrade the reqwest /
                        // direct-H2 paths perform: a `206`/`Content-Range`, SSE,
                        // or other release-eligible body streams through (backend
                        // trailers forwarded via `H3FrameSource`) instead of being
                        // buffered and capped by the response size limit. The
                        // streaming-incoming-body API already hands back the
                        // pre-drain headers + `recv_stream`, so only the refine
                        // call was missing on this branch.
                        let stream_response = refine_stream_response_for_content_type(
                            stream_response,
                            proxy,
                            plugins,
                            response_decision_ctx,
                            response.status,
                            &response.headers,
                        );
                        if stream_response {
                            (
                                h3_streaming_backend_response(
                                    response,
                                    proxy,
                                    resolved_ip,
                                    state.max_response_body_size_bytes,
                                ),
                                None,
                            )
                        } else {
                            (
                                drain_h3_streaming_response_to_buffered(
                                    response,
                                    state,
                                    proxy,
                                    method,
                                    backend_url,
                                    resolved_ip,
                                )
                                .await,
                                None,
                            )
                        }
                    }
                    Err(e) => {
                        let error_str = e.to_string();
                        if error_str.contains("exceeds maximum size") {
                            (
                                retry::BackendResponse {
                                    status_code: 413,
                                    body:
                                        ResponseBody::Buffered(
                                            r#"{"error":"Request body exceeds maximum size"}"#
                                                .as_bytes()
                                                .to_vec(),
                                        ),
                                    headers: HashMap::new(),
                                    connection_error: false,
                                    backend_resolved_ip: resolved_ip,
                                    error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                                },
                                None,
                            )
                        } else if error_str
                            .to_ascii_lowercase()
                            .contains("client disconnected while sending request body")
                        {
                            error!(
                                proxy_id = %proxy.id,
                                backend_url = %strip_query_params(backend_url),
                                error = %e,
                                "Client disconnected while sending request body (HTTP/3 streaming)"
                            );
                            (
                                retry::BackendResponse {
                                    status_code: 499,
                                    body: ResponseBody::Buffered(
                                        r#"{"error":"Client disconnected"}"#.as_bytes().to_vec(),
                                    ),
                                    headers: HashMap::new(),
                                    connection_error: false,
                                    backend_resolved_ip: resolved_ip,
                                    error_class: Some(retry::ErrorClass::ClientDisconnect),
                                },
                                None,
                            )
                        } else if e.is_read_timeout() {
                            // `backend_read_timeout_ms` expired waiting for
                            // response headers — surface 504 Backend timeout
                            // like the direct-H2 / HBONE read-timeout arms,
                            // not a generic 502.
                            warn!(
                                proxy_id = %proxy.id,
                                backend_url = %strip_query_params(backend_url),
                                error = %e,
                                "HTTP/3 backend read timeout waiting for response (streaming request body)"
                            );
                            (h3_read_timeout_backend_response(resolved_ip), None)
                        } else {
                            // `H3PoolError::request_on_wire()` is the
                            // authoritative body-on-wire signal: it is set
                            // to `true` once `send_request().await` succeeds
                            // on ANY internal pool attempt (sticky across
                            // cached → fallback → fresh-connect retries),
                            // and `false` otherwise. The error class adds
                            // no information beyond it for the
                            // connection_error decision and can disagree
                            // — e.g. a connect-phase QUIC reset is genuinely
                            // pre-wire but the string-heuristic fallback
                            // can classify it as `ConnectionReset` (which
                            // `request_reached_wire` treats as post-wire).
                            // ANDing the class here would silently skip
                            // `retry_on_connect_failure` for those cases.
                            // Trust the pool's typed signal.
                            let (error_kind, error_class) = classify_h3_pool_error(&e);
                            // A gateway-side egress denial (DispatchPolicyRejected)
                            // dialed no backend — override the pre-wire signal to
                            // keep it non-retryable + backend-health-neutral.
                            let is_conn_error = !e.request_on_wire()
                                && !matches!(
                                    error_class,
                                    retry::ErrorClass::DispatchPolicyRejected
                                );
                            record_port_exhaustion_if_class(&state.overload, error_class);
                            error!(
                                proxy_id = %proxy.id,
                                backend_url = %strip_query_params(backend_url),
                                error_kind = error_kind,
                                error = %e,
                                "HTTP/3 backend streaming request failed"
                            );
                            (
                                retry::BackendResponse {
                                    status_code: 502,
                                    body: ResponseBody::Buffered(
                                        r#"{"error":"HTTP/3 backend request failed"}"#
                                            .as_bytes()
                                            .to_vec(),
                                    ),
                                    headers: HashMap::new(),
                                    connection_error: is_conn_error,
                                    backend_resolved_ip: resolved_ip,
                                    error_class: Some(error_class),
                                },
                                None,
                            )
                        }
                    }
                };
            }
            other => other,
        }
    } else {
        client_request_body
    };

    let request_body = match client_request_body {
        ClientRequestBody::Buffered(buffered) => buffered.body,
        ClientRequestBody::Streaming(original_req) => {
            let (_parts, body) = (*original_req).into_parts();
            if state.max_request_body_size_bytes > 0 {
                if let Some(content_length) = headers.get("content-length")
                    && let Ok(len) = content_length.parse::<usize>()
                    && len > state.max_request_body_size_bytes
                {
                    return (
                        retry::BackendResponse {
                            status_code: 413,
                            body: ResponseBody::Buffered(
                                r#"{"error":"Request body exceeds maximum size"}"#
                                    .as_bytes()
                                    .to_vec(),
                            ),
                            headers: HashMap::new(),
                            connection_error: false,
                            backend_resolved_ip: resolved_ip,
                            error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                        },
                        None,
                    );
                }
                let limited = http_body_util::Limited::new(body, state.max_request_body_size_bytes);
                match collect_request_body_with_deadline(
                    limited.collect(),
                    grpc_deadline_at,
                    proxy.backend_read_timeout_ms,
                )
                .await
                {
                    Ok(Ok(collected)) => collected.to_bytes().to_vec(),
                    Ok(Err(_)) => {
                        return (
                            retry::BackendResponse {
                                status_code: 413,
                                body: ResponseBody::Buffered(
                                    r#"{"error":"Request body exceeds maximum size"}"#
                                        .as_bytes()
                                        .to_vec(),
                                ),
                                headers: HashMap::new(),
                                connection_error: false,
                                backend_resolved_ip: resolved_ip,
                                error_class: Some(retry::ErrorClass::RequestBodyTooLarge),
                            },
                            None,
                        );
                    }
                    Err(RequestBodyWaitError::TimedOut) => {
                        return (request_body_timeout_backend_response(resolved_ip), None);
                    }
                    Err(RequestBodyWaitError::DeadlineExceeded) => {
                        return (
                            client_grpc_deadline_exceeded_response_for_optional_request(
                                ctx.as_deref(),
                                headers,
                                resolved_ip,
                            ),
                            None,
                        );
                    }
                }
            } else {
                match collect_request_body_with_deadline(
                    body.collect(),
                    grpc_deadline_at,
                    proxy.backend_read_timeout_ms,
                )
                .await
                {
                    Ok(Ok(collected)) => collected.to_bytes().to_vec(),
                    Ok(Err(e)) => {
                        error!(
                            proxy_id = %proxy.id,
                            backend_url = %strip_query_params(backend_url),
                            error_kind = "client_disconnect",
                            error = %e,
                            "Client disconnected while sending request body (HTTP/3)"
                        );
                        return (
                            retry::BackendResponse {
                                status_code: 499,
                                body: ResponseBody::Buffered(
                                    r#"{"error":"Client disconnected"}"#.as_bytes().to_vec(),
                                ),
                                headers: HashMap::new(),
                                connection_error: false,
                                backend_resolved_ip: resolved_ip,
                                error_class: Some(retry::ErrorClass::ClientDisconnect),
                            },
                            None,
                        );
                    }
                    Err(RequestBodyWaitError::TimedOut) => {
                        return (request_body_timeout_backend_response(resolved_ip), None);
                    }
                    Err(RequestBodyWaitError::DeadlineExceeded) => {
                        return (
                            client_grpc_deadline_exceeded_response_for_optional_request(
                                ctx.as_deref(),
                                headers,
                                resolved_ip,
                            ),
                            None,
                        );
                    }
                }
            }
        }
    };

    // Prepared buffers have already contributed their raw client-visible
    // length before transformation. The buffer here may be larger after a
    // transform, so counting it again would turn bytes_sent into backend-wire
    // bytes instead of client-wire bytes.
    if !request_body_prepared {
        ctx_bytes_sent_observed.fetch_max(request_body.len() as u64, Ordering::Release);
    }

    let request_body = if request_body_prepared {
        request_body
    } else {
        let request_body = apply_request_body_plugins_with_context(
            plugins,
            ctx.as_deref_mut(),
            grpc_deadline_at,
            headers,
            request_body,
        )
        .await;
        match run_final_request_body_hooks(plugins, ctx, grpc_deadline_at, headers, &request_body)
            .await
        {
            PluginResult::Continue => {}
            reject @ PluginResult::Reject { .. } | reject @ PluginResult::RejectBinary { .. } => {
                return (
                    reject_result_to_backend_response(reject, resolved_ip.clone()),
                    None,
                );
            }
        }
        request_body
    };

    let request_content_length = if !request_body.is_empty() {
        Some(request_body.len().to_string())
    } else {
        None
    };
    let http3_headers = build_http3_backend_headers(
        state,
        proxy,
        headers,
        Http3BackendHeaderContext {
            client_ip,
            xff_append_ip,
            effective_host,
            request_is_secure,
            inbound_version,
            content_length: request_content_length.as_deref(),
        },
    );

    // `Bytes::from(Vec<u8>)` transfers ownership without copying. Convert
    // before the optional retain-clone so retain becomes a refcount bump
    // rather than a Vec deep copy on every retry-enabled request.
    let body_bytes: bytes::Bytes = request_body.into();
    let retained_body = if retain_request_body && !body_bytes.is_empty() {
        Some(body_bytes.clone())
    } else {
        None
    };

    if stream_response {
        let h3_result = if let Some(target) = upstream_target {
            let target_host = target.host.clone();
            let target_port = target.port;
            let connection_pool = state.connection_pool.clone();
            let proxy_clone = proxy.clone();
            state
                .h3_pool
                .request_with_target_streaming(
                    proxy,
                    &target_host,
                    target_port,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        } else {
            let connection_pool = state.connection_pool.clone();
            let proxy_clone = proxy.clone();
            state
                .h3_pool
                .request_streaming(
                    proxy,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        };

        match h3_result {
            Ok(response) => (
                h3_streaming_backend_response(
                    response,
                    proxy,
                    resolved_ip,
                    state.max_response_body_size_bytes,
                ),
                retained_body,
            ),
            Err(e) => {
                if e.is_read_timeout() {
                    // `backend_read_timeout_ms` expired waiting for response
                    // headers — surface 504 Backend timeout like the
                    // direct-H2 / HBONE read-timeout arms, not a generic 502.
                    warn!(
                        proxy_id = %proxy.id,
                        backend_url = %strip_query_params(backend_url),
                        error = %e,
                        "HTTP/3 backend read timeout waiting for response (streaming response)"
                    );
                    return (h3_read_timeout_backend_response(resolved_ip), retained_body);
                }
                // Trust the pool's body-on-wire signal — see the
                // streaming-incoming-body branch above for why we drop
                // the error-class contribution here.
                let (error_kind, error_class) = classify_h3_pool_error(&e);
                // A gateway-side egress denial (DispatchPolicyRejected) dialed no
                // backend, so override the pool's pre-wire signal to keep it
                // non-retryable + backend-health-neutral. This is the ONE class
                // safe to AND with the typed `request_on_wire` signal — it is a
                // gateway rejection, not a transport class that could disagree.
                let is_conn_error = !e.request_on_wire()
                    && !matches!(error_class, retry::ErrorClass::DispatchPolicyRejected);
                record_port_exhaustion_if_class(&state.overload, error_class);
                error!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    error_kind = error_kind,
                    error = %e,
                    "HTTP/3 backend streaming request failed"
                );
                (
                    retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(
                            r#"{"error":"HTTP/3 backend request failed"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: is_conn_error,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(error_class),
                    },
                    retained_body,
                )
            }
        }
    } else {
        // The base decision was to buffer (a response-body plugin such as
        // `compression` is active), but call the STREAMING H3 API anyway: it
        // returns the response headers + `recv_stream` BEFORE draining, so the
        // same `refine_stream_response_for_content_type` downgrade the reqwest /
        // direct-H2 paths run can fire here too. A `206`/`Content-Range`, SSE, or
        // other release-eligible body then streams through — forwarding backend
        // trailers via `H3FrameSource` — instead of being fully buffered and
        // capped by the response size limit (which previously turned large ranged
        // H3-backend downloads into `502 ResponseBodyTooLarge`). When the refine
        // keeps the buffered decision, `drain_h3_streaming_response_to_buffered`
        // drains the body with the same incremental size enforcement the pool's
        // `request()` applied internally.
        let h3_result = if let Some(target) = upstream_target {
            let target_host = target.host.clone();
            let target_port = target.port;
            let connection_pool = state.connection_pool.clone();
            let proxy_clone = proxy.clone();
            state
                .h3_pool
                .request_with_target_streaming(
                    proxy,
                    &target_host,
                    target_port,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        } else {
            let connection_pool = state.connection_pool.clone();
            let proxy_clone = proxy.clone();
            state
                .h3_pool
                .request_streaming(
                    proxy,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        };

        match h3_result {
            Ok(response) => {
                let stream_response = refine_stream_response_for_content_type(
                    stream_response,
                    proxy,
                    plugins,
                    response_decision_ctx,
                    response.status,
                    &response.headers,
                );
                if stream_response {
                    (
                        h3_streaming_backend_response(
                            response,
                            proxy,
                            resolved_ip,
                            state.max_response_body_size_bytes,
                        ),
                        retained_body,
                    )
                } else {
                    (
                        drain_h3_streaming_response_to_buffered(
                            response,
                            state,
                            proxy,
                            method,
                            backend_url,
                            resolved_ip,
                        )
                        .await,
                        retained_body,
                    )
                }
            }
            Err(e) => {
                if e.is_read_timeout() {
                    // `backend_read_timeout_ms` expired waiting for response
                    // headers (`recv_response`) — surface 504 Backend timeout
                    // like the direct-H2 / HBONE read-timeout arms, not a
                    // generic 502. Body-drain timeouts surface separately
                    // inside `drain_h3_streaming_response_to_buffered`.
                    warn!(
                        proxy_id = %proxy.id,
                        backend_url = %strip_query_params(backend_url),
                        error = %e,
                        "HTTP/3 backend read timeout waiting for response (buffered)"
                    );
                    return (h3_read_timeout_backend_response(resolved_ip), retained_body);
                }
                // Trust the pool's body-on-wire signal — see the streaming
                // H3 branch above for why we drop the class contribution.
                let (error_kind, error_class) = classify_h3_pool_error(&e);
                // A gateway-side egress denial (DispatchPolicyRejected) dialed no
                // backend, so override the pool's pre-wire signal to keep it
                // non-retryable + backend-health-neutral. This is the ONE class
                // safe to AND with the typed `request_on_wire` signal — it is a
                // gateway rejection, not a transport class that could disagree.
                let is_conn_error = !e.request_on_wire()
                    && !matches!(error_class, retry::ErrorClass::DispatchPolicyRejected);
                record_port_exhaustion_if_class(&state.overload, error_class);
                error!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    error_kind = error_kind,
                    error = %e,
                    "HTTP/3 backend request failed"
                );
                (
                    retry::BackendResponse {
                        status_code: 502,
                        body: ResponseBody::Buffered(
                            r#"{"error":"HTTP/3 backend request failed"}"#.as_bytes().to_vec(),
                        ),
                        headers: HashMap::new(),
                        connection_error: is_conn_error,
                        backend_resolved_ip: resolved_ip,
                        error_class: Some(error_class),
                    },
                    retained_body,
                )
            }
        }
    }
}

/// Build the [`retry::BackendResponse`] for an H3 backend response that has
/// been chosen to stream downstream (`StreamingH3`), applying the declared-
/// `Content-Length` pre-stream size check (mirroring the reqwest retry path's
/// pre-stream reject). Returns the size-limit `502` when the declared length
/// exceeds the configured cap.
///
/// `headers` is left empty intentionally: the sole dispatch caller
/// (`backend_dispatch` site in `handle_proxy_request_inner`) moves the headers
/// out of the `StreamingH3` payload via `std::mem::take(&mut h3_resp.headers)`
/// rather than cloning the map per request. Backend response trailers ride
/// along on the streamed `recv_stream` and are forwarded — with hop-by-hop
/// trailer names stripped — by [`crate::proxy::body::H3FrameSource`], so both
/// H1 (chunked trailers) and H2 (trailers frame) downstream clients receive
/// them.
///
/// Native-H3 streaming responses use the same per-frame
/// `backend_read_timeout_ms` idle regime as direct-H2 streaming responses, so a
/// backend that sends headers and then stalls is cut by the response-body
/// wrapper instead of waiting for the QUIC idle timeout. Streamable H3 statuses
/// also defer CB / passive-health dispatch accounting to body completion; a
/// declared `Content-Length` lets the drop safety net treat a body dropped after
/// yielding the full byte count as a success instead of a false client
/// disconnect.
fn h3_streaming_backend_response(
    response: crate::http3::client::H3StreamingResponse,
    proxy: &Proxy,
    resolved_ip: Option<String>,
    max_response_body_size_bytes: usize,
) -> retry::BackendResponse {
    if let Some(len) =
        declared_response_length_exceeds_limit(&response.headers, max_response_body_size_bytes)
    {
        return h3_response_body_too_large_response(
            proxy,
            resolved_ip,
            Some(len),
            max_response_body_size_bytes,
        );
    }
    debug!(
        proxy_id = %proxy.id,
        status = response.status,
        "HTTP/3 backend streaming request successful"
    );
    retry::BackendResponse {
        status_code: response.status,
        body: ResponseBody::StreamingH3(Box::new(response)),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: None,
    }
}

/// Drain a fully-headers-received
/// [`H3StreamingResponse`](crate::http3::client::H3StreamingResponse) into a
/// buffered [`retry::BackendResponse`], enforcing `max_response_body_size_bytes`
/// incrementally and mapping drain failures exactly as the rest of the H3
/// dispatcher does: oversized → `502` `ResponseBodyTooLarge`, read timeout →
/// `504`, mid-body protocol fault → `502`.
///
/// Backend response trailers (the second tuple element from
/// [`drain_h3_response_body`](crate::http3::client::drain_h3_response_body)) are
/// dropped on this buffered path: `ResponseBody::Buffered` cannot carry them and
/// the buffered decision is only reached when a response-body plugin needs the
/// full body (plugins cannot inspect trailers today). The streaming path
/// ([`h3_streaming_backend_response`]) forwards them instead.
///
/// A mid-body `Stream` fault is classified with [`classify_h3_error`] on the raw
/// `h3::error::StreamError` (not `classify_h3_pool_error`) because a close
/// mid-body is a real protocol fault — the backend signalled completion but
/// truncated the response — matching the streaming-incoming-body drain site.
async fn drain_h3_streaming_response_to_buffered(
    response: crate::http3::client::H3StreamingResponse,
    state: &ProxyState,
    proxy: &Proxy,
    method: &str,
    backend_url: &str,
    resolved_ip: Option<String>,
) -> retry::BackendResponse {
    let status = response.status;
    let response_headers = response.headers;
    let mut recv_stream = response.recv_stream;
    let content_length: Option<u64> = response_headers
        .get("content-length")
        .and_then(|v| v.parse().ok());

    match crate::http3::client::drain_h3_response_body(
        &mut recv_stream,
        method,
        status,
        content_length,
        state.max_response_body_size_bytes,
        proxy.backend_read_timeout_ms,
    )
    .await
    {
        Ok((body, _trailers)) => retry::BackendResponse {
            status_code: status,
            body: ResponseBody::Buffered(body),
            headers: response_headers,
            connection_error: false,
            backend_resolved_ip: resolved_ip,
            error_class: None,
        },
        Err(crate::http3::client::H3BodyDrainError::ResponseTooLarge { .. }) => {
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                max_response_body_size_bytes = state.max_response_body_size_bytes,
                "HTTP/3 backend response body exceeded configured maximum"
            );
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"Backend response body exceeds maximum size"}"#
                        .as_bytes()
                        .to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
            }
        }
        Err(crate::http3::client::H3BodyDrainError::ReadTimeout { timeout_ms }) => {
            warn!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                timeout_ms = timeout_ms,
                "HTTP/3 backend buffered response read timed out"
            );
            h3_read_timeout_backend_response(resolved_ip)
        }
        Err(crate::http3::client::H3BodyDrainError::Stream(e)) => {
            let (error_kind, error_class) = classify_h3_error(&e);
            record_port_exhaustion_if_class(&state.overload, error_class);
            // Headers were already received and the body read started — the
            // request was on the wire and the backend processed it.
            // `connection_error=false` so a mid-body QUIC failure does not
            // bypass `retry_on_methods`. Graceful close after a complete body
            // is recovered inside `drain_h3_response_body` and never reaches
            // here.
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                error_kind = error_kind,
                error = %e,
                "HTTP/3 backend buffered response read failed"
            );
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"HTTP/3 backend request failed"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(error_class),
            }
        }
        Err(crate::http3::client::H3BodyDrainError::Truncated { received, declared }) => {
            // The backend FIN'd before delivering its declared Content-Length —
            // a framing violation. The request was on the wire and the backend
            // responded, so `connection_error=false` (respect `retry_on_methods`);
            // `ConnectionClosed` is a post-wire backend failure, so the dispatch
            // outcome trips CB / passive-health rather than banking a short body
            // as a success.
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                received = received,
                declared = ?declared,
                "HTTP/3 backend buffered response truncated (FIN before declared Content-Length)"
            );
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"HTTP/3 backend response truncated"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: Some(retry::ErrorClass::ConnectionClosed),
            }
        }
    }
}

/// Classify an HTTP/3/QUIC error into (error_kind_label, ErrorClass).
///
/// Called only on the error path — not hot path. Thin wrapper around
/// [`crate::http3::client::classify_http3_error`] so the H3 backend
/// dispatcher and the H3 backend pool agree byte-for-byte on the
/// classification of the same error chain. The shared classifier already
/// orders specific QUIC / h3 protocol tokens (`reset_stream`, `goaway`,
/// `applicationclose`, `h3_*`) BEFORE the bare `"reset"`/`"closed"`
/// substrings so a stream-level RESET_STREAM is no longer misclassified
/// as a connection-level `ConnectionReset`. It also avoids the bare
/// `"stream"` substring match that previously matched `"upstream"` (e.g.
/// in load-balancer error messages) and mislabeled them as protocol errors.
///
/// `connection_error: bool` is NOT returned here — callers derive it via
/// [`retry::request_reached_wire`] so the boundary between connect-class
/// failures (eligible for `retry_on_connect_failure`) and post-wire
/// failures (must respect `retry_on_methods`) lives in exactly one place.
fn classify_h3_error(err: &(dyn std::error::Error + 'static)) -> (&'static str, retry::ErrorClass) {
    let class = crate::http3::client::classify_http3_error(err);
    (retry::error_class_log_kind(class), class)
}

/// Bump the `port_exhaustion_events` counter when `class` is
/// [`retry::ErrorClass::PortExhaustion`].
///
/// Used by the native HTTP/3 dispatch sites (
/// [`proxy_to_backend_http3`] / [`proxy_to_backend_http3_retry`] in this
/// module, plus the H3 frontend → H3 backend fast paths in
/// [`crate::http3::server`]) to bring the H3 native paths in line with
/// the reqwest path ([`mod@crate::proxy`] line 8113-style sites), the
/// gRPC pool, the H2 pool, the TCP backend connect, and the H3
/// cross-protocol bridge — all of which already record port exhaustion
/// when their per-protocol classifier returns `PortExhaustion`. Without
/// this, `/overload.port_exhaustion_events` undercounts whenever a
/// QUIC/H3 dispatch hits ephemeral-port exhaustion (typically
/// EADDRNOTAVAIL on Linux, EADDRINUSE on macOS) at high RPS.
///
/// Returns `true` when the counter was bumped — used by unit tests to
/// assert the wiring without re-creating a full H3 classification
/// pipeline.
pub(crate) fn record_port_exhaustion_if_class(
    overload: &crate::overload::OverloadState,
    class: retry::ErrorClass,
) -> bool {
    if matches!(class, retry::ErrorClass::PortExhaustion) {
        overload.record_port_exhaustion();
        true
    } else {
        false
    }
}

/// Classifier overload for [`crate::http3::client::H3PoolError`] that
/// honors the typed `is_graceful_close()` signal before falling back to
/// the shared error-chain classifier.
///
/// The recv_response error sites in [`crate::http3::client`] flag
/// `H3_NO_ERROR` `ApplicationClose` / GOAWAY via the dedicated
/// [`crate::http3::client::H3PoolError::graceful_close`] constructor.
/// Surfacing those as [`retry::ErrorClass::GracefulRemoteClose`] keeps
/// `is_h3_transport_error_class` returning false so the cached H3
/// capability stays `Supported` even though the in-flight request must
/// 502 (no headers were available to forward).
///
/// The recv_data Err path at the buffered streaming-incoming-body site
/// uses a raw [`h3::error::StreamError`] rather than `H3PoolError` —
/// classification there stays on [`classify_h3_error`] because a close
/// mid-body is a real protocol fault (the backend signaled completion
/// but truncated the response), not a spec-legal teardown.
fn classify_h3_pool_error(
    e: &crate::http3::client::H3PoolError,
) -> (&'static str, retry::ErrorClass) {
    // A DnsCacheResolver egress-policy denial (hostname resolving/rebinding to a
    // blocked IP) surfaces in the pool error message as "...denied by backend
    // egress policy...". Classify it as the non-retryable, health-neutral
    // DispatchPolicyRejected — the dispatch sites pair this with a
    // `request_on_wire`-based `is_conn_error` override so it is neither retried
    // nor charged to backend health (no backend was dialed).
    if format!("{e:?}").contains("egress policy") {
        let class = retry::ErrorClass::DispatchPolicyRejected;
        return (retry::error_class_log_kind(class), class);
    }
    if e.is_graceful_close() {
        let class = retry::ErrorClass::GracefulRemoteClose;
        return (retry::error_class_log_kind(class), class);
    }
    if e.is_read_timeout() {
        // Typed `backend_read_timeout_ms` deadline signal from the pool —
        // classify deterministically instead of relying on the "timeout"
        // substring fallback in the shared classifier. `ReadWriteTimeout`
        // is excluded from `is_h3_transport_error_class`, so this never
        // drives `mark_h3_unsupported`.
        let class = retry::ErrorClass::ReadWriteTimeout;
        return (retry::error_class_log_kind(class), class);
    }
    classify_h3_error(e.as_ref())
}

/// Build the 502 returned when an H3 backend response body exceeds
/// `max_response_body_size_bytes`. `connection_error` stays `false` (the
/// request demonstrably reached the backend) and the
/// `ResponseBodyTooLarge` class is excluded from
/// `is_h3_transport_error_class`, so this never downgrades the cached H3
/// capability.
fn h3_response_body_too_large_response(
    proxy: &Proxy,
    resolved_ip: Option<String>,
    observed_size: Option<usize>,
    max_size: usize,
) -> retry::BackendResponse {
    match observed_size {
        Some(size) => warn!(
            proxy_id = %proxy.id,
            response_body_bytes = size,
            max_response_body_size_bytes = max_size,
            "HTTP/3 backend response body exceeds configured size limit"
        ),
        None => warn!(
            proxy_id = %proxy.id,
            max_response_body_size_bytes = max_size,
            "HTTP/3 backend response body exceeded configured size limit while streaming"
        ),
    }
    retry::BackendResponse {
        status_code: 502,
        body: ResponseBody::Buffered(
            r#"{"error":"Backend response body exceeds maximum size"}"#
                .as_bytes()
                .to_vec(),
        ),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
    }
}

/// Fast-path size check on the declared `Content-Length` of a backend
/// response, mirroring the reqwest retry path's pre-stream reject. Returns
/// the declared length when it exceeds a nonzero limit.
fn declared_response_length_exceeds_limit(
    headers: &HashMap<String, String>,
    max_response_body_size_bytes: usize,
) -> Option<usize> {
    if max_response_body_size_bytes == 0 {
        return None;
    }
    let len = headers
        .get("content-length")
        .and_then(|value| value.parse::<usize>().ok())?;
    (len > max_response_body_size_bytes).then_some(len)
}

/// Build the 504 `BackendResponse` for an H3 backend read timeout
/// (`backend_read_timeout_ms` expired waiting for response headers via
/// `recv_response()` or buffered body frames via `recv_data()`).
///
/// Mirrors the direct-H2 / HBONE / sidecar-mTLS read-timeout arms so the
/// same proxy config produces the same client-visible outcome regardless
/// of dispatch path: 504 + `{"error":"Backend timeout"}` +
/// `ErrorClass::ReadWriteTimeout`. `connection_error=false` — the request
/// reached the backend's application layer (post-wire), so
/// `retry_on_connect_failure` must not replay it; retries are governed by
/// `retry_on_methods` / `retryable_status_codes`.
fn h3_read_timeout_backend_response(resolved_ip: Option<String>) -> retry::BackendResponse {
    retry::BackendResponse {
        status_code: 504,
        body: ResponseBody::Buffered(r#"{"error":"Backend timeout"}"#.as_bytes().to_vec()),
        headers: HashMap::new(),
        connection_error: false,
        backend_resolved_ip: resolved_ip,
        error_class: Some(retry::ErrorClass::ReadWriteTimeout),
    }
}

/// Replay a saved HTTP/3 request to an explicit target (used during retries).
///
/// Accepts pre-collected body bytes, method, URI, and headers so the original
/// `Request<Incoming>` body (already consumed) can be replayed. Mirrors the
/// pattern used by `proxy_to_backend_retry` for HTTP/1.1.
#[allow(clippy::too_many_arguments)]
async fn proxy_to_backend_http3_retry(
    state: &ProxyState,
    proxy: &Proxy,
    backend_url: &str,
    method: &str,
    headers: &HashMap<String, String>,
    upstream_target: Option<&UpstreamTarget>,
    request_body: Option<&[u8]>,
    stream_response: bool,
    plugins: &[Arc<dyn Plugin>],
    request_ctx: &RequestContext,
    client_ip: &str,
    xff_append_ip: &str,
    request_is_secure: bool,
    inbound_version: hyper::Version,
) -> retry::BackendResponse {
    // reqwest dispatch receives `upstream_target` separately, so it only
    // needs per-port timeout rebasing. gRPC/direct-H2 pool paths use
    // `resolve_backend_connection_proxy_for_target` because their pool key and
    // dial target come from `proxy.backend_host` / `proxy.backend_port`.
    let effective_proxy = resolve_effective_proxy_for_target(proxy, upstream_target);
    let proxy: &Proxy = effective_proxy.as_ref();

    let effective_host = upstream_target
        .map(|t| t.host.as_str())
        .unwrap_or(&proxy.backend_host);
    let effective_port = upstream_target
        .map(|t| t.port)
        .unwrap_or(proxy.backend_port);

    // Re-screen the (possibly LB-rotated) retry target: the native H3 pool
    // self-resolves via `resolve_backend_addr_cached` (canonical `IpAddr` fast
    // path; non-canonical → real DNS + resolved-address screen), so use the
    // canonical screen, mirroring the first-attempt H3 screen — the
    // URL-canonicalizing one would wrongly reject a legitimate all-numeric
    // hostname reached via rotation.
    if denied_literal_backend_ip_canonical(effective_host, &state.env_config.backend_allow_ips)
        .is_some()
    {
        return backend_egress_denied_response(effective_host);
    }

    let resolved_ip = state
        .dns_cache
        .resolve(
            effective_host,
            proxy.dns_override.as_deref(),
            proxy.dns_cache_ttl_seconds,
        )
        .await
        .ok()
        .map(|ip| ip.to_string());

    let http3_headers = build_http3_backend_headers(
        state,
        proxy,
        headers,
        Http3BackendHeaderContext {
            client_ip,
            xff_append_ip,
            effective_host,
            request_is_secure,
            inbound_version,
            content_length: None,
        },
    );

    let body_bytes = bytes::Bytes::copy_from_slice(request_body.unwrap_or(&[]));
    let may_release_after_headers =
        !stream_response && plugins_may_release_response_body_under_retries(plugins, request_ctx);
    let retry_ctx = may_release_after_headers.then(|| retry_response_decision_context(request_ctx));

    if stream_response || may_release_after_headers {
        let connection_pool = state.connection_pool.clone();
        let proxy_clone = proxy.clone();
        let h3_result = if let Some(target) = upstream_target {
            let target_host = target.host.clone();
            let target_port = target.port;
            state
                .h3_pool
                .request_with_target_streaming(
                    proxy,
                    &target_host,
                    target_port,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        } else {
            state
                .h3_pool
                .request_streaming(
                    proxy,
                    method,
                    backend_url,
                    &http3_headers,
                    body_bytes,
                    move || connection_pool.get_tls_config_for_backend(&proxy_clone),
                )
                .await
        };

        return match h3_result {
            Ok(mut response) => {
                // Fast path: reject before streaming when the declared
                // Content-Length exceeds the configured response size limit —
                // mirrors the reqwest retry path's pre-stream reject. Without
                // this a streaming retry attempt would forward an
                // oversized declared body unguarded (the downstream H3 body
                // builder only size-limits when Content-Length is absent).
                if let Some(len) = declared_response_length_exceeds_limit(
                    &response.headers,
                    state.max_response_body_size_bytes,
                ) {
                    return h3_response_body_too_large_response(
                        proxy,
                        resolved_ip,
                        Some(len),
                        state.max_response_body_size_bytes,
                    );
                }
                let should_stream = if stream_response {
                    true
                } else {
                    refine_stream_response_for_content_type(
                        false,
                        proxy,
                        plugins,
                        retry_ctx.as_ref(),
                        response.status,
                        &response.headers,
                    )
                };
                if should_stream {
                    debug!(
                        proxy_id = %proxy.id,
                        status = response.status,
                        "HTTP/3 backend streaming retry request successful"
                    );
                    let headers = std::mem::take(&mut response.headers);
                    retry::BackendResponse {
                        status_code: response.status,
                        body: ResponseBody::StreamingH3(Box::new(response)),
                        headers,
                        connection_error: false,
                        backend_resolved_ip: resolved_ip,
                        error_class: None,
                    }
                } else {
                    drain_h3_streaming_response_to_buffered(
                        response,
                        state,
                        proxy,
                        method,
                        backend_url,
                        resolved_ip,
                    )
                    .await
                }
            }
            Err(e) => {
                if e.is_read_timeout() {
                    // `backend_read_timeout_ms` expired waiting for the
                    // retried response headers — surface 504 Backend timeout
                    // like the buffered retry arm below, not a generic 502.
                    warn!(
                        proxy_id = %proxy.id,
                        backend_url = %strip_query_params(backend_url),
                        target = %format!("{}:{}", effective_host, effective_port),
                        error = %e,
                        "HTTP/3 backend read timeout waiting for response (streaming retry)"
                    );
                    return h3_read_timeout_backend_response(resolved_ip);
                }
                let (error_kind, error_class) = classify_h3_pool_error(&e);
                // A gateway-side egress denial (DispatchPolicyRejected) dialed no
                // backend, so override the pool's pre-wire signal to keep it
                // non-retryable + backend-health-neutral. This is the ONE class
                // safe to AND with the typed `request_on_wire` signal — it is a
                // gateway rejection, not a transport class that could disagree.
                let is_conn_error = !e.request_on_wire()
                    && !matches!(error_class, retry::ErrorClass::DispatchPolicyRejected);
                record_port_exhaustion_if_class(&state.overload, error_class);
                error!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    target = %format!("{}:{}", effective_host, effective_port),
                    error_kind = error_kind,
                    error = %e,
                    "HTTP/3 backend streaming retry request failed"
                );
                retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"HTTP/3 backend request failed"}"#.as_bytes().to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: is_conn_error,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(error_class),
                }
            }
        };
    }

    let connection_pool = state.connection_pool.clone();
    let proxy_clone = proxy.clone();
    let h3_result = if let Some(target) = upstream_target {
        let target_host = target.host.clone();
        let target_port = target.port;
        state
            .h3_pool
            .request_with_target(
                proxy,
                &target_host,
                target_port,
                method,
                backend_url,
                &http3_headers,
                body_bytes,
                move || connection_pool.get_tls_config_for_backend(&proxy_clone),
            )
            .await
    } else {
        state
            .h3_pool
            .request(
                proxy,
                method,
                backend_url,
                &http3_headers,
                body_bytes,
                move || connection_pool.get_tls_config_for_backend(&proxy_clone),
            )
            .await
    };

    match h3_result {
        Ok(response) => {
            debug!(
                proxy_id = %proxy.id,
                status = response.status,
                "HTTP/3 backend retry request successful"
            );
            // Belt-and-suspenders size guard. The H3 pool enforces this while
            // draining the response body so oversized responses stop before
            // full buffering; keep this post-return check to protect future
            // alternate H3 collection paths.
            if state.max_response_body_size_bytes > 0
                && response.body.len() > state.max_response_body_size_bytes
            {
                warn!(
                    "Backend response body ({} bytes) exceeds limit ({} bytes)",
                    response.body.len(),
                    state.max_response_body_size_bytes
                );
                return retry::BackendResponse {
                    status_code: 502,
                    body: ResponseBody::Buffered(
                        r#"{"error":"Backend response body exceeds maximum size"}"#
                            .as_bytes()
                            .to_vec(),
                    ),
                    headers: HashMap::new(),
                    connection_error: false,
                    backend_resolved_ip: resolved_ip,
                    error_class: Some(retry::ErrorClass::ResponseBodyTooLarge),
                };
            }
            // Backend trailers (`response.trailers`) are dropped here for the
            // same reason as the non-retry H1/H2-frontend → H3-backend path:
            // emitting them to an H1/H2 client needs chunked-trailer / trailers-
            // frame machinery that is out of scope for issue #1630.
            retry::BackendResponse {
                status_code: response.status,
                body: ResponseBody::Buffered(response.body),
                headers: response.headers,
                connection_error: false,
                backend_resolved_ip: resolved_ip,
                error_class: None,
            }
        }
        Err(e) => {
            if e.is_read_timeout() {
                // `backend_read_timeout_ms` expired waiting for the retried
                // response — surface 504 Backend timeout like the direct-H2
                // / HBONE read-timeout arms, not a generic 502.
                warn!(
                    proxy_id = %proxy.id,
                    backend_url = %strip_query_params(backend_url),
                    target = %format!("{}:{}", effective_host, effective_port),
                    error = %e,
                    "HTTP/3 backend read timeout waiting for response (retry)"
                );
                return h3_read_timeout_backend_response(resolved_ip);
            }
            // Trust the pool's body-on-wire signal — see the streaming
            // H3 branch above for why we drop the class contribution.
            let (error_kind, error_class) = classify_h3_pool_error(&e);
            // …except a gateway-side egress denial (DispatchPolicyRejected) dialed
            // no backend, so keep it non-retryable + backend-health-neutral even
            // on the retry path (matches the other H3 dispatch sites).
            let is_conn_error = !e.request_on_wire()
                && !matches!(error_class, retry::ErrorClass::DispatchPolicyRejected);
            record_port_exhaustion_if_class(&state.overload, error_class);
            error!(
                proxy_id = %proxy.id,
                backend_url = %strip_query_params(backend_url),
                target = %format!("{}:{}", effective_host, effective_port),
                error_kind = error_kind,
                error = %e,
                "HTTP/3 backend retry request failed"
            );
            retry::BackendResponse {
                status_code: 502,
                body: ResponseBody::Buffered(
                    r#"{"error":"HTTP/3 backend request failed"}"#.as_bytes().to_vec(),
                ),
                headers: HashMap::new(),
                connection_error: is_conn_error,
                backend_resolved_ip: resolved_ip,
                error_class: Some(error_class),
            }
        }
    }
}

fn canonicalize_client_ip(ip: std::net::IpAddr) -> std::net::IpAddr {
    match ip {
        std::net::IpAddr::V6(v6) => v6
            .to_ipv4_mapped()
            .map(std::net::IpAddr::V4)
            .unwrap_or(std::net::IpAddr::V6(v6)),
        other => other,
    }
}

