    fn streaming_dispatch_test_proxy() -> Proxy {
        serde_json::from_value(json!({
            "id": "p",
            "hosts": ["p.example.com"],
            "backend_host": "127.0.0.1",
            "backend_port": 50051,
            "circuit_breaker": {
                "failure_status_codes": [500]
            }
        }))
        .expect("valid proxy")
    }

    /// The cross-cluster HBONE backend-URL authority rewrite swaps the
    /// (non-parseable) scoped synthetic host for the real pod addr in the
    /// AUTHORITY position only, leaving the path/query (and any host-like
    /// substring inside the path) untouched, so the resulting URL parses and
    /// yields the correct `path_and_query`.
    #[test]
    fn rewrite_backend_url_authority_host_swaps_authority_only() {
        let synth = "mesh-xc-hbone|10.9.9.9|15443|10.244.5.5";
        let url = format!("http://{synth}:8080/api/v1?host={synth}&x=1");
        let rewritten = rewrite_backend_url_authority_host(&url, synth, "10.244.5.5");
        assert_eq!(
            rewritten,
            "http://10.244.5.5:8080/api/v1?host=mesh-xc-hbone|10.9.9.9|15443|10.244.5.5&x=1",
            "only the authority host is swapped; the query's host= value is preserved"
        );
        // The rewritten URL must parse and expose the original path_and_query.
        let uri: hyper::Uri = rewritten.parse().expect("rewritten URL parses");
        assert_eq!(
            uri.path_and_query().map(|pq| pq.as_str()),
            Some("/api/v1?host=mesh-xc-hbone|10.9.9.9|15443|10.244.5.5&x=1")
        );

        // An IPv6 real pod addr is bracketed in the rewritten authority.
        let url6 = format!("http://{synth}:8080/p");
        let rewritten6 = rewrite_backend_url_authority_host(&url6, synth, "fd00::5");
        assert_eq!(rewritten6, "http://[fd00::5]:8080/p");

        // No `://` or a non-matching authority ⇒ returned unchanged (defensive).
        assert_eq!(
            rewrite_backend_url_authority_host("not-a-url", synth, "10.0.0.1"),
            "not-a-url"
        );
        assert_eq!(
            rewrite_backend_url_authority_host("http://other-host:80/p", synth, "10.0.0.1"),
            "http://other-host:80/p"
        );
    }

    #[test]
    fn backend_capability_probe_proxy_clamps_per_port_connect_timeouts() {
        let mut proxy = streaming_dispatch_test_proxy();
        proxy.backend_connect_timeout_ms = 30_000;
        proxy.dispatch_port_overrides = Some(HashMap::from([
            (
                8080,
                crate::config::types::ResolvedPortOverride {
                    connect_timeout_ms: Some(60_000),
                    ..Default::default()
                },
            ),
            (
                9090,
                crate::config::types::ResolvedPortOverride {
                    connect_timeout_ms: Some(0),
                    ..Default::default()
                },
            ),
        ]));
        proxy.dispatch_port_override_fallback = Some(crate::config::types::ResolvedPortOverride {
            connect_timeout_ms: Some(120_000),
            ..Default::default()
        });

        let probe_proxy = ProxyState::build_backend_capability_probe_proxy(&proxy);

        assert_eq!(
            probe_proxy.backend_connect_timeout_ms,
            BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP
        );
        assert_eq!(
            hbone_pool::effective_connect_timeout_ms_for_policy_port(&probe_proxy, 8080),
            BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP,
            "HBONE probes must not wait longer than the capability probe cap"
        );
        assert_eq!(
            hbone_pool::effective_connect_timeout_ms_for_policy_port(&probe_proxy, 9090),
            1,
            "probe timeouts retain the existing lower-bound clamp"
        );
        assert_eq!(
            probe_proxy
                .dispatch_port_override_fallback
                .as_ref()
                .and_then(|override_config| override_config.connect_timeout_ms),
            Some(BACKEND_CAPABILITY_PROBE_TIMEOUT_MS_CAP)
        );
        assert_eq!(
            hbone_pool::effective_connect_timeout_ms_for_policy_port(&proxy, 8080),
            60_000,
            "real request dials keep the operator's per-port timeout"
        );
    }

    #[test]
    fn node_waypoint_outbound_prefers_ebpf_original_destination() {
        let socket_capture_endpoint: SocketAddr = "127.0.0.1:15001".parse().unwrap();
        let ebpf_original_dst: SocketAddr = "10.244.1.4:8080".parse().unwrap();

        assert_eq!(
            select_mesh_original_dst(
                Some(crate::modes::mesh::MeshTrafficDirection::Outbound),
                Some(socket_capture_endpoint),
                Some(ebpf_original_dst),
            ),
            Some(ebpf_original_dst),
            "cgroup/connect capture has no conntrack original-dst, so direct Pod-IP HTTP must route by the eBPF original destination"
        );
        assert_eq!(
            select_mesh_original_dst(
                Some(crate::modes::mesh::MeshTrafficDirection::Outbound),
                Some(socket_capture_endpoint),
                None,
            ),
            Some(socket_capture_endpoint),
            "non-node-waypoint outbound REDIRECT capture still uses SO_ORIGINAL_DST"
        );
        assert_eq!(
            select_mesh_original_dst(
                Some(crate::modes::mesh::MeshTrafficDirection::Inbound),
                Some(socket_capture_endpoint),
                Some(ebpf_original_dst),
            ),
            Some(socket_capture_endpoint),
            "inbound capture is still the iptables original-dst path"
        );
    }

    #[test]
    fn node_waypoint_identity_resolution_is_outbound_capture_only() {
        assert!(
            should_resolve_node_waypoint_identity(Some(
                crate::modes::mesh::MeshTrafficDirection::Outbound
            )),
            "pod-loopback outbound capture must resolve the eBPF cookie before request handling"
        );
        assert!(
            !should_resolve_node_waypoint_identity(Some(
                crate::modes::mesh::MeshTrafficDirection::Inbound
            )),
            "peer HBONE connections on the inbound listener do not carry pod-loopback cookies"
        );
        assert!(
            !should_resolve_node_waypoint_identity(None),
            "non-mesh listeners must not be coupled to the NodeWaypoint identity resolver"
        );
    }

    #[test]
    fn node_waypoint_listener_uid_fallback_is_cookie_lookup_only() {
        let pod_uid = [1u8; 16];
        let other_uid = [2u8; 16];

        assert!(node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::SocketCookieUnavailable("not supported".to_string())
        ));
        assert!(node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::UnknownCookie(7)
        ));

        assert!(!node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::MissingPodUid(7)
        ));
        assert!(!node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::MissingWorkloadHash { cookie: 7, pod_uid }
        ));
        assert!(!node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::UnknownPod(pod_uid)
        ));
        assert!(!node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::WorkloadHashMismatch {
                pod_uid,
                expected: 1,
                actual: 2,
            }
        ));
        assert!(!node_waypoint_listener_uid_fallback_allowed(
            &NodeWaypointIdentityError::PodUidMismatch {
                expected: pod_uid,
                actual: other_uid,
            }
        ));
    }

    #[test]
    fn direct_pod_ip_http_route_is_node_waypoint_only() {
        assert!(
            should_use_direct_pod_ip_http_route(
                Some(crate::modes::mesh::MeshTrafficDirection::Outbound),
                true
            ),
            "NodeWaypoint outbound capture with a resolved source pod identity may route by original pod IP"
        );
        assert!(
            !should_use_direct_pod_ip_http_route(
                Some(crate::modes::mesh::MeshTrafficDirection::Outbound),
                false
            ),
            "Sidecar and other outbound listeners keep Host routing because they do not have NodeWaypoint pod identity"
        );
        assert!(
            !should_use_direct_pod_ip_http_route(
                Some(crate::modes::mesh::MeshTrafficDirection::Inbound),
                true
            ),
            "inbound HBONE relay traffic must not use the outbound direct-pod-IP lookup"
        );
    }

    #[test]
    fn grpc_streaming_defers_passive_unhealthy_2xx_until_body_terminal() {
        let proxy = streaming_dispatch_test_proxy();

        assert!(
            streaming_dispatch_should_defer(&proxy, 206, false, false, false),
            "ordinary open 2xx streaming responses defer terminal accounting"
        );
        assert!(
            !streaming_dispatch_should_defer(&proxy, 206, false, false, true),
            "direct HTTP/2 streaming keeps passively-unhealthy 2xx eager"
        );
        assert!(
            grpc_streaming_dispatch_should_defer(&proxy, 206, false),
            "gRPC streaming must not eagerly bank passive-only unhealthy 2xx as CB success"
        );
        assert!(
            !grpc_streaming_dispatch_should_defer(&proxy, 500, false),
            "configured CB failures remain header-time-final"
        );
        assert!(
            !grpc_streaming_dispatch_should_defer(&proxy, 200, true),
            "already-ended gRPC responses remain header-time-final"
        );

        // No-body statuses (204/304) must stay eager even when the backend left
        // the body open (no END_STREAM on the header frame, so `is_end_stream()`
        // would report false): hyper may never poll a 304/204 body, and the
        // never-polled streaming `ProxyBody::Drop` would otherwise record a client
        // disconnect that drops the header-time success and blocks HALF_OPEN
        // healing for cache-validation traffic.
        for no_body_status in [204u16, 304u16] {
            assert!(
                !streaming_dispatch_should_defer(&proxy, no_body_status, false, false, false),
                "{no_body_status} is a no-body status and must record eagerly even with an \
                 open (non-END_STREAM) backend body"
            );
            assert!(
                !grpc_streaming_dispatch_should_defer(&proxy, no_body_status, false),
                "{no_body_status} no-body status must record eagerly on the gRPC path too"
            );
        }
    }

    /// F3 §3.4: the direct-pod-IP / headless per-workload raw-TCP egress
    /// upstreams are referenced by NO config proxy, so without a dedicated
    /// capability-enrollment pass `retain_keys` would evict their HBONE records
    /// and every Ambient by-workload dial would 502 `hbone_required` forever.
    /// `collect_mesh_tcp_egress_capability_targets` must enroll the Ambient
    /// `mesh.hbone` per-workload targets (keyed by the SAME deterministic
    /// per-workload relay proxy the index/dispatch use) and skip `mesh.mtls`.
    #[test]
    fn collect_mesh_tcp_egress_capability_targets_enrolls_per_workload_hbone() {
        use crate::identity::spiffe::{SpiffeId, TrustDomain};
        use crate::modes::mesh::config::{
            AppProtocol, MeshConfig, MeshService, ServicePort, ServiceTargetPort, Workload,
            WorkloadPort, WorkloadRef, WorkloadSelector,
        };

        // Build a headless Ambient (HBONE) raw-TCP service backed by a pod IP.
        // We build `config.mesh` + the materialized by-workload upstream directly
        // (the collector forward-derives candidates from `config.mesh` and looks
        // them up in the upstream map), so the test needs no `MeshRuntimeConfig`.
        let spiffe = "spiffe://cluster.local/ns/default/sa/redis";
        let svc = MeshService {
            name: "redis".to_string(),
            namespace: "default".to_string(),
            ports: vec![ServicePort {
                port: 6379,
                protocol: AppProtocol::Redis,
                name: Some("redis".to_string()),
                target_port: Some(ServiceTargetPort::Number(6380)),
            }],
            workloads: vec![WorkloadRef {
                spiffe_id: SpiffeId::new(spiffe).unwrap(),
            }],
            protocol_overrides: HashMap::new(),
            cluster_ips: Vec::new(),
        };
        let wl = Workload {
            spiffe_id: SpiffeId::new(spiffe).unwrap(),
            selector: WorkloadSelector::default(),
            service_name: "redis".to_string(),
            addresses: vec!["10.0.0.7".to_string()],
            ports: vec![WorkloadPort {
                port: 6380,
                protocol: AppProtocol::Redis,
                name: Some("redis".to_string()),
            }],
            trust_domain: TrustDomain::new("cluster.local").unwrap(),
            namespace: "default".to_string(),
            network: None,
            cluster: None,
            weight: None,
            locality: None,
            service_account: None,
            pod_uid: None,
            node_waypoint: None,
            remote_provenance: false,
        };

        let bywl_id = crate::modes::mesh::mesh_outbound_tcp_bywl_upstream_id(
            "default",
            "redis",
            6379,
            "10.0.0.7".parse().unwrap(),
        );
        // The single-target HBONE-tagged, identity-pinned upstream the Ambient
        // materializer would emit.
        let mut upstream: Upstream = serde_json::from_value(json!({
            "id": bywl_id,
            "name": "redis.default.svc.cluster.local",
            "targets": [{
                "host": "10.0.0.7",
                "port": 6380,
                "tags": {"mesh.hbone": "true", "mesh.spiffe_id": spiffe},
            }],
        }))
        .expect("upstream deserializes");
        upstream.port_overrides.insert(
            6379,
            crate::config::types::UpstreamPortOverride {
                tcp_keepalive: Some(crate::config::types::TcpKeepaliveCfg {
                    time_seconds: Some(10),
                    interval_seconds: Some(2),
                    probes: Some(3),
                }),
                ..Default::default()
            },
        );
        let config = GatewayConfig {
            upstreams: vec![upstream],
            mesh: Some(Box::new(MeshConfig {
                services: vec![svc],
                workloads: vec![wl],
                ..MeshConfig::default()
            })),
            ..GatewayConfig::default()
        };

        let upstream_map: HashMap<&str, &Upstream> = config
            .upstreams
            .iter()
            .map(|u| (u.id.as_str(), u))
            .collect();
        let mut seen = std::collections::HashSet::new();
        let mut targets = Vec::new();
        ProxyState::collect_mesh_tcp_egress_capability_targets(
            &config,
            &upstream_map,
            &mut seen,
            &mut targets,
        );

        // The expected probe key is the one the by-workload relay proxy + the
        // materialized target produce — exactly what dispatch will look up.
        let relay = crate::modes::mesh::mesh_outbound_tcp_bywl_relay_proxy(
            "default",
            "redis",
            6379,
            "10.0.0.7".parse().unwrap(),
            &bywl_id,
        );
        let expected =
            BackendCapabilityProbeTarget::from_proxy(&relay, Some(&config.upstreams[0].targets[0]));
        let enrolled = targets
            .iter()
            .find(|t| t.key == expected.key)
            .expect("the per-workload Ambient HBONE target is enrolled for probing");
        assert!(
            enrolled.hbone_hint,
            "the enrolled per-workload target opts into HBONE probing"
        );
        assert_eq!(
            enrolled.hbone_expected_peer.as_ref().map(|p| p.as_str()),
            Some(spiffe),
            "the HBONE probe pins the same destination identity dispatch uses"
        );
        assert!(
            enrolled
                .proxy
                .dispatch_port_overrides
                .as_ref()
                .and_then(|overrides| overrides.get(&6379))
                .and_then(|override_config| override_config.tcp_keepalive.as_ref())
                .is_some(),
            "the HBONE probe relay must carry the same per-port TCP policy as dispatch"
        );
    }

    /// F3 §3.3 Stage 4: the UDP egress upstreams are referenced by NO config
