    #[async_trait]
    impl Plugin for RejectHeaderPlugin {
        fn name(&self) -> &str {
            "reject_header_plugin"
        }

        fn applies_after_proxy_on_reject(&self) -> bool {
            true
        }

        async fn after_proxy(
            &self,
            ctx: &mut RequestContext,
            _response_status: u16,
            response_headers: &mut HashMap<String, String>,
        ) -> PluginResult {
            if ctx
                .metadata
                .get(REJECTION_RESPONSE_METADATA_KEY)
                .is_some_and(|value| value == "true")
            {
                response_headers.insert("x-after-reject".to_string(), "applied".to_string());
            }
            PluginResult::Continue
        }
    }

    #[async_trait]
    impl Plugin for ReplaceRejectPlugin {
        fn name(&self) -> &str {
            "replace_reject_plugin"
        }

        fn applies_after_proxy_on_reject(&self) -> bool {
            true
        }

        fn may_replace_rejection_response(&self) -> bool {
            true
        }

        async fn after_proxy(
            &self,
            _ctx: &mut RequestContext,
            _response_status: u16,
            _response_headers: &mut HashMap<String, String>,
        ) -> PluginResult {
            PluginResult::Reject {
                status_code: 503,
                body: "late fail-closed rejection".to_string(),
                headers: HashMap::from([("x-replaced".to_string(), "true".to_string())]),
            }
        }
    }

    #[async_trait]
    impl Plugin for CommittedHeaderProbePlugin {
        fn name(&self) -> &str {
            "committed_header_probe"
        }

        fn requires_response_committed_hook(&self) -> bool {
            true
        }

        async fn on_response_committed(
            &self,
            ctx: &mut RequestContext,
            response_status: u16,
            response_headers: &HashMap<String, String>,
            body: &[u8],
        ) {
            ctx.metadata.insert(
                "test:committed_status".to_string(),
                response_status.to_string(),
            );
            if let Some(content_type) = response_headers.get("content-type") {
                ctx.metadata.insert(
                    "test:committed_content_type".to_string(),
                    content_type.clone(),
                );
            }
            ctx.metadata.insert(
                "test:committed_body".to_string(),
                String::from_utf8_lossy(body).into_owned(),
            );
        }
    }

