    #[test]
    fn ws_idle_tracker_from_timeout_seconds_disabled_when_zero() {
        // 0 must produce no tracker (idle bound disabled).
        assert!(WsIdleTracker::from_timeout_seconds(0).is_none());
    }

    #[test]
    fn ws_idle_tracker_from_timeout_seconds_builds_tracker_when_nonzero() {
        let tracker = WsIdleTracker::from_timeout_seconds(300)
            .expect("non-zero timeout must build a tracker");
        assert_eq!(tracker.timeout, Duration::from_secs(300));
        // A fresh tracker has its full window remaining.
        assert!(tracker.remaining().is_some());
    }

    #[tokio::test]
    async fn next_websocket_message_no_tracker_never_times_out() {
        // Disabled idle bound: a pending (silent) stream must park forever, not
        // resolve to IdleTimeout. We assert it does not complete within a window
        // that would have elapsed several times over for a 5ms tracker.
        let mut stream = futures_util::stream::pending::<
            Result<Message, tokio_tungstenite::tungstenite::Error>,
        >();
        let result = tokio::time::timeout(
            Duration::from_millis(50),
            next_websocket_message(&mut stream, None),
        )
        .await;
        assert!(
            result.is_err(),
            "with idle timeout disabled (None), next_websocket_message must never resolve on a silent stream"
        );
    }

    #[tokio::test]
    async fn next_websocket_message_times_out_when_idle_bound_elapsed() {
        let mut stream = futures_util::stream::pending::<
            Result<Message, tokio_tungstenite::tungstenite::Error>,
        >();
        let idle = WsIdleTracker::new(Duration::from_millis(5));

        let item = next_websocket_message(&mut stream, Some(&idle)).await;

        assert!(matches!(item, WsNextMessage::IdleTimeout));
    }

    #[tokio::test]
    async fn next_websocket_message_counter_direction_activity_prevents_expiry() {
        let mut stream = futures_util::stream::pending::<
            Result<Message, tokio_tungstenite::tungstenite::Error>,
        >();
        let idle = Arc::new(WsIdleTracker::new(Duration::from_millis(300)));

        // Simulate the OTHER relay half receiving frames: refresh the shared
        // watermark every 100ms, well inside the 300ms idle window.
        let toucher = {
            let idle = idle.clone();
            tokio::spawn(async move {
                loop {
                    tokio::time::sleep(Duration::from_millis(100)).await;
                    idle.touch();
                }
            })
        };

        // The quiet half's wait must NOT expire while the counter-direction
        // keeps refreshing the watermark, even though 350ms > the 300ms
        // window. Pre-fix, a per-direction timeout would have fired at 300ms.
        let waited = tokio::time::timeout(
            Duration::from_millis(350),
            next_websocket_message(&mut stream, Some(idle.as_ref())),
        )
        .await;
        assert!(
            waited.is_err(),
            "counter-direction activity must defer the shared idle expiry"
        );

        // Once the counter-direction goes quiet too, the same wait expires
        // after the idle window truly elapses with no activity on either side.
        toucher.abort();
        let item = next_websocket_message(&mut stream, Some(idle.as_ref())).await;
        assert!(matches!(item, WsNextMessage::IdleTimeout));
    }

    /// Byte-level activity through the `WsActivityIo` adapter must refresh
    /// the shared idle watermark even though no complete WebSocket `Message`
    /// is ever yielded — this is what keeps a slowly arriving large or
    /// fragmented message alive past the idle window.
    #[tokio::test]
    async fn ws_activity_io_read_progress_refreshes_idle_watermark() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let idle = Arc::new(WsIdleTracker::new(Duration::from_millis(200)));
        let (client, server) = tokio::io::duplex(64);
        let mut tracked = WsActivityIo::new(server, Some(idle.clone()));

        // Writer drips raw bytes (mid-message continuation data) every 50ms,
        // never completing a frame.
        let writer = tokio::spawn(async move {
            let mut client = client;
            for _ in 0..8u8 {
                tokio::time::sleep(Duration::from_millis(50)).await;
                let _ = client.write_all(b"x").await;
            }
        });

        // Read through the adapter for 400ms — twice the idle window. Each
        // read with progress must touch the tracker, so `remaining()` never
        // hits zero while bytes keep arriving.
        let mut buf = [0u8; 8];
        let deadline = tokio::time::Instant::now() + Duration::from_millis(400);
        while tokio::time::Instant::now() < deadline {
            match tokio::time::timeout_at(deadline, tracked.read(&mut buf)).await {
                Ok(Ok(0)) | Err(_) => break,
                Ok(Ok(_)) => {
                    assert!(
                        idle.remaining().is_some(),
                        "mid-message byte progress must keep the idle window open"
                    );
                }
                Ok(Err(e)) => panic!("duplex read failed: {e}"),
            }
        }
        writer.abort();

        // With the byte drip stopped, the window finally elapses.
        tokio::time::sleep(Duration::from_millis(250)).await;
        assert!(
            idle.remaining().is_none(),
            "idle window must expire once byte progress stops"
        );
    }

    #[tokio::test]
    async fn plugin_rejection_response_runs_after_proxy_reject_hooks() {
        let plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(RejectHeaderPlugin)];
        let mut ctx = RequestContext::new("203.0.113.10".into(), "GET".into(), "/body".into());
        let mut response_status = 200;
        let mut response_headers =
            HashMap::from([("content-type".to_string(), "text/plain".to_string())]);
        let reject = RejectedResponseParts {
            status_code: 502,
            body: br#"{"error":"blocked"}"#.to_vec(),
            headers: HashMap::new(),
        };

        let body = apply_plugin_rejection_response(
            &plugins,
            &mut ctx,
            &mut response_status,
            &mut response_headers,
            reject,
        )
        .await;

        assert_eq!(response_status, 502);
        assert_eq!(
            response_headers.get("content-type").map(String::as_str),
            Some("application/json")
        );
        assert_eq!(
            response_headers.get("x-after-reject").map(String::as_str),
            Some("applied")
        );
        assert_eq!(body, br#"{"error":"blocked"}"#);
        assert!(!ctx.metadata.contains_key(REJECTION_RESPONSE_METADATA_KEY));
    }

    #[tokio::test]
    async fn opted_in_replacement_preserves_earlier_rejection_decorators() {
        let plugins: Vec<Arc<dyn Plugin>> =
            vec![Arc::new(RejectHeaderPlugin), Arc::new(ReplaceRejectPlugin)];
        let mut ctx = RequestContext::new("203.0.113.10".into(), "GET".into(), "/body".into());
        let mut status = 200;
        let mut headers = HashMap::from([
            ("content-type".to_string(), "text/plain".to_string()),
            ("content-length".to_string(), "17".to_string()),
            ("content-encoding".to_string(), "gzip".to_string()),
            ("content-range".to_string(), "bytes 0-16/17".to_string()),
            ("content-md5".to_string(), "stale-md5".to_string()),
            ("digest".to_string(), "sha-256=stale".to_string()),
            ("content-digest".to_string(), "sha-256=:stale:".to_string()),
            ("repr-digest".to_string(), "sha-256=:stale:".to_string()),
            ("etag".to_string(), "\"stale\"".to_string()),
            (
                "last-modified".to_string(),
                "Wed, 01 Jan 2025 00:00:00 GMT".to_string(),
            ),
            (
                "cache-control".to_string(),
                "public, max-age=3600".to_string(),
            ),
            ("cdn-cache-control".to_string(), "max-age=3600".to_string()),
            ("surrogate-control".to_string(), "max-age=3600".to_string()),
            (
                "expires".to_string(),
                "Wed, 01 Jan 2030 00:00:00 GMT".to_string(),
            ),
            ("age".to_string(), "120".to_string()),
            ("pragma".to_string(), "cache".to_string()),
            ("vary".to_string(), "accept-encoding, Origin".to_string()),
            ("warning".to_string(), "110 stale".to_string()),
        ]);
        let mut body = b"synthetic success".to_vec();

        apply_reject_after_proxy_and_synthetic_body_hooks(
            &plugins,
            &mut ctx,
            &mut status,
            &mut headers,
            &mut body,
            false,
            false,
        )
        .await;

        assert_eq!(status, 503);
        assert_eq!(body, b"late fail-closed rejection");
        assert_eq!(
            headers.get("x-after-reject").map(String::as_str),
            Some("applied"),
            "replacement must retain CORS/correlation-style headers from earlier hooks"
        );
        assert_eq!(headers.get("x-replaced").map(String::as_str), Some("true"));
        for stale_header in [
            "content-length",
            "content-encoding",
            "content-range",
            "content-md5",
            "digest",
            "content-digest",
            "repr-digest",
            "etag",
            "last-modified",
            "cache-control",
            "cdn-cache-control",
            "surrogate-control",
            "expires",
            "age",
            "pragma",
            "warning",
        ] {
            assert!(
                !headers.contains_key(stale_header),
                "replacement retained stale {stale_header}"
            );
        }
        assert_eq!(headers.get("vary").map(String::as_str), Some("Origin"));
        assert!(!ctx.metadata.contains_key(REJECTION_RESPONSE_METADATA_KEY));
        assert!(
            !ctx.metadata
                .contains_key(REPLACEABLE_REJECTION_RESPONSE_METADATA_KEY)
        );
    }

