    #[tokio::test]
    async fn synthetic_head_representation_uses_get_guardrails_then_restores_head() {
        let plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(HeadSkippingSyntheticGuardPlugin)];
        let mut ctx = RequestContext::new(
            "203.0.113.10".to_string(),
            "HEAD".to_string(),
            "/api/specz".to_string(),
        );
        ctx.metadata.insert(
            SYNTHETIC_RESPONSE_METHOD_OVERRIDE_METADATA_KEY.to_string(),
            "GET".to_string(),
        );
        let mut status = 200;
        let mut headers =
            HashMap::from([("content-type".to_string(), "application/json".to_string())]);
        let mut body = br#"{"secret":"must be inspected"}"#.to_vec();

        apply_reject_after_proxy_and_synthetic_body_hooks(
            &plugins,
            &mut ctx,
            &mut status,
            &mut headers,
            &mut body,
            false,
            false,
        )
        .await;

        // Guardrails inspected the GET representation and replaced it; the
        // shared finalizer then restores HEAD and applies wire omission so the
        // client receives representation metadata without content bytes.
        const BLOCKED_REPRESENTATION: &[u8] = b"blocked synthetic representation";
        let expected_content_length = BLOCKED_REPRESENTATION.len().to_string();
        assert_eq!(status, 451);
        assert!(
            body.is_empty(),
            "HEAD final wire body must be empty after shared no-body preparation"
        );
        assert_eq!(
            headers.get("content-length").map(String::as_str),
            Some(expected_content_length.as_str())
        );
        assert_eq!(
            ctx.metadata
                .get("test:synthetic_body_method")
                .map(String::as_str),
            Some("GET")
        );
        assert_eq!(ctx.method, "HEAD");
        assert_eq!(
            headers.get("x-after-proxy-method").map(String::as_str),
            Some("HEAD")
        );
        assert!(
            !ctx.metadata
                .contains_key(SYNTHETIC_RESPONSE_METHOD_OVERRIDE_METADATA_KEY)
        );
    }

