    #[test]
    fn backend_tls_watched_sources_collects_and_deduplicates_sources() {
        let env_config = EnvConfig {
            tls_ca_bundle_path: Some("/ca/global.pem".to_string()),
            backend_tls_client_cert_path: Some("/certs/shared.pem".to_string()),
            backend_tls_client_key_path: Some("/keys/global.key".to_string()),
            tls_crl_file_path: Some("/crl/global.pem".to_string()),
            ..EnvConfig::default()
        };
        let mut config: GatewayConfig = serde_json::from_value(json!({
            "version": "1",
            "proxies": [{
                "id": "p1",
                "listen_path": "/",
                "backend_host": "api.example.com",
                "backend_port": 443,
                "backend_scheme": "https"
            }],
            "consumers": [],
            "plugin_configs": [{
                "id": "mrd1",
                "plugin_name": "mesh_route_dispatch",
                "scope": "proxy",
                "proxy_id": "p1",
                "enabled": true,
                "config": {
                    "rules": [{
                        "match": {"methods": ["GET"]},
                        "destination": {
                            "backend_host": "canary.example.com",
                            "backend_port": 443,
                            "backend_tls": {
                                "client_cert_path": "/certs/mesh-route.pem",
                                "client_key_path": "/keys/mesh-route.key",
                                "server_ca_cert_path": "/ca/mesh-route.pem"
                            }
                        }
                    }]
                }
            }],
            "upstreams": [{
                "id": "u1",
                "targets": [{"host": "api.example.com", "port": 443}],
                "backend_tls_client_cert_path": "/certs/shared.pem",
                "backend_tls_client_key_path": "/keys/upstream.key",
                "backend_tls_server_ca_cert_path": "/ca/upstream.pem"
            }]
        }))
        .expect("config should deserialize");
        config.proxies[0].resolved_tls = BackendTlsConfig {
            client_cert_path: Some("/certs/proxy.pem".to_string()),
            client_key_path: Some("/keys/proxy.key".to_string()),
            server_ca_cert_path: Some("/ca/proxy.pem".to_string()),
            verify_server_cert: true,
            sni: None,
            san_allow_list: Vec::new(),
            san_allow_list_key_digest: None,
        };

        let sources = collect_backend_tls_watched_sources(&config, &env_config);
        let ids = sources
            .iter()
            .map(|source| source.source.pool_key_component())
            .collect::<Vec<_>>();

        assert_eq!(sources.len(), 12);
        assert_eq!(
            ids.iter()
                .filter(|id| id.as_str() == "/certs/shared.pem")
                .count(),
            1,
            "shared global/upstream cert source should be watched once"
        );
        assert!(ids.contains(&"/ca/global.pem".to_string()));
        assert!(ids.contains(&"/crl/global.pem".to_string()));
        assert!(ids.contains(&"/ca/proxy.pem".to_string()));
        assert!(ids.contains(&"/ca/upstream.pem".to_string()));
        assert!(ids.contains(&"/certs/mesh-route.pem".to_string()));
        assert!(ids.contains(&"/keys/mesh-route.key".to_string()));
        assert!(ids.contains(&"/ca/mesh-route.pem".to_string()));
    }

    #[test]
    fn clone_log_metadata_removes_body_and_unowned_waf_metadata() {
        let mut ctx = RequestContext::new("203.0.113.10".into(), "GET".into(), "/search".into());
        ctx.metadata
            .insert("request_body".to_string(), "secret body".to_string());
        ctx.metadata
            .insert("waf.rule_hits".to_string(), "SPOOFED".to_string());
        ctx.metadata
            .insert("waf.action".to_string(), "blocked".to_string());
        ctx.metadata
            .insert("mcp.needs_response_rewrite".to_string(), "true".to_string());
        ctx.metadata.insert(
            "mcp.response_rewrite.session".to_string(),
            "internal-session-hash".to_string(),
        );
        ctx.metadata.insert(
            ORIGINAL_RESPONSE_METADATA_STAMPED_KEY.to_string(),
            "true".to_string(),
        );
        ctx.metadata.insert(
            ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY.to_string(),
            "128".to_string(),
        );
        ctx.metadata.insert(
            ORIGIN_ENCODED_RESPONSE_METADATA_KEY.to_string(),
            "true".to_string(),
        );

        let metadata = clone_log_metadata(&ctx);

        assert!(!metadata.contains_key("request_body"));
        assert!(!metadata.contains_key("waf.rule_hits"));
        assert!(!metadata.contains_key("waf.action"));
        assert!(!metadata.contains_key("mcp.needs_response_rewrite"));
        assert!(!metadata.contains_key("mcp.response_rewrite.session"));
        assert!(!metadata.contains_key(ORIGINAL_RESPONSE_METADATA_STAMPED_KEY));
        assert!(!metadata.contains_key(ORIGINAL_RESPONSE_CONTENT_LENGTH_METADATA_KEY));
        assert!(!metadata.contains_key(ORIGIN_ENCODED_RESPONSE_METADATA_KEY));

        ctx.set_waf_metadata("waf.rule_hits", "FE-SQLI-001");
        ctx.metadata
            .insert("waf.action".to_string(), "blocked".to_string());

        let metadata = clone_log_metadata(&ctx);

        assert_eq!(
            metadata.get("waf.rule_hits").map(String::as_str),
            Some("FE-SQLI-001")
        );
        assert!(!metadata.contains_key("waf.action"));
    }

    #[test]
    fn final_body_hook_context_omits_then_restores_request_body_and_carries_waf_metadata() {
        let mut ctx = RequestContext::new("203.0.113.10".into(), "POST".into(), "/submit".into());
        // The buffered prompt: it must survive the hook-context round-trip even
        // though the clone omits it (so the full body is not copied per request).
        ctx.metadata
            .insert("request_body".into(), "{\"prompt\":\"hello\"}".into());

        let mut hook_ctx = ctx.clone_for_final_request_body_hooks();
        assert!(
            !hook_ctx.metadata.contains_key("request_body"),
            "final-body hook clone must not copy the request_body prompt"
        );

        // Simulate an `on_final_request_body` hook writing a marker + WAF metadata.
        hook_ctx
            .metadata
            .insert("ai_ratelimit_request".into(), "true".into());
        hook_ctx.set_waf_metadata("waf.rule_hits", "FE-XSS-001");
        hook_ctx.set_waf_metadata("waf.action", "monitored");

        // Mirror the handler's writeback: take the hook context's metadata + WAF
        // state, carrying the omitted request_body across the swap.
        let request_body = ctx.metadata.remove("request_body");
        ctx.metadata = hook_ctx.metadata;
        if let Some(body) = request_body {
            ctx.metadata.insert("request_body".to_string(), body);
        }
        ctx.waf_metadata_initialized = hook_ctx.waf_metadata_initialized;
        ctx.waf_owned_metadata = hook_ctx.waf_owned_metadata;
        ctx.waf_instance_scores = hook_ctx.waf_instance_scores;

        // The hook's metadata write propagated back to the live context.
        assert_eq!(
            ctx.metadata.get("ai_ratelimit_request").map(String::as_str),
            Some("true")
        );
        // The omitted request_body was restored across the swap.
        assert_eq!(
            ctx.metadata.get("request_body").map(String::as_str),
            Some("{\"prompt\":\"hello\"}")
        );
        // WAF metadata is carried across (and surfaces in log metadata).
        let metadata = clone_log_metadata(&ctx);
        assert_eq!(
            metadata.get("waf.rule_hits").map(String::as_str),
            Some("FE-XSS-001")
        );
        assert_eq!(
            metadata.get("waf.action").map(String::as_str),
            Some("monitored")
        );
    }

