    #[test]
    fn collect_response_headers_filters_hop_by_hop_headers() {
        let mut source = reqwest::header::HeaderMap::new();
        source.insert("connection", HeaderValue::from_static("keep-alive"));
        source.insert("transfer-encoding", HeaderValue::from_static("chunked"));

        let mut target = HashMap::new();
        collect_response_headers(&source, &mut target);

        assert!(!target.contains_key("connection"));
        assert!(!target.contains_key("transfer-encoding"));
    }

    #[test]
    fn backend_selected_http1_uses_reqwest_fallback() {
        assert!(should_fallback_to_reqwest_after_http2_pool_error(
            &http2_pool::Http2PoolError::BackendSelectedHttp1 {
                pool_key: "example|443".to_string()
            }
        ));

        assert!(!should_fallback_to_reqwest_after_http2_pool_error(
            &http2_pool::Http2PoolError::BackendTimeout {
                message: "timeout".to_string(),
                source: None,
            }
        ));
    }

    #[test]
    fn collect_response_headers_joins_set_cookie_with_newlines() {
        let mut source = reqwest::header::HeaderMap::new();
        source.append("set-cookie", HeaderValue::from_static("session=a"));
        source.append("set-cookie", HeaderValue::from_static("theme=dark"));

        let mut target = HashMap::new();
        collect_response_headers(&source, &mut target);

        assert_eq!(
            target.get("set-cookie").map(String::as_str),
            Some("session=a\ntheme=dark")
        );
    }

    #[test]
    fn collect_response_headers_folds_non_cookie_headers_with_commas() {
        let mut source = reqwest::header::HeaderMap::new();
        source.append("x-test", HeaderValue::from_static("one"));
        source.append("x-test", HeaderValue::from_static("two"));

        let mut target = HashMap::new();
        collect_response_headers(&source, &mut target);

        assert_eq!(target.get("x-test").map(String::as_str), Some("one, two"));
    }

    #[test]
    fn collect_response_headers_skips_invalid_utf8_values() {
        let mut source = reqwest::header::HeaderMap::new();
        source.insert(
            "x-non-utf8",
            HeaderValue::from_bytes(&[0x80, 0x81]).expect("valid raw header value"),
        );

        let mut target = HashMap::new();
        collect_response_headers(&source, &mut target);

        assert!(!target.contains_key("x-non-utf8"));
    }

    #[test]
    fn collect_hyper_response_headers_matches_reqwest_behavior() {
        let mut source = hyper::HeaderMap::new();
        source.append("x-test", HeaderValue::from_static("alpha"));
        source.append("x-test", HeaderValue::from_static("beta"));
        source.append("set-cookie", HeaderValue::from_static("a=1"));
        source.append("set-cookie", HeaderValue::from_static("b=2"));
        source.insert("upgrade", HeaderValue::from_static("h2c"));

        let mut target = HashMap::new();
        collect_hyper_response_headers(&source, &mut target);

        assert_eq!(
            target.get("x-test").map(String::as_str),
            Some("alpha, beta")
        );
        assert_eq!(
            target.get("set-cookie").map(String::as_str),
            Some("a=1\nb=2")
        );
        assert!(!target.contains_key("upgrade"));
    }

    #[test]
    fn should_stream_response_body_honors_response_body_mode_and_plugin_refinement() {
        let ctx = RequestContext::new("127.0.0.1".to_string(), "GET".to_string(), "/".to_string());
        let proxy = test_proxy(ResponseBodyMode::Stream);

        let plugin_buffers: Vec<Arc<dyn Plugin>> = vec![Arc::new(ResponseBufferPlugin {
            should_buffer: true,
        })];
        assert!(!should_stream_response_body(
            &proxy,
            &plugin_buffers,
            &ctx,
            true,
        ));

        let plugin_skips: Vec<Arc<dyn Plugin>> = vec![Arc::new(ResponseBufferPlugin {
            should_buffer: false,
        })];
        assert!(should_stream_response_body(
            &proxy,
            &plugin_skips,
            &ctx,
            true
        ));

        let buffered_proxy = test_proxy(ResponseBodyMode::Buffer);
        assert!(!should_stream_response_body(
            &buffered_proxy,
            &plugin_skips,
            &ctx,
            false,
        ));
    }

    #[test]
    fn refine_stream_response_for_content_type_downgrades_unscanned_bodies() {
        let ctx = RequestContext::new("127.0.0.1".to_string(), "GET".to_string(), "/".to_string());
        let proxy = test_proxy(ResponseBodyMode::Stream);
        let plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(ContentTypeBufferPlugin {
            buffer_content_type: "application/json",
        })];

        let json_headers =
            HashMap::from([("content-type".to_string(), "application/json".to_string())]);
        let binary_headers = HashMap::from([(
            "content-type".to_string(),
            "application/octet-stream".to_string(),
        )]);

        // Inspectable content-type: keep buffering (no downgrade).
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &plugins,
            Some(&ctx),
            200,
            &json_headers,
        ));

        // Non-inspectable content-type: downgrade buffer -> stream.
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &plugins,
            Some(&ctx),
            200,
            &binary_headers,
        ));

        // If a later `after_proxy` hook can relabel Content-Type, keep the
        // body buffered so WAF-like final-body inspection sees the final
        // client-visible headers instead of being bypassed by an early
        // backend-header downgrade.
        let relabel_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(ContentTypeBufferPlugin {
                buffer_content_type: "application/json",
            }),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "update",
                        "target": "header",
                        "key": "Content-Type",
                        "value": "application/json"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &relabel_plugins,
            Some(&ctx),
            200,
            &binary_headers,
        ));

        let mut compression_ctx = ctx.clone();
        compression_ctx.max_response_body_size_bytes = 10 * 1024 * 1024;
        compression_ctx
            .headers
            .insert("accept-encoding".to_string(), "gzip".to_string());
        let no_transform_headers = HashMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("cache-control".to_string(), "no-transform".to_string()),
        ]);
        let compression_relabel_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "update",
                        "target": "header",
                        "key": "Content-Type",
                        "value": "application/json"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &compression_relabel_plugins,
            Some(&compression_ctx),
            200,
            &no_transform_headers,
        ));

        let late_no_transform_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(
                SecurityHeaders::new(&json!({
                    "set": {"Cache-Control": "no-transform"}
                }))
                .expect("security headers config should be valid"),
            ),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &late_no_transform_plugins,
            Some(&compression_ctx),
            200,
            &json_headers,
        ));

        let earlier_no_transform_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "update",
                        "target": "header",
                        "key": "Cache-Control",
                        "value": "no-transform"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &earlier_no_transform_plugins,
            Some(&compression_ctx),
            200,
            &json_headers,
        ));

        let cacheable_json_headers = HashMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("cache-control".to_string(), "max-age=60".to_string()),
        ]);
        let cumulative_late_no_transform_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "remove",
                        "target": "header",
                        "key": "Cache-Control"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
            Arc::new(
                SecurityHeaders::new(&json!({
                    "override_existing": false,
                    "set": {"Cache-Control": "no-transform"}
                }))
                .expect("security headers config should be valid"),
            ),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &cumulative_late_no_transform_plugins,
            Some(&compression_ctx),
            200,
            &cacheable_json_headers,
        ));

        let strong_etag_headers = HashMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("etag".to_string(), "\"abc123\"".to_string()),
        ]);
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &compression_relabel_plugins,
            Some(&compression_ctx),
            200,
            &strong_etag_headers,
        ));

        let weak_etag_headers = HashMap::from([
            ("content-type".to_string(), "application/json".to_string()),
            ("etag".to_string(), "W/\"abc123\"".to_string()),
        ]);
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &compression_relabel_plugins,
            Some(&compression_ctx),
            200,
            &weak_etag_headers,
        ));

        let late_strong_etag_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(
                SecurityHeaders::new(&json!({
                    "set": {"ETag": "\"late\""}
                }))
                .expect("security headers config should be valid"),
            ),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &late_strong_etag_plugins,
            Some(&compression_ctx),
            200,
            &json_headers,
        ));

        let cumulative_late_strong_etag_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "remove",
                        "target": "header",
                        "key": "ETag"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
            Arc::new(
                SecurityHeaders::new(&json!({
                    "override_existing": false,
                    "set": {"ETag": "\"late\""}
                }))
                .expect("security headers config should be valid"),
            ),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &cumulative_late_strong_etag_plugins,
            Some(&compression_ctx),
            200,
            &weak_etag_headers,
        ));

        let inspected_late_no_transform_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(ContentTypeBufferPlugin {
                buffer_content_type: "application/json",
            }),
            Arc::new(
                SecurityHeaders::new(&json!({
                    "set": {"Cache-Control": "no-transform"}
                }))
                .expect("security headers config should be valid"),
            ),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &inspected_late_no_transform_plugins,
            Some(&compression_ctx),
            200,
            &json_headers,
        ));

        let inspected_no_transform_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
            Arc::new(ContentTypeBufferPlugin {
                buffer_content_type: "application/json",
            }),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "update",
                        "target": "header",
                        "key": "Content-Type",
                        "value": "application/json"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &inspected_no_transform_plugins,
            Some(&compression_ctx),
            200,
            &no_transform_headers,
        ));

        let removable_no_transform_headers = HashMap::from([
            ("content-type".to_string(), "text/plain".to_string()),
            ("cache-control".to_string(), "no-transform".to_string()),
        ]);
        let remove_no_transform_then_relabel_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [
                        {
                            "operation": "remove",
                            "target": "header",
                            "key": "Cache-Control"
                        },
                        {
                            "operation": "update",
                            "target": "header",
                            "key": "Content-Type",
                            "value": "application/json"
                        }
                    ]
                }))
                .expect("response transformer config should be valid"),
            ),
            Arc::new(CompressionPlugin::new(&json!({})).unwrap()),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &remove_no_transform_then_relabel_plugins,
            Some(&compression_ctx),
            200,
            &removable_no_transform_headers,
        ));

        let mut route_ctx = ctx.clone();
        route_ctx.route_override_response_transform = Some(Arc::new(vec![
            crate::plugins::utils::route_header_transform::RouteHeaderTransformRule {
                operation:
                    crate::plugins::utils::route_header_transform::RouteHeaderTransformOp::Update,
                key: "content-type".to_string(),
                value: Some("application/json".to_string()),
            },
        ]));
        let route_relabel_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(ContentTypeBufferPlugin {
                buffer_content_type: "application/json",
            }),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "apply_route_overrides": true
                }))
                .expect("route override response transformer config should be valid"),
            ),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &route_relabel_plugins,
            Some(&route_ctx),
            200,
            &binary_headers,
        ));

        // An already-streaming response stays streaming.
        assert!(refine_stream_response_for_content_type(
            true,
            &proxy,
            &plugins,
            Some(&ctx),
            200,
            &json_headers,
        ));

        // Explicit Buffer mode is never downgraded.
        let buffered_proxy = test_proxy(ResponseBodyMode::Buffer);
        assert!(!refine_stream_response_for_content_type(
            false,
            &buffered_proxy,
            &plugins,
            Some(&ctx),
            200,
            &binary_headers,
        ));

        // No request context (including retry configurations with no eligible
        // release plugin): keep the pre-flight buffering decision.
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &plugins,
            None,
            200,
            &binary_headers,
        ));

        // A plugin that needs the body for every content-type (default method)
        // blocks the downgrade even for a binary content-type.
        let always: Vec<Arc<dyn Plugin>> = vec![Arc::new(ResponseBufferPlugin {
            should_buffer: true,
        })];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &always,
            Some(&ctx),
            200,
            &binary_headers,
        ));

        let retry_ctx = retry_response_decision_context(&ctx);
        let sse_headers = HashMap::from([(
            "content-type".to_string(),
            "text/event-stream; charset=utf-8".to_string(),
        )]);
        let retry_sse_plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(RetrySseReleasePlugin)];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &retry_sse_plugins,
            Some(&retry_ctx),
            200,
            &sse_headers,
        ));
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &retry_sse_plugins,
            Some(&retry_ctx),
            200,
            &json_headers,
        ));
        let retry_sse_with_json_only_inspector: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(RetrySseReleasePlugin),
            Arc::new(ContentTypeBufferPlugin {
                buffer_content_type: "application/json",
            }),
        ];
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &retry_sse_with_json_only_inspector,
            Some(&retry_ctx),
            200,
            &sse_headers,
        ));
        let retry_sse_blocked_by_other_buffering_plugin: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(RetrySseReleasePlugin),
            Arc::new(ResponseBufferPlugin {
                should_buffer: true,
            }),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &retry_sse_blocked_by_other_buffering_plugin,
            Some(&retry_ctx),
            200,
            &sse_headers,
        ));
    }

    #[test]
    fn refine_stream_response_releases_irrelevant_body_validator_media_types() {
        let ctx = RequestContext::new("127.0.0.1".into(), "GET".into(), "/download".into());
        let proxy = test_proxy(ResponseBodyMode::Stream);
        let plugins: Vec<Arc<dyn Plugin>> = vec![Arc::new(
            crate::plugins::body_validator::BodyValidator::new(&json!({
                "response_required_fields": ["id"]
            }))
            .unwrap(),
        )];

        let png_headers = HashMap::from([("content-type".to_string(), "image/png".to_string())]);
        let json_headers =
            HashMap::from([("content-type".to_string(), "application/json".to_string())]);

        assert!(
            refine_stream_response_for_content_type(
                false,
                &proxy,
                &plugins,
                Some(&ctx),
                200,
                &png_headers,
            ),
            "body_validator must release non-matching image/png"
        );
        assert!(
            !refine_stream_response_for_content_type(
                false,
                &proxy,
                &plugins,
                Some(&ctx),
                200,
                &json_headers,
            ),
            "matching JSON must remain buffered"
        );

        // Under retries, irrelevant types still release once headers are known.
        let retry_ctx = retry_response_decision_context(&ctx);
        assert!(refine_stream_response_for_content_type(
            false,
            &proxy,
            &plugins,
            Some(&retry_ctx),
            200,
            &png_headers,
        ));
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &plugins,
            Some(&retry_ctx),
            200,
            &json_headers,
        ));

        // A later Content-Type rewrite keeps the original buffered decision.
        let rewrite_plugins: Vec<Arc<dyn Plugin>> = vec![
            Arc::new(
                crate::plugins::body_validator::BodyValidator::new(&json!({
                    "response_required_fields": ["id"]
                }))
                .unwrap(),
            ),
            Arc::new(
                crate::plugins::response_transformer::ResponseTransformer::new(&json!({
                    "rules": [{
                        "operation": "update",
                        "target": "header",
                        "key": "Content-Type",
                        "value": "application/json"
                    }]
                }))
                .expect("response transformer config should be valid"),
            ),
        ];
        assert!(!refine_stream_response_for_content_type(
            false,
            &proxy,
            &rewrite_plugins,
            Some(&ctx),
            200,
            &png_headers,
        ));
    }

    // ---------------------------------------------------------------------
    // H3 transport-failure classifier tests (gates the capability downgrade)
    // ---------------------------------------------------------------------

    #[test]
    fn is_h3_transport_error_class_covers_connection_failures() {
        for class in [
            retry::ErrorClass::ConnectionRefused,
            retry::ErrorClass::ConnectionTimeout,
            retry::ErrorClass::ConnectionReset,
            retry::ErrorClass::ConnectionClosed,
            retry::ErrorClass::TlsError,
            retry::ErrorClass::ProtocolError,
            retry::ErrorClass::DnsLookupError,
            retry::ErrorClass::PortExhaustion,
        ] {
            assert!(
                is_h3_transport_error_class(class),
                "expected {class:?} to be a transport-class failure"
            );
        }
    }

    #[test]
    fn is_h3_transport_error_class_excludes_application_errors() {
        // Application-layer errors must NOT downgrade the H3 capability — the
        // backend is fine, the request itself is bad. Downgrading here would
        // route subsequent requests via reqwest for no operational reason.
        //
        // `GracefulRemoteClose` is also excluded: `H3_NO_ERROR` /
        // `RemoteClosing` is a spec-legal teardown signal (RFC 9114 §8.1),
        // not a transport-level capability fault — see the docstring on
        // [`crate::http3::client::H3PoolError::graceful_close`] and the
        // matching short-circuit in
        // [`crate::http3::server::classify_h3_error`]. Adding it to the
        // positive list in `is_h3_transport_error_class` would re-introduce
        // the regression where a fast responder racing FIN with
        // `CONNECTION_CLOSE` permanently disables H3 for the backend.
        //
        // `ReadWriteTimeout` is excluded for the same capability reason:
        // a backend that stalls after accepting a request is slow or wedged,
        // but it has not proved that the native H3 pool itself is invalid.
        //
        // `ConnectionPoolError` is also excluded: local QUIC endpoint/config
        // failures such as CID exhaustion or endpoint shutdown are gateway-side
        // resource conditions, not evidence that the backend lost H3 support.
        for class in [
            retry::ErrorClass::ClientDisconnect,
            retry::ErrorClass::RequestBodyTooLarge,
            retry::ErrorClass::ResponseBodyTooLarge,
            retry::ErrorClass::GracefulRemoteClose,
            retry::ErrorClass::ReadWriteTimeout,
            retry::ErrorClass::ConnectionPoolError,
            retry::ErrorClass::DispatchPolicyRejected,
            retry::ErrorClass::RequestError,
        ] {
            assert!(
                !is_h3_transport_error_class(class),
                "{class:?} must not trigger an H3 downgrade"
            );
        }
    }

    #[test]
    fn is_h3_transport_failure_ignores_connection_error_flag() {
        // `classify_h3_error` marks GOAWAY / stream reset with
        // `connection_error=false`, so the downgrade predicate must NOT
        // require that flag. The decision hinges on `error_class` alone:
        // transport-level classes downgrade, application-layer classes and
        // backend read timeouts do not.
        let mk = |connection_error: bool, error_class: Option<retry::ErrorClass>| {
            retry::BackendResponse {
                status_code: 502,
                body: retry::ResponseBody::Buffered(Vec::new()),
                headers: HashMap::new(),
                connection_error,
                backend_resolved_ip: None,
                error_class,
            }
        };

        // Connect-class failure with connection_error=true: transport failure.
        assert!(is_h3_transport_failure(&mk(
            true,
            Some(retry::ErrorClass::ConnectionTimeout)
        )));
        // ProtocolError (GOAWAY / stream reset) with connection_error=false
        // MUST still downgrade — this is the P2 bug the review called out.
        assert!(is_h3_transport_failure(&mk(
            false,
            Some(retry::ErrorClass::ProtocolError)
        )));
        // ReadWriteTimeout with connection_error=false does NOT downgrade:
        // the backend stalled after accepting the request, but capability is
        // still valid.
        assert!(!is_h3_transport_failure(&mk(
            false,
            Some(retry::ErrorClass::ReadWriteTimeout)
        )));
        // Missing error_class → not classifiable as transport.
        assert!(!is_h3_transport_failure(&mk(true, None)));
        // Application-layer error class: NOT a transport failure.
        assert!(!is_h3_transport_failure(&mk(
            true,
            Some(retry::ErrorClass::ClientDisconnect)
        )));
        assert!(!is_h3_transport_failure(&mk(
            false,
            Some(retry::ErrorClass::RequestBodyTooLarge)
        )));
    }

    // ── Connection-error classification boundary tests ─────────────────
    //
    // These exercise the unified contract: every protocol classifier funnels
    // through `retry::request_reached_wire`, and the H3 thin wrapper
    // (`classify_h3_error`) inherits the corrected ordering from
    // `classify_http3_error` so stream-level RESET_STREAM is no longer
    // mislabeled `ConnectionReset` and load-balancer "upstream" messages no
    // longer false-match the bare "stream" substring.

    /// Small helper to invoke the proxy/mod.rs `classify_h3_error` against
    /// a synthesized `anyhow::Error` carrying a particular message. Mirrors
    /// the runtime path where the H3 pool wraps quinn / h3 errors in
    /// anyhow before bubbling them up.
    fn classify_h3_message(msg: &str) -> retry::ErrorClass {
        let err: anyhow::Error = anyhow::anyhow!("{}", msg);
        let (_, class) = super::classify_h3_error(err.as_ref());
        class
    }

    #[test]
    fn classify_h3_error_orders_protocol_tokens_before_bare_reset() {
        // Pre-fix: `lower.contains("reset")` matched RESET_STREAM (an h3
        // stream-level abort, not a connection reset) BEFORE the protocol
        // ordering had a chance to fire. Fixed by aligning with
        // `classify_http3_error` — these stream-level tokens land as
        // `ProtocolError`, not `ConnectionReset`.
        assert_eq!(
            classify_h3_message("h3 stream RESET_STREAM (code=H3_REQUEST_REJECTED)"),
            retry::ErrorClass::ProtocolError,
            "RESET_STREAM is a stream-level abort — must classify as ProtocolError"
        );
        assert_eq!(
            classify_h3_message("stream reset by backend"),
            retry::ErrorClass::ProtocolError
        );
        assert_eq!(
            classify_h3_message("reset_stream"),
            retry::ErrorClass::ProtocolError
        );
    }

    #[test]
    fn classify_h3_error_does_not_false_match_upstream_substring() {
        // Pre-fix: the bare `lower.contains("stream")` substring matched
        // "upstream", so any load-balancer error mentioning "upstream
        // target" landed as ProtocolError. The shared classifier removed
        // the bare "stream" check; "upstream" no longer false-matches.
        let class = classify_h3_message("upstream target unreachable: connection refused");
        assert_eq!(
            class,
            retry::ErrorClass::ConnectionRefused,
            "the literal 'upstream' must not steer classification toward ProtocolError"
        );
    }

    #[test]
    fn classify_h3_error_recognizes_application_close() {
        // h3 0.0.8 renders quinn::ConnectionError::ApplicationClose as the
        // bare token "ApplicationClose" — without the explicit substring
        // match in the shared classifier this would have landed as
        // RequestError (since the bare "closed" substring requires
        // trailing 'd'). Confirm we now classify it as ConnectionClosed.
        assert_eq!(
            classify_h3_message("h3 connection closed: ApplicationClose code=0x100"),
            retry::ErrorClass::ConnectionClosed
        );
    }

    #[test]
    fn classify_h3_error_recognizes_h3_protocol_codes() {
        // Any token starting with `H3_` is an h3 protocol error code
        // (H3_FRAME_UNEXPECTED, H3_FRAME_ERROR, etc.). Must classify as
        // ProtocolError so the capability registry downgrade fires.
        assert_eq!(
            classify_h3_message("LocalError::Application { code: H3_FRAME_UNEXPECTED }"),
            retry::ErrorClass::ProtocolError
        );
        assert_eq!(
            classify_h3_message("h3::Error: GoAway received"),
            retry::ErrorClass::ProtocolError
        );
    }

    #[test]
    fn classify_h3_error_distinguishes_connect_vs_read_timeout() {
        assert_eq!(
            classify_h3_message("QUIC connect timeout after 5s"),
            retry::ErrorClass::ConnectionTimeout
        );
        assert_eq!(
            classify_h3_message("recv_data timed out"),
            retry::ErrorClass::ReadWriteTimeout
        );
    }

    #[test]
    fn classify_h3_error_dns_and_tls_remain_pre_wire() {
        // DNS / TLS classifications gate `connection_error=true` in the
        // gateway because the request never went on the wire. Verify the
        // boundary stays consistent.
        let dns = classify_h3_message("DNS resolution failed: no record found");
        assert_eq!(dns, retry::ErrorClass::DnsLookupError);
        assert!(!retry::request_reached_wire(dns));

        let tls = classify_h3_message("TLS handshake failed: certificate invalid");
        assert_eq!(tls, retry::ErrorClass::TlsError);
        assert!(!retry::request_reached_wire(tls));
    }

    #[test]
    fn classify_h3_error_protocol_class_reaches_wire() {
        // Protocol errors happen AFTER the request has been sent, so they
        // must `request_reached_wire=true` (`connection_error=false`)
        // — the backend may have processed the request, retries must
        // respect `retry_on_methods`.
        let protocol = classify_h3_message("h3_frame_error: GOAWAY");
        assert_eq!(protocol, retry::ErrorClass::ProtocolError);
        assert!(retry::request_reached_wire(protocol));
    }

    #[test]
    fn classify_h3_error_connect_refused_is_pre_wire() {
        let class = classify_h3_message("Connection refused: ECONNREFUSED");
        assert_eq!(class, retry::ErrorClass::ConnectionRefused);
        assert!(!retry::request_reached_wire(class));
    }

    #[test]
    fn classify_h3_pool_error_short_circuits_on_graceful_close_flag() {
        // Regression: when an `H3PoolError` carries `is_graceful_close=true`
        // (set at the recv_response sites for `H3_NO_ERROR` ApplicationClose
        // / RemoteClosing), the classifier MUST surface the dedicated
        // `GracefulRemoteClose` class so `is_h3_transport_error_class`
        // returns false and the gateway skips `mark_h3_unsupported`. The
        // underlying error chain would otherwise classify as
        // `ConnectionClosed`, which IS in the transport-error list.
        let e = crate::http3::client::H3PoolError::graceful_close(anyhow::anyhow!(
            "recv_response after graceful remote close: ApplicationClose"
        ));
        let (kind, class) = super::classify_h3_pool_error(&e);
        assert_eq!(class, retry::ErrorClass::GracefulRemoteClose);
        assert_eq!(kind, "graceful_remote_close");
        assert!(
            !super::is_h3_transport_error_class(class),
            "GracefulRemoteClose must NOT be classified as a transport error \
             — that's exactly what suppresses the cached H3 capability \
             downgrade"
        );
    }

    #[test]
    fn classify_h3_pool_error_falls_through_on_post_wire_errors() {
        // Without the graceful-close flag, the classifier delegates to
        // `classify_h3_error` and returns the underlying class. A normal
        // post-wire `recv_response` timeout is a backend read timeout, not
        // an H3 capability failure, so it must not fire `mark_h3_unsupported`.
        let e = crate::http3::client::H3PoolError::post_wire(anyhow::anyhow!(
            "recv_response failed: timed out reading from QUIC stream"
        ));
        let (_, class) = super::classify_h3_pool_error(&e);
        // String-heuristic fallback in classify_http3_error matches "timed out"
        // → ReadWriteTimeout (read-side, no "connect" token).
        assert_eq!(class, retry::ErrorClass::ReadWriteTimeout);
        assert!(
            !super::is_h3_transport_error_class(class),
            "Post-wire backend read timeout must not trigger H3 downgrade"
        );
    }

    #[test]
    fn classify_h3_pool_error_short_circuits_on_read_timeout_flag() {
        // The typed `H3PoolError::read_timeout` constructor (used by the
        // `backend_read_timeout_ms` deadline wraps around `recv_response()`
        // and the buffered `recv_data` drain) must classify as
        // `ReadWriteTimeout` regardless of the error message — no string
        // heuristics. The message below deliberately avoids any "timeout"
        // token to prove the typed flag drives classification.
        let e = crate::http3::client::H3PoolError::read_timeout(anyhow::anyhow!(
            "backend stalled mid-response"
        ));
        assert!(e.is_read_timeout());
        assert!(
            e.request_on_wire(),
            "read timeouts are post-wire: the request was committed before \
             the gateway started waiting on the response"
        );
        assert!(!e.is_graceful_close());
        let (kind, class) = super::classify_h3_pool_error(&e);
        assert_eq!(class, retry::ErrorClass::ReadWriteTimeout);
        assert_eq!(kind, retry::error_class_log_kind(class));
        assert!(
            !super::is_h3_transport_error_class(class),
            "H3 backend read timeout must not trigger mark_h3_unsupported"
        );
    }

    #[test]
    fn h3_read_timeout_backend_response_maps_to_504_backend_timeout() {
        // The H3 read-timeout arms must produce the same client-visible
        // outcome as the direct-H2 / HBONE / sidecar-mTLS read-timeout arms:
        // 504 + {"error":"Backend timeout"} + ReadWriteTimeout, and
        // connection_error=false so `retry_on_connect_failure` cannot replay
        // a request the backend already received.
        let resp = super::h3_read_timeout_backend_response(Some("10.0.0.1".to_string()));
        assert_eq!(resp.status_code, 504);
        let ResponseBody::Buffered(body) = &resp.body else {
            panic!("H3 read-timeout response must be buffered");
        };
        assert_eq!(body.as_slice(), br#"{"error":"Backend timeout"}"#);
        assert!(
            !resp.connection_error,
            "post-wire read timeout must not be treated as a connect failure"
        );
        assert_eq!(resp.error_class, Some(retry::ErrorClass::ReadWriteTimeout));
        assert_eq!(resp.backend_resolved_ip.as_deref(), Some("10.0.0.1"));
    }

    // ── `record_port_exhaustion_if_class` (H3 native paths) ─────────────
    //
    // The H3 native dispatcher (`proxy_to_backend_http3`,
    // `proxy_to_backend_http3_retry`) and the H3 frontend → H3 backend
    // fast path in `http3::server` were missing the `record_port_exhaustion`
    // bump that every other backend dispatcher performs (reqwest path,
    // gRPC pool, H2 pool, TCP backend connect, H3 cross-protocol bridge).
    // Result: `/overload.port_exhaustion_events` undercounted any time
    // an H3 frontend → H3 backend dispatch hit ephemeral-port exhaustion
    // (e.g. EADDRNOTAVAIL on a high-RPS gateway with constrained
    // `ip_local_port_range`). All eight H3 sites now funnel through this
    // helper, so verifying the helper itself is sufficient regression
    // protection: if a future H3 dispatch site forgets the call,
    // `port_exhaustion_events` will silently undercount on that path —
    // but the helper signature documents the contract.

    #[test]
    fn record_port_exhaustion_if_class_bumps_counter_only_for_port_exhaustion() {
        let overload = crate::overload::OverloadState::new();
        assert_eq!(
            overload
                .port_exhaustion_events
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "counter should start at 0"
        );

        // Synthetic H3 PortExhaustion outcome: the dispatch site obtains
        // `ErrorClass::PortExhaustion` from the H3 classifier (e.g. via
        // an EADDRNOTAVAIL surfaced as "bind: address not available")
        // and hands it to this helper. The helper must bump the counter
        // and return true.
        let bumped =
            super::record_port_exhaustion_if_class(&overload, retry::ErrorClass::PortExhaustion);
        assert!(bumped, "PortExhaustion must bump the counter");
        assert_eq!(
            overload
                .port_exhaustion_events
                .load(std::sync::atomic::Ordering::Relaxed),
            1
        );

        // Repeated bumps accumulate — every dispatch site that hits
        // PortExhaustion contributes independently.
        super::record_port_exhaustion_if_class(&overload, retry::ErrorClass::PortExhaustion);
        super::record_port_exhaustion_if_class(&overload, retry::ErrorClass::PortExhaustion);
        assert_eq!(
            overload
                .port_exhaustion_events
                .load(std::sync::atomic::Ordering::Relaxed),
            3
        );
    }

    #[test]
    fn record_port_exhaustion_if_class_is_no_op_for_non_port_exhaustion() {
        let overload = crate::overload::OverloadState::new();

        // Every other class the H3 classifier can return — including the
        // transport-class siblings that DO trigger `mark_h3_unsupported`
        // — must NOT bump the port-exhaustion counter. The metric is
        // narrow: only ephemeral-port exhaustion. Other transport
        // failures have their own diagnostics (FD pressure, conn count,
        // last_probe_error on the capability registry).
        for class in [
            retry::ErrorClass::ConnectionRefused,
            retry::ErrorClass::ConnectionTimeout,
            retry::ErrorClass::ConnectionReset,
            retry::ErrorClass::ConnectionClosed,
            retry::ErrorClass::TlsError,
            retry::ErrorClass::ProtocolError,
            retry::ErrorClass::DnsLookupError,
            retry::ErrorClass::ConnectionPoolError,
            retry::ErrorClass::ReadWriteTimeout,
            retry::ErrorClass::ClientDisconnect,
            retry::ErrorClass::RequestBodyTooLarge,
            retry::ErrorClass::ResponseBodyTooLarge,
            retry::ErrorClass::GracefulRemoteClose,
            retry::ErrorClass::DispatchPolicyRejected,
            retry::ErrorClass::RequestError,
        ] {
            let bumped = super::record_port_exhaustion_if_class(&overload, class);
            assert!(!bumped, "{class:?} must not bump port_exhaustion_events");
        }
        assert_eq!(
            overload
                .port_exhaustion_events
                .load(std::sync::atomic::Ordering::Relaxed),
            0,
            "counter should remain 0 across non-PortExhaustion classes"
        );
    }

    // ── Fix 5: `should_bypass_h2_coalesce_for_large_response` ───────────
    // Validates the per-response decision that steers plain-HTTPS
    // direct-H2 responses away from `CoalescingH2Body` when the
    // backend is already emitting large frames (response >= 512 KiB).

    #[test]
    fn h2_coalesce_bypass_skips_large_known_length_when_unlimited() {
        // 1 MiB response, no cap → bypass.
        assert!(super::should_bypass_h2_coalesce_for_large_response(
            Some(1_048_576),
            0,
        ));
    }

    #[test]
    fn h2_coalesce_bypass_skips_exactly_at_threshold() {
        // Threshold is 512 KiB; exactly 512 KiB should qualify (>=, not >).
        assert!(super::should_bypass_h2_coalesce_for_large_response(
            Some(512 * 1024),
            0,
        ));
    }

    #[test]
    fn h2_coalesce_bypass_keeps_coalescer_for_small_response() {
        // Under 512 KiB → coalescer still wins.
        assert!(!super::should_bypass_h2_coalesce_for_large_response(
            Some(64 * 1024),
            0,
        ));
        // 256 KiB is still under threshold.
        assert!(!super::should_bypass_h2_coalesce_for_large_response(
            Some(256 * 1024),
            0,
        ));
    }

    #[test]
    fn h2_coalesce_bypass_requires_known_content_length() {
        // Chunked / unknown length → keep coalescer. We cannot assume
        // frames are already large when the backend has not told us
        // the total size.
        assert!(!super::should_bypass_h2_coalesce_for_large_response(
            None, 0
        ));
        // Same with a size limit configured — unknown length still
        // retains the coalescer, which is the size-enforcement
        // pathway when CL is absent.
        assert!(!super::should_bypass_h2_coalesce_for_large_response(
            None,
            10 * 1024 * 1024,
        ));
    }

    #[test]
    fn h2_coalesce_bypass_honours_response_size_limit() {
        // Limit is 2 MiB, response is 5 MiB → bypass disabled so the
        // coalescer's size-enforcement path stays in play even though
        // the body itself is larger than the threshold. (The upstream
        // admission check should reject CL > limit earlier, but the
        // decision layer is defensive.)
        assert!(!super::should_bypass_h2_coalesce_for_large_response(
            Some(5 * 1024 * 1024),
            2 * 1024 * 1024,
        ));
    }

    #[test]
    fn h2_coalesce_bypass_allows_response_exactly_at_size_limit() {
        // Limit is 1 MiB, response is exactly 1 MiB — inclusive, so
        // bypass is allowed.
        assert!(super::should_bypass_h2_coalesce_for_large_response(
            Some(1024 * 1024),
            1024 * 1024,
        ));
    }

    /// Guards the declared-Content-Length fast-path reject used by every
    /// streaming H3 retry attempt: only a nonzero limit with a parseable
    /// over-limit Content-Length triggers the pre-stream 502.
    #[test]
    fn declared_response_length_exceeds_limit_only_when_header_is_over_cap() {
        let mut headers = HashMap::new();
        assert_eq!(declared_response_length_exceeds_limit(&headers, 10), None);

        headers.insert("content-length".to_string(), "11".to_string());
        assert_eq!(declared_response_length_exceeds_limit(&headers, 0), None);
        assert_eq!(declared_response_length_exceeds_limit(&headers, 11), None);
        assert_eq!(
            declared_response_length_exceeds_limit(&headers, 10),
            Some(11)
        );

        headers.insert("content-length".to_string(), "not-a-number".to_string());
        assert_eq!(declared_response_length_exceeds_limit(&headers, 10), None);
    }

    /// The 502 built for an over-limit H3 response must not replay (no
    /// retry: `ResponseBodyTooLarge` is in `should_retry`'s deny-list and
    /// `connection_error` is false) and must not downgrade the cached H3
    /// capability (`ResponseBodyTooLarge` is excluded from
    /// `is_h3_transport_error_class`).
    #[test]
    fn h3_response_body_too_large_response_is_non_retryable_and_not_a_transport_failure() {
        let proxy = test_proxy(ResponseBodyMode::Stream);
        let resp = h3_response_body_too_large_response(&proxy, None, Some(11), 10);
        assert_eq!(resp.status_code, 502);
        assert!(!resp.connection_error);
        assert_eq!(
            resp.error_class,
            Some(retry::ErrorClass::ResponseBodyTooLarge)
        );
        assert!(
            !super::is_h3_transport_failure(&resp),
            "a size-limit reject must never mark the backend H3-unsupported"
        );
    }

    /// XFF truth table — identical across H1/H2/H3 frontends (issue #1571):
    ///
    /// | shape                              | inbound XFF | client vs peer | outbound XFF       |
    /// |------------------------------------|-------------|----------------|--------------------|
    /// | no proxy in front                  | none        | equal          | peer               |
    /// | trusted LB sending XFF             | chain       | differ         | chain, peer        |
    /// | trusted LB sending real-IP header  | none        | differ         | client, peer       |
    /// | untrusted peer                     | none        | equal          | peer               |
    #[test]
    fn build_xff_value_appends_peer_and_seeds_resolved_client() {
        let no_policy =
            client_ip::TrustedProxies::parse_strict("", "test").expect("empty trust list is valid");
        let lb_trusted = client_ip::TrustedProxies::parse_strict("10.0.0.7", "test")
            .expect("valid trusted proxy list");

        // No proxy in front: client == peer, no inbound chain.
        assert_eq!(
            build_xff_value(None, "203.0.113.1", "203.0.113.1", &no_policy),
            "203.0.113.1"
        );

        // Trusted LB sending XFF: resolved client is already in the chain —
        // append only the immediate peer (never duplicate the client).
        assert_eq!(
            build_xff_value(
                Some("198.51.100.7"),
                "198.51.100.7",
                "10.0.0.7",
                &lb_trusted
            ),
            "198.51.100.7, 10.0.0.7"
        );
        assert_eq!(
            build_xff_value(
                Some("198.51.100.7, 172.16.0.3"),
                "198.51.100.7",
                "10.0.0.7",
                &lb_trusted
            ),
            "198.51.100.7, 172.16.0.3, 10.0.0.7"
        );

        // Trusted LB sending only a real-IP header: no inbound chain but the
        // resolved client differs from the peer — seed with the client so
        // the real client is not lost.
        assert_eq!(
            build_xff_value(None, "203.0.113.9", "10.0.0.7", &lb_trusted),
            "203.0.113.9, 10.0.0.7"
        );

        // Untrusted peer (spoofed real-IP header ignored): resolution kept
        // client == peer, so the seed must not duplicate.
        assert_eq!(
            build_xff_value(None, "192.0.2.6", "192.0.2.6", &lb_trusted),
            "192.0.2.6"
        );

        // Untrusted peer sending a spoofed XFF chain while a trust policy is
        // configured: the inbound chain is dropped — backends must never see
        // attacker-seeded addresses the gateway itself refused to trust.
        assert_eq!(
            build_xff_value(Some("6.6.6.6"), "192.0.2.6", "192.0.2.6", &lb_trusted),
            "192.0.2.6"
        );

        // No trust policy configured: transparent nginx-style passthrough —
        // the inbound chain is preserved and the peer appended.
        assert_eq!(
            build_xff_value(Some("198.51.100.7"), "192.0.2.6", "192.0.2.6", &no_policy),
            "198.51.100.7, 192.0.2.6"
        );

        // Trusted LB resolving via FERRUM_REAL_IP_HEADER while passing an
        // XFF chain through verbatim: the resolved client is not in the
        // chain, so it must be seeded before the peer — backends consuming
        // XFF must still see the authenticated client.
        assert_eq!(
            build_xff_value(Some("198.51.100.7"), "203.0.113.9", "10.0.0.7", &lb_trusted),
            "198.51.100.7, 203.0.113.9, 10.0.0.7"
        );
        // ...but when the resolved client already appears in the chain
        // (canonicalization differences included), nothing is duplicated.
        assert_eq!(
            build_xff_value(
                Some("198.51.100.7, 203.0.113.9"),
                "203.0.113.9",
                "10.0.0.7",
                &lb_trusted
            ),
            "198.51.100.7, 203.0.113.9, 10.0.0.7"
        );
        assert_eq!(
            build_xff_value(Some("2001:DB8::1"), "2001:db8::1", "10.0.0.7", &lb_trusted),
            "2001:DB8::1, 10.0.0.7",
            "IPv6 case differences must not duplicate the client in the chain"
        );
    }

    /// Complementary ordering guard for the inbound HBONE relay synthesis that
    /// must stay ahead of the REGISTRY_ONLY route-miss gate in the same arm.
    /// Executable request-path coverage for the gate itself lives in
    /// `tests/integration/mesh_outbound_registry_route_miss_tests.rs`; this
    /// fingerprint only asserts the hard-to-drive HBONE-vs-gate source order.
    #[test]
    fn registry_only_route_miss_gate_precedes_generic_not_found() {
        let src = include_str!("mod.rs");
        let gate_pos = src
            .find("enforcement.http_route_miss_reject_status")
            .expect("REGISTRY_ONLY route-miss gate helper call not found");
        let not_found_pos = gate_pos
            + src[gate_pos..]
                .find("No route matched for request path")
                .expect("generic route-miss log after the REGISTRY_ONLY gate not found");
        assert!(
            gate_pos < not_found_pos,
            "REGISTRY_ONLY route-miss evaluation must run before the generic 404 response"
        );
        let relay_pos = src[..not_found_pos]
            .rfind("build_inbound_hbone_relay_proxy(req.uri().authority()")
            .expect("inbound HBONE relay synthesis must remain in the route-miss arm");
        assert!(
            relay_pos < gate_pos,
            "inbound HBONE relay synthesis must stay ahead of the REGISTRY_ONLY route-miss gate"
        );
    }

    /// Regression guard: the gRPC request-body-hook branch must always
    /// return the collected request bytes alongside the dispatch result,
    /// even when the response is being streamed.
    ///
    /// Background: the response-streaming decision (`grpc_should_stream`)
    /// is orthogonal to whether the REQUEST body must be replayable on a
    /// connection-level retry. The retry loop fires on connection errors
    /// observed BEFORE response headers, so streaming-vs-buffering the
    /// response has no bearing on whether the request needs to be
    /// replayable. The OLD pattern collapsed both into a single decision:
    ///
    /// ```ignore
    /// if grpc_should_stream { (result, Bytes::new()) }
    /// else                  { (result, grpc_req_body) }
    /// ```
    ///
    /// which silently fed the retry loop an empty request body whenever a
    /// body-hook proxy ALSO had `retry_on_connect_failure` enabled and the
    /// streaming-response gate was open. This test fingerprints the fixed
    /// shape so a future cleanup cannot accidentally re-introduce the
    /// branching.
    #[test]
    fn grpc_hook_path_returns_collected_request_body_unconditionally() {
        let src = include_str!("mod.rs");
        let marker = "// Dispatch to backend with pre-collected body bytes";
        let block_start = src
            .find(marker)
            .expect("hook-path dispatch block marker not found");
        // The block ends at the `} else {` that opens the `grpc_needs_request_body_hooks=false` arm.
        let tail = &src[block_start..];
        let block_end = tail
            .find("} else {\n            // Fast path: no plugin body hooks needed")
            .expect("end of grpc hook-path branch not found");
        let block = &tail[..block_end];

        for (i, line) in block.lines().enumerate() {
            let trimmed = line.trim_start();
            if trimmed.starts_with("//") || trimmed.starts_with("///") {
                continue;
            }
            assert!(
                !trimmed.starts_with("if grpc_should_stream"),
                "regression at relative line {} of grpc hook-path branch: \
                 found `if grpc_should_stream` split on the success path. \
                 Always return the collected request body so a connect-level \
                 retry can replay it. Offending line:\n  {}",
                i + 1,
                line
            );
            assert!(
                !trimmed.contains("Bytes::new()"),
                "regression at relative line {} of grpc hook-path branch: \
                 the success path must return `grpc_req_body`, not \
                 `Bytes::new()`. Offending line:\n  {}",
                i + 1,
                line
            );
        }
    }

    /// Regression guard: the gRPC retry loop must propagate the original
    /// streaming-response decision into each retry attempt.
    ///
    /// Background: the loop only retries CONNECTION errors that surface
    /// BEFORE response headers (`BackendUnavailable` /
    /// `BackendTimeout::Connect`). Once any retry attempt produces a
    /// response, the loop's match falls through and the response is
    /// handed off to the downstream client untouched. Buffering the retry
    /// response therefore has no benefit but reintroduces the
    /// trailer-stall the rest of this PR is fixing — a single transient
    /// connect failure on a server-streaming RPC would silently downgrade
    /// the entire response to "wait for the whole body".
    #[test]
    fn grpc_retry_loop_passes_streaming_decision_through() {
        let src = include_str!("mod.rs");
        let loop_start = src
            .find("// gRPC retry loop — retries on connection failures")
            .expect("gRPC retry loop marker not found");
        let tail = &src[loop_start..];
        let loop_end = tail
            .find("\n        }\n\n        let backend_total_ms = backend_start.elapsed()")
            .expect("end of gRPC retry loop not found");
        let loop_body = &tail[..loop_end];

        let call_marker = "grpc_proxy::proxy_grpc_request_from_bytes(";
        let call_idx = loop_body
            .find(call_marker)
            .expect("retry-loop call to proxy_grpc_request_from_bytes not found");
        let call_tail = &loop_body[call_idx..];
        let call_end = call_tail
            .find(")\n                .await")
            .expect("end of retry-loop call not found");
        let call_args = &call_tail[..call_end];

        // The OLD pattern hard-coded the streaming flag to `false` on the
        // retry path. Either explicit `false,` or any phrasing that
        // disables streaming irrespective of the initial decision is a
        // regression.
        for (i, line) in call_args.lines().enumerate() {
            let trimmed = line.trim();
            if trimmed.starts_with("//") || trimmed.starts_with("///") {
                continue;
            }
            assert!(
                trimmed != "false," && trimmed != "false",
                "regression at relative line {} of gRPC retry call: \
                 `proxy_grpc_request_from_bytes` is invoked with a hard-\
                 coded `false` streaming flag. Pass `grpc_should_stream` \
                 instead so successful retries keep the trailer-stall fix \
                 active. Offending line:\n  {}",
                i + 1,
                line
            );
        }
        assert!(
            call_args.contains("grpc_should_stream"),
            "expected `grpc_should_stream` to be threaded into the retry \
             call to proxy_grpc_request_from_bytes; argument list was:\n{}",
            call_args
        );
    }

    // ----- Pool warmup partition + gating tests --------------------------
    //
    // These cover the dual optimization in `warmup_connection_pools`:
    //   1. Phase-1 partitioning sends HTTP-only candidates to the parallel
    //      warmup batch (which runs alongside the capability refresh) and
    //      HTTPS candidates to the gated phase-2 batch.
    //   2. Phase-2 gating skips reqwest HEADs for HTTPS targets the
    //      capability registry has already classified as covered by the
    //      direct HTTP/2 pool, while still warming `Unknown` /
    //      `Unsupported` targets so the fallback pool is ready.

    use super::backend_capabilities::{
        BackendCapabilityRecord, BackendCapabilityRegistry, ProtocolSupport, capability_key,
        capability_key_for_proxy_target,
    };
    use crate::config::types::{BackendScheme, DispatchKind, Upstream};

    /// Build a minimal HTTPS proxy at `host:port`. The proxy carries the
    /// default TLS config so it shares a capability key with the registry
    /// fixtures below.
    fn warmup_test_proxy(id: &str, scheme: BackendScheme, host: &str, port: u16) -> Proxy {
        let mut proxy: Proxy = serde_json::from_value(json!({
            "id": id,
            "backend_host": host,
            "backend_port": port,
            "backend_scheme": match scheme {
                BackendScheme::Http => "http",
                BackendScheme::Https => "https",
                _ => "https",
            },
            "listen_path": "/",
        }))
        .expect("warmup test proxy should deserialize");
        proxy.dispatch_kind = DispatchKind::from(scheme);
        proxy
    }

    fn upstream_with_targets(id: &str, targets: &[(&str, u16)]) -> Upstream {
        let targets_json: Vec<_> = targets
            .iter()
            .map(|(host, port)| {
                json!({
                    "host": host,
                    "port": port,
                })
            })
            .collect();
        serde_json::from_value(json!({
            "id": id,
            "name": id,
            "algorithm": "round_robin",
            "targets": targets_json,
        }))
        .expect("upstream should deserialize")
    }

    use crate::config::types::{BackoffStrategy, RetryConfig};

    /// Empty maps for tests that only need one bucket populated.
    fn empty_candidate_maps() -> (
        HashMap<String, ReqwestWarmupCandidate>,
        HashMap<String, ReqwestWarmupCandidate>,
    ) {
        (HashMap::new(), HashMap::new())
    }

    /// Synthesize a stand-in pool key for the test. Real production keys
    /// come from `ConnectionPool::pool_key_for_warmup(proxy)` and embed
    /// `(scheme, host, port, dns_override, ca, mtls_*, verify)`. For the
    /// dedup contract these tests exercise, ANY string serves — same key
    /// → dedupe, different key → separate candidate. Embedding the proxy
    /// id by default makes tests where every proxy has a unique pool key
    /// trivially correct, while tests that need shared keys can pass an
    /// explicit string.
    fn fake_pool_key(proxy_id: &str) -> String {
        format!("test-pool-key|{proxy_id}")
    }

    #[tokio::test]
    async fn capability_targets_include_mesh_route_dispatch_override_upstreams() {
        let proxy = warmup_test_proxy("p", BackendScheme::Https, "stable.test", 443);
        let mut upstream = upstream_with_targets("canary", &[("canary.test", 8443)]);
        upstream.backend_tls_client_cert_path = Some("/certs/canary.pem".to_string());
        upstream.backend_tls_client_key_path = Some("/certs/canary.key".to_string());
        upstream.backend_tls_server_ca_cert_path = Some("/certs/canary-ca.pem".to_string());
        upstream.backend_tls_verify_server_cert = false;

        let now = chrono::Utc::now();
        let plugin = PluginConfig {
            id: "mrd-p".to_string(),
            plugin_name: "mesh_route_dispatch".to_string(),
            namespace: "ferrum".to_string(),
            config: json!({
                "rules": [{
                    "match": {"methods": ["GET"]},
                    "destination": {"upstream_id": "canary"}
                }]
            }),
            scope: PluginScope::Proxy,
            proxy_id: Some("p".to_string()),
            enabled: true,
            priority_override: None,
            api_spec_id: None,
            created_at: now,
            updated_at: now,
        };
        let config = GatewayConfig {
            proxies: vec![proxy],
            upstreams: vec![upstream],
            plugin_configs: vec![plugin],
            ..GatewayConfig::default()
        };
        let state = make_test_proxy_state(config);
        let loaded = state.config.load_full();

        let targets = state.collect_backend_capability_targets(&loaded);
        let canary = targets
            .iter()
            .find(|target| target.host() == "canary.test" && target.port() == 8443)
            .expect("override upstream target should be probed");
        assert_eq!(
            canary.proxy.resolved_tls.client_cert_path.as_deref(),
            Some("/certs/canary.pem")
        );
        assert_eq!(
            canary.proxy.resolved_tls.client_key_path.as_deref(),
            Some("/certs/canary.key")
        );
        assert_eq!(
            canary.proxy.resolved_tls.server_ca_cert_path.as_deref(),
            Some("/certs/canary-ca.pem")
        );
        assert!(!canary.proxy.resolved_tls.verify_server_cert);
    }

